# --- what the game's own help text knows -------------------------------
# The save stores ids and counts; the rules behind them live in the locale
# file the game ships. Both are parsed here rather than written down, so a
# patch that changes a recipe changes the dashboard with it.

# "**Bacon** is a special *employee station* that requires employees with
# [Customer Service](skill-customerservice) skill." Every one of those serves a
# queue, whatever skill it asks for — a fitness planning board is as much a
# serving station as a checkout counter, and the link names the skill it wants.
# Fridges and shelves carry a Customer Capacity too and must never be summed.
_STATION_RE = re.compile(
    r"special \*employee station\* that requires employees with"
    r" \[([^\]]+)\]\(skill-([a-z0-9_]+)\)"
)
_CAPACITY_RE = re.compile(r"\*\*Customer Capacity:\*\*\s*([\d,]+)")
_ITEM_HELP_RE = re.compile(r"^help_(ba:itemname_[a-z0-9_]+)_content$")

# "* 40 X [Cheese](products-cheese)" against "* 200 [Burger](products-burger)"
_INGREDIENT_RE = re.compile(
    r"^\*\s*([\d,]+)\s*X\s*\[([^\]]+)\]\(products-([a-z0-9_]+)\)", re.M
)
_OUTPUT_RE = re.compile(r"^\*\s*([\d,]+)\s*\[([^\]]+)\]\(products-([a-z0-9_]+)\)", re.M)
_WORKSTATION_RE = re.compile(r"\[([^\]]+)\]\(furniture-([a-z0-9_]+)workstation\)")
_FURNITURE_RE = re.compile(r"\[([^\]]+)\]\(furniture-([a-z0-9_]+)\)")
_RECIPE_LINK_RE = re.compile(r"\[([^\]]+)\]\(recipes-([a-z0-9_]+)\)")

# A business type's F1 help page — the same text the in-game help menu shows —
# splits its range into "primarily sell" (or, for a one-product type, "can
# sell") and a separate "can additionally sell" for cross-sell extras. Goods
# link as [Label](products-slug), service fees as [Label](fees-slug); both use
# the same ba:itemname_ slug underneath.
_BUSINESS_HELP_RE = re.compile(r"^help_(ba:businesstype_[a-z0-9_]+)_content$")
_SELLS_HEADER_RE = re.compile(r"Businesses of this type (?:primarily sell|can sell):")
_EXTRAS_HEADER_RE = re.compile(r"can additionally sell:")
_SOLD_ITEM_RE = re.compile(r"\[([^\]]+)\]\((?:products|fees)-([a-z0-9_]+)\)")

SERVICE_SKILL = "ba:skill_customerservice"
CLEANING_SKILL = "ba:skill_cleaning"
CLEANING_SHIFT = 0  # a roaming cleaning-station duty
STATION_SHIFT = 1  # a post at one named station

# An office customer is one billed hour of one professional's time. No help page
# gives the figure: it was measured, on a law firm at build 3680, whose hour
# reports matched the lawyers posted at computers one for one (1, 2, 33 and 50
# alike) while the fee's demand reading stood at 66. Re-check after a game update.
OFFICE_POST_RATE = 1

# "Options include: * [Laptop](furniture-laptop)" on the Computer Options page:
# the computers a Computer Workstation is built around, where office shifts post.
COMPUTER_GROUP_HELP = "help_ba:itemname_computergroup_content"


def _int(text: str) -> int:
    return int(text.replace(",", ""))


def _service_stations(names: Names) -> dict:
    """Which furniture serves a customer queue, the skill it asks for, and how many an hour.

    Every *employee station* with a Customer Capacity is here, not just the
    Customer Service ones: a gym's fitness planning boards, a hairdresser's
    chairs and a theatre's booths all hold a queue of their own, and a site
    whose stations want different skills is only as fast as its slowest role.
    """
    out = {}
    for key, text in names.locale.items():
        match = _ITEM_HELP_RE.match(key)
        if not match:
            continue
        station = _STATION_RE.search(text)
        capacity = _CAPACITY_RE.search(text)
        if station and capacity:
            out[match.group(1)] = ("ba:skill_" + station.group(2), _int(capacity.group(1)))
    return out


# The fees a station's help page says its employee can charge for, from the
# "At this station, employees can do the following" list.
_STATION_FEE_RE = re.compile(r"\]\(fees-([a-z0-9_]+)\)")


def _station_roles(stations: dict, names: Names | None) -> dict:
    """The role each serving station belongs to: its skill, unless that skill's
    stations do different work.

    A hairdresser's chairs and its head wash both ask for a Hair Stylist, but
    the chair cuts, styles and colours while the head wash only shampoos. A
    head wash cannot give a haircut, so the two are separate queues, each
    planned against the site's demand, and pooling them let the head wash's 10
    an hour stand in for the chairs. Stations of one skill are split by the
    fees their help pages list; the group holding the alphabetically first
    station keeps the bare skill as its key, so every site whose skill does one
    kind of work keeps the key it always had. Hair Stylists stay one pool of
    people either way: the key splits the queue, not the hiring.
    """
    if names is None:
        return {slug: skill for slug, (skill, _rate) in stations.items()}
    work = collections.defaultdict(lambda: collections.defaultdict(list))
    for slug, (skill, _rate) in stations.items():
        text = names.locale.get(f"help_{slug}_content", "")
        fees = frozenset(_STATION_FEE_RE.findall(text.split("purchased from")[0]))
        work[skill][fees].append(slug)
    out = {}
    for skill, groups in work.items():
        for rank, slugs in enumerate(sorted(groups.values(), key=min)):
            for slug in slugs:
                out[slug] = skill if rank == 0 else f"{skill}|{min(slugs)}"
    return out


def _role_key(role: dict):
    """A role's own key: its skill, or the split key _station_roles() gave it."""
    return role.get("key", role["skill"])


def _station_role(station: dict):
    """The role key a grid station belongs to, as _role_key() reads a role's."""
    return station.get("role", station["skill"])


def _office_posts(names: Names) -> set:
    """The computers an office professional is posted to, from Computer Options."""
    _head, _, options = names.locale.get(COMPUTER_GROUP_HELP, "").partition("Options include:")
    return {"ba:itemname_" + slug for _label, slug in _FURNITURE_RE.findall(options)}


def _recipes(names: Names) -> dict:
    """Every recipe the game documents, keyed by the product it makes."""
    out = {}
    for key, text in names.locale.items():
        if not (key.startswith("help_recipes_") and key.endswith("_content")):
            continue
        head, _, tail = text.partition("**Max Production Rate Per Hour:**")
        made = _OUTPUT_RE.findall(tail)
        if not made:
            continue
        rate, label, slug = made[0]
        station = _WORKSTATION_RE.search(head)
        out["ba:itemname_" + slug] = {
            "slug": "ba:itemname_" + slug,
            "item": label,
            "out": _int(rate),
            "workstation": station.group(2) if station else None,
            "ingredients": [
                {
                    "slug": "ba:itemname_" + ing,
                    "item": name,
                    "per": _int(amount),
                }
                for amount, name, ing in _INGREDIENT_RE.findall(head)
            ],
        }
    return out


def _type_catalogue_from_help(names: Names) -> dict:
    """The primary range for each business type, straight from its own F1 help page.

    That page also lists what it "can additionally sell" — a florist's spare
    umbrellas, a gift shop's headphones — and that part is deliberately left
    out: those extras belong to whichever type sells them as its main line,
    not to every type that happens to carry a few on the side.
    """
    out = {}
    for key, text in names.locale.items():
        match = _BUSINESS_HELP_RE.match(key)
        if not match:
            continue
        header = _SELLS_HEADER_RE.search(text)
        if not header:
            continue
        block = text[header.end() :].lstrip("\n").split("\n\n", 1)[0]
        items = {"ba:itemname_" + slug for _, slug in _SOLD_ITEM_RE.findall(block)}
        if items:
            out[match.group(1)] = items
    return out


def _type_ranges(names: Names) -> tuple:
    """Each business type's whole price list as the game fills it in: what it
    primarily sells and what it can additionally sell, goods and fees alike
    ({type: {item}}); and every item any type sells as goods (a product link,
    not a fee: a fee is charged for work, never stocked)."""
    ranges, goods = {}, set()
    for key, text in names.locale.items():
        match = _BUSINESS_HELP_RE.match(key)
        if not match:
            continue
        header = _SELLS_HEADER_RE.search(text)
        if not header:
            continue
        found = set()
        block = text[header.end():].lstrip("\n").split("\n\n", 1)[0]
        extra = _EXTRAS_HEADER_RE.search(text, header.end())
        if extra:
            block += "\n" + text[extra.end():].lstrip("\n").split("\n\n", 1)[0]
        for kind, slug in re.findall(r"\]\((products|fees)-([a-z0-9_]+)\)", block):
            found.add("ba:itemname_" + slug)
            if kind == "products":
                goods.add("ba:itemname_" + slug)
        if found:
            ranges[match.group(1)] = found
    return ranges, goods


def _workstations(names: Names) -> dict:
    """Which machines make up each workstation, and what it can run."""
    out = {}
    for key, text in names.locale.items():
        match = re.match(r"^help_factory_workstation_([a-z0-9]+)_content$", key)
        if not match:
            continue
        machines, _, rest = text.partition("To an Assembly Machine")
        assembly, _, makes = rest.partition("can be used to create")
        out[match.group(1)] = {
            "slug": match.group(1),
            "name": f"{match.group(1).title()} Workstation",
            "machines": [n for n, _s in _FURNITURE_RE.findall(machines)],
            "assembly": [n for n, _s in _FURNITURE_RE.findall(assembly)],
            "makes": [n for n, _s in _RECIPE_LINK_RE.findall(makes)],
        }
    return out


def site_key(address) -> str:
    return f"{address[0]}#{address[1]}" if address else ""


RHYTHM_MIN_DAYS = 10  # below this there is not enough to separate cycle from noise
RHYTHM_MIN_WEEKS = 2  # every weekday needs at least this many observations
# Steady growth is fine — the centred mean tracks it. A jump this large between
# neighbouring baselines is a level shift (a shop opening, a hype spike), and a
# weekly cycle cannot be told apart from one.
RHYTHM_MAX_STEP = 1.6
# Two-sided t at 95% by sample size. Two observations of a weekday say very
# little, eight say a good deal, and the threshold should reflect that rather
# than treating every sample as if it were large.
T_95 = {2: 12.71, 3: 4.30, 4: 3.18, 5: 2.78, 6: 2.57, 7: 2.45, 8: 2.36, 9: 2.31}
# The company's own week, as the Daily result chart's By weekday draws it, reads
# only the last four weeks: a company that opened a new line of shops a month
# ago has a different week now, and eight weeks would mostly describe the old one.
RHYTHM_RECENT_DAYS = 28


# Consumption is measured, not declared, so two figures this close are the same
# figure. Below the first band it is rounding; below the second it is worth
# knowing but not worth an alarm.
FIT_NOISE = 0.01
FIT_TIGHT = 0.05
FIT_ORDER = ["ok", "tight", "short"]  # a verdict's severity, mildest first
FIT_FLOOR = 5  # units, so tiny lines are not judged on fractions
# A holding that empties a few hours before its delivery is an order sized to
# consumption, which is what a well set-up chain looks like.
COVER_NOISE_DAYS = 0.5
# Every site keeps its last sixty delivery transactions. Averaged over the days
# a logistics round actually ran, that log is the draw as it happened; below
# this many days it is an anecdote.
SHIPPED_WINDOW = 7
DELIVERY_LOG_SIZE = 60  # transactions a site's log keeps before the oldest go
PRICE_DAYS = 7  # days of goods cost and deliveries a unit price is read over
SHIPPED_MIN_DAYS = 3
LINE_STARVED = 0.75  # a line fed less than this share of its need is losing hours
# The week's arrivals are measured backwards; the need is counted from the
# machines standing there today. A recipe switched on yesterday has six days of
# zeroes behind it and nothing wrong with it, so an input drawn on fewer than
# this share of the window is read from its last completed round instead of
# from an average that describes a factory which no longer exists.
FEED_SETTLED = 0.7
FEED_SLACK = 0.02  # a top-up within this of the need is sized to it
# A line held by its Produce up to limit sits at the limit, or just under it
# while the machines make back what the morning round took. Never more than
# this share of the limit under it: further down, the limit is not what stops it.
LIMIT_SLACK = 0.25
PILE_DAYS = 3  # output held beyond this many days of making it is piling up
STAFF_HOURS = 168  # a machine runs only while a factory worker is posted to it
STAFF_CRITICAL = 0.5  # below this share of the week a line is barely running
WS_PREFIX = "ba:factoryworkstationtype_"
FLAT_WEEK = {wd: 1.0 for wd in range(7)}
# One margin over the whole chain, import to sale, applied once and never per
# hop: what the ends use, plus this share, is what a top-up or an import has
# to bring. 24/7 factory sizing takes the machines' rated capacity instead,
# with no margin; Demand sizing takes the ends' use plus it, capped at
# capacity. Every figure the board suggests is rounded up to SUPPLY_ROUND_TO.
SUPPLY_MARGIN = 0.15
SUPPLY_ROUND_TO = 10
# A standing supply that is missing is always said; what is held only grades
# how soon it bites: stock lasting under this many days is critical.
LASTS_WEEK = 7
LASTS_CAP = 60  # days: a holding lasting longer is said as "over 60 days"
SIZING_MODES = ("cap", "dem")  # 24/7 and Demand; the board's switch picks one
# The goods-flow panel's three-way fit, from a fact's status word.
NODE_FIT = {"short": "short", "paused": "short", "noplan": "short",
            "tight": "tight", "stalled": "tight"}


def _fit(need: float, provision: float) -> str:
    """Whether a standing order covers a cycle: 'ok', 'tight' or 'short'."""
    if not need or not provision:
        return "ok"
    gap = need - provision
    if gap <= max(need * FIT_NOISE, FIT_FLOOR):
        return "ok"
    return "tight" if gap <= need * FIT_TIGHT else "short"


def _weekday_profile(points: list, last: int | None = None, end: int | None = None) -> list | None:
    """How each weekday compares with its own week, as a percentage.

    A business that grew tenfold over the sample would otherwise make late
    weekdays look strong purely because they happened later. Each day is divided
    by a centred seven-day mean first, which cancels the trend and leaves the
    weekly cycle behind.

    ``last`` keeps only the days in that many calendar days before ``end``
    (the latest day of the series by default): 28 give every weekday at most
    four readings, and a series with gaps (profit leaves out the loss days) gets
    fewer rather than reaching back into older weeks. ``end`` itself is left
    out because it has no days after it to centre a week on. The days before
    the window still serve as neighbours for the means.
    """
    values = {day: float(value) for day, value in points}
    if len(values) < RHYTHM_MIN_DAYS:
        return None

    baselines = {}
    for day, value in values.items():
        window = [values[d] for d in range(day - 3, day + 4) if d in values]
        if len(window) >= 5:  # enough neighbours to say what a normal week looked like
            baseline = sum(window) / len(window)
            if baseline > 0:
                baselines[day] = baseline

    ordered = sorted(baselines)
    if last:
        anchor = end if end is not None else max(values)
        ordered = [day for day in ordered if anchor - last <= day < anchor]
        baselines = {day: baselines[day] for day in ordered}
    for earlier, later in zip(ordered, ordered[1:]):
        step = baselines[later] / baselines[earlier]
        if step > RHYTHM_MAX_STEP or step < 1 / RHYTHM_MAX_STEP:
            return None

    indexed = collections.defaultdict(list)
    for day, baseline in baselines.items():
        indexed[day % 7].append(values[day] / baseline)

    if len(indexed) < 7 or sum(len(v) for v in indexed.values()) < RHYTHM_MIN_DAYS:
        return None
    if min(len(v) for v in indexed.values()) < RHYTHM_MIN_WEEKS:
        return None

    # Signal against noise: the gap between the best and worst weekday has to
    # clear the uncertainty in those weekday averages, or the pattern is drift
    # dressed up as a cycle. Standard error is used rather than raw spread so
    # that a long, noisy history is not penalised for simply having more of it.
    means = {wd: sum(v) / len(v) for wd, v in indexed.items()}
    signal = max(means.values()) - min(means.values())
    errors = [
        statistics.stdev(v) / math.sqrt(len(v)) for v in indexed.values() if len(v) > 1
    ]
    noise = sum(errors) / len(errors) if errors else 0.0
    thinnest = min(len(v) for v in indexed.values())
    if signal <= T_95.get(thinnest, 2.26) * noise:
        return None
    return [
        {
            "day": WEEKDAYS[wd],
            "short": WEEKDAYS[wd][:3],
            "index": round(sum(indexed[wd]) / len(indexed[wd]) * 100),
            "n": len(indexed[wd]),
        }
        for wd in (1, 2, 3, 4, 5, 6, 0)
    ]


def _weeks(profile: list | None) -> int:
    """How many observations back the thinnest weekday of a profile."""
    return min((p["n"] for p in profile), default=0) if profile else 0


def _swing(profile: list | None) -> int:
    """How far the best weekday sits above the worst, in points."""
    if not profile:
        return 0
    return max(p["index"] for p in profile) - min(p["index"] for p in profile)


def _peak_day(profile: list | None) -> str | None:
    return max(profile, key=lambda p: p["index"])["day"] if profile else None


def money(x: float) -> float:
    return round(float(x or 0), 2)


def _configured_price(value):
    """Keep unset prices distinct from explicit zero, including in old saves."""
    return (round(value, 2) if type(value) in (int, float)
            and math.isfinite(value) and value >= 0 else None)


def _in_order(keys) -> list:
    """Keys in one order on every run: set order follows the per-process hash
    seed. Saves hold some items with no name, so None sorts last, not first."""
    return sorted(keys, key=lambda k: (k is None, str(k)))


def _frozen(table):
    """`table` as plain dicts all the way down. A defaultdict built in a loop
    and read by key after it is frozen with this, so a read of a key it does
    not hold adds nothing, and cannot change its size while a walk iterates it."""
    if isinstance(table, dict):
        return {key: _frozen(value) for key, value in table.items()}
    return table


# ------------------------------------------------------------------ premises
# Every building in the city, so the map can answer "which available premises
# are best right now?". The save only carries rent and door capacity for a
# building somebody already occupies, so both are reconstructed here: rent from
# a formula fitted to observed leases, capacity from the game's own help page.

EMPTY_TYPE = "ba:businesstype_empty"
# Buildings the player can never take: the game's fixtures and other people's
# flats. They read "unavailable" whatever else the registration says.
UNRENTABLE_BUILDINGS = ("residential", "special")

# rent_per_day = m2 x (30 + traffic) x district rate x (1.033 in an office)
#
# Fitted 15 September 2026 against 48 non-residential leases across three
# characters on build 3675, worst residual 0.6%. Residential leases do not
# follow it and are never estimated. A game patch can rebalance rents, so the
# payload carries a live check against the player's own current leases and the
# page can say how far the estimate is off today.
RENT_TRAFFIC_OFFSET = 30
RENT_RATES = {
    "Midtown": 0.02482,
    "Hell's Kitchen": 0.01468,
    "Murray Hill": 0.01020,
    "Garment District": 0.00734,
    "Lower Manhattan": 0.00621,
    "The Hamptons": 0.00568,
    "Industry City": 0.00566,
}
RENT_OFFICE_FACTOR = 1.033

# Taking a lease costs a deposit upfront, which is what actually stops an early
# character signing. The game bills it as a transaction and never stores it
# against the building, so it too is a multiple of the daily rent, fitted on
# 15 September 2026 across 21 lease deposits from three characters (build 3675).
# A deposit transaction can also be a building purchase (about 1000x the rent
# and more) or one of the small deposits the game takes for something that is
# not a lease, so only the band between these two factors is read as a lease.
DEPOSIT_FACTORS = {"lease": 62.84, "warehouse": 93.61}
DEPOSIT_ROUNDING = 10
DEPOSIT_MIN_FACTOR = 30
DEPOSIT_MAX_FACTOR = 300
DEPOSIT_TRANSACTION = "ba:transaction_deposit"

# The door capacity each size letter buys, per building type. Read from the
# game's help page, which travels with the bundled game text (a player's own
# en.json wins over it); this is the same table as builds 3675 and 3680 ship, and
# it stands for any category the page does not yield. A local run without the game
# reads the page from the bundle, so this is reached only when there is no game
# text at all. A letter whose variants disagree carries [min, max]; in a
# LAYOUT_CAP_CATEGORIES category each layout code (S1) carries its own number
# beside it.
CAP_CATEGORIES = ("retail", "office", "cinema", "theater")
FALLBACK_CAPS = {
    "retail": {"A": 15, "C": 30, "D": 40, "M": 75},
    "office": {"A": 4, "C": 8, "D": 10, "J": 10, "K": 50},
    "cinema": {"S": [100, 150], "S1": 150, "S2": 125, "S3": 100},
    "theater": {"R": [150, 200]},
}
# Where the help page's per-layout number is the building's own, confirmed by
# the saves: every player cinema reads customerCapacity exactly its layout's
# (4 Broadway S1 150, 5 Sixth Street S2 125, 15 Third Avenue S3 100), and no
# rival's reads above it. A building row's version (`v`) names its layout.
LAYOUT_CAP_CATEGORIES = ("cinema",)
_CAP_SECTION_RE = re.compile(r"^\*\*([A-Za-z][A-Za-z /]*)\*\*$")
_CAP_SIZE_RE = re.compile(
    r"^\*\s*\*\*([A-Z]+)(\d+)\*\*:.*?/\s*([\d,]+)\s*customer capacity", re.I
)
# Types whose own building class is neither a shop floor nor an office.
VENUE_TYPES = {
    "ba:businesstype_cinema": "cinema",
    "ba:businesstype_theater": "theater",
}


def _cap_rows(names: Names):
    """(category, size letter, layout code, customer capacity) for each size row
    of help_building_types_content, in a CAP_CATEGORIES section: the one parse
    _door_caps() and _venue_caps() both read."""
    section = None
    for line in (names.locale.get("help_building_types_content") or "").split("\n"):
        line = line.strip()
        head = _CAP_SECTION_RE.match(line)
        if head:
            section = head.group(1).strip().lower()
            continue
        size = _CAP_SIZE_RE.match(line)
        if size and section in CAP_CATEGORIES:
            letter = size.group(1).upper()
            yield section, letter, letter + size.group(2), int(size.group(3).replace(",", ""))


def _door_caps(names: Names) -> dict:
    """{building type: {size letter: capacity}} from help_building_types_content.

    The page lists a code per layout — C1 and C2 are both 225 m2 retail floors —
    so the codes collapse to their letter, which is what ba_buildings.json
    records as `z`. A theatre's three layouts seat different crowds, so a
    letter whose variants disagree keeps [min, max] rather than pretending to
    a single number. A cinema's do too, and there the saves confirm the page's
    number per layout, so each code is also kept as its own key (S1: 150),
    which _size_cap() reads off the row's `z` and `v`.
    """
    found: dict[str, dict[str, list]] = {}
    codes: dict[str, dict[str, int]] = {}
    for section, letter, code, cap in _cap_rows(names):
        found.setdefault(section, {}).setdefault(letter, []).append(cap)
        if section in LAYOUT_CAP_CATEGORIES:
            codes.setdefault(section, {})[code] = cap
    caps = {kind: dict(letters) for kind, letters in FALLBACK_CAPS.items()}
    for kind, letters in found.items():
        caps[kind] = {
            letter: (min(seen) if min(seen) == max(seen) else [min(seen), max(seen)])
            for letter, seen in sorted(letters.items())
        }
        caps[kind].update(sorted(codes.get(kind, {}).items()))
    return caps


def _size_cap(row: dict, caps: dict):
    """The customer capacity a building row's size buys, out of _door_caps().

    A number: the layout's own (S1 150) where the table keys the layout, else
    the size letter's. [min, max] for a theatre, whose layouts seat different
    crowds; None for a type or size the table does not know.
    """
    kind = caps.get(row.get("t"), {})
    if row.get("z") and row.get("v") is not None:
        exact = kind.get(f"{row['z']}{row['v']}")
        if exact is not None:
            return exact
    return kind.get(row.get("z"))


def _rent_estimate(row: dict) -> int | None:
    """Estimated rent per day for one building, from the static table's row."""
    # The rates were fitted and written down by neighbourhood name.
    rate = RENT_RATES.get(HOOD_LABEL.get(hood_key(row)))
    # The casino boat is the one row with no floor area: the table does not
    # know how big it is, so there is nothing to price.
    if rate is None or not row.get("m") or row.get("t") == "residential":
        return None
    rent = row["m"] * (RENT_TRAFFIC_OFFSET + row["x"]) * rate
    if row.get("t") == "office":
        rent *= RENT_OFFICE_FACTOR
    return int(round(rent))


def _deposit_estimate(row: dict, rent: int | None) -> int | None:
    """The upfront deposit a lease asks for, to the nearest ten dollars."""
    if not rent:
        return None
    factor = DEPOSIT_FACTORS["warehouse" if row.get("t") == "warehouse" else "lease"]
    return int(round(rent * factor / DEPOSIT_ROUNDING)) * DEPOSIT_ROUNDING


def _deposit_check(save: Save, table: dict) -> dict:
    """The estimate against every lease deposit this character has actually paid.

    A deposit transaction can also be a building purchase, or one of the small
    deposits the game takes for something other than a lease, so only the band
    the leases sit in counts.
    """
    worst, paid_count = 0.0, 0
    for tx in save.items(save.root.get("Transactions")):
        if tx.get("transactionType") != DEPOSIT_TRANSACTION:
            continue
        addr = save.address(tx.get("address"))
        row = table.get(addr) if addr else None
        if not row:
            continue
        rent = _rent_estimate(row)
        estimate = _deposit_estimate(row, rent)
        paid = abs(tx.get("amount") or 0)
        if not estimate or not paid:
            continue
        if not DEPOSIT_MIN_FACTOR <= paid / rent <= DEPOSIT_MAX_FACTOR:
            continue
        paid_count += 1
        worst = max(worst, abs(estimate - paid) / paid)
    return {"deposits": paid_count, "worst": round(worst, 4)}


def _rival_numbers(save: Save) -> dict:
    """Each rival company's id as a stable 1-based number.

    The save never writes a rival's name against a building. The names appear
    only in event text, and addresses change hands, so there is no id-to-name
    map to be had and the board does not invent one: it numbers the companies
    in the order ``rivalStates`` lists them, which holds for a character, so
    "rival 3" is the same company on every card and after every reload.
    """
    return {
        state["rivalId"]: number
        for number, state in enumerate(save.items(save.root.get("rivalStates")), 1)
        if state.get("rivalId")
    }


# The four story rivals carry the same ids in every save. Their names are in
# the message keys the game has sent, but a rival who has not written yet has
# no key, so the pairs are kept here too.
SPECIAL_RIVAL_NAMES = {
    "yXNH9hTIv0KhI5OI8be0A==": "Huang Guo",
    "jTnQhoNwhkuGDTnL6K0Sxw==": "Ingrid Schneider",
    "HJFtA8Jq+kOZ6KHWfS8PQ==": "Jessica Johnson",
    "ju1yVbREcE2B5ymg6q5tyA==": "Thierry Laurent Moreau",
}
# rivals_thierry_laurent_moreau_entrance -> thierry laurent moreau
_RIVAL_MESSAGE_RE = re.compile(r"^rivals_(.+)_[a-z0-9]+$")
OPENING_EVENT = 0  # "{rival} opened {business} at {address}"


def _rival_names(save: Save, numbers: dict) -> dict:
    """{rival number: name} for every rival company the save lets us name.

    Two sources. The four story rivals are named by their fixed ids, and a
    story rival the table lacks by the message keys it has sent: a rival's list
    can hold another rival's keys, so the first match is only a fallback.
    Everybody else is named by their own opening announcement: a market
    event of type 0 carries the rival's name, the business's name and its
    address, and the registration still standing at that address, opened on the
    same day and under the same name, carries the owner's id. A name is kept
    only where every announcement for that id agrees, so a business that has
    since closed and been replaced cannot rename its owner.
    """
    found = {}
    for state in save.items(save.root.get("specialRivalStates")):
        rival = state.get("rivalId")
        if not rival:
            continue
        if rival in SPECIAL_RIVAL_NAMES:
            found[rival] = SPECIAL_RIVAL_NAMES[rival]
            continue
        for key in save.items(state.get("sentMessageKeys")):
            match = _RIVAL_MESSAGE_RE.match(key or "")
            if match:
                found[rival] = match.group(1).replace("_", " ").title()
                break
        else:
            found[rival] = SPECIAL_RIVAL_NAMES.get(rival)

    registrations = {
        _address_of(reg): reg
        for reg in save.items(save.root.get("BuildingRegistrations"))
    }
    claimed = collections.defaultdict(set)
    for event in save.items(save.root.get("marketEvents")):
        if event.get("type") != OPENING_EVENT or not event.get("rivalName"):
            continue
        reg = registrations.get(save.address(event.get("address")))
        if not reg or not reg.get("businessOwnerRivalId"):
            continue
        if reg.get("creationDay") != event.get("startDay"):
            continue
        if reg.get("BusinessName") != event.get("businessName"):
            continue
        claimed[reg["businessOwnerRivalId"]].add(event["rivalName"])
    for rival, names_seen in claimed.items():
        if len(names_seen) == 1:
            found.setdefault(rival, next(iter(names_seen)))

    return {
        numbers[rival]: name
        for rival, name in found.items()
        if name and rival in numbers
    }


def _premises_status(reg: dict, row: dict) -> str:
    """Whether the player could take this building today."""
    if reg.get("RentedByPlayer"):
        return "mine"
    kind = reg.get("businessTypeName")
    # A bank, a wholesaler, the hospital or the IRS belongs to the city itself:
    # the registration names a business but no rival owns it, so there is
    # nobody to buy out. Only a business with an owner is a takeover target.
    # Somebody else's flat is nobody's business either way.
    if kind and kind != EMPTY_TYPE and row.get("t") != "residential":
        return "rival" if reg.get("businessOwnerRivalId") else "service"
    if row.get("t") in UNRENTABLE_BUILDINGS:
        return "unavailable"
    # Vacancy is exact: every empty retail, office, cinema and theater building
    # says so itself. Nothing else is ever read as vacant.
    return "vacant" if reg.get("AvailableForRent") else "unavailable"


def _premises_demand(market: dict) -> dict:
    """The Market grid's by-type rows, turned inside out into one list per hood.

    The page ranks a building on its neighbourhood's demand for a type, so it
    wants the grid by neighbourhood; the grid itself is by type. Same numbers,
    no second reading.
    """
    hoods = market.get("hoods") or []
    out: dict[str, list] = {hood: [] for hood in hoods}
    for band in (market.get("types") or [], market.get("offices") or []):
        for row in band:
            slug = row["slug"]
            category = (
                "office" if slug in OFFICE_TYPES else VENUE_TYPES.get(slug, "retail")
            )
            for hood, cell in zip(hoods, row["cells"]):
                if not cell:
                    continue
                out[hood].append(
                    {
                        "slug": slug,
                        "type": row["type"],
                        "demand": cell["demand"],
                        "providers": cell["providers"],
                        # Whether one of those providers is the player's own.
                        "mine": bool(cell.get("here")),
                        "category": category,
                    }
                )
    return {hood: rows for hood, rows in out.items() if rows}


# The kinds whose buildings the finder shows a floor plan for. A layout is the
# building's size code plus its version ("C2"), which is how the game picks the
# interior (BuildingSizeInfo(size, version)); the type is not part of it, so an
# office C2 is the same shell as a shop C2. make_floor_plans.py draws one plan
# for each layout these kinds use.
FLOOR_PLAN_KINDS = ("retail", "office", "warehouse")


def _layout(row: dict) -> str | None:
    """A building's layout code, or None when it has no plan or no version."""
    if row.get("t") not in FLOOR_PLAN_KINDS or row.get("v") is None:
        return None
    return f"{row['z']}{row['v']}"


def _premises(save: Save, names: Names, market: dict) -> dict:
    """Every building in the city, with what it would cost and what it holds.

    One row per registration the static table places. A couple of addresses in
    some saves are registered but missing from the table; they are dropped
    rather than guessed at.
    """
    table = load_buildings()
    caps = _door_caps(names)
    rivals = _rival_numbers(save)
    bought = {
        addr
        for addr in (save.address(e.get("address")) for e in save.items(save.root.get("realEstate")))
        if addr
    }
    buildings, deviations = [], []
    for reg in save.items(save.root.get("BuildingRegistrations")):
        addr = _address_of(reg)
        row = table.get(addr)
        if not row:
            continue
        rent = _rent_estimate(row)
        status = _premises_status(reg, row)
        kind = reg.get("businessTypeName")
        occupant = None
        # Somebody else's flat is still "unavailable", but the card says who is
        # in there, so every occupied building names its occupant.
        if kind and kind != EMPTY_TYPE:
            occupant = {
                "name": reg.get("BusinessName") or "",
                "type": names.label(kind, ""),
                "typeSlug": kind,
            }
        # Who the rent goes to: you once you have bought the building, a rival
        # landlord, or the city, which owns everything nobody else does.
        landlord = reg.get("buildingOwnerRivalId")
        owner = "you" if addr in bought else ("rival" if landlord else "city")
        buildings.append(
            {
                "key": site_key(addr),
                "address": f"{addr[1]} {names.street(addr[0])}",
                "hood": hood_key(row),
                "type": row["t"],
                "size": row["z"],
                "layout": _layout(row),
                "m2": row["m"],
                "traffic": row["x"],
                "cap": _size_cap(row, caps),
                "rent": rent,
                "deposit": _deposit_estimate(row, rent),
                "status": status,
                "occupant": occupant,
                "owner": owner,
                "ownerRival": rivals.get(landlord) if owner == "rival" else None,
                "occupantRival": rivals.get(reg.get("businessOwnerRivalId")),
            }
        )
        # How far the formula is from what the player is actually billed today.
        paid = reg.get("RentPerDay") or 0
        if reg.get("RentedByPlayer") and rent and paid > 0:
            deviations.append(abs(rent - paid) / paid)
    buildings.sort(key=lambda b: b["key"])

    for_sale = []
    for entry in save.items(save.root.get("buildingsForSale")):
        addr = save.address(entry.get("address"))
        row = table.get(addr) if addr else None
        if not row:
            continue
        for_sale.append(
            {
                "key": site_key(addr),
                "address": f"{addr[1]} {names.street(addr[0])}",
                "hood": hood_key(row),
                "type": row["t"],
                "size": row["z"],
                "layout": _layout(row),
                "m2": row["m"],
                "price": int(round(entry.get("buildingPrice") or 0)),
            }
        )
    for_sale.sort(key=lambda b: b["key"])

    return {
        "buildings": buildings,
        # How many companies the numbering runs over, so the page can say which
        # of how many a card means, and the ones it can put a name to.
        "rivals": len(rivals),
        "rivalNames": _rival_names(save, rivals),
        "forSale": for_sale,
        "demand": _premises_demand(market),
        "rent": {
            "constant": RENT_TRAFFIC_OFFSET,
            # By the neighbourhood's key, as everything the page reads is.
            "rates": {key: RENT_RATES[label] for key, label in HOOD_LABEL.items() if label in RENT_RATES},
            "officeFactor": RENT_OFFICE_FACTOR,
            "check": {
                "leases": len(deviations),
                "worst": round(max(deviations), 4) if deviations else 0,
            },
            "deposit": {
                "factors": dict(DEPOSIT_FACTORS),
                "check": _deposit_check(save, table),
            },
        },
        "caps": caps,
    }


# ---------------------------------------------------------------- extraction
def extract(save: Save, names: Names, history_path: str | None = None) -> dict:
    root = save.root
    day = root["Day"]

    buildings = [
        b for b in save.items(root["BuildingRegistrations"]) if b.get("RentedByPlayer")
    ]
    summaries = sorted(
        save.items(root["financialSummaries"]), key=lambda s: s["dayNumber"]
    )

    stations = _service_stations(names)
    recipes = _recipes(names)
    staff_by_addr, staff = _staff(save, names)
    # Every skill a person holds, the top one first: a station is held by
    # anyone with its skill, not only by those whose best skill it is.
    crew_skill = {p["id"]: [p["skill"], *(s for s in p.get("skills", ()) if s != p["skill"])]
                  for p in staff}
    residential = _residential_addresses(save, summaries, buildings)
    stmt_history = _statement_history(save, summaries)
    latest = stmt_history[-1][1] if stmt_history else {}

    agencies = _marketing_agencies(save, names)
    businesses = []
    for b in buildings:
        addr = _address_of(b, strict=True)
        if addr in residential:
            continue
        row = _business(save, names, b, addr, latest, stmt_history, staff_by_addr, day, agencies)
        # The game's own switch that shuts a site's doors, which the
        # not-trading finding names as a reason of its own.
        row["closed"] = bool(b.get("temporarilyClosed"))
        businesses.append(row)
    businesses.sort(key=lambda x: -x["profit"])
    _job_demands(save, names, businesses)

    daily = _daily_series(save, summaries)
    loans = _loans(save, names)
    products = _products(businesses)
    history = History(history_path)
    character = root.get("characterId") or "default"
    rhythm = _chain_rhythm(save, buildings, daily, day)
    supply = _supply(save, names, businesses, day, rhythm, recipes, history, character)
    _order_says(businesses, supply)
    product_rhythm = _product_rhythm(save, buildings)
    for entry in products:
        beat = product_rhythm.get(entry["slug"])
        entry["peak"] = beat["peak"] if beat else None
        entry["swing"] = beat["swing"] if beat else 0
        # How many weeks of sales the peak is read from, which the Products
        # table names beside it.
        entry["weeks"] = beat["weeks"] if beat else 0
    market = _market(save, names, businesses, day, history, character)

    profits = [d["profit"] for d in daily]
    last7 = profits[-7:] or [0]
    prev7 = profits[-14:-7] or last7
    profit_avg7 = sum(last7) / len(last7)

    active = [b for b in businesses if b["status"] != "vacant"]
    rent_total = sum(b["rent"] for b in businesses)
    wage_total = sum(b["wages"] for b in businesses)

    # A rolling seven-day profit line, so the purchase calendar's sawtooth does
    # not read as trading moving up and down.
    for i, row in enumerate(daily):
        window = [d["profit"] for d in daily[max(0, i - 6) : i + 1]]
        row["profit7"] = money(sum(window) / len(window))

    trends = _site_trends(businesses, day)
    chains = _chains(save, businesses, trends)
    # Before history.write(): it remembers bills and break-even days.
    payback = _payback(save, names, buildings, businesses, chains, stmt_history, history, character)
    hype = _hype_exposure(businesses, market)

    # Every trading site, measured or not. The page's hour grid takes only the
    # sites with reports behind them, as it always has -- an empty grid says
    # nothing -- while the roster builder plans an unmeasured site too, because
    # its cleaning and security cover and its hiring lines do not wait on a
    # measurement.
    all_grids = _hourly(
        save, buildings, businesses, stations, _office_posts(names), crew_skill, names
    )
    grids = [grid for grid in all_grids if grid["reported"]]
    service_wage = _service_wages(staff, {b["key"]: b["status"] for b in businesses})
    hour_findings = _hour_findings(grids, businesses, service_wage)
    plan = _plan(
        save,
        names,
        businesses,
        market.pop("catalogue"),
        recipes,
        stations,
        _ingredient_prices(save, names, supply, businesses),
        rhythm,
    )
    premises = _premises(save, names, market)
    # Expansion › Open a store: the facts a plan for a new store is worked
    # out from (_open_store(), docs/open-a-store-scope.md).
    open_store = _open_store(save, names, buildings, businesses, premises, all_grids,
                             stmt_history, daily, staff)
    # Expansion › Plan a factory: what a factory plan is priced from (_open_factory()).
    open_factory = _open_factory(save, names, buildings, businesses, recipes, staff)
    net_worth = _net_worth(root, history, character, day)
    entry = {
        "hour": root["Hour"],
        "cash": money(root["Money"]),
        "profit": profits[-1] if profits else 0,
    }
    if root.get("NetWorth") is not None:
        entry["netWorth"] = money(root["NetWorth"])
    ledger = history.ledger(character, day, entry)
    history.write()
    gate = max(profit_avg7 * MATERIAL_SHARE, MATERIAL_FLOOR)
    # Every site's week over one pool of people: shops, then offices by Peter's
    # office default, then factory lines in each sizing (which takes the
    # lines' _posts); then the Staff page's key, which takes every plan's
    # private `_hire` part off its row.
    with _collector_paused():
        staffing, office_staffing, factory_staffing = _staff_plans(
            save, names, businesses, all_grids, supply.get("factories", {}), staff,
            (save.deref(root.get("gameVariables")) or {}).get(
                "baseCustomerPromotionMultiplier", 0.55
            ),
        )
        hiring = _hiring(save, businesses, staffing, factory_staffing, office_staffing)
    alerts = _alerts(
        businesses, supply, chains, trends, hype, hour_findings, grids, day, gate, agencies=agencies
    )
    # The same findings with factory lines sized on demand, for the board's
    # Demand switch: a second pass over the facts already built, not a second
    # supply model.
    alerts_demand = _alerts(
        businesses, supply, chains, trends, hype, hour_findings, grids, day, gate, "dem", agencies=agencies
    )

    # Every sentence written with msg() carries its key and params to the page
    # in the row's "i18n" field, in one pass at the end.
    return _wire_msgs({
        "meta": {
            "character": character,
            "save": root.get("SaveGameName") or "Save",
            "day": day,
            "hour": root["Hour"],
            "minute": int(root["Minute"]),
            "cityDate": _city_date(save, day),
            "build": root.get("buildNumberAtLastSave"),
            "verifiedBuild": VERIFIED_BUILD,
            # Names alone can be shipped with the page; recipes and station
            # capacities only come from the game's own help pages.
            "locale": any(k.startswith("help_") for k in names.locale),
            "difficulty": _difficulty(save)["label"],
            "houseRules": _difficulty(save),
            "generated": dt.datetime.now().strftime("%d %b %Y, %H:%M"),
            "source": os.path.basename(save.path),
            "saved": dt.datetime.fromtimestamp(os.path.getmtime(save.path)).strftime(
                "%d %b %Y, %H:%M"
            ),
        },
        "kpi": {
            "cash": money(root["Money"]),
            "netWorth": net_worth["value"],
            "netWorthAsOf": net_worth["asOf"],
            "debt": sum(l["remaining"] for l in loans),
            "profitYesterday": profits[-1] if profits else 0,
            "profitAvg7": profit_avg7,
            "profitPrev7": sum(prev7) / len(prev7),
            "profitSum7": sum(last7),
            "materiality": round(gate, 2),
            "revenue": daily[-1]["revenue"] if daily else 0,
            "businesses": len(active),
            "vacant": len(businesses) - len(active),
            "employees": len(staff),
            "wageBill": wage_total,
            "rentBill": rent_total,
            "customers": sum(b["customers"] for b in businesses),
        },
        "daily": daily,
        "businesses": businesses,
        "ownedBuildings": _owned_buildings(save, names),
        "homes": _homes(buildings, residential, names),
        "products": products,
        "staff": _staff_summary(staff, businesses),
        "loans": loans,
        "supply": supply,
        "rhythm": rhythm,
        "market": market,
        "premises": premises,
        "chains": chains,
        # Investment, profit so far and break-even, per site and per chain
        # (_payback(), docs/open-a-store-scope.md).
        "payback": payback,
        # Expansion › Open a store: outfits, market, own shops, loans
        # (_open_store()).
        "openStore": open_store,
        # Expansion › Plan a factory: prices, kits, storage, vehicles and what
        # the company's warehouses and factories hold (_open_factory()).
        "openFactory": open_factory,
        "trends": trends,
        "hypeExposure": hype,
        "hours": grids,
        "hourFindings": hour_findings,
        "staffing": staffing,
        "factoryStaffing": factory_staffing,
        "officeStaffing": office_staffing,
        # The Staff page: the headhunters' candidates, best first, and what
        # every site still needs by role. See _candidates() and _hiring().
        "candidates": _candidates(save),
        "hiring": hiring,
        "plan": plan,
        # Every game name the text knows -- items, business types,
        # neighbourhoods, stations, skills, job demands -- by the game's own
        # key, so the page names anything the payload identifies by key, and a
        # material no recipe or shop line mentions is still named.
        "names": _game_names(names),
        # The game's name for every skill a station can ask for, so the write
        # dialogs never spell a role from its slug ("Securityguard").
        "skillNames": {skill: names.label(skill) for skill in sorted({s for v in STATION_SKILLS.values() for s in v})},
        # The city's marketing agencies: which are phone contacts, what each
        # sells and when each is open, for the marketing write.
        "marketingAgencies": agencies,
        "cashFlow": _cash_flow(ledger, daily, day),
        "ledgerDays": len(ledger),
        "alerts": alerts["lines"],
        "minor": alerts["minor"],
        "alertsDemand": {"lines": alerts_demand["lines"], "minor": alerts_demand["minor"]},
        "goals": _goals(save, names, businesses),
    })


def _net_worth(root: dict, history, character: str, day: int) -> dict:
    """Net worth, or the last one the game told us.

    Build 3672 dropped ``NetWorth`` from the save (``midnightBankBalances``
    appeared in its place). There is no honest way to recompute the game's own
    figure from what is left, so the last recorded one is carried forward and
    labelled with the day it came from rather than passed off as today's. A
    day after this save's own is from a later save, so it is never the one.
    """
    live = root.get("NetWorth")
    if live is not None:
        return {"value": money(live), "asOf": None}
    for entry in reversed(history.ledger_entries(character)):
        if entry["day"] <= day and entry.get("netWorth"):
            return {"value": money(entry["netWorth"]), "asOf": entry["day"]}
    return {"value": None, "asOf": None}


def _city_date(save: Save, day: int) -> str:
    """In-game day number rendered as a year/day-of-year, using the save's calendar."""
    per_year = save.deref(save.root.get("gameVariables")).get("daysPerYear") or 60
    year = (day - 1) // per_year + 1
    return f"Year {year}, day {(day - 1) % per_year + 1} of {per_year}"


# The custom-game sliders: the unit each is shown in, its value on the game's
# Normal preset, and the direction that makes the game harder. Names are the
# main_menu_custom_* titles in the locale, shortened; "Tax rate" is the board's
# own, and the effects paraphrase the game's tooltips. Normal's values come from the game's
# DifficultySetting assets at VERIFIED_BUILD, and Normal is not ×1 across the
# board: its urgent wholesale fee is ×0.2 and its tax rate 5%.
HOUSE_RULES = [
    ("marketPriceMultiplier", "Public prices", "×", 0.7, "up",
     "cost of wholesale and imported goods, hospital fees and the like"),
    ("employeeHourlySalaryMultiplier", "Employee hourly salary", "×", 0.7, "up",
     "what staff cost an hour"),
    ("bankInterestMultiplier", "Bank interest", "×", 0.7, "up",
     "interest on loans and investments"),
    ("rivalsDifficultyMultiplier", "Rival attacks", "×", 1.0, "up",
     "severity of rival attacks; 0 switches them off entirely"),
    ("baseCustomerPromotionMultiplier", "Base customer promotion", "×", 0.55, "down",
     "base level of customers without traffic or marketing"),
    ("exportMultiplier", "Export price", "×", 0.65, "down",
     "what exporters pay for factory-made goods"),
    ("sellingMultiplier", "Resale value", "×", 0.75, "down",
     "share of an item's or vehicle's value received when selling it"),
    ("wholesaleUrgentFeeMultiplier", "Wholesale urgent fee", "×", 0.2, "up",
     "surcharge for rushing a wholesale order"),
    ("importerUrgentFeeMultiplier", "Importer urgent fee", "×", 0.75, "up",
     "surcharge for rushing an import"),
    ("taxPercentage", "Tax rate", "%", 5, "up", "annual rate from the IRS"),
]

# The game's Difficulty enum, which is what the save's ``difficulty`` holds.
DIFFICULTY_SLOTS = {0: "Custom", 1: "Easy", 2: "Normal", 3: "Hard"}


def _difficulty(save: Save) -> dict:
    """The difficulty the game is played on, and how its settings compare with Normal.

    The stored ``difficulty`` slot is trustworthy: in game, a preset game can
    only switch to another preset, and the sliders can only be moved on a custom
    game (slot 0). The settings are still read off the save, because a preset's
    values can change between builds and an older game keeps the ones it got.
    A slot the enum does not know, such as a preset added by a later build, is
    "Unknown" rather than a guess.
    """
    gv = save.deref(save.root.get("gameVariables")) or {}
    rules = []
    for key, name, unit, normal, harder, what in HOUSE_RULES:
        value = gv.get(key)
        if value is None:
            continue
        value = round(value, 3)
        # An unset multiplier reads as 0 in older saves; that is absence, not a
        # setting. Rival attacks at 0 are switched off, and a 0% tax rate is real.
        if not value and key not in ("rivalsDifficultyMultiplier", "taxPercentage"):
            continue
        if value == normal:
            lean = "level"
        else:
            up = value > normal
            lean = "harder" if (up == (harder == "up")) else "easier"
        rules.append({"name": name, "value": value, "normal": normal, "unit": unit,
                      "lean": lean, "what": what})

    slot = gv.get("difficulty")
    return {
        "label": DIFFICULTY_SLOTS.get(slot, "Unknown"),
        "slot": slot,
        "harder": sum(1 for r in rules if r["lean"] == "harder"),
        "easier": sum(1 for r in rules if r["lean"] == "easier"),
        "startingMoney": gv.get("startingMoney"),
        "rules": rules,
    }


def _residential_addresses(save: Save, summaries: list, buildings: list = ()) -> set:
    """Apartments are billed as residences, not businesses.

    A home rented today, or a new character's first one, has no statement
    yet, so a rented building the building table calls residential is a home
    too: nobody can run a business in one.
    """
    table = load_buildings() if buildings else {}
    out = {
        _address_of(b, strict=True) for b in buildings
        if (table.get(_address_of(b, strict=True)) or {}).get("t") == "residential"
    }
    for s in summaries[-5:]:
        for r in save.items(s.get("residentialStatements")):
            addr = save.address(r.get("Address"))
            if addr:
                out.add(addr)
    return out


def _statement_history(save: Save, summaries: list) -> list:
    history = []
    for s in summaries:
        by_addr = {}
        for st in save.items(s["businessIncomeStatements"]):
            addr = save.address(st.get("Address"))
            if addr:
                by_addr[addr] = st
        history.append((s["dayNumber"], by_addr))
    return history


def _character(save: Save, instance: dict) -> dict:
    """Who an employee or a candidate is: name, age in days and skills.

    Current saves keep these on the instance's `characterData`; older ones keep
    `name`, `ageInDays` and `skills` on the instance itself. One reader for both,
    so a name never reads "?" only because the save is older. `skills` is in the
    save's order, each `{"skill", "level"}`, and a skill the save has without a
    value counts at 0.
    """
    char = save.deref(instance.get("characterData"))
    source = char if isinstance(char, dict) else instance
    return {
        "name": source.get("name"),
        "ageDays": source.get("ageInDays"),
        "skills": [
            {"skill": s.get("name"), "level": s.get("value") or 0}
            for s in save.items(source.get("skills"))
            if isinstance(s, dict)
        ],
    }


def _staff(save: Save, names: Names):
    by_addr = collections.defaultdict(list)
    staff = []
    for e in save.items(save.root["EmployeeInstances"]):
        char = _character(save, e)
        skills = [{"name": s["skill"], "value": s["level"]} for s in char["skills"]]
        top = max(skills, key=lambda s: s["value"], default=None)
        rec = {
            "id": e.get("id"),
            "name": char["name"] if char["name"] is not None else "?",
            "role": names.label(top["name"]) if top else "-",
            "skill": top["name"] if top else None,
            # Every skill, not just the top one: a character carries one or two,
            # and a uniform is owed for whichever of them works the station.
            "skills": [s["name"] for s in skills],
            "level": round(top["value"], 0) if top else 0,
            "wage": money(e.get("hourlyWage", 0)),
            "hours": e.get("assignedWeeklyHours", 0),
            "satisfaction": round(e.get("satisfaction", 0)),
            "hired": e.get("dayHired", 0),
            "addr": save.address(e.get("assignedAddress")),
            "absent": bool(e.get("isAbsent")),
            "complaining": bool(
                (save.deref(e.get("complaintData")) or {}).get("isComplaining")
            ),
        }
        rec["daily"] = rec["wage"] * rec["hours"] / 7
        staff.append(rec)
        by_addr[rec["addr"]].append(rec)
    return by_addr, staff


def _skill_rows(char: dict) -> list:
    """A character's skills, highest first, levels rounded as _staff() rounds them.

    Ties keep the save's order, which is a list and so a promise.
    """
    ordered = sorted(enumerate(char["skills"]), key=lambda e: (-e[1]["level"], e[0]))
    return [{"skill": s["skill"], "level": int(round(s["level"]))} for _i, s in ordered]


def _candidate_source(save: Save, info: dict) -> str:
    """Where a candidate came from: a headhunter, the job board, an agency."""
    if info.get("sourceHeadhunterId"):
        return "headhunter"
    if info.get("fromJobBoard"):
        return "jobboard"
    if save.address(info.get("sourceAddress")):
        return "agency"
    return "other"


def _candidates(save: Save) -> list:
    """The people the game offers to hire, one row each, best first.

    From GameInstance.CandidateEmployeeInstances; an older save marks a finished
    offer `hired` or `declined` rather than dropping it, and those are left out.
    Ordered by top skill level (highest first), then wage (cheapest first),
    then id, so the list is the same on every run. `hoursLeft` is the game's
    countdown as of the save; a candidate leaves the list at 0. `age` is in the
    game's years (ageInDays over gameVariables.daysPerYear, as the game counts
    retirement), None when the save has no year length.
    """
    root = save.root
    per_year = (save.deref(root.get("gameVariables")) or {}).get("daysPerYear")
    rows = []
    for c in save.items(root.get("CandidateEmployeeInstances")):
        if not isinstance(c, dict) or c.get("hired") or c.get("declined"):
            continue
        char = _character(save, c)
        skills = _skill_rows(char)
        info = save.deref(c.get("candidateInfo")) or {}
        age = char["ageDays"]
        rows.append({
            "id": c.get("id"),
            "name": char["name"],
            "age": int(age // per_year) if age is not None and per_year else None,
            "skill": skills[0]["skill"] if skills else None,
            "level": skills[0]["level"] if skills else 0,
            "skills": skills,
            "wage": money(c.get("hourlyWage") or 0),
            "demands": _in_order(
                {d for d in save.items(c.get("demands")) if isinstance(d, str)}),
            "hoursLeft": info.get("hoursUntilExpiring"),
            "source": _candidate_source(save, info),
        })
    rows.sort(key=lambda r: (-r["level"], r["wage"], str(r["id"])))
    return rows


def _cleanliness(save: Save, building: dict) -> float:
    """A building's cleanliness as the game scores it, from its saved dirt spots.

    BuildingCleanliness.GetCleanliness: 100 with no spots, or with no spot dirty
    enough to see (5 or more); otherwise 100 less the mean of the visible dirt and
    the mean of all dirt, whole points, never below 0.
    """
    dirt = [spot.get("dirtiness") or 0 for spot in save.items(building.get("dirtSpots"))]
    visible = sum(x for x in dirt if x >= 5)
    if not dirt or not visible:
        return 100.0
    return float(max(0, int(100 - sum(dirt) / len(dirt) - visible / len(dirt))))


def _item_instances(save: Save, instances):
    """The items an itemInstances collection holds, each one dereferenced. An
    empty or unreadable slot is skipped."""
    for holder in save.items(instances):
        item = save.deref(holder.get("$v")) if isinstance(holder, dict) else None
        if item:
            yield item


def _items_by_name(save: Save, registration: dict) -> dict:
    """A building's items, as lists by item name."""
    held = collections.defaultdict(list)
    for item in _item_instances(save, registration.get("itemInstances")):
        if item.get("itemName"):
            held[item["itemName"]].append(item)
    return held


def _holds_demanded_item(save: Save, here: dict, setting) -> bool:
    """Whether a building holds one of a "building" demand's items, as the game
    counts it: an item that displays products only while it holds some."""
    for slug in setting:
        for item in here.get("ba:itemname_" + slug, ()):
            if item["itemName"] not in DISPLAY_ITEMS or any(
                c.get("itemName") and (c.get("amount") or 0) > 0
                for c in save.items(item.get("cargoInstances"))
            ):
                return True
    return False


def _job_demands(save: Save, names: Names, businesses: list) -> None:
    """Which staff demands go unmet at each site, written onto its business row.

    staffDemands is one row per unmet demand with how many staff there hold it,
    highest priority first; company rows (health insurance, a happy boss) are
    marked, since no site can settle them. staffLacking, staffLackingCompany and
    staffLackingAny count the people behind the site rows, the company rows and
    either, and quitWarnings the people with anything unmet who have already
    warned they will quit. An hours or days row whose roster is right for some of
    them, who fail only on what they have already worked this week, carries
    workedOver: how many, and the most hours or days the demand allows. A demand
    the table does not know, from a newer game, is left out rather than guessed at.

    Somebody given no hours at the site holds no demand here at all (Peter, 30
    September 2026: "this should not be a warning, more an opportunity. You can
    reduce your headcount"): a full-time or four-day demand is only unmet once
    they have a week, and a desk, a building or insurance only matter while
    they work, and a quit warning from one of them is somebody the site can
    do without leaving. Their ids are listed as staffIdle instead, the people
    the site could move or let go; the board keeps those the plan on screen
    gives no week either (spSpareIds()).
    """
    root = save.root
    by_key = {b["key"]: b for b in businesses}
    regs = {
        site_key(_address_of(r, strict=True)): r
        for r in save.items(root["BuildingRegistrations"])
        if r.get("RentedByPlayer")
    }
    employees = save.items(root["EmployeeInstances"])
    by_id = {e.get("id"): e for e in employees}
    plans = {p.get("id"): p for p in save.items(root.get("hrManagerPlans"))}
    happiness = root.get("Happiness") or 0
    held, clean = {}, {}

    def items_at(key):
        if key not in held:
            held[key] = _items_by_name(save, regs[key])
        return held[key]

    def shifts(key, employee_id):
        """The employee's shifts on the days the building opens."""
        for day in save.items(regs[key].get("scheduleDays")):
            if day.get("isOpen"):
                for shift in save.items(day.get("workShifts")):
                    if shift.get("employeeId") == employee_id:
                        yield shift

    def rostered(e, kind, setting):
        """Whether the hours or days assigned meet an hours or days demand."""
        if kind == "hours":
            low, high = setting
            return low <= (e.get("assignedWeeklyHours") or 0) <= high
        return len(save.items(e.get("assignedWeeklyDays"))) == setting

    def worked_over(e, kind, setting):
        """Whether the hours or days worked so far this week pass the demand's top."""
        if kind == "hours":
            return (e.get("workedHoursThisWeek") or 0) > setting[1]
        return (e.get("workedDays") or 0) > setting

    def met(e, key, kind, setting):
        if kind in ("hours", "days"):
            return rostered(e, kind, setting) and not worked_over(e, kind, setting)
        if kind == "daysoff":
            return not set(save.items(e.get("assignedWeeklyDays"))) & set(setting)
        if kind == "noshift":
            return not any(
                low < (s.get("endingHour") or 0) and (s.get("startingHour") or 0) < high
                for s in shifts(key, e.get("id")) for low, high in setting
            )
        if kind == "nocleaning":
            return bool(regs[key].get("temporarilyClosed")) or not any(
                s.get("type") == CLEANING_SHIFT for s in shifts(key, e.get("id"))
            )
        if kind == "desk":
            desk = set(save.items(e.get("assignedWorkStationItems")))
            return any("ba:itemname_" + slug in desk for slug in setting)
        if kind == "building":
            return _holds_demanded_item(save, items_at(key), setting)
        if kind == "insurance":
            plan = plans.get(e.get("assignedHrManagerPlanId")) or {}
            cover = save.deref(plan.get("healthInsurancePlan")) or {}
            manager = by_id.get(plan.get("assignedEmployeeId")) or {}
            return (bool(cover) and (cover.get("planType") or 0) >= setting
                    and bool(manager) and not manager.get("isBeingReplaced"))
        if kind == "happiness":
            return happiness >= setting
        if kind == "clean":
            if key not in clean:
                clean[key] = _cleanliness(save, regs[key])
            return clean[key] >= setting
        raise ValueError(kind)

    unmet = collections.defaultdict(collections.Counter)
    # Of those, the people whose roster meets an hours or days demand and who
    # fail it only on what they have already worked this week.
    worked = collections.defaultdict(collections.Counter)
    # People, not demands: how many at each site lack something the site can
    # give, how many lack something only the owner can, and how many of those
    # with anything unmet have warned they will quit.
    people = collections.defaultdict(collections.Counter)
    idle = collections.defaultdict(list)
    for e in employees:
        key = site_key(save.address(e.get("assignedAddress")))
        if key not in by_key or key not in regs:
            continue
        if not (e.get("assignedWeeklyHours") or 0) > 0:
            idle[key].append(e.get("id"))
            continue
        lacks = set()
        for slug in dict.fromkeys(save.items(e.get("demands"))):  # one person, one count
            rule = JOB_DEMANDS.get(slug)
            if rule and not met(e, key, rule[0], rule[1]):
                unmet[key][slug] += 1
                if rule[0] in ("hours", "days") and rostered(e, rule[0], rule[1]):
                    worked[key][slug] += 1
                lacks.add("company" if rule[0] in COMPANY_DEMAND_KINDS else "site")
        for scope in lacks:
            people[key][scope] += 1
        if lacks:
            people[key]["any"] += 1
            if e.get("hasSendQuitWarning"):
                people[key]["quitting"] += 1
    for b in businesses:
        rows = [
            {
                "slug": slug,
                "demand": names.label(slug),
                "count": count,
                "priority": JOB_DEMANDS[slug][2],
                "company": JOB_DEMANDS[slug][0] in COMPANY_DEMAND_KINDS,
            }
            for slug, count in unmet[b["key"]].items()
        ]
        for row in rows:
            if worked[b["key"]][row["slug"]]:
                kind, setting, _ = JOB_DEMANDS[row["slug"]]
                row["workedOver"] = {
                    "count": worked[b["key"]][row["slug"]],
                    "max": setting[1] if kind == "hours" else setting,
                    "unit": kind,
                }
        rows.sort(key=lambda r: (-r["priority"], -r["count"], r["demand"]))
        b["staffDemands"] = rows
        b["staffLacking"] = people[b["key"]]["site"]
        b["staffLackingCompany"] = people[b["key"]]["company"]
        b["staffLackingAny"] = people[b["key"]]["any"]
        b["quitWarnings"] = people[b["key"]]["quitting"]
        b["staffIdle"] = sorted(idle[b["key"]], key=str)


def _station_shifts(save: Save, b: dict, crew: list):
    """(shift, person) for every station shift on an open day worked by someone
    on the staff: the shifts the game's uniform demand walks."""
    by_id = {p["id"]: p for p in crew if p.get("id") is not None}
    for schedule_day in save.items(b.get("scheduleDays")):
        if not schedule_day.get("isOpen"):
            continue
        for shift in save.items(schedule_day.get("workShifts")):
            # The game asks for a Default shift by type, not for "not cleaning",
            # so a type a later build adds is left out rather than counted in.
            if shift.get("type") != STATION_SHIFT:
                continue
            person = by_id.get(shift.get("employeeId"))
            if person:
                yield shift, person


def _uniform_gaps(save: Save, b: dict, crew: list, names: Names) -> list:
    """The skill ids working this floor that have no uniform, as the game scores it.

    EmployeeUniformsCustomerDemand.Fulfilled walks the staff on shift at that
    instant, takes for each the first of their station's suitableSkills they
    have, and wants uniformsBySkill to hold every skill it collected. The game
    only ever runs it at a moment — at midnight, or when the player moves an
    item or a worker — so its cached answer says "fine" for any shop whose floor
    happened to be empty then, and flips back to "not set" the next time an
    uncovered role is on. The same rule over the whole week gives the player the
    one answer that holds at every such moment: cover these skills and the
    demand is met whenever it is checked.

    Cleaning shifts are left out, as the game leaves them out. Whether anyone is
    absent today is not considered: absence passes on its own, and the uniform
    is still owed for the shift.
    """
    if not crew:
        return []  # no staff, no uniforms owed: the game returns fulfilled
    uniforms = {entry.get("$k") for entry in save.items(b.get("uniformsBySkill"))}
    # Keyed the way the game looks a station up, by the itemInstances key that
    # a shift's itemInstanceId names.
    stations = {}
    for holder in save.items(b.get("itemInstances")):
        item = save.deref(holder.get("$v")) if isinstance(holder, dict) else None
        if item:
            stations[holder.get("$k")] = item.get("itemName")
    gaps = set()
    for shift, person in _station_shifts(save, b, crew):
        held = set(person.get("skills") or ())
        for skill in STATION_SKILLS.get(stations.get(shift.get("itemInstanceId")), ()):
            if skill in held:
                if skill not in uniforms:
                    gaps.add(skill)
                break  # the game checks the first match and stops
    # A set decides these, so sort before they reach the payload. The caller
    # labels them; the ids stay for a write that sets the uniforms.
    return sorted(gaps)


def schedule_entries(save: Save, registration: dict) -> list:
    """A business's shifts as the shift print reads them: (weekday, from, to,
    employee id, station id, type), every field at its default when the save
    leaves it out."""
    return [
        (
            (scheduled.get("day") or 0) % 7,
            shift.get("startingHour") or 0,
            shift.get("endingHour") or 0,
            shift.get("employeeId") or "",
            shift.get("itemInstanceId") or "",
            shift.get("type") or 0,
        )
        for scheduled in save.items(registration.get("scheduleDays"))
        for shift in save.items(scheduled.get("workShifts"))
    ]


def shift_print(entries) -> str:
    """The schedule write's compare-and-set: docs/game-link-api.md, "Shift print".

    The mod computes the same from live state, so this is the contract's
    algorithm to the letter: one line per shift, sorted by ordinal string order,
    joined with newlines, FNV-1a 32-bit over the UTF-8 bytes. No shifts at all
    is the print of the empty string, 811c9dc5.
    """
    lines = sorted(
        "|".join((str(int(d)), str(int(f)), str(int(t)), e, s, str(int(k))))
        for d, f, t, e, s, k in entries
    )
    value = 0x811C9DC5
    for byte in "\n".join(lines).encode("utf-8"):
        value = ((value ^ byte) * 0x01000193) & 0xFFFFFFFF
    return f"{value:08x}"


def _business(save, names, b, addr, latest, history, staff_by_addr, day, agencies=None) -> dict:
    # The address keeps its takings after a business closes: a statement from
    # before this business opened (or from a day it did not exist) is the old
    # tenant's, not this one's.
    since = b.get("creationDay", 0)
    st = latest.get(addr, {}) if not history or history[-1][0] >= since else {}
    name = b.get("BusinessName")
    tag = ""
    if name and name.startswith("[") and "]" in name:
        tag = name[1 : name.index("]")]

    # The city is fixed, so the building table knows the neighbourhood from the
    # address alone; the name prefix only covers an address it does not list.
    building = load_buildings().get(addr)
    neighbourhood = hood_key(building) if building else NEIGHBOURHOODS.get(tag, "")

    orders = save.items(b["orderHistory"])
    # Every day the order history still holds, zeros included: a shop that
    # served nobody on Sunday measured that, and the fortnight spark has to
    # tell it apart from a day the history no longer reaches.
    customer_by_day = {e["dayNumber"]: e.get("totalCustomers", 0) for e in orders}
    # The weekday profile is a shape, and a closed day is not part of it, so
    # that one keeps to the days somebody came.
    customer_days = [(day, seen) for day, seen in customer_by_day.items() if seen]
    revenue_days = [
        (dayno, by_addr[addr]["TotalSales"])
        for dayno, by_addr in history
        if addr in by_addr and by_addr[addr]["TotalSales"] > 0
    ]
    rhythm = _weekday_profile(revenue_days)
    customer_rhythm = _weekday_profile(customer_days)
    recent = orders[-STOCK_COVER_DAYS:]
    customers = recent[-1]["totalCustomers"] if recent else 0

    units_sold = collections.Counter()
    revenue_by_item = collections.Counter()
    for entry in recent:
        for sale in save.items(entry.get("itemSales")):
            units_sold[sale["itemName"]] += sale.get("amountSold", 0)
            revenue_by_item[sale["itemName"]] += sale.get("totalPrice", 0)
    span = max(len(recent), 1)

    # A trading day is one after the opening day with somebody through the
    # door: the opening day is partial, and a closed day or a day before the
    # shop opened says nothing about how fast it sells; today is not over. The
    # rate the supply figures read is the last week of trading days, not of
    # calendar days, so a shop open four days is not judged at four sevenths
    # of its pace.
    opened = b.get("creationDay", 0)
    trading = [e for e in orders
               if opened < e.get("dayNumber", 0) < day and e.get("totalCustomers", 0) >= 1]
    trade_window = trading[-STOCK_COVER_DAYS:]
    week_trading = sum(1 for e in trading if e.get("dayNumber", 0) >= day - 7)
    # The days of the last seven since the site first traded: the days before
    # it (the opening day, an empty day or two) are no week it could sell in.
    first_trade = trading[0].get("dayNumber", day - 7) if trading else day - 7
    open_days = min(7, max(1, day - first_trade))
    trade_sold = collections.Counter()
    for entry in trade_window:
        for sale in save.items(entry.get("itemSales")):
            trade_sold[sale["itemName"]] += sale.get("amountSold", 0)
    # A site under a week old keeps its trading days, so Demand sizing can fit
    # a line through them and read the coming week off it (_coming_week).
    young = day - opened < NEW_SITE_DAYS
    sold_days = collections.defaultdict(list)
    if young:
        for entry in trading:
            by_item = collections.Counter()
            for sale in save.items(entry.get("itemSales")):
                by_item[sale["itemName"]] += sale.get("amountSold", 0)
            for item, units in by_item.items():
                sold_days[item].append([entry["dayNumber"], units])

    stock = collections.Counter()
    has_uniform_locker = False
    for item in _item_instances(save, b["itemInstances"]):
        if item.get("itemName") == "ba:itemname_uniformlocker":
            has_uniform_locker = True
        for cargo in save.items(item.get("cargoInstances")):
            stock[cargo["itemName"]] += cargo.get("amount", 0)

    prices = {
        p["itemName"]: p["price"] for p in save.items(b["retailPrices"]) if p
    }

    lines = []
    # Rows that tie on cover would otherwise reshuffle between runs and page loads.
    for item in _in_order(set(stock) | set(units_sold) | set(prices)):
        rate = units_sold[item] / span
        # With no trading day on record (a depot, or a site nobody has come to
        # yet) the calendar rate is all there is.
        trade_rate = trade_sold[item] / len(trade_window) if trade_window else rate
        # A week of it: the trading-day rate on the days the shop traded in the
        # last seven, so a shop open two days a week sells two days' worth. A
        # site open less than a week spreads its week over the days it has
        # been open, not over days before it opened.
        week_sold = (trade_rate * week_trading * 7 / open_days) if trade_window else rate * 7
        lines.append(
            {
                "item": names.label(item),
                "slug": item,
                "units": int(stock[item]),
                "rate": round(rate, 1),
                "tradeRate": round(trade_rate, 1),
                "weekSold": round(week_sold, 1),
                **({"soldDays": sold_days[item]} if sold_days.get(item) else {}),
                "cover": round(stock[item] / rate, 1) if rate > 0.5 else None,
                "price": money(prices.get(item, 0)),
                "configuredPrice": _configured_price(prices.get(item)),
                "revenue": money(revenue_by_item[item] / span),
                # What a unit sold for over the window: the takings over the
                # units, both unrounded (a slow line's rounded rate would
                # skew it); None where nothing sold.
                "soldPrice": (round(revenue_by_item[item] / units_sold[item], 2)
                              if units_sold[item] > 0 else None),
                "soldPerDay": round(units_sold[item] / span),
                "soldPerWeek": round(units_sold[item] / span * 7),
                **({"issued": True} if item in ISSUED_ITEMS else {}),
                # Unrounded, for _products() alone, which takes them off the
                # payload: a price from rounded units is no price.
                "_sold": units_sold[item] / span,
                "_takings": revenue_by_item[item] / span,
            }
        )
    lines.sort(key=lambda x: (x["cover"] is None, x["cover"] if x["cover"] else 0))

    series = []
    for dayno, by_addr in history[-30:]:
        s = by_addr.get(addr)
        if s:
            series.append(
                {
                    "day": dayno,
                    "profit": money(s["TotalProfit"]),
                    "revenue": money(s["TotalSales"]),
                    # The same day's door count, so a site can draw a fortnight
                    # of shoppers beside its fortnight of takings. The order
                    # history is shorter than the takings history, so a day it
                    # no longer covers has no reading — None, never a zero.
                    "customers": customer_by_day.get(dayno),
                }
            )

    crew = staff_by_addr.get(addr, [])
    sat = save.deref(b.get("satisfaction")) or {}
    promo = save.deref(b.get("promotion")) or {}
    btype = b.get("businessTypeName", "")
    revenue = money(st.get("TotalSales", 0))
    profit = money(st.get("TotalProfit", 0))

    if not name:
        status = "vacant"
    elif btype in RETAIL_TYPES:
        status = "retail"
    elif btype in OFFICE_TYPES:
        status = "office"
    elif btype in OVERHEAD_TYPES:
        status = "overhead"
    else:
        status = "support"

    # What customers currently find when they walk in. The game caches only the
    # demands it found fulfilled, so an absent one has either failed or is never
    # asked for here at all — and a demand this type's customers never make is
    # absent for good, which is why it is dropped rather than reported. A shop
    # too new to have been scored yet is held back by the not-trading gate in
    # _alerts() instead. The uniform demand is worked out from the roster rather
    # than read here at all.
    demands = set(save.items(b.get("cachedFulfilledCustomerDemands")))
    not_made = DEMANDS_NOT_MADE.get(btype, ())
    missing_amenities = (
        [
            slug
            for slug in AMENITY_DEMANDS
            if slug not in demands and slug not in not_made
        ]
        if status == "retail"
        else []
    )
    wants_uniforms = status == "retail" and UNIFORM_DEMAND not in not_made
    uniform_gaps = _uniform_gaps(save, b, crew, names) if wants_uniforms else []
    campaigns, marketing = _marketing(save, b, building, status, neighbourhood, promo, agencies)

    return {
        "name": name or "Vacant lease",
        "tag": tag,
        "neighbourhood": neighbourhood,
        # The badge's two letters: the player's own prefix, or the canonical
        # one for a neighbourhood only the table knows.
        "code": tag or HOOD_TAG.get(neighbourhood, ""),
        "type": names.label(btype, "Empty"),
        "typeSlug": btype,
        "status": status,
        "costCentre": btype in COST_CENTRE_TYPES,
        "key": site_key(addr),
        "restocks": btype in RESELLER_TYPES,
        "address": f"{house_number(b['StreetNumber'])} {names.street(b['StreetName'])}",
        "opened": b.get("creationDay", 0),
        "rent": money(b.get("RentPerDay", 0)),
        "capacity": b.get("customerCapacity", 0),
        "revenue": revenue,
        "cogs": money(st.get("TotalResources", 0)),
        "wages": money(st.get("SalaryExpenses", 0)),
        "marketing": money(st.get("MarketingExpenses", 0)),
        "theft": money(st.get("Theft", 0)),
        "licensing": money(st.get("LicensingFees", 0)),
        "profit": profit,
        "margin": round(profit / revenue * 100, 1) if revenue else None,
        "satisfaction": {
            "overall": sat.get("overall", 0) if status in ("retail", "office") else None,
            "service": sat.get("customerService", 0),
            "pricing": sat.get("pricing", 0),
            "cleanliness": sat.get("cleanliness", 0),
            "facility": sat.get("facility", 0),
        },
        "promotion": promo.get("total", 0),
        "traffic": promo.get("trafficIndex", 0),
        "marketingIndex": promo.get("marketing", 0),
        # The campaigns as the game holds them, and the cheapest mix for a shop
        # or an office (None elsewhere, or where a figure is unknown).
        "campaigns": campaigns,
        "marketingPlan": marketing,
        "missingAmenities": missing_amenities,
        # The same walk, amenity by amenity: True is the game cached the demand
        # as fulfilled, False is looked for and missed. A demand the type never
        # makes has no row at all, so a florist has no music key — and an office
        # is never asked, so it carries no dict and the panel draws no lamps.
        "amenities": (
            {
                group: slug in demands
                for slug, (group, _text) in AMENITY_DEMANDS.items()
                if slug not in not_made
            }
            if status == "retail"
            else None
        ),
        # The roles on this floor with no uniform set for them, named, and the
        # same skills as the game's ids, in the same order.
        "uniformGaps": [names.label(skill) for skill in uniform_gaps],
        "uniformGapSkills": uniform_gaps,
        # What a schedule write sends as `expect`: the shifts as these bytes
        # hold them, printed the way the mod prints its live ones.
        "shiftPrint": shift_print(schedule_entries(save, b)),
        # The locker is what the player manages uniforms from, so it is checked
        # directly rather than through any demand; one still in cargo is boxed.
        # A type whose customers never ask about uniforms needs neither.
        "missingUniformLocker": wants_uniforms and not has_uniform_locker,
        # Shifts at a named station: without one no uniform is asked for yet.
        "stationShifts": sum(1 for _ in _station_shifts(save, b, crew)),
        # Whether the shop has ever booked a sale: the last statement alone is
        # zero on a day the shop stood closed.
        "hasTraded": revenue > 0
        or any(dayno >= since and by_addr.get(addr, {}).get("TotalSales", 0) > 0 for dayno, by_addr in history),
        "staff": len(crew),
        "staffCost": sum(c["daily"] for c in crew),
        "crew": _crew(crew),
        "people": _people(crew),
        "rhythm": rhythm,
        "customerRhythm": customer_rhythm,
        "swing": _swing(rhythm or customer_rhythm),
        "peakDay": _peak_day(rhythm or customer_rhythm),
        "customers": customers,
        # customerCapacity is how many shoppers fit inside at once, not a daily
        # figure, so spend per visit is the honest derived number here.
        "basket": round(revenue / customers, 2) if customers else None,
        "security": round(b.get("securityLevelPercentage", 0)),
        "lines": lines,
        "series": series,
        "daysOpen": max(day - b.get("creationDay", day), 1),
        # Days after opening with at least one customer, all the order history
        # holds: under MIN_TRADE_DAYS a shelf is too young to judge.
        "tradeDays": len(trading),
    }


def _open_hours(save, reg) -> list:
    """A registration's opening slots per board weekday (0 is Sunday), [] shut.

    ScheduleDay.day is the game day modulo 7, with 7 for Sunday's 0.
    """
    hours = [[] for _ in range(7)]
    for scheduled in save.items(reg.get("scheduleDays")):
        if not scheduled.get("isOpen") or not isinstance(scheduled.get("day"), int):
            continue
        hours[scheduled["day"] % 7] = sorted(
            [max(0, slot.get("startingHour") or 0), min(24, slot.get("endingHour") or 0)]
            for slot in save.items(scheduled.get("openingHourSlots"))
            if (slot.get("endingHour") or 0) > (slot.get("startingHour") or 0))
    return hours


def open_at(hours, closed, day, hour) -> bool:
    """BusinessHelper.IsBusinessOpen at a game day and whole hour (build 3682
    IL): not temporarily closed, and the hour inside one of that weekday's
    slots, start included and end excluded. Minutes are never looked at, and
    no slot runs past midnight."""
    return not closed and any(start <= hour < end for start, end in hours[day % 7])


def next_open(hours, closed, day, hour) -> dict | None:
    """The first whole hour from (day, hour) on at which the place is open,
    as {day, hour}; None when it is temporarily closed or never opens."""
    if closed:
        return None
    for step in range(8 * 24):
        d, h = day + (hour + step) // 24, (hour + step) % 24
        if open_at(hours, False, d, h):
            return {"day": d, "hour": h}
    return None


def _marketing_agencies(save, names=None) -> list:
    """The city's marketing agencies, as the board plans and writes with them.

    Per agency: its site key and name, whether it is a phone contact (the
    player has visited it once; the write works only through those), the
    types it sells, its opening slots per board weekday and whether it is
    temporarily closed, and, at the save's clock, whether it is open now and
    when it next opens (the write works only while it is open).
    """
    root = save.root
    contacts = {(c.get("streetName"), c.get("streetNumber"))
                for c in save.items(root.get("Contacts")) if isinstance(c, dict)}
    regs = {_address_of(r): r
            for r in save.items(root.get("BuildingRegistrations")) if isinstance(r, dict)}
    day, hour = root.get("Day") or 0, int(root.get("Hour") or 0)
    out = []
    for addr, (name, kinds) in MARKETING_AGENCIES.items():
        reg = regs.get(addr) or {}
        hours, closed = _open_hours(save, reg), bool(reg.get("temporarilyClosed"))
        out.append({
            "key": site_key(addr),
            "name": reg.get("BusinessName") or name,
            "address": f"{house_number(addr[1])} {names.street(addr[0]) if names else _plain(addr[0].removeprefix('ba:street_'))}",
            "contact": addr in contacts,
            "types": [MARKETING_TYPES[k][0] for k in kinds],
            "hours": hours,
            "closed": closed,
            "open": open_at(hours, closed, day, hour),
            "opens": next_open(hours, closed, day, hour),
        })
    return out


def _marketing(save, b, building, status, neighbourhood, promo, agencies=None) -> tuple[list, dict | None]:
    """A site's campaigns, and its cheapest mix (marketing_plan()).

    `campaigns` is one row per entry the game holds: the type's enum name, the
    agency's site key and whether it runs. The plan is for a shop or an office
    in a building whose type carries a promotion, with its m² and neighbourhood
    known; anything else gets None. `on` and `was` are enum names, as the write
    sends them.

    Peter's rule (28 Sep 2026): a type the site already has an entry for (a
    switch in BizMan) is turned on or off at any time, whatever its agency. A
    type with no entry needs a new one, which only an agency that is a phone
    contact adds, and only while it is open. So the plan may switch the types
    with an entry and the types a contacted agency sells; any other stays off.
    With no type free and a change wanted the plan's `on` is None.
    `visit` names the agencies, not contacts yet, whose types would make a
    better plan (a higher promotion, or the same for less); `visitRaises`, that
    it would be higher, not only cheaper. `setupTypes` and
    `setupAgencies` are the switches a contacted agency could add and who
    sells them. `agencies` are the agencies the plan needs a NEW switch from,
    each of which must be open at the write; flipping an existing switch needs
    none. `needsSetup`: a type a contacted agency sells has no entry, so
    BizMan does not show its switch yet.
    """
    campaigns = []
    for c in save.items(b.get("marketingCampaigns")):
        kind = c.get("marketingTypeName")
        if not isinstance(kind, int) or not 0 <= kind < len(MARKETING_TYPES):
            continue
        campaigns.append({"type": MARKETING_TYPES[kind][0],
                          "agency": site_key(save.address(c.get("agencyAddress"))),
                          "enabled": bool(c.get("enabled"))})
    if status not in ("retail", "office") or not building:
        return campaigns, None
    sqm, kind = building.get("m"), building.get("t")
    if not sqm or kind not in MARKETING_REACH or neighbourhood not in MARKETING_STRENGTH:
        return campaigns, None
    if agencies is None:
        agencies = _marketing_agencies(save)
    was = {MARKETING_IDS[c["type"]] for c in campaigns if c["enabled"]}
    entered = {MARKETING_IDS[c["type"]] for c in campaigns}
    contact = {a["key"] for a in agencies if a["contact"]}
    # The agency a new entry of a type comes from: the first that sells it,
    # as the mod walks them.
    seller = {}
    for a in agencies:
        for t in a["types"]:
            seller.setdefault(MARKETING_IDS[t], a["key"])
    new_ok = {t for t, a in seller.items() if a in contact}
    free = entered | new_ok
    traffic = promo.get("trafficIndex", 0) or 0
    best = marketing_plan(traffic, was, sqm, kind, neighbourhood)
    plan = marketing_plan(traffic, was, sqm, kind, neighbourhood, free)
    # With no switch to flip and no agency to book through, a site that needs
    # a change has no plan.
    if not free and set(best["on"]) != was:
        plan = None
    better = plan is None or (best["promotion"], -best["cost"]) > (plan["promotion"], -plan["cost"])
    visit = sorted({seller[t] for t in set(best["on"]) - free if t in seller}) if better else []
    setup = new_ok - entered
    fresh = set(plan["on"]) - entered if plan else set()
    name = lambda ids: [MARKETING_TYPES[i][0] for i in sorted(ids)]  # noqa: E731
    return campaigns, {
        "on": name(plan["on"]) if plan else None,
        "was": name(was),
        "costNow": best["costNow"],
        "costPlan": plan["cost"] if plan else None,
        "marketingNow": promo.get("marketing", 0),
        "marketingPlan": plan["marketing"] if plan else None,
        "promotionNow": promo.get("total", 0),
        "promotionPlan": plan["promotion"] if plan else None,
        "target": plan["target"] if plan else None,
        "needsSetup": bool(setup),
        # The switches a contacted agency could still add, and who sells
        # them: one is added only while its agency is open.
        "setupTypes": name(setup),
        "setupAgencies": sorted({seller[t] for t in setup}),
        "agencies": sorted({seller[t] for t in fresh}),
        "visit": visit,
        # Whether those visits would raise promotion, not only save money.
        "visitRaises": bool(visit) and (plan is None or best["promotion"] > plan["promotion"]),
    }


def _crew(crew: list) -> list:
    """Who works here, folded into roles."""
    roles = collections.OrderedDict()
    for person in sorted(crew, key=lambda c: (c["role"], -c["level"])):
        entry = roles.setdefault(
            person["role"],
            {"role": person["role"], "count": 0, "daily": 0.0, "skill": 0, "absent": 0},
        )
        entry["count"] += 1
        entry["absent"] += 1 if person.get("absent") else 0
        entry["daily"] += person["daily"]
        entry["skill"] = max(entry["skill"], person["level"])
    for entry in roles.values():
        entry["daily"] = money(entry["daily"])
    return sorted(roles.values(), key=lambda r: -r["count"])


def _people(crew: list) -> list:
    """The same crew one person at a time, so a site can name who works it.

    A character without a name — the save permits it, and _staff then reads
    "?" — still gets a stable label: its role plus a number within the role.
    """
    seen = collections.Counter()
    out = []
    for person in sorted(crew, key=lambda c: (c["role"], c["name"])):
        seen[person["role"]] += 1
        name = person["name"]
        if name == "?":
            name = f"{person['role']} {seen[person['role']]}"
        out.append(
            {
                "name": name,
                "role": person["role"],
                "absent": bool(person["absent"]),
                "daily": money(person["daily"]),
            }
        )
    return out


def _chain_rhythm(save: Save, buildings: list, daily: list, day: int) -> dict:
    """The weekly cycle across the whole chain, in revenue and in footfall."""
    customers = collections.Counter()
    for b in buildings:
        for entry in save.items(b["orderHistory"]):
            customers[entry["dayNumber"]] += entry.get("totalCustomers", 0)
    profiles = {
        "revenue": _weekday_profile([(d["day"], d["revenue"]) for d in daily]),
        "profit": _weekday_profile(
            [(d["day"], d["profit"]) for d in daily if d["profit"] > 0]
        ),
        "customers": _weekday_profile(sorted(customers.items())),
    }
    # What today and yesterday are normally worth, so a single day's figure can
    # be read against its own weekday rather than a flat average.
    reference = profiles["customers"] or profiles["revenue"]
    by_name = {p["day"]: p["index"] for p in reference} if reference else {}
    today = WEEKDAYS[day % 7]
    yesterday = WEEKDAYS[(day - 1) % 7]
    profiles["today"] = {"day": today, "index": by_name.get(today)}
    profiles["yesterday"] = {"day": yesterday, "index": by_name.get(yesterday)}
    profiles["basis"] = "customers" if profiles["customers"] else "revenue"
    # The same three series over the last four weeks only, for the chart. The
    # full-length ones above stay what the supply sizing reads.
    # The window is counted in calendar days back from the last finished day,
    # the same for all three, so a series with gaps reads fewer weeks.
    end = daily[-1]["day"] if daily else None
    profiles["recent"] = {
        "days": RHYTHM_RECENT_DAYS,
        "revenue": _weekday_profile(
            [(d["day"], d["revenue"]) for d in daily], RHYTHM_RECENT_DAYS, end),
        "profit": _weekday_profile(
            [(d["day"], d["profit"]) for d in daily if d["profit"] > 0], RHYTHM_RECENT_DAYS, end),
        "customers": _weekday_profile(sorted(customers.items()), RHYTHM_RECENT_DAYS, end),
    }
    return profiles


def _product_rhythm(save: Save, buildings: list) -> dict:
    """Which weekday each product peaks on, across every shop that sells it,
    by the item's key."""
    units = collections.defaultdict(collections.Counter)
    for b in buildings:
        for entry in save.items(b["orderHistory"]):
            for sale in save.items(entry.get("itemSales")):
                units[sale["itemName"]][entry["dayNumber"]] += sale.get("amountSold", 0)
    out = {}
    for item, by_day in units.items():
        profile = _weekday_profile(sorted(by_day.items()))
        if profile:
            out[item] = {
                "profile": profile,
                "peak": _peak_day(profile),
                "swing": _swing(profile),
                "weeks": _weeks(profile),
            }
    return out


def _daily_series(save: Save, summaries: list) -> list:
    out = []
    for s in summaries:
        revenue = cogs = wages = rent = marketing = theft = 0.0
        for st in save.items(s["businessIncomeStatements"]):
            revenue += st.get("TotalSales", 0)
            cogs += st.get("TotalResources", 0)
            wages += st.get("SalaryExpenses", 0)
            rent += st.get("RentExpenses", 0)
            marketing += st.get("MarketingExpenses", 0)
            theft += st.get("Theft", 0)
        out.append(
            {
                "day": s["dayNumber"],
                "profit": money(s.get("totalProfit", 0)),
                "business": money(s.get("totalBusinessProfit", 0)),
                "revenue": money(revenue),
                "cogs": money(cogs),
                "wages": money(wages),
                "rent": money(rent),
                "marketing": money(marketing),
                "theft": money(theft),
                "loans": money(-s.get("totalLoanExpenses", 0)),
                # The company's own costs, which no site's statement carries:
                # with the loans they are the gap between `business` (the
                # Portfolio total) and `profit`. The game books residential
                # expenses as a positive number and the rest as negative ones.
                "insurance": money(-s.get("totalHealthInsuranceExpenses", 0)),
                "homes": money(s.get("totalResidentialExpenses", 0)),
                "parking": money(-s.get("parkingFees", 0)),
            }
        )
    return out


def _loans(save: Save, names: Names) -> list:
    out = []
    for l in save.items(save.root["Loans"]):
        remaining = money(l.get("remainingAmount", 0))
        total = money(l.get("totalAmount", 0))
        bank = save.address(l.get("bankAddress"))
        out.append(
            {
                "bank": names.addr(bank),
                # The bank's site key, as openStore.finance names each bank: a
                # plan's loan is looked up by it (Open a store, step 6).
                "key": site_key(bank),
                "total": total,
                "remaining": remaining,
                "repaid": round((1 - remaining / total) * 100, 1) if total else 0,
                "dailyPayment": money(l.get("dailyPayment", 0)),
                "dailyInterest": money(l.get("dailyInterest", 0)),
            }
        )
    return sorted(out, key=lambda x: -x["remaining"])


def _products(businesses: list) -> list:
    agg = collections.defaultdict(
        lambda: {"revenue": 0.0, "units": 0.0, "week": 0, "stock": 0, "stores": 0}
    )
    for b in businesses:
        for line in b["lines"]:
            # The day's takings and units before rounding: a line selling 0.4
            # a day is not nothing, and its share of the average price is not
            # free. _business() leaves them for this and nothing else.
            sold, takings = line.pop("_sold", None), line.pop("_takings", None)
            if not line["revenue"] and not line["units"]:
                continue
            # By key: two items can share a name, and the page names a row
            # from its key.
            rec = agg[line["slug"]]
            rec["item"] = line["item"]
            rec["revenue"] += line["revenue"] if takings is None else takings
            rec["units"] += line.get("rate", line["soldPerDay"]) if sold is None else sold
            rec["week"] += line["soldPerWeek"]
            rec["stock"] += line["units"]
            rec["stores"] += 1 if line["revenue"] else 0
    out = [{"item": v.pop("item"), "slug": k, **v} for k, v in agg.items()]
    for rec in out:
        rec["price"] = round(rec["revenue"] / rec["units"], 2) if rec["units"] else 0
        rec["revenue"] = money(rec["revenue"])
        rec["units"] = round(rec["units"])
    return sorted(out, key=lambda x: -x["revenue"])


def _staff_summary(staff: list, businesses: list) -> dict:
    by_role = collections.Counter(s["role"] for s in staff)
    cost_by_role = collections.Counter()
    for s in staff:
        cost_by_role[s["role"]] += s["daily"]
    # By site key, not name: two shops can share a name.
    by_site = collections.Counter()
    site_name = {}
    for b in businesses:
        by_site[b["key"]] += b["staff"]
        site_name[b["key"]] = b["name"]
    return {
        "total": len(staff),
        "dailyCost": sum(s["daily"] for s in staff),
        "avgSatisfaction": round(sum(s["satisfaction"] for s in staff) / len(staff), 1)
        if staff
        else 0,
        "unhappy": sum(1 for s in staff if s["satisfaction"] < 70),
        "absent": sum(1 for s in staff if s["absent"]),
        "complaining": sum(1 for s in staff if s["complaining"]),
        "roles": sorted(
            ({"role": r, "count": c, "cost": round(cost_by_role[r])} for r, c in by_role.items()),
            key=lambda x: -x["count"],
        ),
        "sites": sorted(
            ({"site": site_name[k], "key": k, "count": c} for k, c in by_site.items() if c),
            key=lambda x: -x["count"],
        ),
    }


def _openable_types(names: Names) -> list[str]:
    """Every business type a player can open, as the game's own F1 pages list them.

    The locale also carries display names for types nobody can open — empty,
    notimplemented, the IRS, the government, the hospital — so the raw
    businesstype_* keys overcount. A type gets a help page only where the
    player can actually run one: the sixteen retail floors, the five
    agencies, the factory, the warehouse and the headquarters.
    """
    found = set()
    for key in names.locale:
        match = _BUSINESS_HELP_RE.match(key)
        if match:
            found.add(match.group(1))
    return sorted(found)


def _owned_buildings(save: Save, names: Names) -> list[dict]:
    """Purchased real estate, independent of rented business registrations."""
    result = []
    for entry in save.items(save.root.get("realEstate")):
        address = save.address(entry.get("address"))
        if address:
            result.append({
                "key": site_key(address), "address": names.addr(address),
                "purchaseDay": entry.get("purchaseDay"),
                "purchasePrice": money(entry["purchasePrice"]) if entry.get("purchasePrice") is not None else None,
            })
    return result


def _homes(buildings: list, residential: set, names: Names) -> list[dict]:
    """Rented homes: registrations the save bills as residences, never businesses.

    Size and neighbourhood come from the static building table, read here and
    not at import time: in the browser nothing is on the virtual filesystem
    until the worker has written it. An address the table does not carry gets
    None for both, never a zero — the flat has a size, it is just not known.
    """
    table = load_buildings()
    result = []
    for b in buildings:
        addr = _address_of(b, strict=True)
        if addr in residential:
            row = table.get(addr) or {}
            result.append({
                "key": site_key(addr),
                "address": f"{house_number(b['StreetNumber'])} {names.street(b['StreetName'])}",
                "rent": money(b.get("RentPerDay") or 0),
                "m": row.get("m") or None,
                "hood": hood_key(row),
            })
    return result


def _goals(save: Save, names: Names, businesses: list) -> dict:
    """Career totals, with a denominator where the save carries one.

    The save lists every diploma the player can study and every story rival,
    so those two read "n of total". The personal goals list holds only the
    completed ones and the achievement counters have no target, so the rest
    are bare totals.
    """
    ach = save.deref(save.root.get("achievementsData")) or {}
    diplomas = save.items(save.root["PlayerDiplomas"])
    rivals = save.items(save.root.get("specialRivalStates"))
    goals_done = save.items(save.root["completedPersonalGoals"])
    return {
        "completed": len(goals_done),
        "diplomas": sum(1 for d in diplomas if d.get("completed")),
        "diplomasTotal": len(diplomas),
        "rivalsDefeated": sum(1 for r in rivals if r.get("isDefeated")),
        "rivalsTotal": len(rivals),
        "goodsProduced": ach.get("goodsProducedInFactories", 0),
        "taxesPaid": money(ach.get("taxesPaid", 0)),
        # Types the player runs versus the types the game offers, and buildings
        # bought outright (root realEstate, each with its purchase day) versus
        # every building in the city's table. The goals carry no total: the
        # save stores only the ids of the ones already completed.
        "typesRun": len({b["typeSlug"] for b in businesses if b["status"] in ("retail", "office")}),
        "typesTotal": len(_openable_types(names)),
        "buildingsOwned": len(save.items(save.root.get("realEstate"))),
        "buildingsTotal": len(load_buildings()),
        "goalsDone": len(goals_done),
        "goalsTotal": None,
    }


# --------------------------------------------------------------------- supply
def _deepest_use(per_day, weekly, day, until, left_today, rounds=False, extra=None, steady=None, drop=True):
    """The most a walk from now to the start of `until` has used at any point.

    A day's use can be negative (a route's surplus beyond it stays on the
    shelf), so this is the deepest the running total goes, not where it ends:
    a quiet Sunday does not refill a shelf emptied on Saturday.

    Shop-style (`rounds` False): the rest of today, charged for the hours it
    has left, then whole days up to `until`, whose drop supplies that day. A
    depot served by a morning logistics round (`rounds` True) is emptied a
    round at a time, not an hour at a time: `left_today` is then 1 or 0 (0
    once today's round is in the log), and the delivery day's own round is
    charged too, because it leaves before the import lands. `extra` {day:
    units} is added to a day's draw (the depot rows' routes to depots whose
    own import has not landed yet). `steady` (units a day, today's share) is
    a draw that runs round the clock whatever the rounds do, the site's own
    factory lines: charged flat for the hours left today and each whole day
    before `until`, never on the delivery day, whose drop feeds them. With
    `drop` False nothing lands at `until` (a paused line walked a week), so
    the steady draw is charged on `until` too.
    """
    extra = extra or {}
    used = deepest = 0.0
    for ahead in range(max(0, until - day + (1 if rounds else 0))):
        share = left_today if ahead == 0 else 1
        used += (per_day * weekly[(day + ahead) % 7] + extra.get(day + ahead, 0.0)) * share
        used += _steady_on(steady, ahead, day + ahead < until or not drop)
        deepest = max(deepest, used)
    return deepest


def _steady_on(steady, ahead, before_drop=True):
    """What a round-the-clock draw (`steady`: units a day, today's share)
    takes on the day `ahead` days from now; nothing from the drop on."""
    if not steady or not before_drop:
        return 0.0
    return steady[0] * (steady[1] if ahead == 0 else 1.0)


def _import_catch_up(stock, per_day, weekly, day, arrives, left_today, rounds=False, extra=None, steady=None,
                     drop=True):
    """Extra whole units needed until the scheduled delivery lands.

    Use the same weekday demand and partial current day (or whole rounds) as
    the coverage walk; the drop itself is supplied by the recurring order, not
    this one-off. With a route's surplus days it is the deepest shortfall on
    the way (_deepest_use), not the net over the stretch.
    """
    return max(0, math.ceil(
        _deepest_use(per_day, weekly, day, arrives, left_today, rounds, extra, steady, drop) - stock))


def _import_setting(supply: dict) -> dict:
    """How a depot line's imports are set in game, for the page to show.

    `smart` and `target` say whether the line runs on Smart Delivery and the
    level of the contract that holds it, named by `levelImporter` and
    `levelId` (_import_level); `levelName` is how the page names it, the
    importer, with the contract's number where that importer has several. `plain` is what plain contracts on the line
    bring a week: `plainBefore` of it is delivered before that level and
    counts toward it, `plainAfter` comes after it, on top. `pass` is the
    counted contracts in delivery order and `levelAt` the named one's place in
    it, so the page can replay the pass with another level (importLevelFor).
    `arrivedLastWeek` sums every contract's amountOrderedLastWeek, paused ones
    too, since those goods did arrive. `contracts` lists each contract on the
    line in the order the game delivers them.
    """
    # A hand-built supply (tests of the factory view) may carry only the
    # weekly figures; it reads as plain contracts with nothing more known.
    return {
        "smart": supply.get("smart", False),
        "target": supply.get("target"),
        "plain": supply.get("plain", supply.get("weekly", 0)),
        "plainAfter": supply.get("plainAfter", 0),
        "plainBefore": supply.get("plainBefore", 0),
        "levelImporter": supply.get("levelImporter"),
        "levelName": supply.get("levelName", supply.get("levelImporter")),
        "levelId": supply.get("levelId"),
        "levelAt": supply.get("levelAt"),
        "pass": [{"amount": d["amount"], "smart": d["smart"]} for d in supply.get("pass", [])],
        "arrivedLastWeek": supply.get("arrived", supply.get("lastWeek", 0)),
        "contracts": supply.get("contracts", []),
    }


def _import_ranks(save: Save, partnerships: list) -> list:
    """Each contract's place in the game's delivery pass, by plan position.

    DoAllDeliveries goes importer by importer, each importer in the place of
    its first contract in importPartnerships, and its contracts in plan order.
    """
    first_of = {}
    for order, partnership in enumerate(partnerships):
        first_of.setdefault(save.address(partnership.get("importAddress")), order)
    return [
        (first_of[save.address(partnership.get("importAddress"))], order)
        for order, partnership in enumerate(partnerships)
    ]


def _contract_list(contracts: list) -> list:
    """A line's contracts in the order the game delivers them.

    The rank (importer group first) orders the list and is then dropped; each
    contract keeps its raw place in importPartnerships as `order`, which is
    what a later reorder writes.
    """
    return [
        {k: v for k, v in c.items() if k != "rank"}
        for c in sorted(contracts, key=lambda c: c["rank"])
    ]


def _import_level(drops: list) -> dict:
    """Which Smart Delivery contract holds a line's level, and the plain around it.

    `drops` is in delivery order, as _import_drop() walks them. The contract
    named (`at`, its index) is the last Smart Delivery one that still brings
    something into an empty depot: a later level finds the depot already at
    or above it and brings nothing. Where none brings anything, because plain
    amounts delivered first already pass every level, the last one is named.
    `plainBefore` is the plain amount delivered before it, which counts toward
    its level (the top-up is only what is missing); `plainAfter` is delivered
    after it and comes on top. A line with no level has `smart` False.
    """
    stock, holds, last = 0, None, None
    for i, drop in enumerate(drops):
        if drop["smart"]:
            last = i
            brought = max(0, drop["amount"] - max(stock, 0))
            if brought > 0:
                holds = i
        else:
            brought = drop["amount"]
        stock += brought
    if last is None:
        return {"smart": False, "level": None, "at": None, "plainBefore": 0, "plainAfter": 0}
    at = holds if holds is not None else last
    plain = lambda part: sum(d["amount"] for d in part if not d["smart"])
    return {"smart": True, "level": drops[at]["amount"], "at": at,
            "plainBefore": plain(drops[:at]), "plainAfter": plain(drops[at + 1:])}


def _import_pass(drops: list, at: int, level) -> float:
    """What one delivery brings into an empty depot with the contract at `at`
    set to `level`: the pass _import_drop() makes, replayed."""
    return _import_drop(0, [dict(d, amount=level) if i == at else d for i, d in enumerate(drops)])


def _level_for(drops: list, at: int, need) -> int:
    """The smallest level, in steps of SUPPLY_ROUND_TO, for the contract at
    `at` whose pass brings `need`.

    Found by replaying the pass, not by arithmetic on the plain amounts: a
    plain amount delivered before the level counts toward it, one after it
    comes on top, and a later level may take over. The pass only grows with
    the level and brings at least the level itself, so `need` rounded up to
    the step always suffices and a halving search finds the least.
    """
    step = SUPPLY_ROUND_TO
    lo, hi = 0, math.ceil(max(need, 0) / step)
    while lo < hi:
        mid = (lo + hi) // 2
        if _import_pass(drops, at, mid * step) >= need:
            hi = mid
        else:
            lo = mid + 1
    return lo * step


def _raise_import(supply: dict, need) -> int:
    """What to raise a line's import to so a week brings `need`: the named
    level, replayed through the pass, for Smart Delivery; the week rounded up
    to SUPPLY_ROUND_TO for a plain order. A Smart Delivery line with no pass
    (a hand-built one) takes off what comes after the level."""
    if supply.get("smart") and supply.get("pass") and supply.get("levelAt") is not None:
        return _level_for(supply["pass"], supply["levelAt"], need)
    if supply.get("smart"):
        return _ceil_ten(max(0, need - supply.get("plainAfter", 0)))
    return _ceil_ten(need)


def _level_name(contracts: list, importer, order):
    """How the page names the contract holding a level: its importer, and,
    where that importer has several contracts on the line, which of them
    ("1 Pier, its 2nd of 2 contracts here").

    `contracts` is every contract on the line, paused and zero ones too, in
    delivery order, each with its `importer` and its `order` in
    importPartnerships; `order` names the one holding the level. Only that
    importer's own contracts are counted, from that one full list, so the
    Logistics and Plan pages give the same contract the same number.
    """
    if importer is None:
        return None
    own = [c["order"] for c in contracts if c["importer"] == importer]
    if len(own) < 2 or order not in own:
        return importer
    return msg("sb.py.levelName", "{importer}, its {nth} of {n} contracts here",
               importer=importer, nth=_ordinal_msg(own.index(order) + 1), n=len(own))


def _ordinal_msg(n: int) -> Msg:
    """1st, 2nd, 3rd, 4th ... 11th, 12th, 13th, 21st, as a message: the
    suffix is picked the English way, one key per suffix, so a translation
    writes its own ordinal ("2.") for each."""
    if 10 <= n % 100 <= 20:
        return msg("sb.py.ord.th", "{n}th", n=n)
    last = n % 10
    if last == 1:
        return msg("sb.py.ord.st", "{n}st", n=n)
    if last == 2:
        return msg("sb.py.ord.nd", "{n}nd", n=n)
    if last == 3:
        return msg("sb.py.ord.rd", "{n}rd", n=n)
    return msg("sb.py.ord.th", "{n}th", n=n)


def _smart_words(level, plain_after, plain_before=0):
    """A Smart Delivery setting in words, as the findings say it (a msg()). A
    plain amount delivered first that already reaches the level leaves the
    level nothing to bring, and says so."""
    said = dict(level=level, before=plain_before, after=plain_after)
    if plain_before and plain_before > level:
        if plain_after:
            return msg("f.smart.passes.plus", "Smart Delivery keeps {level:,} in stock, but the {before:,} a week "
                       "delivered before it already passes the {level:,} level, plus {after:,} a week on top", **said)
        return msg("f.smart.passes", "Smart Delivery keeps {level:,} in stock, but the {before:,} a week "
                   "delivered before it already passes the {level:,} level", **said)
    if plain_before and plain_before == level:
        if plain_after:
            return msg("f.smart.reaches.plus", "Smart Delivery keeps {level:,} in stock, but the {before:,} a week "
                       "delivered before it already reaches the {level:,} level, plus {after:,} a week on top", **said)
        return msg("f.smart.reaches", "Smart Delivery keeps {level:,} in stock, but the {before:,} a week "
                   "delivered before it already reaches the {level:,} level", **said)
    if plain_before:
        if plain_after:
            return msg("f.smart.counting.plus", "Smart Delivery keeps {level:,} in stock, counting the {before:,} a "
                       "week delivered before it, plus {after:,} a week on top", **said)
        return msg("f.smart.counting", "Smart Delivery keeps {level:,} in stock, counting the {before:,} a week "
                   "delivered before it", **said)
    if plain_after:
        return msg("f.smart.plus", "Smart Delivery keeps {level:,} in stock, plus {after:,} a week on top", **said)
    return msg("f.smart", "Smart Delivery keeps {level:,} in stock", **said)


def _import_drop(stock, drops):
    """Units one delivery day brings to one depot line, the game's way.

    DeliveryHelper walks the contracts in delivery order. A plain contract brings
    its amount. A Smart Delivery one (isTarget) brings what tops the depot up
    to its amount, max(0, amount - stock), and counts what an earlier contract
    delivered the same morning. So two Smart Delivery contracts on one item
    hold the larger of their two levels, not the sum. `drops` is in delivery
    order (_import_ranks).
    """
    brought = 0
    for drop in drops:
        if drop.get("smart"):
            brought += max(0, drop["amount"] - max(stock + brought, 0))
        else:
            brought += drop["amount"]
    return brought


def _scheduled_import_gap(stock, per_day, weekly, day, deliveries, left_today, rounds=False, added=None,
                          steady=None):
    """Project stock through the last upcoming drop, retaining each quantity.

    The maximum running deficit is the one-off amount that bridges every gap;
    a small early drop must not make a much larger later shipment arrive early.
    The last delivery day itself is excluded, as in _import_catch_up.

    A Smart Delivery drop brings only what tops the depot up to its level, so
    extra stock brought in now makes that drop smaller: the one-off amount is
    then the least that keeps every day of the walk above zero, found by search.

    With `rounds` the depot is emptied by a morning round, as in _deepest_use:
    each day's round leaves before that day's drop lands, so the walk charges
    the round first, and the last delivery day's round is part of it.
    `added` {day: units} is added to a day's draw, as in _deepest_use()'s
    `extra`; `steady` is its round-the-clock draw, charged after a day's
    drop has landed and not on the last delivery day.
    """
    added = added or {}
    drops = collections.defaultdict(list)
    for delivery in deliveries:
        if delivery["day"] >= day:
            drops[delivery["day"]].append(delivery)
    if len(drops) < 2:
        return None
    for same_day in drops.values():
        same_day.sort(key=lambda d: d.get("rank", 0))
    until = max(drops)
    last = until + 1 if rounds else until

    def walk(extra):
        remaining, elapsed, low = stock + extra, 0.0, 0.0
        cover = runs_out = None
        for when in range(day, last):
            if when in drops and not rounds:
                remaining += _import_drop(remaining, drops[when])
            share = left_today if when == day else 1.0
            use = (per_day * weekly[when % 7] + added.get(when, 0.0)) * share
            eat = _steady_on(steady, when - day, when < until)
            if not rounds:
                use, eat = use + eat, 0.0
            if use > remaining and cover is None:
                cover = elapsed + share * max(remaining, 0) / use if use else elapsed
                runs_out = when
            remaining -= use
            low = min(low, remaining)
            if when in drops and rounds:
                remaining += _import_drop(remaining, drops[when])
            if eat:
                # A round-fed site's own lines eat through the day, after
                # the morning's round and drop.
                if eat > remaining and cover is None:
                    cover = elapsed + share * max(remaining, 0) / eat
                    runs_out = when
                remaining -= eat
                low = min(low, remaining)
            elapsed += share
        return (cover if cover is not None else elapsed), runs_out, -low

    cover, runs_out, deficit = walk(0)
    catch_up = math.ceil(deficit)
    if deficit > 0 and any(d.get("smart") for same_day in drops.values() for d in same_day):
        # Enough to cover every day with no delivery at all always works,
        # counting no day's use below nothing.
        lo, hi = 0, math.ceil(sum(
            max(0.0, (per_day * weekly[when % 7] + added.get(when, 0.0)) * (left_today if when == day else 1.0))
            + _steady_on(steady, when - day, when < until)
            for when in range(day, last)
        ))
        while lo < hi:
            mid = (lo + hi) // 2
            if walk(mid)[1] is None:
                hi = mid
            else:
                lo = mid + 1
        catch_up = lo
    return {"until": until, "cover": cover,
            "runsOut": runs_out, "catchUp": catch_up}


def _coming_week(points: list, day: int) -> float | None:
    """The average day of the coming week on a straight line fitted through
    a young site's trading days ([[day, units], ...]), never below nothing;
    None with fewer than two days to draw a line through."""
    if len(points) < 2:
        return None
    xs = [p[0] for p in points]
    ys = [p[1] for p in points]
    mx, my = sum(xs) / len(xs), sum(ys) / len(ys)
    spread = sum((x - mx) ** 2 for x in xs)
    slope = sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / spread if spread else 0.0
    # Today to six days on: the middle of that week is three days ahead.
    return max(0.0, my + slope * (day + 3 - mx))


def _plan_dag(edges: dict, index: dict, supplied, uses=lambda _site, _item: False,
              surplus=lambda _site, _item: 0.0) -> dict:
    """The logistics plans with every loop cut the same way whatever order the
    sites are read in: {source: [(dest, item, target), ...]} as `edges`.

    Two sites can top each other up with the same item (a factory and the
    warehouse that feeds it, say). Goods going round a loop are no new need,
    so inside each strongly connected set of sites (per item) a plan counts
    only where it runs away from the supply and toward the use: from a site
    with a supply of its own (`supplied(site, item)`: an import, a wholesale
    delivery, a line making it) to one without; then from the site whose own
    supply leaves more over after its own use (`surplus(site, item)`) to the
    one short of it, so two importing depots topping each other up count the
    way the goods have to go; then from fewer hops from such a site to more; then from further from the use (a site using it
    itself, `uses(site, item)`, or sending it out of the loop) to nearer;
    then by the site key, so a tie always breaks the same way. A plan to an
    address not the company's is kept as it is.
    """
    by_item = collections.defaultdict(lambda: collections.defaultdict(set))
    for source, legs in edges.items():
        if source not in index:
            continue
        for dest, item, _target in legs:
            if dest in index and dest != source:
                by_item[item][source].add(dest)
    dropped = set()  # (source, dest, item)
    for item in _in_order(by_item):
        graph = by_item[item]
        # Tarjan's strongly connected components, iteratively.
        order, low, on, stack, comps, counter = {}, {}, set(), [], [], [0]
        nodes = _in_order(set(graph) | {d for ds in graph.values() for d in ds})
        for root in nodes:
            if root in order:
                continue
            work = [(root, iter(_in_order(graph.get(root, ()))))]
            order[root] = low[root] = counter[0]
            counter[0] += 1
            stack.append(root)
            on.add(root)
            while work:
                node, it = work[-1]
                advanced = False
                for nxt in it:
                    if nxt not in order:
                        order[nxt] = low[nxt] = counter[0]
                        counter[0] += 1
                        stack.append(nxt)
                        on.add(nxt)
                        work.append((nxt, iter(_in_order(graph.get(nxt, ())))))
                        advanced = True
                        break
                    if nxt in on:
                        low[node] = min(low[node], order[nxt])
                if advanced:
                    continue
                work.pop()
                if work:
                    low[work[-1][0]] = min(low[work[-1][0]], low[node])
                if low[node] == order[node]:
                    comp = []
                    while True:
                        top = stack.pop()
                        on.discard(top)
                        comp.append(top)
                        if top == node:
                            break
                    comps.append(comp)
        for comp in comps:
            if len(comp) < 2:
                continue
            members = set(comp)
            hops = {m: 0 for m in members if supplied(m, item)}
            frontier = list(_in_order(hops))
            while frontier:
                nxt_frontier = []
                for m in frontier:
                    for d in _in_order(graph.get(m, ())):
                        if d in members and d not in hops:
                            hops[d] = hops[m] + 1
                            nxt_frontier.append(d)
                frontier = nxt_frontier
            # How far each is from the use, walking the plans backwards.
            back = collections.defaultdict(set)
            for m in members:
                for d in graph.get(m, ()):
                    if d in members:
                        back[d].add(m)
            dist = {m: 0 for m in members
                    if uses(m, item) or any(d not in members for d in graph.get(m, ()))}
            frontier = list(_in_order(dist))
            while frontier:
                nxt_frontier = []
                for m in frontier:
                    for b in _in_order(back.get(m, ())):
                        if b not in dist:
                            dist[b] = dist[m] + 1
                            nxt_frontier.append(b)
                frontier = nxt_frontier
            rank = {m: (0 if supplied(m, item) else 1, -round(surplus(m, item), 6),
                        hops.get(m, len(members)), -dist.get(m, -1), m) for m in members}
            for m in members:
                for d in graph.get(m, ()):
                    if d in members and not rank[m] < rank[d]:
                        dropped.add((m, d, item))
    if not dropped:
        return edges
    return {source: [(d, i, t) for d, i, t in legs if (source, d, i) not in dropped]
            for source, legs in edges.items()}


def _share_out(total: float, weights: dict, caps: dict) -> dict:
    """`total` split between senders by `weights`; a sender whose part would
    pass its cap (a factory's capacity; None for no cap) is held to it and
    the rest goes to the others, again by weight, as long as any has room.
    Returns {sender: part}."""
    parts, left, active = {}, total, {s: w for s, w in weights.items() if w > 0}
    while active and left > 1e-9:
        whole = sum(active.values())
        over = {s for s, w in active.items()
                if caps.get(s) is not None and left * w / whole > caps[s] - parts.get(s, 0.0)}
        if not over:
            for s, w in active.items():
                parts[s] = parts.get(s, 0.0) + left * w / whole
            break
        for s in over:
            room = max(0.0, caps[s] - parts.get(s, 0.0))
            parts[s] = parts.get(s, 0.0) + room
            left -= room
            del active[s]
    return parts


def _share_with_room(total: float, weights: dict, caps: dict, own: float = 0.0) -> dict:
    """`total` split between senders by `weights`, a sender held to its cap
    (caps: sender -> most it can take; absent for no cap) handing the rest to
    those with room (_share_out()). The routes come first: what none has room
    for is the site's `own` supply's (its import or wholesale delivery) to
    bring, as far as it goes, and what is left beyond that stays where the
    weights put it, so the sender that cannot bring it is still the one
    asked. Returns {sender: part}. The one routine the chain's walk and Demand
    sizing both share a site's need out with."""
    parts = _share_out(total, weights, caps)
    left = max(0.0, total - sum(parts.values()) - own)
    whole = sum(w for w in weights.values() if w > 0)
    if left > 1e-9 and whole:
        for sender, w in weights.items():
            if w > 0:
                parts[sender] = parts.get(sender, 0.0) + left * w / whole
    return parts


HAND_ON_PASSES = 50  # the most passes a hand-on is solved in


def _pooled_level(room: float, wants: list) -> float | None:
    """The level a sender's room fills its shares up to, water-filling: at
    each site it tops up beside others it takes what it would be given there
    (`desired`, what is left once the others with room have theirs, never
    past the route's target) or `level` times its weighted share there,
    whichever is less, and the level is set so that together that is its
    `room`. Room a site does not use goes to the sites that need it. `wants`
    [(share, desired)]; None where its room holds all it would be given."""
    if sum(desired for _share, desired in wants) <= room:
        return None
    room = max(0.0, room)
    left, level = room, 0.0
    # Sites by the level at which they stop drawing on it.
    open_sites = sorted((desired / share, share, desired) for share, desired in wants if share > 0)
    weight = sum(share for _stop, share, _desired in open_sites)
    for stop, share, desired in open_sites:
        if weight <= 0 or left <= stop * weight - level * weight:
            break
        left -= (stop - level) * weight
        level = stop
        weight -= share
    return level + (left / weight if weight > 0 else 0.0)


def _held_levels(sites: dict, limits: dict, fixed: dict, route_caps: dict | None = None) -> dict:
    """How far each sender with a known supply holds its shares down at the
    sites it tops up beside other senders, the one allocation the chain's
    walk and Demand sizing both share a site's need out with. `sites`
    {site: (need, {sender: weight}, own)}: what the site needs, how its
    senders split it by target, and what its own supply brings (its import:
    the routes come first, and it brings what their room leaves, so a site
    with one sender and an import of its own counts as shared); `limits` {sender: what it
    can send a day, or None where unknown}; `fixed` {sender: what it is asked
    where it is the only sender, and its own use}, which comes first, as no
    one else can bring it; `route_caps` {(sender, site): the most its round
    brings there}. What is left of a sender's limit fills
    its shares by _pooled_level(); what it cannot bring goes to the others
    with room (_share_with_room()). Solved by passes over the senders until
    no level moves. Returns {sender: level}: its part at a site is at most
    level x residual x weight."""
    route_caps = route_caps or {}
    shared = {site: (residual, {s: w for s, w in weights.items() if w > 0})
              for site, (residual, weights, own) in sites.items()
              if residual > 0 and (own > 0 or sum(1 for w in weights.values() if w > 0) > 1)}
    by_sender = collections.defaultdict(list)
    for site, (_residual, weights) in shared.items():
        for sender in weights:
            if limits.get(sender) is not None:
                by_sender[sender].append(site)
    levels = {}
    for _pass in range(HAND_ON_PASSES):
        moved = False
        for sender in _in_order(by_sender):
            wants = []
            for site in by_sender[sender]:
                residual, weights = shared[site]
                whole = sum(weights.values())
                caps = {s: levels[s] * residual * w / whole for s, w in weights.items()
                        if s != sender and s in levels}
                desired = _share_with_room(residual, weights, caps).get(sender, 0.0)
                if (sender, site) in route_caps:
                    desired = min(desired, route_caps[(sender, site)])
                wants.append((residual * weights[sender] / whole, desired))
            level = _pooled_level(limits[sender] - fixed.get(sender, 0.0), wants)
            was = levels.get(sender)
            if level is None:
                if was is not None:
                    del levels[sender]
                    moved = True
            elif was is None or abs(level - was) > 1e-6 * max(1.0, was):
                levels[sender] = level
                moved = True
        if not moved:
            break
    return levels



def _supply_walk(index: dict, edges: dict, leaves: dict, eats: dict, steady: dict,
                 drops: dict, unknown: set) -> dict:
    """The goods' flow worked out from the sources, never from the delivery log.

    Need flows up the logistics plans from the ends; supply flows down from
    the imports and the factories. Every figure is a day's.

    `leaves` {(site, item): (use, need)} is what a shop sells a day (its
    week's sales, `need` with SUPPLY_MARGIN on top: the one place the margin
    is added), or its top-up target where it has sold none yet. A plan to an
    address not the company's (an export) is no leaf: it takes the surplus.
    `eats` {(site, item): (use, need)} is what the factory lines there draw,
    in the sizing mode at hand. `steady` {(site, item): units} is what arrives
    whatever the stock: a wholesale delivery's week, a factory line's output
    in the sizing mode at hand. `drops` {(site, item): [drop, ...]} are an
    import line's active contracts in delivery order, replayed through
    _import_drop() against the stock the routes into the site keep there: a
    Smart Delivery level at or under a route's target brings nothing, a plain
    amount always its amount. `unknown` holds the (site, item) pairs a site
    whose lines the board cannot read (a recipe it cannot name) holds: what
    it sends of those is taken as made there.

    Loops in the plans are cut first (_plan_dag()), the same way whatever the
    order the sites are read in.

    A site's need is its own (`lines`, what its factory lines draw; `sites`,
    what its shelves sell) plus, for every plan that tops another site up,
    that site's need beyond what its own supply brings, split between the
    sites topping it up by their targets (among those with anything coming
    in, where any has). No second margin is added on the way up.

    A route brings what the site it tops up needs of it, never more than its
    target a day (a morning round tops the line up to the target), and no
    more than the sender can spare. Two routes into one line do not add up:
    each round tops the line up to its own target, so the second finds the
    first's stock there and the line never holds more than the highest
    target; together they bring no more than that a day. What a sender can
    spare is its own supply and what routes bring it, less its own use,
    shared between its routes by what they ask; what they could bring with
    the imports beside them set aside (`potential`) is shared the same way,
    so a sender's output is never counted twice. What the sender merely holds
    is no supply: stock runs out, a standing order does not. A site the board
    cannot read is taken to bring what is asked.

    Returns {(site, item): node} with `use`, `need`, `lines` and `sites`
    ((use, need) each), `own` (what its own supply brings a day), `credit`
    (what the routes into it bring a day, capped by their targets),
    `supplied` (the same without the targets' cap: what the senders could
    send), `potential` (what the routes alone could bring, the import aside),
    `covered` (they bring all it uses), `inbound` (a route from a site of
    yours tops it up), `targets` (the highest target of a sender with anything
    coming in), `reach` (the highest of all their targets), `senders` (their
    site keys), `passing` (those with nothing coming in, which only pass on
    what they hold), `demand` {sender: (use, need)}, what it asks of each,
    and `asked` {site: (use, need)}, what each site it tops up asks of it.
    """
    def supplied(site, item):
        n = (site, item)
        return bool(drops.get(n) or steady.get(n) or n in unknown)

    def surplus(site, item):
        n = (site, item)
        brought = _import_drop(0, drops[n]) / 7 if drops.get(n) else 0.0
        return brought + steady.get(n, 0.0) - eats.get(n, (0.0, 0.0))[1] - leaves.get(n, (0.0, 0.0))[1]

    edges = _plan_dag(edges, index, supplied,
                      lambda site, item: (site, item) in leaves or (site, item) in eats, surplus)
    senders = collections.defaultdict(list)  # (dest, item) -> [(source, target)]
    for source, legs in edges.items():
        if source not in index:
            continue
        for dest, item, target in legs:
            if dest in index and dest != source:
                senders[(dest, item)].append((source, target or 0))
    # Frozen once built, as every table below that the closures read by key:
    # a read of a missing key adds nothing while another walk iterates it.
    senders = dict(senders)
    nodes = set(leaves) | set(eats) | set(steady) | set(drops) | set(senders)
    nodes |= {(s, item) for (_d, item), legs in senders.items() for s, _t in legs}

    def capable(sender, item):
        """Whether `sender` has anything coming in to send on: an import, a
        wholesale delivery, a line making it, a route bringing it, or lines
        the board cannot read. What it merely holds does not count."""
        return bool(supplied(sender, item) or senders.get((sender, item)))

    def reach(n):
        """The most the routes into `n` keep there: the highest target of a
        sender with anything coming in."""
        return max((t for s, t in senders.get(n, ()) if capable(s, n[1])), default=0)

    def own(n):
        brought = _import_drop(reach(n), drops[n]) / 7 if drops.get(n) else 0.0
        return brought + steady.get(n, 0.0)

    def shares(n):
        """How `n`'s need beyond its own supply is split between the sites
        topping it up: by their targets, among those with anything coming in
        (one that only holds stock brings nothing for long), or among all of
        them where none has."""
        legs = senders.get(n, ())
        able = [(s, t) for s, t in legs if capable(s, n[1])] or legs
        total = sum(t for _s, t in able)
        weight = collections.defaultdict(float)
        for s, t in able:
            weight[s] += t / total if total else 1 / len(able)
        return dict(weight)

    need_memo, asked = {}, {}  # asked[sender node][dest] = (use, need)
    asked_raw = {}  # the same before the route's target caps it
    route_cap = {}
    for source, legs in edges.items():
        for dest, item, target in legs:
            route_cap[(source, dest, item)] = max(route_cap.get((source, dest, item), 0), target or 0)

    # How far each sender's share of a site's need is held down because it
    # cannot supply all it is asked across its routes: {sender node: k}.
    # 1 until the first pass below finds a sender asked for more than it has.
    scale = {}

    def portion(d, need):
        """How `d`'s need is split between its senders, as a share of it: by
        their targets (shares()), except that a sender asked for more than it
        has in all (`scale`) is held to its part of what it has, the rest
        going to the others with room, then to the site's own supply (its
        import or wholesale delivery: the routes come first), and only what
        none of them brings back to the senders (_share_with_room())."""
        weights = shares(d)
        caps = {s: scale[(s, d[1])] * need * w for s, w in weights.items()
                if (s, d[1]) in scale}
        if need <= 0:
            return weights
        parts = _share_with_room(need, weights, caps, own(d))
        return {s: part / need for s, part in parts.items()}

    portions, residual_at = {}, {}

    def total(n, seen=frozenset()):
        """(lines use, lines need, sites use, sites need) a day at `n`."""
        if n in need_memo:
            return need_memo[n]
        if n in seen:  # the plans are a DAG once cut; this is only a guard
            return (0.0, 0.0, 0.0, 0.0)
        key, item = n
        lu, ln = eats.get(n, (0.0, 0.0))
        su, sn = leaves.get(n, (0.0, 0.0))
        for dest in _in_order({d for d, it, _t in edges.get(key, ()) if it == item}):
            d = (dest, item)
            if dest == key or dest not in index or key not in index:
                continue
            dlu, dln, dsu, dsn = total(d, seen | {n})
            dneed = dln + dsn
            if dneed <= 0:
                continue
            if d not in portions:
                residual_at[d] = dneed
                portions[d] = portion(d, dneed)
            f = portions[d].get(key, 0.0)
            asked_raw.setdefault(n, {})[dest] = dneed * f
            # A round a day brings no more than the route's target. Where the
            # site has a supply of its own, what it needs beyond the target is
            # that supply's to bring, and is not asked of this one as well
            # (the top-up finding says to raise the target instead). A shop
            # or a depot with nothing else is asked for all of it: raising
            # the target then needs the supply behind it.
            cap = route_cap.get((key, dest, item), 0)
            if dneed * f > cap > 0 and supplied(dest, item):
                f *= cap / (dneed * f)
            asked.setdefault(n, {})[dest] = ((dlu + dsu) * f, dneed * f)
            lu, ln, su, sn = lu + dlu * f, ln + dln * f, su + dsu * f, sn + dsn * f
        need_memo[n] = (lu, ln, su, sn)
        return need_memo[n]

    def alone(d):
        """Whether `d` is a site its one sender alone tops up, with no supply
        of its own: its sender answers for it first (_held_levels() `fixed`)."""
        return own(d) <= 0 and sum(1 for w in shares(d).values() if w > 0) <= 1

    def has(sender_node, memo=None, seen=frozenset()):
        """What a sender can send a day at most: its own supply, plus what
        the routes into it can bring, never past the route's target and
        together never past the highest target, less its own use. A sender
        topping it up brings its own throughput less what the other sites
        only it tops up take (they come first, as in _held_levels(); where
        they and this one together ask for more than it has, they share it
        by what they ask); where this one is a site it shares with other
        senders (or one with a supply of its own), it brings no more than
        its part here as the last pass allocated it, the sender's split
        solved first. None where it is, or draws on, a line the board cannot
        read. `memo` is a pass's."""
        memo = {} if memo is None else memo
        if sender_node in memo:
            return memo[sender_node]
        if sender_node in unknown or sender_node in seen:
            return None
        key, item = sender_node
        own_need = eats.get(sender_node, (0.0, 0.0))[1] + leaves.get(sender_node, (0.0, 0.0))[1]
        inbound = 0.0
        for source in _in_order({s for s, _t in senders.get(sender_node, ())}):
            if not capable(source, item):
                continue
            there = has((source, item), memo, seen | {sender_node})
            if there is None:
                memo[sender_node] = None
                return None
            first = {dest: a[1] for dest, a in asked.get((source, item), {}).items() if alone((dest, item))}
            other = sum(need for dest, need in first.items() if dest != key)
            mine = first.get(key, 0.0)
            if key in first and other + mine > there > 0:
                bring = there * mine / (other + mine)
            else:
                bring = max(0.0, there - other)
                if key not in first and (source, item) in scale and (key, item) in residual_at:
                    # Its part as allocated: its level of its share here,
                    # not what is left with it when no one else brings it.
                    bring = min(bring, scale[(source, item)] * residual_at[(key, item)]
                                * shares((key, item)).get(source, 0.0))
            target = route_cap.get((source, key, item), 0)
            inbound += min(bring, target) if target > 0 else bring
        if senders.get(sender_node):
            inbound = min(inbound, reach(sender_node))
        memo[sender_node] = max(0.0, own(sender_node) + inbound - own_need)
        return memo[sender_node]

    # A sender asked for more than it has, across all its routes, hands the
    # rest to the other senders of the sites it tops up, as far as they have
    # room (_held_levels(), the allocation Demand sizing shares out by too).
    # A pass can change what the sites further up are asked, so passes run
    # until no sender's level moves; a sender that is the only one topping
    # its sites up has no one to hand to and never holds anything down.
    # HAND_ON_PASSES only bounds it.
    last_limits = {}
    for _pass in range(HAND_ON_PASSES):
        for n in _in_order(nodes):
            total(n)
        sites, limits, fixed, caps_at = {}, {}, collections.defaultdict(float), {}
        through = {}
        for d, need in residual_at.items():
            sites[d] = (need, {(s, d[1]): w for s, w in shares(d).items()}, own(d))
        for n in _in_order(asked):
            limits[n] = has(n, through)
            if senders.get(n) and limits[n] is not None and n in last_limits:
                # A routed sender's limit follows its senders' split, which
                # follows what it is asked: halfway each pass, so the two
                # settle rather than swing round each other.
                limits[n] = (limits[n] + last_limits[n]) / 2
            for dest, (_use, need) in asked[n].items():
                d = (dest, n[1])
                if own(d) > 0 or sum(1 for w in shares(d).values() if w > 0) > 1:
                    cap = route_cap.get((n[0], dest, n[1]), 0)
                    if cap > 0 and supplied(dest, n[1]):
                        caps_at[(n, d)] = cap
                else:
                    fixed[n] += need
        levels = _held_levels(sites, limits, fixed, caps_at)
        # A routed sender's damped limit still moving is a change too: it may
        # hold no level yet while its limit is still coming down to its ask.
        moved = any(n in last_limits and abs(v - last_limits[n]) > 1e-6 * max(1.0, v)
                    for n, v in limits.items() if v is not None and senders.get(n))
        last_limits = {n: v for n, v in limits.items() if v is not None}
        changed = moved or levels.keys() != scale.keys() or any(
            abs(levels[n] - scale[n]) > 1e-6 * max(1.0, scale[n]) for n in levels)
        scale.clear()
        scale.update(levels)
        if not changed:
            break
        need_memo.clear()
        asked.clear()
        asked_raw.clear()
        portions.clear()
    # How many passes the last walk took, for the tests to hold it to. A walk
    # that used every one of HAND_ON_PASSES stopped before it settled (a
    # damped limit or a level still moving): its figures are the last pass's,
    # and `capped` says so for debugging; the tests hold the synthetic chains
    # well inside the bound.
    _supply_walk.passes = _pass + 1
    _supply_walk.capped = _pass + 1 == HAND_ON_PASSES and changed
    for n in _in_order(nodes):
        total(n)

    spare_memo, out_memo = {}, {}

    def spare(n, seen=frozenset()):
        """What `n` can send on a day: its own supply and what routes bring
        it, less what it uses itself. None where it is a site the board
        cannot read and nothing known brings it: taken to make it."""
        if n in spare_memo:
            return spare_memo[n]
        if n in seen:
            return 0.0
        key, item = n
        inbound = min(reach(n), sum(sends(s, item, seen | {n}).get(key, (0.0, 0.0, 0.0))[0]
                                    for s in {s for s, _t in senders.get(n, ())}))
        _lu, ln = eats.get(n, (0.0, 0.0))
        _su, sn = leaves.get(n, (0.0, 0.0))
        if n in unknown and not own(n) and not inbound:
            spare_memo[n] = None
        else:
            spare_memo[n] = own(n) + inbound - ln - sn
        return spare_memo[n]

    def sends(source, item, seen=frozenset()):
        """{dest: (credit, supplied, potential)} a day on every route from
        `source` of `item`, out of one budget, its spare: first what each
        asks (its need beyond its own supply), then what is left over, shared
        by what each still lacks of its whole need, for what the routes alone
        could bring (an import beside them then a backup). Never more in all
        than the sender has."""
        s_node = (source, item)
        if s_node in out_memo:
            return out_memo[s_node]
        legs = collections.defaultdict(int)
        for dest, it, target in edges.get(source, ()):
            if it == item and dest in index and dest != source:
                legs[dest] = max(legs[dest], target or 0)
        want = {d: asked.get(s_node, {}).get(d, (0.0, 0.0))[1] for d in legs}
        raw = {d: asked_raw.get(s_node, {}).get(d, 0.0) for d in legs}
        whole = {d: (total((d, item))[1] + total((d, item))[3])
                    * portions.get((d, item), shares((d, item))).get(source, 0.0)
                 for d in legs}
        have = spare(s_node, seen)
        result = {}
        if have is None:
            for d, target in legs.items():
                result[d] = (min(target, want[d]), raw[d], min(target, whole[d]))
        else:
            have = max(0.0, have)
            asks = sum(want.values())
            ratio = 1.0 if asks <= 0 else min(1.0, have / asks)
            credit = {d: min(target, want[d] * ratio) for d, target in legs.items()}
            left = max(0.0, have - sum(credit.values()))
            lack = {d: max(0.0, min(legs[d], whole[d]) - credit[d]) for d in legs}
            lacking = sum(lack.values())
            extra = 1.0 if lacking <= 0 else min(1.0, left / lacking)
            # What the sender could send with no target in the way: whether
            # its supply, not the route's target, is what falls short.
            raws = sum(raw.values())
            could = 1.0 if raws <= 0 else min(1.0, have / raws)
            for d in legs:
                result[d] = (credit[d], raw[d] * could, credit[d] + lack[d] * extra)
        if not seen or s_node not in seen:
            out_memo[s_node] = result
        return result

    out = {}
    for n in _in_order(nodes):
        lu, ln, su, sn = total(n)
        legs = senders.get(n, ())
        from_each = {s: sends(s, n[1]).get(n[0], (0.0, 0.0, 0.0)) for s in _in_order({s for s, _t in legs})}
        got = list(from_each.values())
        use = lu + su
        top = reach(n)
        potential = min(top, sum(g[2] for g in got))
        covered = bool(legs) and use > 0 and potential >= use * (1 - FIT_TIGHT)
        brings = min(top, sum(g[0] for g in got))
        if covered:
            # The routes could bring all of it: the import beside them is a
            # backup, and the routes are what brings the week.
            brings = max(brings, min(potential, ln + sn))
        out[n] = {
            "use": use, "need": ln + sn, "lines": (lu, ln), "sites": (su, sn),
            "own": own(n),
            "credit": brings,
            "supplied": sum(g[1] for g in got),
            # What each sender has room to send this line a day: its spare
            # less what its other routes ask of it (None: a site the board
            # cannot read, taken to send what is asked).
            "room": {s: (None if spare((s, n[1])) is None else max(0.0, spare((s, n[1])) - sum(
                         a[1] for d, a in asked.get((s, n[1]), {}).items() if d != n[0])))
                     for s in _in_order({s for s, _t in legs})},
            "potential": potential,
            "covered": covered,
            "inbound": bool(legs),
            "targets": top,
            "reach": max((t for _s, t in legs), default=0),
            # Each sender's own target into it: what its round brings at most.
            "routeTargets": {s: max(t for s2, t in legs if s2 == s) for s, _t in legs},
            "senders": _in_order({s for s, _t in legs}),
            "passing": _in_order({s for s, _t in legs if not capable(s, n[1])}),
            "demand": {s: asked.get((s, n[1]), {}).get(n[0], (0.0, 0.0)) for s, _t in legs},
            # What each sender's round brings it a day out of its budget.
            "brings": {s: g[0] for s, g in from_each.items()},
            "asked": dict(asked.get(n, {})),
        }
    return out


def _supply(
    save: Save,
    names: Names,
    businesses: list,
    day: int,
    rhythm: dict,
    recipes: dict | None = None,
    history: "History | None" = None,
    character: str = "default",
) -> dict:
    """How the goods actually move: a daily top-up round, and a weekly import.

    The logistics manager refills every shop to a per-item target each morning,
    so a shop only runs dry if it sells more in a day than that target. Imports
    land once a week, so a warehouse only runs dry if its holding cannot cover
    the daily draw until the next delivery. Those are the two questions worth
    asking, plus: what is piling up and never moving?
    """
    index = {b["key"]: i for i, b in enumerate(businesses)}
    # What each shelf sells a trading day (_business); a hand-built business
    # without it sells at its calendar rate.
    sold = {b["key"]: {l["slug"]: l.get("tradeRate", l["rate"]) for l in b["lines"]}
            for b in businesses}
    held = {b["key"]: {l["slug"]: l["units"] for l in b["lines"]} for b in businesses}
    # What each shelf sells a week, as a day: the trading-day rate over the
    # days the shop traded in the last week (_business's weekSold). Every
    # weekly figure reads this; a daily top-up reads the trading-day rate.
    sold_week = {b["key"]: {l["slug"]: _week_sold(b, l) / 7 for l in b["lines"]} for b in businesses}

    # Most of today is already spent. A save taken at 23:00 on a Saturday has one
    # hour of Saturday's selling left in it, not a whole day of it, and charging
    # the full day would report a warehouse running dry that is in fact fine.
    # Everything that walks forward from now starts with this fraction.
    left_today = max(0.0, (24 - save.root["Hour"] - int(save.root["Minute"]) / 60) / 24)
    spent_today = 1 - left_today

    # A flat daily average under-provisions a Saturday and over-provisions a
    # Wednesday, so every consumption figure below is read through the weekday
    # profile of the site doing the consuming.
    chain_beat = rhythm.get("customers") or rhythm.get("revenue")

    def beat(business: dict) -> dict:
        profile = business.get("rhythm") or chain_beat
        if not profile:
            return {wd: 1.0 for wd in range(7)}
        by_name = {p["day"]: p["index"] / 100 for p in profile}
        return {wd: by_name.get(WEEKDAYS[wd], 1.0) for wd in range(7)}

    def peak_of(business: dict):
        profile = business.get("rhythm") or chain_beat
        if not profile:
            return 1.0, None
        top = max(profile, key=lambda p: p["index"])
        return top["index"] / 100, top["day"]

    # The distribution graph: factory -> warehouse -> shop, with a stock target
    # on every edge.
    edges = collections.defaultdict(list)
    target_at = {}
    for plan in save.items(save.root["logisticsManagerPlans"]):
        source = site_key(save.address(plan["targetAddress"]))
        for dest in save.items(plan["destinations"]):
            dest_key = site_key(save.address(dest["deliveryTargetAddress"]))
            for target in save.items(dest["stockTargets"]):
                item, amount = target["itemName"], target["targetAmount"]
                edges[source].append((dest_key, item, amount))
                target_at.setdefault((dest_key, item), []).append((amount, source))
    edges = dict(edges)  # read by key from here on; its values are lists, so one level is all
    # Where several plans top one line up, the one that counts is the highest
    # target of a site that has the item to send (it holds some, imports it,
    # is routed it, or is a factory that may make it); failing any, the
    # highest of all. Ties go to the site key, so plan order never decides.
    imported = {(site_key(save.address(product.get("assignedWarehouse"))), product.get("itemName"))
                for partnership in save.items(save.root["importPartnerships"])
                if partnership.get("isActive")
                for product in save.items(partnership.get("products")) if product.get("amount")}
    routed_to = {(d, i) for legs in edges.values() for d, i, _a in legs}
    held_here = {(b["key"], line["slug"]) for b in businesses for line in b["lines"] if line["units"] > 0}
    # What a factory's machines make, as far as the recipe table names them:
    # a factory is a sender of that, not of everything (a line the table
    # cannot name makes at most what the factory holds, counted above).
    makes_here = set()
    for building in save.items(save.root["BuildingRegistrations"]):
        if not building.get("RentedByPlayer"):
            continue
        for machine in _item_instances(save, building.get("itemInstances")):
            if machine.get("workstationType") and RECIPE_ITEMS.get(machine.get("selectedRecipeId")):
                makes_here.add((site_key(_address_of(building, strict=True)),
                                RECIPE_ITEMS[machine["selectedRecipeId"]]))

    def has_it(source, item):
        return ((source, item) in imported or (source, item) in routed_to
                or (source, item) in held_here or (source, item) in makes_here)

    for line, offers in list(target_at.items()):
        able = [o for o in offers if has_it(o[1], line[1])] or offers
        target_at[line] = max(able, key=lambda o: (o[0], str(o[1])))

    # A shop can also be fed by a wholesale store: a repeating delivery
    # contract (DeliveryContracts) brings `amount` of each item on its
    # delivery day, once a week. A one-off or urgent order, or a disabled
    # contract, is no standing supply. {(shop key, item): {weekly, day, days}}:
    # what a week brings, the weekday it lands and the days from now to it.
    wholesale = {}
    for contract in save.items(save.root.get("DeliveryContracts")):
        if not contract.get("enabled") or not contract.get("repeatingOrder") or contract.get("isUrgentOrder"):
            continue
        shop = site_key(save.address(contract.get("businessAddress")))
        if shop not in index:
            continue
        due = contract.get("nextDeliveryDay")
        for entry in save.items(contract.get("items")):
            item, amount = entry.get("itemName"), entry.get("amount") or 0
            if not item or amount <= 0:
                continue
            deal = wholesale.setdefault((shop, item), {"weekly": 0, "day": None, "days": None})
            deal["weekly"] += amount
            if isinstance(due, int) and (deal["days"] is None or due - day - spent_today < deal["days"]):
                deal["day"] = WEEKDAYS[due % 7]
                deal["days"] = round(max(0.0, due - day - spent_today), 2)

    # The ends of the chain, a day of each: what a shop sells over its week,
    # with the margin on top (the one place it is added), or, for a line it
    # has not sold yet but is topped up to a target for, that target. The
    # need further up is the sum of these, never read off the delivery log.
    leaves = {}
    for business in businesses:
        # A factory's or a depot's own "sales" are the goods its rounds take
        # away, which the plans already count: only a shop's are an end.
        if business["status"] != "retail" or business.get("closed"):
            continue  # a shop shut with the game's switch needs nothing either
        key = business["key"]
        for slug, per_day in sold_week.get(key, {}).items():
            if per_day > 0:
                leaves[(key, slug)] = (per_day, per_day * (1 + SUPPLY_MARGIN))
    # A target stands in for sales only where the line has none yet: a shop
    # under a week of trading, or a line it has never held. A shop that has
    # traded for weeks with the line at its target and nothing sold needs
    # nothing; nor does one shut with the game's temporarily closed switch.
    stocked = {(b["key"], line["slug"]) for b in businesses for line in b["lines"]
               if line["units"] > 0 or line.get("weekSold", 0) > 0}
    for (dest, item), (amount, _source) in target_at.items():
        if not (dest in index and amount > 0 and (dest, item) not in leaves):
            continue
        shop = businesses[index[dest]]
        if shop["status"] != "retail" or shop.get("closed"):
            continue
        if shop.get("tradeDays", 0) < NEW_SITE_DAYS or (dest, item) not in stocked:
            leaves[(dest, item)] = (float(amount), float(amount))
    # A plan to an address not the company's (a pier, to export) takes what
    # is left once the company's own sites are served: it is no need to size
    # a supply on, and asks nothing of a sender the walk has to share.

    drawn = {}

    def draw(key: str, item: str, seen: frozenset = frozenset()) -> float:
        """Units of `item` leaving this site per day, following the chain down:
        what the ends sell (_supply's leaves), not what the log saw leave."""
        if key not in index or key in seen:
            return 0.0  # a pier or someone else's address: its source counts it
        if (key, item) in drawn:
            return drawn[(key, item)]
        total = leaves.get((key, item), (0.0, 0.0))[0]
        for dest_key, dest_item, _ in edges.get(key, []):
            if dest_item == item:
                total += draw(dest_key, item, seen | {key})
        drawn[(key, item)] = total
        return total

    def customer_driven(key: str, item: str, seen: frozenset = frozenset()) -> bool:
        """Whether this holding ends up on a shop floor.

        A shelf follows the week's rhythm; a machine fed to a target every
        morning takes the same amount on a Saturday as on a Tuesday.
        """
        if key not in index or key in seen:
            return False
        if businesses[index[key]]["status"] == "retail":
            return True
        return any(
            customer_driven(dest_key, item, seen | {key})
            for dest_key, dest_item, _ in edges.get(key, [])
            if dest_item == item
        )

    # The game's own delivery log. A negative amount is a logistics round
    # leaving, a positive one an import or a factory run arriving. It keeps
    # only a site's last sixty transactions, under three days at a busy
    # depot, so it sizes nothing here: no need, no route's share, no import
    # and no shortfall is read off it (_supply_walk() works those out from
    # the plans). What still reads it describes what happened: whether a
    # factory's inputs arrived and what its lines shipped (_factories), a
    # first fill, whether today's round has left, the weekdays rounds run
    # on, and a depot line nothing else draws on (idle stock).
    shipped = collections.defaultdict(lambda: collections.defaultdict(float))
    received = collections.defaultdict(lambda: collections.defaultdict(float))
    by_day = collections.defaultdict(lambda: collections.defaultdict(lambda: collections.defaultdict(float)))
    # What left a site and what reached it, day by day and gross: a factory's
    # forwarding apart from what reached it the same day.
    out_by_day = collections.defaultdict(lambda: collections.defaultdict(lambda: collections.defaultdict(float)))
    in_by_day = collections.defaultdict(lambda: collections.defaultdict(lambda: collections.defaultdict(float)))
    round_days = collections.defaultdict(set)
    inbound_days = collections.defaultdict(set)
    first_logged = {}  # the oldest day a site's log still holds
    first_seen = {}  # (site, item) -> the oldest day its whole log names the item
    log_full = set()  # sites whose log is at its sixty, so its oldest day is partial
    rounds_today = set()  # (site, item) whose round has already left today
    for building in save.items(save.root["BuildingRegistrations"]):
        if not building.get("RentedByPlayer"):
            continue
        key = site_key(_address_of(building, strict=True))
        if len(save.items(building.get("deliveryTransactions"))) >= DELIVERY_LOG_SIZE:
            log_full.add(key)
        for transaction in save.items(building.get("deliveryTransactions")):
            when = transaction.get("dayOfDelivery")
            if when is not None:
                first_logged[key] = min(first_logged.get(key, when), when)
                for entry in save.items(transaction.get("deliveryItems")):
                    if entry.get("itemName") and entry.get("amountDelivered", 0):
                        seen_at = (key, entry["itemName"])
                        first_seen[seen_at] = min(first_seen.get(seen_at, when), when)
            if when == day:
                rounds_today.update(
                    (key, entry["itemName"])
                    for entry in save.items(transaction.get("deliveryItems"))
                    if entry.get("itemName") and entry.get("amountDelivered", 0) < 0
                )
            # Today's round may still be on the road; yesterday's is complete.
            if when is None or when >= day or when < day - SHIPPED_WINDOW:
                continue
            for entry in save.items(transaction.get("deliveryItems")):
                amount = entry.get("amountDelivered", 0)
                if not entry.get("itemName"):
                    continue
                if amount < 0:
                    shipped[key][entry["itemName"]] -= amount
                    out_by_day[key][entry["itemName"]][when] -= amount
                    round_days[key].add(when)
                elif amount > 0:
                    received[key][entry["itemName"]] += amount
                    in_by_day[key][entry["itemName"]][when] += amount
                    inbound_days[key].add(when)
                by_day[key][entry["itemName"]][when] += amount
    # Read by key from here on, by _factories() too (_frozen()).
    shipped, received, by_day = _frozen(shipped), _frozen(received), _frozen(by_day)
    out_by_day, in_by_day = _frozen(out_by_day), _frozen(in_by_day)
    round_days, inbound_days = _frozen(round_days), _frozen(inbound_days)

    def first_fill(dest: str, item: str) -> tuple:
        """A site's first fill of `item` inside the window, as (day, one-off
        units), else (None, 0). The one rule for both uses: the first day the
        site's whole log names the item, when that falls in the window, unless
        the log is full (sixty entries) and starts that very day, so older
        entries may have been cut. The one-off part is what that day brought
        beyond the largest round after it: a new target's fill to its level
        is no draw, the rounds that follow are."""
        first = first_seen.get((dest, item))
        if first is None or first < day - SHIPPED_WINDOW or first >= day:
            return None, 0.0
        if dest in log_full and first_logged.get(dest, first) >= first:
            return None, 0.0
        arrived = in_by_day.get(dest, {}).get(item, {})
        later = max((units for d, units in arrived.items() if d > first), default=0.0)
        return first, max(0.0, arrived.get(first, 0.0) - later)

    def shipped_per_day(key: str, item: str) -> float | None:
        """Measured daily outflow, or None when too few rounds are on record.
        The one-off part of a first fill of a site on a plan from here (a new
        target's first round, first_fill()) is no draw, and comes off the day
        it left."""
        days = round_days.get(key, ())
        if len(days) < SHIPPED_MIN_DAYS:
            return None
        total = shipped.get(key, {}).get(item, 0.0)
        for dest in {d for d, i, _a in edges.get(key, []) if i == item and d != key}:
            when, units = first_fill(dest, item)
            if when is not None:
                total -= min(units, out_by_day.get(key, {}).get(item, {}).get(when, 0.0))
        return max(0.0, total) / len(days)

    def received_per_day(key: str, item: str) -> float | None:
        """Measured daily inflow, or None when too few rounds are on record."""
        days = inbound_days.get(key, ())
        if len(days) < SHIPPED_MIN_DAYS:
            return None
        return received.get(key, {}).get(item, 0.0) / len(days)

    def forwarded_per_day(key: str, item: str) -> float:
        """What a site sent on of an item, over the same days as its inflow:
        a factory passing an import to a depot target did not eat it."""
        days = inbound_days.get(key, ())
        return shipped.get(key, {}).get(item, 0.0) / len(days) if days else 0.0

    # --- imports: what lands weekly, and when
    # A contract is plain or Smart Delivery (isTarget; the save leaves out a
    # false one). Plain brings its amount every Monday. Smart Delivery's amount
    # is a stock level: the purchasing agent brings what tops the depot up to
    # it, so a week can use at most that level. `weekly` is therefore what one
    # delivery brings into an empty depot, the most a week can draw on: the
    # sum of plain amounts, the level of a Smart Delivery one, and the game's
    # own sequence where a depot mixes the two. Deliveries run importer by
    # importer, each importer in the place of its first contract in the plan.
    imports = {}
    contracts_at = collections.defaultdict(list)
    next_day = None
    partnerships = save.items(save.root["importPartnerships"])
    ranks = _import_ranks(save, partnerships)
    for order, partnership in enumerate(partnerships):
        arrives = partnership.get("nextDeliveryDay") or 0
        active = bool(partnership.get("isActive"))
        smart = bool(partnership.get("isTarget"))
        importer = save.address(partnership.get("importAddress"))
        rank = ranks[order]
        who = names.addr(importer)
        if active and arrives >= day:
            next_day = arrives if next_day is None else min(next_day, arrives)
        for place, product in enumerate(save.items(partnership["products"])):
            warehouse = site_key(save.address(product["assignedWarehouse"]))
            ordered = product.get("amountOrderedLastWeek", 0)
            amount = product.get("amount", 0)
            if not warehouse:
                continue
            # Every contract on the line, for the page to list and a later
            # write to address; after a delivery a contract stays on only if
            # it repeats, so a paused one may be a finished one-off. `group`
            # (the importer's place: its first contract in the plan) and
            # `product` (this product's place in the contract) finish the
            # game's delivery order, which the write's cap budget follows.
            contracts_at[(warehouse, product["itemName"])].append({
                "order": order, "group": rank[0], "product": place, "rank": rank,
                "id": partnership.get("id"), "importer": who,
                "smart": smart, "amount": amount, "lastWeek": ordered, "active": active,
                "repeating": bool(partnership.get("isRepeatingOrder")),
                "agent": partnership.get("employeeInstanceId") is not None,
            })
            if not (amount or ordered):
                continue
            # Current settings establish a route even before its first delivery.
            # Several importers can supply the same holding; inactive contracts
            # and zero orders must never replace or inflate its active supply.
            supply = imports.setdefault((warehouse, product["itemName"]), {
                "weekly": 0, "lastWeek": 0, "arrived": 0, "arrives": arrives,
                "active": False, "from": "",
                "suppliers": {"active": [], "paused": [], "zero": []},
                "history": {"active": 0, "paused": 0, "zero": 0},
                "pausedWeekly": 0, "deliveries": [],
                "drops": {"active": [], "paused": [], "zero": []},
            })
            supplying = active and amount > 0
            group = "active" if supplying else "paused" if not active else "zero"
            drop = {"day": arrives, "amount": amount, "smart": smart, "rank": rank,
                    "importer": who, "id": partnership.get("id")}
            if supplying:
                supply["arrives"] = min(supply["arrives"], arrives) if supply["deliveries"] else arrives
                supply["deliveries"].append(drop)
            supply["drops"][group].append(drop)
            supply["active"] = supply["active"] or active
            supply["history"][group] += ordered
            supply["arrived"] += ordered
            if who not in supply["suppliers"][group]:
                supply["suppliers"][group].append(who)

    for line, supply in imports.items():
        for drops in supply["drops"].values():
            drops.sort(key=lambda d: d["rank"])
        supply["deliveries"].sort(key=lambda d: d["rank"])
        supply["weekly"] = _import_drop(0, supply["drops"]["active"])
        supply["pausedWeekly"] = _import_drop(0, supply["drops"]["paused"])
        group = "active" if supply["weekly"] else "paused" if supply["pausedWeekly"] else "zero"
        supply["lastWeek"] = supply["history"][group]
        supply["from"] = ", ".join(supply["suppliers"][group])
        if group == "paused":
            supply["active"] = False
        # How the line is set in game: Smart Delivery where any contract of the
        # group that counts is, at the highest level, which is the one that
        # holds, and what plain contracts deliver on top of it.
        lead = supply["drops"][group]
        holds = _import_level(lead)
        supply["smart"], supply["target"] = holds["smart"], holds["level"]
        supply["plainAfter"], supply["plainBefore"] = holds["plainAfter"], holds["plainBefore"]
        supply["pass"], supply["levelAt"] = lead, holds["at"]
        named = lead[holds["at"]] if holds["smart"] else {}
        supply["levelImporter"], supply["levelId"] = named.get("importer"), named.get("id")
        supply["plain"] = sum(d["amount"] for d in lead if not d["smart"])
        supply["contracts"] = _contract_list(contracts_at[line])
        supply["levelName"] = _level_name(
            supply["contracts"], named.get("importer"), named["rank"][1] if named else None)

    # A line whose every contract is set to zero and brought nothing last
    # week supplies nothing, so it stays out of the sums above; the page still
    # lists it, at zero, so a contract set up but never filled in is not read
    # as no contract at all.
    configured = {
        line: _contract_list(contracts)
        for line, contracts in contracts_at.items() if line not in imports
    }

    days_to_import = (next_day - day) if next_day is not None else None
    # The delivery lands at the start of its day, so the stock has to reach it
    # from now — the rest of today plus the whole days in between.
    hours_to_import = (
        max(days_to_import - spent_today, 0.0) if days_to_import is not None else None
    )

    # --- 1. shops: does a day of selling outrun the morning top-up?
    shop_rows = []
    for business in businesses:
        if business["status"] != "retail" or business.get("closed"):
            continue
        for line in business["lines"]:
            item, rate = line["slug"], line.get("tradeRate", line["rate"])
            if rate <= 0:
                continue
            target, source = target_at.get((business["key"], item), (0, None))
            factor, peak_day = peak_of(business)
            peak_rate = rate * factor
            if target:
                pressure = peak_rate / target
                fit = _fit(peak_rate, target)
                level = (
                    "critical" if fit == "short"
                    else "warn" if fit == "tight" or pressure >= 0.85
                    else "ok"
                )
            elif (business["key"], item) in wholesale:
                # A weekly wholesale delivery: the stock has to reach the drop.
                deal = wholesale[(business["key"], item)]
                pressure = None
                level = ("critical" if deal["days"] is not None and line["units"] < rate * deal["days"]
                         else "ok")
            elif not line["units"]:
                continue  # never held here, so it is made on demand, not stocked
            else:
                # Nothing refills this shelf on a schedule, so the old
                # days-of-cover question is the right one after all.
                cover = line["units"] / peak_rate
                pressure = None
                level = "critical" if cover < 1 else "warn" if cover < 2 else "ok"
            shop_rows.append(
                {
                    "s": index[business["key"]],
                    "item": line["item"],
                    # The label is what a finding says; the slug is what the
                    # rest of the chain matches on, because a recipe's label
                    # ("Bag of Tomatoes") is not the depot line's ("Tomatoes").
                    "slug": item,
                    "sold": round(rate),
                    "peakSold": round(peak_rate),
                    "peakDay": peak_day,
                    "target": target,
                    "pressure": round(pressure * 100) if pressure is not None else None,
                    "stock": line["units"],
                    "from": index.get(source) if source else None,
                    "level": level,
                    **({"wholesale": wholesale[(business["key"], item)]["weekly"],
                        "wholesaleDay": wholesale[(business["key"], item)]["day"]}
                       if (business["key"], item) in wholesale else {}),
                }
            )
    shop_rows.sort(
        key=lambda r: -(r["pressure"] if r["pressure"] is not None else 999)
    )

    # --- 2. depots: does the holding reach the next delivery?
    # Worked out once the factories' lines are known: _factories() calls
    # walk() back as soon as it has them. What each line needs and what each
    # route brings come from the plans, the imports and the machines
    # (_supply_walk()), never from the delivery log.
    import_rows, import_rows_dem = [], []  # the rows in 24/7 and in Demand sizing
    weekly_use = {}  # (depot, item) -> a week of the draw the 24/7 rows judge
    walked = {}  # sizing mode -> {(site, item): node}, from _supply_walk()
    made_day = {}  # (factory, item) -> what its lines make a day at capacity
    unread = set()  # (factory, item) a line the board cannot name may make: what it holds
    eats_now = {}  # sizing mode -> what factory lines draw, from walk()
    made_now = {}  # sizing mode -> what factory lines make a day, from walk()
    # What arrives whatever the stock: a wholesale store's weekly delivery,
    # a day of it; and each import line's active contracts, which
    # _supply_walk() replays against the stock the routes keep there.
    steady = collections.defaultdict(float)
    for line, deal in wholesale.items():
        steady[line] += deal["weekly"] / 7
    drops = {line: supply["drops"]["active"] for line, supply in imports.items() if supply["weekly"]}

    def depot_rows(mode):
        """The import rows in one sizing mode: each depot line an import
        brings, walked day by day from now to its next drop on what that
        mode's walk says leaves it."""
        rows = []
        for business in businesses:
            if business["status"] not in ("overhead", "support"):
                continue
            for line in business["lines"]:
                item = line["slug"]
                supply = imports.get((business["key"], item))
                if not supply:
                    continue
                node = walked[mode].get((business["key"], item)) or {}
                # The draw: what the ends down the plans use (the shops' sales,
                # the machines' need, what goes to an address not ours), worked
                # out by _supply_walk(). A factory's own lines eating its own
                # import are part of it: the shelf runs dry for the machines
                # as surely as for a round (in this mode's sizing, full rate
                # or Demand), though their week is still judged on the fact
                # (_supply_facts). They eat round the clock, flat whatever the
                # weekday, so the walk charges them apart (`steady`) from what
                # leaves (`onward`), which may follow the shops' week and the
                # morning rounds. Nothing drawing on it, there is no draw to
                # walk.
                per_day = node.get("use", 0.0)
                eaten = min(eats_now.get(mode, {}).get((business["key"], item), (0.0, 0.0))[0], per_day)
                onward = per_day - eaten
                if per_day <= 0:
                    continue  # the graph's pipe then shows what arrived last week
                driven = customer_driven(business["key"], item)
                # The routes come first in the sizing, but a plain import at a
                # depot this line tops up lands whatever that depot holds, and
                # the round then brings only what is missing: the timing walk
                # below charges this line what physically leaves it, its share
                # of what the depots' plain imports leave (`physical`, a
                # fraction of the draw).
                # Until that import lands the walk replays the depot beside
                # this line, day by day on the depot's own weekday rhythm (flat
                # where it feeds machines), and charges this line's rounds to
                # it (`before`, a day's units added to the walk's reduced draw,
                # by day). A top-up to the target is a need only where the
                # depot would otherwise fall short of its own draw before its
                # import lands; the rest of a fill-up is stock moved, not lost,
                # unless this line also serves sites with no import of their
                # own (its own shelves, lines, other sites), which a fill-up
                # then starves: there each morning's round is charged in full,
                # up to the target, the landing morning's included (the round
                # leaves before the import lands). Sizing keeps the standing
                # shares; only the timing replays the rounds. Several senders
                # into the depot share its rounds by what each is asked (a
                # factory's round filling first is not modelled: that takes a
                # depot with a factory route, a relay and an import at once).
                off, before, replayed = 0.0, collections.defaultdict(float), []
                for dest, (asked_use, _asked_need) in node.get("asked", {}).items():
                    dnode = walked[mode].get((dest, item)) or {}
                    plain = sum(d["amount"] for d in drops.get((dest, item), ()) if not d.get("smart")) / 7
                    routes_use = sum(u for u, _n in dnode.get("demand", {}).values())
                    there = imports.get((dest, item))
                    if plain <= 0 or routes_use <= 0 or not there or not there.get("active"):
                        continue
                    left = max(0.0, dnode.get("use", 0.0) - plain)
                    reduced = asked_use * max(0.0, 1 - left / routes_use)
                    off += reduced
                    replayed.append((dest, asked_use, reduced, routes_use, dnode.get("use", 0.0), there["arrives"]))
                # The site's own lines count: a fill-up starves them too.
                serves_more = per_day - sum(r[1] for r in replayed) > 0.5
                tops_up = {}
                for dest, asked_use, reduced, routes_use, dest_use, arrives in replayed:
                    dest_stock = held.get(dest, {}).get(item, 0)
                    dest_week = (beat(businesses[index[dest]]) if customer_driven(dest, item)
                                 else FLAT_WEEK)
                    target = max((a or 0 for d, i, a in edges.get(business["key"], ())
                                  if d == dest and i == item), default=0)
                    charged = 0.0
                    last = arrives + 1 if serves_more else arrives
                    for when in range(day, max(day, last)):
                        draw = dest_use * dest_week[when % 7]
                        if serves_more:
                            # This morning's round: up to the target, or where
                            # the plan has none, what the day's draw leaves
                            # missing; then the day's draw.
                            fill = (max(0.0, target - dest_stock) if target
                                    else max(0.0, draw - dest_stock))
                            dest_stock = max(dest_stock + fill - draw, 0.0)
                        else:
                            # Only what the depot needs to reach its import.
                            fill = max(0.0, draw - dest_stock)
                            dest_stock = max(dest_stock - draw, 0.0)
                        # This line's part of it, less the reduced draw the
                        # walk already charges.
                        part = fill * asked_use / routes_use
                        charged += part
                        before[when] += part - (asked_use - reduced)
                    if charged > 0:
                        tops_up[dest] = (charged, target)
                physical = max(0.0, 1 - off / onward) if onward > 0 else 1.0

                # Walk real days forward rather than dividing by an average: three
                # days that land on a weekend eat more than three ordinary ones. Today
                # is charged for the hours it has left, not for a whole day, so cover
                # is measured from now rather than from this morning.
                weekly = beat(business) if driven else FLAT_WEEK
                factor, peak_day = peak_of(business) if driven else (1.0, None)

                # What leaves is not all the import's to bring: a site of the
                # company's own that tops this line up every morning covers what
                # its supply lets it (_supply_walk(): its imports, its machines,
                # what routes bring it, up to the route's target a day), and a
                # backup import beside it brings nothing while the depot stays
                # full. Only the rest is the import's. Over a week that is the
                # week's draw less what the route brings; a route that can bring
                # all of the draw covers it. Within the week the walk takes each
                # day's draw less the route, signed: a quiet day's surplus stays
                # on the shelf, and a busy Saturday can still empty it. The walk
                # goes in whole units a day (per_day 1, `weekly` the units), the
                # same arithmetic as the plain case.
                gross = per_day
                # A line of the site's own that makes it refills it the same
                # way, round the clock.
                routed = min(node.get("credit", 0.0) + made_now.get(mode, {}).get((business["key"], item), 0.0),
                             gross)
                week_draw = sum(onward * weekly[wd] for wd in range(7)) + 7 * eaten
                covered = bool(node.get("covered"))
                import_avg = gross
                if routed:
                    import_avg = 0.0 if covered else max(0.0, week_draw / 7 - routed)
                if mode == "cap":
                    weekly_use[(business["key"], item)] = import_avg * 7
                # Stock is for timing, never for sizing: what the senders hold
                # still reaches the shelf round by round until it runs out, so
                # the walk to the drop counts it, spread over the days to the
                # drop and never past their targets, where the sizing above
                # counts only what they make or are brought. The rounds bring
                # what is missing each morning, whatever the import brought,
                # so the walk takes what the senders could send (`potential`),
                # not the share the import leaves them.
                to_drop = max(1, supply["arrives"] - day) if supply["active"] else 7
                held_behind = sum(held.get(sender, {}).get(item, 0) for sender in node.get("senders", ()))
                walk_routed = min(gross, node.get("reach", 0),
                                  node.get("potential", 0.0) + held_behind / to_drop) if node.get("inbound") else 0.0
                walk_routed = max(walk_routed, routed)
                walk_weekly, walk_per_day = weekly, onward * physical
                if walk_routed:
                    walk_weekly = {wd: onward * physical * weekly[wd] - walk_routed for wd in range(7)}
                    walk_per_day = 1.0
                    weekly = {wd: onward * weekly[wd] - walk_routed for wd in range(7)}
                    per_day = 1.0
                else:
                    per_day = onward
                # A depot its plans empty is emptied a round at a time: each round
                # leaves in the morning, today's counts only while it has not left
                # yet (today's log is the one record of that), and the delivery
                # day's round leaves before the import lands, so the stock has to
                # cover it too. Cover and due are then counted in rounds.
                rounds = any(
                    i == item and d != business["key"] for d, i, _a in edges.get(business["key"], ()))
                today = ((0.0 if (business["key"], item) in rounds_today else 1.0)
                         if rounds else left_today)
                # The site's own lines: the hours left today, then whole days.
                steady = (eaten, left_today) if eaten else None
                landing = supply["arrives"] if supply["active"] and rounds else None
                def cover_walk(extra):
                    remaining, cover, runs_out = line["units"], 0.0, None
                    for ahead in range(60):
                        share = today if ahead == 0 else 1.0
                        # On a round-fed site's delivery day only the round
                        # leaves before the drop; the lines eat after it.
                        today_use = ((walk_per_day * walk_weekly[(day + ahead) % 7]
                                      + extra.get(day + ahead, 0.0)) * share
                                     + _steady_on(steady, ahead, day + ahead != landing))
                        if today_use <= 0:
                            remaining -= today_use  # a route's surplus stays on the shelf
                            cover += share
                            continue
                        if remaining <= today_use:
                            cover += share * remaining / today_use
                            runs_out = day + ahead
                            break
                        remaining -= today_use
                        cover += share
                    else:
                        cover = 60.0
                    return cover, runs_out

                cover, runs_out = cover_walk(before)

                # From now to the drop: the whole days before it plus what is left
                # of today, and for a round-fed depot the delivery day's round too.
                def until_drop(when):
                    return max(when - day - 1 + today + (1 if rounds else 0), 0.0)

                # Is the standing order the right size? Last week's draw is not the
                # test — an order that exactly matched last week's use is a well
                # sized order, not a warning. The test is the week the order has to
                # cover, charged day by day at each weekday's own rate, the same
                # walk the cover figure above uses.
                start = supply["arrives"] if supply["active"] else day
                week_need = (
                    import_avg * 7 if routed
                    else week_draw if walk_routed
                    else sum(per_day * weekly[(start + ahead) % 7] for ahead in range(7)) + 7 * eaten
                )
                due = until_drop(supply["arrives"]) if supply["active"] else None
                # A paused backup beside a route that brings the week has no drop
                # to reach; the shelf is judged over a week instead, which the
                # route's few percent of drift cannot empty.
                horizon = covered and due is None
                week_on = day + (6 if rounds else 7)  # a week of rounds, or of days
                if horizon:
                    due = until_drop(week_on)

                # Last week's order against this week's is a change of mind, not a
                # shortfall: the order is judged on the week the plans draw.
                order_fit = (
                    "short" if week_need and not supply["weekly"] else _fit(week_need, supply["weekly"])
                )

                # An order sized to consumption always looks as though it runs out a
                # few hours before the next drop — that is the design, not a finding.
                # So the same tolerance the order fit uses applies to the walk: a gap
                # under half a day, or under 5% of the week the order covers, is
                # tight rather than short.
                slack = max(COVER_NOISE_DAYS, FIT_TIGHT * week_need / import_avg if import_avg else 0.0)
                short_by = max(due - cover, 0.0) if due is not None else 0.0
                cover_fit = (
                    "short" if short_by > slack else "tight" if short_by > 0 else "ok"
                )
                catch_up = _import_catch_up(
                    line["units"], walk_per_day, walk_weekly, day,
                    week_on if horizon else supply["arrives"], today, rounds, before, steady, supply["active"]
                ) if supply["active"] or horizon else None
                schedule = _scheduled_import_gap(
                    line["units"], walk_per_day, walk_weekly, day, supply["deliveries"], today, rounds, before,
                    steady)
                stock_cover = cover
                if schedule:
                    cover, runs_out = schedule["cover"], schedule["runsOut"]
                    due = until_drop(schedule["until"])
                    short_by = max(due - cover, 0.0)
                    cover_fit = "short" if short_by > slack else "tight" if short_by > 0 else "ok"
                    catch_up = schedule["catchUp"]
                until = (schedule["until"] if schedule
                         else week_on if horizon else supply["arrives"])

                # An order too small for its week and a shelf that runs dry before
                # the next drop are usually the same fact at two stages: the order
                # loses ground every week, and the buffer hides it until it cannot.
                # Naming the order first keeps them one finding with one fix, and
                # leaves 'shortfall' for the case that really is different — an
                # order sized right, and stock that still will not reach the drop.
                if covered and cover_fit == "ok":
                    # The route brings everything that leaves: the import is a
                    # backup, paused or not, and has nothing to answer for.
                    level, reason = "ok", None
                elif covered:
                    # It brings the week, but a busy day outruns what is on the
                    # shelf before the next morning's round.
                    level = "critical" if cover_fit == "short" else "warn"
                    reason = "shortfall"
                elif not supply["active"]:
                    level, reason = ("critical" if cover < 7 else "warn"), "paused"
                elif order_fit == "short":
                    level, reason = "critical", "order"
                elif cover_fit == "short":
                    level, reason = "critical", "shortfall"
                elif order_fit == "tight":
                    level, reason = "warn", "order"
                elif cover_fit == "tight":
                    level, reason = "warn", "shortfall"
                else:
                    level, reason = "ok", None
                # A run-dry the rounds to a depot beside decide (the walk
                # without them would reach the drop): the finding names that
                # depot and its target, the biggest such round's.
                tops = None
                if reason == "shortfall" and tops_up and due is not None and cover_walk({})[0] >= due:
                    dest = max(tops_up, key=lambda d: (tops_up[d][0], d))
                    tops = [index[dest], tops_up[dest][1]]
                rows.append(
                    {
                        "s": index[business["key"]],
                        "item": line["item"],
                        "slug": item,
                        "stock": line["units"],
                        # [site, target]: the depot this line's morning rounds
                        # top up before its own import lands, where those rounds
                        # are what runs it dry; left off otherwise.
                        **({"topsUp": tops} if tops else {}),
                        # What leaves a day, and of it what the company's own
                        # routes bring (routed) and what is left for the import
                        # (importPerDay): the week, cover and catch-up below are
                        # judged on the last.
                        "perDay": round(gross),
                        # Of it, what the site's own factory lines eat; the
                        # rest leaves the site.
                        **({"eats": round(eaten)} if eaten else {}),
                        "routed": round(routed),
                        "importPerDay": round(import_avg),
                        # The route covers all of it: a paused import beside it
                        # is a backup, not a warning.
                        "covered": covered,
                        # What the draw is read from: what the ends down the
                        # plans sell and eat (_supply_walk()).
                        "basis": "sales",
                        "peakDay": peak_day,
                        "peakPerDay": round(onward * factor + eaten),
                        "cover": round(cover, 1),
                        "stockCover": round(stock_cover, 1),
                        # The plain division, without the weekday walk: units on the
                        # shelf against a flat day of draw.
                        "daysOnHand": round(line["units"] / gross, 1),
                        "runsOut": WEEKDAYS[runs_out % 7] if runs_out is not None else None,
                        "weekly": supply["weekly"],
                        "lastWeek": supply["lastWeek"],
                        **_import_setting(supply),
                        "weekNeed": round(week_need),
                        # What the walk takes before the next refill, for the
                        # goods-flow panel: flat for a line that feeds machines,
                        # the weekday profile for one that feeds shelves, whole
                        # rounds where its plans empty it; a paused
                        # line is walked a week.
                        "dueNeed": round(_deepest_use(
                            walk_per_day, walk_weekly, day,
                            supply["arrives"] if supply["active"] else week_on, today, rounds, before, steady,
                            supply["active"])),
                        "rounds": rounds,
                        "orderFit": order_fit,
                        "coverFit": cover_fit,
                        "due": round(due, 2) if due is not None else None,
                        "shortBy": round(short_by, 2),
                        "catchUp": catch_up,
                        "coverageUntil": until,
                        # What the shelf has to hold, from the same walk, for a
                        # line a route helps feed: to the next drop (the first,
                        # where several are due), or, where a later drop is still
                        # too far for what lands before it, the stock plus the
                        # catch-up that bridges it. The goods-flow node reads it
                        # rather than a busy day times the days.
                        "carry": round(max(
                            _deepest_use(
                                walk_per_day, walk_weekly, day,
                                week_on if horizon else supply["arrives"] if supply["active"] else until,
                                today, rounds, before, steady, supply["active"]),
                            line["units"] + catch_up if catch_up else 0,
                        )) if walk_routed else None,
                        "paused": not supply["active"],
                        "arrives": supply["arrives"],
                        "from": supply["from"],
                        "level": level,
                        "reason": reason,
                    }
                )
        rows.sort(key=lambda r: r["stockCover"])
        return rows

    def walk(makes: dict, eats: dict, unknown: set) -> dict:
        """_factories()'s call back once its lines are known: `makes` what
        each factory's lines make a day in each sizing mode, {mode: {(factory,
        item): units}} (24/7 at capacity, Demand what the ends draw);
        `eats` what they draw a day in each sizing mode, {mode: {(factory,
        item): (use, need)}}; `unknown` the (factory, item) pairs a factory
        with a line the board cannot name holds, taken as made there. Walks the chain in each mode, builds the import rows,
        and returns what routes from the company's own sites bring each depot
        line a week, for the factory view: `routed` where an import brings
        it too, `routeOnly` where none does, each as (a week of what the
        routes bring, whether that is all of it, a week of what leaves)."""
        made_day.update(makes.get("cap", {}))
        made_now.update(makes)
        unread.update(unknown)
        eats_now.update(eats)
        for mode in SIZING_MODES:
            grown = collections.defaultdict(float, steady)
            for line, per_day in makes.get(mode, {}).items():
                grown[line] += per_day
            # One cut of the plans' loops for everything: the one Demand
            # sizing made (dem_graph), so the two modes never disagree on it.
            walked[mode] = _supply_walk(index, dem_graph.get("edges", edges), leaves, eats.get(mode, {}),
                                        dict(grown), drops, unknown)
        import_rows[:] = depot_rows("cap")
        import_rows_dem[:] = depot_rows("dem")
        routed_in, route_only = {}, {}
        for (key, item), node in walked["cap"].items():
            if (key not in index or businesses[index[key]]["status"] not in ("overhead", "support")
                    or (key, item) in eats.get("cap", {})):
                continue
            figures = (node["credit"] * 7, node["covered"], node["use"] * 7)
            if (key, item) in imports:
                if node["credit"]:
                    routed_in[(key, item)] = figures
            elif node["inbound"] and node["use"]:
                route_only[(key, item)] = figures
        return {"routed": routed_in, "routeOnly": route_only}

    # Demand sizing reads a factory line's use off what the ends draw of its
    # product down the plan. A shop under a week old has not settled yet: its
    # coming week is read off a straight line through its trading days
    # (_coming_week), and every such shop behind a figure is named (ramp).
    sold_dem, ramping = {}, set()
    # What each shop measurably sells a day, before any coming week or target
    # stands in for it: the Sold / day a factory line shows (demand(measured)).
    sold_measured = {}
    for business in businesses:
        key = business["key"]
        if business["status"] != "retail" or business.get("closed"):
            # A factory's or a depot's own "sales" are the goods its rounds
            # take away: only a shop's sales are an end, and not a shop shut
            # with the game's temporarily closed switch.
            continue
        young = (business["status"] == "retail"
                 and day - business.get("opened", day) < NEW_SITE_DAYS)
        # A shop a week old sells its week; one younger its trading-day rate
        # until its coming week can be read off a line.
        rates = dict((sold if young else sold_week).get(key, {}))
        sold_measured[key] = dict(rates)
        for line in business["lines"]:
            if young and rates.get(line["slug"], 0) > 0:
                ramping.add(key)
                ahead = _coming_week(line.get("soldDays") or [], day)
                if ahead is not None:
                    rates[line["slug"]] = ahead
        # A line topped up to a target it has sold none of yet asks for the
        # target, as the chain's walk reads it (leaves).
        if business["status"] == "retail":
            for (dest, item), (use, _need) in leaves.items():
                if dest == key and not rates.get(item):
                    rates[item] = use
        sold_dem[key] = rates
    dem_drawn, dem_levels_at = {}, {}
    # The plans with their loops cut as the chain's walk cuts them, and each
    # plan's share of what the site it tops up draws: two factories topping
    # one shop up split its demand by their targets, never both taking all.
    # The graph is the walk's (_supply_walk): the same loop cut and the same
    # senders with anything coming in, production included, which
    # _factories() names (dem_made) before it sizes a line.
    dem_graph = {}

    def dem_made(made, made_amount=lambda _site, _item: 0.0) -> None:
        """Say which (site, item) a line makes, and how much a day at most,
        and build the graph from it."""
        def supplied(site, item):
            return bool((site, item) in drops or (site, item) in wholesale or made(site, item))
        def surplus(site, item):
            n = (site, item)
            own = (imports[n]["weekly"] / 7 if n in imports else 0.0) + (
                wholesale[n]["weekly"] / 7 if n in wholesale else 0.0) + made_amount(site, item)
            return own - leaves.get(n, (0.0, 0.0))[1]
        dem_graph["edges"] = cut = _plan_dag(edges, index, supplied, lambda site, item: (site, item) in leaves,
                                             surplus)
        senders = collections.defaultdict(list)
        for source, legs in cut.items():
            if source not in index:
                continue
            for dest, item, amount in legs:
                if dest in index and dest != source:
                    senders[(dest, item)].append((source, amount or 0))
        share = collections.defaultdict(lambda: collections.defaultdict(float))
        for line, legs in senders.items():
            able = [(s, t) for s, t in legs if supplied(s, line[1]) or senders.get((s, line[1]))] or legs
            whole = sum(t for _s, t in able)
            for s, t in able:
                share[line][s] += t / whole if whole else 1 / len(able)
        # Frozen: demand() and dem_levels() read it by key while dem_levels()
        # walks it, and a plan to an address not the company's has no entry.
        dem_graph["share"] = _frozen(share)
        # What a sender can bring of it a day: what a factory can make, or
        # what an import or a wholesale delivery brings a site (the walk's
        # has() in 24/7). A sender whose shares would pass it hands the rest
        # to the others (dem_levels()). None is no cap: a site that brings
        # none of its own, or a line the board cannot read, taken to send
        # what it is asked with no known capacity.
        def own_supply(site, item):
            # What the site brings in itself a day: a line making it adds to
            # an import beside it. None where a line makes it at a capacity
            # the board cannot read, or nothing brings it here but routes
            # (dem_levels() then adds what they can bring, as the walk's
            # has() does).
            n = (site, item)
            brought = ((imports[n]["weekly"] / 7 if n in imports else 0.0)
                       + (wholesale[n]["weekly"] / 7 if n in wholesale else 0.0))
            if made(site, item):
                making = made_amount(site, item)
                return (making + brought) if making else None
            return brought if (n in imports or n in wholesale) else None
        dem_graph["cap"] = own_supply
        dem_graph["made"] = made
        dem_drawn.clear()
        dem_levels_at.clear()

    dem_made(lambda _site, _item: False)

    def dem_own(site: str, item: str) -> float:
        """What a site's own import and wholesale delivery bring it a day, less
        the margin: what brings the part of its draw the senders topping it
        up have no room for, as in the chain's walk (the routes come first)."""
        n = (site, item)
        # A Smart Delivery level at or under the routes' target brings
        # nothing (the walk's own(): _import_drop() against that stock).
        able = dem_graph["share"].get(n) or {}
        reach = max((a for source, legs in dem_graph["edges"].items() if source in able
                     for d, i, a in legs if d == site and i == item), default=0)
        brought = ((_import_drop(reach, drops[n]) / 7 if drops.get(n) else 0.0)
                   + (wholesale[n]["weekly"] / 7 if n in wholesale else 0.0))
        return brought / (1 + SUPPLY_MARGIN)

    def has_own(site: str, item: str) -> bool:
        """Whether a site has a supply of its own, whatever it brings now (a
        Smart Delivery level at or under the routes' target brings nothing):
        where the chain's walk caps a round at its target (supplied())."""
        n = (site, item)
        return bool(drops.get(n) or n in wholesale or dem_graph["made"](site, item))

    def dem_levels(item: str, eats) -> dict:
        """How far each sender with a known capacity holds its shares down,
        {sender: level}: the chain's walk's own allocation (_held_levels()),
        on what the sites down the plan draw (before any holding down), each
        site's own supply bringing what its senders' room leaves. A factory's capacity and an import are taken
        less the margin (the line is sized on its share plus the margin,
        _line_hours(), and an import is judged against the need)."""
        memo = (item, eats is not None)
        if memo in dem_levels_at:
            return dem_levels_at[memo]
        dem_levels_at[memo] = {}  # a loop back into this item holds nothing down
        sites, limits, fixed, caps_at = {}, {}, collections.defaultdict(float), {}
        for (dest, it), weights in list(dem_graph["share"].items()):
            if it != item or dest not in index:
                continue
            more, _behind = demand(dest, item, eats=eats, held_down=False)
            sites[dest] = (more, dict(weights), dem_own(dest, item))
        own_use = {}

        def used(site):
            if site not in own_use:
                own_use[site] = sold_dem.get(site, {}).get(item, 0.0) + (
                    eats(site, item) if eats is not None else 0.0)
            return own_use[site]

        through_at = {}

        def through(site, seen=frozenset()):
            """What `site` can send a day, the margin included: what it
            brings in itself, plus what the routes into it can bring (each
            sender's own throughput less what it sends its other sites and
            uses, never past the route's target, together never past the
            highest), as the walk's has(). None where unknown."""
            if site in through_at:
                return through_at[site]
            if site in seen:
                return None
            own_here = dem_graph["cap"](site, item)
            legs = {s: w for s, w in (dem_graph["share"].get((site, item)) or {}).items() if w > 0}
            if not legs:
                through_at[site] = own_here
                return own_here
            if own_here is None and dem_graph["made"](site, item):
                through_at[site] = None
                return None
            inbound, reach = 0.0, 0
            for source in _in_order(legs):
                there = through(source, seen | {site})
                if there is None:
                    through_at[site] = None
                    return None
                # Its own use and the sites only it tops up come first, as in
                # the walk's has(); at a shared site it brings no more than
                # the part the last pass allocated it there.
                first = {dest: more for dest, (more, weights, own_d) in sites.items()
                         if weights.get(source) and own_d <= 0
                         and sum(1 for w in weights.values() if w > 0) <= 1}
                other = (used(source) + sum(v for d, v in first.items() if d != site)) * (1 + SUPPLY_MARGIN)
                mine = first.get(site, 0.0) * (1 + SUPPLY_MARGIN)
                target = max((a for d, i, a in dem_graph["edges"].get(source, []) if d == site and i == item),
                             default=0)
                reach = max(reach, target)
                if site in first and other + mine > there > 0:
                    bring = there * mine / (other + mine)
                else:
                    bring = max(0.0, there - other)
                    if site not in first and (site, source) in allotted:
                        bring = min(bring, allotted[(site, source)] * (1 + SUPPLY_MARGIN))
                inbound += min(bring, target) if target else bring
            through_at[site] = (own_here or 0.0) + (min(inbound, reach) if reach else inbound)
            return through_at[site]

        # Passes, as the walk's: a sender's limit at a site it shares is the
        # part the last pass allocated it there, so the upstream split is
        # solved first; they stop when no part moves.
        allotted, levels, last_levels, last_limits = {}, {}, {}, {}
        for _pass in range(HAND_ON_PASSES):
            through_at.clear()
            limits, fixed, caps_at = {}, collections.defaultdict(float), {}
            for dest, (residual, weights, own_here) in sites.items():
                whole = sum(weights.values())
                several = own_here > 0 or sum(1 for w in weights.values() if w > 0) > 1
                for sender, w in weights.items():
                    if sender not in limits:
                        cap = through(sender)
                        limits[sender] = None if cap is None else cap / (1 + SUPPLY_MARGIN)
                        fixed[sender] += used(sender)
                    if not several:
                        fixed[sender] += residual * w / whole if whole else 0.0
                    elif has_own(dest, item):
                        target = max((a for d, i, a in dem_graph["edges"].get(sender, [])
                                      if d == dest and i == item), default=0)
                        if target:
                            caps_at[(sender, dest)] = target / (1 + SUPPLY_MARGIN)
            levels = _held_levels(sites, limits, fixed, caps_at)
            parts = {}
            for dest, (residual, weights, own_here) in sites.items():
                whole = sum(weights.values())
                caps = {sender: levels[sender] * residual * w / whole
                        for sender, w in weights.items() if sender in levels}
                for sender, part in _share_with_room(residual, weights, caps, own_here).items():
                    # Its part as allocated: its level of its share, not what
                    # is left with it when no one else brings it.
                    parts[(dest, sender)] = min(part, caps[sender]) if sender in caps else part
            # The walk's stop rule: no level and no limit moved since the
            # last pass (a sender with no level yet can still have a limit
            # coming down to its ask).
            same = (levels.keys() == last_levels.keys()
                    and all(abs(levels[k] - last_levels[k]) <= 1e-6 * max(1.0, levels[k]) for k in levels)
                    and all(abs((limits[k] or 0.0) - (last_limits.get(k) or 0.0)) <= 1e-6 * max(1.0, limits[k] or 0.0)
                            for k in limits))
            if _pass and same:
                break
            last_levels, last_limits = levels, dict(limits)
            allotted = parts
        dem_levels_at[memo] = levels
        return dem_levels_at[memo]

    def demand(key: str, item: str, seen: frozenset = frozenset(), eats=None,
               held_down: bool = True, measured: bool = False) -> tuple:
        """What the ends draw of `item` a day from this site down the plan, as
        Demand sizing reads it, and the young shops behind that figure. The
        ends are the shelves and, given `eats(site, item)`, the factory lines
        along the way that draw on it; never what the delivery log saw leave.
        A plan to an address not ours (an export) takes the surplus, as the
        chain's walk reads it, and sizes nothing. With `measured`, the
        shelves' measured sales alone (sold_measured: no coming week, no
        target in their place, and `eats` not added), shared out between the
        senders as Demand sizing shares its own figure (the same levels and
        targets), for display; it sizes nothing."""
        if key not in index or key in seen:
            return 0.0, frozenset()
        memo = (key, item, eats is not None, held_down, measured)
        if memo in dem_drawn:
            return dem_drawn[memo]
        total = (sold_measured if measured else sold_dem).get(key, {}).get(item, 0.0)
        ramp = {index[key]} if key in ramping and total > 0 else set()
        if eats is not None and not measured:
            total += eats(key, item)
        for dest_key in _in_order({d for d, i, _a in dem_graph["edges"].get(key, []) if i == item and d != key}):
            # .get(): a plan to an address not the company's has no share.
            weights = dem_graph["share"].get((dest_key, item)) or {}
            if not weights.get(key):
                continue
            more, behind = demand(dest_key, item, seen | {key}, eats, held_down, measured)
            # The routes come first, as in the chain's walk: the site's own
            # import brings only what the senders' room leaves.
            residual = more
            if held_down:
                # A sender asked for more than it can make or bring in across
                # all the sites it tops up is held to its level here
                # (dem_levels()), and the rest goes to the other senders with
                # room (_share_with_room).
                levels = dem_levels(item, eats)
                caps = {sender: levels[sender] * residual * w / sum(weights.values())
                        for sender, w in weights.items() if sender in levels}
                own_here = dem_own(dest_key, item)
                targets = {}
                if has_own(dest_key, item):
                    # A round brings no more than its target a day where the
                    # site has a supply of its own, as in the chain's walk:
                    # the rest is that supply's to bring, even past what it
                    # brings now (its own fact asks for it).
                    for sender in weights:
                        target = max((a for d, i, a in dem_graph["edges"].get(sender, [])
                                      if d == dest_key and i == item), default=0)
                        if target:
                            targets[sender] = target / (1 + SUPPLY_MARGIN)
                            caps[sender] = min(caps.get(sender, targets[sender]), targets[sender])
                part = _share_with_room(residual, weights, caps, own_here).get(key, 0.0)
                total += min(part, targets[key]) if key in targets else part
            else:
                total += residual * weights[key] / sum(weights.values())
            ramp |= behind
        dem_drawn[memo] = (total, frozenset(ramp))
        return dem_drawn[memo]

    # --- 3. the factories: what each line makes and eats, against the flow
    flow = {
        "day": day,
        "demand": demand,
        # Named by _factories() before it sizes a line: what each makes.
        "demandMade": dem_made,
        "index": index,
        "held": held,
        "targets": target_at,
        "imports": imports,
        "configured": configured,
        "edges": edges,
        "shipped": shipped_per_day,
        "received": received_per_day,
        "forwarded": forwarded_per_day,
        "byDay": lambda key, item: by_day.get(key, {}).get(item, {}),
        "outByDay": lambda key, item: out_by_day.get(key, {}).get(item, {}),
        "inByDay": lambda key, item: in_by_day.get(key, {}).get(item, {}),
        # A site's first fill of an item in the window (first_fill()).
        "firstFill": first_fill,
        # A shop listing the item sells it, and so does any site whose line
        # for it shows sales, whatever its type.
        "sells": lambda key, item: key in index and (
            sold.get(key, {}).get(item, 0) > 0
            or (businesses[index[key]]["status"] == "retail" and item in sold.get(key, {}))),
        "roundDays": lambda key: round_days.get(key, set()),
        # Called back once the factories' lines are known; it fills in
        # `routed` and `routeOnly` (walk()).
        "walk": walk,
    }
    factories = _factories(save, names, businesses, recipes or {}, flow, history, character)

    # --- 3b. anything just sitting there
    # Stock is idle when it is IDLE_WEEKS or more of what draws on it, and not
    # moving when nothing does. What draws on it depends on where it sits: a
    # shelf sells at its trading-day rate; a factory input is eaten at its
    # machines' need in the sizing mode (a first fill is not stock sitting); a
    # depot or a pass-through feeds the shelves and machines its plans reach,
    # and only where they reach none is the measured outflow read instead. A
    # shop too new to judge, or a depot whose only plan leads to one, waits.
    need_rows, made_at = {}, set()
    for site in factories.get("sites", []):
        key = businesses[site["s"]]["key"]
        made_at |= {(key, line["slug"]) for line in site["lines"]}
        for row in site["needs"]:
            need_rows[(key, row["slug"])] = row
    # A factory with a machine whose recipe the board cannot read: what
    # arrives there may be what that machine eats.
    unread_sites = {businesses[site["s"]]["key"] for site in factories.get("sites", [])
                    if site.get("unnamed")}

    def line_need(row, mode):
        return row["perDay"] if mode == "cap" else row.get("demDay", row["perDay"])

    def young_shop(key):
        b = businesses[index[key]]
        return b["status"] == "retail" and b.get("tradeDays", MIN_TRADE_DAYS) < MIN_TRADE_DAYS

    def plan_draw(key, item, mode, seen=frozenset()):
        """What the plans from `key` carry away a day: the shelves' sales, the
        machines' need, and what a depot further on passes on in turn; and
        whether a shop too new to judge is among them (True), or a machine
        line on its first fill ("fresh"), whose draw the log cannot judge yet."""
        total, waits = 0.0, False
        for dest, dest_item, _amount in edges.get(key, []):
            if dest_item != item or dest not in index or dest in seen or dest == key:
                continue
            if businesses[index[dest]]["status"] == "retail":
                # A shop too new to have a week behind it sells at its
                # trading-day rate, not at the few days it has traded yet.
                young = young_shop(dest)
                total += (sold if young else sold_week).get(dest, {}).get(item, 0.0)
                waits = waits or young
                continue
            row = need_rows.get((dest, item))
            if row:
                total += line_need(row, mode)
                if row.get("firstFill"):
                    waits = "fresh"
            onward, later = plan_draw(dest, item, mode, seen | {key})
            total += onward
            waits = "fresh" if "fresh" in (waits, later) else waits or later
        return total, waits

    # Own sites that sell or need an item no plan brings them: a shelf with
    # sales and no top-up, a factory input with no top-up, import or maker.
    unfed_by_item = collections.defaultdict(list)
    for business in businesses:
        key = business["key"]
        for line in business["lines"]:
            item = line["slug"]
            if (key, item) in target_at or (key, item) in wholesale:
                continue
            if business["status"] == "retail":
                rate = sold.get(key, {}).get(item, 0.0)
                if rate > 0 and line["units"]:
                    unfed_by_item[item].append(
                        [index[key], round(rate), round(line["units"] / rate, 1)])
    for (key, item), row in need_rows.items():
        if (row["target"] or (key, item) in imports or index[key] in row["madeAt"]
                or (key, item) in wholesale or not row["perDay"]):
            continue
        units = held.get(key, {}).get(item, 0)
        unfed_by_item[item].append([index[key], round(row["perDay"]), round(units / row["perDay"], 1)])
    # And a site whose own plans send an item on to shelves or machines while
    # nothing brings it there: no top-up, no import, no wholesale delivery, no
    # line of its own that makes it. Its plans carry what they would, from
    # whatever it holds. A factory with a machine the board cannot name may
    # make it there, so it is left out.
    for key, outs in edges.items():
        if (key not in index or key in unread_sites
                or businesses[index[key]]["status"] in ("vacant", "retail")):
            continue
        for item in _in_order({i for _d, i, _a in outs}):
            if ((key, item) in target_at or (key, item) in imports or (key, item) in made_at
                    or (key, item) in wholesale):
                continue
            per_day, _waits = plan_draw(key, item, "cap")
            if per_day <= 0:
                continue
            units = held.get(key, {}).get(item, 0)
            unfed_by_item[item].append([index[key], round(per_day), round(units / per_day, 1)])

    all_eaten = set(need_rows)
    idle_by = collections.defaultdict(dict)  # (key, item) -> {mode: row}
    for business in businesses:
        if business["status"] == "vacant":
            continue
        key = business["key"]
        factor, _peak = peak_of(business)
        for line in business["lines"]:
            item, units = line["slug"], line["units"]
            if units < IDLE_UNITS or (key, item) in made_at and (key, item) not in need_rows:
                continue
            target, source = target_at.get((key, item), (0, None))
            supply = imports.get((key, item))
            for mode in SIZING_MODES:
                row = need_rows.get((key, item))
                if business["status"] == "retail":
                    if young_shop(key):
                        continue
                    # Weeks of what it sells in a week; the busiest day, for a
                    # top-up target, at the trading-day rate.
                    per_day = sold_week.get(key, {}).get(item, 0.0)
                    busiest = sold.get(key, {}).get(item, 0.0) * factor
                elif row:
                    if row.get("firstFill"):
                        continue
                    per_day = line_need(row, mode)
                    onward, _waits = plan_draw(key, item, mode)
                    per_day += onward
                    busiest = per_day
                elif key in unread_sites and not any(i == item for _d, i, _a in edges.get(key, [])):
                    # A factory holding what no named line eats (a recipe the
                    # board cannot read): what arrives is what its machines
                    # draw, never nothing while deliveries come in.
                    per_day = received_per_day(key, item) or 0.0
                    busiest = per_day
                else:
                    per_day, waits = plan_draw(key, item, mode)
                    per_day += sold_week.get(key, {}).get(item, 0.0)
                    # Feeding lines on their first fill: not judged yet.
                    if waits == "fresh":
                        continue
                    if not per_day:
                        if waits:
                            continue
                        per_day = shipped_per_day(key, item) or 0.0
                    busiest = per_day
                entry = {"target": target, "perWeek": round(per_day * 7)}
                if per_day <= 0:
                    if units < DEAD_UNITS:
                        continue
                    unfed = [u for u in unfed_by_item.get(item, []) if u[0] != index[key]]
                    entry.update(weeks=None, dead=True, level="warn",
                                 why="notRouted" if unfed else "notMoving")
                    if unfed:
                        entry["unfed"] = unfed
                    # Routed here by a top-up target, and nothing here uses
                    # it or sends it on: the route is the thing to change.
                    elif (target and source in index and (key, item) not in all_eaten
                            and not any(i == item for _d, i, _a in edges.get(key, []))):
                        entry["routedFrom"] = index[source]
                else:
                    weeks = units / (per_day * 7)
                    if weeks < IDLE_WEEKS:
                        continue
                    entry.update(weeks=round(weeks, 1), dead=False,
                                 level="warn" if weeks >= IDLE_WEEKS * 2 else "info")
                    brings = (supply["target"] if supply and supply.get("smart")
                              else supply["weekly"] if supply else 0)
                    if brings and brings >= IDLE_WEEKS * per_day * 7:
                        entry.update(why="importHigh", importLevel=brings,
                                     smart=bool(supply.get("smart")))
                    elif target and (target >= IDLE_WEEKS * 7 * busiest
                                     # a shelf at its target holds what the target puts there
                                     or (business["status"] == "retail" and target >= units)):
                        entry["why"] = "targetHigh"
                    else:
                        entry["why"] = "overstock"
                idle_by[(key, item)][mode] = entry

    idle_rows = []
    for (key, item), by_mode in idle_by.items():
        line = next(l for l in businesses[index[key]]["lines"] if l["slug"] == item)
        base = by_mode.get("cap") or by_mode["dem"]
        row = {"s": index[key], "item": line["item"], "slug": item, "stock": line["units"],
               "price": line["price"], "value": money(line["units"] * line["price"]),
               **base, "modes": [mode for mode in SIZING_MODES if mode in by_mode]}
        dem = by_mode.get("dem")
        if dem and "cap" in by_mode:
            changed = _mode_changes(base, dem)
            if changed:
                row["dem"] = changed
        idle_rows.append(row)
    idle_rows.sort(key=lambda r: (-(r["weeks"] or 999), r["s"], r["slug"]))
    # A depot line nothing draws on (its only measured outflow a one-off fill)
    # has no draw to walk to the drop: it is idle stock, not a holding that
    # reaches the import, so Before the import leaves it to Idle stock.
    still = {(index[key], item) for (key, item), by_mode in idle_by.items()
             if (by_mode.get("cap") or {}).get("dead")}
    import_rows = [r for r in import_rows if (r["s"], r["slug"]) not in still]
    import_rows_dem = [r for r in import_rows_dem if (r["s"], r["slug"]) not in still]

    # What the facts carry: the idle verdict in each mode, and, for stock no
    # plan sends on while own sites sell or need it, the sites it could feed
    # (`unfed`), each of which names the depot holding the most of it (`via`).
    idle_facts = collections.defaultdict(dict)
    extra = collections.defaultdict(dict)
    via = {}
    for (key, item), by_mode in idle_by.items():
        for mode, entry in by_mode.items():
            idle_facts[(key, item)][mode] = {"idle": entry["why"], "idleLvl": entry["level"]}
        cap = by_mode.get("cap") or by_mode["dem"]
        if cap.get("unfed"):
            extra[(key, item)]["unfed"] = cap["unfed"]
            units = held[key][item]
            for s, _per_day, _days in cap["unfed"]:
                best = via.get((s, item))
                if best is None or units > best[0]:
                    via[(s, item)] = (units, index[key])
    for (s, item), (_units, depot) in via.items():
        extra[(businesses[s]["key"], item)]["via"] = depot

    def round_gap(key: str) -> int:
        """The most days a site's logistics rounds leave between two of them,
        read off the weekdays a round left in the last SHIPPED_WINDOW days;
        1 (a round every morning) where too few rounds are logged to say."""
        weekdays = sorted({d % 7 for d in round_days.get(key, ())})
        if len(weekdays) < SHIPPED_MIN_DAYS:
            return 1
        return max((b - a) % 7 or 7 for a, b in zip(weekdays, weekdays[1:] + weekdays[:1]))

    # --- 3c. one fact per (site, item), with one status word, read by every
    # view of the board and by the findings (_supply_facts)
    def sourced(key: str, item: str) -> bool:
        """Whether `key` has `item` to send on: it holds some, an import (even
        a paused one: its own fact says so) or a wholesale delivery brings
        it, a line there makes it (or may: a line
        the board cannot name), or a route from a site of yours tops it up.
        Someone else's address is not the company's to judge."""
        if key not in index:
            return True
        node = walked.get("cap", {}).get((key, item)) or {}
        return bool(held.get(key, {}).get(item, 0) > 0 or (key, item) in imports
                    or (key, item) in wholesale or made_day.get((key, item))
                    or (key, item) in made_at or (key, item) in unread or node.get("inbound"))

    facts = _supply_facts({
        "businesses": businesses, "index": index, "factories": factories,
        "targets": target_at, "import_rows": import_rows, "import_rows_dem": import_rows_dem,
        "peak": peak_of, "wholesale": wholesale,
        "idle": idle_facts, "extra": extra, "roundGap": round_gap,
        "walk": walked, "made": made_now, "sourced": sourced, "held": held, "label": names.label,
        "edges": edges, "catalogue": _type_ranges(names),
    })
    # A shelf nothing upstream supplies has sold nothing, so it has no row
    # above; it gets one, so its finding lands on it (Deliveries, the site
    # panel's shelves).
    have_row = {(r["s"], r["slug"]) for r in shop_rows}
    for s_key, items in facts.items():
        for slug, fact in items.items():
            if (fact["role"] != "shelf" or fact["st"] != "noplan" or fact["why"] not in ("source", "priced")
                    or (int(s_key), slug) in have_row):
                continue
            business = businesses[int(s_key)]
            line = next((l for l in business["lines"] if l["slug"] == slug), None)
            target, source = target_at.get((business["key"], slug), (0, None))
            shop_rows.append({
                "s": int(s_key), "item": line["item"] if line else names.label(slug), "slug": slug,
                "sold": 0, "peakSold": 0, "peakDay": None, "target": target, "pressure": None,
                "stock": line["units"] if line else 0,
                "from": fact.get("from", index.get(source) if source else None),
                "level": "critical" if fact["lvl"] == "critical" else "warn",
            })
    factories.pop("_ramp", None)
    # The factory view's rows carry their fact's verdict: `status`, `why` and
    # `level` in 24/7 sizing, and under `dem` what Demand sizing changes.
    for site in factories.get("sites", []):
        for row in site["needs"]:
            fact = facts.get(str(site["s"]), {}).get(row["slug"])
            if not fact:
                continue
            row["status"], row["why"], row["level"] = fact["st"], fact["why"], fact["lvl"]
            # A depot of yours holds it and no plan sends it on: Not routed
            # says so, naming this factory, and the input's own finding gives
            # way to it, as a shelf's does.
            if fact.get("via") is not None:
                row["via"] = fact["via"]
            row["raiseTarget"] = (fact["setTo"] if row["target"] and fact["cad"] == "daily"
                                  else None)
            # The factory's own contract, paused while the top-up falls short
            # without it: the input's finding names it as the other way out,
            # in each sizing (Demand's under `dem`).
            def own_paused(own):
                return bool(own) and own.get("st") == "paused" and own.get("lvl") != "info"
            paused_cap = own_paused(fact.get("import"))
            paused_dem = own_paused((fact.get("dem") or {}).get("import", fact.get("import")))
            if paused_cap:
                row["ownPaused"] = True
            at = row["importSite"] if row["importSite"] is not None else site["s"]
            upstream_fact = facts.get(str(at), {}).get(row["slug"]) or {}
            row["raiseImport"] = (upstream_fact.get("setTo")
                                  if upstream_fact.get("cad") == "weekly" else None)
            dem = fact.get("dem")
            if dem:
                row["dem"] = {name: dem[field] for field, name in (
                    ("st", "status"), ("why", "why"), ("lvl", "level"), ("use", "use"),
                    ("setTo", "setTo")) if field in dem}
            if paused_dem != paused_cap:
                row.setdefault("dem", {})["ownPaused"] = paused_dem

    # --- 4. the chain as a graph, with what each node holds against what it needs
    COLUMN = {"import": 0, "factory": 1, "depot": 2, "shop": 3}
    nodes, links = {}, []

    def node(key, name, kind, tag="", hood="", sub=""):
        if key not in nodes:
            nodes[key] = {
                "id": key,
                "name": name,
                "kind": kind,
                "col": COLUMN[kind],
                "tag": tag,
                "hood": hood,
                "sub": sub,
                "items": [],
                "site": index.get(key),
            }
        return nodes[key]

    def kind_of(business):
        if business["status"] == "retail":
            return "shop"
        if "factory" in (business["typeSlug"] or ""):
            return "factory"
        return "depot"

    for business in businesses:
        if business["status"] == "vacant":
            continue
        node(
            business["key"],
            business["name"],
            kind_of(business),
            business["code"],  # prefix or table-derived, like the site badge
            business["neighbourhood"],
            business["type"],
        )

    # What each contract brings in an ordinary week, for the pipe's width. A
    # plain contract brings its amount. A Smart Delivery one brings only the
    # top-up, max(0, level - stock on Monday), and in a steady week the stock
    # on Monday is the level less what the week used, so the top-up is the
    # week's use, up to the level. The use is the depot row's own draw (the
    # delivery log, else the shops' sales, else last week's order); a line with
    # no row takes what arrived last week, which is measured too. Today's stock
    # would be a worse guide: it is only the Monday figure on a Monday.
    # Contracts sharing a line split that top-up in the game's delivery order.
    expected = {}
    for line, supply in imports.items():
        use = weekly_use.get(line, supply["arrived"])
        for group in ("active", "paused"):
            drops = supply["drops"][group]
            stock = max(0, _import_drop(0, drops) - use)
            for drop in drops:
                brought = _import_drop(stock, [drop])
                expected[(drop["rank"][1], line)] = brought
                stock += brought

    # Importers sit outside the company: they are where the week's goods enter.
    for order, partnership in enumerate(save.items(save.root["importPartnerships"])):
        source = save.address(partnership.get("importAddress"))
        if not source:
            continue
        source_key = "import:" + site_key(source)
        arrives = partnership.get("nextDeliveryDay") or 0
        node(
            source_key,
            names.addr(source),
            "import",
            "",
            "",
            "Weekly import" if partnership.get("isActive") else "Import paused",
        )
        moved = collections.defaultdict(lambda: [0, 0, set()])
        for product in save.items(partnership["products"]):
            warehouse = site_key(save.address(product["assignedWarehouse"]))
            amount = product.get("amount", 0)
            if warehouse not in nodes or not amount:
                continue
            entry = moved[warehouse]
            entry[0] += expected.get((order, (warehouse, product["itemName"])), amount)
            entry[1] += 1
            entry[2].add(product["itemName"])
        for warehouse, (amount, count, slugs) in moved.items():
            links.append(
                {
                    "from": source_key,
                    "to": warehouse,
                    "perDay": round(amount / 7),
                    "items": count,
                    # What the pipe carries, so a phone's chain can colour
                    # the one pipe a stalled or short product rides.
                    "slugs": _in_order(slugs),
                    "cadence": "weekly",
                    "paused": not partnership.get("isActive"),
                    "arrives": arrives,
                }
            )

    for source, destinations in edges.items():
        if source not in nodes:
            continue
        moved = collections.defaultdict(lambda: [0.0, 0, set()])
        for dest_key, item, _target in destinations:
            if dest_key not in nodes:
                continue  # a pier: that is an export, not an internal move
            entry = moved[dest_key]
            entry[0] += draw(dest_key, item)
            entry[1] += 1
            entry[2].add(item)
        for dest_key, (per_day, count, slugs) in moved.items():
            links.append(
                {
                    "from": source,
                    "to": dest_key,
                    "perDay": round(per_day),
                    "items": count,
                    "slugs": _in_order(slugs),
                    "cadence": "daily",
                    "paused": False,
                    "arrives": None,
                }
            )

    # What each node holds, against what it has to cover before its next refill.
    shop_need = collections.defaultdict(dict)
    for row in shop_rows:
        shop_need[businesses[row["s"]]["key"]][row["item"]] = row
    depot_need = collections.defaultdict(dict)
    for row in import_rows:
        depot_need[businesses[row["s"]]["key"]][row["item"]] = row
    # A factory's inputs are judged by the factory view against what its
    # machines eat; its outputs are made on the spot and need no refill.
    feed_need, made_here = {}, set()
    for site in factories.get("sites", []):
        key = businesses[site["s"]]["key"]
        made_here |= {(key, line["slug"]) for line in site["lines"]}
        for row in site["needs"]:
            feed_need[(key, row["slug"])] = row

    for business in businesses:
        entry = nodes.get(business["key"])
        if not entry:
            continue
        weekly = beat(business)
        factor, _peak_day = peak_of(business)
        for line in business["lines"]:
            # A ticket is issued at the booth, never held: no stock, need or
            # refill belongs on the node (issue #159).
            if line.get("issued"):
                continue
            shop = shop_need[business["key"]].get(line["item"])
            depot = depot_need[business["key"]].get(line["item"])
            own = (business["key"], line["slug"])
            feed = feed_need.get(own)
            # An input a line here makes for another, with no route bringing
            # it in, is made on the spot rather than missing a plan.
            if (feed and not feed["target"] and not feed["directImport"]
                    and index[business["key"]] in feed["madeAt"]):
                feed = None
            # Made here, unless something else claims the row: a shelf, a depot
            # line, or a live import of it, even one with no week behind it yet.
            # A paused or zeroed contract claims nothing, and the depot row its
            # history leaves behind is no refill of something made on the spot.
            # An intermediate eaten here keeps it: its feed row reads the
            # measured onward draw from it.
            ordered = (imports.get(own) or {}).get("weekly", 0)
            if own in made_here and not ordered and not feed:
                depot = None
            made = not (feed or shop or depot or ordered) and own in made_here
            fit = why = None
            backed = keeps = False
            if shop and shop.get("wholesale") and not shop["target"]:
                # A wholesale store delivers the week: the sales to its next
                # drop against what the delivery brings.
                deal = wholesale[(business["key"], line["slug"])]
                need = round(shop["sold"] * (deal["days"] or 0))
                provision = deal["weekly"]
                cycle_need, cadence = round(shop["sold"] * 7), "weekly"
            elif shop:
                need = shop["peakSold"]
                provision = shop["target"]
                # A shelf is refilled daily, so a day's peak is the whole test.
                cycle_need, cadence = need, "daily"
            elif feed and feed["target"] and not feed["directImport"]:
                # Topped up each morning: the next refill is tomorrow's round, so
                # a day of the machines is the test, with the factory view's
                # slack. The depot's import is judged on the depot.
                need, provision = feed["perDay"], feed["target"]
                cycle_need, cadence = need, "daily"
                fit = "short" if provision < feed["dailyNeed"] * (1 - FEED_SLACK) else "ok"
            elif feed and feed["directImport"]:
                # Imported straight to the factory: the week's order has to feed
                # the machines here, the factories topped up from here, and
                # anything measured leaving onward. Machines run flat, so the
                # hours to the drop need no weekday walk. A drop due now leaves
                # the next one a week out, as for a depot.
                supply = imports.get(own)
                due = (
                    max(supply["arrives"] - day - spent_today, 0.0)
                    if supply and supply["weekly"] else 0.0
                ) or 7.0
                onward = depot["perDay"] - depot.get("eats", 0) if depot else 0
                # The larger, not the sum: the measured draw already carries the
                # top-ups to other factories that depotNeed plans for. A starved
                # neighbour makes this an underestimate.
                per_day = max(feed["depotNeed"] / 7, feed["perDay"] + onward)
                need = round(per_day * due)
                provision = feed["directWeekly"] or 0
                cycle_need, cadence = round(per_day * 7), "weekly"
                # A target only fills up to its level, so beside an import that
                # covers the week it ships nothing until stock runs down; one
                # that covers a day of everything drawn here is a floor under the
                # week, and the holding cannot run dry before the drop.
                backed = bool(
                    feed["target"] and feed["target"] >= per_day * (1 - FEED_SLACK)
                )
                if feed["importPaused"]:
                    fit, why = "short", "paused"
                else:
                    # Past the order's own need, measured onward draw can only
                    # make the week longer, never shorter.
                    fit = max(feed["importFit"] or "ok", _fit(cycle_need, provision),
                              key=FIT_ORDER.index)
            elif feed:
                # Neither imported here nor topped up: nothing brings it in.
                need, provision = feed["perDay"], 0
                cycle_need, cadence = need, "daily"
                fit, why = "short", "unplanned"
            elif depot:
                # The import's share of the draw: what a route from the
                # company's own factory brings every morning is not its to cover.
                # A line a route helps feed carries what its own weekday walk
                # says the shelf must hold to the drop: quiet days' surplus
                # counts, a busy day's extra too.
                # Otherwise the row's own walk to its next drop: flat for a
                # line that feeds machines, the weekday profile for one that
                # feeds shelves, and whole rounds where the draw is the rounds.
                if depot["routed"]:
                    need = depot["carry"]
                else:
                    need = depot["dueNeed"]
                provision = depot["weekly"]
                # A Smart Delivery level is what the depot keeps, not what a
                # refill brings: that is the level less the stock on the day.
                keeps = bool(depot.get("smart"))
                # The order arrives weekly, so it has to cover a week — comparing
                # it with the days left until the next one would flatter it.
                cycle_need, cadence = round(depot["importPerDay"] * 7), "weekly"
            elif made:
                need = provision = cycle_need = 0
                cadence = "made"
            elif ordered and own in made_here:
                # An output made here and imported too, before any draw or order
                # history gives it a depot row: the order is known, the need not.
                need = cycle_need = 0
                provision, cadence = ordered, "weekly"
            else:
                out = draw(business["key"], line["slug"])
                if out <= 0 and line["units"] <= 0:
                    continue
                target = next(
                    (
                        amount
                        for (dest, item), (amount, _src) in target_at.items()
                        if dest == business["key"] and item == line["slug"]
                    ),
                    0,
                )
                need = round(out * factor)
                provision, cycle_need, cadence = target, need, "daily"
            if not need and not line["units"] and not provision:
                continue
            # A factory input carries the verdict set above, which follows the
            # factory view's sizing checks: a thin week of arrivals is a
            # delivery question, not whether the order covers a cycle. A depot
            # line already carries its verdict, weekday-walked and withheld
            # where no draw has been measured; do not second-guess it.
            if fit is None:
                fit = depot["orderFit"] if depot else _fit(cycle_need, provision)
            # The verdict is the fact's: one word for the (site, item),
            # whichever view shows it.
            fact = facts.get(str(index[business["key"]]), {}).get(line["slug"])
            if fact:
                fit = NODE_FIT.get(fact["st"], "ok")
            entry["items"].append(
                {
                    "item": line["item"],
                    "slug": line["slug"],
                    "st": fact["st"] if fact else None,
                    "stock": line["units"],
                    "need": need,
                    "cycleNeed": cycle_need,
                    "provision": provision,
                    "cadence": cadence,
                    "made": made,
                    "keeps": keeps,
                    "why": why,
                    "fit": fit,
                    "short": fit == "short",
                    # Only worth flagging where the next refill is days away. A
                    # half-empty shelf at teatime is tomorrow morning's business.
                    "low": bool(
                        cadence == "weekly" and need and line["units"] < need and not backed
                    ),
                }
            )
        rank = {"short": 0, "tight": 1, "ok": 2}
        entry["items"].sort(
            key=lambda i: (rank[i["fit"]], not i["low"], -i["need"])
        )
        entry["short"] = sum(1 for i in entry["items"] if i["fit"] == "short")
        entry["tight"] = sum(1 for i in entry["items"] if i["fit"] == "tight")
        entry["low"] = sum(1 for i in entry["items"] if i["low"])
        entry["stock"] = sum(i["stock"] for i in entry["items"])

    for entry in nodes.values():
        entry.setdefault("tight", 0)
        entry.setdefault("short", 0)
        entry.setdefault("low", 0)
        entry.setdefault("stock", 0)

    # A site earns a place on the diagram by being on a plan or by holding
    # something worth drawing. Head office keeps a dozen paper bags in a drawer;
    # that is not a depot.
    reached = {l["from"] for l in links} | {l["to"] for l in links}
    graph = {
        "nodes": [
            n
            for n in nodes.values()
            if n["id"] in reached or n["stock"] >= GRAPH_MIN_STOCK
        ],
        "links": links,
    }

    return {
        "day": day,
        "today": weekday(day),
        "graph": graph,
        "nextImportDay": next_day,
        "nextImportWeekday": weekday(next_day) if next_day else None,
        "daysToImport": days_to_import,
        "hoursToImport": round(hours_to_import, 2)
        if hours_to_import is not None
        else None,
        "leftToday": round(left_today, 3),
        "shops": shop_rows,
        # The shops a repeating wholesale contract delivers to: a standing
        # supply that draws no link on the graph.
        "wholesaleShops": sorted({index[shop] for shop, _item in wholesale}),
        # The (shop index, product) pairs a plan or a wholesale contract really
        # delivers: a stock target above zero, or a repeating contract, whatever
        # the shop's sales rate. shops[] holds a row only for a selling line.
        "routed": sorted(
            [index[shop], item]
            for shop, item in (
                {k for k, (amount, _src) in target_at.items() if amount > 0}
                | set(wholesale)
            )
            if shop in index
        ),
        "imports": import_rows,
        # The same rows walked in Demand sizing (the page's supplyImports()).
        "importsDem": import_rows_dem,
        "idle": idle_rows,
        "idleWeeks": IDLE_WEEKS,
        "factories": factories,
        "facts": facts,
        "margin": SUPPLY_MARGIN,
        "roundTo": SUPPLY_ROUND_TO,
    }


def _below(have, figure) -> bool:
    """Whether `have` falls short of `figure` by more than rounding: 1% of the
    figure, or FIT_FLOOR units on a small one. Consumption is measured, not
    declared, so two figures this close are the same figure."""
    return bool(figure) and figure - (have or 0) > max(figure * FIT_NOISE, FIT_FLOOR)


def _supply_status(p: dict) -> tuple:
    """One supply fact's status word, the reason behind it and its severity:
    (st, why, lvl). The probe `p` says what is true of the fact; the first row
    of the table that matches wins, so each fact has one word however many
    things are true of it.

    made    -- made at this site, with nothing to import (`made`)
    paused  -- the import is paused and no route covers it (`paused`):
               critical, or warn while the stock holds a week (`cover` >= 7)
    noplan  -- nothing brings it (`noplan` is the why: target for a shelf or
               a factory input, order for a depot; severity `noplanLvl`)
    new     -- too young to judge (`young` is the why: young or firstFill)
    short   -- `short` lists what falls short, most telling first: order,
               shortfall (cover to the drop), target, dry (a wholesale shelf
               puts shortfall before order); critical, or
               `shortLvl` (a wholesale order whose stock reaches the drop: warn)
    stalled -- planned, the source holds it, little arrives, and neither a
               Produce up to limit nor staffing explains it (`stalled`:
               notDrawn, or waiting for another input, which is info)
    idle    -- stock not moving on (`idle` is the why, `idleLvl` the severity)
    tight   -- covers the use but not the margin (`tight` is the why); tight
               is never a finding on Today
    covered -- everything else; `covered` names why where a reason other than
               the figure itself holds it: route, limit or staffing
    """
    if p.get("made"):
        return "made", None, "ok"
    if p.get("paused"):
        return "paused", "order", "warn" if p.get("cover", 0) >= 7 else "critical"
    if p.get("noplan"):
        return "noplan", p["noplan"], p.get("noplanLvl", "critical")
    if p.get("young"):
        return "new", p["young"], "info"
    if p.get("short"):
        return "short", p["short"][0], p.get("shortLvl", "critical")
    if p.get("stalled"):
        return "stalled", p["stalled"], "info" if p["stalled"] == "waiting" else "warn"
    if p.get("idle"):
        return "idle", p["idle"], p.get("idleLvl", "info")
    if p.get("tight"):
        return "tight", p["tight"], "warn"
    return "covered", p.get("covered"), "ok"


def _week_sold(business: dict, line: dict) -> float:
    """What a shelf sells a week: _business's weekSold, or, on a hand-built
    line without it, seven days at its trading-day rate."""
    if "weekSold" in line:
        return line["weekSold"]
    return line.get("tradeRate", line["rate"]) * 7


SET_WORDS = ("short", "tight", "noplan")  # the words whose fact carries a figure to set


def _mode_changes(base: dict, other: dict) -> dict:
    """What another sizing mode changes on a record, as the overlay the page
    spreads over it ({...base, ...changes}): the fields that differ, and None
    for a field the other mode leaves out, so a 24/7-only field (a second
    plan to raise, how long stock lasts) never shows through in Demand."""
    changed = {k: v for k, v in other.items() if base.get(k) != v}
    changed.update({k: None for k in base if k not in other and base[k] is not None})
    return changed


def _supply_fact(facts: dict, s, slug: str, mode: str = "cap") -> dict | None:
    """One fact as the chosen sizing mode sees it: the 24/7 fields with the
    Demand mode's changes laid over them (the page's supplyFact())."""
    fact = facts.get(str(s), {}).get(slug)
    if fact and mode == "dem" and fact.get("dem"):
        return {**{k: v for k, v in fact.items() if k != "dem"}, **fact["dem"]}
    return fact


def _supply_facts(ctx: dict) -> dict:
    """{site index: {slug: fact}}: one fact per (site, item) held, needed or
    planned, each with one status word (_supply_status) and the figures behind
    it. The base fields are 24/7 sizing; `dem` carries only the fields Demand
    sizing changes, and is left off where it changes nothing.

    A shelf is judged on its daily top-up against its busiest day's sales, or,
    fed by a weekly wholesale delivery contract instead, on the contract's
    amount against a week of sales. A
    factory input topped up each morning is judged on that top-up against a
    day of its machines, and on what arrives. A line an import brings (a
    depot's, or a factory's own) is judged on the week: what the ends use,
    summed up the plan to the import (`parts`: the factory lines, the other
    sites, less what a route brings), against what a week's delivery brings,
    and on whether the stock reaches the next drop. `need` adds the margin
    once over the chain; 24/7 sizing sizes factory lines at capacity, with no
    margin. `setTo` is the figure to set in game, rounded up to
    SUPPLY_ROUND_TO with a Smart Delivery level found by replaying the pass;
    None where nothing needs to change.

    Units: `use`, `need`, `have`, `setTo` and `lower` are a week's on a fact
    with `cad` weekly (an import brings it: a depot line, a factory input
    imported direct, a factory's own contract under `import`; or a shelf on a
    wholesale contract), and a day's otherwise (a shelf's or a depot's daily
    top-up, a factory input topped up each morning). `parts` is always a
    week's, and only on a week's facts (the page's szWeekly()).

    "New" holds back the verdicts a history too short cannot back: a shelf's
    use is its sales, so a shop under MIN_TRADE_DAYS is new; a factory
    input's need is its machines', known from the first day, so its top-up is
    judged at once and only what the log says (stalled, idle) waits.
    """
    businesses, index = ctx["businesses"], ctx["index"]
    factories = ctx["factories"]
    target_at = ctx["targets"]
    sourced = ctx.get("sourced", lambda _key, _item: True)
    # Business type -> its whole default price list, and every item sold as
    # goods anywhere (_type_ranges(): a fee is never stocked).
    catalogue, goods = ctx.get("catalogue", ({}, set()))
    # {(shop, item): [(site, target), ...]}: every plan that tops a line up.
    top_ups = collections.defaultdict(list)
    for (source, legs) in ctx.get("edges", {}).items():
        for dest, item, amount in legs:
            if source in index and dest != source:
                top_ups[(dest, item)].append((source, amount or 0))
    wholesale = ctx.get("wholesale", {})
    ramp_at = factories.get("_ramp", {})
    depots = factories.get("depots", {})
    route_only = factories.get("depotRoutes", {})
    # The chain walked from the sources in each sizing mode (_supply_walk()),
    # and what each site holds.
    walked = ctx.get("walk", {})
    stocks = ctx.get("held", {})
    idle = ctx.get("idle", {})
    extra = ctx.get("extra", {})
    import_rows_by = {
        "cap": {(r["s"], r["slug"]): r for r in ctx["import_rows"]},
        "dem": {(r["s"], r["slug"]): r for r in ctx.get("import_rows_dem", ctx["import_rows"])},
    }
    inputs, outputs = {}, {}
    for site in factories.get("sites", []):
        key = businesses[site["s"]]["key"]
        for row in site["needs"]:
            inputs[(key, row["slug"])] = row
        for line in site["lines"]:
            outputs[(key, line["slug"])] = line

    def behind(node, slug, stock, per_day):
        """How long what is held lasts at `per_day`: the site's own stock and
        what the sites topping it up with nothing coming in hold (they only
        pass it on), as (days, the first such sender holding any, or None).
        Stock never sizes a standing supply; it only says how soon a missing
        one bites: under LASTS_WEEK days is critical, longer a warning."""
        passing = [sender for sender in node.get("passing", ())
                   if stocks.get(sender, {}).get(slug, 0) > 0]
        held_here = stock + sum(stocks[sender][slug] for sender in passing)
        days = held_here / per_day if per_day > 0 else 999.0
        return days, (passing[0] if passing else None)

    def graded(days):
        return "critical" if days < LASTS_WEEK else "warn"

    def said_downstream(node, slug, use):
        """Whether every site asking this one for the item says what it
        lacks itself: a depot (its import is short, or its own fact asks for
        one) or a site with an import of its own; a shelf or a factory line
        does not. Then this one's missing supply is a note, said once there."""
        passed = sum(asked[0] for dest, asked in node.get("asked", {}).items()
                     if (depots.get(index.get(dest), {}).get(slug) or {}).get("weekly")
                     or (dest in index and (dest, slug) not in inputs
                         and businesses[index[dest]]["status"] != "retail"))
        return use - 7 * passed <= 0.5

    def upstream_asks(sender, slug, mode, seen=frozenset()):
        """Whether what `sender` cannot send is asked for further up: it has
        a live import of its own (whose fact is judged on the whole chain's
        need, this one's share included), or every site with anything coming
        in that tops it up is such a site in turn."""
        if sender in seen or sender not in index:
            return False
        if (depots.get(index[sender], {}).get(slug) or {}).get("weekly"):
            return True
        node = walked.get(mode, {}).get((sender, slug)) or {}
        able = [s for s in node.get("senders", ()) if s not in node.get("passing", ())]
        return bool(able) and all(upstream_asks(s, slug, mode, seen | {sender}) for s in able)

    def upstream_root(sender, slug, mode, seen=frozenset()):
        """The site whose import is short, where upstream_asks() bottoms out."""
        if sender in seen or sender not in index:
            return sender
        if (depots.get(index[sender], {}).get(slug) or {}).get("weekly"):
            return sender
        node = walked.get(mode, {}).get((sender, slug)) or {}
        able = [s for s in node.get("senders", ()) if s not in node.get("passing", ())]
        return upstream_root(able[0], slug, mode, seen | {sender}) if able else sender

    def route_short(key, slug, node, mode):
        """Whether a depot only routes feed has senders that cannot bring
        its day's use (several: multi_route() finds no target to raise and
        the room short), so nothing brings the rest (route_fed())."""
        use_day = node.get("use", 0.0)
        if not use_day:
            return False
        if len(node.get("routeTargets") or {}) > 1:
            return multi_route(key, slug, node, use_day, node.get("need", 0.0)) is None
        made = ctx.get("made", {}).get(mode, {}).get((key, slug), 0.0)
        return _below(node.get("supplied", 0.0) + made, use_day)

    def asks_itself(dest, slug, mode):
        """Whether `dest`, a depot only routes feed, asks for an import of its
        own for what its senders cannot bring: short of supply, with a sender
        whose shortfall no import further up asks for (route_fed())."""
        if dest not in index:
            return False
        s = index[dest]
        entry = depots.get(s, {}).get(slug)
        if (entry and (entry.get("weekly") or entry.get("pausedWeekly"))) or wholesale.get((dest, slug)):
            return False
        node = walked.get(mode, {}).get((dest, slug)) or {}
        if not node.get("inbound") or not route_short(dest, slug, node, mode):
            return False
        able = [x for x in node.get("senders", ()) if x not in node.get("passing", ())]
        return not (able and all(upstream_asks(x, slug, mode) for x in able))

    def weekly(key, slug, mode, stock):
        """A line an import brings, judged on its week: what the ends use,
        summed up the plans (the chain's walk, `walk`), less what the routes
        from your own sites bring, against what a week's delivery brings."""
        s = index[key]
        entry = depots.get(s, {}).get(slug)
        node = walked.get(mode, {}).get((key, slug)) or {}
        lines_use, lines_need = (7 * x for x in node.get("lines", (0.0, 0.0)))
        sites_use, sites_need = (7 * x for x in node.get("sites", (0.0, 0.0)))
        # A depot this one's import tops up beside a sender with no import
        # behind it (a factory) asks for an import of its own for all it
        # lacks (route_fed()): this one's share of it is what the route
        # brings now, so the one gap is asked for once. (With no import
        # here, said_downstream() already makes this one a note.)
        # The ask comes off where the depot's own need lies: its factory
        # lines' and its sites' parts, in the depot's own proportions.
        for dest, (asked_use, asked_need) in node.get("asked", {}).items():
            if (entry or {}).get("weekly") and asks_itself(dest, slug, mode):
                dnode = walked.get(mode, {}).get((dest, slug)) or {}
                now = dnode.get("brings", {}).get(key, 0.0)
                (dlu, dln), (dsu, dsn) = dnode.get("lines", (0.0, 0.0)), dnode.get("sites", (0.0, 0.0))
                off_use, off_need = 7 * max(0.0, asked_use - now), 7 * max(0.0, asked_need - now)
                share_use = dlu / (dlu + dsu) if dlu + dsu > 0 else 0.0
                share_need = dln / (dln + dsn) if dln + dsn > 0 else 0.0
                lines_use -= off_use * share_use
                sites_use -= off_use * (1 - share_use)
                lines_need -= off_need * share_need
                sites_need -= off_need * (1 - share_need)
        lines_use, lines_need = max(0.0, lines_use), max(0.0, lines_need)
        sites_use, sites_need = max(0.0, sites_use), max(0.0, sites_need)
        gross, gross_need = lines_use + sites_use, lines_need + sites_need
        row = import_rows_by.get(mode, import_rows_by["cap"]).get((s, slug))
        # What the routes from your own sites bring a week, never more than
        # their targets and than their senders' supply lets them; covering
        # all of it, the import beside them is a backup and answers for none.
        routed = 7 * node.get("credit", 0.0)
        # Where the sites topping it up fall short only because a site
        # further up is short of its own import, that import is asked for the
        # whole chain: the route here is taken at what it asks of them (up to
        # its target), so the same gap is never asked for twice.
        able = [s for s in node.get("senders", ()) if s not in node.get("passing", ())]
        upstream = bool(able) and all(upstream_asks(s, slug, mode) for s in able)
        routed_use = routed
        if upstream:
            asks = [node.get("demand", {}).get(s, (0.0, 0.0)) for s in able]
            routed = max(routed, 7 * min(node.get("targets", 0), sum(a[1] for a in asks)))
            routed_use = max(routed_use, 7 * min(node.get("targets", 0), sum(a[0] for a in asks)))
        # What lines at the site itself make of it comes off the week too.
        made = 7 * ctx.get("made", {}).get(mode, {}).get((key, slug), 0.0)
        covered = bool(node.get("covered"))
        brought = (entry or {}).get("weekly", 0) or 0
        paused = bool(entry and not brought and entry.get("pausedWeekly"))
        live = bool(entry and (brought or entry.get("pausedWeekly")))
        inbound = bool(node.get("inbound"))
        deal = wholesale.get((key, slug))
        if inbound and not live and not deal:
            return route_fed(key, slug, node, entry, stock, bool(lines_use), mode)
        # Where the routes cover the week the import is a backup and answers
        # for nothing, but its figures still show its planned share: what
        # the routes leave of the need (the margin, where they bring the
        # use), not a nought.
        use = round(max(0.0, gross - routed_use - made))
        need = round(max(0.0, gross_need - routed - made))
        parts = {"lines": round(lines_use), "sites": round(sites_use), "route": round(routed)}
        measured = row is not None
        if deal and not live:
            # A depot a wholesale store delivers each week: its contract is
            # judged against the week as an import is, and a top-up from your
            # own site comes off the week on top of it.
            brings = deal["weekly"]
            # A route that covers the week makes the contract a backup, as
            # beside an import: no word, only its share on show.
            p = {"short": ["order"] if use and not covered and _below(brings, use) else []}
            if need and not covered and _below(brings, need):
                p["tight"] = "order"
            if covered:
                p["covered"] = "route"
            return p, {
                "use": use, "need": need, "have": brings,
                "setTo": _ceil_ten(need) if need and not covered and _below(brings, need) else None,
                "parts": parts, "imp": False, "wholesale": True, "day": deal["day"],
            }, "weekly"
        p = {}
        if paused and use and not covered:
            p["paused"] = True
            p["cover"] = row["cover"] if row else (stock / (use / 7) if use else 60)
        elif not entry and use and not covered:
            # Nothing brings it here. Where every site it tops up has an
            # import of its own, that import is the one to raise (its fact
            # says so), and this is a note; so is stock holding the week.
            # A depot it tops up says what it lacks itself (its import is short,
            # or its own fact asks for one); a shelf or a factory line does not.
            # Where the site holds none and only shelves draw on it, each
            # shelf's own finding says so, naming this site (unsourced).
            shelves_say = not lines_use and not sourced(key, slug) and not any(
                stocks.get(dest, {}).get(slug, 0) > 0 for dest in node.get("asked", {}))
            said = shelves_say or said_downstream(node, slug, use)
            days, _passes = behind(node, slug, stock, use / 7)
            p["noplan"] = "order"
            # Stock never hides a missing supply: it only grades how soon.
            p["noplanLvl"] = "info" if said else graded(days)
            lasts = days
        short = []
        passes = None
        if entry and not paused and use and not covered and _below(brought, use):
            short.append("order")
            # How soon an order short of its week bites: what the depot and
            # the sites passing it their stock hold, drawn down by what the
            # order leaves short each day.
            lasts, passes = behind(node, slug, stock, (use - brought) / 7)
            p["shortLvl"] = graded(lasts)
        if measured and row["coverFit"] == "short":
            short.append("shortfall")
            p["shortLvl"] = "critical"
        p["short"] = short
        if entry and not paused and not covered and _below(brought, need):
            p["tight"] = "order"
        elif measured and row["coverFit"] == "tight":
            p["tight"] = "shortfall"
        if covered:
            p["covered"] = "route"
        set_to = None
        if not paused and need and not covered and (_below(brought, need) if entry else p.get("noplan")):
            set_to = _raise_import(entry, need) if entry else _ceil_ten(need)
        have = None
        if entry:
            have = (entry.get("target") if entry.get("smart")
                    else entry.get("pausedWeekly") if paused else brought)
        fields = {"use": use, "need": need, "have": have, "setTo": set_to,
                  "parts": parts,
                  "imp": bool(entry) or lines_use > 0 or (bool(p.get("noplan"))
                                                          and not said_downstream(node, slug, use))}
        if p.get("noplan") or "order" in short:
            # How long the stock lasts, and the route that only passes on
            # what its sender holds, for the finding to say.
            fields["lasts"] = round(lasts, 1)
            if passes is not None:
                fields["passes"] = index.get(passes)
        # A plain order well past the week is worth a word; a high Smart
        # Delivery level only holds stock, so it never is.
        if (entry and not entry.get("smart") and not paused and need and not covered
                and brought > need * 1.5 and not _below(brought, need)):
            fields["lower"] = _ceil_ten(need)
        return p, fields, "weekly"

    def route_fed(key, slug, node, entry, stock, lines, mode):
        """A depot topped up each morning from another of your sites, with no
        import bringing it (a contract set to zero at most). Where its senders
        can send all it uses (their own imports, their machines, what routes
        bring them: `supplied`), the route is the whole of its supply and it
        is judged as a shelf is, on that top-up against its busiest day's use
        (cad daily). Where they cannot, what comes in is less than what goes
        out: nothing brings the rest, and the fact asks for an import of it
        (noplan, cad weekly), whatever they hold, since a holding runs out and
        a standing order does not; only the severity reads what they hold."""
        use_day, need_day = node.get("use", 0.0), node.get("need", 0.0)
        several = len(node.get("routeTargets") or {}) > 1
        if several:
            got = multi_route(key, slug, node, use_day, need_day)
            if got is not None:
                return got
        if route_short(key, slug, node, mode):
            made = ctx.get("made", {}).get(mode, {}).get((key, slug), 0.0)
            credit = node.get("credit", 0.0) + made
            lines_use = 7 * node.get("lines", (0.0, 0.0))[0]
            use = round(max(0.0, use_day - credit) * 7)
            need = round(max(0.0, need_day - credit) * 7)
            days, passes = behind(node, slug, stock, use / 7)
            # The senders with anything coming in fall short because a site
            # further up is short, and that site's own import is judged on
            # this one's need too: it asks, once. Here the route is judged on
            # its target alone (a target too small is a finding of its own,
            # which no import further up can fix), and otherwise the fact is
            # a note naming that site (why upstream).
            able = [s for s in node.get("senders", ()) if s not in node.get("passing", ())]
            if able and all(upstream_asks(s, slug, mode) for s in able):
                if several:
                    # multi_route() found the targets hold the day: only the
                    # supply behind them is short, and it asks there.
                    factor, _day = ctx["peak"](businesses[index[key]])
                    biggest = max(able, key=lambda s: ((node.get("room") or {}).get(s) or 0.0, s))
                    return {"noplan": "upstream", "noplanLvl": "info", "short": []}, {
                        "use": round(use_day * factor), "need": round(need_day * factor),
                        "have": max(node["routeTargets"].values()), "setTo": None, "imp": False,
                        "from": index.get(upstream_root(biggest, slug, mode))}, "daily"
                p, fields, cad = daily_route(key, slug, node, use_day, need_day)
                if not p.get("short") and not p.get("tight"):
                    p = {"noplan": "upstream", "noplanLvl": "info", "short": []}
                    fields["from"] = index.get(upstream_root(able[0], slug, mode))
                return p, fields, cad
            p = {"noplan": "order", "short": [],
                 "noplanLvl": "info" if said_downstream(node, slug, use) else graded(days)}
            set_to = (_raise_import(entry, need) if entry else _ceil_ten(need)) if need else None
            return p, {
                "use": use, "need": need, "setTo": set_to,
                "have": (entry.get("target") if entry.get("smart") else 0) if entry else None,
                "parts": {"lines": round(lines_use), "sites": round(7 * use_day - lines_use),
                          "route": round(7 * credit)},
                # An import to add is an import line, where this site is the
                # one that asks for it (not a depot further down): Weekly
                # imports lists it.
                "imp": bool(entry) or lines or not said_downstream(node, slug, use),
                "lasts": round(days, 1),
                **({"passes": index.get(passes)} if passes is not None else {}),
            }, "weekly"
        return daily_route(key, slug, node, use_day, need_day)

    def multi_route(key, slug, node, use_day, need_day):
        """A route-fed depot several sites top up, as two questions.

        Targets are levels: each morning round tops the line up TO its
        target from what its sender has room for, so the line holds no more
        than the highest target, and no more than the senders bring on top
        of one another. (a) The targets, on the busiest day: with every
        sender that has anything coming in taken as unlimited, does the
        highest target hold the busiest day's need? (b) The supply, on an
        average day: do the senders have room for the day (what each can
        spare less what its other routes ask), and, replayed as levels in
        both orders within that room, do the rounds hold the day?

        Targets short on either count are a top-up finding, naming every
        sender whose target has to rise (the fewest, those with the most
        room first, whose room between them brings an average day's need:
        the week's stock behind it carries the busy day) and the level each
        rises to: the busiest day's need, which then holds the day whichever
        order the rounds run in. Room short with the targets
        holding is no target finding: returns None, and route_fed() says
        it as the supply's (the senders' own import or line findings ask).
        Otherwise covered, holding what the rounds bring."""
        factor, _day = ctx["peak"](businesses[index[key]])
        use, need = round(use_day * factor), round(need_day * factor)
        targets = node.get("routeTargets") or {}
        room = node.get("room") or {}
        capable = [s for s in _in_order(targets) if room.get(s) is None or room[s] > 0]
        cap = {s: float("inf") if room.get(s) is None else room[s] for s in capable}
        # Supply is judged on the day's use, as one sender's is (route_fed()):
        # room short of only the margin is no missing supply, and a leftover
        # plan from a site with nothing coming in changes nothing.
        enough = not _below(sum(cap.values()), use_day)

        def replay(levels):
            held = []
            for order in (capable, capable[::-1]):
                level = 0.0
                for sender in order:
                    level = max(level, min(levels[sender], level + cap[sender]))
                held.append(level)
            return min(held) if held else 0.0

        top = max((targets[s] for s in capable), default=0)
        held = replay(targets)
        short = bool(use and (_below(top, use) or (enough and _below(held, use_day))))
        tight = not short and bool(need and (_below(top, need) or (enough and _below(held, need_day))))
        if short or tight:
            level = _ceil_ten(need)
            chosen, room_sum = [], 0.0
            for sender in sorted(capable, key=lambda s: (-cap[s], -targets[s], s)):
                if chosen and not _below(room_sum, need_day):
                    break
                chosen.append(sender)
                room_sum += cap[sender]
            raise_ = [sender for sender in chosen if targets[sender] < level]
            if raise_:
                p = {"short": ["target"]} if short else {"short": [], "tight": "target"}
                first = raise_[0]
                return p, {"use": use, "need": need, "have": targets[first], "setTo": level, "imp": False,
                           "from": index.get(first),
                           **({"raise": [[index.get(sender), targets[sender], level] for sender in raise_[1:]]}
                              if len(raise_) > 1 else {})}, "daily"
        if not enough:
            return None
        # Covered: what the line holds after the rounds, never a target a
        # sender cannot fill (a 10,000 target from a line making 720).
        biggest = max(capable, key=lambda s: (cap[s], targets[s], s)) if capable else None
        return {"short": [], "covered": "route"}, {
            "use": use, "need": need, "have": round(min(held, max(targets.values()))), "setTo": None,
            "imp": False, "from": index.get(biggest)}, "daily"

    def daily_route(key, slug, node, use_day, need_day):
        """A route-fed depot's daily top-up against its busiest day's use."""
        factor, _day = ctx["peak"](businesses[index[key]])
        use, need = round(use_day * factor), round(need_day * factor)
        top = node.get("targets") or node.get("reach") or target_at[(key, slug)][0]
        source = target_at[(key, slug)][1]
        p = {"short": []}
        if use and _below(top, use):
            p["short"].append("target")
        elif need and _below(top, need):
            p["tight"] = "target"
        else:
            p["covered"] = "route"
        set_to = _ceil_ten(need) if need and _below(top, need) else None
        # `from`: the site whose plan sends the top-up, which Orders names.
        return p, {"use": use, "need": need, "have": top, "setTo": set_to, "imp": False,
                   "from": index.get(source)}, "daily"

    def daily_input(key, row, mode):
        """A factory input topped up each morning, judged on a day of its machines."""
        cap_day = row["perDay"]
        use_day = cap_day if mode == "cap" else row.get("demDay", cap_day)
        need_day = use_day if mode == "cap" else min(use_day * (1 + SUPPLY_MARGIN), cap_day)
        use, need = round(use_day), round(need_day)
        target = row["target"]
        p = {"short": []}
        if not target:
            if index[key] in row["madeAt"]:
                p["made"] = True
            else:
                p["noplan"], p["noplanLvl"] = "target", "critical"
        elif _below(target, use):
            p["short"].append("target")
        young = bool(row.get("firstFill"))
        if target and young and not p["short"]:
            p["young"] = "firstFill"
        if target and not young and row["known"] and row["arrives"] < use_day * LINE_STARVED:
            staffed = use_day * row.get("staffedShare", 1.0)
            if row["waitingOn"]:
                p["stalled"] = "waiting"
            elif row["arrives"] >= staffed * 0.85:
                p["covered"] = "staffing"
            elif row["depotStock"] < use_day:
                p["short"].append("dry")
            elif row.get("limited"):
                p["covered"] = "limit"
            else:
                p["stalled"] = "notDrawn"
        if target and _below(target, need):
            p["tight"] = "target"
        set_to = (_ceil_ten(need) if need and (not target or _below(target, need))
                  and not p.get("made") else None)
        return p, {"use": use, "need": need, "have": target, "setTo": set_to, "imp": False}

    def shelf(business, line):
        """A shop's shelf, judged on its daily top-up against its busiest day,
        or, where a wholesale store delivers it each week and no top-up does,
        on the week: the order against a week of sales, and the stock against
        the days to the drop. Returns (probe, fields, cadence)."""
        key, slug = business["key"], line["slug"]
        rate = line.get("tradeRate", line["rate"])
        target = target_at.get((key, slug), (0, None))[0]
        young = rate > 0 and business.get("tradeDays", MIN_TRADE_DAYS) < MIN_TRADE_DAYS
        deal = wholesale.get((key, slug))
        if deal and not target:
            week = max(_week_sold(business, line), 0.0)
            use = round(week)
            need = round(week * (1 + SUPPLY_MARGIN))
            have = deal["weekly"]
            p = {"short": []}
            # Running out before the delivery is the more telling of the two,
            # so it comes first where the order is short of the week too.
            if rate > 0 and deal["days"] and _below(line["units"], rate * deal["days"]):
                p["short"].append("shortfall")
            if use and _below(have, use):
                p["short"].append("order")
            # A young shop is too new to judge, unless what it has already
            # sold outruns what comes in: that is said at once.
            if young and not p["short"]:
                p["young"] = "young"
            # An order under the week is a warning while the stock reaches the
            # next drop; the stock running out before it is critical.
            p["shortLvl"] = "critical" if "shortfall" in p["short"] else "warn"
            if need and _below(have, need):
                p["tight"] = "order"
            set_to = _ceil_ten(need) if need and _below(have, need) else None
            fields = {"use": use, "need": need, "have": have, "setTo": set_to,
                      "parts": {"lines": 0, "sites": use, "route": 0}, "imp": False,
                      "wholesale": True, "day": deal["day"]}
            if "shortfall" in p["short"]:
                # What to bring in by hand to reach the delivery.
                fields["catchUp"] = math.ceil(rate * deal["days"] - line["units"])
            return p, fields, "weekly"
        factor, _day = ctx["peak"](business)
        peak = rate * factor if rate > 0 else 0.0
        use = round(peak)
        need = round(peak * (1 + SUPPLY_MARGIN))
        p = {"short": []}
        extra_fields = {}
        # Every site whose plan tops this shelf up, the highest target first.
        sources = [sender for sender, _t in sorted(top_ups.get((key, slug), ()), key=lambda st: (-st[1], st[0]))]
        stockable = isinstance(slug, str) and slug and not line.get("issued") and not deal
        # Every shop's price list holds its type's whole catalogue at the
        # game's default prices, so a price says the player wants to sell it
        # only for goods outside that catalogue (a burger bar in a gym). A
        # type whose catalogue is not known is given no such reading.
        own_range = catalogue.get(business.get("typeSlug"))
        added = bool(own_range) and slug not in own_range and slug in goods
        priced = line.get("configuredPrice", line.get("price") or None) is not None
        if (stockable and target and sources and not line["units"]
                and not any(sourced(src, slug) for src in sources)):
            # Nothing upstream supplies it: no site that tops it up holds any,
            # imports it (a paused contract counts), makes it or is brought it
            # by a route, and the shelf is empty. Whatever the shop's type,
            # age or sales, it is said: critical where it has been selling.
            p["noplan"], p["noplanLvl"] = "source", "critical" if peak else "warn"
            extra_fields["from"] = index.get(sources[0])
        elif stockable and not target and added and priced and not line["units"]:
            # Goods the player added to the price list, with nothing on the
            # shelf and no top-up, wholesale delivery or import bringing any:
            # critical where it has been selling (it is sold out), else a
            # warning. Stock on the shelf came from somewhere: not this.
            p["noplan"], p["noplanLvl"] = "priced", "critical" if peak else "warn"
        elif peak and not target:
            if not line["units"]:
                return None  # never held here, so it is made on demand, not stocked
            cover = line["units"] / peak
            p["noplan"] = "target"
            p["noplanLvl"] = "critical" if cover < 1 else "warn" if cover < 2 else "info"
        if target and peak and _below(target, use):
            p["short"].append("target")
        if target and _below(target, need):
            p["tight"] = "target"
        # A young shop is too new to judge, unless what it has already sold
        # outruns its top-up: that is said at once, with the figure to set.
        if peak and young and not p["short"]:
            p["young"] = "young"
        set_to = (_ceil_ten(need) if need and (not target or _below(target, need))
                  and p.get("noplan") not in ("source", "priced") else None)
        return p, {"use": use, "need": need, "have": target or line["units"],
                   "setTo": set_to, "imp": False, **extra_fields}, "daily"

    def lower_target(business, line, key, slug, fields):
        """The top-up target a shelf whose target is set too high could come
        down to: its busiest day for every day to the source's next round
        (round_gap), plus the chain margin once, rounded up to
        SUPPLY_ROUND_TO, and never below what the shelf needs. None where
        that is not below the target it has."""
        rate = line.get("tradeRate", line["rate"])
        target, source = target_at.get((key, slug), (0, None))
        if not target or rate <= 0:
            return None
        factor, _day = ctx["peak"](business)
        days = ctx.get("roundGap", lambda _key: 1)(source) if source else 1
        lowered = max(_ceil_ten(rate * factor * days * (1 + SUPPLY_MARGIN)),
                      _ceil_ten(fields.get("need") or 0))
        return lowered if 0 < lowered < target else None

    held = {}
    keys = set()
    for business in businesses:
        if business["status"] == "vacant":
            continue
        for line in business["lines"]:
            keys.add((business["key"], line["slug"]))
            held[(business["key"], line["slug"])] = line
    for s, items in list(depots.items()) + list(route_only.items()):
        if 0 <= s < len(businesses):
            keys |= {(businesses[s]["key"], slug) for slug in items}
    # Every site the plans ask something of, whether it holds any or not.
    keys |= {k for k, node in walked.get("cap", {}).items()
             if k[0] in index and node["use"] > 0
             and businesses[index[k[0]]]["status"] != "retail"}
    keys |= set(inputs)
    # A shop topped up to a target for an item it neither holds, sells nor
    # prices: a shelf all the same, empty, so nothing upstream supplying it
    # is said (noplan, why source).
    label = ctx.get("label", lambda slug: slug)
    for (key, slug), (amount, _source) in target_at.items():
        if (amount and key in index and (key, slug) not in held
                and businesses[index[key]]["status"] == "retail"):
            keys.add((key, slug))
            held[(key, slug)] = {"slug": slug, "item": label(slug), "units": 0, "rate": 0.0,
                                 "tradeRate": 0.0, "weekSold": 0.0, "price": 0,
                                 "configuredPrice": None}

    facts = collections.defaultdict(dict)
    for key, slug in _in_order(keys):
        business = businesses[index[key]]
        # An office's fees and the equipment it holds are not supply; a shop
        # shut with the game's temporarily closed switch sells nothing, so
        # its shelves are sized on nothing and asked to change nothing.
        if business["status"] in ("vacant", "office") or (
                business["status"] == "retail" and business.get("closed")):
            continue
        line = held.get((key, slug))
        stock = line["units"] if line else 0
        made_line = outputs.get((key, slug))
        entry = depots.get(index[key], {}).get(slug)
        by_mode = {}
        for mode in SIZING_MODES:
            if business["status"] == "retail":
                if not line:
                    break
                got = shelf(business, line)
                if got is None:
                    break
                p, fields, cad = got
                role = "shelf"
            elif (key, slug) in inputs and not inputs[(key, slug)]["directImport"]:
                p, fields = daily_input(key, inputs[(key, slug)], mode)
                role, cad = "input", "made" if p.get("made") else "daily"
            elif (key, slug) in inputs:
                p, fields, cad = weekly(key, slug, mode, stock)
                role = "input"
            elif made_line and not (entry and entry.get("weekly")):
                p = {"made": True}
                fields = {"use": 0, "need": 0, "have": stock, "setTo": None, "imp": False}
                role, cad = "output", "made"
            else:
                p, fields, cad = weekly(key, slug, mode, stock)
                role = "depot"
            more = idle.get((key, slug), {}).get(mode)
            if more:
                p.update(more)
            st, why, lvl = _supply_status(p)
            fact = {"st": st, "why": why, "lvl": lvl, "role": role, "cad": cad, **fields}
            # Only a word that asks for a change carries a figure to set: a new
            # line waits for its history, an idle one for its stock to run down.
            if st not in SET_WORDS:
                fact["setTo"] = None
            # The one exception: a shelf whose top-up target holds weeks of its
            # sales (targetHigh) carries the lower target to type, marked
            # `lowers`: a lowering change, never tight and never on Today.
            if role == "shelf" and st == "idle" and why == "targetHigh" and cad == "daily":
                lowered = lower_target(business, line, key, slug, fields)
                if lowered is not None:
                    fact["setTo"], fact["lowers"] = lowered, True
            if st != "short":
                fact.pop("catchUp", None)
            fact.update(extra.get((key, slug), {}))
            # A factory input topped up from a depot and imported to the
            # factory as well: the input keeps its one daily word, and its own
            # contract is judged on the week beside it (`import`), as a depot
            # line is, so Weekly imports and the findings see that contract.
            row = inputs.get((key, slug))
            if (role == "input" and cad != "weekly" and row
                    and row.get("factoryImportSite") is not None and entry):
                ip, ifields, _icad = weekly(key, slug, mode, stock)
                ist, iwhy, ilvl = _supply_status(ip)
                ifields.pop("imp", None)
                if not entry.get("weekly") and entry.get("pausedWeekly"):
                    # A paused contract beside a top-up: paused, and only a
                    # warning where the input is short without it (a line
                    # waiting on another input is not). Where the top-up
                    # covers the line, the player most likely paused it
                    # because the depot feeds the line now (why topup).
                    if st in ("short", "noplan") or (st == "stalled" and why == "notDrawn"):
                        cover = stock / row["perDay"] if row["perDay"] else 60
                        ist, iwhy, ilvl = "paused", "order", "warn" if cover >= 7 else "critical"
                    else:
                        ist, iwhy, ilvl = "paused", "topup", "info"
                    ifields["from"] = row.get("from")
                if ist not in SET_WORDS:
                    ifields["setTo"] = None
                fact["import"] = {"st": ist, "why": iwhy, "lvl": ilvl, "role": "input",
                                  "cad": "weekly", **ifields}
                fact["imp"] = True
            if mode == "dem" and role in ("input", "depot"):
                ramp = sorted(ramp_at.get((key, slug)) or ())
                if ramp:
                    fact["ramp"] = ramp
            by_mode[mode] = fact
        if not by_mode:
            continue
        base = by_mode["cap"]
        dem = _mode_changes(base, by_mode["dem"])
        if dem:
            base["dem"] = dem
        facts[str(index[key])][slug] = base
    return {s: facts[s] for s in _in_order(facts)}


# --- staffing by hour ---------------------------------------------------
HOUR_WEEKS_THIN = 2  # a weekday resting on fewer weeks than this is marked thin
AT_CAP = 0.95  # this close to the ceiling is at the ceiling
IDLE_RATIO = 2.0  # capacity this many times the queue is capacity doing nothing
IDLE_RUN = 3  # ...for at least this many hours in a row
IDLE_STAFF = 2  # ...with at least this many people on
HYPE_TIGHT = 0.90  # a wave arriving at a shop already this full is being turned away
PHRASE_SHAPES = 2  # how many weekday-hour patterns to name before counting the rest


# The staffing and hour-grid words (docs/architecture.md, "UI text"): every
# phrase below is a message whose English is what these functions always
# wrote, so the page can say it in the reader's language, and the board code
# that reads a limit's English reads enOf(). Keys are sp.py.*: the site panel's
# own script owns sp.*, so the two never write the same key.
def _sp_list(items: list, sep: str):
    """Phrases joined as `sep.join(items)` joined them, still a message: a
    nested "{a}, {b}", "{a}; {b}" or "{a} and {b}" per separator, so a
    translation joins its own way. One item is itself, none is ""."""
    if not items:
        return ""
    if len(items) == 1:
        return items[0]
    rest = _sp_list(items[1:], sep)
    if sep == ", ":
        return msg("sp.py.list.comma", "{a}, {b}", a=items[0], b=rest)
    if sep == "; ":
        return msg("sp.py.list.semi", "{a}; {b}", a=items[0], b=rest)
    if sep == " and ":
        return msg("sp.py.list.and", "{a} and {b}", a=items[0], b=rest)
    raise ValueError(f"_sp_list(): no message joins by {sep!r}")


def _sp_weekday(wd: int):
    """A weekday's first three letters, 0 Sunday, as WEEKDAYS[wd][:3] wrote them."""
    return (
        msg("sp.py.wd.0", "Sun") if wd == 0 else msg("sp.py.wd.1", "Mon") if wd == 1
        else msg("sp.py.wd.2", "Tue") if wd == 2 else msg("sp.py.wd.3", "Wed") if wd == 3
        else msg("sp.py.wd.4", "Thu") if wd == 4 else msg("sp.py.wd.5", "Fri") if wd == 5
        else msg("sp.py.wd.6", "Sat")
    )


def _sp_hours(start: int, end: int):
    """One run of hours, "8-11", or "8" for a single hour."""
    if end - start > 1:
        return msg("sp.py.when.hours", "{a}-{b}", a=start, b=end)
    return msg("sp.py.when.hour", "{h}", h=start)


def _sp_days(first: int, last: int):
    """A run of weekdays, "Mon-Wed"."""
    return msg("sp.py.when.days", "{a}-{b}", a=_sp_weekday(first), b=_sp_weekday(last))


def _sp_counters(office: bool):
    """What a site's serving posts are called where no station names them."""
    return msg("sp.py.workstations", "workstations") if office else msg("sp.py.counters", "counters")


def _sp_station_noun(words: dict):
    """A role's stations by their English plural, as _role_words() says them,
    with the station's name as a token beside it (`station_name`); None where
    the role has no station word of its own. The grid's role["noun"] stays
    the plain str, which the page compares against a limit's English."""
    if not words["noun"]:
        return None
    return msg("sp.py.noun.station", "{stations}", stations=words["noun"], station_name=words["stationName"])


def _cap_first(text):
    """A cap finding's limit opening a sentence ("{limit} is the limit" in
    _alerts()): its first character upper case, as `limit[:1].upper() +
    limit[1:]` writes it, and still a message. Call this instead of slicing,
    which gives a plain str that stays English on every page.

    A limit that already starts upper case (a role's "{role} staffing" leads
    with a game name's token) comes back as it is. The three that start lower
    case have a sentence-initial key of their own (sp.py.*.first: "Staffing",
    "Registers", "Workstations"), and a join capitalises its first part only:
    "Staffing and projection booths". A station's own plural keeps its
    `station_name` token beside the capitalised English. German capitalises
    its nouns anyway, so a .first key's translation is usually its plain key's."""
    if text[:1].upper() == text[:1]:
        return text
    if isinstance(text, Msg):
        rest = {k: v for k, v in text.p.items() if k != "a"}
        if text.key == "sp.py.list.and":
            return msg("sp.py.list.and", "{a} and {b}", a=_cap_first(text.p["a"]), **rest)
        if text.key == "sp.py.list.comma":
            return msg("sp.py.list.comma", "{a}, {b}", a=_cap_first(text.p["a"]), **rest)
        if text.key == "sp.py.list.semi":
            return msg("sp.py.list.semi", "{a}; {b}", a=_cap_first(text.p["a"]), **rest)
        if text.key == "sp.py.limit.staffing":
            return msg("sp.py.limit.staffing.first", "Staffing")
        if text.key == "sp.py.limit.registers":
            return msg("sp.py.limit.registers.first", "Registers")
        if text.key == "sp.py.workstations":
            return msg("sp.py.workstations.first", "Workstations")
        if text.key == "sp.py.limit.station":
            return msg("sp.py.limit.station.first", "{stations}", stations=_cap_first(text.p["stations"]),
                       station_name=text.p["station_name"])
        if text.key == "sp.py.limit.station.staff":
            return msg("sp.py.limit.station.staff.first", "{station} staffing",
                       station=_cap_first(text.p["station"]), station_name=text.p["station_name"])
    return text[:1].upper() + text[1:]


def _hour_phrase(hours_by_day: dict, sep: str = "; "):
    """"Mon-Sun 8-11, 18-20" — the shape of a set of weekday-hours in words.

    `sep` joins one day shape to the next ("Mon-Wed 8-20; Sat 10-14"); a caller
    that lists several phrases apart by "; " passes " and " instead. A message
    (sp.py.when.*), or "" for no hours."""
    def runs(hours):
        out, start = [], None
        for h in range(25):
            if h in hours and start is None:
                start = h
            elif h not in hours and start is not None:
                out.append(_sp_hours(start, h))
                start = None
        return out

    shapes = collections.defaultdict(list)
    for wd, hours in hours_by_day.items():
        shapes[tuple(runs(hours))].append(wd)
    parts, spare = [], 0
    ranked = sorted(shapes.items(), key=lambda kv: (-len(kv[1]), -len(kv[0])))
    for shape, days in ranked:
        order = [1, 2, 3, 4, 5, 6, 0]
        picked = sorted(days, key=order.index)
        if len(parts) >= PHRASE_SHAPES:
            spare += sum(len(h) for d, h in hours_by_day.items() if d in picked)
            continue
        if len(picked) == 7:
            label = msg("sp.py.when.everyday", "every day")
        elif len(picked) > 2 and [order.index(d) for d in picked] == list(
            range(order.index(picked[0]), order.index(picked[0]) + len(picked))
        ):
            label = _sp_days(picked[0], picked[-1])
        else:
            label = _sp_list([_sp_weekday(d) for d in picked], ", ")
        parts.append(msg("sp.py.when.part", "{days} {hours}", days=label, hours=_sp_list(list(shape), ", ")))
    phrase = _sp_list(parts, sep)
    # A list of every scattered hour is not a shape. Name the pattern and count
    # the rest.
    if spare:
        return msg("sp.py.when.scattered", {"one": "{when} and {n} scattered hour",
                                            "other": "{when} and {n} scattered hours"}, when=phrase, n=spare)
    return phrase


def _off_hours(covered: set):
    """Group identical gaps, preserving exception days and split shifts. A
    message in _hour_phrase()'s words, or "" for none."""
    weekdays = (1, 2, 3, 4, 5, 6, 0)
    groups, said = {}, {}
    for day, wd in enumerate(weekdays):
        gaps = [h for h in range(24) if (wd, h) not in covered]
        if not gaps:
            continue
        runs, start, prev = [], gaps[0], gaps[0]
        for h in gaps[1:]:
            if h != prev + 1:
                runs.append(msg("sp.py.when.hours", "{a}-{b}", a=start, b=prev + 1))
                start = h
            prev = h
        runs.append(msg("sp.py.when.hours", "{a}-{b}", a=start, b=prev + 1))
        hours = _sp_list(runs, ", ")
        groups.setdefault(str(hours), []).append(day)
        said.setdefault(str(hours), hours)
    parts = []
    for hours, days in groups.items():
        ranges, start, prev = [], days[0], days[0]
        def day_range(first, last):
            a, b = (weekdays[d] for d in (first, last))
            return _sp_weekday(a) if first == last else _sp_days(a, b)
        for day in days[1:]:
            if day != prev + 1:
                ranges.append(day_range(start, prev))
                start = day
            prev = day
        ranges.append(day_range(start, prev))
        parts.append(msg("sp.py.when.part", "{days} {hours}", days=_sp_list(ranges, ", "), hours=said[hours]))
    return _sp_list(parts, "; ")


def _ceil_ten(value: float) -> int:
    """A suggested figure, rounded up to SUPPLY_ROUND_TO units."""
    return int(math.ceil(value / SUPPLY_ROUND_TO) * SUPPLY_ROUND_TO)


# ------------------------------------------------------------------ factories
def _depot_routes(flow: dict, index: dict) -> dict:
    """Depot lines no import contract covers that a route from the company's
    own site feeds: {site index: {slug: {routed, covered, drawWeek}}}, in
    the shape the import lines carry them, for the Weekly imports table."""
    out = collections.defaultdict(dict)
    for (key, slug), (routed_week, covered, draw_week) in sorted(flow.get("routeOnly", {}).items()):
        if key in index:
            out[index[key]][slug] = {"routed": round(routed_week), "covered": covered,
                                     "drawWeek": round(draw_week)}
    return out


def _depot_flow(flow: dict, index: dict) -> dict:
    """What each depot imports a week, with what routes from the company's
    own sites bring it (_supply's walk()).

    Orders come from current import contracts, so they are known even when
    no factory recipe can be read. That is why this sits apart from the line
    analysis: the import table must never go blank just because en.json was
    not loaded.
    """
    depots = collections.defaultdict(dict)
    for (depot, slug), supply in flow["imports"].items():
        if depot in index:
            routed_week, covered, draw_week = flow.get("routed", {}).get(
                (depot, slug), (0, False, 0))
            depots[index[depot]][slug] = {
                "weekly": supply["weekly"], "pausedWeekly": supply.get("pausedWeekly", 0),
                "routed": round(routed_week), "covered": covered, "drawWeek": round(draw_week),
                **_import_setting(supply),
            }
    # Contracts set up at zero that brought nothing: listed at zero for the
    # page, marked so the factory view does not take them for a supply.
    # A Smart Delivery line among them names the contract to set, as a live
    # one does: the first Smart Delivery contract in delivery order, an
    # active one first, replayed over the contracts of its own group.
    for (depot, slug), contracts in flow.get("configured", {}).items():
        if depot not in index:
            continue
        smart = [c for c in contracts if c["smart"]]
        named = next((c for c in smart if c["active"]), smart[0] if smart else None)
        group = [c for c in contracts if named is not None and c["active"] == named["active"]]
        depots[index[depot]][slug] = {
            "weekly": 0, "pausedWeekly": 0, "zeroOnly": True,
            "smart": named is not None, "target": named["amount"] if named else None,
            "plain": 0, "plainAfter": 0, "plainBefore": 0,
            "levelImporter": named["importer"] if named else None,
            "levelId": named["id"] if named else None,
            "levelName": _level_name(contracts, named["importer"], named["order"]) if named else None,
            "levelAt": group.index(named) if named else None,
            "pass": [{"amount": c["amount"], "smart": c["smart"]} for c in group],
            "arrivedLastWeek": 0, "contracts": contracts,
        }
    return depots


def _recipe_identity(rid: str | None, station: str, recipes: dict, chosen: dict) -> tuple:
    """Prefer a usable table identity, then a manual choice; never infer from flow."""
    if not rid:
        return None, None
    for slug, basis in ((RECIPE_ITEMS.get(rid), "table"), (chosen.get(rid), "you")):
        rec = recipes.get(slug)
        if rec and rec["workstation"] == station:
            return slug, basis
    return None, None


def _line_hours(posted: list, machines: int, rate: float, dem_makes: float, basis: str) -> dict:
    """A factory line's hours: rostered now, and needed in each sizing.

    `hoursNow` is the week of its least-rostered machine as whole hours a
    day (rounded down), so a machine off one day reads 20, not 0; `thinDay`
    names that machine's weekday with the fewest hours where that is under
    `hoursNow`. 24/7 needs every machine all 24; Demand the hours that
    make what the ends draw plus the margin once (`dem_makes` a day), never
    past 24, and 24 where nothing is drawn (`demBasis` "none"). A line is
    judged on the week, as _staff_notes() judges a machine: short (why hours:
    critical below STAFF_CRITICAL of the week on its least-staffed machine,
    else warn) where that machine's week is under the need's. More than
    Demand needs is covered, with `lower` as a suggestion, never a change.
    `_posts`, the machines' item ids by list position, is for
    _factory_staffing() and leaves the payload there.
    """
    posted = sorted(posted, key=lambda m: (m["slot"], str(m["id"])))
    least = min(posted, key=lambda m: sum(m["days"]), default=None)
    weekly = sum(least["days"]) if least else 0
    now = weekly // 7
    thin = (min(least["days"]), least["days"].index(min(least["days"]))) if least else None
    dem = 24
    if basis == "sales" and rate and machines:
        dem = min(24, math.ceil(round(dem_makes * (1 + SUPPLY_MARGIN) / (rate * machines), 6)))

    def verdict(need):
        if weekly < need * 7:
            level = "critical" if weekly < need * 7 * STAFF_CRITICAL else "warn"
            return {"status": "short", "why": "hours", "level": level}
        out = {"status": "covered", "why": None, "level": "ok"}
        if now > need:
            out["lower"] = need
        return out

    return {
        "hoursNow": now,
        **({"thinDay": {"day": WEEKDAYS[thin[1]][:3], "hours": thin[0]}}
           if thin is not None and thin[0] < now else {}),
        "needHours": {"cap": 24, "dem": dem},
        "demBasis": basis,
        "running": sum(m["running"] for m in posted),
        **verdict(24),
        "dem": verdict(dem),
        "_posts": [m["id"] for m in posted],
    }


def _line_use(machines: int, rate: float, makes: float, sold: float | None,
              use: float | None) -> dict:
    """A factory line's use against what it makes at 24 h, for display only:
    staffing and sizing keep _line_hours()'s 24 h cap.

    `soldDay` is `sold`, the line's share of what the shops down its plan
    measurably sell a day: no margin, no target or coming week in place of
    sales, no factory line eating it. `needDay` is `use`, the figure Demand
    sizing works from (demand(): those, the new shops' coming week or target
    and the factory lines that eat the product), plus the margin once, never
    capped. Both read the same in either sizing. `production` is short where
    `needDay` is past what the line makes at 24 h: a line at 24 h cannot gain
    hours, so it is a machine gap, `more` machines at the recipe's rate,
    making `makesWith` a day with them; critical where `use` alone is past
    it, a warning where only the margin is. A line nothing draws on reads 0,
    0 and covered. All three are None where no demand can be read at all
    (no plan walk: `sold` and `use` None)."""
    if sold is None or use is None:
        return {"soldDay": None, "needDay": None, "production": None}
    need = use * (1 + SUPPLY_MARGIN)
    out = {"soldDay": round(sold), "needDay": round(need), "production": {"status": "covered", "level": "ok"}}
    each = rate * 24
    if each and round(need, 6) > round(makes, 6):
        total = max(machines + 1, math.ceil(round(need / each, 6)))
        out["production"] = {"status": "short", "level": "critical" if round(use, 6) > round(makes, 6) else "warn",
                             "more": total - machines, "makesWith": round(total * each)}
    return out


def _factories(
    save: Save,
    names: Names,
    businesses: list,
    recipes: dict,
    flow: dict,
    history: "History | None",
    character: str,
) -> dict:
    """What each factory line makes and eats, against the flow set up to feed it.

    The recipe table names usable IDs; the player names unresolved ones. Both use
    the game's help pages for quantities. Full-rate need is machines × hourly
    ingredients × 24; the roster supplies the separate staffed estimate.
    """
    index = flow["index"]
    empty = {"sites": [], "machines": 0, "unnamed": 0}
    machines = collections.defaultdict(collections.Counter)
    # Where each machine sits in the factory's workstation list — the one
    # handle the player can match against the game screen — and the hours a
    # factory worker is posted to it. A machine runs only while someone is on
    # it: the wine machine rostered 144 of 168 hours draws 86% of its grapes.
    slots = collections.defaultdict(lambda: collections.defaultdict(list))
    roster = collections.defaultdict(lambda: collections.defaultdict(list))
    # Each machine's Produce up to setting (produceUpTo, with the figure in
    # produceUpToValue; the save leaves out a false one): the game stops the
    # machine once the factory holds that many of what it makes.
    limits = collections.defaultdict(lambda: collections.defaultdict(list))
    # Each machine's item id and its rostered hours per weekday, for the line's
    # hours now, what runs, and the factory roster (_factory_staffing).
    posted = collections.defaultdict(lambda: collections.defaultdict(list))
    for building in save.items(save.root["BuildingRegistrations"]):
        if not building.get("RentedByPlayer"):
            continue
        key = site_key(_address_of(building, strict=True))
        if key not in index:
            continue
        posts = {}
        for item in _item_instances(save, building["itemInstances"]):
            if not item.get("workstationType"):
                continue
            station = item["workstationType"].replace(WS_PREFIX, "").removesuffix("workstation")
            line = (station, item.get("selectedRecipeId"))
            slot = (item.get("priority") or 0) + 1
            machines[key][line] += 1
            slots[key][line].append(slot)
            limits[key][line].append(item.get("produceUpToValue") if item.get("produceUpTo") else None)
            posts[item.get("id")] = (line, slot)
        covered = collections.defaultdict(set)
        for scheduled in save.items(building.get("scheduleDays")):
            wd = scheduled["day"] % 7
            for shift in save.items(scheduled.get("workShifts")):
                post = shift.get("itemInstanceId")
                if post not in posts or shift.get("type") != STATION_SHIFT:
                    continue
                for hour in range(max(0, shift["startingHour"]), min(24, shift["endingHour"])):
                    covered[post].add((wd, hour))
        for post, (line, slot) in posts.items():
            roster[key][line].append(
                {"slot": slot, "hours": len(covered[post]), "off": _off_hours(covered[post])}
            )
            posted[key][line].append({
                "slot": slot, "id": post,
                "days": [sum(1 for w, _h in covered[post] if w == wd) for wd in range(7)],
                # Running: a recipe chosen and somebody posted at some hour.
                "running": line[1] is not None and bool(covered[post]),
            })
    if not machines or not recipes:
        # No line can be read (no machines, or no recipe pages to read them
        # with), but current import contracts and the plans are known; a
        # factory whose lines cannot be read is taken to make what it sends.
        if flow.get("walk"):
            flow.update(flow["walk"]({}, {}, {(key, item) for key in machines
                                              for item, units in flow["held"].get(key, {}).items()
                                              if units > 0}))
        return {
            **empty,
            "character": character,
            "aliases": {},
            "depots": _depot_flow(flow, index),
            "depotRoutes": _depot_routes(flow, index),
        }

    def station_name(slug: str) -> str:
        text = names.locale.get(f"help_factory_workstation_{slug}_content", "")
        match = re.search(r"\*\*([^*]+)\*\*", text)
        return match.group(1) if match else f"{slug.title()} Workstation"

    by_station = collections.defaultdict(list)
    for slug, rec in recipes.items():
        by_station[rec["workstation"]].append(slug)

    def held(key, slug):
        return flow["held"].get(key, {}).get(slug, 0)

    # A hand-built flow (the recipe tests) may carry only the net log.
    in_by_day = flow.get("inByDay") or flow["byDay"]
    out_by_day = flow.get("outByDay") or (lambda *args: {})
    forwarded = flow.get("forwarded") or (lambda *args: 0.0)

    def out_of(key, slug):
        return flow["shipped"](key, slug) or 0.0

    def arrives(key, slug):
        """The daily feed this line is actually getting.

        The week behind an input only describes it if the input was drawn all
        week. Where the record is younger than the window the average is of a
        factory that has since changed, and the last completed round is the
        honest measure of what the logistics brings in.
        """
        # The log is already cut to the window and to completed days. What the
        # factory sends on of the same item (an import passed to a depot's
        # target) arrived but was never eaten, so it comes off.
        seen = in_by_day(key, slug)
        drawn = [d for d, amount in seen.items() if amount > 0]
        if len(drawn) >= SHIPPED_WINDOW * FEED_SETTLED:
            return max(0.0, (flow["received"](key, slug) or 0.0) - forwarded(key, slug))
        if not drawn:
            return 0.0
        last = max(drawn)
        return max(0.0, seen[last] - out_by_day(key, slug).get(last, 0.0))

    hours_today = save.root.get("Hour", 24) + (save.root.get("Minute") or 0) / 60

    def line_limit(key, line):
        """The stock at which a line's machines all stop, or None if one of
        them has no Produce up to set and so runs whatever is held."""
        set_to = limits[key][line]
        return max(set_to) if set_to and None not in set_to else None

    # The help text links an ingredient under one name and the game moves it
    # under another — "Bag of Tomatoes" is rawtomato on the page and tomato in
    # every warehouse — so each ingredient is matched to the item the city
    # actually holds, by label when the slug itself is never seen.
    seen = {slug for lines in flow["held"].values() for slug in lines}
    seen |= {slug for _key, slug in flow["targets"]} | {slug for _key, slug in flow["imports"]}
    by_label = collections.defaultdict(list)
    for slug, label in names.locale.items():
        if slug.startswith("ba:itemname_"):
            by_label[label].append(slug)

    def resolve(ing: dict) -> str:
        if ing["slug"] in seen:
            return ing["slug"]
        return next((alt for alt in by_label.get(ing["item"], []) if alt in seen), ing["slug"])

    chosen = history.named(character) if history else {}

    # Every factory's named lines, for Demand sizing to follow a product
    # through the factories that eat it: {factory: [(product, machines)]},
    # and what each factory can make of a product a day.
    specs = collections.defaultdict(list)
    capacity_at = collections.defaultdict(collections.Counter)
    for key, counter in machines.items():
        for (station, rid), n in counter.items():
            named = _recipe_identity(rid, station, recipes, chosen)[0]
            if named:
                specs[key].append((named, n))
                capacity_at[key][named] += n * recipes[named]["out"] * 24
    # A factory running a recipe the board cannot name may make what it
    # holds: it is taken to have those items coming in, and nothing else.
    unread_pairs = {(key, item) for key, counter in machines.items()
                    if any(rid and not _recipe_identity(rid, station, recipes, chosen)[0]
                           for station, rid in counter)
                    for item, units in flow["held"].get(key, {}).items() if units > 0}
    if flow.get("demandMade"):
        flow["demandMade"](lambda site, item: capacity_at[site][item] > 0 or (site, item) in unread_pairs,
                           lambda site, item: capacity_at[site][item])
    dem_made = {}

    def dem_output(key, slug):
        """What the lines at `key` make of `slug` a day in Demand sizing: what
        the ends draw of it down the plan (demand()), the factory lines that
        eat it along the way included, never past capacity; capacity where
        nothing draws on it."""
        if (key, slug) in dem_made:
            got = dem_made[(key, slug)]
            return capacity_at[key][slug] if got is None else got
        dem_made[(key, slug)] = None  # a loop in the plans reads capacity
        wanted = demand(key, slug, eats=dem_eats)[0] if demand else 0.0
        cap = capacity_at[key][slug]
        dem_made[(key, slug)] = min(cap, wanted) if wanted > 0 else cap
        return dem_made[(key, slug)]

    def dem_eats(site, item):
        """What the factory lines at `site` draw of `item` a day in Demand sizing."""
        total = 0.0
        for slug, n in specs.get(site, ()):
            per = sum(ing["per"] for ing in recipes[slug]["ingredients"] if resolve(ing) == item)
            if per and capacity_at[site][slug]:
                total += n * per * 24 * dem_output(site, slug) / capacity_at[site][slug]
        return total

    def missing(key, slug, keys=False):
        """Inputs of a recipe that neither arrive nor are held at the site: their
        names, or with `keys` their game keys, in the same order."""
        if flow["received"](key, "") is None:
            return []
        return [
            ing["slug"] if keys else ing["item"]
            for ing in recipes[slug]["ingredients"]
            if not arrives(key, resolve(ing)) and not held(key, resolve(ing))
        ]

    # --- each factory: its lines, and what they eat
    made_by = collections.defaultdict(set)
    sites, depot_need = [], collections.defaultdict(float)
    # `ramp_at` names the shops under a week old behind a Demand figure,
    # whose coming week was read off a line (_coming_week).
    ramp_at = collections.defaultdict(set)
    demand = flow.get("demand")

    def upstream(site, slug):
        """The site whose import carries a need topped up from `site`: a
        factory with no import of its own passes on what its own top-up
        brings, so a factory it feeds is sized on the import behind it."""
        seen = set()
        while site in machines and (site, slug) not in flow["imports"] and site not in seen:
            seen.add(site)
            behind = flow["targets"].get((site, slug), (0, None))[1]
            if not behind:
                break
            site = behind
        return site

    def unnamed_hours(machines_posted):
        """An unnamed line's hours now and its machines' ids, as a line's."""
        got = _line_hours(machines_posted, 1, 1, 0, "none")
        return {"hoursNow": got["hoursNow"], "_posts": got["_posts"]}

    dem_out = collections.defaultdict(float)  # (factory, product) -> a day's make in Demand sizing
    for key, counter in machines.items():
        lines, unnamed, needs = [], [], {}
        # Every named line's capacity by product, so a product two lines make
        # splits what the ends draw of it between them.
        capacity = collections.Counter()
        for (station, rid), n in counter.items():
            named = _recipe_identity(rid, station, recipes, chosen)[0]
            if named:
                capacity[named] += n * recipes[named]["out"] * 24
        for (station, rid), n in sorted(counter.items(), key=lambda kv: -kv[1]):
            slug, basis = _recipe_identity(rid, station, recipes, chosen)
            staffing = {
                "hoursWeek": sum(m["hours"] for m in roster[key][(station, rid)]),
                "fullWeek": n * STAFF_HOURS,
                "gaps": [
                    m for m in sorted(roster[key][(station, rid)], key=lambda m: m["hours"])
                    if m["hours"] < STAFF_HOURS
                ],
            }
            if not slug:
                unnamed.append(
                    {
                        "rid": rid,
                        "workstation": station_name(station),
                        "workstationKey": f"ba:factoryworkstationtype_{station}",
                        "slots": sorted(slots[key][(station, rid)]),
                        "machines": n,
                        "idle": rid is None,
                        "limit": line_limit(key, (station, rid)),
                        "candidates": [
                            {"slug": c, "item": recipes[c]["item"]}
                            for c in by_station.get(station, [])
                        ] if rid else [],
                        **staffing,
                        # A recipe the board cannot name still runs: its
                        # machines are rostered like any line's (_factory_staffing).
                        **(unnamed_hours(posted[key][(station, rid)]) if rid else {}),
                    }
                )
                continue
            rec = recipes[slug]
            makes = n * rec["out"] * 24
            share = staffing["hoursWeek"] / staffing["fullWeek"] if staffing["fullWeek"] else 0.0
            ships = out_of(key, slug)
            stock = held(key, slug)
            to_city = sum(a for d, i, a in flow["edges"].get(key, []) if i == slug and d in index)
            to_pier = sum(a for d, i, a in flow["edges"].get(key, []) if i == slug and d not in index)
            stopped = missing(key, slug)
            # Held by its production limit: the output held is at the limit, or
            # under it by no more than the machines could have made back of
            # what the morning round took. That is bounded three ways: by a
            # day of what leaves, by what the line makes in the hours of today
            # so far, and by LIMIT_SLACK of the limit, so a line shipping more
            # a day than its limit is not taken as held whatever it holds.
            # Such a line eats only what leaves, and that is no feed fault.
            # Demand sizing: what the ends draw of the product a day (the
            # shops down the plan and the factory lines along the way that
            # eat it, dem_eats(); an export takes the surplus), this line's
            # share of it, never past capacity. With nothing drawn there is
            # no demand to read, and the line is taken at capacity.
            dem_makes, ramp, dem_basis, sold, use = makes, (), "none", None, None
            if demand:
                wanted, ramp = demand(key, slug, eats=dem_eats)
                # Two figures for _line_use(), each this line's share as the
                # makers of the product split it: `use`, what Demand sizing
                # works from (new shops' coming week and targets, the factory
                # lines that eat it), uncapped and without the margin; `sold`,
                # what the shops down the plan measurably sell, split by the
                # same routing, and nothing else.
                split = makes / capacity[slug] if capacity[slug] else 0.0
                use = wanted * split
                sold = demand(key, slug, eats=dem_eats, measured=True)[0] * split
                if wanted > 0 and capacity[slug]:
                    dem_makes = min(makes, wanted * makes / capacity[slug])
                    dem_basis = "sales"
            # What the line makes run the hours Demand sizes it to (its share
            # plus the margin, _line_hours()): what the chain's Demand walk
            # takes it to send, so the walk and the sizing agree on who
            # brings the margin.
            dem_out[(key, slug)] += min(makes, dem_makes * (1 + SUPPLY_MARGIN))
            limit = line_limit(key, (station, rid))
            make_back = min(ships, makes / 24 * hours_today, (limit or 0) * LIMIT_SLACK)
            limit_held = limit is not None and stock > 0 and stock >= limit - make_back
            lines.append(
                {
                    "rid": rid,
                    "item": rec["item"],
                    "slug": slug,
                    "missing": stopped,
                    # Their game keys, index for index, for the page to name them.
                    "missingSlugs": missing(key, slug, keys=True),
                    "workstation": station_name(station),
                    "workstationKey": f"ba:factoryworkstationtype_{station}",
                    "slots": sorted(slots[key][(station, rid)]),
                    "machines": n,
                    "rate": rec["out"],
                    "makes": round(makes),
                    "ships": round(ships),
                    "stock": stock,
                    "toCity": to_city,
                    "toPier": to_pier,
                    "basis": basis,
                    "piling": stock > makes * PILE_DAYS and ships < makes * share * 0.8,
                    "limit": limit,
                    "limitHeld": limit_held,
                    "atRoster": round(makes * share),
                    **staffing,
                    **_line_hours(posted[key][(station, rid)], n, rec["out"], dem_makes, dem_basis),
                    **_line_use(n, rec["out"], makes, sold, use),
                }
            )
            made_by[slug].add(key)
            for ing in rec["ingredients"]:
                item = resolve(ing)
                row = needs.setdefault(
                    item,
                    {"item": ing["item"], "slug": item, "perDay": 0.0, "lines": [], "lineSlugs": [],
                     "staffedDay": 0.0,
                     "demDay": 0.0, "ramp": set(), "_shipDraw": 0.0, "_allLimit": True},
                )
                row["perDay"] += n * ing["per"] * 24
                # What the lines' shipped output took of it: a line held by its
                # limit makes what leaves, and eats for that, not for capacity.
                row["_shipDraw"] += n * ing["per"] * 24 * (min(makes, ships) / makes if makes else 0.0)
                row["_allLimit"] = row["_allLimit"] and limit is not None
                row["staffedDay"] += n * ing["per"] * 24 * share
                row["demDay"] += n * ing["per"] * 24 * (dem_makes / makes if makes else 1.0)
                row["ramp"] |= set(ramp)
                # The lines that eat it: their keys, and beside each its name.
                if slug not in row["lineSlugs"]:
                    row["lineSlugs"].append(slug)
                    row["lines"].append(rec["item"])
        # Held by its limit too: a line whose machines all have Produce up to
        # set, making well under its roster's output while every input it eats
        # is on hand for the rest of the day at the full rate. Such machines
        # stop at the limit and start again as the round takes the output, so
        # what it holds at any hour sits anywhere under the limit, and what
        # it draws matches what it makes, not what it could. A starved line
        # runs its input down instead.
        rest_of_day = max(0.0, 24 - hours_today) / 24
        on_hand = {slug: held(key, slug) >= row["perDay"] * rest_of_day for slug, row in needs.items()}
        for line in lines:
            if line["limitHeld"] or line["limit"] is None or line["missing"]:
                continue
            eats = [resolve(ing) for ing in recipes[line["slug"]]["ingredients"]]
            if (eats and all(on_hand.get(item) for item in eats) and line["stock"] > 0
                    and line["ships"] < line["atRoster"] * LINE_STARVED):
                line["limitHeld"] = True
        stopped_lines = {line["item"]: line["missing"] for line in lines if line["missing"]}
        # The same lines' inputs with their keys, in step with the names: two
        # keys can share an English name.
        stopped_pairs = {line["item"]: list(zip(line["missing"], line.get("missingSlugs") or []))
                         for line in lines if line["missing"]}
        held_lines = collections.defaultdict(lambda: True)
        for line in lines:
            held_lines[line["item"]] = held_lines[line["item"]] and line["limitHeld"]
        # What the lines not yet held by their limit would eat of each input
        # at full rate: a starved line ships little, so its shipped output is
        # no measure of what it has to have on hand.
        free_draw = collections.defaultdict(float)
        for line in lines:
            if line["limitHeld"]:
                continue
            for ing in recipes[line["slug"]]["ingredients"]:
                free_draw[resolve(ing)] += line["machines"] * ing["per"] * 24
        for slug, row in needs.items():
            target, source = flow["targets"].get((key, slug), (0, None))
            # A factory can itself be an import destination. Weekly deliveries
            # do not require a daily logistics target, nor can their delivery
            # log be judged as a daily warehouse round.
            own_import = flow["imports"].get((key, slug))
            direct_weekly = own_import["weekly"] if own_import else 0
            mixed = bool(own_import and target and source)
            # Beside a top-up, the factory's own contract answers for its own
            # amount. A paused one brings nothing, so its share is none and the
            # top-up (and the import behind it) carries the whole week.
            share = direct_weekly
            direct_need = min(share, row["perDay"] * 7) if mixed else row["perDay"] * 7 if own_import else 0
            warehouse_need = max(row["perDay"] * 7 - direct_need, 0) if source and (mixed or not own_import) else 0
            # A paused contract never makes an input direct: beside a top-up the
            # top-up is what brings it today.
            direct = bool(own_import and not warehouse_need and not (mixed and not direct_weekly))
            import_source = key if direct else upstream(source, slug) if source else None
            # An input that only sits because every line using it is stopped
            # for want of something else is waiting, not being ignored.
            waiting = (
                sorted({pair for line in row["lines"] for pair in stopped_pairs[line] if pair[0] != row["item"]},
                       key=lambda pair: (pair[0], str(pair[1])))
                if all(line in stopped_lines for line in row["lines"])
                else []
            )
            row["waitingOn"] = [name for name, _slug in waiting]
            row["waitingOnSlugs"] = [slug for _name, slug in waiting]
            # Every line eating it held by its limit, with some of it on hand:
            # the machines are not waiting for it, they have nothing to make.
            # Or every such line has Produce up to set, what arrives covers
            # what their shipped output ate, and enough is on hand to run the
            # lines not yet held at full rate for the rest of the day: one
            # line held at its limit all day and another only late in the day
            # still draw no more than they ship, whatever the hour's stock
            # test says. A line that could not run flat out on what it holds
            # is starved, not held.
            ship_draw, all_limit = row.pop("_shipDraw"), row.pop("_allLimit")
            row["limited"] = bool(
                row["lines"] and held(key, slug) > 0 and (
                    all(held_lines[line] for line in row["lines"])
                    or (all_limit and ship_draw > 0 and arrives(key, slug) >= ship_draw * 0.85
                        and held(key, slug) >= free_draw[slug] * rest_of_day))
            )
            row["target"] = target
            row["source"] = import_source
            row["from"] = index.get(source) if source and not direct else None
            row["directImport"] = direct
            row["factoryImportSite"] = index[key] if own_import else None
            row["directWeekly"] = direct_weekly if own_import else None
            row["directNeed"] = direct_need
            row["warehouseNeed"] = warehouse_need
            # A daily route fills to a stock level; weekly imports reduce its
            # shipment volume, not the level needed for a full production day.
            row["dailyNeed"] = row["perDay"]
            row["importSite"] = index.get(import_source)
            row["known"] = not own_import and flow["received"](key, slug) is not None
            row["arrives"] = round(arrives(key, slug))
            row["stock"] = held(key, slug)
            row["depotStock"] = held(source, slug) if source and not direct else 0
            # Planned, stocked at the depot, and yet nothing came all week.
            row["stalled"] = bool(row["known"] and not row["arrives"] and row["depotStock"] > 0)
            if own_import:
                depot_need[(key, slug)] += direct_need
            if source:
                depot_need[(import_source, slug)] += warehouse_need
            ramp = row.pop("ramp")
            if ramp:
                ramp_at[(key, slug)] |= ramp
                if source:
                    ramp_at[(import_source, slug)] |= ramp
            row["demDay"] = round(row["demDay"])
            # A line on its first fill (first_fill()): the first of it arrived
            # in the last MIN_TRADE_DAYS days, and the site's whole log names it
            # nowhere before, so the log cannot judge it yet. A line fed before
            # and starved now is not new, whatever the first days of the window
            # hold.
            fed = [d for d, amount in in_by_day(key, slug).items() if amount > 0]
            first, _once = flow.get("firstFill", lambda *_: (None, 0.0))(key, slug)
            row["firstFill"] = bool(
                fed and flow.get("day") is not None and first is not None
                and first == min(fed) and first >= flow["day"] - MIN_TRADE_DAYS)
        # What the page needs to work out a line the player names by hand:
        # every top-up into this factory, and what arrived over the week.
        into = {
            slug: [amount, index.get(source)]
            for (dest, slug), (amount, source) in flow["targets"].items()
            if dest == key
        }
        watched = set(into) | set(flow["held"].get(key, {}))
        sites.append(
            {
                "s": index[key],
                "machines": sum(counter.values()),
                # Placed is `machines`; running, those with a recipe and
                # somebody posted at some hour.
                "running": sum(m["running"] for line in posted[key].values() for m in line),
                "lines": lines,
                "unnamed": unnamed,
                "needs": list(needs.values()),
                "targets": into,
                "known": flow["received"](key, "") is not None,
                "arrivals": {slug: round(arrives(key, slug)) for slug in _in_order(watched)},
            }
        )

    # --- the chain walked from the sources (_supply's walk()), now the lines
    # are known: what each factory makes, what its lines draw in each sizing,
    # and the factories with a line the board cannot name. It fills in what
    # routes bring each depot line, which the verdicts below read.
    if flow.get("walk"):
        makes_at, eats_at = {mode: collections.defaultdict(float) for mode in SIZING_MODES}, {
            mode: {} for mode in SIZING_MODES}
        for site in sites:
            key = businesses[site["s"]]["key"]
            for line in site["lines"]:
                makes_at["cap"][(key, line["slug"])] += line["makes"]
            for row in site["needs"]:
                cap_day, dem_day = row["perDay"], row["demDay"]
                eats_at["cap"][(key, row["slug"])] = (cap_day, cap_day)
                eats_at["dem"][(key, row["slug"])] = (
                    dem_day, min(dem_day * (1 + SUPPLY_MARGIN), cap_day))
        for line, per_day in dem_out.items():
            makes_at["dem"][line] += per_day
        flow.update(flow["walk"]({mode: dict(by) for mode, by in makes_at.items()}, eats_at, unread_pairs))

    # --- the verdict on each input, once the depot totals are known
    for site in sites:
        for row in site["needs"]:
            per_day, source = row["perDay"], row.pop("source")
            if row["directImport"]:
                source = businesses[site["s"]]["key"]
            supply = flow["imports"].get((source, row["slug"])) if source else None
            weekly_need = depot_need.get((source, row["slug"]), 0.0)
            staffed = row.pop("staffedDay", per_day)
            row["staffedShare"] = round(staffed / per_day, 2) if per_day else 1.0
            row["perDay"] = round(per_day)
            row["perWeek"] = round(per_day * 7)
            row["depotNeed"] = round(weekly_need)
            row["importWeekly"] = supply["weekly"] if supply else None
            # A Smart Delivery line keeps importTarget in stock, plus any plain
            # amount delivered after it; importWeekly is what a week can bring.
            row["importSmart"] = bool(supply and supply.get("smart"))
            row["importTarget"] = supply.get("target") if row["importSmart"] else None
            row["importPlainAfter"] = supply.get("plainAfter", 0) if row["importSmart"] else 0
            row["importPlainBefore"] = supply.get("plainBefore", 0) if row["importSmart"] else 0
            row["importLevelImporter"] = supply.get("levelImporter") if row["importSmart"] else None
            row["importLevelName"] = (
                supply.get("levelName", supply.get("levelImporter")) if row["importSmart"] else None)
            # A route from the company's own site into the depot brings part
            # of the week, or all of it; the import answers for the rest.
            # depotNeed is the factories' part of what leaves the depot; the
            # route goes to the whole, so only what it brings beyond the rest
            # (the shops' part of the measured draw) comes off the factories'.
            # Covered is the route against the depot's measured draw; a
            # starved factory draws less than it needs, so it holds only where
            # the need is no more than that draw. A depot with no import of
            # the item may still be fed by a route (depot to depot, say):
            # then the route is all there is, read the same way.
            routes = flow.get("routed", {}) if supply else flow.get("routeOnly", {})
            routed_week, covered, draw_week = routes.get((source, row["slug"]), (0, False, 0))
            # Worked on the rounded figures the page gets, so feedVerdict,
            # which redoes it, agrees.
            routed_week, draw_week = round(routed_week), round(draw_week)
            if routed_week:
                weekly_need = round(weekly_need)
            covered = covered and weekly_need <= draw_week * (1 + FIT_TIGHT)
            row["importRouted"] = routed_week
            row["importCovered"] = covered
            row["importDrawWeek"] = draw_week
            to_factories = max(0, routed_week - max(0, draw_week - weekly_need))
            # The route's share that reaches the factories, the rest going to the shops.
            row["importRoutedFactories"] = round(to_factories)
            weekly_need = 0 if covered else max(weekly_need - to_factories, 0)
            # What the import has to bring a week, after the route.
            row["importNeed"] = round(weekly_need)
            row["importPaused"] = bool(supply and not supply["weekly"] and supply.get("pausedWeekly")
                                       and not covered)
            row["importFit"] = (
                "short" if weekly_need and not supply["weekly"] else _fit(weekly_need, supply["weekly"])
            ) if supply else None
            row["madeAt"] = sorted(index[k] for k in made_by.get(row["slug"], ()) if k in index)
            row["raiseTarget"] = row["raiseImport"] = None
            if row["importPaused"]:
                status, level = "paused", "critical"
            elif row["directImport"]:
                if row["importFit"] in ("short", "tight"):
                    status, level = "import", "critical" if row["importFit"] == "short" else "warn"
                    if row["importFit"] == "short":
                        row["raiseImport"] = _raise_import(supply, weekly_need)
                else:
                    status, level = "ok", "ok"
            elif not row["target"]:
                status, level = "unplanned", "critical"
            elif row["target"] < row["dailyNeed"] * (1 - FEED_SLACK):
                status, level = "target", "critical"
                row["raiseTarget"] = _ceil_ten(row["dailyNeed"])
            elif row["known"] and row["arrives"] < per_day * LINE_STARVED:
                if row["waitingOn"]:
                    status, level = "waiting", "info"
                elif row["arrives"] >= staffed * 0.85:
                    # The line takes what its roster lets it take.
                    status, level = "staffing", "warn"
                elif row["depotStock"] < per_day:
                    status, level = "dry", "critical"
                elif row["limited"]:
                    status, level = "limit", "ok"
                else:
                    status, level = "idle", "warn"
            elif supply and row["importFit"] == "short":
                status, level = "import", "critical"
                row["raiseImport"] = _raise_import(supply, weekly_need)
            elif supply and row["importFit"] == "tight":
                status, level = "import", "warn"
            elif not supply and row["madeAt"]:
                status, level = "made", "ok"
            elif not supply and row["depotStock"] < weekly_need:
                status, level = "noimport", "warn"
            else:
                status, level = "ok", "ok"
            row["status"], row["level"] = status, level
        site["needs"].sort(
            key=lambda r: ({"critical": 0, "warn": 1, "info": 2, "ok": 3}[r["level"]], -r["perDay"])
        )
    sites.sort(key=lambda s: -s["machines"])
    depots = _depot_flow(flow, index)
    return {
        "sites": sites,
        "machines": sum(s["machines"] for s in sites),
        "unnamed": sum(u["machines"] for s in sites for u in s["unnamed"]),
        "character": character,
        "aliases": {
            ing["slug"]: resolve(ing)
            for rec in recipes.values()
            for ing in rec["ingredients"]
            if resolve(ing) != ing["slug"]
        },
        "depots": depots,
        "depotRoutes": _depot_routes(flow, index),
        # Read by _supply_facts() and dropped before the payload.
        "_ramp": ramp_at,
    }


def _serves(status: str | None, skill, needed: str | None = None) -> bool:
    """Whether someone with this skill can hold the post a station is.

    `skill` is one skill, or every skill the person holds with the top one
    first: a shop's station takes anyone holding its skill.

    A shop's queue is served at whichever station the shift posts to, and the
    station names its own skill: the fitness planning board wants a Gym Trainer,
    the hairdresser chair a Hair Stylist, the register Customer Service. An
    office's customers are served by the professional the agency employs, which
    is everyone there but the cleaners, so its computers name no skill at all.
    """
    held = [skill] if skill is None or isinstance(skill, str) else list(skill)
    if status == "office":
        top = held[0] if held else None
        return bool(top) and top != CLEANING_SKILL
    return needed is not None and needed in held


def _service_wages(staff: list, status_of: dict) -> dict:
    """The wage that prices each role's idle hours, per site, per skill.

    It is the best paid person holding that role at the site. An office's
    professionals are everyone there but the cleaners, and the office is one
    role with no skill of its own, so their best wage goes under the None key
    that role looks up; a cleaner's wage prices no hour anywhere.
    """
    wages = collections.defaultdict(lambda: collections.defaultdict(float))
    for person in staff:
        if not person["addr"]:
            continue
        key = site_key(person["addr"])
        skill = person["skill"]
        if status_of.get(key) == "office":
            if not skill or skill == CLEANING_SKILL:
                continue
            skill = None  # the office role's own key, as _hourly() builds it
        wages[key][skill] = max(wages[key].get(skill, 0.0), person["wage"])
    return wages


def _hourly(
    save: Save,
    buildings: list,
    businesses: list,
    stations: dict,
    computers: set,
    crew: dict,
    names: Names | None = None,
) -> list:
    """What each shop-front and office took per hour, against the capacity that was on.

    Three numbers meet in one grid. The customers are measured, an hour at a
    time, over the fortnight the save keeps. The capacity is whatever staff were
    rostered on that hour, at the rate of the exact stations they were posted to;
    in an office they are the professionals posted at computers, OFFICE_POST_RATE
    an hour each. A site whose stations want different skills serves a customer
    only through its slowest role, so its grid is the minimum across roles, and
    `roles` carries each role's own grid beside it. The door cap is the
    building's own limit. The smallest of them is the one that decides, and the
    finding is which.
    """
    by_key = {b["key"]: b for b in businesses}
    role_of = _station_roles(stations, names)
    out = []
    for b in buildings:
        key = site_key(_address_of(b, strict=True))
        business = by_key.get(key)
        if not business or business["status"] not in ("retail", "office"):
            continue
        office = business["status"] == "office"
        # An office posts to its computers, and any professional but a cleaner
        # can hold one. A shop's posts are its serving stations, each with the
        # skill it asks for and the customers an hour it serves.
        posts = (
            {slug: (None, OFFICE_POST_RATE) for slug in computers} if office else stations
        )

        seen = [[[] for _ in range(24)] for _ in range(7)]
        for entry in save.items(b["orderHistory"]):
            wd = entry["dayNumber"] % 7
            for report in save.items(entry.get("hourReports")):
                hour = report.get("hour")
                if hour is not None and 0 <= hour < 24:
                    seen[wd][hour].append(report.get("customers", 0))
        weeks = [max((len(h) for h in row), default=0) for row in seen]
        customers = [
            [round(sum(h) / len(h), 1) if h else None for h in row] for row in seen
        ]

        # A station the game does not let work in this type (a concession
        # stand register in a shop) serves nobody there and holds no post.
        furniture = load_store_rules().get("furniture") or {}
        kind = (business.get("typeSlug") or "").removeprefix("ba:businesstype_")
        # A station whose skill this business type takes nobody for is left
        # out: nobody can be assigned here to work it, so it serves nobody and
        # gates nothing. The game lets any item be placed in any business, so a
        # liquor store can hold a leftover fitness planning board.
        accepts = None if office else ASSIGN_SKILLS.get(business.get("typeSlug"))
        stray = collections.Counter()
        here, labels, slugs, keys = {}, {}, {}, {}
        for item in _item_instances(save, b["itemInstances"]):
            if item.get("itemName") in posts and works_in(furniture.get(item["itemName"]) or {}, kind):
                if accepts is not None and posts[item["itemName"]][0] not in accepts:
                    stray[item["itemName"]] += 1
                    continue
                here[item.get("id")] = posts[item["itemName"]]
                slugs[item.get("id")] = item["itemName"]
                labels[item.get("id")] = (
                    names.label(item["itemName"]) if names else item["itemName"]
                )
                keys[item.get("id")] = (
                    None if office else role_of.get(item["itemName"], here[item.get("id")][0])
                )
        # One role per queue the site's stations hold: per skill, with a skill
        # whose stations do different work split by _station_roles(). A set
        # decides the order they reach the payload in.
        by_role = collections.defaultdict(dict)
        skill_of = {}
        for post, (skill, rate) in here.items():
            by_role[keys[post]][post] = rate
            skill_of[keys[post]] = skill
        roles = []
        for role_key in _in_order(by_role):
            skill = skill_of[role_key]
            rates = {}
            for post, rate in by_role[role_key].items():
                label = labels[post]
                rates[label] = max(rates.get(label, 0), rate)
            biggest = max(_in_order(rates), key=rates.get)
            role = {
                "key": role_key,
                "skill": skill,
                "label": names.label(skill) if skill and names else skill,
                # The station of this role worth adding another of: the
                # largest, ties broken by name so the words do not move.
                "station": biggest,
                # Its game key, so a sentence can carry the station's name
                # as a token beside the English words made of it.
                "stationKey": min(slugs[p] for p in by_role[role_key] if labels[p] == biggest),
                "counters": sum(by_role[role_key].values()),
                "stationCount": len(by_role[role_key]),
                "staffed": [[0] * 24 for _ in range(7)],
                "onShift": [[0] * 24 for _ in range(7)],
                # Stations of this role manned that hour. Capacity and furniture
                # are two different numbers -- one projection booth is 25 an
                # hour -- and the page has to say both without mixing them.
                "posts": [[0] * 24 for _ in range(7)],
            }
            # The plural the page names this role's stations by, where
            # "register capacity" would be wrong; None where it would not.
            role["noun"] = _role_words(role, office)["noun"]
            # The furniture, always named, singular and plural, for the hour
            # cell: it counts stations even where the alert lines do not.
            role["one"] = _lower_first(role["station"])
            role["many"] = _plural(role["one"])
            roles.append(role)
        # Two roles of one skill at one site -- a hairdresser's chairs and head
        # wash -- cannot both be named by the skill, so their words name the
        # station instead (_role_words()).
        for role in roles:
            if sum(1 for other in roles if other["skill"] == role["skill"]) > 1:
                role["shared"] = True

        # The roster, read the same way the game reads it: scheduleDay.day is the
        # game day modulo 7, with 7 standing in for Sunday's 0. A site with no
        # serving station installed has no roster to read and stays at zero.
        open_hours = [[] for _ in range(7)]
        for scheduled in save.items(b.get("scheduleDays")):
            if not scheduled.get("isOpen"):
                continue
            wd = scheduled["day"] % 7
            open_hours[wd] = sorted(
                [
                    max(0, slot.get("startingHour") or 0),
                    min(24, slot.get("endingHour") or 0),
                ]
                for slot in save.items(scheduled.get("openingHourSlots"))
                if (slot.get("endingHour") or 0) > (slot.get("startingHour") or 0)
            )
        staffed = [[0] * 24 for _ in range(7)]
        on_shift = [[0] * 24 for _ in range(7)]
        if by_role:
            for scheduled in save.items(b.get("scheduleDays")):
                wd = scheduled["day"] % 7
                manned = {k: [set() for _ in range(24)] for k in by_role}
                on = {k: [0] * 24 for k in by_role}
                for shift in save.items(scheduled.get("workShifts")):
                    if shift.get("type") != STATION_SHIFT:
                        continue
                    post = shift.get("itemInstanceId")
                    if post not in here:
                        continue
                    needed = here[post][0]
                    if not _serves(
                        business["status"], crew.get(shift.get("employeeId")), needed
                    ):
                        continue
                    for hour in range(
                        max(0, shift["startingHour"]), min(24, shift["endingHour"])
                    ):
                        manned[keys[post]][hour].add(post)
                        on[keys[post]][hour] += 1
                for role in roles:
                    role_key = role["key"]
                    posts_here = by_role[role_key]
                    for hour in range(24):
                        role["staffed"][wd][hour] = sum(
                            rate
                            for post, rate in posts_here.items()
                            if post in manned[role_key][hour]
                        )
                        role["onShift"][wd][hour] = on[role_key][hour]
                        role["posts"][wd][hour] = len(
                            manned[role_key][hour] & set(posts_here)
                        )
                for hour in range(24):
                    # A customer passes through every role, so the site is only
                    # as fast as its slowest one that hour.
                    staffed[wd][hour] = min(role["staffed"][wd][hour] for role in roles)
                    on_shift[wd][hour] = min(role["onShift"][wd][hour] for role in roles)

        door = b.get("customerCapacity", 0) or 0
        effective = [
            [min(staffed[wd][h], door) if door else staffed[wd][h] for h in range(24)]
            for wd in range(7)
        ]
        entry = {
            "key": key,
            "name": business["name"],
            "office": office,
            # Whether the site has traded long enough to have been measured at
            # all. The board's hour grid shows only reported sites, as it always
            # has; the roster builder plans an unreported one anyway, because
            # its cleaning and security cover does not wait on a measurement.
            "reported": any(weeks),
            # Customers an hour per staffed computer, for the page to say.
            "postRate": OFFICE_POST_RATE if office else None,
            "customers": customers,
            "weeks": weeks,
            "thin": [w < HOUR_WEEKS_THIN for w in weeks],
            "staffed": staffed,
            "onShift": on_shift,
            "effective": effective,
            "door": door,
            # The same number under the name the cap findings think in.
            "cap": door,
            # The most an hour the site can serve with every role manned.
            "counters": min((role["counters"] for role in roles), default=0),
            "stationCount": len(here),
            "roles": roles,
            # The stations themselves, not just their totals: the roster
            # builder posts a named person to a named piece of furniture, and
            # _need_curve() packs a role's real throughputs rather than an even
            # split of its total. Sorted, because a save's item order is not a
            # promise.
            "stations": sorted(
                (
                    {
                        "id": post,
                        "slug": slugs[post],
                        "name": labels[post],
                        "skill": skill,
                        "rate": rate,
                        # A station of a split skill names its role; every
                        # other one's role is its skill (_station_role()).
                        **({"role": keys[post]} if keys[post] != skill else {}),
                    }
                    for post, (skill, rate) in here.items()
                ),
                key=lambda s: (s["skill"] or "", -s["rate"], s["name"], str(s["id"])),
            ),
            # When the doors are open, per weekday: the day's openingHourSlots
            # as [start, end] pairs, and [] for a day the site stays shut. Every
            # open day of every save seen holds exactly one slot, but the game's
            # field is a list, so this is one too, and the planner treats the
            # hour between two slots as shut rather than as a dip in trade.
            "open": open_hours,
            "basket": business["basket"],
            "peak": max(
                (c for row in customers for c in row if c is not None), default=0
            ),
        }
        entry["capHours"] = len(_capped_cells(entry))
        if stray:
            entry["unstaffable"] = _unstaffable_rows(
                stray, {slug: posts[slug][0] for slug in stray}, names)
        out.append(entry)
    return out


def _unstaffable_rows(counts: collections.Counter, skills: dict, names: Names | None) -> list:
    """Stations this business type takes nobody for, as the Staffing note names
    them: {slug, station, skill, role, n}, by station name."""
    label = lambda key: names.label(key) if key and names else key  # noqa: E731
    return sorted(
        ({"slug": slug, "station": label(slug), "skill": skills[slug],
          "role": label(skills[slug]), "n": n} for slug, n in counts.items()),
        key=lambda r: (str(r["station"]), r["slug"]),
    )


def _capped_cells(grid: dict) -> set:
    """The weekday-hour cells measured at or above the cap that was on.

    One test shared by the grid's capHours and the cap findings in
    _hour_findings(): an hour is capped when the customers measured come
    within AT_CAP of what was actually available that hour, on a weekday
    with enough weeks behind it to measure.
    """
    return {
        (wd, hour)
        for wd in range(7)
        if not grid["thin"][wd]
        for hour in range(24)
        if grid["customers"][wd][hour] is not None
        and grid["effective"][wd][hour]
        and grid["customers"][wd][hour] >= grid["effective"][wd][hour] * AT_CAP
    }


# CustomerEntriesCalculatorRetail.BuildNumberToStartCappingInitialCustomers: a
# game started at this build or later sizes a shop's arrivals off its building's
# customer capacity; an older game keeps sizing them off its shelves.
CAPPED_INITIAL_BUILD = 2847


def _initial_customers(
    build_at_start: int | None,
    size_cap,
    type_slug: str,
    sqm: float,
    products=(),
) -> float:
    """CustomerEntriesCalculatorRetail.GetInitialCustomers: a shop's base arrivals.

    For a game started at CAPPED_INITIAL_BUILD or later, which is every new
    game, it is the customer capacity of the building's size (`size_cap`, one
    entry of _door_caps()), whatever the shop holds. For an older game it is the
    largest productSalesRatio among the products the shop has on hand that are
    primary for its type, times the building's square metres. `build_at_start`
    is the save's buildNumberAtStart; a save without one reads as 0, the old
    rule, the way the game's own default does. A theater size whose layouts
    seat different crowds comes as [min, max]; its top is taken, which
    keeps the ceiling an upper bound, and the door clips it to the building's
    own number anyway.

    0 where it cannot be known: a new game's building of unknown size, or an old
    game's shop with no known floor area, holding none of its type's primary
    products, or of a type the curves file does not carry. A new game's type is
    not looked up here; _arrival_ceiling() answers None for a type it has no
    curves for.
    """
    if (build_at_start or 0) >= CAPPED_INITIAL_BUILD:
        if isinstance(size_cap, list):
            size_cap = max(size_cap, default=0)
        return size_cap if isinstance(size_cap, (int, float)) and size_cap > 0 else 0
    curves = load_demand_curves()
    curve = curves["types"].get(type_slug)
    if not curve:
        return 0
    ratios = curves["items"]
    primary = set(curve.get("p") or ())
    # A save hands back whatever is in the list, and a product entry is not
    # always the string it is supposed to be; an unhashable one would otherwise
    # take the whole board down on the set test.
    return max(
        (
            ratios.get(name, 0.0)
            for name in products
            if isinstance(name, str) and name in primary
        ),
        default=0.0,
    ) * (sqm or 0)


def _arrival_ceiling(
    type_slug: str,
    initial: float,
    promotion: float,
    base_promotion: float,
    door: int,
) -> list | None:
    """CustomerEntriesCalculatorRetail.GetCustomersByHour, per weekday and hour.

        ceil(min(initial x promotion x dayMultiplier x hourMultiplier,
                 the building's customer capacity))

    `initial` is _initial_customers(). `promotion` is the save's own
    baseCustomerPromotionMultiplier plus 0.75 x the promotion total over 100.
    `door` is the registration's customerCapacity, the grid's door. The game
    sends arrivals in open hours only; which those are is the caller's to know.
    Where `initial` is the top of a theater's capacity range, the
    grid is a bound on that venue's arrivals rather than the game's exact number.

    **These are the game's arrivals, an upper bound on customers served, never
    the demand, and the board must never print them as one.** An arrival is
    lost when the hour's staffed stations are full, and buys nothing when the
    shop holds nothing they want. It has exactly two jobs here: bounding a
    censored hour from above in _need_curve(), and answering "how much more
    could there be". Break-even's profit estimate is to reuse the pair of helpers.

    None where the curves file is missing, where it does not know the type, or
    where `initial` is nothing (see _initial_customers()). None of those is an
    error, and none of them is a ceiling of zero: a grid of zeros would silently
    cancel the censored estimate's "one more station" and read off the page as
    "no arrivals are possible here". Every number the board states comes off the
    measured grid either way.
    """
    curve = load_demand_curves()["types"].get(type_slug)
    if not curve or not initial or initial <= 0:
        return None
    promo = base_promotion + 0.75 * (promotion or 0) / 100
    day, hour = curve["d"], curve["h"]
    out = []
    for wd in range(7):
        row = []
        for h in range(24):
            reach = initial * promo * day[wd] * hour[h]
            row.append(math.ceil(min(reach, door) if door else reach))
        out.append(row)
    return out


def _fill_stations(demand: float, rates: list) -> int:
    """How many of a role's stations it takes to serve `demand` an hour.

    The smallest set whose throughputs sum to the demand, largest first, and
    never more stations than are installed. One person per station, so this is
    also the people that hour.
    """
    if demand <= 0:
        return 0
    served, count = 0.0, 0
    for rate in sorted(rates, reverse=True):
        if served >= demand:
            break
        served += rate
        count += 1
    return count


def _role_rates(role: dict, rates: dict | None) -> list:
    """The throughputs of one role's stations.

    `rates` is {role key: [throughput per station]} where the caller has the
    station list to hand. Without it the grid carries only the role's total and
    its station count, so the honest stand-in is an even split.
    """
    if rates and _role_key(role) in rates:
        return list(rates[_role_key(role)])
    count = role["stationCount"]
    if not count:
        return []
    return [role["counters"] / count] * count


def _need_curve(
    grid: dict, day: list | None = None, ceiling: list | None = None, rates: dict | None = None
) -> dict:
    """How many of each role's stations an hour actually wants, and on what basis.

    Per role, per weekday, per hour, one of four cases (the staffing scope,
    section 4):

      measured  a weekday with enough weeks behind it, an hour that did not run
                into a ceiling: the customers measured are the demand
      censored   the hour sits within AT_CAP of what was available, so the real
                demand is unknown and above it. The estimate is what the *site*
                served that hour -- its effective capacity, the slowest role
                with the door cap already in it -- plus one more of this role's
                stations, bounded from above by the arrival ceiling, the door
                cap and this role's stations installed. Starting from the role's
                own staffed capacity instead would ask a fast role to grow
                because a slow one held the hour back.
      scaled     a thin weekday, or an hour with no report, read off a measured
                weekday through the game's own day curve
      none       nothing measured anywhere: no recommendation, the site is new

    Returns {skill: {"demand": [[customers/hour]], "need": [[stations]],
    "basis": [[case]]}}. Only a measured cell may be stated as a target;
    everything else has to be qualified, and `basis` is what qualifies it.
    """
    capped = _capped_cells(grid)
    customers, door = grid["customers"], grid["door"]
    # The weekday a thin day is scaled from: the best measured one, most weeks
    # first and the earliest weekday to break a tie, so it never moves between
    # two runs of the same save.
    measured_days = [
        wd
        for wd in range(7)
        if not grid["thin"][wd] and any(c is not None for c in customers[wd])
    ]
    source = (
        min(measured_days, key=lambda wd: (-grid["weeks"][wd], wd))
        if measured_days
        else None
    )

    out = {}
    for role in grid["roles"]:
        station_rates = _role_rates(role, rates)
        installed = sum(station_rates)

        def cell(wd: int, hour: int) -> tuple:
            """One weekday-hour of this role, as (demand, basis)."""
            seen = customers[wd][hour]
            if grid["thin"][wd] or seen is None:
                return (0.0, None)  # nothing of its own; the caller may scale it
            if (wd, hour) not in capped:
                return (seen, "measured")
            served = grid["effective"][wd][hour]
            step = max(station_rates) if station_rates else 0
            bounds = [served + step]
            if installed:
                bounds.append(installed)
            if door:
                bounds.append(door)
            if ceiling:
                bounds.append(ceiling[wd][hour])
            return (max(seen, min(bounds)), "censored")

        demand = [[0.0] * 24 for _ in range(7)]
        basis = [["none"] * 24 for _ in range(7)]
        for wd in range(7):
            for hour in range(24):
                value, case = cell(wd, hour)
                if case:
                    demand[wd][hour], basis[wd][hour] = value, case
                elif source is not None and day and day[source]:
                    from_value, from_case = cell(source, hour)
                    if from_case:
                        demand[wd][hour] = from_value * day[wd] / day[source]
                        basis[wd][hour] = "scaled"
        out[_role_key(role)] = {
            "demand": [[round(v, 1) for v in row] for row in demand],
            "need": [[_fill_stations(v, station_rates) for v in row] for row in demand],
            "basis": basis,
        }
    return out


# ------------------------------------------------------------ roster building
# The rules any suggested roster has to obey, read from BigAmbitions.dll at
# VERIFIED_BUILD. docs/dashboard-reference.md, "The rules every planned week
# keeps", lists each source.
# The longest shift, and the most hours the plan gives anybody in one day: the
# game's own auto-filler stops at 12 a day too, short of the 14 that raise
# sickness (ScheduleHelper.GetOverworkedDays).
SHIFT_CAP = 12  # ScheduleHelper.ShiftLengthCap, ScheduleAutoFiller.MaxEmployeeHoursPerDay
SLACK_SHARE = 0.10  # of a site's required station-hours, spent bridging troughs
# The shortest piece the plan will cut a shift into, and the shortest head it
# will leave behind. Not a game rule: the game takes a one-hour shift happily.
# It is this feature's whole premise -- the week it replaces is 182 two-hour
# scraps -- so where a demand can only be met by splitting a shift, the split
# has to be worth typing or the demand is better reported unmet.
MIN_SPLIT = 4
FULL_TIME = (30, 50)  # the band headcount is sized in, JOB_DEMANDS' fulltime
SECURITY_SKILL = "ba:skill_securityguard"
# Stations with shifts but no queue: they get one person for every open hour
# rather than a derived need, because the game stores no model to derive one
# from. Cleaning feeds cleanliness and the CleanWorkplace demand; a security
# locker sets the building's security level.
COVER_STATIONS = {
    "ba:itemname_cleaningstation": ("clean", CLEANING_SKILL),
    "ba:itemname_securityguardlocker": ("security", SECURITY_SKILL),
}
WEEKEND_WEEKDAYS = (6, 0)  # the game's days 6 and 7, which freeweekends asks for


def _cut_run(start: int, end: int) -> list:
    """One run of cover split into the fewest legal shifts, as equal as possible.

    12 hours is the longest shift the game accepts, and 12 divides a 24-hour day
    exactly twice. Deterministic and search-free: ceil(L / 12) pieces, the
    longer ones first, so a 13-hour run is 7 then 6 and a 24-hour day is two
    twelves.
    """
    length = end - start
    if length <= 0:
        return []
    pieces = math.ceil(length / SHIFT_CAP)
    base, extra = divmod(length, pieces)
    out, at = [], start
    for index in range(pieces):
        span = base + (1 if index < extra else 0)
        out.append((at, at + span))
        at += span
    return out


def _runs(hours) -> list:
    """Contiguous [start, end) runs over a set of hours."""
    out = []
    for hour in sorted(hours):
        if out and out[-1][1] == hour:
            out[-1][1] = hour + 1
        else:
            out.append([hour, hour + 1])
    return [(start, end) for start, end in out]


def _plan_people(save: Save, staff: list) -> dict:
    """Everyone hired, as the roster builder has to think of them.

    A demand the table does not know is skipped rather than guessed at, and a
    person with no hours demand has **no band** — 225 of 227 on the reference
    save demand full time, but the plan may not invent one for the other two.
    """
    demands, training = {}, set()
    # The stations each person has a shift on now, at any site: an office's
    # plan keeps somebody at their own desk where it can (_placement_rank()).
    home = collections.defaultdict(set)
    for reg in save.items(save.root.get("BuildingRegistrations")):
        for day in save.items(reg.get("scheduleDays")):
            for shift in save.items(day.get("workShifts")):
                if isinstance(shift, dict) and shift.get("employeeId") is not None:
                    home[shift["employeeId"]].add(shift.get("itemInstanceId"))
    for employee in save.items(save.root.get("EmployeeInstances")):
        if save.deref(employee.get("trainingSession")):
            training.add(employee.get("id"))
        demands[employee.get("id")] = [
            slug
            for slug in dict.fromkeys(save.items(employee.get("demands")))
            if slug in JOB_DEMANDS
        ]
    out = {}
    for person in staff:
        held = demands.get(person["id"], [])
        rules = [JOB_DEMANDS[slug] for slug in held]
        out[person["id"]] = {
            "id": person["id"],
            "name": person["name"],
            "skills": set(person["skills"] or ()),
            "wage": person["wage"] or 0.0,
            "addr": person["addr"],
            "demands": held,
            "band": next((r[1] for r in rules if r[0] == "hours"), None),
            "days": next((r[1] for r in rules if r[0] == "days"), None),
            "weekendsOff": any(r[0] == "daysoff" for r in rules),
            # Every blackout window of every hours demand this person holds.
            "blackouts": sorted(
                window for rule in rules if rule[0] == "noshift" for window in rule[1]
            ),
            "nocleaning": any(r[0] == "nocleaning" for r in rules),
            # In training (trainingSession set): the game will not assign them
            # to a business, so no plan counts on them from the bench.
            "training": person["id"] in training,
            # The weekly hours the game has them on now, at the one site they
            # work: a plan giving them fewer names them (`fewer`).
            "now": person.get("hours") or 0,
            "home": home.get(person["id"], set()),
            # Each desk or chair demand, as the item names that meet it.
            "desks": [tuple("ba:itemname_" + name for name in r[1]) for r in rules if r[0] == "desk"],
            # The site they work at, as a business is keyed (_site_pool()).
            "site": site_key(person["addr"]) if person["addr"] else None,
        }
    return out


def _fresh_state() -> dict:
    """One person's week as the placer fills it in."""
    return {
        "hours": 0.0,
        "busy": [set() for _ in range(7)],
        "days": set(),
        "stations": set(),
    }


def _copy_state(entry: dict) -> dict:
    """One person's week, deep enough that filling the copy leaves the original alone."""
    return {
        "hours": entry["hours"],
        "busy": [set(hours) for hours in entry["busy"]],
        "days": set(entry["days"]),
        "stations": set(entry["stations"]),
    }


def _week_without(entry: dict, shift: dict) -> dict:
    """One person's week with one of their entries taken off, to test a swap on.

    Only as deep as a test reads: the hours, the days and the entry's own day
    are the copy's, the other six days and the stations are the original's.
    Read it, never fill it in; `_copy_state()` is the one to write to.
    """
    wd = shift["wd"]
    busy = list(entry["busy"])
    busy[wd] = busy[wd].difference(range(shift["from"], shift["to"]))
    days = set(entry["days"])
    if not busy[wd]:
        days.discard(wd)
    return {
        "hours": entry["hours"] - (shift["to"] - shift["from"]),
        "busy": busy,
        "days": days,
        "stations": entry["stations"],
    }


def _usable(person: dict, skill: str | None, kind: str) -> bool:
    """Whether the plan would ever put this person on that role at all.

    The two tests that are about the *role* rather than about a particular hour,
    kept in one place because three callers have to agree on them or the board
    contradicts itself: `_can_work()` when it places somebody, `here["flex"]`
    when it decides whose week to start, and `headcount.have` when it counts who
    is here. They disagreed once, and the scarcity key went back to letting the
    employee id decide which station turned into hiring lines.

    A customer service employee is never put on a cleaning station -- the plan's
    one policy, see `_can_work()` -- and neither is somebody whose contract says
    no cleaning, which is the game's own demand.
    """
    if skill and skill not in person["skills"]:
        return False
    return not (
        kind == "clean" and (person["nocleaning"] or SERVICE_SKILL in person["skills"])
    )


def _can_work(person: dict, state: dict, slot: dict) -> bool:
    """Would this shift break any rule the game, the person's demands, or the
    plan's own policy set?

    All but one test here is a line of section 2 of the staffing scope, and never
    a judgement call. The exception is named and deliberate: a customer service
    employee is never put on a cleaning station. The game allows it and the
    board's own model says it works, but a register standing empty while the
    person who could be on it mops costs more than a cleaner's wage, so the plan
    does not offer it. Cleaning nobody here may do becomes a hiring line, which
    is the honest answer: hire a cleaner.

    A slot nobody passes becomes a hiring line, never a broken demand.

    Two halves, because the placer asks this a million times on a big save:
    `_may_take()` is the part no week can change, so the placer asks it once
    per slot shape, and `_has_room()` the part that moves as the week fills.
    """
    return _may_take(person, slot) and _has_room(person, state, slot)


def _may_take(person: dict, slot: dict) -> bool:
    """The rules of `_can_work()` that read the person and the slot, never the week.

    The role, free weekends and blackout windows: for one person, the same
    answer for every slot of one skill, kind, day and hours, however far the
    week has filled.
    """
    if not _usable(person, slot["skill"], slot["kind"]):
        return False
    if person["weekendsOff"] and slot["wd"] in WEEKEND_WEEKDAYS:
        return False
    # The game's own test is any overlap with the window, not containment.
    start, end = slot["from"], slot["to"]
    return not any(low < end and start < high for low, high in person["blackouts"])


def _slot_shape(slot: dict) -> tuple:
    """What `_may_take()` reads of a slot: slots alike in it get one answer."""
    return (slot["skill"], slot["kind"], slot["wd"], slot["from"], slot["to"])


def _has_room(person: dict, state: dict, slot: dict) -> bool:
    """The rules of `_can_work()` that read the person's week as it stands."""
    start, end, wd = slot["from"], slot["to"], slot["wd"]
    hours = end - start
    # The 12-hour day before the overlap: it is one comparison. Every test here
    # is a veto, so their order only decides how soon the answer is known.
    busy = state["busy"][wd]
    if len(busy) + hours > SHIFT_CAP:
        return False
    if not busy.isdisjoint(range(start, end)):
        return False
    # The week's ceiling. Their own band's if they have one, and full time's 50
    # if they do not: that is not a demand invented for somebody who holds none
    # -- nobody is ever reported short against it -- it is the most the plan will
    # hand anybody, because the roster now fills one person up before it starts
    # the next and without a ceiling it gave a person with no hours demand 84
    # hours, twelve a day for seven days.
    if state["hours"] + hours > (person["band"] or FULL_TIME)[1]:
        return False
    return not (
        person["days"] is not None
        and wd not in state["days"]
        and len(state["days"]) >= person["days"]
    )


def _placement_rank(person: dict, state: dict, slot: dict, here: dict) -> tuple:
    """Which of the eligible people takes this slot.

    An employee works one business. `assignedAddress` binds them to a single
    building, so the 30 hours full time demands have to come from this site or
    from nowhere, and the plan cannot leave anybody to be topped up next door.
    That fixes the objective, in the player's own order of priority:

    1. **The fewest people, each on a full week.** Nobody new is started while
       somebody already on this roster can legally take the slot, and among those
       the hours level up — the emptiest week first — so they cross their floor
       together rather than one of them being stranded under it. Levelling across
       *everybody* was the bug: 168 station-hours across nine staff came out as
       nine people on 18 hours and nine failed demands, where it is four people
       on 36 to 48 hours and five to post somewhere else. Past the floor the
       levelling stops: an even share buys nothing once everybody's demand is
       met, and it split days that would otherwise be each other's copy.

       Which name is started matters as much as how many, so two things settle
       it. **The least flexible person first**: somebody who holds two of this
       site's roles is the only one who can cover the other, and spending them on
       the register turned a cleaning station's whole week into hiring lines --
       `hire 4` for a locker, decided by nothing but whose employee id sorted
       first. **Then the most room left in their band**: a part-timer starting a
       48-hour week means a second name at 30 hours where one full-timer covers
       it alone.
    2. **Then every other demand**: a day they are not already on, for somebody
       still short of a four- or five-day week. The rest are not ranked here at
       all — blackout windows, free weekends and cleaning are tested in
       `_can_work()` and never traded away.
    3. **Then the longest shifts.** Nothing to rank: the shifts are cut before
       anybody is placed, into the fewest that stay inside the 12-hour cap, and
       the 12-hour day belongs to `_can_work()`.

    Then continuity — already on this station the day before or after, so the
    player types fewer distinct names — the site's own staff before a bench
    member, the cheaper wage, and the employee id. The last one is not cosmetic:
    a roster that reshuffles names between two runs of the same save is unusable,
    because the player is halfway through typing it.

    Before all of it, a hire (_placeholder()) after every real person: a line
    goes to a hire only where nobody the site has, or the bench, can take it.
    """
    floor = person["band"][0] if person["band"] else 0
    # A four- or five-day week is exactly four or five, so somebody still short
    # of their count wants a day they are not already on. It never overrides the
    # hours they are short, and it never bends another rule: a slot they may not
    # work is not offered to them at all.
    wants_day = (
        person["days"] is not None
        and slot["wd"] not in state["days"]
        and len(state["days"]) < person["days"]
    )
    adjacent = (
        (slot["station"], (slot["wd"] - 1) % 7) in state["stations"]
        or (slot["station"], (slot["wd"] + 1) % 7) in state["stations"]
    )
    # Asked once and read by two keys below: this runs for every candidate of
    # every slot, and only somebody holding a desk demand at a site whose
    # furniture is known has a desk to test.
    fits = _desk_fits(person, slot, here) if person.get("desks") and here.get("groups") else True
    short = state["hours"] < floor
    # Which keys are live at all: a name already on this roster is being filled
    # up, a name that is not is being chosen, and those are different questions.
    on_roster = person["id"] in here["rostered"]
    return (
        # A hire only where nobody real can take the slot (_place_hires()): a
        # placeholder holds one skill, so the scarcity key below would
        # otherwise start one ahead of a real person holding two.
        1 if person.get("hire") else 0,
        # Headcount first: one more name on the roster is the expensive thing,
        # because it is one more person this site owes 30 hours to.
        0 if person["id"] in here["rostered"] else 1,
        # Within that tier, the site's own person whose desk or chair demand
        # this very station meets: otherwise a lawyer with no such demand takes
        # the executive desk ahead of the one who asks for it, who is then put
        # at a desk that breaks it. Only where the site's furniture is known
        # (an office), and never somebody from the bench over the site's own.
        0 if here.get("groups") and person["addr"] and person.get("desks")
        and fits else 1,
        # Then whose floor is still at stake, emptiest week first. A part-timer
        # already past their ten hours waits behind a full-timer still under
        # thirty, and two people under theirs rise towards it together. Past the
        # floor everybody ties, so the keys below decide instead of an even
        # share nobody asked for.
        #
        # Flat for anybody not on the roster yet, the mirror of the two keys
        # below. Nobody has hours before their first shift, so all these can say
        # about a new name is whether they hold an hours demand at all -- and
        # starting somebody because they have a floor, ahead of the person this
        # site actually needs, is how a part-timer came to start a week a
        # full-timer would carry alone.
        (0 if short else 1) if on_roster else 0,
        (state["hours"] if short else 0.0) if on_roster else 0.0,
        # The next two keys only ever choose *which name to start*, so they are
        # flat for anybody already on the roster -- the key above has separated
        # the two groups, and inside the roster these would quietly level the
        # week again, splitting days that would otherwise be each other's copy.
        #
        # How many of *this site's* roles they could work, fewest first: the
        # site's only guard is not spent on a register while the locker goes
        # unmanned. Counted against the roles here rather than against every
        # skill they hold, which would rank somebody by stations this site does
        # not have.
        0 if on_roster else here["flex"].get(person["id"], 0),
        # Then the most room left in their band, so the bigger contract starts
        # the week and the site owes as few people thirty hours as it can.
        0.0 if on_roster else -((person["band"] or FULL_TIME)[1] - state["hours"]),
        0 if wants_day else 1,
        # A desk or chair demand is met by the station's own furniture: the
        # station that meets theirs first, then the one they work now, so a
        # new week does not move a whole office to other desks (Peter's
        # in-game test, 25 September 2026).
        0 if fits else 1,
        0 if slot["station"] in (person.get("home") or ()) else 1,
        0 if adjacent else 1,
        # A bench member is a last resort even at equal hours: drawing one costs
        # the checklist a MyEmployees step and binds them to this building, so
        # the site's own staff are filled up first.
        0 if person["addr"] else 1,
        person["wage"],
        str(person["id"]),
    )


def _desk_fits(person: dict, slot: dict, here: dict) -> bool:
    """Whether a station meets every desk or chair demand a person holds.

    True for somebody with none, and where the site's furniture is not known.
    """
    wants = person.get("desks") or ()
    groups = here.get("groups") or {}
    if not wants or not groups:
        return True
    held = groups.get(slot["station"], ())
    return all(any(name in held for name in names) for names in wants)


def _cover_runs(need: list, rates: list, open_hours: list) -> dict:
    """Which hours each station of one role has to be manned, before bridging.

    Station k is wanted on every hour the need reaches k + 1, and only while the
    doors are open. Stations are indexed largest-throughput first, the order
    _fill_stations() packs them in.
    """
    out = {}
    for index in range(len(rates)):
        wanted = [set() for _ in range(7)]
        for wd in range(7):
            for hour in open_hours[wd]:
                if need[wd][hour] >= index + 1:
                    wanted[wd].add(hour)
        out[index] = wanted
    return out


def _bridge_troughs(wanted: dict, wages: dict, budget: float, slots: list) -> tuple:
    """Buy the cheapest dips between two runs of the same station, while the budget lasts.

    One budget for the whole site, and one queue: every gap of every role is
    priced at its hours times that role's wage and the cheapest go first, so a
    one-hour lunch dip at a cheap role is bought before an hour of an expensive
    one, whatever order the roles happen to be in. No width constant to defend.
    Ties break on the earlier gap and then on the role, so the result does not
    move between two runs of the same save.

    A gap only counts if it lies wholly inside one of the day's opening slots.
    The hour between two slots is the doors being shut, not trade dipping, and
    bridging it would roster somebody into a closed shop.

    Returns the hours spent and what they cost in wages.
    """
    # A role's own key can be None, which will not sort against a string, so
    # the queue carries its position in _in_order() instead.
    order = _in_order(wanted)
    gaps = []
    for rank, skill in enumerate(order):
        for index in sorted(wanted[skill]):
            for wd in range(7):
                runs = _runs(wanted[skill][index][wd])
                for (_first, start), (end, _second) in zip(runs, runs[1:]):
                    if not any(
                        low <= start and end <= high for low, high in slots[wd]
                    ):
                        continue  # the doors are shut in there
                    gaps.append(
                        ((end - start) * wages.get(skill, 0.0), wd, start, rank,
                         index, end)
                    )
    gaps.sort()
    spent, cost = 0.0, 0.0
    for price, wd, start, rank, index, end in gaps:
        hours = end - start
        if spent + hours > budget:
            continue  # a cheaper gap is already bought; a smaller one may fit
        wanted[order[rank]][index][wd].update(range(start, end))
        spent += hours
        cost += price
    return spent, cost


# --- hires: placeholder people inside the one placer
# A hire is somebody the week needs and the site has not got. They are not
# packed onto weeks of their own after the placer is done: they go through the
# placer, as placeholder people with a plain full-time contract and no other
# demand, so the same repair passes size their weeks under the same caps and
# floors as everybody else's (_place_hires()). They rank after every real
# person (_placement_rank()), so nobody who could work a line loses it to one.
HIRE_ID = "hire:"


def _placeholder(skill, n: int) -> dict:
    """The n-th hire a week counts for one skill: full time (30 to 50 hours), nothing else.

    The same fields as a _plan_people() row, so every rule reads them the same
    way; `hire` marks them, and their id (`hire:<skill>:<n>`) is the same on
    every run of one save.
    """
    return {
        "id": f"{HIRE_ID}{skill}:{n}",
        "name": None,
        "skills": {skill} if skill else set(),
        "skill": skill,
        "wage": 0.0,
        "addr": None,
        "demands": [],
        "band": FULL_TIME,
        "days": None,
        "weekendsOff": False,
        "blackouts": [],
        "nocleaning": False,
        "training": False,
        "now": 0,
        "home": set(),
        "desks": [],
        "hire": True,
    }


def _hire_bound(lines: list, people: list) -> int:
    """The fewest hires a role's week could need: where the search for the count starts.

    `lines` are all the week's lines of the role, open or held; `people` the
    people here who may work it. Each term holds whoever holds which line and
    however lines are cut between people:

    - every hour of the lines is worked by somebody here, at most their band's
      ceiling (50 without one) each, or by a hire, at most 50 each;
    - every hour of one day's lines by somebody working at most 12 hours that
      day;
    - and the lines running at one hour by as many people at that hour, one
      line each.

    Nothing about where the one-at-a-time fill left the open lines is a
    bound: the swaps spread them over the week (a law firm's 267 open hours
    all on a Friday, 22 of them at one hour, are six people's work, not 22).
    """
    hours = sum(s["to"] - s["from"] for s in lines)
    held = sum((person["band"] or FULL_TIME)[1] for person in people)
    bound = math.ceil(max(0, hours - held) / FULL_TIME[1])
    helpers = len(people)
    for wd in range(7):
        day = [s for s in lines if s["wd"] == wd]
        if not day:
            continue
        bound = max(bound, math.ceil(sum(s["to"] - s["from"] for s in day) / SHIFT_CAP) - helpers)
        running = [0] * 24
        for s in day:
            for hour in range(max(s["from"], 0), min(s["to"], 24)):
                running[hour] += 1
        bound = max(bound, max(running) - helpers)
    return max(bound, 0)


def _fill_hole(row: dict, pool: list, state: dict, here: dict) -> bool:
    """Put the best eligible person on one open line of the week, in place.

    `_take_slot()` for a line that is already a row of the week: `pool` is
    everybody `_may_take()` passes for it.
    """
    person = _best_for(row, pool, state, here)
    if person is None:
        return False
    here["rostered"].add(person["id"])
    _take_over(row, person, state)
    return True


# The orders a hire's lines are dealt in, and whether each line goes to the
# first hire with room (first fit) or the emptiest (balanced): the old packer's
# four ways of packing the open lines, tried at each count before the count
# rises, since none of them always needs the fewest people.
HIRE_ORDERS = (
    lambda s: (s["wd"], s["from"], s["to"], str(s["station"])),
    lambda s: (s["wd"], -(s["to"] - s["from"]), s["from"], str(s["station"])),
)
HIRE_PACKINGS = tuple((order, balanced) for balanced in (False, True) for order in HIRE_ORDERS)
# Tried before those: the weekend's lines dealt first, by the clock, so they
# land on as few hires as the count allows and the rest keep their weekends
# free, which a good share of candidates ask for.
WEEKEND_FIRST = (lambda s: (s["wd"] not in WEEKEND_WEEKDAYS, s["wd"], s["from"], s["to"],
                            str(s["station"])), False)


def _deal_hires(rows: list, hires: list, state: dict, here: dict, order, balanced,
                allowed: dict, ordered: bool = False) -> None:
    """Deal the open lines out to the hires, in `order`, first fit or balanced.

    `allowed` keeps `_may_take()`'s answer for a placeholder by slot shape,
    the same for every deal of one search; `ordered` says `rows` already
    stand in `order`.
    """
    by_skill = collections.defaultdict(list)
    for hire in hires:
        by_skill[hire["skill"]].append((hire, state[hire["id"]]))
    ceiling = FULL_TIME[1]
    # A hire with no room left for the shortest line of the role is passed
    # over from then on, not asked again for every line after it.
    shortest = {}
    for row in rows:
        if row["employee"] is None:
            shortest[row["skill"]] = min(shortest.get(row["skill"], 24), row["to"] - row["from"])
    for row in (rows if ordered else sorted(rows, key=order)):
        if row["employee"] is not None:
            continue
        # Placeholders of one skill hold no demand, so one answers for all.
        mine = by_skill.get(row["skill"], ())
        if not mine:
            continue
        shape = _slot_shape(row)
        if shape not in allowed:
            allowed[shape] = _may_take(mine[0][0], row)
        if not allowed[shape]:
            continue
        # _has_room() for a placeholder, which has full time's band and no day
        # count: the deal asks it more than anything else in the search.
        start, end, wd = row["from"], row["to"], row["wd"]
        hours = end - start
        span = range(start, end)
        able = (hire for hire, week in mine
                if week["hours"] + hours <= ceiling
                and len(week["busy"][wd]) + hours <= SHIFT_CAP
                and week["busy"][wd].isdisjoint(span))
        if balanced:
            able = list(able)
            hire = min(able, key=lambda h: state[h["id"]]["hours"]) if able else None
        else:
            hire = next(able, None)
        if hire is None:
            continue
        here["rostered"].add(hire["id"])
        _take_over(row, hire, state)
        if state[hire["id"]]["hours"] + shortest[row["skill"]] > ceiling:
            mine[:] = [entry for entry in mine if entry[0] is not hire]


def _may_split(rows: list, hires: list, state: dict) -> bool:
    """Whether the lines a deal left open could still go to its hires in two pieces each.

    Only what no cut changes: every open line long enough for two pieces of
    MIN_SPLIT, a hire of its role to take them, and the role's open hours
    within the room those hires have left under 50.
    """
    room = collections.Counter()
    for hire in hires:
        room[hire["skill"]] += max(0, FULL_TIME[1] - state[hire["id"]]["hours"])
    owed = collections.Counter()
    for row in rows:
        if row["employee"] is None:
            if row["to"] - row["from"] < 2 * MIN_SPLIT or not room[row["skill"]]:
                return False
            owed[row["skill"]] += row["to"] - row["from"]
    return bool(owed) and all(hours <= room[skill] for skill, hours in owed.items())


def _cut_role(indices: list, rows: list, pool: list, by_id: dict, state: dict, here: dict,
              before: dict) -> None:
    """Cut one role's lines nobody here may take whole, for people here (_cut_for_pool()).

    All or nothing for the role: the pieces go out a line at a time, so where
    they leave anybody who took one short of a demand -- under their band's
    floor, off an exact day count -- that their week before the pass met, or
    had no hours at all, the role's pass is undone and its lines are the
    hires'. A guard with a four-day week cannot hold seven afternoons, and 24
    hours of pieces is not a full-time week; spare (no hours) is fine, and
    somebody already short is not held to a demand the pass only brings
    nearer. One role never undoes another's cut.

    Each line is cut nearest its middle first. Where that leaves lines for
    hires, or fails, the pass is asked again with one cut hour for every line
    (up to eight of them, nearest the middle first): six days of a locker
    08-20 cut 08-14 and 14-20 run a part-time guard to 30 hours on the fifth
    afternoon, where 08-15 and 15-20 cover all six. The pass that covers the
    most lines and passes is kept, the earlier one on a tie. `indices` are
    the role's lines in `rows`, which a cut appends to.
    """
    snapshot = ([dict(row) for row in rows],
                {person["id"]: _copy_state(state[person["id"]]) for person in pool},
                set(here["rostered"]))

    def restore():
        rows[:] = [dict(row) for row in snapshot[0]]
        for pid, entry in snapshot[1].items():
            state[pid] = _copy_state(entry)
        here["rostered"] = set(snapshot[2])

    def short(pid, entry):
        return _short_of_demands(by_id[pid], entry, before.get(pid, (0.0, 0)))

    def run(at):
        """How many lines one pass covers, or None where it leaves somebody short."""
        failed, took, covered = set(), set(), 0
        for index in indices:
            row = rows[index]
            if _slot_shape(row) in failed:
                continue  # a cut only fills weeks, so it fails again
            cut = _cut_for_pool(row, rows, pool, state, here, at)
            if cut:
                took.update(cut)
                covered += 1
            else:
                failed.add(_slot_shape(row))
        # Short before the pass (with hours) is no veto: the pieces only add.
        if any(short(pid, state[pid]) and not short(pid, snapshot[1][pid]) for pid in took):
            return None
        return covered

    best = (run(None), None)
    if best[0] != len(indices):
        # From the lines as they were: the pass just run cut them.
        lines = [snapshot[0][i] for i in indices]
        middle = sum(line["from"] + line["to"] for line in lines) / (2 * len(lines))
        points = sorted({at for line in lines
                         for at in range(line["from"] + MIN_SPLIT, line["to"] - MIN_SPLIT + 1)},
                        key=lambda at: (abs(at - middle), at))[:8]
        for at in points:
            restore()
            covered = run(at)
            if covered is not None and (best[0] is None or covered > best[0]):
                best = (covered, at)
        restore()
        if best[0]:
            run(best[1])


def _cut_for_pool(row: dict, rows: list, pool: list, state: dict, here: dict,
                  at=None) -> tuple:
    """Cut one line nobody here may take whole between two people who may each take a piece.

    A line runs the whole of a station's day, so somebody with no mornings or
    no evenings can never take it whole: a locker open 08-20 turned away both
    of a shop's guards and hired two more, where the game's own week had them
    share it. The cut nearest the middle first, both pieces MIN_SPLIT or
    longer; each piece to whom `_best_for()` puts first among those
    `_may_take()` passes for that piece, two different people; or at `at`
    alone, where given. The head keeps the row, the tail is appended to
    `rows`. Returns the two people's ids, or () where no cut fits.
    """
    start, end = row["from"], row["to"]
    points = sorted(range(start + MIN_SPLIT, end - MIN_SPLIT + 1),
                    key=lambda cut: (abs(2 * cut - start - end), cut))
    if at is not None:
        points = [at] if at in points else []
    for at in points:
        head, tail = dict(row, to=at), dict(row, **{"from": at})
        first = _best_for(head, [p for p in pool if _may_take(p, head)], state, here)
        if first is None:
            continue
        second = _best_for(tail, [p for p in pool if p is not first and _may_take(p, tail)],
                           state, here)
        if second is None:
            continue
        row["to"] = at
        for piece, person in ((row, first), (tail, second)):
            here["rostered"].add(person["id"])
            _take_over(piece, person, state)
        rows.append(tail)
        return (first["id"], second["id"])
    return ()


def _short_of_demands(person: dict, entry: dict, before: tuple) -> bool:
    """Whether a week here with hours in it misses the band's floor or an exact day count."""
    hours = entry["hours"] - before[0]
    if not hours:
        return False
    if person["band"] and hours < person["band"][0]:
        return True
    return person["days"] is not None and len(entry["days"]) - before[1] != person["days"]


def _split_open(rows: list, hires: list, state: dict, here: dict) -> None:
    """Cut each line still open between two hires, a piece each.

    Deals and swaps move whole lines, so nine 11-hour lines -- a station
    22 hours on four days and 11 on a fifth -- come out three hires where two
    can work them: 44 hours each, and the fifth day's line cut 6 and 5, 50 and
    49 hours. Every cut point that leaves both pieces MIN_SPLIT or longer is
    asked, for each hire in order: the longest piece they have room for
    first, the head of the line before its tail, and the other piece to the
    first other hire with room; both pieces pass `_has_room()`. A shorter
    piece is what fits a hire already working part of that day. Asked only
    where the whole lines left a hire short (_place_hires()).
    """
    clock = HIRE_ORDERS[0]
    for row in sorted((r for r in rows if r["employee"] is None), key=clock):
        mine = [hire for hire in hires if hire["skill"] == row["skill"]]
        if not mine or not _may_take(mine[0], row):
            continue
        start, end = row["from"], row["to"]
        cut = _split_for(row, mine, state, start, end)
        if cut is None:
            continue
        first, second, at, head_first = cut
        tail = dict(row, **{"from": at})
        row["to"] = at
        _take_over(row, first if head_first else second, state)
        _take_over(tail, second if head_first else first, state)
        rows.append(tail)
        here["rostered"].update((first["id"], second["id"]))


def _split_for(row: dict, mine: list, state: dict, start: int, end: int):
    """The first cut of one line two hires can take: (first, second, at, head to first)."""
    for first in mine:
        week = state[first["id"]]
        most = min(FULL_TIME[1] - week["hours"], SHIFT_CAP - len(week["busy"][row["wd"]]),
                   end - start - MIN_SPLIT)
        for piece in range(int(most), MIN_SPLIT - 1, -1):
            for head_first in (True, False):
                at = start + piece if head_first else end - piece
                mine_piece = dict(row, to=at) if head_first else dict(row, **{"from": at})
                if not _has_room(first, week, mine_piece):
                    continue
                other = dict(row, **{"from": at}) if head_first else dict(row, to=at)
                second = next((hire for hire in mine if hire is not first
                               and _has_room(hire, state[hire["id"]], other)), None)
                if second is not None:
                    return first, second, at, head_first
    return None


def _open_crowded(residue: list, limit: int) -> bool:
    """Whether _spread_open() would look for a swap at all: an hour more open
    lines of a role run at than `limit` hires, or a day with more of them
    than `limit` twelve-hour days, as its first pass reads them."""
    at = [[0] * 24 for _ in range(7)]
    day = [0] * 7
    for s in residue:
        day[s["wd"]] += s["to"] - s["from"]
        for hour in range(s["from"], s["to"]):
            at[s["wd"]][hour] += 1
    return any(at[wd][hour] and (at[wd][hour] > limit or day[wd] > limit * SHIFT_CAP)
               for wd in range(7) for hour in range(24))


def _spread_open(residue: list, shifts: list, pool: list, state: dict, before: dict,
                 limit: int) -> list:
    """Move the open shifts off the day they pile up on, by swapping days with staff.

    The placer fills the people a site already has before it counts a hire, so
    the shifts nobody can take pile up on whichever day their weeks ran out: at
    a law firm of 84 lawyers, 267 hours all on a Friday, 22 of them at the same
    hour, which packed onto 22 hires of one day each, 7 to 14 hours a week
    (Peter's in-game test, 25 September 2026). The hires those hours need are
    about ceil(hours / 50). While more open shifts than that run at one hour,
    or more than that many 12-hour days of them fall on one day, one of them
    goes to somebody here who is off that day, and one of their own shifts of
    the role on another day, where the open ones are fewer, is opened in its
    place: nobody's week breaks a rule or a demand for it (_can_work()), and
    nobody drops under their own hours floor or day count, or under the hours
    they have if they are under it already. `limit` is the hires being tried
    (_place_hires()). Returns the open shifts afterwards, the same shift rows,
    reassigned in place. Deterministic.
    """
    if not residue:
        return residue
    skill = residue[0]["skill"]
    residue = list(residue)
    by_id = {person["id"]: person for person in pool}
    stuck = set()

    def load():
        at = [[0] * 24 for _ in range(7)]
        day = [0] * 7
        for s in residue:
            day[s["wd"]] += s["to"] - s["from"]
            for hour in range(s["from"], s["to"]):
                at[s["wd"]][hour] += 1
        return at, day

    def find(wd, hour, at, day):
        rows = sorted((s for s in residue if s["wd"] == wd and s["from"] <= hour < s["to"]),
                      key=lambda s: (s["from"], s["to"], str(s["station"])))
        free = sorted((pid for pid in by_id if not state[pid]["busy"][wd]), key=str)
        # Everybody's own lines of the role on the other days, read once: the
        # search below only reads the week.
        theirs = collections.defaultdict(list)
        for s in shifts:
            if s["skill"] == skill and s["wd"] != wd and s["employee"] in by_id:
                theirs[s["employee"]].append(s)
        for mine_list in theirs.values():
            mine_list.sort(key=lambda s: (s["wd"], s["from"]))
        for open_row in rows:
            for pid in free:
                person = by_id[pid]
                if not _usable(person, skill, open_row["kind"]):
                    continue
                for mine in theirs.get(pid, ()):
                    if any(at[mine["wd"]][h] + 1 > limit for h in range(mine["from"], mine["to"])):
                        continue
                    if day[mine["wd"]] + (mine["to"] - mine["from"]) > limit * SHIFT_CAP:
                        continue
                    # The floor first: it reads the hours alone.
                    here = state[pid]["hours"] - before[pid][0]
                    after = here - (mine["to"] - mine["from"]) + (open_row["to"] - open_row["from"])
                    floor = person["band"][0] if person["band"] else 0
                    if after < min(floor, here):
                        continue
                    trial = _copy_state(state[pid])
                    trial["hours"] -= mine["to"] - mine["from"]
                    trial["busy"][mine["wd"]].difference_update(range(mine["from"], mine["to"]))
                    if not trial["busy"][mine["wd"]]:
                        trial["days"].discard(mine["wd"])
                    if not _can_work(person, trial, open_row):
                        continue
                    days_after = len(trial["days"] | {wd}) - before[pid][1]
                    if person["days"] is not None and days_after < min(
                            person["days"], len(state[pid]["days"]) - before[pid][1]):
                        continue
                    return open_row, person, mine
        return None

    for _ in range(4 * len(shifts) + 1):
        at, day = load()
        crowded = sorted(
            (-at[wd][hour], wd, hour)
            for wd in range(7) for hour in range(24)
            if at[wd][hour] and (at[wd][hour] > limit or day[wd] > limit * SHIFT_CAP)
            and (wd, hour) not in stuck
        )
        if not crowded:
            break
        _, wd, hour = crowded[0]
        swap = find(wd, hour, at, day)
        if swap is None:
            stuck.add((wd, hour))
            continue
        open_row, person, mine = swap
        theirs = state[person["id"]]
        theirs["hours"] -= mine["to"] - mine["from"]
        theirs["busy"][mine["wd"]].difference_update(range(mine["from"], mine["to"]))
        if not theirs["busy"][mine["wd"]]:
            theirs["days"].discard(mine["wd"])
        if not any(other is not mine and other["employee"] == person["id"]
                   and other["station"] == mine["station"] and other["wd"] == mine["wd"]
                   for other in shifts):
            theirs["stations"].discard((mine["station"], mine["wd"]))
        mine.update(employee=None, name=None, fromBench=False)
        _take_over(open_row, person, state)
        residue.remove(open_row)
        residue.append(mine)
    return residue




# A hire week of at least FULL_TIME[0] hours is a full-time week; from
# PART_TIME_FLOOR a part-time one (JOB_DEMANDS' parttime band, 10 to 30);
# under it no hours demand the game has is met, and the week is said to be one
# nobody would take (_hire_band()).
PART_TIME_FLOOR = 10


def _hire_band(hours: float) -> str:
    """Which contract a hire week suits: `full`, `part`, or `short` (none)."""
    if hours >= FULL_TIME[0]:
        return "full"
    return "part" if hours >= PART_TIME_FLOOR else "short"


def _absorb_scraps(rows: list, hires: list, pool: list, state: dict, here: dict) -> None:
    """Hand a hire week too short for any contract to somebody else, whole or not at all.

    A hire under PART_TIME_FLOOR hours is a week no candidate asks for. Its
    lines go to whoever the rank puts first among those with room -- somebody
    already working here, then another hire with hours (_working_here()), so
    nobody is started on a scrap -- all of them or none, so no week is left in
    pieces. The shortest such week first; deterministic.
    """
    clock = HIRE_ORDERS[0]
    for hire in sorted(hires, key=lambda h: (state[h["id"]]["hours"], h["id"])):
        mine = sorted((row for row in rows if row["employee"] == hire["id"]), key=clock)
        if not mine or state[hire["id"]]["hours"] >= PART_TIME_FLOOR:
            continue
        others = _working_here(rows, pool, hires, state, hire["id"])
        saved = {p["id"]: _copy_state(state[p["id"]]) for p in pool + hires}
        rostered = set(here["rostered"])
        moved = []
        for row in mine:
            _week_off(row, hire, state, rows)
            taker = _best_for(row, [p for p in others if _may_take(p, row)], state, here)
            if taker is None:
                break
            here["rostered"].add(taker["id"])
            _take_over(row, taker, state)
            moved.append(row)
        if len(moved) < len(mine):
            for row in mine:
                row.update(employee=hire["id"], name=None, fromBench=True)
            state.update(saved)
            here["rostered"] = rostered


def _working_here(rows: list, pool: list, hires: list, state: dict, *leave) -> list:
    """The people and hires with lines in this week, but for the ids in `leave`, pool order."""
    working = {row["employee"] for row in rows if row["employee"] is not None}
    return [p for p in pool + hires if p["id"] in working and p["id"] not in leave]


def _lift_short_hires(rows: list, hires: list, pool: list, state: dict, here: dict,
                      before: dict, entry: dict) -> None:
    """Lift a hire week under full time's 30 hours to 30, or leave it as it is.

    Candidates ask for full time (Peter, 29 September 2026: "if there's 16 h
    left over, that means one needs to reduce the hours of another full-time
    worker to make room for another full-time worker at >30 h"), so a hire
    week of 16 hours is a week nobody takes. Three ways, the first that works:

    1. Hours off the full weeks here (_lift_hire()): the people and the other
       hires of the role with the most hours first, whole lines or a piece of
       MIN_SPLIT or more, each keeping 30 hours and their own floor and day
       count -- only somebody on a full week gives.
    2. Where that is too little -- a supermarket's three servers at 32, 40
       and 31 hours and a 16-hour hire are 119 hours, one short of four full
       weeks -- the site has one person too many: one of that role gives up
       all of their week and is spare (no hours is fine, rule 4), a bench
       member before the site's own, then the fewest hours first. Their lines
       go to the hire first and then to whoever the rank puts first among
       those already working here (_working_here()), never to somebody not
       yet on the week; step 1 again after. A taker only gains, within their
       ceiling and day count, so no demand of theirs breaks.
    3. Where nobody can be spared either, step 1 with each giver keeping only
       their own band's floor (none without one), so every demand of theirs
       still holds.

    All or nothing a hire at a time; the shortest hire week first;
    deterministic.
    """
    floor = FULL_TIME[0]
    by_id = {person["id"]: person for person in pool}
    everyone = pool + hires

    def snapshot():
        return ([(row, dict(row)) for row in rows], len(rows),
                {p["id"]: _copy_state(state[p["id"]]) for p in everyone},
                set(here["rostered"]))

    def restore(saved):
        pairs, length, weeks, rostered = saved
        del rows[length:]
        for row, copy in pairs:
            row.clear()
            row.update(copy)
        state.update(weeks)
        here["rostered"] = rostered

    def givers(hire):
        # The people here and the other hires: a hire that works gives too.
        return {p["id"]: p for p in everyone if p["id"] != hire["id"]}

    for hire in sorted(hires, key=lambda h: (state[h["id"]]["hours"], h["id"])):
        hours = state[hire["id"]]["hours"]
        if not 0 < hours < floor:
            continue
        saved = snapshot()
        if _lift_hire(hire, rows, givers(hire), state, before, floor, full=True):
            continue
        restore(saved)
        if _stand_one_down(hire, rows, pool, hires, by_id, state, here, before, floor,
                           snapshot, restore, givers(hire)):
            continue
        saved = snapshot()
        if not _lift_hire(hire, rows, givers(hire), state, before, floor, full=False):
            restore(saved)
    # And a week the hires' settling cut to a part week -- it lifts a hire to
    # 30 out of hours above other people's floors, so a part-timer at 28 and
    # a 16-hour hire come out 14 and 30 -- is one person too many where the
    # hires and the people already working can take all of it. Only those
    # this pass cut (`entry` is everybody's hours when it began): a part
    # week the placement gave is not the hires' doing.
    cut = {pid for pid in by_id if state[pid]["hours"] < entry.get(pid, 0)}
    for hire in sorted(hires, key=lambda h: (state[h["id"]]["hours"], h["id"])):
        if state[hire["id"]]["hours"] >= floor and cut:
            _stand_one_down(hire, rows, pool, hires, by_id, state, here, before, floor,
                            snapshot, restore, givers(hire), below=floor, among=cut)


def _stand_one_down(hire, rows, pool, hires, by_id, state, here, before, floor,
                    snapshot, restore, givers, below=None, among=None) -> bool:
    """_lift_short_hires()'s second way: one person of the hire's role spare, all or nothing.

    `below` and `among`, where given, limit it to people working fewer hours
    than that here, and to those ids.
    """
    own = collections.defaultdict(list)
    for row in rows:
        if row["employee"] in by_id:
            own[row["employee"]].append(row)
    spares = sorted(
        (pid for pid, mine in own.items()
         if any(row["skill"] == hire["skill"] for row in mine)
         # Every hour of theirs here is one of these lines: a week kept as it
         # stands (rule 4) is not theirs to give.
         and state[pid]["hours"] - before.get(pid, (0.0, 0))[0]
         == sum(row["to"] - row["from"] for row in mine)
         and (below is None or state[pid]["hours"] - before.get(pid, (0.0, 0))[0] < below)
         and (among is None or pid in among)),
        # The bench first (no address of their own here), as the placer ranks them.
        key=lambda pid: (0 if not by_id[pid]["addr"] else 1, state[pid]["hours"], str(pid)))
    for pid in spares:
        saved = snapshot()
        person, moved = by_id[pid], True
        others = _working_here(rows, pool, hires, state, pid, hire["id"])
        for row in sorted(own[pid], key=HIRE_ORDERS[0]):
            _week_off(row, person, state, rows)
            if _may_take(hire, row) and _has_room(hire, state[hire["id"]], row):
                taker = hire
            else:
                taker = _best_for(row, [p for p in others if _may_take(p, row)], state, here)
            if taker is None:
                moved = False
                break
            _take_over(row, taker, state)
        if moved and (state[hire["id"]]["hours"] >= floor
                      or _lift_hire(hire, rows, {k: v for k, v in givers.items() if k != pid},
                                    state, before, floor, full=True)):
            here["rostered"].discard(pid)
            return True
        restore(saved)
    return False


def _lift_hire(hire: dict, rows: list, givers: dict, state: dict, before: dict,
               floor: int, full: bool) -> bool:
    """Give a hire hours off the people and hires here of their role until they reach `floor`.

    The givers with the most hours first; their lines by the clock, whole
    where the hire has room and the giver keeps what they must, or the end of
    one, at least MIN_SPLIT and leaving MIN_SPLIT. With `full` a giver keeps
    30 hours as well as their own floor, so only a full week gives; without
    it their band's floor alone, none without a band. Their day count holds
    either way. Whether the hire reached the floor; the caller undoes it
    where not.
    """
    mine = state[hire["id"]]
    while mine["hours"] < floor:
        need = floor - mine["hours"]
        donors = sorted({row["employee"] for row in rows
                         if row["employee"] in givers and row["skill"] == hire["skill"]},
                        key=lambda pid: (-state[pid]["hours"], str(pid)))
        moved = False
        for pid in donors:
            giver, week = givers[pid], state[pid]
            here_hours = week["hours"] - before.get(pid, (0.0, 0))[0]
            keep = giver["band"][0] if giver["band"] else 0
            if full:
                keep = max(keep, FULL_TIME[0])
            spare = here_hours - keep
            if spare < 1:
                continue
            lines = sorted((row for row in rows if row["employee"] == pid
                            and row["skill"] == hire["skill"]), key=HIRE_ORDERS[0])
            for row in lines:
                length = row["to"] - row["from"]
                whole_day = week["busy"][row["wd"]] == set(range(row["from"], row["to"]))
                keeps_days = giver["days"] is None or not whole_day
                if length <= spare and keeps_days and _may_take(hire, row) \
                        and _has_room(hire, mine, row):
                    _hand_over(row, giver, hire, state, rows)
                    moved = True
                    break
                take = int(min(max(need, MIN_SPLIT), spare, length - MIN_SPLIT))
                if take < MIN_SPLIT:
                    continue
                piece = dict(row, **{"from": row["to"] - take})
                if _may_take(hire, piece) and _has_room(hire, mine, piece):
                    _piece_over(row, giver, hire, state, rows, take)
                    moved = True
                    break
            if moved:
                break
        if not moved:
            return False
    return True


def _week_off(row: dict, person: dict, state: dict, rows: list) -> None:
    """Take one of a person's lines off their week, leaving the row nobody's."""
    mine = state[person["id"]]
    mine["hours"] -= row["to"] - row["from"]
    mine["busy"][row["wd"]].difference_update(range(row["from"], row["to"]))
    if not mine["busy"][row["wd"]]:
        mine["days"].discard(row["wd"])
    if not any(other is not row and other["employee"] == person["id"]
               and other["station"] == row["station"] and other["wd"] == row["wd"]
               for other in rows):
        mine["stations"].discard((row["station"], row["wd"]))
    row.update(employee=None, name=None, fromBench=False)


def _place_hires(shifts: list, pool: list, state: dict, here: dict, before: dict) -> tuple:
    """Hire for the lines nobody here can work: (the week, {skill: hire weeks}).

    The week as the ordinary placement left it, its open lines offered to the
    pool again first -- somebody the settling passes left room for takes one
    ahead of any hire, and a line nobody here may take whole at all is cut in
    two for two of them where every demand of theirs still holds, all or
    nothing a role at a time (_cut_role()) -- then dealt to N placeholders
    per skill
    (_placeholder()), and the week settled by the same repair passes
    (_repair_week()). The swaps may still move a line between somebody here
    and a hire, so a hire's day can be one a person here gave up; the settling
    is the hires' alone: a hire is lifted towards 30 hours out of the hours
    above other people's floors, but nobody already here is reshuffled for
    their own sake.

    N starts at the fewest the role's week could need (_hire_bound()). The
    tries are ten: the lines dealt five ways -- the weekend's lines first,
    which comes first so the other hires keep their weekends free, then
    HIRE_PACKINGS: by the clock or the longest line of each day first, first
    fit or balanced -- and the five again after the open lines are spread off
    the days they crowd by swapping days with the staff (_spread_open(); left
    out with nobody to swap with). A deal alone is cheap, so the least N some
    deal covers is searched first: from the open hours over 50 (never under
    the bound), up in doubling steps and back by halves. Below that, down to
    the bound, all ten tries are asked in four ways, in this order: whole
    lines dealt, whole lines with the swaps (_fill_by_exchange()) after them,
    a line cut between two hires straight after the deal (_split_open()), and
    a line cut after the swaps, a skill at a time and one fewer at a time,
    while one still covers every line. So a line is only cut where no try
    covers with whole lines at that count. The week kept is the first try,
    in that order, that covers at the N found, settled in full in the order
    that covered it. The fewest people first, as for everybody;
    deterministic throughout, each try starting from the week as it was, so
    an answer asked twice is looked up, not worked out again.

    A hire week under 10 hours is then handed to others (_absorb_scraps()),
    and one under 30 lifted to full time where the site allows it
    (_lift_short_hires()).

    A hire week is `{"hours", "busy", "slots"}`, the slots being the week's
    own rows, which then have nobody on them again (`p: null` on the page).
    """
    entry = {person["id"]: state[person["id"]]["hours"] for person in pool}
    holes = collections.defaultdict(list)
    for row in shifts:
        if row["employee"] is None:
            holes[row["skill"]].append(row)
    limit = {skill: len(rows) for skill, rows in holes.items()}
    count = {
        skill: min(_hire_bound([row for row in shifts if row["skill"] == skill],
                               [p for p in pool if _usable(p, skill, rows[0]["kind"])]),
                   limit[skill])
        for skill, rows in holes.items()
    }
    clock = HIRE_ORDERS[0]
    # The pool's own turn at the open lines, the same for every try: somebody
    # the settling passes left room for takes a line ahead of any hire.
    first = [dict(row) for row in shifts]
    allowed = {}
    open_rows = [row for row in first if row["employee"] is None]
    for row in open_rows:
        shape = _slot_shape(row)
        if shape not in allowed:
            allowed[shape] = [person for person in pool if _may_take(person, row)]
    for row in sorted(open_rows, key=clock):
        _fill_hole(row, allowed[_slot_shape(row)], state, here)
    # And a line nobody here may take whole at all -- the role, free
    # weekends, the hours they will not work -- cut in two for two of them: a
    # locker open 08-20 and two guards, one with no mornings and one with no
    # evenings, is 08-14 and 14-20 for them, not two guards to hire. A line
    # only too long for the room people have left stays whole, for the hires:
    # cutting those as well spent the room the swaps needed. A role at a time
    # (_cut_role()), all or nothing for that role.
    by_id = {person["id"]: person for person in pool}
    cut_rows = collections.defaultdict(list)
    for index, row in enumerate(first):
        if row["employee"] is None and not allowed[_slot_shape(row)]:
            cut_rows[row["skill"]].append(index)
    for skill in _in_order(cut_rows):
        _cut_role(sorted(cut_rows[skill], key=lambda i: clock(first[i])), first, pool, by_id,
                  state, here, before)
    saved = {person["id"]: _copy_state(state[person["id"]]) for person in pool}
    saved_rostered = set(here["rostered"])

    spreads_done = {}
    hire_may = {}
    # What a deal, or a deal and the swaps, left open, by the count and the
    # try: the search asks the same again, and each attempt starts from the
    # same week, so the answer is the same.
    known = {}
    swapped = {}
    swap_may = {}

    def counted():
        return tuple(sorted(count.items(), key=lambda item: str(item[0])))

    def attempt(packing, spread, split=False, settle=True, how=None):
        if settle is not True:
            key = (counted(), packing, spread, split)
            if (key, settle) in known:
                return [], None, known[key, settle][0]
            if settle == "swaps" and (key, False) in known and not known[key, False][0]:
                return [], None, set()
            if settle is False and not split:
                read = dealt_again(packing, spread)
                if read is not None:
                    known[key, settle] = read
                    return [], None, read[0]
            # Two tries that dealt the same lines to the same hires -- first
            # fit and balanced with one hire, or the weekend first with no
            # weekend -- start the swaps from the same week, so they end the
            # same: asked once.
            memo = dealt.get((counted(), same_packing(packing), spread)) if settle == "swaps" else None
            sig = None if memo is None else (counted(), spread, split, tuple(memo))
            if sig in same_deal:
                left, near, kept = same_deal[sig]
                known[key, settle] = (left, near)
                if kept is not None:
                    swapped[key] = kept
                return [], None, left
            hires, rows, left = attempt_now(packing, spread, split, settle)
            near = bool(left) and _may_split(rows, hires, state)
            known[key, settle] = (left, near)
            if near and settle == "swaps" and not split:
                # The week the swaps left, for the same try with the lines
                # cut to start from rather than swap all over again.
                swapped[key] = ([dict(row) for row in rows],
                                {pid: _copy_state(state[pid])
                                 for pid in list(saved) + [hire["id"] for hire in hires]},
                                set(here["rostered"]))
            if sig is not None:
                same_deal[sig] = (left, near, swapped.get(key))
            return hires, rows, left
        return attempt_now(packing, spread, split, settle, how)

    def may_split(packing, spread, settle):
        """Whether the whole-line try left lines its hires could take in pieces."""
        entry = known.get(((counted(), packing, spread, False), settle))
        return bool(entry and entry[1])

    dealt = {}
    same_deal = {}
    sorted_at = {}
    shares = {}

    def same_packing(packing):
        """Balanced is first fit where no role has two hires to balance between."""
        return (packing[0], False) if packing[1] and all(n <= 1 for n in count.values()) else packing

    def deal(open_rows, hires, key, packing, spread):
        """_deal_hires(), or the same deal again from what it gave last time.

        A deal reads only the open lines (the pool's, or the spread's at this
        count, in the same order either way) and the hires, fresh each time,
        so the lines it gave which hire are the same at a count and a try.
        And a role's hires take only the role's lines, so each role's share
        of it depends on that role's count alone: the search moves one
        role's count at a time, and the others' shares are looked up.
        """
        packing = same_packing(packing)
        memo = dealt.get((key, packing, spread))
        by_id = {hire["id"]: hire for hire in hires}
        if memo is None:
            # The open lines stand in the same order at every count: sorted once.
            by = (key if spread else None, spread, packing[0])
            if by not in sorted_at:
                sorted_at[by] = sorted(range(len(open_rows)), key=lambda i: packing[0](open_rows[i]))
            memo = []
            for skill in _in_order(count):
                if not count[skill]:
                    continue
                own = (packing[0], packing[1] and count[skill] > 1)
                part_key = (skill, count[skill], own, key if spread else None, spread)
                part = shares.get(part_key)
                if part is None:
                    mine = [i for i in sorted_at[by] if open_rows[i]["skill"] == skill]
                    _deal_hires([open_rows[i] for i in mine],
                                [hire for hire in hires if hire["skill"] == skill],
                                state, here, *own, hire_may, ordered=True)
                    shares[part_key] = [(i, open_rows[i]["employee"]) for i in mine
                                        if open_rows[i]["employee"] is not None]
                else:
                    for index, hid in part:
                        here["rostered"].add(hid)
                        _take_over(open_rows[index], by_id[hid], state)
            memo = sorted((index, row["employee"]) for index, row in enumerate(open_rows)
                          if row["employee"] is not None)
            dealt[key, packing, spread] = memo
            return
        for index, hid in memo:
            here["rostered"].add(hid)
            _take_over(open_rows[index], by_id[hid], state)

    def attempt_now(packing, spread, split, settle, how=None):
        hires = [_placeholder(skill, n) for skill in _in_order(count) for n in range(count[skill])]
        key = counted()
        if split and settle == "swaps" and (key, packing, spread, False) in swapped:
            kept_rows, kept_state, kept_rostered = swapped[key, packing, spread, False]
            rows = [dict(row) for row in kept_rows]
            for pid, entry in kept_state.items():
                state[pid] = _copy_state(entry)
            here["rostered"] = set(kept_rostered)
            _split_open(rows, hires, state, here)
            return hires, rows, {row["skill"] for row in rows if row["employee"] is None}
        for hire in hires:
            state[hire["id"]] = _fresh_state()
        here["rostered"] = set(saved_rostered)
        if settle is False and (not spread or key in spreads_done):
            # A deal alone reads and writes only the hires' weeks and the open
            # lines, so nobody else's week is set back and nothing else copied.
            source = spreads_done[key][0] if spread else first
            open_rows = [dict(row) for row in source if row["employee"] is None]
            deal(open_rows, hires, key, packing, spread)
            if split:
                _split_open(open_rows, hires, state, here)
            return hires, open_rows, {row["skill"] for row in open_rows if row["employee"] is None}
        everyone = pool + hires
        for pid, entry in saved.items():
            state[pid] = _copy_state(entry)
        rows = [dict(row) for row in first]
        open_rows = [row for row in rows if row["employee"] is None]
        if spread:
            # The spread reads the count and the week as the pool left it, not
            # the deal, so one spread serves every deal at a count.
            if key not in spreads_done:
                for skill in _in_order(count):
                    _spread_open([row for row in rows if row["employee"] is None
                                  and row["skill"] == skill], rows, pool, state, before,
                                 count[skill])
                spreads_done[key] = ([dict(row) for row in rows],
                                     {pid: _copy_state(state[pid]) for pid in saved})
                # No swap made: no line moved and nobody's week either.
                if len(rows) == len(first) and all(
                        row["employee"] == was["employee"] for row, was in zip(rows, first)):
                    moot[key] = True
            else:
                spread_rows, spread_state = spreads_done[key]
                rows = [dict(row) for row in spread_rows]
                for pid, entry in spread_state.items():
                    state[pid] = _copy_state(entry)
            open_rows = [row for row in rows if row["employee"] is None]
        deal(open_rows, hires, key, packing, spread)
        if not settle:
            if split:
                _split_open(rows, hires, state, here)
            return hires, rows, {row["skill"] for row in rows if row["employee"] is None}
        if settle == "swaps":
            # The swaps alone: all the settling does to open lines (the rest
            # moves hours between people and never opens one).
            if any(row["employee"] is None for row in rows):
                # Whether the week covers is all that is asked here, and a
                # line the swaps leave open that no cut could place either
                # decides it: too short for two pieces, or no hire of its role.
                _fill_by_exchange(rows, everyone, state, here["rostered"],
                                  final=lambda row: row["to"] - row["from"] < 2 * MIN_SPLIT
                                  or not count.get(row["skill"]), answers=swap_may)
            if split and any(row["employee"] is None for row in rows):
                _split_open(rows, hires, state, here)
            return hires, rows, {row["skill"] for row in rows if row["employee"] is None}
        # The week kept, in the order that covered it: a line cut straight
        # after the deal, or after the swaps (which the settling runs, and
        # keeps only where they break no demand); `how` is which.
        if split and how is False and any(row["employee"] is None for row in rows):
            _split_open(rows, hires, state, here)
        _repair_week(rows, everyone, state, here["rostered"],
                     {**before, **{hire["id"]: (0.0, 0) for hire in hires}},
                     only={hire["id"] for hire in hires})
        if split and any(row["employee"] is None for row in rows):
            _split_open(rows, hires, state, here)
        left = {row["skill"] for row in rows if row["employee"] is None}
        return hires, rows, left

    # The spread swaps days with the people here who may work a role: with
    # nobody of the kind, the tries with it are the tries without it again.
    spreads = (False, True) if any(
        _usable(person, rows[0]["skill"], rows[0]["kind"])
        for rows in holes.values() for person in pool) else (False,)
    tries = [(packing, spread) for spread in spreads
             for packing in (WEEKEND_FIRST,) + HIRE_PACKINGS]

    def distinct(among):
        """The tries that can differ: with no hire to deal to, how is moot;
        and where the spread would move nothing, its tries are the others
        again, each after its twin, so never the first to cover."""
        if spread_moot():
            among = [(packing, spread) for packing, spread in among if not spread]
        if any(count.values()):
            return among
        seen = set()
        return [(packing, spread) for packing, spread in among
                if spread not in seen and not seen.add(spread)]

    moot = {}

    def dealt_again(packing, spread):
        """A deal given before, read without dealing it: (lines' roles left
        open, _may_split() of it), or None where it has not been dealt."""
        at = counted()
        memo = dealt.get((at, same_packing(packing), spread))
        source = first if not spread else (spreads_done[at][0] if at in spreads_done else None)
        if memo is None or source is None:
            return None
        open_rows = [row for row in source if row["employee"] is None]
        worked = collections.Counter()
        for index, hid in memo:
            worked[hid] += open_rows[index]["to"] - open_rows[index]["from"]
        taken = {index for index, _ in memo}
        left_rows = [row for index, row in enumerate(open_rows) if index not in taken]
        left = {row["skill"] for row in left_rows}
        room = collections.Counter()
        for skill in _in_order(count):
            for n in range(count[skill]):
                room[skill] += max(0, FULL_TIME[1] - worked[_placeholder(skill, n)["id"]])
        owed = collections.Counter()
        near = bool(left)
        for row in left_rows:
            if row["to"] - row["from"] < 2 * MIN_SPLIT or not room[row["skill"]]:
                near = False
                break
            owed[row["skill"]] += row["to"] - row["from"]
        near = near and bool(owed) and all(hours <= room[skill] for skill, hours in owed.items())
        return left, near

    def spread_moot():
        """Whether the spread leaves the week as it is at this count.

        _spread_open() only moves a line off an hour or a day that more of
        them crowd than the role's hires could take; with none such for any
        role, it returns at once. Where it ran and found no swap, the same.
        """
        key = counted()
        if key not in moot:
            moot[key] = not any(
                _open_crowded([row for row in first if row["employee"] is None
                               and row["skill"] == skill], count[skill])
                for skill in _in_order(count))
        return moot[key]

    def run_all(modes):
        """The skills some try covers, and the first (try, how) covering all.

        `modes` are (cut, settle) pairs asked in turn, every try in each:
        a line is cut (_split_open()) only once no try covers with whole
        lines, and then only in the tries whose leftover lines the hires have
        room for.
        """
        covered = set()
        for split, settle in modes:
            # Asked again each way round: a spread tried in the first may
            # have turned out to move nothing (spread_moot()).
            among = distinct(tries)
            for packing, spread in among:
                if split and not may_split(packing, spread, settle):
                    continue
                hires, _rows, left = attempt(packing, spread, split, settle)
                for hire in hires:
                    del state[hire["id"]]
                covered |= set(count) - left
                if not left:
                    return covered, (packing, spread, split, settle)
        return covered, None

    def screen():
        """A deal alone, each try, whole lines and then a line cut: nothing
        is settled, so it only finds the count to search down from."""
        return run_all(((False, False), (True, False)))

    def settle_all():
        """At one count, in the order the week should come out: whole lines
        dealt, whole lines with the swaps after, a line cut in the deal, a
        line cut after the swaps."""
        return run_all(((False, False), (False, "swaps"), (True, False), (True, "swaps")))

    # 1. The least count some deal alone covers, per skill: from a first
    #    guess, the open lines' hours over 50 (never under the bound), up in
    #    doubling steps and halved back. A deal is cheap: nothing is settled.
    start = dict(count)
    for skill, rows in holes.items():
        guess = math.ceil(sum(row["to"] - row["from"] for row in rows) / FULL_TIME[1])
        count[skill] = min(limit[skill], max(count[skill], guess))
    failed = {skill: count[skill] - 1 for skill in count}
    enough = {skill: None for skill in count}
    step = {skill: 1 for skill in count}
    while True:
        todo = [skill for skill in count
                if enough[skill] is None or enough[skill] - failed[skill] > 1]
        if not todo:
            break
        for skill in count:
            if skill not in todo:
                count[skill] = enough[skill]
            elif enough[skill] is None:
                count[skill] = min(limit[skill], failed[skill] + step[skill])
            else:
                count[skill] = (failed[skill] + enough[skill]) // 2
        covered, _ = screen()
        for skill in todo:
            if skill in covered or count[skill] >= limit[skill]:
                enough[skill] = count[skill]
            else:
                failed[skill] = count[skill]
                step[skill] = step[skill] * 2 if step[skill] else 1
    # 2. Below it, down to the bound, every try with the swaps, which can
    #    cover what a deal cannot: a skill at a time, one fewer while one of
    #    them covers every line. All ten, and the swaps however many lines
    #    the deal left: each cut once cost a shop or an office a hire more.
    count.update(enough)
    found = None
    for skill in _in_order(count):
        while count[skill] > start[skill]:
            count[skill] -= 1
            _covered, below = settle_all()
            if below is None:
                count[skill] += 1
                break
            found = below
    def keep(found):
        """The week at the count found, settled in full, as the winning try covered it.

        The settling keeps the swaps only where they break no demand, so it
        can leave a line the proof covered open. Defensive, as no sweep has
        met it: the same try with a line cut, in the other orders, is asked
        before a hire more, and the first week is kept where none covers.
        """
        packing, spread, split, how = found
        hires, rows, left = attempt(packing, spread, split, True, how)
        if not left:
            return hires, rows, left
        ids = list(saved) + [hire["id"] for hire in hires]
        first = (hires, rows, left, {pid: _copy_state(state[pid]) for pid in ids},
                 set(here["rostered"]))
        others = [("swaps" if how is False else False)] if split else [False, "swaps"]
        for other in others:
            again = attempt(packing, spread, True, True, other)
            if not again[2]:
                return again
        hires, rows, left, weeks, rostered = first
        for pid, entry in weeks.items():
            state[pid] = entry
        here["rostered"] = rostered
        return hires, rows, left

    # 3. The week at that count: the first try, in the order settle_all()
    #    asks them, settled in full (keep()); where nothing covers at that
    #    count (the tries do not cover in step with the count), the count
    #    rises for what is left.
    while True:
        if found is None:
            _covered, found = settle_all()
        if found is not None:
            hires, rows, left = keep(found)
            grow = [skill for skill in _in_order(left) if count[skill] < limit[skill]]
            if not left or not grow:
                break
            for hire in hires:
                del state[hire["id"]]
            for skill in grow:
                count[skill] += 1
            found = None
            continue
        hires, rows, left = attempt(HIRE_PACKINGS[0], False)
        grow = [skill for skill in _in_order(left) if count[skill] < limit[skill]]
        if not left or not grow:
            break
        for hire in hires:
            del state[hire["id"]]
        for skill in grow:
            count[skill] += 1
    _absorb_scraps(rows, hires, pool, state, here)
    _lift_short_hires(rows, hires, pool, state, here, before, entry)
    ids = {hire["id"]: hire for hire in hires}
    theirs = collections.defaultdict(list)
    for row in rows:
        if row["employee"] in ids:
            theirs[row["employee"]].append(row)
    weeks = collections.defaultdict(list)
    for hire in hires:
        mine = theirs.get(hire["id"])
        if mine:
            weeks[hire["skill"]].append({
                "hours": sum(row["to"] - row["from"] for row in mine),
                "busy": state[hire["id"]]["busy"],
                "slots": mine,
            })
        del state[hire["id"]]
        here["rostered"].discard(hire["id"])
    for row in rows:
        if row["employee"] in ids:
            row.update(employee=None, name=None, fromBench=False)
    return rows, dict(weeks)


# --- the rule for the people a site already has (Peter, 28-29 September 2026)
# Somebody already working here may be given no hours (they are spare, and
# the Staff page offers to move them), or a week that still meets every
# schedule demand they hold; somebody it does not meet now may be moved any
# way that leaves them no further from it. Where a plan would cut them short
# of that, their week here as it stands is kept, as much of it as is legal,
# and the rest is planned around it.
def _weeks_now(current, pool: list) -> dict:
    """Each of the site's own people's week here now: {id: {hours, days, rows}}."""
    own = {person["id"] for person in pool if person["addr"]}
    out = {}
    for row in current or ():
        pid = row.get("employee")
        if pid not in own or row["to"] <= row["from"]:
            continue
        mine = out.setdefault(pid, {"hours": 0, "days": set(), "rows": []})
        mine["hours"] += row["to"] - row["from"]
        mine["days"].add(row["wd"])
        mine["rows"].append(row)
    return out


def _worse_off(person: dict, entry: dict, before: tuple, now: dict) -> bool:
    """Whether a planned week cuts somebody short of a demand the week they have meets better.

    No hours at all is never worse off: the person is spare, and the Staff
    page offers to move them (Peter, 29 September 2026: "0 h is fine"). A
    week with hours in it has to keep the hours band's floor (its ceiling and
    the rest are never broken by the placer) and an exact day count, or leave
    them no further from it than now: a person with no hours demand may be cut
    to anything, one under their floor now may stay there, not sink further.
    """
    hours = entry["hours"] - before[0]
    if not hours:
        return False
    days = len(entry["days"]) - before[1]
    band = person["band"]
    if band and hours < band[0] and hours < now["hours"]:
        return True
    want = person["days"]
    return want is not None and abs(days - want) > abs(len(now["days"]) - want)


def _pin_weeks(ids: list, now: dict, stations: dict, open_hours: list, by_id: dict) -> list:
    """The weeks kept as they are, as shift rows, as much of each as is legal.

    Only on a station the plan staffs a role of (`stations`: {id: (skill,
    kind)}), inside the hours the plan opens, never an hour somebody kept
    before them holds, and only what `_can_work()` allows: the 12-hour shift
    and day, their band's ceiling, their day count and their windows. People in
    id order, their rows by the clock.
    """
    taken = collections.defaultdict(set)
    opened = [set(hours) for hours in open_hours]
    out = []
    for pid in sorted(ids, key=str):
        person = by_id[pid]
        week = _fresh_state()
        for row in sorted(now[pid]["rows"], key=lambda r: (r["wd"], r["from"], r["to"],
                                                         str(r["station"]))):
            if row["station"] not in stations:
                continue
            skill, kind = stations[row["station"]]
            wd = row["wd"]
            free = [hour for hour in range(row["from"], row["to"])
                    if hour in opened[wd] and hour not in taken[(row["station"], wd)]]
            for start, end in _runs(free):
                for low, high in _cut_run(start, end):
                    piece = {"wd": wd, "station": row["station"], "skill": skill,
                             "from": low, "to": high, "kind": kind}
                    if not _can_work(person, week, piece):
                        continue
                    week["hours"] += high - low
                    week["busy"][wd].update(range(low, high))
                    week["days"].add(wd)
                    taken[(row["station"], wd)].update(range(low, high))
                    out.append(dict(piece, employee=pid, name=person["name"], hours=high - low,
                                    fromBench=False))
    return out


def _without_pins(slots: list, pins: list) -> list:
    """The slots less the station-hours a kept week already holds, re-cut."""
    held = collections.defaultdict(set)
    for row in pins:
        held[(row["station"], row["wd"])].update(range(row["from"], row["to"]))
    out = []
    for slot in slots:
        hours = held.get((slot["station"], slot["wd"]))
        if not hours or hours.isdisjoint(range(slot["from"], slot["to"])):
            out.append(slot)
            continue
        for start, end in _runs(set(range(slot["from"], slot["to"])) - hours):
            for low, high in _cut_run(start, end):
                out.append(dict(slot, **{"from": low, "to": high}))
    return out


def _current_roster(save: Save, building: dict, stations: dict) -> dict:
    """The site's schedule as it stands, to show beside the plan.

    Counts the shifts the player would have to clear, how many of them are the
    two-hour fragments auto-fill produces, and lists each one so the page can
    offer a now/plan toggle.

    `stations` has to cover the cover posts as well as the serving ones: a
    security guard on a locker works an ordinary type 1 shift, so without the
    locker in the table the duty reads as serving the queue and the site's
    security count comes out at zero.
    """
    rows, fragments = [], 0
    for scheduled in save.items(building.get("scheduleDays")):
        wd = scheduled["day"] % 7
        for shift in save.items(scheduled.get("workShifts")):
            start = max(0, shift.get("startingHour") or 0)
            end = min(24, shift.get("endingHour") or 0)
            if end <= start:
                continue
            post = shift.get("itemInstanceId")
            station = stations.get(post)
            if shift.get("type") == CLEANING_SHIFT:
                kind = "clean"
            elif station and station["slug"] in COVER_STATIONS:
                kind = COVER_STATIONS[station["slug"]][0]
            else:
                kind = "serve"
            rows.append(
                {
                    "wd": wd,
                    "station": post,
                    "from": start,
                    "to": end,
                    "employee": shift.get("employeeId"),
                    "kind": kind,
                }
            )
            if end - start <= 2:
                fragments += 1
    rows.sort(
        key=lambda r: (r["wd"], r["from"], r["to"], str(r["station"]), str(r["employee"]))
    )
    return {
        "shifts": len(rows),
        "fragments": fragments,
        # And how many of those scraps are on the cover side, counted here
        # beside the rest rather than walked again on the page: this list is the
        # longest on the row, and the page reads these counts several times a
        # draw.
        "coverFragments": sum(
            1 for r in rows if r["kind"] != "serve" and r["to"] - r["from"] <= 2
        ),
        "cleaning": sum(1 for r in rows if r["kind"] == "clean"),
        "security": sum(1 for r in rows if r["kind"] == "security"),
        "list": rows,
    }


def _address_of(building: dict, strict: bool = False) -> tuple:
    """A building registration's address as the building table keys it. With
    strict, a registration without StreetName or StreetNumber raises KeyError."""
    if strict:
        return (building["StreetName"], building["StreetNumber"])
    return (building.get("StreetName"), building.get("StreetNumber"))


def _first_skill(person: dict) -> str | None:
    """One skill to name a bench member by; a set decides it, so sort it."""
    return _in_order(person["skills"])[0] if person["skills"] else None


def _site_pool(people: dict, business: dict, bench: list) -> list:
    """Everyone the plan may roster here: assigned to the site, plus the bench.

    assignedAddress binds an employee to one building, so nothing can be
    borrowed from next door; candidates are not staff and stay out, because
    hiring is a headcount line rather than a roster entry. The bench shrinks as
    the sites are planned: assigning somebody is a move to one building, so once
    a site has given a bench member hours they belong to it and no later site
    may count on them.
    """
    # Picked out first and then put in order: sorting only this site's people
    # gives them the same order as sorting everybody would.
    here = [
        people[pid]
        for pid in _in_order(
            pid for pid in people
            if people[pid]["addr"] and (people[pid]["site"] if "site" in people[pid]
                                        else site_key(people[pid]["addr"])) == business["key"]
        )
    ]
    return here + list(bench)


def _role_wage(site_pool: list, skill: str | None) -> float:
    """What an hour of this role costs, for pricing a bridged trough.

    The mean of the people who could actually work it here (`site_pool`, from
    _site_pool()); with nobody qualified yet the gap is free to bridge, which
    is the honest answer when the hours are going to be a hiring line either
    way.
    """
    wages = [
        person["wage"]
        for person in site_pool
        if not skill or skill in person["skills"]
    ]
    return sum(wages) / len(wages) if wages else 0.0


def _cover_posts(save: Save, building: dict, names: Names) -> list:
    """The site's cleaning stations and security lockers, sorted."""
    out = []
    for item in _item_instances(save, building.get("itemInstances")):
        if item.get("itemName") in COVER_STATIONS:
            out.append(
                {
                    "id": item.get("id"),
                    "slug": item["itemName"],
                    "name": names.label(item["itemName"]) if names else item["itemName"],
                }
            )
    out.sort(key=lambda post: (post["slug"], str(post["id"])))
    return out


def _by_fewest_eligible(slots: list, allowed: dict, state: dict) -> list:
    """The order slots are filled in: minimum remaining values, ties broken by the clock.

    Someone demanding "no afternoon shifts" has only the night shift open to
    them on a 24-hour site, so they have to be placed before the unconstrained
    staff take it. Placing them last is what makes a schedule unsatisfiable.
    The count is taken against the week as it stands when the pass starts --
    empty for the serving pass, part filled for the cover pass that follows --
    and eligibility is re-tested at the moment of placing. `allowed` is the
    pool by `_slot_shape()`, each list the people `_may_take()` passes.

    Slots of one shape -- two registers over the same hours -- have the same
    count against the same week, so it is taken once per shape.
    """
    eligible = {}
    for slot in slots:
        shape = _slot_shape(slot)
        if shape not in eligible:
            eligible[shape] = sum(
                1 for person in allowed[shape]
                if _has_room(person, state[person["id"]], slot)
            )
    counted = [
        (
            eligible[_slot_shape(slot)],
            slot["wd"],
            slot["from"],
            slot["to"],
            str(slot["station"]),
            slot,
        )
        for slot in slots
    ]
    counted.sort(key=lambda row: row[:5])
    return [row[-1] for row in counted]


def _best_for(slot: dict, pool: list, state: dict, here: dict):
    """The person _placement_rank() puts first among those with room, or None.

    The rank's first two keys sort everybody into three tiers -- a real person
    on this roster, a real person not on it yet, a hire -- and a tier is only
    looked into when every tier before it has nobody with room: the answer
    ranking everybody gives, for a fraction of the ranks. The placer asks this
    for every slot of every week.

    Among hires it is the first with room, in the order they were opened:
    first fit, so N hires hold whatever the old packer's first fit held with
    N, and the repair passes level their weeks afterwards (_place_hires()).
    """
    rostered = here["rostered"]
    tiers = ([], [], [])
    for person in pool:
        tiers[2 if person.get("hire") else 0 if person["id"] in rostered else 1].append(person)
    for tier in tiers[:2]:
        able = [person for person in tier if _has_room(person, state[person["id"]], slot)]
        if able:
            return min(able, key=lambda p: _placement_rank(p, state[p["id"]], slot, here))
    return next((hire for hire in tiers[2] if _has_room(hire, state[hire["id"]], slot)), None)


def _take_slot(slot: dict, pool: list, state: dict, shifts: list, here: dict) -> bool:
    """Give one slot to the best eligible person, or report that nobody is.

    `pool` is everybody `_may_take()` already passes for this slot, in pool
    order, so only their weeks are left to test.

    `here` is what the rank knows about this site and nothing else: `rostered`,
    who it has already given a shift to, and `flex`, how many of its roles each
    person could work. `rostered` is the site's own set rather than something
    read back off `state`, because a bench member offered around carries the
    hours of whichever site took them, and those are not this site's roster.
    """
    person = _best_for(slot, pool, state, here)
    if person is None:
        return False
    here["rostered"].add(person["id"])
    mine = state[person["id"]]
    mine["hours"] += slot["to"] - slot["from"]
    mine["busy"][slot["wd"]].update(range(slot["from"], slot["to"]))
    mine["days"].add(slot["wd"])
    mine["stations"].add((slot["station"], slot["wd"]))
    shifts.append(
        {
            "wd": slot["wd"],
            "station": slot["station"],
            "skill": slot["skill"],
            "from": slot["from"],
            "to": slot["to"],
            "employee": person["id"],
            "name": person["name"],
            "hours": slot["to"] - slot["from"],
            "kind": slot["kind"],
            "fromBench": not person["addr"],
        }
    )
    return True


def _take_over(shift: dict, taker: dict, state: dict) -> None:
    """Write the taker onto a shift row and into their week."""
    theirs = state[taker["id"]]
    theirs["hours"] += shift["to"] - shift["from"]
    theirs["busy"][shift["wd"]].update(range(shift["from"], shift["to"]))
    theirs["days"].add(shift["wd"])
    theirs["stations"].add((shift["station"], shift["wd"]))
    shift["employee"] = taker["id"]
    shift["name"] = taker["name"]
    shift["hours"] = shift["to"] - shift["from"]
    shift["fromBench"] = not taker["addr"]


def _hand_over(shift: dict, donor: dict, taker: dict, state: dict, shifts: list) -> None:
    """Move one whole shift from the donor's week to the taker's, state and row alike."""
    hours = shift["to"] - shift["from"]
    mine = state[donor["id"]]
    mine["hours"] -= hours
    mine["busy"][shift["wd"]].difference_update(range(shift["from"], shift["to"]))
    if not mine["busy"][shift["wd"]]:
        mine["days"].discard(shift["wd"])
    # Only when nothing of theirs is left on that station that day. A person who
    # holds both pieces of a split day keeps the station until the second goes,
    # which is the one thing this function used to get wrong.
    if not any(
        other is not shift
        and other["employee"] == donor["id"]
        and other["station"] == shift["station"]
        and other["wd"] == shift["wd"]
        for other in shifts
    ):
        mine["stations"].discard((shift["station"], shift["wd"]))
    _take_over(shift, taker, state)


def _piece_over(shift: dict, donor: dict, taker: dict, state: dict, shifts: list,
                take: int) -> dict:
    """Cut the last `take` hours off the donor's shift and give them their own line.

    The donor keeps the head of the shift, so they keep that day and that
    station; the taker gets a line of their own, which is what the player types.
    A shift is only ever cut where a demand would otherwise fail -- the plan's
    third priority is the longest shifts it can manage, and this is the second.
    """
    start = shift["to"] - take
    mine = state[donor["id"]]
    mine["hours"] -= take
    mine["busy"][shift["wd"]].difference_update(range(start, shift["to"]))
    shift["to"] = start
    shift["hours"] = shift["to"] - shift["from"]
    piece = dict(shift, **{"from": start, "to": start + take})
    _take_over(piece, taker, state)
    shifts.append(piece)
    return piece


def _keeps_floors(person: dict, before: dict, without: dict, gained: dict) -> bool:
    """Whether a swap leaves a person no worse off against their own demands.

    `_can_work()` tests ceilings only: the 50 hours, the 12-hour day, the most
    days a count allows. A swap hands one entry away and takes another, so it
    can also lower somebody's hours under their floor, or their days under an
    exact four- or five-day count, and turn a met demand into a broken one.
    `without` is their week with the given entry taken off; `gained` is the
    line they take instead. Their hours and days afterwards must reach the
    floor, or at least not fall below what they had.
    """
    hours = without["hours"] + (gained["to"] - gained["from"])
    days = len(without["days"] | {gained["wd"]})
    floor = person["band"][0] if person["band"] else 0
    if hours < min(before["hours"], floor):
        return False
    want = person["days"]
    return want is None or days >= min(len(before["days"]), want)


def _broken(pool: list, state: dict, before: dict, shifts: list) -> set:
    """The hours and day-count demands a week leaves unmet, as (id, kind) pairs.

    The same test `shortHours` and `shortDays` are built from, for comparing
    two versions of one site's week.
    """
    worked = {shift["employee"] for shift in shifts if shift["employee"] is not None}
    out = set()
    for person in pool:
        if not (person["addr"] or person["id"] in worked):
            continue
        mine, (hours0, days0) = state[person["id"]], before[person["id"]]
        if person["band"] and mine["hours"] - hours0 < person["band"][0]:
            out.add((person["id"], "hours"))
        if person["days"] is not None and len(mine["days"]) - days0 < person["days"]:
            out.add((person["id"], "days"))
    return out


def _fill_by_exchange(shifts: list, pool: list, state: dict, rostered: set,
                      final=None, answers=None) -> int:
    """Give a line nobody could take to somebody on the roster, by a swap.

    Filling one person at a time works the first names up to their ceiling on
    the first days of the week, and the last days are left to people who may
    take one entry a day: two registers around the clock come out with seven
    people and three entries still open, where seven people can work all 28.
    So each open line is offered to somebody already on this roster who is
    free that day but full for the week, if they can hand one of their own
    entries to another person on the roster who has room for it. Both moves
    are tested with `_can_work()`'s two halves, `_may_take()` for who may take
    the line at all and `_has_room()` against the weeks as they would stand, and
    the giver with `_keeps_floors()` too, so no rule bends, no met demand is
    broken, and nobody new is started. The taker only gains. Deterministic: open
    lines by the clock, people and their entries by id and the clock.

    Each line is offered once, so one no swap places stays open. `final`,
    when given, says of such a line whether that settles the question the
    caller asks, and the pass stops there. `answers` keeps `_may_take()`'s
    answer by person and slot shape across calls over the same people.

    Returns how many lines it placed.
    """
    placed_count = 0
    by_id = {person["id"]: person for person in pool}
    people = [by_id[pid] for pid in sorted(rostered, key=str) if pid in by_id]
    clock = lambda s: (s["wd"], s["from"], s["to"], str(s["station"]))  # noqa: E731
    # Who on the roster could take each entry off its giver, by the entry's shape, and
    # everybody's entries in clock order. Neither depends on the line being
    # filled, only on the weeks, and the weeks only move when a line is placed:
    # a line nobody could be swapped onto leaves both standing for the next
    # one. Both are dropped the moment a line is placed.
    takers, by_person = {}, None
    # And who on the roster `_may_take()` passes at all, by slot shape, which no
    # swap changes.
    answers = {} if answers is None else answers
    # Kept with the answers, by who is on the roster: the same people ask the
    # same of a shape on every call over one search.
    allowed = answers.setdefault(("allowed", tuple(p["id"] for p in people)), {})

    def asked(person, slot, shape) -> bool:
        key = (person["id"], shape)
        if key not in answers:
            answers[key] = _may_take(person, slot)
        return answers[key]

    def may_take(slot, shape=None) -> list:
        shape = shape or _slot_shape(slot)
        if shape not in allowed:
            allowed[shape] = [person for person in people if asked(person, slot, shape)]
        return allowed[shape]

    # A line of one shape nobody could be swapped onto fails the same way for
    # the next line of that shape -- two counters open the same hours -- until
    # a placement moves somebody's week.
    failed = set()
    for hole in sorted((s for s in shifts if s["employee"] is None), key=clock):
        placed = False
        if _slot_shape(hole) in failed:
            continue
        if by_person is None:
            by_person = collections.defaultdict(list)
            for s in shifts:
                by_person[s["employee"]].append(s)
            for entries in by_person.values():
                entries.sort(key=clock)
            # Each entry beside its shape, which the loop below asks of all.
            for pid in by_person:
                by_person[pid] = [(s, _slot_shape(s)) for s in by_person[pid]]
        # The givers: only what no handed-over entry could change is asked
        # here, the role, free weekends and blackout windows (`_may_take()`).
        span = range(hole["from"], hole["to"])
        for giver in may_take(hole):
            # Busy at the line's hours, or over twelve with it, that day: only
            # an entry of that day handed over could free them.
            week = state[giver["id"]]
            busy = week["busy"][hole["wd"]]
            day_full = (len(busy) + len(span) > SHIFT_CAP or not busy.isdisjoint(span))
            # _has_room()'s ceiling and _keeps_floors()' floor, which read the
            # hours alone, asked before the trial week is built: the entry
            # handed over has to be long enough to make room for the line,
            # and short enough to leave the floor standing.
            ceiling = (giver["band"] or FULL_TIME)[1]
            keep = min(week["hours"], giver["band"][0] if giver["band"] else 0)
            for given, shape in by_person[giver["id"]]:
                if day_full and given["wd"] != hole["wd"]:
                    continue
                after = week["hours"] - (given["to"] - given["from"]) + len(span)
                if after > ceiling or after < keep:
                    continue
                # Whoever may take an entry depends on its shape alone, so the
                # first two with room are kept a shape: one of them is not
                # the giver. Asked first, as it is most often what fails and
                # reads nothing the trial week below would change.
                if shape not in takers:
                    room = (q for q in may_take(given, shape) if _has_room(q, state[q["id"]], given))
                    takers[shape] = [q for q, _ in zip(room, range(2))]
                taker = next((q for q in takers[shape] if q["id"] != giver["id"]), None)
                if taker is None:
                    continue
                trial = _week_without(state[giver["id"]], given)
                if not _has_room(giver, trial, hole):
                    continue
                if not _keeps_floors(giver, state[giver["id"]], trial, hole):
                    continue
                _hand_over(given, giver, taker, state, shifts)
                _take_over(hole, giver, state)
                takers, by_person = {}, None
                failed = set()
                placed = True
                placed_count += 1
                break
            if placed:
                break
        if not placed:
            failed.add(_slot_shape(hole))
            if final is not None and final(hole):
                return placed_count
    return placed_count


def _top_up_short(shifts: list, pool: list, state: dict, rostered: set, only=None) -> None:
    """Settle what the one-at-a-time fill leaves owing, without adding a name.

    Two demands are settled here, in the order the player ranked them.

    **The hours.** Filling one person at a time leaves the residue on whoever was
    rostered last: 168 station-hours in twelve-hour pieces come out 48, 48, 48
    and 24, and that 24 is a full-time demand failed by six hours that nobody can
    make up at another business. The same fourteen lines with a name moved are
    48, 48, 36, 36.

    **The days.** `fourdaysweek` and `fivedaysweek` ask to be assigned *exactly*
    four or five days -- the game's own `DaysWorkingPerWeek.Fulfilled()` fails on
    `!=`, not on `>` -- and five twelve-hour days is 60 hours, over full time's
    50. So on a site whose doors are open long enough to cut twelve-hour shifts,
    a five-day week cannot be built out of them at all. Rather than fail the
    demand, one shift is cut: the person takes the tail of a day they were not
    working, as long as their band has room for it, and the donor keeps the head
    of it. That costs one more line to type, which is the third priority paying
    for the second.

    Three rules hold throughout the hours and day passes. Only somebody already on
    this roster is topped up there, because handing hours to a person the plan
    used for nothing would add a name, and a name is another person owed thirty
    hours. The hand-over below is the exception and says so: it moves a whole
    week between two people, so the headcount does not change but the names do,
    and the giver may lose a day count they were meeting to settle an hours
    demand that was not. A donor never drops
    below their own minimum and never loses a day their own demand asks for, so
    no shortfall is ever traded for another. And a week that cannot be made up at
    all is left alone: 56 station-hours will not give two people thirty each
    however the shifts move, so it is reported rather than shuffled.

    `only` limits whose week is settled to those ids: the hires, once the
    week has been settled for everybody else (_place_hires()). The others
    then only give, never take, so a week that needs a hire is not also
    reshuffled for the people it had settled already.
    """
    by_id = {person["id"]: person for person in pool}
    floor_of = {
        pid: (by_id[pid]["band"][0] if by_id[pid]["band"] else 0) for pid in by_id
    }
    roster = [pid for pid in sorted(rostered, key=str) if pid in by_id]

    def slack(donor) -> float:
        """Hours this donor could give up before failing their own demand."""
        return state[donor["id"]]["hours"] - floor_of[donor["id"]]

    def donors(taker) -> list:
        """Everybody else's shifts, the fullest week first, then the week in order.

        One order for both passes, so the same save moves the same shift on every
        run of it. Somebody with nothing to spare is left in: the hours pass
        tests their slack itself, and the day pass can give the hours back.
        """
        out = []
        for shift in shifts:
            donor = by_id.get(shift["employee"])
            if donor is None or donor["id"] == taker["id"]:
                continue
            out.append((-state[donor["id"]]["hours"], shift["wd"], shift["from"],
                        shift["to"], str(shift["station"]), shift, donor))
        out.sort(key=lambda row: row[:5])
        return [(row[-2], row[-1]) for row in out]

    # --- the hours ----------------------------------------------------------
    # One person at a time, and all or nothing. Moving what a donor happened to
    # be able to spare and seeing how far it got left people with a scrap of a
    # line *and* a failed demand -- 60 pieces under four hours across 400 shops,
    # and in 43 of them the person was still short when it was done. So a week
    # is settled on copies first, and written only if the floor is actually
    # reached; where it is not, nothing moves and the shortfall is reported as
    # it stands. That also retires the old guess at whether a week could be made
    # up at all, which was generous on purpose and wrong often enough to matter.
    def settle(taker, goal=None) -> bool:
        """Reach this person's floor out of other people's slack, or leave it.

        A hire (_placeholder()) is paid out of the hours above each donor's own
        floor too, and somebody here with no hours demand keeps a full week's
        thirty: a hire is never why a person already here drops off the week.
        """
        pid = taker["id"]
        keep = floor_of if not taker.get("hire") else {
            other: floor_of[other] if by_id[other]["band"] or by_id[other].get("hire")
            else FULL_TIME[0]
            for other in by_id
        }
        # The weeks as they would stand, copied only once the plan writes to
        # one: until then a week reads as it stands in `state`.
        weeks = {pid: _copy_state(state[pid])}
        on_roster = set(roster) | {pid}

        def week(other) -> dict:
            return weeks[other] if other in weeks else state[other]

        def own(other) -> dict:
            if other not in weeks:
                weeks[other] = _copy_state(state[other])
            return weeks[other]

        # A shadow of the week to plan against, so nothing on the page moves
        # until the whole sequence is known to work. It stays index-for-index
        # with `shifts`, and `_piece_over()` appends to both in the same order.
        # Its rows are the week's own until one changes: a changed row is a
        # new one, never the old one edited.
        rows = list(shifts)
        moves = []

        def spare_of(other) -> float:
            return week(other)["hours"] - keep[other]

        static = {}

        def allowed(row, start, stop) -> bool:
            # _can_work()'s two halves, the one no week changes asked once a
            # shape: the settling pass asks it of every line of the week.
            shape = (row["skill"], row["kind"], row["wd"], start, stop)
            ok = static.get(shape)
            if ok is False:
                return False
            slot = {"from": start, "to": stop, "wd": row["wd"], "skill": row["skill"],
                    "kind": row["kind"], "station": row["station"]}
            if ok is None:
                ok = static[shape] = _may_take(taker, slot)
            return ok and _has_room(taker, weeks[pid], slot)

        def order():
            """The same fullest-week-first order the day pass uses.

            Only the lines of somebody with an hour to spare: both passes
            below skip everybody else, the whole lines for want of the
            line's length and the pieces for want of one hour.
            """
            spare = {other: spare_of(other) >= 1 for other in on_roster if other != pid}
            return sorted(
                (index for index, row in enumerate(rows) if spare.get(row["employee"])),
                key=lambda index: (
                    -week(rows[index]["employee"])["hours"], rows[index]["wd"],
                    rows[index]["from"], rows[index]["to"], str(rows[index]["station"])),
            )

        goal = floor_of[pid] if goal is None else goal
        while weeks[pid]["hours"] < goal:
            gap = goal - weeks[pid]["hours"]
            picked = None
            # Nothing moves until a shift is picked, so one order serves
            # both the whole shifts and the pieces.
            donors_now = order()
            for index in donors_now:
                row = rows[index]
                length = row["to"] - row["from"]
                giver = by_id[row["employee"]]
                if spare_of(giver["id"]) < length:
                    continue  # the fix would only move the shortfall along
                if giver["days"] is not None and week(giver["id"])["busy"][row["wd"]] \
                        == set(range(row["from"], row["to"])):
                    continue  # their only shift that day, and days are a demand
                if allowed(row, row["from"], row["to"]):
                    picked = (index, length)
                    break
            if picked is None:
                # No whole shift a donor may give up: take the hours that are
                # still owed off the end of one. Twelve-hour pieces cannot give
                # two people thirty hours out of sixty; 30 and 30 needs a six.
                # At least MIN_SPLIT of them wherever the donor can spare it,
                # because a two-hour gap closed with a two-hour line is a scrap
                # of the kind this feature exists to clear, and an hour or two
                # over the floor costs the player nothing.
                for index in donors_now:
                    row = rows[index]
                    room = min(spare_of(row["employee"]),
                               row["to"] - row["from"] - MIN_SPLIT)
                    for want in (max(gap, MIN_SPLIT), gap):
                        take = int(min(room, want))
                        if take >= 1 and allowed(row, row["to"] - take, row["to"]):
                            picked = (index, take)
                            break
                    if picked:
                        break
            if picked is None:
                return False  # nothing here can make their week up
            index, take = picked
            row = rows[index]
            start = row["to"] - take
            mine, theirs = own(row["employee"]), weeks[pid]
            mine["hours"] -= take
            mine["busy"][row["wd"]].difference_update(range(start, row["to"]))
            theirs["hours"] += take
            theirs["busy"][row["wd"]].update(range(start, row["to"]))
            theirs["days"].add(row["wd"])
            moves.append((index, row["employee"], take, take == row["to"] - row["from"]))
            if take == row["to"] - row["from"]:
                rows[index] = dict(row, employee=pid)
            else:
                rows[index] = dict(row, to=start)
                rows.append(dict(row, **{"from": start, "employee": pid}))

        for index, giver, take, entire in moves:
            if entire:
                _hand_over(shifts[index], by_id[giver], taker, state, shifts)
            else:
                _piece_over(shifts[index], by_id[giver], taker, state, shifts, take)
        return True

    # Worst off first, and the id to break a tie: two people the same number of
    # hours short must not swap places between two runs of one save. Settling
    # one changes what is left for the next, so the list is taken again each
    # time rather than once.
    def settle_everybody() -> None:
        """Every week that can still be reached, worst off first."""
        tried = set()
        while True:
            short = sorted(
                (state[pid]["hours"] - floor_of[pid], str(pid))
                for pid in roster
                if state[pid]["hours"] < floor_of[pid] and pid not in tried
                and (only is None or pid in only)
            )
            if not short:
                break
            pid = short[0][1]
            tried.add(pid)
            # A hire that cannot reach a full week is still lifted to a
            # part-time one where it can (_hire_band()).
            if (not settle(by_id[pid]) and by_id[pid].get("hire")
                    and state[pid]["hours"] < PART_TIME_FLOOR):
                settle(by_id[pid], PART_TIME_FLOOR)

    settle_everybody()

    # --- the week that went to the wrong person -------------------------------
    # Which name gets started is decided before anybody has an hour, so among new
    # names the rank can only compare contracts and wages. Where a site holds one
    # week's work, that lets a cheaper person with no hours demand take all of it
    # while a full-timer beside them is reported 0 of 30: the same headcount, the
    # same lines, and a Critical demand failed for the sake of a wage the player
    # ranked below every demand.
    #
    # It is not a rank key, because a key would fire on the shop that has too few
    # hours to fill a band as well, where starting the full-timer would trap them
    # on a partial week and leaving them spare is the better answer. Here the week
    # is already known, so the swap can be made only where it settles something:
    # every line has to be one the taker may work, and the total has to land
    # inside their band and meet their day count.
    def would_suit(taker, rows) -> bool:
        """Could the taker work this whole week, and does it fit their contract?"""
        low, high = taker["band"]
        if not low <= sum(row["to"] - row["from"] for row in rows) <= high:
            return False
        week = _fresh_state()
        for row in sorted(rows, key=lambda r: (r["wd"], r["from"])):
            if not _can_work(taker, week, {
                "from": row["from"], "to": row["to"], "wd": row["wd"],
                "skill": row["skill"], "kind": row["kind"],
                "station": row["station"],
            }):
                return False
            week["hours"] += row["to"] - row["from"]
            week["busy"][row["wd"]].update(range(row["from"], row["to"]))
            week["days"].add(row["wd"])
        # A day count is exact, so a week that would fail it is one failed demand
        # traded for another.
        return taker["days"] is None or len(week["days"]) == taker["days"]

    for taker in [
        person for person in pool
        if person["band"] and person["addr"] and not state[person["id"]]["hours"]
        and only is None
    ]:
        for giver_id in [pid for pid in roster if not by_id[pid]["band"]]:
            mine = [row for row in shifts if row["employee"] == giver_id]
            if not mine or not would_suit(taker, mine):
                continue
            for row in mine:
                _hand_over(row, by_id[giver_id], taker, state, shifts)
            roster.append(taker["id"])
            roster.remove(giver_id)
            break

    # --- the days -----------------------------------------------------------
    # A day is *shared*, never moved: the taker takes the tail of somebody's
    # shift on a day they were not working, and the donor keeps the head, so the
    # donor's own day count is untouched. Moving a whole shift would hand one
    # person's day to another and settle nothing.
    #
    # Where the taker has no room for it -- four twelve-hour days is 48 hours and
    # full time stops at 50 -- the two of them swap instead: the taker hands a
    # piece of a day they are keeping to the same person they are taking the new
    # day from. Their hours barely move, only the shape of the week does, and a
    # donor sitting exactly on their own floor can still take part, because what
    # they give comes straight back. That matters more than it sounds: the hours
    # pass above leaves people *on* their floor, so a rule that asked donors for
    # spare hours found none in the ordinary case.
    #
    # Both legs are tried against copies of the two weeks and written only if the
    # whole exchange is legal. Handing the hours over first and discovering
    # afterwards that the day would not fit left the week a line shorter and the
    # demand no nearer met.
    def ceiling_of(person) -> float:
        return (person["band"] or FULL_TIME)[1]

    def keeps_promises(person, week) -> bool:
        """Is this still a week the plan could put that person's name to?"""
        return (
            week["hours"] >= floor_of[person["id"]]
            and week["hours"] <= ceiling_of(person)
            and (person["days"] is None or len(week["days"]) <= person["days"])
        )

    def leg(weeks, giver, taker, shift, take) -> bool:
        """One half of an exchange, against copies of the two weeks.

        The giver always keeps the head of the shift, so they keep that day; only
        the taker's day count moves.
        """
        start = shift["to"] - take
        # Every rule but the weekly ceiling, which is `keeps_promises()`'s to
        # judge once both legs are in. An exchange gives hours back as well as
        # takes them, so a donor sitting on their ceiling would be refused the
        # compensation that is the whole point of one -- 50 and 48 is a legal
        # pair of weeks that this used to read as 50 + 4.
        if not _can_work(taker, dict(weeks[taker["id"]], hours=0.0), {
            "from": start, "to": shift["to"], "wd": shift["wd"],
            "skill": shift["skill"], "kind": shift["kind"],
            "station": shift["station"],
        }):
            return False
        mine, theirs = weeks[giver["id"]], weeks[taker["id"]]
        mine["hours"] -= take
        mine["busy"][shift["wd"]].difference_update(range(start, shift["to"]))
        theirs["hours"] += take
        theirs["busy"][shift["wd"]].update(range(start, shift["to"]))
        theirs["days"].add(shift["wd"])
        return True

    def can_land(taker, shift, take) -> bool:
        """`leg()`'s own test of the taker, against their week as it stands."""
        start = shift["to"] - take
        return _can_work(taker, dict(state[taker["id"]], hours=0.0), {
            "from": start, "to": shift["to"], "wd": shift["wd"],
            "skill": shift["skill"], "kind": shift["kind"], "station": shift["station"],
        })

    def share(taker, want) -> bool:
        """Buy the taker the day `want`, at nobody else's expense."""
        for shift, donor in donors(taker):
            if shift["wd"] != want:
                continue
            length = shift["to"] - shift["from"]
            # Half the shift where it will go round, so neither end is a scrap
            # and the donor is not left with the remains of a day.
            take = int(min(length - MIN_SPLIT, max(MIN_SPLIT, length // 2)))
            if take < MIN_SPLIT:
                continue
            # What the taker has to hand back: enough to make room in their own
            # week for the day, *and* enough that the donor is not left under
            # their floor for having parted with it. The second is the usual
            # one -- the hours pass leaves people exactly on their floor.
            owed = max(
                take - (ceiling_of(taker) - state[taker["id"]]["hours"]),
                take - slack(donor),
            )
            offers = [None]
            if owed > 0:
                # What the taker hands back for it, longest day first so the
                # piece comes off a week that can spare its shape. The donor is
                # asked before anybody else, because giving the hours straight
                # back is the one trade that needs neither of them to have room
                # going in -- but a donor who cannot work those hours at all
                # leaves the day unreachable, and on a shop with two registers,
                # twelve-hour doors and a few five-day contracts that is a
                # demand failed for want of a third pair of hands. Two rules
                # keep the third person out of trouble: they have to be working
                # here already, so the page never gains a name holding a scrap,
                # and they may not be somebody still owed days themselves, whose
                # own week the hours would quietly spend.
                offers = [
                    (mine, give, by_id[pid])
                    for mine in sorted(
                        (s for s in shifts
                         if s["employee"] == taker["id"] and s["wd"] != want),
                        key=lambda s: (-(s["to"] - s["from"]), s["wd"], s["from"],
                                       str(s["station"])),
                    )
                    for give in [int(min(max(owed, MIN_SPLIT),
                                         (mine["to"] - mine["from"]) - MIN_SPLIT))]
                    if give >= MIN_SPLIT
                    for pid in [donor["id"]] + [
                        other for other in roster
                        if other not in (donor["id"], taker["id"])
                        and state[other]["hours"] > 0
                        and not (by_id[other]["days"] is not None
                                 and len(state[other]["days"]) < by_id[other]["days"])
                    ]
                ]
            # Each leg's own test reads nobody's week but the day it lands on,
            # which the other leg never touches, so it is asked of the weeks
            # as they stand first, and the weeks are only copied for an
            # exchange that passes both.
            if not can_land(taker, shift, take):
                continue
            for offer in offers:
                if offer and not can_land(offer[2], offer[0], offer[1]):
                    continue
                weeks = {pid: _copy_state(state[pid])
                         for pid in {taker["id"], donor["id"]}
                         | ({offer[2]["id"]} if offer else set())}
                if offer and not leg(weeks, taker, offer[2], offer[0], offer[1]):
                    continue
                if not leg(weeks, donor, taker, shift, take):
                    continue
                if not all(keeps_promises(by_id[pid], week)
                           for pid, week in weeks.items()):
                    continue
                if offer:
                    _piece_over(offer[0], taker, offer[2], state, shifts, offer[1])
                _piece_over(shift, donor, taker, state, shifts, take)
                return True
        return False

    moved = True
    while moved:
        moved = False
        # Worst off first, and the id to break a tie, the same as the hours.
        for _gap, pid in sorted(
            (len(state[pid]["days"]) - by_id[pid]["days"], str(pid))
            for pid in roster
            if by_id[pid]["days"] is not None
            and len(state[pid]["days"]) < by_id[pid]["days"]
            and (only is None or pid in only)
        ):
            for want in range(7):
                if want in state[pid]["days"]:
                    continue  # a day they already work buys them nothing
                if share(by_id[pid], want):
                    moved = True
                    break
            if moved:
                break

    # Again, now the days have moved hours about. `settle()` writes a week off
    # for good once it cannot reach a floor, so somebody the day pass has since
    # given hours to is never looked at twice without this.
    #
    # It was removed once for want of a shop that needed it, and three thousand
    # random shops across two generators could not produce one. The shape is
    # narrow: it takes somebody holding an hours band *and* a day count *and* a
    # blackout window at the same time, which the generators offered only as
    # alternatives. On the shop that does it -- a ticket booth, doors 05-12 and
    # 13-24, and a five-day full-timer who works no evenings -- they come out on
    # 14 hours over 2 days with both demands failed, against 30 over 5 with this
    # pass in. `ExchangeTest` keeps that shop now.
    settle_everybody()


def _repair_week(shifts: list, pool: list, state: dict, rostered: set, before: dict,
                 only=None) -> None:
    """Settle what the one-at-a-time fill left: the swaps, then _top_up_short().

    The lines the one-at-a-time fill could not place, offered round the
    roster by a swap, so the hiring count is the least the week needs. The
    week without the swaps is kept beside it and both are settled by
    _top_up_short(); the swaps are kept only if they break no demand the
    week without them meets. A swap that is fair to the giver can still take
    away the room the settling pass needed for somebody else. `only`: see
    _top_up_short().
    """
    # A swap only ever fills an open line, so a week with none has nothing to
    # keep a copy of.
    if not any(shift["employee"] is None for shift in shifts):
        _top_up_short(shifts, pool, state, rostered, only)
        return
    plain_shifts = [dict(shift) for shift in shifts]
    # A swap only ever moves hours between people on this roster, so their
    # weeks are the ones kept as they were; everybody else's week is the same
    # after the swaps as before, and is copied only when a swap was made.
    unswapped = {pid: _copy_state(state[pid]) for pid in rostered}
    swapped = _fill_by_exchange(shifts, pool, state, rostered)
    plain_state = None
    if swapped:
        plain_state = {
            pid: unswapped[pid] if pid in unswapped else _copy_state(state[pid])
            for pid in (person["id"] for person in pool)
        }
    # The residue the one-at-a-time fill leaves on whoever was admitted last:
    # the same lines, a name or two different, and one fewer failed demand.
    _top_up_short(shifts, pool, state, rostered, only)
    if swapped:
        _top_up_short(plain_shifts, pool, plain_state, rostered, only)
        if not _broken(pool, state, before, shifts) <= _broken(
            pool, plain_state, before, plain_shifts
        ):
            shifts[:] = plain_shifts
            state.update(plain_state)


def _fill_week(slots: list, cover_slots: list, pool: list, state: dict, here: dict,
               pins=(), allowed=None) -> list:
    """One week placed on the pool a slot at a time; the lines nobody may work stay open.

    _repair_week() settles it. `pins` are weeks kept as they stand
    (_pin_weeks()): written into their people's weeks first, their people
    counted on the roster, and their hours taken out of the slots, and never
    handed on by a repair pass, because they are not in the list it works on.
    `allowed` keeps who may take each shape of slot between two fills of one
    pool, since no week changes it.
    """
    by_id = {person["id"]: person for person in pool}
    for row in pins:
        here["rostered"].add(row["employee"])
        _take_over(dict(row), by_id[row["employee"]], state)
    if pins:
        slots, cover_slots = _without_pins(slots, pins), _without_pins(cover_slots, pins)
    # Who may take each shape of slot at all, in pool order: the half of
    # `_can_work()` no week changes (`_may_take()`), asked once per shape
    # rather than for every slot, and never of the whole bench again.
    allowed = {} if allowed is None else allowed
    for slot in slots + cover_slots:
        shape = _slot_shape(slot)
        if shape not in allowed:
            allowed[shape] = [person for person in pool if _may_take(person, slot)]
    shifts = []
    for group in (slots, cover_slots):
        for slot in _by_fewest_eligible(group, allowed, state):
            if not _take_slot(slot, allowed[_slot_shape(slot)], state, shifts, here):
                # A slot nobody here may legally work is still a line of the
                # week: it is the one the player has to hire for, and leaving
                # it out of `shifts` left the page with a headcount saying
                # "hire 2" and no way to see which two hours were meant. It
                # goes in with no employee, which is what `p: null` means on
                # the page.
                shifts.append(_open_slot(slot))
    return shifts


def _open_slot(slot: dict) -> dict:
    """One slot of the week with nobody to give it to, in a shift's shape.

    The same row `_take_slot()` writes, without a person: `_shift_row()` turns
    the missing employee into the payload's ``p: null`` and the page draws a
    dashed hiring line where the shift would be. It is not work anybody does,
    so it earns nobody hours, days or a station, and it is priced at nothing.
    """
    return {
        "wd": slot["wd"],
        "station": slot["station"],
        "skill": slot["skill"],
        "from": slot["from"],
        "to": slot["to"],
        "employee": None,
        "name": None,
        "hours": slot["to"] - slot["from"],
        "kind": slot["kind"],
        "fromBench": False,
    }


def _demand_driven(shifts: list, pool: list) -> list:
    """Who has a schedule demand, and where the plan put them because of it.

    The row that answers the original ask directly. Only the demands that decide
    *where* a person may be put count here: the blackout windows, free weekends
    and a day count. An hours band is deliberately out — it shapes how much
    somebody works, not which shift they are on, and a site where 225 of 227
    staff demand full time would otherwise list almost everybody.
    """
    kinds = {"noshift", "daysoff", "days"}
    wanted = {}
    for person in pool:
        driving = [
            slug for slug in person["demands"] if JOB_DEMANDS[slug][0] in kinds
        ]
        if driving:
            wanted[person["id"]] = (person, driving[0])
    out = []
    for shift in shifts:
        if shift["employee"] not in wanted:
            continue
        person, demand = wanted[shift["employee"]]
        out.append(
            {
                "employee": person["id"],
                "name": person["name"],
                "demand": demand,
                "wd": shift["wd"],
                "from": shift["from"],
                "to": shift["to"],
            }
        )
    return out


def _shift_row(shift: dict, table: dict) -> dict:
    """One line of a roster, plan or current, as the payload carries it.

    d weekday, s the station's index, f and t the hours it runs from and to, p
    the person's index or null, k the kind of duty. `k` is left off an ordinary
    serving shift, which is what a row without one means: two thirds of a
    fragmented site's rows are serving shifts, and the repeated word costs more
    than everything else on the row put together.
    """
    row = {
        "d": shift["wd"],
        "s": table["station"][shift["station"]],
        "f": shift["from"],
        "t": shift["to"],
        "p": table["person"].get(shift["employee"]),
    }
    if shift["kind"] != "serve":
        row["k"] = shift["kind"]
    return row


def _schedule_demands(person: dict | None) -> list:
    """The demands of a person the week they work decides (DEMAND_SCOPE `schedule`)."""
    return [slug for slug in (person or {}).get("demands") or ()
            if DEMAND_SCOPE.get(JOB_DEMANDS.get(slug, (None,))[0]) == "schedule"]


def _index_table(posts: list, station_rows, person_rows, people: dict) -> dict:
    """The two lookup tables a site's rows point into, and the maps to build them.

    A save's employee and item ids are 24 characters of base64, and a busy site
    has nearly a thousand shift rows between its plan and its current schedule.
    Repeating the ids there costs more than the rest of the row put together, so
    the rows carry an index and this is what they index into. Every station the
    plan or the current roster posts anyone to is listed, including one the
    board knows nothing else about, and so is everyone either names.
    """
    stations, station_index = [], {}

    def station(post_id, name=None, skill=None, rate=None):
        if post_id not in station_index:
            station_index[post_id] = len(stations)
            stations.append(
                {"id": post_id, "name": name, "skill": skill, "rate": rate}
            )
        return station_index[post_id]

    for post in posts:
        station(
            post["id"],
            post.get("name"),
            post.get("skill") or (COVER_STATIONS.get(post.get("slug")) or (None, None))[1],
            post.get("rate"),
        )
    for rows in station_rows:
        for row in rows:
            station(row["station"])

    # A row whose employee is unknown keeps a null rather than an index: that is
    # what a hire bar is, a shift the plan wants with nobody to put on it.
    seen = [
        row["employee"]
        for rows in person_rows
        for row in rows
        if row.get("employee") is not None
    ]
    order = sorted(
        dict.fromkeys(seen),
        key=lambda pid: ((people.get(pid) or {}).get("name") or "", str(pid)),
    )
    person_index = {pid: index for index, pid in enumerate(order)}
    return {
        "stations": stations,
        "station": station_index,
        # A person's schedule demands, where they hold any: the board checks
        # every week it is about to write against them (gwWeekCheck()).
        "people": [
            {"id": pid, "name": (people.get(pid) or {}).get("name"),
             **({"demands": held} if (held := _schedule_demands(people.get(pid))) else {})}
            for pid in order
        ],
        "person": person_index,
    }


def _current_cost(current: dict, wage_of: dict) -> float:
    """What the schedule as it stands pays out in a week, for the staff we can price."""
    return sum(
        (row["to"] - row["from"]) * wage_of.get(row["employee"], 0.0)
        for row in current["list"]
    )


def _plan_world(save: Save, staff: list) -> dict:
    """The one pool of people every plan of a save draws on, and their weeks.

    `people` is _plan_people() once for the whole save; `state` one week per
    person, which every placement writes into its own copy of and commits back;
    `bench` the unassigned people nobody is in training among, which each plan
    that gives one of them hours takes them off. Shops, then offices, then
    factories plan over the same three (_staff_plans()), so an unassigned
    person is promised to one site at most, whichever kind it is.
    """
    people = _plan_people(save, staff)
    return {
        "people": people,
        "state": {pid: _fresh_state() for pid in people},
        "bench": [people[pid] for pid in _in_order(people)
                  if not people[pid]["addr"] and not people[pid]["training"]],
    }


@contextlib.contextmanager
def _collector_paused():
    """Python's cycle collector off while the staffing is planned, and back as it was.

    The planner copies thousands of small weeks and throws them away, and every
    so often the collector walks everything alive -- on a big save, the whole
    save as well -- to find cycles that are not there: a sixth of the step's
    time on Jacob Maynard's hub-and-spoke save. Reference counting still frees
    every week the moment it is dropped; what cycles there are (the search's
    own closures) wait for the next collection after it. Nothing planned
    changes.
    """
    was = gc.isenabled()
    gc.disable()
    try:
        yield
    finally:
        if was:
            gc.enable()


def _staff_plans(save: Save, names: Names, businesses: list, grids: list, factories: dict,
                 staff: list, base_promotion: float) -> tuple:
    """Every site's week, over one pool: (staffing, officeStaffing, factoryStaffing).

    Shops first, in their order, then offices, then factories, each drawing on
    the unassigned people the ones before it left (_plan_world()).
    """
    world = _plan_world(save, staff)
    staffing = _staffing(save, names, businesses, grids, staff, base_promotion, world)
    offices = _office_staffing(save, names, businesses, grids, staff, world)
    factory = _factory_staffing(save, names, businesses, factories, staff, world=world)
    return staffing, offices, factory


def _staffing(
    save: Save,
    names: Names,
    businesses: list,
    grids: list,
    staff: list,
    base_promotion: float,
    world: dict | None = None,
) -> list:
    """A roster the player can type in, one row per retail site.

    Retail only: an office's need is exact and deferred (scope section 9); a
    factory's roster is _factory_staffing(), through the same placer. The plan replaces a
    site's whole schedule rather than patching it, which is why cleaning and
    security shifts are reproduced here too — clearing wipes them, and the
    player would otherwise lose cleanliness and security without being told.

    What it optimises for, in order: cover, then the fewest lines to type, then
    nobody's demand broken, then wages. Where those pull against each other the
    slack budget decides, and its price is carried either way.

    Two passes. Every site's demand plan first, in site order, each taking
    whom it uses off the bench; then every site's full-cover plan, in the same
    order, against the bench the demand plans left, each taking whom it uses
    off a shared copy of it. A site's full-cover plan may also use whoever its
    own demand plan took, since the player follows one plan or the other there.
    So no unassigned person is promised to two shops. `world` is the save's
    one pool (_plan_world()), which the offices and factories plan over next;
    the bench this leaves in it is everybody no shop plan counts on.
    """
    by_key = {b["key"]: b for b in businesses}
    buildings = {
        site_key(_address_of(b, strict=True)): b
        for b in save.items(save.root.get("BuildingRegistrations"))
        if b.get("RentedByPlayer")
    }
    world = world or _plan_world(save, staff)
    people = world["people"]
    bench = list(world["bench"])
    everyone_on_bench = list(bench)
    curves = load_demand_curves()
    table = load_buildings()
    caps = _door_caps(names)

    # One week per person for the whole save, not one per site. A person
    # assigned to a site appears in that site's pool alone, but a bench member
    # is in every pool until somebody takes them, and a fresh state map per site
    # would put the same employee on the same Monday morning at three shops at
    # once. The sites are planned in their payload order so the bench goes to
    # the same site on every run.
    state = world["state"]
    planned = sorted(
        (
            (by_key[grid["key"]], buildings[grid["key"]], grid)
            for grid in grids
            if grid["key"] in by_key
            and by_key[grid["key"]]["status"] == "retail"
            and grid["key"] in buildings
        ),
        key=lambda row: (row[0]["name"] or "", row[0]["key"]),
    )

    def failed(business):
        # One odd site is one missing plan, not a blank board, and not a
        # silent hole either: the row says the site could not be planned so
        # the page can say so. Nothing of it is committed, and it fails in
        # the same place on every run, so the payload stays the same twice
        # over.
        return {
            "key": business["key"],
            "name": business["name"],
            "typeSlug": business["typeSlug"],
            "failed": True,
        }

    sites = []
    for business, building, grid in planned:
        # A site is planned against its own copy of the week, and the copy is
        # only written back once the whole row is built. _plan_site() places
        # people well before it reads the current schedule or builds the lookup
        # tables, so a site that falls over halfway through would otherwise
        # leave phantom hours on people it never actually rosters -- and the
        # next site would hire around staff who are, in fact, free. Only the
        # people this site could roster are copied, which is a handful of small
        # sets per site: this runs in Pyodide.
        scratch = {
            person["id"]: _copy_state(state[person["id"]])
            for person in _site_pool(people, business, bench)
        }
        try:
            site = _plan_site(save, names, business, building, grid, people,
                              list(bench), scratch, curves, table, base_promotion, caps)
        except Exception:
            sites.append((business, None))
            continue
        sites.append((business, site))
        if _opens_first(site, business):
            # The site is on its open-hours plan: its demand plan may draw on
            # the bench but reserves nobody, so only its own people's weeks
            # are written back.
            state.update({pid: entry for pid, entry in scratch.items() if people[pid]["addr"]})
            continue
        state.update(scratch)
        # Whoever this site drew off the bench now works here, so they leave it.
        taken = {p["id"] for p in site["took"]}
        bench = [person for person in bench if person["id"] not in taken]

    # The full-cover plans, against what the demand plans left on the bench.
    # A bench member's week is shared across these plans the same way it is
    # across the demand plans, and written back only once a site's row is built.
    # The sites where the test is the live choice go first -- a shop with
    # neither HOUR_WEEKS_THIN weeks on every weekday it opens nor complete data,
    # or one already running the 24/7 test -- so a measured shop's full
    # cover, which nobody is following, cannot take the unassigned staff a
    # new shop's test needs. Site order within each.
    def live(entry):
        business, site = entry[1]
        if site is None:
            return 1
        grid = site["grid"]
        opens = [wd for wd in range(7) if grid["open"][wd]]
        thin = not opens or min(grid["weeks"][wd] for wd in opens) < HOUR_WEEKS_THIN
        return 0 if (
            (thin and site["run"] < DEMAND_RUN_DAYS)
            or (_open_all_hours(grid["open"]) and _full_cover_in_game(
                site["current"]["list"], grid["stations"], grid["open"]))
        ) else 1

    left = list(bench)
    shared = {person["id"]: _copy_state(state[person["id"]]) for person in left}
    out = [None] * len(sites)
    for index, (business, site) in sorted(enumerate(sites), key=lambda e: (live(e), e[0])):
        if site is None:
            out[index] = failed(business)
            continue
        mine = {p["id"] for p in site["took"]}
        free = {p["id"] for p in left}
        site_bench = [p for p in everyone_on_bench if p["id"] in mine or p["id"] in free]
        scratch = {pid: _copy_state(entry) for pid, entry in site["before"].items()
                   if pid not in free}
        scratch.update({pid: _copy_state(shared[pid]) for pid in free})
        # The Staff page's plan for the shop (Peter, 26 September 2026:
        # "Staff the hours it's open, never change opening"): the hours it
        # opens now and never more, placed from the same starting week as the
        # full-cover plan, as the other choice to it. See _open_need().
        opened_scratch = {pid: _copy_state(entry) for pid, entry in scratch.items()}
        grid = site["grid"]
        offered = any(s["skill"] for s in grid["stations"]) and any(grid["open"])
        try:
            full = _place_week(
                grid, _full_need(grid), ALL_DAY_OPEN, site["coverPosts"],
                site["own"] + site_bench, people, business, site_bench, scratch,
                current=site["current"]["list"],
            )
            if not offered:
                opened = None
            elif _open_is_full(site):
                opened = _copy_week(full)
            else:
                opened = _place_week(
                    grid, _open_need(site), grid["open"], site["coverPosts"],
                    site["own"] + site_bench, people, business, site_bench, opened_scratch,
                    current=site["current"]["list"],
                )
            row = _finish_site(site, full, names, people, opened)
        except Exception:
            out[index] = failed(business)
            continue
        # Only the plan the site is on by default reserves whom it draws off
        # the bench, before the offices and factories are planned: the demand
        # plan did above, or the open-hours plan here for a shop that opens on
        # it (_opens_first()). Full cover, and whichever of the two the site
        # is not on, may draw on the bench but hold nobody back from others.
        if opened is not None and _opens_first(site, business):
            drawn = {p["id"] for p in opened["took"]}
            for pid in drawn & free:
                shared[pid] = opened_scratch[pid]
            left = [person for person in left if person["id"] not in drawn]
        out[index] = row
    state.update(shared)
    world["bench"] = left
    return out


def _opens_first(site: dict, business: dict) -> bool:
    """Whether a shop is on its open-hours plan by default, as the board picks it.

    The board's spOpenFirst(): a shop whose demand data is not complete, or
    one nobody works at yet, is on the open-hours plan; any other on its
    demand plan, until the player picks the 24/7 test.
    """
    grid = site["grid"]
    offered = any(s["skill"] for s in grid["stations"]) and any(grid["open"])
    return offered and (site["run"] < DEMAND_RUN_DAYS or not business.get("staff"))


def _open_is_full(site: dict) -> bool:
    """Whether a shop's open-hours plan is its full-cover plan, placed a second time.

    A shop with complete data whose doors are already open every hour: its
    open-hours need is full cover's (_open_need()), and the hours it is cut
    against are 0 to 24 on every day either way. The one thing that tells the
    two apart, the slots the doors are held in, only decides which gaps may be
    bridged, and a need of every station every hour leaves no gap. The two
    placements start from copies of one week with one pool, so the second is
    the first again; _staffing() copies it (_copy_week()) instead.
    """
    return site["run"] >= DEMAND_RUN_DAYS and _open_all_hours(site["grid"]["open"])


def _copy_week(week: dict) -> dict:
    """A placement's result another plan carries as its own, with no row shared.

    The rows are copied and the hire weeks pointed at the copies, because
    _hire_fields() finds a hire's rows by identity; the headcount is copied
    because the payload carries its entries as they are.
    """
    shifts = [dict(shift) for shift in week["shifts"]]
    twin = {id(old): new for old, new in zip(week["shifts"], shifts)}
    return dict(
        week,
        shifts=shifts,
        headcount={skill: dict(entry) for skill, entry in week["headcount"].items()},
        hireWeeks={
            skill: [dict(hire, slots=[twin[id(s)] for s in hire["slots"]],
                         busy=[set(hours) for hours in hire["busy"]]) for hire in hires]
            for skill, hires in week["hireWeeks"].items()
        },
    )


def _open_need(site: dict) -> dict:
    """The need of the Staff page's plan for a shop, which never opens it longer.

    A shop with complete data (DEMAND_RUN_DAYS): every station of every role,
    the hours it opens now; the page uses it where the player runs full cover.
    A shop without: its demand curve, with every open hour nothing has read
    (basis `none`) given every station of the role (_open_floor()), which the
    page uses in place of the demand plan -- an open hour needs its stations
    before anything is measured (Peter, 26 September 2026). Hours the shop is
    shut are left out by the placer either way.
    """
    if site["run"] >= DEMAND_RUN_DAYS:
        return _full_need(site["grid"])
    return _open_floor(site["need"], site["grid"])


def _open_floor(need: dict, grid: dict) -> dict:
    """A need curve with every open hour it reads nothing for (`none`) staffed in full.

    The curve is keyed by role (_station_role()), not by skill: a hairdresser's
    head wash is a role of its own under the Hair Stylist skill, and counting
    stations by skill gave it none and its chairs the head washes' as well.
    """
    stations = collections.Counter(_station_role(s) for s in grid["stations"])
    out = {}
    for skill, row in need.items():
        count = stations.get(skill, 0)
        cells = [list(day) for day in row["need"]]
        basis = [list(day) for day in row["basis"]]
        for wd in range(7):
            for start, end in grid["open"][wd]:
                for hour in range(max(0, start), min(24, end)):
                    if count and basis[wd][hour] == "none":
                        cells[wd][hour] = count
                        basis[wd][hour] = "open"
        out[skill] = dict(row, need=cells, basis=basis)
    return out


def _full_need(grid: dict) -> dict:
    """The need curve of the full-cover plan: every station of every role, every hour.

    A new shop has no measured hour, so its demand plan is cleaning and security
    alone. The full-cover plan is the demand test that fixes that: every serving
    station staffed every hour for the shop's first DEMAND_RUN_DAYS days (days
    since it first opened, closed days included), so no hour's customers are
    turned away by an empty register and the count that comes back is the
    demand. It goes through the same placer as the demand plan with this curve
    in place of _need_curve()'s, which is the whole difference between the two.
    """
    out = {}
    for role in grid["roles"]:
        count = sum(1 for s in grid["stations"] if _station_role(s) == _role_key(role))
        out[_role_key(role)] = {
            "need": [[count] * 24 for _ in range(7)],
            "basis": [["full"] * 24 for _ in range(7)],
        }
    return out


# The opening hours the full-cover plan assumes: every weekday, 0 to 24. An hour
# the shop is shut is an hour the demand test never measures, so opening every
# day around the clock is the plan's first step, not an option beside it.
ALL_DAY_OPEN = [[[0, 24]] for _ in range(7)]


FACTORY_SKILL = "ba:skill_factoryworker"
FACTORY_RUN_START = 6  # where a shorter run sits when nobody's demands decide it


def _factory_run_start(hours: int, pool: list) -> int:
    """Where a line's daily run of `hours` starts: around the workers' demands.

    Every start from 0 to 24 - hours (a run never wraps past midnight) is cut
    as the placer cuts it (_cut_run), and scored by how many of the pool could
    take each piece without it touching one of their blackout windows. The
    best score wins; a tie goes to the start closest to FACTORY_RUN_START, then
    the earliest. A factory has no customer curve, so with nobody's demands
    in play every run starts at 06:00.
    """
    if hours >= 24:
        return 0
    best = None
    for start in range(0, 25 - hours):
        score = sum(
            1
            for low, high in _cut_run(start, start + hours)
            for person in pool
            if not any(a < high and low < b for a, b in person["blackouts"])
        )
        rank = (-score, abs(start - FACTORY_RUN_START), start)
        if best is None or rank < best[0]:
            best = (rank, start)
    return best[1]


def _factory_staffing(save: Save, names, businesses: list, factories: dict, staff: list,
                      detail: bool = False, world: dict | None = None) -> dict:
    """Staffing for factory lines, once per sizing: {cap: [row], dem: [row]}.

    The shop roster's placer (_place_week) over a synthetic grid: one role,
    Factory Worker, one station per machine, open around the clock, with no
    cleaning or security. Each line runs its needed hours a day (24 sized
    24/7, `needHours.dem` sized for demand) as one run from
    _factory_run_start(), cut into shifts of at most 12 hours. The pool is the
    factory's own staff, then the unassigned factory workers the shops and
    offices left on `world`'s bench (_staff_plans()), whom either sizing's
    week draws off it. `headcount.needed` is the week's
    machine-hours; `wageDay` the mean day's wage of the factory's factory
    workers; `delta` what hiring the plan's `hire` and letting its `spare` go
    does to the headcount and the day's wage bill. A factory the placer falls
    over on is one `failed` row, as a shop is in _staffing().

    A line whose recipe the board cannot name (`unnamed`, a recipe set) is
    rostered too, all 24 hours sized 24/7 and its hours now sized for demand
    (24 where nobody is on it), since what it makes is unknown; the row counts
    its machines in `unnamedMachines`. A machine with no recipe stays out.

    The payload row is what the board reads: `lines`, `headcount`, `wageDay`,
    `delta` (and `unnamedMachines`). `detail` keeps the placer's own tables
    (`stations`, `people`, `shifts`, `placed`, `shortHours`) for the tests.

    Takes each line's `_posts` (its machines' item ids) off the payload, keyed
    by the line's place in its list, so two lines making one item keep theirs.
    """
    sites = factories.get("sites", [])
    posts_of = {}
    for site in sites:
        for i, line in enumerate(site["lines"]):
            posts_of[("line", site["s"], i)] = line.pop("_posts", [])
        for i, line in enumerate(site.get("unnamed", [])):
            posts_of[("unnamed", site["s"], i)] = line.pop("_posts", [])
    world = world or _plan_world(save, staff)
    people = world["people"]
    label = names.label(FACTORY_SKILL) if names else FACTORY_SKILL
    buildings = {
        site_key(_address_of(b)): b
        for b in save.items(save.root.get("BuildingRegistrations"))
        if isinstance(b, dict)
    }
    out = {mode: [] for mode in SIZING_MODES}
    for site in sites:
        business = businesses[site["s"]]
        building = buildings.get(business["key"])
        pool = [p for p in _site_pool(people, business, world["bench"])
                if _usable(p, FACTORY_SKILL, "serve")]
        workers = [
            p for p in staff
            if p["addr"] and site_key(p["addr"]) == business["key"]
            and FACTORY_SKILL in (p["skills"] or ())
        ]
        wage_day = money(sum(p["daily"] for p in workers) / len(workers)) if workers else 0.0
        drawn = set()
        rows = {}
        for mode in SIZING_MODES:
            # Both sizings asking for the same hours of every line is one week
            # placed twice over (a factory whose lines run all day either way):
            # the second is a copy of the first, never the same row.
            twin = next((other for other in rows if _factory_hours(site, other)
                         == _factory_hours(site, mode)), None)
            try:
                if twin is not None:
                    row = copy.deepcopy(rows[twin])
                else:
                    row = _factory_site_plan(save, building, site, business, posts_of, pool,
                                             people, mode, label, names, wage_day, world["state"])
            except Exception:
                row = {"key": business["key"], "s": site["s"], "name": business["name"],
                       "failed": True}
            rows[mode] = row
        for mode in SIZING_MODES:
            row = rows[mode]
            if row is not None and not detail and not row.get("failed"):
                # The week itself stays (stations, people, shifts), so the Staff
                # page can write it; the placer's own tables go.
                for field in ("placed", "shortHours"):
                    row.pop(field, None)
            if row is not None:
                drawn.update(row.pop("_took", ()))
                out[mode].append(row)
        # Whom either sizing draws off the bench is this factory's either way,
        # as a shop's two plans share theirs.
        world["bench"] = [p for p in world["bench"] if p["id"] not in drawn]
    return out


def _factory_hours(site: dict, mode: str) -> list:
    """The hours a day each line of a factory runs in one sizing, as _factory_site_plan() reads them."""
    return ([line["needHours"][mode] for line in site["lines"]]
            + [24 if mode == "cap" or not line.get("hoursNow") else line["hoursNow"]
               for line in site.get("unnamed", []) if line.get("rid") is not None])


def _factory_site_plan(save, building, site, business, posts_of, pool, people, mode, label,
                       names, wage_day, state=None):
    """One factory's row of _factory_staffing() in one sizing, or None with no line.

    `current` is the factory's schedule as it stands (_current_roster()), so the
    Staff page can keep the shifts on stations the plan does not own -- the
    delivery drivers' -- when it replaces the week, and can tell a move source
    whose people hold hours there.
    """
    stations, runs, lines, idle = [], {}, [], []
    unnamed_machines = 0
    todo = [(line, posts_of.get(("line", site["s"], i)) or [], line["needHours"][mode], line["item"], False)
            for i, line in enumerate(site["lines"])]
    for i, line in enumerate(site.get("unnamed", [])):
        if line.get("rid") is None:
            continue
        now = line.get("hoursNow") or 0
        todo.append((line, posts_of.get(("unnamed", site["s"], i)) or [],
                     24 if mode == "cap" or not now else now,
                     msg("sp.py.factory.unnamed", "{workstation}, recipe not named",
                         workstation=tok(line.get("workstationKey"), line["workstation"])), True))
    for line, posts, hours, item, unnamed in todo:
        if posts and not hours:
            # A line this sizing leaves idle: its machines are still machines,
            # listed with the factory worker's skill so the Staff page never
            # keeps a live shift on one as it keeps a driver's.
            idle.extend({"id": post, "skill": FACTORY_SKILL, "rate": 1,
                         "name": f"{item}, position {position}"}
                        for position, post in zip(line["slots"], posts))
        if not posts or not hours:
            continue
        if unnamed:
            unnamed_machines += len(posts)
        # Around the factory's own staff's demands: the bench is only who
        # might be drawn, and an unassigned worker nobody uses must not move
        # the line. The bench alone decides where the factory has nobody.
        start = _factory_run_start(hours, [p for p in pool if p["addr"]] or pool)
        for position, post in zip(line["slots"], posts):
            runs[len(stations)] = [set(range(start, start + hours)) for _ in range(7)]
            stations.append({"id": post, "skill": FACTORY_SKILL, "rate": 1,
                             "name": msg("sp.py.factory.station", "{item}, position {slot}",
                                         item=plain(item), slot=position, item_name=item)})
        lines.append({
            "slug": line.get("slug"), "item": item, "machines": line["machines"],
            "hoursNow": line.get("hoursNow"), "hours": hours, "from": start, "to": start + hours,
            "cuts": [list(cut) for cut in _cut_run(start, start + hours)],
            **({"unnamed": True} if unnamed else {}),
        })
    if not lines:
        return None
    grid = {"roles": [{"skill": FACTORY_SKILL, "label": label}], "stations": stations}
    need = {FACTORY_SKILL: {
        "need": [[sum(1 for days in runs.values() if hour in days[wd]) for hour in range(24)]
                 for wd in range(7)],
        "stations": runs,
    }}
    # The fewest of the factory's own workers that cover the week. The placer
    # spreads a week over everybody it is given, so it is given the least
    # ceil(machine-hours / 50) first, and one more while a line is left with
    # nobody on it: whoever it is not given is spare. The factory's own staff
    # before anybody off the bench, then those whose blackout windows touch
    # the fewest shifts, then the pool's order.
    pieces = [cut for line in lines for cut in line["cuts"]]
    current = (
        _current_roster(save, building, {s["id"]: dict(s, slug=None) for s in stations + idle})
        if building is not None else {"shifts": 0, "fragments": 0, "list": []}
    )
    ranked = sorted(
        enumerate(pool),
        key=lambda entry: (
            not entry[1]["addr"],
            sum(1 for low, high in pieces for a, b in entry[1]["blackouts"]
                if a < high and low < b),
            entry[1]["weekendsOff"],
            entry[1]["days"] is not None,
            entry[0],
        ),
    )
    ranked = [person for _index, person in ranked]
    needed = sum(len(hours) for days in runs.values() for hours in days)
    for count in range(min(math.ceil(needed / FULL_TIME[1]), len(ranked)), len(ranked) + 1):
        trial = ranked[:count]
        trial_state = {
            person["id"]: _copy_state(state[person["id"]]) if state else _fresh_state()
            for person in trial
        }
        # Hires only in the last trial, the whole pool's: an earlier one that
        # leaves a line open is only the answer "more of the pool", and the
        # count search goes on to ask it.
        week = _place_week(grid, need, ALL_DAY_OPEN, [], trial, people, business,
                           [p for p in trial if not p["addr"]], trial_state,
                           current=current["list"], hires=count == len(ranked))
        if all(shift["employee"] is not None for shift in week["shifts"]):
            break
    table = _index_table(stations + idle, (week["shifts"], current["list"]),
                         (current["list"], week["shifts"], week["shortHours"], week["placed"]),
                         people)
    count = week["headcount"][FACTORY_SKILL]
    worked = {shift["employee"] for shift in week["shifts"] if shift["employee"] is not None}
    own = {p["id"] for p in pool if p["addr"]}
    took = [p for p in pool if not p["addr"] and p["id"] in worked]
    headcount = {"needed": count["needed"], "min": count["min"], "have": len(own) + len(took),
                 "spare": len(own - worked), "hire": count["hire"]}
    workers = headcount["hire"] - headcount["spare"]
    # The whole pool's spare, not only the trial's: everybody here the week
    # gives no hours. The week was placed on its own trial, so its own ids
    # are overwritten. Only the factory's own: a bench member the week does
    # not use was never this factory's.
    week["spareIds"] = _in_order(own - worked)
    week["spareSkills"] = {pid: [FACTORY_SKILL] for pid in week["spareIds"]}
    return {
        "key": business["key"],
        "s": site["s"],
        "name": business["name"],
        "lines": lines,
        "headcount": headcount,
        "wageDay": wage_day,
        "delta": {"workers": workers, "perDay": money(workers * wage_day)},
        **({"unnamedMachines": unnamed_machines} if unnamed_machines else {}),
        "stations": table["stations"],
        "people": table["people"],
        "shifts": [_shift_row(shift, table) for shift in week["shifts"]],
        "current": {
            "shifts": current["shifts"],
            "fragments": current["fragments"],
            "list": [_shift_row(r, table) for r in current["list"]],
        },
        "placed": [
            {"p": table["person"][r["employee"]], "demand": r["demand"],
             "label": names.label(r["demand"]) if names else r["demand"],
             "wd": r["wd"], "from": r["from"], "to": r["to"]}
            for r in week["placed"]
        ],
        "shortHours": [
            {"p": table["person"][r["employee"]], "hours": r["hours"], "min": r["min"],
             "planned": r["planned"]}
            for r in week["shortHours"]
        ],
        "addPeople": _add_people(week, people, names),
        # The Staff page's part, taken off by _hiring(). See _hire_fields().
        "_hire": _hire_fields(week),
        # Whom this week draws off the bench, taken off by _factory_staffing().
        "_took": [p["id"] for p in took],
    }


# How many finished days since the shop first opened make the demand data good
# enough for the demand plan (Peter, 23 September 2026): nine covers every
# weekday once and two of them twice, a week and a bit of game time rather than
# the fortnight HOUR_WEEKS_THIN would take. Not nine in a row: a nightclub shut
# every Monday still completes on its ninth day, and its Mondays are no demand.
DEMAND_RUN_DAYS = 9


def _days_open(save: Save, building: dict) -> int:
    """Finished days since the shop first opened, today's unfinished day left out.

    The first open day is the earliest day on file with at least one hour
    report: the game files a report for an hour the shop was open and served
    somebody, and none for an hour it was shut or empty. The order history
    keeps about sixteen days, so a shop older than that counts from the
    earliest day it still holds, which is past DEMAND_RUN_DAYS already. A
    window with no report at all is not complete, whatever the shop's age: a
    shop fitted out and left shut, or one nobody visits, has measured nothing,
    and a demand plan of no customers anywhere would be a guess, not data. A
    save without a day counts to the last day on file.
    """
    today = save.root.get("Day")
    served, held = [], []
    for entry in save.items(building.get("orderHistory")):
        number = entry.get("dayNumber")
        if number is None or (today is not None and number >= today):
            continue
        held.append(number)
        if save.items(entry.get("hourReports")):
            served.append(number)
    if not held:
        return 0
    end = today if today is not None else max(held) + 1
    return end - min(served) if served else 0


def _open_day_average(save: Save, building: dict, slots: list) -> list:
    """Customers per weekday and hour, averaged over the days the shop was open.

    The board's customer grid averages an hour over the reports filed for it,
    and the game files none for an hour nobody came, so a quiet hour drops out
    and the average is the busy days' alone: 3 one Tuesday at 03:00 and nobody
    the next reads 3. Here an hour is averaged over every open day on that
    weekday, a missing hour counting as none: that Tuesday reads 1.5.

    An open day is a finished day in `orderHistory` -- the game keeps an entry
    for every day, reports or not -- on a weekday the shop's current schedule
    (`slots`) opens, from the first day the shop served anybody: the days
    before it were the fit-out, not trade. A day nobody came all day files an
    entry with no report and counts as a day of none. Today, unfinished, is
    left out. A weekday with no open day yet, or one the schedule keeps shut,
    is none throughout.
    """
    today = save.root.get("Day")
    entries = []
    for entry in save.items(building.get("orderHistory")):
        number = entry.get("dayNumber")
        if number is None or (today is not None and number >= today):
            continue
        entries.append((number, save.items(entry.get("hourReports"))))
    served = [number for number, reports in entries if reports]
    sums = [[0.0] * 24 for _ in range(7)]
    days = [0] * 7
    for number, reports in entries:
        wd = number % 7
        if not served or number < min(served) or not slots[wd]:
            continue
        days[wd] += 1
        for report in reports:
            hour = report.get("hour")
            if hour is not None and 0 <= hour < 24:
                sums[wd][hour] += report.get("customers", 0) or 0
    return [
        [round(total / days[wd], 1) for total in sums[wd]] if days[wd] else [0.0] * 24
        for wd in range(7)
    ]


def _run_measured(grid: dict, run: int, daily: list | None = None) -> dict:
    """The hour grid the demand plan reads, for a shop with complete data.

    The demand plan calls a weekday thin below HOUR_WEEKS_THIN weeks and reads
    a thin weekday off another through the game's day curve, or not at all; an
    hour with no report it reads off another weekday the same way. Nine days
    since the shop first opened are what Peter decided is enough (23 September
    2026). So for such a shop no weekday is thin, and every hour with no report
    on file counts as no customers: the shop was shut then, or empty, and
    either way nobody is staffed for it. A weekday it never opened is no demand
    all day. `daily`, from _open_day_average(), replaces each hour's average
    over its reports with the average over the days the shop was open, so a
    day nobody came at that hour counts as none rather than dropping out, and
    a weekday with no finished open day is none rather than whatever today's
    unfinished day has filed so far; this copy only, the board's own customer
    grid is left as it is. A shop without
    the nine days keeps the grid, and the gate, as it is.
    """
    if run < DEMAND_RUN_DAYS:
        return grid
    customers = [
        [0.0 if value is None else value for value in row] for row in grid["customers"]
    ]
    for wd in range(7):
        if daily is not None:
            customers[wd] = list(daily[wd])
    return dict(grid, thin=[False] * 7, customers=customers)


def _unmeasured(grid: dict, run: int) -> list:
    """Hours the current schedule opens that no report has measured, per weekday.

    Only for a shop with complete data, where such an hour counts as no
    customers: it is the missing data the page points at, so a player who
    measured 8 to 22 and now opens around the clock knows the night is a guess
    of nobody until the reports arrive.
    """
    if run < DEMAND_RUN_DAYS:
        return [[] for _ in range(7)]
    return [
        sorted(
            hour
            for start, end in grid["open"][wd]
            for hour in range(max(0, start), min(24, end))
            if grid["customers"][wd][hour] is None
        )
        for wd in range(7)
    ]


def _demand_data_complete(run, week, grid, in_game) -> bool:
    """Whether to tell the player to switch from full cover to the demand plan.

    All of it, straight from the save:

    - the demand data is complete: at least DEMAND_RUN_DAYS finished days since
      the shop first opened (_days_open()), read from the days as they were
      staffed, whoever was on;
    - the game staffs every serving station every hour the shop is open now
      (`in_game`, see _full_cover_in_game()), so this is advice to a shop on
      the test, not to one already on a demand plan;
    - and the demand plan asks for fewer serving hours than full cover of the
      shop's own open hours now (_own_full_hours()): a shop busy every open
      hour is already on its demand plan, and switching changes nothing. The
      full-cover plan's 24/7 is not the measure, or every shop shut some hour
      would seem to save the hours it is shut.

    No age and no clock: an older shop run at full cover with complete data
    gets the same advice, and it is right for it too.
    """
    if not in_game or run < DEMAND_RUN_DAYS:
        return False
    return _serving_hours(week["shifts"]) < _own_full_hours(grid)


def _own_full_hours(grid: dict) -> int:
    """Serving station-hours of full cover of the shop's current open hours.

    Every serving station of every role, every hour the schedule opens now.
    """
    opened = sum(
        len({hour for start, end in grid["open"][wd] for hour in range(max(0, start), min(24, end))})
        for wd in range(7)
    )
    return opened * len(grid["stations"])


def _open_all_hours(slots: list) -> bool:
    """Whether the doors are open every hour of every weekday."""
    return all(
        {hour for start, end in slots[wd] for hour in range(max(0, start), min(24, end))}
        == set(range(24))
        for wd in range(7)
    )


def _full_cover_in_game(current: list, stations: list, slots: list) -> bool:
    """Whether the schedule in the game is full cover of the shop's own hours.

    Every serving station staffed every hour the shop is open, whatever those
    hours are (Peter, 23 September 2026: the player may keep a shorter day, and
    the plan counts its shut hours as no demand). Nothing less inside them: an
    hour a register stands empty is an hour whose customers were turned away by
    the schedule rather than by demand. A site with no serving station, or one
    open no hour at all, has no demand to test, so it never is one.
    """
    opened = {
        (wd, hour)
        for wd in range(7)
        for start, end in slots[wd]
        for hour in range(max(0, start), min(24, end))
    }
    if not stations or not opened:
        return False
    covered = {station["id"]: set() for station in stations}
    for row in current:
        if row["kind"] == "serve" and row["station"] in covered:
            covered[row["station"]].update(
                (row["wd"], hour) for hour in range(row["from"], row["to"])
            )
    return all(opened <= hours for hours in covered.values())


def _serving_hours(shifts: list) -> int:
    """The station-hours a plan puts on the serving stations, staffed or not."""
    return sum(s["to"] - s["from"] for s in shifts if s["kind"] == "serve")


def _place_week(grid, need, slots_open, cover_posts, pool, people, business, bench, state,
                groups=None, current=None, hires=True) -> dict:
    """One week of shifts for one site, from one need curve: the placer itself.

    Everything after the need curve, in the scope's order: a. per-station cover
    and b. the cut with the troughs bridged in between, c. the headcount, d. the
    placement, e. the residue, f. cleaning and security. `slots_open` is the
    opening hours the week is cut against -- the shop's own for the demand plan,
    0 to 24 every day for the full-cover plan -- and `state` is the copy of
    everybody's week this plan writes into.

    `current` is the site's week as it stands (_current_roster()'s rows): a
    person already working here whom the plan would leave worse off keeps it
    (_worse_off(), _pin_weeks()). `hires` false leaves the lines nobody here
    may work open with no hire weeks, for a caller that only asks whether a
    pool covers the week.
    """
    open_hours = [
        sorted({hour for start, end in slots_open[wd] for hour in range(start, end)})
        for wd in range(7)
    ]

    # a. Per-station cover, b. the cut, with the troughs bridged in between.
    wanted, role_wages = {}, {}
    site_pool = _site_pool(people, business, bench)  # one list for every role's wage
    for role in grid["roles"]:
        skill, role_key = role["skill"], _role_key(role)
        posts = [s for s in grid["stations"] if _station_role(s) == role_key]
        role_wages[role_key] = _role_wage(site_pool, skill)
        # A factory hands each machine's hours over itself (`stations`, see
        # _factory_staffing()); a shop's come from its need curve. Copied,
        # because the bridging below writes into them.
        stations = need[role_key].get("stations")
        wanted[role_key] = {
            index: [set(hours) for hours in days] for index, days in stations.items()
        } if stations else _cover_runs(
            need[role_key]["need"], [s["rate"] for s in posts], open_hours
        )
    required = sum(
        len(days[wd])
        for by_index in wanted.values()
        for days in by_index.values()
        for wd in range(7)
    )
    budget = required * SLACK_SHARE
    slack_hours, slack_cost = _bridge_troughs(
        wanted, role_wages, budget, slots_open
    )

    slots = []
    for role in grid["roles"]:
        skill, role_key = role["skill"], _role_key(role)
        posts = [s for s in grid["stations"] if _station_role(s) == role_key]
        for index, days in wanted[role_key].items():
            post = posts[index]
            for wd in range(7):
                for start, end in _runs(days[wd]):
                    for cut_start, cut_end in _cut_run(start, end):
                        slots.append(
                            {
                                "wd": wd,
                                "station": post["id"],
                                "skill": skill,
                                "from": cut_start,
                                "to": cut_end,
                                "kind": "serve",
                            }
                        )

    # f. Cleaning and security: one person per station for every open hour, cut
    # the same way and placed after the serving stations, so neither ever steals
    # a person from a queue.
    cover_slots = []
    for post in cover_posts:
        kind, skill = COVER_STATIONS[post["slug"]]
        for wd in range(7):
            for start, end in _runs(open_hours[wd]):
                for cut_start, cut_end in _cut_run(start, end):
                    cover_slots.append(
                        {
                            "wd": wd,
                            "station": post["id"],
                            "skill": skill,
                            "from": cut_start,
                            "to": cut_end,
                            "kind": kind,
                        }
                    )

    # c. Headcount, before anybody is placed: the number the player most wants.
    headcount = {}
    for group in (slots, cover_slots):
        for slot in group:
            entry = headcount.setdefault(
                slot["skill"],
                {"kind": slot["kind"], "needed": 0, "min": 0, "max": 0,
                 "have": 0, "spare": 0, "hire": 0, "hireHours": 0},
            )
            entry["needed"] += slot["to"] - slot["from"]
    for entry in headcount.values():
        entry["min"] = math.ceil(entry["needed"] / FULL_TIME[1])
        entry["max"] = entry["needed"] // FULL_TIME[0]

    # d. Place, most-constrained-first, serving stations before cover.
    before = {
        person["id"]: (
            state[person["id"]]["hours"],
            len(state[person["id"]]["days"]),
        )
        for person in pool
    }
    # What the rank knows about this site. `rostered` is who it has put on a
    # shift, carried across both passes so the cleaning and security cover goes
    # to people already serving the queue here rather than to two more names.
    # `flex` is how many of this site's roles each person could work, so the one
    # who holds a role nobody else does is kept for it.
    # Every role this site has, as the pair `_usable()` reads: the serving ones
    # and then its cleaning and security cover. Counted through that predicate
    # rather than by skills held, or somebody who holds Cleaning and Customer
    # Service scores two roles the plan will only ever use them for one of.
    # Two roles of one skill -- a hairdresser's chairs and head wash -- are one
    # role to the person holding it, so the pairs are counted once each.
    roles_here = list(dict.fromkeys((role["skill"], "serve") for role in grid["roles"]))
    roles_here += [
        (COVER_STATIONS[post["slug"]][1], COVER_STATIONS[post["slug"]][0])
        for post in cover_posts
    ]
    flex = {
        person["id"]: sum(1 for skill, kind in roles_here if _usable(person, skill, kind))
        for person in pool
    }

    def fresh_here():
        # Each station's furniture group (_station_groups()), where the caller
        # has the building: a desk demand is met at a station, not a site.
        return {"groups": groups or {}, "rostered": set(), "flex": flex}

    # The people already working here whom a plan could cut short of the week
    # they have (_worse_off()): those holding an hours band or a day count,
    # with a week here now, in a role this plan staffs.
    # Only the hours on stations this plan owns: a factory's delivery driver
    # entries, say, are no part of the week it plans or writes.
    owned = {s["id"] for s in grid["stations"]} | {post["id"] for post in cover_posts}
    now = _weeks_now([row for row in current or () if row["station"] in owned], pool)
    planned_roles = {(slot["skill"], slot["kind"]) for slot in slots + cover_slots}
    protected = [
        person for person in pool
        if person["id"] in now and (person["band"] or person["days"] is not None)
        and any(_usable(person, skill, kind) for skill, kind in planned_roles)
    ]
    start = {pid: _copy_state(state[pid]) for pid in before} if protected else None
    pins, kept, allowed = [], [], {}
    while True:
        here = fresh_here()
        shifts = _fill_week(slots, cover_slots, pool, state, here, pins, allowed)
        _repair_week(shifts, pool, state, here["rostered"], before)
        worse = [
            person["id"] for person in protected
            if person["id"] not in kept
            and _worse_off(person, state[person["id"]], before[person["id"]], now[person["id"]])
        ]
        if not worse:
            break
        # Keep their week as it stands and plan everybody else round it, from
        # the start. Whose week is kept changes what the rest are given, so the
        # test is asked again until nobody new is cut short.
        for pid, entry in start.items():
            state[pid] = _copy_state(entry)
        kept += worse
        role_of = {s["id"]: _station_role(s) for s in grid["stations"]}
        staffed_roles = {role_of.get(slot["station"]) for slot in slots}
        stations_ok = {s["id"]: (s["skill"], "serve") for s in grid["stations"]
                       if _station_role(s) in staffed_roles}
        stations_ok.update({slot["station"]: (slot["skill"], slot["kind"])
                            for slot in cover_slots})
        by_id = {person["id"]: person for person in pool}
        pins = _pin_weeks(kept, now, stations_ok, open_hours, by_id)

    # e. The lines nobody here may work: offered again with hires in the pool
    # and the week settled for them, only where there are such lines, so a
    # week that needs nobody new is exactly the week above (_place_hires()).
    hire_weeks = {}
    if hires and any(shift["employee"] is None for shift in shifts):
        shifts, hire_weeks = _place_hires(shifts, pool, state, here, before)
    shifts.extend(pins)
    shifts.sort(
        key=lambda s: (s["wd"], s["from"], s["to"], str(s["station"]), str(s["employee"]))
    )

    # Who the site has is settled now rather than before placement: a bench
    # member counts here only if this site is the one that drew them off it.
    # One pass over the shifts, not one per person: the bench is every
    # unassigned employee in the save, and this runs once per site.
    worked = {
        shift["employee"] for shift in shifts if shift["employee"] is not None
    }
    mine_now = {
        person["id"]
        for person in pool
        if person["addr"] or person["id"] in worked
    }
    # Somebody the plan would never put on this role does not count as having
    # it: a shop whose staff all hold Customer Service has no cleaners, however
    # many of them also hold Cleaning, and the line has to say so or it reads
    # "3 here" beside a plan that hires two. `_usable()` is the same test the
    # placer and the scarcity key use.
    for skill, entry in headcount.items():
        entry["have"] = sum(
            1
            for person in pool
            if person["id"] in mine_now and _usable(person, skill, entry["kind"])
        )
        entry["hire"] = max(0, entry["min"] - entry["have"])
        # The people this site has no week for: the ones it holds who are given
        # no shift at all. Counted off the plan rather than as `have - min`,
        # because that arithmetic and the roster beside it could disagree -- the
        # plan may need a person more than `min` where a day's cap or a demand
        # splits the week. Since an employee works one building, this is the
        # number the player acts on: post them somewhere with hours, or let them
        # go. Nobody is double-counted with `hire`: that is the other direction.
        entry["spare"] = sum(
            1
            for person in pool
            if person["id"] in mine_now
            and _usable(person, skill, entry["kind"])
            and person["id"] not in worked
        )

    # The residue is a hiring line, never a broken demand, and a person the
    # plan leaves short of what their contract demands is a jobdemand warning
    # the player is about to earn, so it is said rather than bent away.
    # The hires' weeks are kept per role (hireWeeks, for the Staff page): one
    # week per person hired. `hire` can only exceed those weeks where `min -
    # have` says so with nothing left open, which the arithmetic rules out (the
    # people working a role's slots are all counted in its `have`); an empty
    # week pads it anyway, so the page's count and the weeks always agree.
    for skill in _in_order(hire_weeks):
        headcount[skill]["hire"] = max(headcount[skill]["hire"], len(hire_weeks[skill]))
    for skill in _in_order(headcount):
        weeks = hire_weeks.setdefault(skill, [])
        while len(weeks) < headcount[skill]["hire"]:
            weeks.append({"hours": 0.0, "busy": [set() for _ in range(7)], "slots": []})
    # The site's own people this plan gives no hours in a role it plans: the
    # ones a move may take elsewhere. Only roles the plan has, so a cashier at a
    # shop whose serving hours are not measured yet is not offered away.
    spare_ids = _in_order({
        person["id"]
        for person in pool
        if person["addr"] and person["id"] not in worked
        and any(_usable(person, skill, entry["kind"]) for skill, entry in headcount.items())
    })
    # And the roles each of them is spare in: a move keeps to one of these.
    by_id = {person["id"]: person for person in pool}
    spare_skills = {
        pid: [
            skill for skill in _in_order(headcount)
            if _usable(by_id[pid], skill, headcount[skill]["kind"])
        ]
        for pid in spare_ids
    }
    # The hours the hires' weeks really hold, which a full week each would
    # overstate where a hire's week is part time.
    for skill, entry in headcount.items():
        entry["hireHours"] = sum(week["hours"] for week in hire_weeks.get(skill, ()))
    short_hours, short_days = [], []
    for person in pool:
        if person["id"] not in mine_now:
            continue  # offered to this site and not taken: somebody else's
        mine = state[person["id"]]
        # Only the hours and days this site gave them: a bench member may have
        # been offered around, and another site's week is not this one's.
        hours_here = mine["hours"] - before[person["id"]][0]
        days_here = len(mine["days"]) - before[person["id"]][1]
        # Whether this plan could have used them at all. A site with no measured
        # hour plans its cleaning and security cover and nothing else, so a
        # cashier left with no week there is short because the board cannot read
        # the shop yet, while a cleaner is short in a role it really did plan.
        # Only the second is somebody to act on, and the page cannot tell them
        # apart from the roster alone.
        planned = any(
            _usable(person, skill, entry["kind"])
            for skill, entry in headcount.items()
        )
        if person["band"] and hours_here < person["band"][0]:
            short_hours.append(
                {"employee": person["id"], "hours": hours_here,
                 "min": person["band"][0], "planned": planned}
            )
        # A four- or five-day week is exactly four or five, so somebody the plan
        # can only give three days to has an unmet demand just as surely as
        # somebody under their hours -- and so does somebody it gives no day at
        # all, which is the worst case of the same thing rather than an absence
        # of one.
        if person["days"] is not None and days_here < person["days"]:
            short_days.append(
                {"employee": person["id"], "days": days_here,
                 "want": person["days"], "planned": planned}
            )
    short_hours.sort(key=lambda r: (r["hours"] - r["min"], str(r["employee"])))
    # The site's own people this week gives fewer hours than the game has them
    # on now (and some): the Staff page's review names them before a write
    # replaces the week. Nobody the plan gives no hours at all: the write's
    # own dry run names those (leftWithout).
    fewer = sorted(
        (
            {"employee": person["id"], "name": person["name"], "now": person.get("now") or 0,
             "hours": state[person["id"]]["hours"] - before[person["id"]][0]}
            for person in pool
            if person["addr"] and person["id"] in worked
            and 0 < state[person["id"]]["hours"] - before[person["id"]][0] < (person.get("now") or 0)
        ),
        key=lambda r: (r["hours"] - r["now"], str(r["employee"])),
    )
    short_days.sort(key=lambda r: (r["days"] - r["want"], str(r["employee"])))

    wage_of = {person["id"]: person["wage"] for person in pool}
    # What the plan pays the people it can price, which is what this number has
    # always meant: somebody the save gives no wage for is already counted at
    # nothing here, and a shift with nobody on it is the same case -- there is
    # no wage to quote until the player has hired somebody at one. What those
    # lines would cost is the hiring line's business, and `headcount.hireHours`
    # is the honest half of it.
    weekly = sum(
        s["hours"] * wage_of.get(s["employee"], 0.0)
        for s in shifts
        if s["employee"] is not None
    )
    # `skill` names a bench member for the page to read; `skills` is every
    # role they are counted under, because `have` above counts them once per
    # skill they hold. A reader taking a bench member off `have` under one
    # skill alone would show a two-skill bench member as somebody already here
    # under their second role.
    # Only the roles this site would really give them: `headcount.have` counts
    # a bench member the same way, and the page takes them off `have` under each
    # skill listed here. Listing a skill the plan will never use them for left a
    # bench server drawn as a cleaner, and the site's own cleaner counted off
    # the row to make space for them.
    bench_rows = []
    for person in bench:
        if person["id"] not in worked:
            continue
        usable = _in_order({
            skill for skill, kind in roles_here if _usable(person, skill, kind)
        })
        bench_rows.append({
            "employee": person["id"],
            "skill": usable[0] if usable else _first_skill(person),
            "skills": usable,
        })
    return {
        "need": need,
        "shifts": shifts,
        "headcount": headcount,
        "shortHours": short_hours,
        "shortDays": short_days,
        "placed": _demand_driven(shifts, pool),
        "bench": bench_rows,
        "slack": (slack_hours, slack_cost, budget),
        "weekly": weekly,
        "took": [person for person in bench if person["id"] in worked],
        "hireWeeks": hire_weeks,
        "spareIds": spare_ids,
        "spareSkills": spare_skills,
        "fewer": fewer,
    }


# --- add people: what a plan needs the player to do in MyEmployees first
def _add_people(week: dict, people: dict, names) -> dict:
    """The people a plan counts on who do not work at this site yet.

    The planner draws on the unassigned bench and sizes hires, because that
    keeps the plan the best week the site can have. Assigning and hiring stay
    the player's job, though: a schedule write can only fill entries for people
    already assigned here, so the entries that belong to a bench member or to a
    hire stay empty in the game until the player has added them. This says who
    and how many, and how many hours of the week wait on them.
    """
    label = lambda skill: names.label(skill) if skill and names else skill  # noqa: E731
    assign = [
        {
            "id": row["employee"],
            "name": (people.get(row["employee"]) or {}).get("name"),
            "skill": row["skill"],
            "role": label(row["skill"]),
        }
        for row in week["bench"]
    ]
    hire = [
        {"skill": skill, "role": label(skill), "people": week["headcount"][skill]["hire"]}
        for skill in _in_order(week["headcount"])
        if week["headcount"][skill]["hire"]
    ]
    return {
        "assign": assign,
        "hire": hire,
        "people": len(assign) + sum(row["people"] for row in hire),
        # The entries nobody at the site can be given yet: a hire's, which have
        # nobody on them, and a bench member's, until they are assigned here.
        "hoursUncovered": sum(
            s["to"] - s["from"]
            for s in week["shifts"]
            if s["employee"] is None or s.get("fromBench")
        ),
    }


def _hire_fields(week: dict) -> dict:
    """What the Staff page needs from one plan on top of the plan itself.

    `hireWeeks`: one entry per person the plan hires, its role, hours, days and
    the open entries (`p: null`) it would work, each by its index in the plan's
    `shifts`, so the page can put a person's id on it. The fullest weeks first
    within a role, so the best candidate gets the most hours. `spare`: the
    site's own people this plan gives no hours in a role it plans, and
    `spareSkills` the roles each is spare in (a move keeps to one of them).
    `bench`: the unassigned people the plan already counts on (addPeople.assign).

    Carried on the plan row as `_hire` and taken off it by _hiring().
    """
    index = {id(shift): i for i, shift in enumerate(week["shifts"])}
    slot_key = lambda s: (s["wd"], s["from"], s["to"], str(s["station"]))  # noqa: E731
    weeks = []
    for skill in _in_order(week["hireWeeks"]):
        packed = [
            (sorted(hire["slots"], key=slot_key), hire)
            for hire in week["hireWeeks"][skill]
        ]
        packed.sort(key=lambda e: (-sum(s["to"] - s["from"] for s in e[0]),
                                   [slot_key(s) for s in e[0]]))
        for slots, _hire in packed:
            hours = sum(s["to"] - s["from"] for s in slots)
            weeks.append({
                "skill": skill,
                "hours": hours,
                "days": len({s["wd"] for s in slots}),
                # Which contract the week suits (_hire_band()), for matching
                # a candidate's hours demand to it.
                "band": _hire_band(hours),
                "slots": [
                    {"shift": index[id(s)], "d": s["wd"], "f": s["from"], "t": s["to"],
                     "station": s["station"]}
                    for s in slots
                ],
            })
    return {
        "hireWeeks": weeks,
        # Hire weeks no hours demand is met by (under PART_TIME_FLOOR), said
        # the way shortHours says a person's: {skill, hours}.
        "shortHires": [{"skill": w["skill"], "hours": w["hours"]}
                       for w in weeks if w["band"] == "short" and w["slots"]],
        "spare": list(week["spareIds"]),
        "spareSkills": {pid: list(skills) for pid, skills in (week.get("spareSkills") or {}).items()},
        "bench": [row["employee"] for row in week["bench"]],
        # The site's own people this plan gives fewer hours than they have now.
        "fewer": [{"id": r["employee"], "name": r["name"], "now": r["now"], "hours": r["hours"]}
                  for r in week.get("fewer") or []],
    }


def _plan_fields(week: dict, table: dict, names, people: dict, cost: dict) -> dict:
    """One plan as the payload carries it, demand plan and full cover alike."""
    need = week["need"]
    slack_hours, slack_cost, budget = week["slack"]
    add = _add_people(week, people, names)
    for row in add["assign"]:
        row["p"] = table["person"][row["id"]]
    return {
        "need": {skill: need[skill]["need"] for skill in _in_order(need)},
        "basis": {skill: need[skill]["basis"] for skill in _in_order(need)},
        # One row shape, shared with current.list below: see _shift_row(). These
        # two lists are the only ones long enough for key names to weigh
        # anything, so they alone carry short ones.
        "shifts": [_shift_row(s, table) for s in week["shifts"]],
        "headcount": {skill: week["headcount"][skill] for skill in _in_order(week["headcount"])},
        "shortHours": [
            {"p": table["person"][r["employee"]], "hours": r["hours"],
             "min": r["min"], "planned": r["planned"]}
            for r in week["shortHours"]
        ],
        "shortDays": [
            {"p": table["person"][r["employee"]], "days": r["days"],
             "want": r["want"], "planned": r["planned"]}
            for r in week["shortDays"]
        ],
        "placed": [
            {
                "p": table["person"][r["employee"]],
                "demand": r["demand"],
                # The game's own word for the demand. The slug alone would make
                # the page invent wording for a rule the player reads in
                # MyEmployees, and `staffDemands` carries labels only for the
                # demands a site is *failing* -- a demand the plan has just
                # honoured is by definition not in that list.
                "label": names.label(r["demand"]),
                "wd": r["wd"],
                "from": r["from"],
                "to": r["to"],
            }
            for r in week["placed"]
        ],
        "bench": [
            {
                "p": table["person"][r["employee"]],
                "skill": r["skill"],
                "skills": r["skills"],
            }
            for r in week["bench"]
        ],
        "slack": {
            "hours": round(slack_hours, 1),
            "cost": money(slack_cost),
            "budget": round(budget, 1),
        },
        # `current` is the whole schedule's wage bill and `currentCover` the
        # part of it this plan would really replace. On a shop with no hour
        # reports the plan is cover alone, so the whole bill is not the thing
        # it is cheaper than: the serving shifts it does not touch stay, and
        # showing the two side by side would promise a saving nobody gets.
        "cost": dict(cost, weekly=money(week["weekly"])),
        # Who the player has to add before the plan can be filled: bench people
        # to assign here and people to hire. See _add_people().
        "addPeople": add,
        # The Staff page's part, taken off by _hiring(). See _hire_fields().
        "_hire": _hire_fields(week),
    }


def _plan_site(
    save, names, business, building, grid, people, bench, state, curves, table,
    base_promotion, caps,
) -> dict:
    """One retail site's demand plan, and what its full-cover plan will need.

    The demand plan is cut from the measured hours. The full-cover plan, which
    staffs every station every hour as a two-week demand test for a shop with
    nothing measured yet (docs/dashboard-reference.md, "The week the board would
    copy into BizMan"), is placed
    later by _staffing(), once every site's demand plan has taken its people
    off the bench; _finish_site() then builds the row from both.
    """
    # The arrival ceiling, for bounding a censored hour only. Never a target.
    # A current game sizes it off the building's size; an old one off the
    # products the game itself says are on the shelves, cachedAvailableProducts,
    # which is what GetInitialCustomers reads -- the board's own lines table is
    # sales and stock history and holds items the shop has stopped carrying. A
    # missing building row means the size is unknown, and _arrival_ceiling()
    # answers None rather than zero.
    curve = curves["types"].get(business["typeSlug"]) or {}
    row = table.get(_address_of(building)) or {}
    initial = _initial_customers(
        save.root.get("buildNumberAtStart"),
        _size_cap(row, caps),
        business["typeSlug"],
        row.get("m") or 0,
        save.items(building.get("cachedAvailableProducts")),
    )
    ceiling = _arrival_ceiling(
        business["typeSlug"],
        initial,
        business.get("promotion") or 0,
        base_promotion,
        grid["door"],
    )
    rates = collections.defaultdict(list)
    for station in grid["stations"]:
        rates[_station_role(station)].append(station["rate"])
    run = _days_open(save, building)
    daily = _open_day_average(save, building, grid["open"]) if run >= DEMAND_RUN_DAYS else None
    need = _need_curve(_run_measured(grid, run, daily), day=curve.get("d"), ceiling=ceiling,
                       rates=dict(rates))

    # A locker or cleaning station this business type takes nobody for is
    # left out, as _hourly() leaves out its serving stations: a theatre takes
    # no Security Guard, so a locker there is nobody's week and no hire.
    accepts = ASSIGN_SKILLS.get(business.get("typeSlug"))
    cover_posts, stray = [], collections.Counter()
    for post in _cover_posts(save, building, names):
        if accepts is None or COVER_STATIONS[post["slug"]][1] in accepts:
            cover_posts.append(post)
        else:
            stray[post["slug"]] += 1
    unstaffable = (grid.get("unstaffable") or []) + _unstaffable_rows(
        stray, {slug: COVER_STATIONS[slug][1] for slug in stray}, names)
    pool = _site_pool(people, business, bench)
    # Everybody's week as it stood before this site placed anybody: the
    # full-cover plan is the other choice for this site, not a second site, so
    # it starts from here for the site's own staff.
    before = {pid: _copy_state(entry) for pid, entry in state.items()}
    stations = {s["id"]: s for s in grid["stations"]}
    cover_stations = {post["id"]: post for post in cover_posts}
    # Keyed the way a shift names a station, so _current_roster() can tell a
    # guard on a locker from a cashier on a register.
    current = _current_roster(save, building, {**stations, **cover_stations})
    week = _place_week(grid, need, grid["open"], cover_posts, pool, people, business,
                       bench, state, current=current["list"])
    return {
        "save": save,
        "business": business,
        "building": building,
        "grid": grid,
        "ceiling": ceiling,
        "need": need,
        "coverPosts": cover_posts,
        "unstaffable": unstaffable,
        "own": [person for person in pool if person["addr"]],
        "before": before,
        "week": week,
        # Who this site drew off the bench, for _staffing() to take off it.
        "took": week["took"],
        "wage": {person["id"]: person["wage"] for person in pool},
        "current": current,
        "run": run,
    }


def _finish_site(site, full, names, people, opened=None) -> dict:
    """One retail site's row, from its demand plan and its full-cover plan."""
    save, business, building, grid = (
        site["save"], site["business"], site["building"], site["grid"])
    week, current, cover_posts = site["week"], site["current"], site["coverPosts"]
    wage_of = dict(site["wage"])
    for person in full["took"] + (opened["took"] if opened else []):
        wage_of[person["id"]] = person["wage"]
    # Two lookup tables, so the many rows below can be indices rather than
    # repeated 24-character ids. Everything a row points at is here: every
    # station either plan or the current roster posts anyone to, and everyone
    # any of them names.
    lists = lambda w: (w["shifts"], w["shortHours"], w["shortDays"], w["placed"], w["bench"])  # noqa: E731
    table = _index_table(
        grid["stations"] + cover_posts,
        (week["shifts"], full["shifts"], current["list"]) + ((opened["shifts"],) if opened else ()),
        (current["list"],) + lists(week) + lists(full) + (lists(opened) if opened else ()),
        people,
    )
    cost = {
        "current": money(_current_cost(current, site["wage"])),
        "currentCover": money(_current_cost(
            {"list": [r for r in current["list"] if r["kind"] != "serve"]}, site["wage"])),
    }
    in_game = _full_cover_in_game(current["list"], grid["stations"], grid["open"])
    return {
        "key": grid["key"],
        "name": business["name"],
        "typeSlug": business["typeSlug"],
        # Every opening slot of every weekday, as the game holds them, and an
        # empty list for a day the site stays shut. One pair spanning the day
        # would paint the hour between two slots open, and the plan would put
        # somebody in a closed shop.
        "open": grid["open"],
        # The two tables every index below reads through.
        "stations": table["stations"],
        "people": table["people"],
        "roles": [
            {
                "skill": role["skill"],
                **({"key": _role_key(role)} if _role_key(role) != role["skill"] else {}),
                "label": role["label"],
                "stations": [
                    table["station"][s["id"]]
                    for s in grid["stations"]
                    if _station_role(s) == _role_key(role)
                ],
            }
            for role in grid["roles"]
        ],
        "ceiling": site["ceiling"],
        # Stations here this business type takes nobody for, which no plan
        # staffs (_hourly(), _plan_site()): the Staffing block names them.
        **({"unstaffable": site["unstaffable"]} if site["unstaffable"] else {}),
        **_plan_fields(week, table, names, people, cost),
        # The demand test: every station of every role, every hour, placed by the
        # same placer with the same rules. Same shape as the demand plan above,
        # with the opening hours it assumes -- 0 to 24 every day -- and whether
        # the shop already opens that long, because an hour it is shut is an
        # hour the test never measures. `inGame` is whether the schedule in the
        # game already is one; see _full_cover_in_game(). Its need is every
        # station every hour, which the page reads off `roles`, so the two
        # grids that would say so 168 times a role are left out.
        "fullCover": {
            key: value
            for key, value in _plan_fields(full, table, names, people, cost).items()
            if key not in ("need", "basis")
        } | {
            "open": ALL_DAY_OPEN,
            "openAllHours": True,
            "openNow": _open_all_hours(grid["open"]),
            "inGame": in_game,
            # Finished days since the shop first opened, and the days that make
            # the demand data complete: the test's progress.
            "daysMeasured": site["run"],
            "daysNeeded": DEMAND_RUN_DAYS,
        },
        # The Staff page's plan (_open_need()): the hours the shop opens now,
        # never an hour more (`openAllHours` false); `complete` whether it is
        # full cover of those hours (complete data) or the demand plan with
        # every unread open hour staffed (not yet).
        **({"openCover": {
            key: value
            for key, value in _plan_fields(opened, table, names, people, cost).items()
            if key not in ("need", "basis")
        } | {"open": grid["open"], "openAllHours": False,
             "complete": site["run"] >= DEMAND_RUN_DAYS}} if opened else {}),
        # The hand-over: the demand data is complete while the game runs full
        # cover, and the demand plan would change something. See
        # _demand_data_complete().
        "demandDataComplete": _demand_data_complete(
            site["run"], week, grid, in_game),
        # Hours the schedule opens with no report behind them, per weekday, on
        # a shop whose demand plan counts them as no customers. See
        # _unmeasured(); empty lists everywhere else.
        "unmeasured": _unmeasured(grid, site["run"]),
        "current": {
            "shifts": current["shifts"],
            "fragments": current["fragments"],
            "coverFragments": current["coverFragments"],
            "cleaning": current["cleaning"],
            "security": current["security"],
            "list": [_shift_row(r, table) for r in current["list"]],
        },
        # How far this shop is from a roster of its own, for a page that has to
        # tell a shop with nothing worth changing from one that opened last
        # week. The game files one hour report per trading day, and a weekday's
        # hours are only read once HOUR_WEEKS_THIN of that weekday are on file,
        # so a shop needs a fortnight of trading before its serving shifts can
        # be cut from anything. `days` is the reports the save holds and `open`
        # how long the doors have been open, which is not the same number: a
        # shop shut half the week files fewer reports than it has days.
        "measure": {
            "days": sum(grid["weeks"]),
            "need": HOUR_WEEKS_THIN,
            "open": business.get("daysOpen"),
        },
    }


# --- hiring: the Staff page (issue #89; docs/architecture.md, the payload contract)
#
# The skills a business accepts when the player assigns somebody to it, as the
# game's own check has them (AssignToBusinessAndHireMassAction and
# AssignBusinessMassAction): the business type's employeePrimarySkills, plus
# Cleaning where the building type's requiredBuildingSkills holds it
# (BuildingTypeData.NeedsCleaning), Security Guard where the type carries the
# allowtheft tag, and Delivery Driver where the building type requires it. Read
# from the businesstypes and buildingtypes Addressables bundles at build 3682:
# retail, office, cinema and theatre buildings need cleaning; warehouses (which
# factories use) need nothing, and no building type requires a driver. A type
# missing here accepts nobody, so the page proposes no hire there rather than
# one the mod refuses (`no_skill`). On a new build the bundles are re-read by
# hand: docs/game-update.md, "Hand-read tables no script checks".
_SHOP_SKILLS = ("ba:skill_customerservice", "ba:skill_securityguard", CLEANING_SKILL)
ASSIGN_SKILLS = {
    "ba:businesstype_bookstore": _SHOP_SKILLS,
    "ba:businesstype_clothingstore": _SHOP_SKILLS,
    "ba:businesstype_electronicsstore": _SHOP_SKILLS,
    "ba:businesstype_florist": _SHOP_SKILLS,
    "ba:businesstype_fruitandvegetablestore": _SHOP_SKILLS,
    "ba:businesstype_giftshop": _SHOP_SKILLS,
    "ba:businesstype_jewelrystore": _SHOP_SKILLS,
    "ba:businesstype_liquorstore": _SHOP_SKILLS,
    "ba:businesstype_supermarket": _SHOP_SKILLS,
    "ba:businesstype_coffeeshop": ("ba:skill_customerservice", CLEANING_SKILL),
    "ba:businesstype_fastfoodrestaurant": ("ba:skill_customerservice", CLEANING_SKILL),
    "ba:businesstype_gym": ("ba:skill_gymtrainer", "ba:skill_securityguard", CLEANING_SKILL),
    "ba:businesstype_hairdresser": (
        "ba:skill_hairstylist", "ba:skill_customerservice", "ba:skill_securityguard",
        CLEANING_SKILL),
    "ba:businesstype_nightclub": ("ba:skill_dj", "ba:skill_customerservice", CLEANING_SKILL),
    "ba:businesstype_cinema": (
        "ba:skill_projectionist", "ba:skill_customerservice", CLEANING_SKILL),
    "ba:businesstype_theater": (
        "ba:skill_actor", "ba:skill_stagecrew", "ba:skill_customerservice", CLEANING_SKILL),
    "ba:businesstype_eventplanningagency": ("ba:skill_eventplanner", CLEANING_SKILL),
    "ba:businesstype_graphicdesigner": ("ba:skill_graphicdesigner", CLEANING_SKILL),
    "ba:businesstype_lawfirm": ("ba:skill_lawyer", CLEANING_SKILL),
    "ba:businesstype_travelagency": ("ba:skill_travelagent", CLEANING_SKILL),
    "ba:businesstype_webdevelopmentagency": ("ba:skill_programmer", CLEANING_SKILL),
    "ba:businesstype_headquarters": (
        "ba:skill_purchasingagent", "ba:skill_logisticsmanager", "ba:skill_hrmanager",
        "ba:skill_headhunter", "ba:skill_pricingmanager", CLEANING_SKILL),
    "ba:businesstype_warehouse": ("ba:skill_deliverydriver",),
    "ba:businesstype_factory": ("ba:skill_deliverydriver", "ba:skill_factoryworker"),
}
FACTORY_TYPES = COST_CENTRE_TYPES - OVERHEAD_TYPES

# Peter's office default (25 Sep 2026; docs/dashboard-reference.md): "computers
# staffed 24/7 = 3 in a 50-capacity building, proportionally fewer in smaller
# ones (at least 1); every computer 8 to 22 on weekdays; half the computers 8 to
# 22 on weekends." For every office: round(3 x door / 50) computers, at least 1
# and at most all of them, are staffed around the clock every day; on weekdays
# every computer is also staffed OFFICE_DAY; on weekends ceil(C / 2) computers
# are, the always-on ones counting among them. The door is the building's
# customerCapacity, the office grid's `door`.
OFFICE_ALWAYS_ON = 3  # computers around the clock ...
OFFICE_FULL_DOOR = 50  # ... in a building of this capacity
OFFICE_DAY = (8, 22)
OFFICE_WEEKEND = (6, 0)  # Saturday and Sunday, as day % 7


def _office_always_on(computers: int, door: int) -> int:
    """How many computers the office default staffs around the clock."""
    wanted = math.floor(OFFICE_ALWAYS_ON * (door or 0) / OFFICE_FULL_DOOR + 0.5)
    return min(computers, max(1, wanted))


def _office_runs(computers: int, open_hours: list, door: int) -> tuple:
    """Which hours each computer is staffed by the office default.

    Returns ({station index: [hours per weekday]}, always-on count). Computers
    are staffed in station order, so the first ones are the always-on ones.

    An hour the office is shut in the save is left out: nobody works a closed
    office, and the write does not change opening hours. So an office open 9
    to 17 gets every computer 9 to 17 on weekdays and its always-on computers
    only 9 to 17 as well, and a day it is shut gets nobody. A save that holds
    no opening hours at all for the office is not clipped.
    """
    if not computers:
        return {}, 0
    always = _office_always_on(computers, door)
    opened = [
        {hour for start, end in open_hours[wd] for hour in range(max(0, start), min(24, end))}
        for wd in range(7)
    ]
    if not any(opened):
        opened = [set(range(24)) for _ in range(7)]
    day = set(range(*OFFICE_DAY))
    weekend = math.ceil(computers / 2)
    runs = {}
    for index in range(computers):
        week = []
        for wd in range(7):
            hours = set()
            if index < always:
                hours = set(range(24))
            elif wd not in OFFICE_WEEKEND or index < weekend:
                hours = set(day)
            week.append(hours & opened[wd])
        if any(week):
            runs[index] = week
    return runs, always


def _office_staffing(save: Save, names, businesses: list, grids: list, staff: list,
                     world: dict | None = None) -> list:
    """A week for every office by Peter's office default, one row per office.

    The shop placer (_place_week) over a synthetic grid, as a factory's is: one
    role, the office's professional skill (its type's first accepted skill),
    one station per computer, the hours _office_runs() gives each. The pool is
    the office's own staff with that skill, then the unassigned people no
    shop's plan counts on (`world`'s bench, which _staffing() has already
    taken its own off), handed out in office order the way _staffing() hands
    out the bench. An office the placer falls over on is one `failed` row.

    The row has the shop row's fields a write reads (`stations`, `people`,
    `shifts`, `current`, `roles`, `open`, `openAllHours` false) and its plan
    fields (`need`, `headcount`, `addPeople`, `shortHours`, ...), plus
    `alwaysOn`, `computers` and `staffedComputers`.
    """
    by_key = {b["key"]: b for b in businesses}
    buildings = {
        site_key(_address_of(b)): b
        for b in save.items(save.root.get("BuildingRegistrations"))
        if b.get("RentedByPlayer")
    }
    world = world or _plan_world(save, staff)
    people, state = world["people"], world["state"]
    bench = list(world["bench"])
    offices = sorted(
        (
            (by_key[g["key"]], buildings[g["key"]], g)
            for g in grids
            if g["key"] in by_key and g["key"] in buildings
            and by_key[g["key"]]["status"] == "office"
        ),
        key=lambda row: (row[0]["name"] or "", row[0]["key"]),
    )
    out = []
    for business, building, grid in offices:
        skill = next(iter(ASSIGN_SKILLS.get(business["typeSlug"], ())), None)
        if not skill or not grid["stations"]:
            continue
        pool = [p for p in _site_pool(people, business, bench) if _usable(p, skill, "serve")]
        scratch = {p["id"]: _copy_state(state[p["id"]]) for p in pool}
        try:
            row, took = _office_site_plan(save, names, business, building, grid, skill,
                                          pool, people, bench, scratch)
        except Exception:
            out.append({"key": business["key"], "name": business["name"],
                        "typeSlug": business["typeSlug"], "failed": True})
            continue
        state.update(scratch)
        taken = {p["id"] for p in took}
        bench = [p for p in bench if p["id"] not in taken]
        out.append(row)
    world["bench"] = bench
    return out


def _unrepresentable(save: Save, building: dict) -> int:
    """How many of a building's shifts _current_roster() cannot list as they are."""
    bad = 0
    for scheduled in save.items(building.get("scheduleDays")):
        for shift in save.items(scheduled.get("workShifts")):
            start, end = shift.get("startingHour"), shift.get("endingHour")
            if not isinstance(start, int) or not isinstance(end, int) or not 0 <= start < end <= 24:
                bad += 1
    return bad


def _office_site_plan(save, names, business, building, grid, skill, pool, people, bench,
                      state) -> tuple:
    """One office's row of _office_staffing(), and who it drew off the bench."""
    label = names.label(skill) if names else skill
    stations = [
        {"id": s["id"], "slug": s["slug"], "name": s["name"], "skill": skill,
         "rate": OFFICE_POST_RATE}
        for s in grid["stations"]
    ]
    runs, always = _office_runs(len(stations), grid["open"], grid["door"])
    slots_open = grid["open"] if any(grid["open"]) else ALL_DAY_OPEN
    need = {skill: {
        "need": [[sum(1 for days in runs.values() if hour in days[wd]) for hour in range(24)]
                 for wd in range(7)],
        "basis": [["office"] * 24 for _ in range(7)],
        "stations": runs,
    }}
    fake = {"roles": [{"skill": skill, "label": label}], "stations": stations}
    usable_bench = [p for p in bench if _usable(p, skill, "serve")]
    current = _current_roster(save, building, {s["id"]: s for s in stations})
    week = _place_week(fake, need, slots_open, [], pool, people, business, usable_bench,
                       state, groups=_station_groups(save, building), current=current["list"])
    bad = _unrepresentable(save, building)
    lists = (week["shifts"], week["shortHours"], week["shortDays"], week["placed"],
             week["bench"])
    table = _index_table(stations, (week["shifts"], current["list"]),
                         (current["list"],) + lists, people)
    wage_of = {
        pid: person["wage"] for pid, person in people.items()
        if person["addr"] and site_key(person["addr"]) == business["key"]
    }
    cost = {"current": money(_current_cost(current, wage_of)), "currentCover": 0.0}
    fields = _plan_fields(week, table, names, people, cost)
    fields.pop("basis", None)
    row = {
        "key": business["key"],
        "name": business["name"],
        "typeSlug": business["typeSlug"],
        "skill": skill,
        "label": label,
        # Computers staffed around the clock by the office default.
        "alwaysOn": always,
        # Shifts in the game's week _current_roster() drops or clamps (no
        # hours, reversed, outside 0-24): the page cannot send them back as
        # they are, so an office write, which keeps every entry, is refused.
        **({"unrepresentable": bad} if bad else {}),
        "computers": len(stations),
        "staffedComputers": len(runs),
        # The hours the plan staffs against: the office's own (around the
        # clock where the save holds none). The write never changes them
        # (`openAllHours` false).
        "open": slots_open,
        "openAllHours": False,
        "stations": table["stations"],
        "people": table["people"],
        "roles": [{"skill": skill, "label": label,
                   "stations": [table["station"][s["id"]] for s in stations]}],
        **fields,
        "current": {
            "shifts": current["shifts"],
            "fragments": current["fragments"],
            "list": [_shift_row(r, table) for r in current["list"]],
        },
    }
    return row, week["took"]


def _business_kind(business: dict) -> str | None:
    """The Staff page's kind of site, or None for one it has nothing to say about."""
    slug = business.get("typeSlug")
    if business.get("status") == "vacant" or slug == EMPTY_TYPE:
        return None
    if business.get("status") == "retail":
        return "shop"
    if business.get("status") == "office":
        return "office"
    if slug in FACTORY_TYPES:
        return "factory"
    if slug == "ba:businesstype_headquarters":
        return "hq"
    if slug in OVERHEAD_TYPES:
        return "warehouse"
    return None


# How the Staff page judges each kind of demand a candidate holds: `schedule`
# against the hire week the person gets, `station` against the stations that
# week puts them on (the site's `stations`), `site` against the site's facts,
# `company` once for everybody.
DEMAND_SCOPE = {
    "hours": "schedule", "days": "schedule", "daysoff": "schedule", "noshift": "schedule",
    "nocleaning": "schedule",
    "desk": "station", "building": "site", "clean": "site",
    "insurance": "company", "happiness": "company",
}


def _station_groups(save: Save, registration: dict) -> dict:
    """Each item's furniture group: {item id: {item names}}.

    The game's assignedWorkStationItems, which a desk or chair demand reads
    (WorksOnItem), is every item of the group each station a person has a
    shift on stands in: follow `parentId` up to the root item, usually the
    desk, and take it and everything stacked on it (computer, chair, monitor,
    mousepad, phone). Rebuilt this way from the schedule it matched the saved
    list for every employee of three offices on two saves (26 September 2026).
    """
    items = []
    for item in _item_instances(save, registration.get("itemInstances")):
        if item.get("id") is not None:
            items.append(item)
    by_id = {item["id"]: item for item in items}
    kids = collections.defaultdict(list)
    for item in items:
        if item.get("parentId") in by_id:
            kids[item["parentId"]].append(item)

    def root(item):
        seen = set()
        while item.get("parentId") in by_id and item["id"] not in seen:
            seen.add(item["id"])
            item = by_id[item["parentId"]]
        return item

    def names(item, seen):
        if item["id"] in seen:
            return set()
        seen.add(item["id"])
        out = {item.get("itemName")} - {None}
        for kid in kids[item["id"]]:
            out |= names(kid, seen)
        return out

    groups = {}
    out = {}
    for item in items:
        top = root(item)
        if top["id"] not in groups:
            groups[top["id"]] = names(top, set())
        out[item["id"]] = groups[top["id"]]
    return out


# The fewest station-hours a week the Staff page names as a site's own staff
# with no hours: less is a shift the player moved, not a week left empty.
UNSTAFFED_MIN_HOURS = 8


def _unstaffed_now(row: dict) -> tuple:
    """What _unstaffed() reads off a row's own week, the game's: (role of a
    station, staffed now per role/day/hour, the people with hours at the site)."""
    stations, people = row.get("stations") or [], row.get("people") or []
    person = lambda p: people[p]["id"] if p is not None and 0 <= p < len(people) else None  # noqa: E731
    role_of = {}
    for entry in row.get("roles") or ():
        for index in entry.get("stations") or ():
            role_of[index] = entry.get("key", entry.get("skill"))
    skill_of = lambda s: stations[s].get("skill") if s is not None and 0 <= s < len(stations) else None  # noqa: E731
    skill = lambda s: role_of.get(s, skill_of(s))  # noqa: E731
    now = collections.Counter()
    working = set()
    for entry in (row.get("current") or {}).get("list") or ():
        role, day = skill(entry.get("s")), entry.get("d")
        for hour in range(entry.get("f", 0), entry.get("t", 0)):
            now[(role, day, hour)] += 1
        if person(entry.get("p")) and entry.get("t", 0) > entry.get("f", 0):
            working.add(person(entry.get("p")))
    return skill, now, working


def _unstaffed(row: dict, shifts, own: set, training=frozenset(), read=None) -> dict | None:
    """The plan's hours the site's own people would work that nobody works in
    the game's week now, when there are UNSTAFFED_MIN_HOURS or more.

    Peter's live game (26 September 2026): a liquor store with its four
    cashiers still assigned but their hours taken off in BizMan. The plan
    fills the register with those four and hires nobody, so the Staff page
    said nothing. `shifts` is the plan's (the row's index tables), `row`
    carries the game's week as `current.list`.

    Counted per role, weekday and hour: the site's own people the plan puts
    on the role then, less everybody on the role's stations in the game's
    week then, never below none -- so somebody on register 2 where the plan
    uses register 1 is not a gap. A role is the row's own (`roles[].key`):
    a hairdresser's head wash and its chairs share the Hair Stylist skill,
    and busy chairs must not hide an empty head wash. Only hours a planned
    shift gives the site's own people count, so a hire's week is never
    counted here as well. Only roles where some of them (`idle`) have no
    hours at the site at all in the game's week, and nobody in training: a
    plan that merely differs from the week is the site page's to show.
    Returns {hours, roles: [{skill, hours, idle}]}, one entry a skill, or
    None. `read` is _unstaffed_now() of the row, where the caller has it.
    """
    stations, people = row.get("stations") or [], row.get("people") or []
    person = lambda p: people[p]["id"] if p is not None and 0 <= p < len(people) else None  # noqa: E731
    skill, now, working = read or _unstaffed_now(row)
    # The skill each role is worked in, which is what the page names.
    named = {}
    for index, station in enumerate(stations):
        named.setdefault(skill(index), station.get("skill"))
    want = collections.Counter()
    cells = collections.defaultdict(set)  # (role, person): their planned hours
    for entry in shifts:
        pid = person(entry.get("p"))
        if pid is None or pid not in own:
            continue
        role, day = skill(entry.get("s")), entry.get("d")
        mine = cells[(role, pid)]
        for hour in range(entry.get("f", 0), entry.get("t", 0)):
            want[(role, day, hour)] += 1
            mine.add((day, hour))
    gap = collections.Counter()
    for (role, day, hour), n in want.items():
        gap[role] += max(0, n - now[(role, day, hour)])
    # Idle: nothing at the site in the game's week, not in training, and some
    # of their own planned hours left with nobody on.
    idle = collections.defaultdict(set)
    for (role, pid), hours in cells.items():
        if pid not in working and pid not in training \
                and any(want[(role, d, h)] > now[(role, d, h)] for d, h in hours):
            idle[role].add(pid)
    # Judged per role, told per skill: the head wash's hours and the chairs'
    # are one Hair Stylist line, and somebody idle in both is one person.
    hours_of, idle_of = collections.Counter(), collections.defaultdict(set)
    for role in gap:
        if gap[role] and idle[role]:
            hours_of[named.get(role, role)] += gap[role]
            idle_of[named.get(role, role)] |= idle[role]
    roles = [
        {"skill": name, "hours": hours_of[name], "idle": len(idle_of[name])}
        for name in _in_order(hours_of)
    ]
    total = sum(r["hours"] for r in roles)
    if total < UNSTAFFED_MIN_HOURS:
        return None
    return {"hours": total, "roles": roles}


def _station_roots(save: Save, registration: dict) -> list:
    """The root item of every furniture group of a site (a desk, a table).

    For a site with no plan (headquarters, warehouse), whose people are placed
    by the player: the desk demands its desks meet, one entry per group.
    """
    items = []
    for item in _item_instances(save, registration.get("itemInstances")):
        if item.get("id") is not None:
            items.append(item)
    ids = {item["id"] for item in items}
    return [item["id"] for item in items if item.get("parentId") not in ids]


def _station_facts(save: Save, registration: dict, stations) -> dict:
    """The desk and chair demands each of a site's stations meets.

    {station id: [demand slugs]}, the stations with none left out. A person
    meets such a demand when a station they work stands in a group holding one
    of its items (_station_groups()), which is the game's own test.
    """
    groups = _station_groups(save, registration)
    desk = [(slug, setting) for slug, (kind, setting, _p) in sorted(JOB_DEMANDS.items())
            if kind == "desk"]
    out = {}
    for sid in sorted({s for s in stations if s is not None}, key=str):
        held = groups.get(sid, set())
        met = [slug for slug, setting in desk
               if any("ba:itemname_" + name in held for name in setting)]
        if met:
            out[str(sid)] = met
    return out


def _site_facts(save: Save, registration: dict) -> dict:
    """Whether a site meets each site-level demand, as _job_demands() judges it.

    A desk or chair demand is not one of them: it is about the stations the
    person works (_station_facts()), not whether the site holds such an item
    anywhere, which said met for every lawyer at a firm with one executive
    desk (Peter's in-game test, 25 September 2026).
    """
    here = _items_by_name(save, registration)
    clean = None
    out = {}
    for slug in sorted(JOB_DEMANDS):
        kind, setting, _priority = JOB_DEMANDS[slug]
        if DEMAND_SCOPE.get(kind) != "site":
            continue
        if kind == "clean":
            if clean is None:
                clean = _cleanliness(save, registration)
            out[slug] = clean >= setting
        elif kind == "building":
            out[slug] = _holds_demanded_item(save, here, setting)
    return out


def _company_facts(save: Save) -> dict:
    """Whether the company meets each company-level demand for a new hire.

    Health insurance is a person's own HR manager plan, and a hire joins none
    (54 of Peter's test hires had no assignedHrManagerPlanId): `"plan"` where
    some HR manager's plan, its manager in place (not being replaced), offers
    that tier or better, so the player has one to add them to; False where none
    does. A happy boss: the player's happiness, True or False.
    """
    root = save.root
    by_id = {e.get("id"): e for e in save.items(root.get("EmployeeInstances"))}
    best = -1
    for plan in save.items(root.get("hrManagerPlans")):
        cover = save.deref(plan.get("healthInsurancePlan")) or {}
        manager = by_id.get(plan.get("assignedEmployeeId")) or {}
        if cover and manager and not manager.get("isBeingReplaced"):
            best = max(best, cover.get("planType") or 0)
    happiness = root.get("Happiness") or 0
    out = {}
    for slug in sorted(JOB_DEMANDS):
        kind, setting, _priority = JOB_DEMANDS[slug]
        if kind == "insurance":
            out[slug] = "plan" if best >= setting else False
        elif kind == "happiness":
            out[slug] = happiness >= setting
    return out


def _hiring(save: Save, businesses: list, staffing: list, factory_staffing: dict,
            office_staffing: list) -> dict:
    """The Staff page's payload key `hiring` (docs/architecture.md, the payload contract).

    Takes each plan row's `_hire` off it. One site per business the player runs,
    in the `businesses` order; `people` describes everybody a site's `spare` or
    `bench`, or the top-level `bench`, names, so the page can place them, and
    whether each is in training (`training`), whom the page never moves.
    """
    regs = {
        site_key(_address_of(b)): b
        for b in save.items(save.root.get("BuildingRegistrations"))
        if b.get("RentedByPlayer")
    }
    shops = {row["key"]: row for row in staffing}
    factories = collections.defaultdict(dict)
    for mode in SIZING_MODES:
        for row in factory_staffing.get(mode, []):
            factories[row["key"]][mode] = row
    offices = {row["key"]: row for row in office_staffing}

    def take(row):
        return (row or {}).pop("_hire", None)

    def rows_of(kind, key):
        """The plan rows of one site, whose stations the page may place people on."""
        if kind == "shop":
            return [shops.get(key)]
        if kind == "factory":
            return list(factories.get(key, {}).values())
        if kind == "office":
            return [offices.get(key)]
        return []

    # Each site's own people: whom a plan's shifts there may already count on.
    own = collections.defaultdict(set)
    training = set()
    for employee in save.items(save.root.get("EmployeeInstances")):
        addr = save.address(employee.get("assignedAddress")) if isinstance(employee, dict) else None
        if addr:
            own[site_key(addr)].add(employee.get("id"))
        if isinstance(employee, dict) and save.deref(employee.get("trainingSession")):
            training.add(employee.get("id"))
    sites = []
    for business in businesses:
        kind = _business_kind(business)
        reg = regs.get(business["key"])
        if kind is None or reg is None:
            continue
        plans = {}
        no_hours = False
        if kind == "shop":
            row = shops.get(business["key"])
            demand = take(row)
            full = take((row or {}).get("fullCover"))
            opened = take((row or {}).get("openCover"))
            if row and not row.get("failed") and demand is not None:
                # Peter (26 September 2026): "Staff the hours it's open, never
                # change opening." The Staff page never uses full cover, whose
                # write opens a shop 0 to 24: it has the open-hours plan
                # (`open`, _open_need()) instead. Without complete data that
                # plan replaces the demand plan, whose unread open hours had
                # nobody on the stations (Evil Genius); with it, the page
                # takes `open` only where the player runs full cover. A shop
                # the game opens no hour has no plan until it has hours.
                if not any(row.get("open") or ()):
                    no_hours = True
                elif opened is not None and not (row.get("openCover") or {}).get("complete"):
                    plans["open"] = opened
                else:
                    plans["demand"] = demand
                    if opened is not None:
                        plans["open"] = opened
            # Full cover (24/7), for a shop whose Staffing block the player
            # put on it (29 September 2026): the page hires into it and its
            # write opens the shop 0 to 24 there, and nowhere else.
            if row and not row.get("failed") and full is not None:
                plans["full"] = full
        elif kind == "factory":
            for mode, row in factories.get(business["key"], {}).items():
                found = take(row)
                if found is not None:
                    plans[mode] = found
        elif kind == "office":
            found = take(offices.get(business["key"]))
            if found is not None:
                plans["office"] = found
        # Staff with no hours (_unstaffed()): the hours a site's own people
        # would work that nobody works in the game's week now, against every
        # plan a shop's Staffing block may write -- the demand plan, full
        # cover, and the open-hours plan it writes for a new shop or one
        # without complete data -- which the page picks between as that block
        # does (spPlanOf()); an office's office default.
        unstaffed = {}
        base = shops.get(business["key"]) if kind == "shop" else offices.get(business["key"]) if kind == "office" else None
        if base and not base.get("failed"):
            pairs = (("demand", base.get("shifts")), ("full", (base.get("fullCover") or {}).get("shifts")),
                     ("open", (base.get("openCover") or {}).get("shifts"))) \
                if kind == "shop" else (("office", base.get("shifts")),)
            # The game's week is read once a site, and two plans with the same
            # rows (a shop's full cover and its open-hours plan, on a shop
            # open around the clock) have the same answer.
            done, now = [], _unstaffed_now(base)
            for mode, shifts in pairs:
                shifts = shifts or ()
                gap = next((copy.deepcopy(found) for other, found in done if other == shifts),
                           False)
                if gap is False:
                    gap = _unstaffed(base, shifts, own.get(business["key"], set()), training,
                                     now)
                done.append((shifts, gap))
                if gap:
                    unstaffed[mode] = gap
        sites.append({
            "key": business["key"],
            "name": business["name"],
            "kind": kind,
            "address": {"street": reg.get("StreetName"), "number": reg.get("StreetNumber")},
            "planned": kind in ("shop", "office", "factory"),
            # A shop the game opens no hour: no plan until it has hours.
            **({"noHours": True} if no_hours else {}),
            **({"unstaffed": unstaffed} if unstaffed else {}),
            "new": not business.get("staff"),
            "accepts": list(ASSIGN_SKILLS.get(business["typeSlug"], ())),
            "plans": {mode: plans[mode] for mode in _in_order(plans)},
            "facts": _site_facts(save, reg),
            # The desk and chair demands each station of the site meets: the
            # page judges them against the stations a person's week is on.
            "stations": _station_facts(save, reg, [
                station["id"] for row in rows_of(kind, business["key"])
                for station in (row or {}).get("stations") or ()
            ] or _station_roots(save, reg)),
        })
    # Rows of sites the list above skips still lose their private field.
    for row in staffing:
        take(row)
        take(row.get("fullCover"))
        take(row.get("openCover"))
    for rows in factories.values():
        for row in rows.values():
            take(row)
    for row in office_staffing:
        take(row)

    employees = [e for e in save.items(save.root.get("EmployeeInstances")) if isinstance(e, dict)]
    bench = _in_order({
        e.get("id") for e in employees if not save.address(e.get("assignedAddress"))
    })
    named = set(bench)
    for site in sites:
        for plan in site["plans"].values():
            named.update(plan["spare"])
            named.update(plan["bench"])
    people = {}
    for e in employees:
        if e.get("id") not in named:
            continue
        char = _character(save, e)
        addr = save.address(e.get("assignedAddress"))
        people[e.get("id")] = {
            "name": char["name"],
            "skills": _skill_rows(char),
            "wage": money(e.get("hourlyWage") or 0),
            "site": site_key(addr) if addr else None,
            "hours": e.get("assignedWeeklyHours") or 0,
            "demands": _in_order(
                {d for d in save.items(e.get("demands")) if isinstance(d, str)}),
            # In training (the game's IsTraining: trainingSession set). The
            # game's move turns them away, so the page moves nobody in training
            # and leaves them out of the bench a plan counts on.
            "training": bool(save.deref(e.get("trainingSession"))),
        }
    return {
        "sites": sites,
        "bench": bench,
        "people": {pid: people[pid] for pid in _in_order(people)},
        "demandKinds": {
            slug: DEMAND_SCOPE[JOB_DEMANDS[slug][0]]
            for slug in sorted(JOB_DEMANDS)
            if JOB_DEMANDS[slug][0] in DEMAND_SCOPE
        },
        "company": _company_facts(save),
        "recruiting": _recruiting(save),
    }


def _recruiting(save: Save) -> dict:
    """How many of the company's headhunters are recruiting each skill now.

    {skill: headhunters}, from headhunterPlans: a plan with somebody assigned
    and isRecruiting set, by its skillRecruiting. The Staff page says where to
    find people for a role its candidates cannot fill (Where to find them).
    """
    out = collections.Counter()
    for plan in save.items(save.root.get("headhunterPlans")):
        if isinstance(plan, dict) and plan.get("assignedEmployeeId") and plan.get("isRecruiting") \
                and isinstance(plan.get("skillRecruiting"), str):
            out[plan["skillRecruiting"]] += 1
    return {skill: out[skill] for skill in sorted(out)}


def _lower_first(text: str) -> str:
    """A game label dropped into the middle of a sentence, DJ and all."""
    return " ".join(
        word if word.isupper() and len(word) > 1 else word.lower()
        for word in text.split(" ")
    )


def _role_words(role: dict, office: bool) -> dict:
    """What a finding about one of a site's roles calls its limit and its answer.

    A register asks for another counter and a computer for another workstation;
    a gym's board and a theatre's booth are neither, so those findings name the
    role and the piece of furniture it works. `noun` is the plural the alert
    lines use, and None where the words the board has always used still fit.
    """
    if office:
        return {
            "noun": None,
            "staffing": (msg("sp.py.limit.staffing", "staffing"),
                         msg("sp.py.fix.office.staff", "more staff at the computers on those hours")),
            "posts": (msg("sp.py.workstations", "workstations"),
                      msg("sp.py.fix.office.post", "another computer workstation")),
        }
    if role["skill"] == SERVICE_SKILL:
        return {
            "noun": None,
            "staffing": (msg("sp.py.limit.staffing", "staffing"),
                         msg("sp.py.fix.service.staff", "more service staff on those hours")),
            "posts": (msg("sp.py.limit.registers", "registers"), msg("sp.py.fix.service.post", "another counter")),
        }
    station = _lower_first(role["station"])
    role_name = tok(role["skill"], role["label"])
    # The station's own words are the game's name, lowered and pluralised in
    # English, and stay English: a token cannot be declined or pluralised. So
    # every message holding them also carries the name as a token,
    # `station_name`, for a translation to write instead.
    station_name = tok(role.get("stationKey"), role["station"])
    if role.get("shared"):
        # One of two roles of one skill (_hourly()): the skill alone would name
        # both, so the station says which queue is short of people.
        staffing = (
            msg("sp.py.limit.station.staff", "{station} staffing",
                station=station, station_name=station_name),
            msg("sp.py.fix.station.staff", "another {role} at the {station}",
                role=role_name, station=station, station_name=station_name),
        )
    else:
        staffing = (
            msg("sp.py.limit.role", "{role} staffing", role=role_name),
            msg("sp.py.fix.role.staff", "another {role} on those hours", role=role_name),
        )
    return {
        "noun": _plural(station),
        "stationName": station_name,
        # Two different answers, two different limits, the way a shop's
        # "staffing" and "registers" are two: one line is about people, the
        # other about posts. The posts limit names the station itself, so two
        # shops short of two different stations of one role never collide --
        # the id hashes the limit, and nothing but the limit.
        "staffing": staffing,
        "posts": (msg("sp.py.limit.station", "{stations}", stations=_plural(station), station_name=station_name),
                  msg("sp.py.fix.role.post", "another {station}", station=station, station_name=station_name)),
    }


KIND_ORDER = {"the building": 0, "staffing": 1, "registers": 2}


def _limit_order(limit: tuple) -> tuple:
    """Sort key for one ``(kind, skill)`` limit: people before posts, then the
    skill, with the skill-less office role last, the way _in_order() sorts."""
    kind, skill = limit
    return (KIND_ORDER[kind], skill is None, str(skill))


def _hour_findings(grids: list, businesses: list, wages: dict) -> list:
    """The two things an hourly grid can tell you that a daily total cannot.

    Each role is judged on the roster that was on for it, so a gym short of
    trainers and a cinema short of projectionists get the line that fits them,
    while a shop's counters and an office's workstations keep the words they
    have always had. Wages arrive per role, as ``{site key: {skill: wage}}``.
    """
    by_key = {b["key"]: b for b in businesses}
    out = []
    for grid in grids:
        business = by_key[grid["key"]]
        basket = grid["basket"] or 0
        door = grid["door"]

        # Each capped hour is held by its own limit: a roster that runs one
        # person at night and a full floor by day is short of staff at night and
        # up against the door by day, and a verdict for the week as a whole
        # would be wrong about one of them. A site asking for more than one
        # skill serves nobody until every role is manned, but only a role
        # holding the site's own minimum that hour is holding it back: hiring
        # into a role that is already faster than the slowest one buys nothing.
        # An hour is filed under everything holding it at once, so the trade
        # through it is priced once however many roles are tied on it.
        office = grid.get("office", False)
        # Keyed by role, so a hairdresser's chairs and head wash stay apart:
        # both short of Hair Stylists on one hour is two people to hire, not one.
        roles = {_role_key(role): role for role in grid["roles"]}
        by_limit = collections.defaultdict(lambda: collections.defaultdict(set))
        for wd, hour in sorted(_capped_cells(grid)):
            if door and door <= grid["staffed"][wd][hour]:
                by_limit[(("the building", None),)][wd].add(hour)
                continue
            site_staffed = grid["staffed"][wd][hour]
            # A role holding the minimum is short of people where it has
            # stations standing empty, and short of stations where every one of
            # them is manned. Both can be true of one hour at one site, and then
            # the hour carries both answers on one line: a gym with a spare
            # board and a single manned register is fixed by neither alone, so
            # neither alone is worth the money going through that hour.
            here = tuple(sorted(
                (
                    (
                        "staffing"
                        if r["staffed"][wd][hour] < r["counters"]
                        else "registers",
                        _role_key(r),
                    )
                    for r in roles.values()
                    if r["staffed"][wd][hour] == site_staffed
                ),
                key=_limit_order,
            ))
            # The site's capacity is the minimum across its roles, so some role
            # always stands at it and a capped hour always has one. The guard is
            # defensive: a grid with no roles at all is never capped either.
            if here:
                by_limit[here][wd].add(hour)

        for limits in sorted(
            by_limit, key=lambda ks: tuple(_limit_order(k) for k in ks)
        ):
            capped = {wd: sorted(hours) for wd, hours in by_limit[limits].items()}
            cells = [(wd, h) for wd in sorted(capped) for h in capped[wd]]
            ceilings = [grid["effective"][wd][h] for wd, h in cells]
            finding = {
                "kind": "cap",
                "key": grid["key"],
                "site": grid["name"],
                "office": office,
                "hours": len(cells),
                "when": _hour_phrase(capped),
                "cap": min(ceilings),
                "capTop": max(ceilings),
                "basket": basket,
                # What is measurably flowing through the ceiling, hour by
                # hour. What is being turned away above it is not in the
                # save at all.
                "throughput": money(
                    sum(grid["customers"][wd][h] for wd, h in cells) * basket / 7
                ),
            }
            # What held those hours, as data: the page lights the grid's cells
            # and draws the chip's icons by it, never by the words. ["door"]
            # for the building, else a ["staff" or "post", role key] per role.
            finding["heldBy"] = [
                ["door"] if kind == "the building"
                else ["staff" if kind == "staffing" else "post", skill]
                for kind, skill in limits
            ]
            if limits[0][0] == "the building":
                # The building's capacity comes with the lease, and the board
                # has no advice for it: the finding names the ceiling and what
                # goes through it, and no fix. _alerts() raises no line for it;
                # it shows on the site page's hour grid and chip only.
                finding["limit"] = msg("sp.py.limit.building", "the building")
                finding["fix"] = ""
            else:
                # One role reads exactly as it always has, which is what keeps
                # a shop's and an office's alert ids. Roles tied on the same
                # hours are joined, in the order they were sorted into, so the
                # words and the id do not move between runs.
                said = [
                    (
                        _role_words(roles[skill], office),
                        "staffing" if kind == "staffing" else "posts",
                    )
                    for kind, skill in limits
                ]
                finding["limit"] = _sp_list([w[part][0] for w, part in said], " and ")
                finding["fix"] = _sp_list([w[part][1] for w, part in said], " and ")
                finding["limits"] = len(said)
                finding["noun"] = (
                    _sp_station_noun(said[0][0])
                    if len(said) == 1
                    else _sp_list([_sp_station_noun(w) or _sp_counters(office) for w, _ in said], " and ")
                )
            out.append(finding)

        # Overstaffing is a property of the roster that was on, so each role is
        # read on its own: a gym's spare trainer-hours are real even on an hour
        # when the site was held up by another role. Only a role with a known
        # wage can be priced, so only its runs are counted: the best of those
        # across roles and weekdays leads, first past the post on a tie, and a
        # worse run of a priced role is not lost behind a bigger one nobody can
        # put a wage on. Every priced run is kept beside it in `runs`, so the
        # site's one Today line and its page's hours block both price and name
        # the whole week rather than its worst day.
        wages_here = wages.get(grid["key"], {})
        best = None
        runs_here = []
        for role in grid["roles"]:
            for wd in range(7):
                if grid["thin"][wd]:
                    continue
                run = []
                for hour in range(25):
                    seen = grid["customers"][wd][hour] if hour < 24 else None
                    on = role["onShift"][wd][hour] if hour < 24 else 0
                    cap = role["staffed"][wd][hour] if hour < 24 else 0
                    slack = (
                        seen is not None
                        and on >= IDLE_STAFF
                        and cap > max(seen, 0.5) * IDLE_RATIO
                    )
                    if slack:
                        per_post = cap / on if on else 0
                        needed = max(1, math.ceil(seen / per_post)) if per_post else 1
                        run.append((hour, on - needed, seen, on))
                        continue
                    role_wage = wages_here.get(role["skill"])
                    # The whole unbroken run is what qualifies, however many
                    # were on in it; it is then told in pieces of one headcount
                    # each, so two people 8-12 and four 12-20 never read as
                    # four all day. The pieces add up to the run.
                    if len(run) >= IDLE_RUN and role_wage:
                        for _, piece in itertools.groupby(run, key=lambda r: r[3]):
                            piece = list(piece)
                            spare = sum(r[1] for r in piece)
                            runs_here.append(
                                {
                                    "noun": _sp_station_noun(_role_words(role, office)),
                                    "wd": wd,
                                    "hours": [r[0] for r in piece],
                                    "staff": piece[0][3],
                                    "seen": [r[2] for r in piece],
                                    "spare": spare,
                                    "worth": spare * role_wage / 7,
                                }
                            )
                            if not best or spare > best["spare"]:
                                best = {
                                    "wd": wd,
                                    "from": piece[0][0],
                                    "to": piece[-1][0] + 1,
                                    "spare": spare,
                                    "staff": piece[0][3],
                                    "seen": round(sum(r[2] for r in piece) / len(piece)),
                                    "role": role,
                                    "wage": role_wage,
                                }
                    run = []
        if best:
            wage = best["wage"]
            out.append(
                {
                    "kind": "idle",
                    "key": grid["key"],
                    "site": grid["name"],
                    "office": office,
                    "noun": _sp_station_noun(_role_words(best["role"], office)),
                    "day": WEEKDAYS[best["wd"]],
                    "from": best["from"],
                    "to": best["to"],
                    "staff": best["staff"],
                    "seen": best["seen"],
                    "spare": best["spare"],
                    "worth": money(best["spare"] * wage / 7),
                    "week": _idle_week(runs_here),
                }
            )
    return out


def _idle_week(runs: list) -> dict:
    """Every overstaffed run at one site, as the one line Today gives it.

    A site that runs spare counters all Tuesday usually runs them all Wednesday
    too; one cause is one line, so the runs are summed into a week and each
    role's hours are named as a shape ("Tue, Wed 0-24"). Each run comes in with
    one headcount for all its hours (_hour_findings() splits an unbroken run
    where the number on changes), and a part is one role at one headcount: 2 on
    Monday and 4 on Tuesday, or 2 from 8 and 4 from 12, are two parts, so no
    hour is said to have run more people than it did. A part's own day shapes
    are joined with " and ", since the parts are kept apart by "; ". Each part
    carries its spare staff-hours, so the line can name the biggest. `seen` is the
    customers an hour over every hour named, each hour counted once however
    many roles were idle in it. `cells` is every weekday-hour named, as
    [weekday, hour] pairs, so the site page lights the hours the line names.
    """
    parts = collections.OrderedDict()
    seen = {}
    for run in runs:
        part = parts.setdefault(
            (run["noun"], run["staff"]),
            {"noun": run["noun"], "staff": run["staff"], "spare": 0, "hours": {}},
        )
        part["spare"] += run["spare"]
        part["hours"].setdefault(run["wd"], set()).update(run["hours"])
        for hour, customers in zip(run["hours"], run["seen"]):
            seen[(run["wd"], hour)] = customers
    return {
        "spare": sum(r["spare"] for r in runs),
        "worth": money(sum(r["worth"] for r in runs)),
        "seen": round(sum(seen.values()) / len(seen)) if seen else 0,
        "cells": [list(cell) for cell in sorted(seen)],
        "parts": [
            {"noun": p["noun"], "staff": p["staff"], "spare": p["spare"],
             "when": _hour_phrase(p["hours"], sep=" and ")}
            for p in parts.values()
        ],
    }


IDLE_PARTS = 2  # how many parts of an overstaffed week the line names


def _idle_parts(parts: list, default):
    """The overstaffed week's parts as the line says them: the IDLE_PARTS with
    the most spare staff-hours, in the week's own order, then "(and N more)" --
    in brackets, since "; and 2 more for 10 customers an hour" would read as
    one more part.

    A part's hours can end "and 5 scattered hours" and join day shapes with
    "and", so the parts are kept apart by a semicolon. spIdleWeek() on the
    site page says them the same way. A message (sp.py.idle.*); `default`,
    the noun of a part whose role has none, is best _sp_counters(office), so
    it is a message too."""
    ranked = sorted(range(len(parts)), key=lambda i: (-(parts[i].get("spare") or 0), i))
    named = sorted(ranked[:IDLE_PARTS])
    said = _sp_list([
        msg("sp.py.idle.part", {"one": "{n} {noun} {when}", "other": "{n} {noun} {when}"},
            n=parts[i]["staff"], noun=parts[i]["noun"] or default, when=parts[i]["when"])
        for i in named
    ], "; ")
    more = len(parts) - len(named)
    if more:
        return msg("sp.py.idle.more", {"one": "{parts} (and {n} more)", "other": "{parts} (and {n} more)"},
                   parts=said, n=more)
    return said


# --------------------------------------------------------------------- market
GLOBAL_HOOD = "ba:neighborhood_global"
HYPE_EVENT = 2  # "Citizens in {hood} are showing strong demand for {item}"
SUPPLIER_EVENTS = {
    3: "Product shortage",
    4: "Supplier strain",
    5: "Backorder",
    6: "Supplier strain",
}
HISTORY_DAYS = 60  # how much demand history to keep on disk
TREND_WINDOW = 7  # compare against this many days back when the history reaches it
# The browser's history lives in localStorage (about 5 MB for the site, the
# player's en.json included; a day's demand snapshot is about 22 KB), so it
# keeps two weeks of demand for the characters opened most recently.
BROWSER_HISTORY_DAYS = 14
BROWSER_HISTORY_CHARACTERS = 8


def _market_event_active(event, day):
    start = event.get("startDay") or 0
    return not event.get("stopped") and start <= day < start + (event.get("durationInDays") or 0)


def _wiki_market_prices(save, day):
    """MarketInsider's observed minimum, only where eligibility is reproducible.

    GetLowestMarketPrice includes player shops, all business types, and positive
    prices at named, non-closed businesses in the neighbourhood. Rival shelf
    availability defaults to 1 outside supplier events. Withhold affected items
    rather than guessing event/supplier eligibility or the no-seller fallback.
    Only active type 3/4 events reach the game's shelf-availability checks.
    """
    blocked = {
        e.get("itemName"): "Supply-event pricing unavailable"
        for e in save.items(save.root.get("marketEvents"))
        if e and e.get("itemName") and e.get("type") in (3, 4) and _market_event_active(e, day)
    }
    prices = {}
    buildings = load_buildings()
    for b in save.items(save.root.get("BuildingRegistrations")):
        if not b or b.get("temporarilyClosed") or not b.get("BusinessName"):
            continue
        building = buildings.get(_address_of(b))
        hood = hood_key(building)
        for line in save.items(b.get("retailPrices")):
            if not line or not line.get("itemName"):
                continue
            price = _configured_price(line.get("price"))
            if price is None or line["price"] <= 0:
                continue
            item = line["itemName"]
            if not hood:
                # An unmapped seller could be in any compared neighbourhood.
                blocked[item] = "Seller location unavailable"
                continue
            key = (item, hood)
            prices[key] = min(prices.get(key, price), price)
    return prices, blocked


def _market(
    save: Save, names: Names, businesses: list, day: int, history, character: str
) -> dict:
    """Demand per product per neighbourhood, plus what is moving and why.

    The save stores only today's demand, so a rolling snapshot is kept on disk
    next to the dashboard. Until that fills up, the game's own hype events are
    the trend signal — they are authoritative about what just rose.
    """
    # Shops and offices both sell into a neighbourhood's market: an office's
    # hourly fee has a demand reading there like any product on a shelf.
    trading = [
        b
        for b in businesses
        if b["neighbourhood"] and b["status"] in ("retail", "office")
    ]

    # What we sell, and where. What we make, anywhere.
    sells = collections.defaultdict(set)
    for b in trading:
        for line in b["lines"]:
            if line["price"]:
                sells[line["slug"]].add(b["neighbourhood"])
    makes = set()
    for plan in save.items(save.root["logisticsManagerPlans"]):
        if not plan.get("isFactory"):
            continue
        for dest in save.items(plan["destinations"]):
            for target in save.items(dest["stockTargets"]):
                makes.add(target["itemName"])

    # Active events.
    hype = {}
    starts = {}
    shortages = []
    for event in save.items(save.root["marketEvents"]):
        span = event.get("durationInDays") or 0
        start = event.get("startDay") or 0
        left = start + span - day
        if not _market_event_active(event, day):
            continue
        item = event.get("itemName")
        if event["type"] == HYPE_EVENT and item:
            hood = event.get("neighbourhood") or ""
            hype[(item, hood)] = left
            starts[(item, hood)] = start
        elif event["type"] in SUPPLIER_EVENTS and item:
            shortages.append(
                {
                    "item": names.label(item),
                    "slug": item,
                    "kind": SUPPLIER_EVENTS[event["type"]],
                    "where": names.addr(save.address(event.get("address")))
                    if event.get("address")
                    else names.label(event.get("neighbourhood"), "-"),
                    # The neighbourhood `where` names, by key; None for an address.
                    "hood": None if event.get("address") else event.get("neighbourhood") or None,
                    # The address `where` names, as the map's key; None for a
                    # neighbourhood. The page pins it by this, never by the words.
                    "siteKey": site_key(save.address(event.get("address"))) or None
                    if event.get("address")
                    else None,
                    "daysLeft": left,
                    "mine": item in sells or item in makes,
                }
            )
    shortages.sort(key=lambda s: (not s["mine"], s["daysLeft"]))

    # Today's demand, and the trend against whatever history exists.
    hoods, today_snapshot, rows = [], {}, []
    market_prices, price_gaps = _wiki_market_prices(save, day)
    for entry in save.items(save.root["productMarketEntries"]):
        item = entry["itemName"]
        cells = []
        for value in save.items(entry["demandValues"]):
            if value["neighborhood"] == GLOBAL_HOOD:
                continue
            hood = value["neighborhood"]
            if hood not in hoods:
                hoods.append(hood)
            # The history on disk was keyed by the English name; it stays so.
            today_snapshot[f"{item}|{names.label(hood)}"] = value["demand"]
            market_price = None if item in price_gaps else market_prices.get((item, hood))
            price_note = price_gaps.get(item) or (
                "No eligible seller; game fallback unavailable" if market_price is None else "")
            cells.append(
                {
                    "hood": hood,
                    "demand": value["demand"],
                    "providers": value["providers"],
                    "monopoly": bool(value["hasPlayerMonopoly"]),
                    "sell": hood in sells.get(item, ()),
                    "hype": hype.get((item, hood)),
                    "marketPrice": market_price,
                    **({"marketPriceNote": price_note} if price_note else {}),
                }
            )
        if cells:
            rows.append(
                {
                    "item": names.label(item),
                    "slug": item,
                    "sell": bool(sells.get(item)),
                    "make": item in makes,
                    "cells": cells,
                }
            )

    by_item_hood = {
        (row["slug"], cell["hood"]): cell for row in rows for cell in row["cells"]
    }
    catalogue = _type_catalogue(names, {row["slug"] for row in rows})
    mine_types = {
        b["typeSlug"] for b in businesses if b["status"] in ("retail", "office")
    }

    seen = history.demand(character, day, today_snapshot)
    span = seen["span"]
    for row in rows:
        for cell in row["cells"]:
            was = seen["was"].get(f"{row['slug']}|{names.label(cell['hood'])}")
            cell["delta"] = (cell["demand"] - was) if was is not None else None

    # Columns in the order of their English names, as they always were.
    hoods.sort(key=names.label)
    for row in rows:
        by_hood = {c["hood"]: c for c in row["cells"]}
        row["cells"] = [by_hood.get(h) for h in hoods]
        live = [c for c in row["cells"] if c]
        row["peak"] = max((c["demand"] for c in live), default=0)
        row["rising"] = max((c["delta"] or 0 for c in live), default=0)
        row["hyped"] = any(c["hype"] for c in live)
        open_cells = [c for c in live if not c["sell"]]
        best = max(
            open_cells, key=lambda c: (c["demand"], -c["providers"]), default=None
        )
        row["gap"] = (
            {
                "hood": best["hood"],
                "demand": best["demand"],
                "providers": best["providers"],
            }
            if best
            else None
        )
    # What we touch first, then the loudest demand.
    rows.sort(key=lambda r: (not (r["sell"] or r["make"]), -r["peak"]))

    # Somewhere with real demand and few sellers that we are not in yet.
    gaps = []
    for row in rows:
        for cell in row["cells"]:
            if not cell or cell["sell"] or cell["demand"] < 50:
                continue
            gaps.append(
                {
                    "item": row["item"],
                    "slug": row["slug"],
                    "hood": cell["hood"],
                    "demand": cell["demand"],
                    "providers": cell["providers"],
                    "make": row["make"],
                    "hype": cell["hype"],
                }
            )
    gaps.sort(key=lambda g: (g["providers"], -g["demand"]))

    singles = []
    if span:
        for row in rows:
            for cell in row["cells"]:
                if cell and cell["delta"] and abs(cell["delta"]) >= 5:
                    singles.append(
                        {
                            "item": row["item"],
                            "slug": row["slug"],
                            "hood": cell["hood"],
                            "demand": cell["demand"],
                            "delta": cell["delta"],
                            "sell": cell["sell"],
                        }
                    )
    # One hype wave, or one shop opening, moves a whole family of products in one
    # neighbourhood at once. That is one event, so it gets one line.
    opened_in = collections.defaultdict(list)
    if span:
        for b in trading:
            if day - b["opened"] <= span:
                opened_in[(b["neighbourhood"], b["type"])].append(b)
    movers = _group_movers(
        singles, _family_of(catalogue, names, mine_types), opened_in
    )

    stores = {(b["typeSlug"], b["neighbourhood"]) for b in trading}
    shops = {k: v for k, v in catalogue.items() if k not in OFFICE_TYPES}
    offices = {k: v for k, v in catalogue.items() if k in OFFICE_TYPES}
    # An office fee is served, not made, so its product row has no chain to plan.
    fees = set().union(*offices.values())
    for row in rows:
        row["office"] = row["slug"] in fees
    types = _type_demand(shops, by_item_hood, hoods, names, mine_types, stores)
    # Where the city has no office building at all, the game keeps no reading
    # for a fee either, and the grid can say why the cell is empty.
    office_hoods = {hood_key(r) for r in load_buildings().values() if r.get("t") == "office"}
    return {
        "hoods": hoods,
        "rows": rows,
        # The planner needs the same catalogue, so it travels once and extract
        # moves it across rather than deriving it twice.
        "catalogue": {kind: sorted(items) for kind, items in catalogue.items()},
        # Every type ranks on its average demand, so a one-product type reads
        # that product's own demand and needs no minimum range to be listed.
        "types": types,
        "offices": _office_demand(offices, by_item_hood, hoods, names, mine_types, stores),
        "noOffices": [h for h in hoods if h not in office_hoods] if office_hoods else [],
        "movers": movers,
        "hype": _group_hype(hype, starts, names, sells, makes),
        "shortages": _group_shortages(shortages),
        "gaps": gaps[:20],
        "trendDays": span,
        "trackedDays": seen["days"],
    }


def _family_of(catalogue: dict, names: Names, mine: set) -> dict:
    """Which kind of shop a product belongs to, learned from the city's shops.

    A smartwatch is stocked by jewellers as well as electronics stores. Where we
    run one of the shops that sells it, that is the family it belongs to here —
    otherwise a single wave across one shop's range would still read as several
    unrelated moves. Failing that, the narrowest catalogue wins.
    """
    best = {}
    ordered = sorted(catalogue.items(), key=lambda kv: (kv[0] not in mine, len(kv[1])))
    for kind, items in ordered:
        for item in items:
            best.setdefault(item, names.label(kind))
    return best


def _group_movers(singles: list, family: dict, opened_in: dict) -> list:
    """Group demand moves by neighbourhood and product family."""
    buckets = collections.OrderedDict()
    for row in sorted(singles, key=lambda m: (not m["sell"], -abs(m["delta"]))):
        key = (row["hood"], row["delta"] > 0, family.get(row["slug"], row["item"]))
        bucket = buckets.setdefault(
            key,
            {
                "hood": row["hood"],
                "family": family.get(row["slug"], row["item"]),
                "up": row["delta"] > 0,
                "items": [],
                "deltas": [],
                "sell": False,
            },
        )
        bucket["items"].append(row["item"])
        bucket["deltas"].append(row["delta"])
        bucket["demand"] = row["demand"]
        bucket["sell"] = bucket["sell"] or row["sell"]

    out = []
    for bucket in buckets.values():
        deltas = bucket["deltas"]
        # A drop across a whole family where we just opened a shop of that very
        # kind is our own shop taking the unmet demand, not the market cooling.
        # A phone shop opening does not explain apples getting cheaper, so the
        # kind has to match before the note is worth making.
        opened = opened_in.get((bucket["hood"], bucket["family"]), [])
        blame = opened[0] if opened and not bucket["up"] else None
        out.append(
            {
                "hood": bucket["hood"],
                "family": bucket["family"],
                "up": bucket["up"],
                "count": len(deltas),
                "items": bucket["items"][:3],
                "delta": round(sum(deltas) / len(deltas)),
                "worst": max(deltas) if bucket["up"] else min(deltas),
                "demand": bucket["demand"],
                "sell": bucket["sell"],
                "openedHere": blame["name"] if blame else None,
                "openedDay": blame["opened"] if blame else None,
            }
        )
    out.sort(key=lambda m: (not m["sell"], -abs(m["delta"]) * m["count"]))
    return out[:6]


def _type_catalogue(names: Names, tradeable: set) -> dict:
    """Which products each kind of business the player can open sells.

    The game's F1 help lists every business type a player can open, each with
    its own page — see _type_catalogue_from_help() — and the game text shipped
    with the board carries those pages too, so the list never has to be
    guessed. It holds a type whether or not anybody in the city runs one. The
    city's own gas stations, wholesalers and casino sell products as well but
    have no page, because nobody can open one; learning types from the city's
    shops once let them rank as a business to open.
    """
    catalogue = {}
    for kind, items in _type_catalogue_from_help(names).items():
        kept = items & tradeable
        if kept:
            catalogue[kind] = kept
    return catalogue


def _type_demand(
    catalogue: dict, demand: dict, hoods: list, names: Names, mine: set, stores: set
) -> list:
    """Demand for a business type is the whole basket it sells, not one product.

    Opening a shop is a commitment to its entire range, so the reading is the
    average demand across its primary products, which is all the catalogue
    holds. Each product counts at its own demand rather than in or out of the
    60 line, so a one-product type reads that product's demand and ranks on the
    same scale as an eight-product one.
    """
    rows = []
    for kind, items in catalogue.items():
        cells = []
        for hood in hoods:
            scores = [
                demand[(item, hood)]
                for item in items
                if (item, hood) in demand
            ]
            if not scores:
                cells.append(None)
                continue
            cells.append(
                {
                    "hood": hood,
                    "demand": round(sum(x["demand"] for x in scores) / len(scores)),
                    "count": len(scores),
                    "providers": round(
                        sum(x["providers"] for x in scores) / len(scores)
                    ),
                    "sell": sum(1 for x in scores if x["sell"]),
                    # A shop of this very type in this neighbourhood, from the
                    # building table or the [XX] prefix in its name.
                    "here": (kind, hood) in stores,
                }
            )
        live = [c for c in cells if c]
        if not live:
            continue
        rows.append(
            {
                "type": names.label(kind),
                "slug": kind,
                "products": len(items),
                "mine": kind in mine,
                "cells": cells,
                "peak": max(c["demand"] for c in live),
            }
        )
    return sorted(rows, key=lambda r: (-r["peak"], r["type"]))


def _office_demand(
    catalogue: dict, demand: dict, hoods: list, names: Names, mine: set, stores: set
) -> list:
    """An office sells one hourly fee, so its reading is that fee's own demand.

    Rolled up like a shop's range it would read 1/1 or 0/1 in every cell. The
    fee's score and the number of firms already charging it, the player's own
    included, are what decide whether another office is worth opening there.
    """
    rows = []
    for kind, fees in catalogue.items():
        cells = []
        for hood in hoods:
            scores = [demand[(fee, hood)] for fee in fees if (fee, hood) in demand]
            if not scores:
                cells.append(None)
                continue
            deltas = [x["delta"] for x in scores if x["delta"] is not None]
            cells.append(
                {
                    "hood": hood,
                    "demand": round(sum(x["demand"] for x in scores) / len(scores)),
                    "providers": round(sum(x["providers"] for x in scores) / len(scores)),
                    "hype": max((x["hype"] or 0 for x in scores), default=0) or None,
                    "delta": round(sum(deltas) / len(deltas)) if deltas else None,
                    "here": (kind, hood) in stores,
                }
            )
        live = [c for c in cells if c]
        if not live:
            continue
        rows.append(
            {
                "type": names.label(kind),
                "slug": kind,
                "fees": [names.label(fee) for fee in sorted(fees)],
                "feeSlugs": sorted(fees),
                "mine": kind in mine,
                "cells": cells,
                "peak": max(c["demand"] for c in live),
            }
        )
    return sorted(rows, key=lambda r: (-r["peak"], r["type"]))


def _group_hype(hype: dict, starts: dict, names: Names, sells: dict, makes: set) -> list:
    """A hype wave usually hits a whole product family at once; say it once."""
    waves = collections.defaultdict(list)
    for (item, hood), left in hype.items():
        waves[(hood, left)].append(item)
    out = []
    for (hood, left), items in waves.items():
        began = min(starts.get((i, hood), 0) for i in items)
        out.append(
            {
                "hood": hood,
                "daysLeft": left,
                "startDay": began,
                "items": [names.label(i) for i in sorted(items)],
                "slugs": sorted(items),
                "count": len(items),
                "mine": any(i in sells or i in makes for i in items),
                "sellHere": any(hood in sells.get(i, ()) for i in items),
            }
        )
    return sorted(out, key=lambda h: (not h["mine"], -h["daysLeft"]))


def _group_shortages(shortages: list) -> list:
    """One product short at three suppliers is one problem, not three."""
    grouped = collections.OrderedDict()
    for row in shortages:
        key = (row["slug"], row["kind"])
        if key in grouped:
            grouped[key]["count"] += 1
            grouped[key]["daysLeft"] = max(grouped[key]["daysLeft"], row["daysLeft"])
        else:
            grouped[key] = dict(row, count=1)
    return sorted(grouped.values(), key=lambda s: (not s["mine"], -s["daysLeft"]))


def _prune_days(store: dict, keep: int, day: int | None = None) -> None:
    """Keep the ``keep`` latest days of a day-keyed record.

    With ``day`` (the save being read), the count is taken up to that day, and
    the ``keep`` latest days after it stay too: an older save reloaded after a
    newer one keeps its own day and the days before it, and the newer save's
    days are there for when it is opened again. Stepping back through older
    and older saves never holds more than twice ``keep``.
    """
    keys = sorted(store, key=int)
    if day is None:
        drop = keys[:-keep]
    else:
        before = [k for k in keys if int(k) <= day]
        after = [k for k in keys if int(k) > day]
        drop = before[:-keep] + after[:-keep]
    for old in drop:
        del store[old]


class History:
    """The on-disk record the save itself does not keep.

    The save stores only today: today's demand, today's cash, today's net worth.
    Anything that compares one day with another has to be remembered here. Every
    character is a separately generated city and a separate company, so the
    histories are kept apart; mixing them would invent movement that never
    happened.

    Two records live side by side under each character: ``days`` holds a demand
    snapshot per game day, ``ledger`` holds cash, net worth and that day's profit.
    Both are keyed by the game day, so rebuilding twice on the same day updates
    the entry rather than adding a second one.
    """

    def __init__(self, path: str | None):
        self.path = path
        # False when the file on disk could not be read: this run then never
        # writes, so a file locked for a moment or damaged is not replaced by
        # one day's snapshot and weeks of history lost with it.
        self.writable = True
        self.book = self._load()
        self._touched = set()  # (character, rid) names this instance changed

    def _load(self) -> dict:
        """The book on disk; {} when there is none or it cannot be used.

        A file that exists but does not parse is moved aside to ``.bad`` so
        the next run starts clean and the damaged copy can still be looked at;
        one that cannot be opened (another program holds it) is left alone.
        Either way this run does not write.
        """
        if not self.path or not os.path.exists(self.path):
            return {}
        try:
            with open(self.path, encoding="utf-8") as fh:
                whole = json.load(fh)
            book = whole.get("characters", {}) if isinstance(whole, dict) else None
            if not isinstance(book, dict):
                raise ValueError("no characters table")
            return book
        except ValueError:
            self.writable = False
            try:
                os.replace(self.path, self.path + ".bad")
            except OSError:
                pass
        except OSError:
            self.writable = False
        return {}

    def _for(self, character: str) -> dict:
        return self.book.setdefault(character, {})

    def demand(self, character: str, day: int, snapshot: dict) -> dict:
        store = self._for(character).setdefault("days", {})
        store[str(day)] = snapshot
        _prune_days(store, HISTORY_DAYS, day)

        earlier = [d for d in sorted(store, key=int) if int(d) < day]
        if not earlier:
            return {"was": {}, "span": 0, "days": len(store)}
        target = day - TREND_WINDOW
        reference = min(earlier, key=lambda d: abs(int(d) - target))
        return {
            "was": store[reference],
            "span": day - int(reference),
            "days": len(store),
        }

    def ledger_entries(self, character: str) -> list:
        """The balance sheets already on record, oldest first, without writing."""
        store = self._for(character).get("ledger", {})
        return [dict(store[d], day=int(d)) for d in sorted(store, key=int)]

    def ledger(self, character: str, day: int, entry: dict) -> list:
        """Record today's balance sheet and hand back the whole run of them.

        Merged rather than replaced: a later save on the same day may carry
        fewer fields than an earlier one, and dropping a figure the game has
        since stopped reporting would lose it for good.
        """
        store = self._for(character).setdefault("ledger", {})
        store[str(day)] = {**store.get(str(day), {}), **entry}
        _prune_days(store, HISTORY_DAYS, day)
        # Days after today are from a later save of this character: the player
        # reloaded an older one, or picked it to look back. They are kept for
        # when that later save is opened again, but never read as today's run.
        return [dict(store[d], day=int(d)) for d in sorted(store, key=int) if int(d) <= day]

    def payback(self, character: str) -> dict:
        """What the statements forget after 61 days, kept for _payback(): per
        site key, {"opened", "bill", "firm": [day, investment], "self": [...]},
        and for a trading site its run from the opening (_payback_trail()):
        "trail" ([day, profit, sales] from the opening, capped), "before" (the
        lease's cost before the opening), "since" (the first day the record
        held), or "rolled" once the record moved past the trail; per chain
        name the same without the bill and the trail; and "vehicleFees", the
        delivery paid per vehicle id, company-wide, since a truck changes
        slots. Changed in place; a record whose `opened` no longer matches is
        a new business at that address."""
        store = self._for(character).setdefault("payback", {})
        if not isinstance(store, dict):
            store = self._for(character)["payback"] = {}
        for part in ("sites", "chains", "vehicleFees"):
            if not isinstance(store.get(part), dict):
                store[part] = {}
        return store

    def named(self, character: str, updates: dict | None = None) -> dict:
        """Lines the player named by hand, by recipe id; a None clears one."""
        store = self._for(character).setdefault("lineNames", {})
        for rid, slug in (updates or {}).items():
            self._touched.add((character, rid))
            if slug:
                store[rid] = slug
            else:
                store.pop(rid, None)
        return dict(store)

    def keep_recent(self, character: str, days: int, characters: int, day: int | None = None) -> None:
        """Bound the book, for a store with a small quota (the browser's).

        ``character`` becomes the most recent; only the ``characters`` most
        recently built are kept, each with its last ``days`` demand snapshots.
        The trend compares with about a week back, so two weeks of snapshots
        lose nothing the board shows; the ledger is small and keeps its 60.
        ``day`` is the save just built: an older save of ``character`` keeps
        its own two weeks up to that day, as well as the later days on record.
        """
        if character in self.book:
            self.book[character] = self.book.pop(character)
        for old in list(self.book)[:-characters]:
            del self.book[old]
        for name, record in self.book.items():
            _prune_days(record.get("days", {}), days, day if name == character else None)

    def write(self) -> bool:
        """Save the book; False when it was not saved (no path counts as saved)."""
        if not self.path:
            return True
        if not self.writable:
            return False
        # A build takes seconds and loads this file at its start; a name given
        # in between must not be undone by the build writing what it loaded.
        # Manual names and legacy recipe guesses are preserved from disk: only
        # the names this instance itself changed overrule it.
        disk = self._load()
        if not self.writable:
            return False
        for character, ours in self.book.items():
            theirs = disk.get(character, {})
            names = dict(theirs.get("lineNames", {}))
            mine = ours.get("lineNames", {})
            for rid in list(names) + list(mine):
                if (character, rid) in self._touched:
                    if rid in mine:
                        names[rid] = mine[rid]
                    else:
                        names.pop(rid, None)
            ours["lineNames"] = names
            learnt = dict(theirs.get("recipes", {}))
            learnt.update(ours.get("recipes", {}))
            ours["recipes"] = learnt
        # Written beside it and swapped in, so a run stopped mid-write leaves
        # the old file whole instead of half a file.
        tmp = self.path + ".tmp"
        try:
            with open(tmp, "w", encoding="utf-8") as fh:
                json.dump({"characters": self.book}, fh, separators=(",", ":"))
            os.replace(tmp, self.path)
            return True
        except OSError:
            try:
                os.remove(tmp)
            except OSError:
                pass
            return False


def _cash_flow(ledger: list, daily: list, day: int) -> dict | None:
    """Where the profit went: what the books earned against what cash did.

    Profit is a claim about trading; cash is what is left after paying for the
    next shop and the next week's stock. The gap between them is the number
    worth seeing, and it needs at least two readings to exist at all.
    """
    if len(ledger) < 2:
        return None
    latest = ledger[-1]
    earlier = [e for e in ledger if e["day"] < day]
    if not earlier:
        return None
    target = day - TREND_WINDOW
    ref = min(earlier, key=lambda e: abs(e["day"] - target))
    booked = sum(d["profit"] for d in daily if ref["day"] <= d["day"] < day)
    change = latest["cash"] - ref["cash"]
    flow = {
        "days": day - ref["day"],
        "fromDay": ref["day"],
        "cashFrom": ref["cash"],
        "cashTo": latest["cash"],
        "cashChange": money(change),
        "profit": money(booked),
        "reinvested": money(booked - change),
        "netWorthFrom": None,
        "netWorthTo": None,
        "netWorthChange": None,
    }
    # Build 3672 stopped reporting net worth, so the ledger carries it only for
    # the days the game still did. Cash and profit stand on their own.
    if ref.get("netWorth") is not None and latest.get("netWorth") is not None:
        flow["netWorthFrom"] = ref["netWorth"]
        flow["netWorthTo"] = latest["netWorth"]
        flow["netWorthChange"] = money(latest["netWorth"] - ref["netWorth"])
    return flow


ENDS_A_CHAIN = ("retail", "office")

# The sites that turn what they are sent into something else, so that a product
# which goes no further than one has still reached the shops that site serves.
# Named rather than inferred from "off the shop floor and not a warehouse": a
# storage type the game renames or adds would land in that gap and be read as a
# factory. The plans carry the same fact for a site whose production is set up,
# and either signal is enough.
MAKES_GOODS = frozenset({
    "ba:businesstype_factory",
    "ba:businesstype_foodfactory",
    "ba:businesstype_electronicsfactory",
})


def _chains(save: Save, businesses: list, trends: list) -> list:
    """Which sites work as one business, read off the logistics plans.

    A shop, the depot that fills it and the factory behind that depot are one
    trading operation; judged apart, a 98% shop margin sits next to a factory
    running -80% and neither figure means anything.

    Connected components would put everything in one bucket — the food factory
    sends soda to the electronics depot, which links the two chains through a
    side line. So a chain is named by the kind of shop at the end of it, and each
    warehouse and factory joins the kind of shop it mostly feeds.

    What it mostly feeds is read one stock line at a time. Every delivery of a
    product to a shop or an office is an end, and every line a site ships is one
    vote, divided between the kinds of shop at the ends that line reaches.
    Counting sites rather than goods would hand a shared depot's whole trade to
    anyone who puts a single product into it — one crate of phones into the
    depot that stocks twelve fast food outlets, and the electronics factory
    lands in the fast food chain. A line that reaches no end is no evidence and
    casts no vote, which is what a half-set-up depot looks like until it is
    plumbed in. Nothing here is hand-written; it all comes out of the plans.
    """
    by_key = {b["key"]: b for b in businesses}
    # source -> the stock lines it ships, in plan order. The dict is an ordered
    # set: the same product to the same place, named in two plans, is one supply
    # line, and a real set would order the votes by the hash seed.
    lines = collections.defaultdict(dict)
    arriving = collections.defaultdict(dict)
    fed_by = {}
    makers = {b["key"] for b in businesses if b["typeSlug"] in MAKES_GOODS}
    for plan in save.items(save.root["logisticsManagerPlans"]):
        source = site_key(save.address(plan["targetAddress"]))
        if source not in by_key:
            continue
        if plan.get("isFactory"):
            makers.add(source)
        for dest in save.items(plan["destinations"]):
            target = site_key(save.address(dest["deliveryTargetAddress"]))
            if target not in by_key or target == source:
                continue
            for stock in save.items(dest["stockTargets"]):
                fed_by.setdefault(target, source)
                item = stock.get("itemName")
                lines[source][(target, item)] = None
                arriving[target][item] = None

    # What each site sends out, whatever the destination, so that a product
    # arriving at a factory can be told from one it is only passing along.
    ships = {key: {item: None for _, item in shipped} for key, shipped in lines.items()}

    # Which ends a product can reach once it is at a site. Depots stock each
    # other and factories supply factories, so this cannot be had by walking
    # down the plans: a walk would have to cut those loops somewhere, and where
    # it cut them would depend on which site the save happened to list first.
    # It is read by repetition instead, from nothing known, and every step only
    # ever adds ends, so each reading widens to one exact answer and stops
    # there however the plans loop back on themselves.
    carries = collections.defaultdict(bool)
    ends = collections.defaultdict(frozenset)
    made = collections.defaultdict(frozenset)

    def carried(target: str, item, known: dict) -> frozenset:
        """The shop deliveries this product feeds, arriving at this site."""
        if by_key[target]["status"] in ENDS_A_CHAIN:
            return frozenset(((target, item),))
        return known[(target, item)]

    # First, whether a product gets anywhere on its own: handed from site to
    # site under its own name until it reaches a shop, or reaches a factory that
    # keeps it and turns it into what that factory ships. Either way it is on
    # its way somewhere, and the site that sent it is not the one to ask about
    # it. That question has to be settled by itself and before anything else,
    # because it is what says whether a product arriving at a factory was handed
    # on or used up. Reading it off the answer below as that answer grew would
    # let a reading shrink again — a ring of factories passing one product round
    # would swap between two answers for ever.
    def gets_somewhere(target: str, item) -> bool:
        site = by_key[target]
        if site["status"] in ENDS_A_CHAIN:
            return True
        if target in makers and item not in ships.get(target, ()):
            return True  # kept here, and made into whatever this factory ships
        return carries[(target, item)]

    settling = True
    while settling:
        settling = False
        for source, shipped in lines.items():
            if by_key[source]["status"] in ENDS_A_CHAIN:
                continue
            for item in arriving.get(source, ()):
                if carries[(source, item)]:
                    continue
                if any(gets_somewhere(t, i) for t, i in shipped if i == item):
                    carries[(source, item)] = True
                    settling = True

    # Then the reading proper, over the same plans. Which reading a product gets
    # was settled above, so none of them can take an end away and each pass only
    # ever adds: the widening reaches one exact answer and stops there. One pass
    # carries an end one site further back, so a save settles in as many passes
    # as it has readings; the bound is that, and running it out means the steps
    # stopped only ever adding, which is a fault in this code rather than
    # anything a save can ask for.
    readings = sum(len(items) for items in arriving.values())
    settling = True
    passes = readings + 2
    while settling and passes:
        settling = False
        passes -= 1
        for source, shipped in lines.items():
            if by_key[source]["status"] in ENDS_A_CHAIN:
                continue
            if source in makers:
                # What this factory makes: everything it ships, less the goods
                # it was handed to pass along, which are somebody else's trade
                # and say nothing about what the factory turns its inputs into.
                #
                # A product that both arrives here and leaves is read as passing
                # through, and a factory where every line is such a product is
                # read as making nothing of its own — so whoever supplies its
                # inputs waits in Head office and support. That is the one thing
                # the plans genuinely cannot answer: they record where goods go,
                # never whether a delivery was a recipe's input or a crate being
                # moved on, and the two look identical. Reading those lines as
                # the factory's own making instead would file the site behind
                # them under whatever the factory happens to be carrying for
                # somebody else, which is the complaint this whole reading
                # exists to answer. Better to say nothing than to say that.
                #
                # Which lines count is settled before this reading starts:
                # choosing on whether their ends happen to be filled in yet
                # would let this set shrink again from one pass to the next, and
                # then the plan the save stores first would decide the answer.
                own = [step for step in shipped if not carries[(source, step[1])]]
                everything = frozenset().union(
                    *(carried(t, i, ends) for t, i in own)
                )
                if everything != made[source]:
                    made[source] = everything
                    settling = True
            for item in arriving.get(source, ()):
                onward = frozenset().union(
                    *(carried(t, i, ends) for t, i in shipped if i == item)
                )
                if not carries[(source, item)] and source in makers:
                    # It reaches no shop as itself and this site makes goods, so
                    # it became what the factory ships — the plans never say
                    # which arrival was a recipe input, so all of that factory's
                    # own ends stand behind it.
                    found = made[source]
                else:
                    # Either it goes on from here under its own name, which is
                    # the plainest evidence there is, or this site only stores
                    # and forwards, in which case where its onward lines end up
                    # is the whole of what can be said. A depot holding goods it
                    # never sends on has no onward line, so it reaches nobody.
                    found = onward
                if found != ends[(source, item)]:
                    ends[(source, item)] = found
                    settling = True

    def votes(key: str) -> collections.Counter:
        """Which kinds of shop this site's goods end up in, and how heavily."""
        cast = collections.Counter()
        for target, item in lines.get(key, ()):
            found = carried(target, item, ends)
            if not found:
                continue  # these goods reach no shop floor: no chain to vote for
            kinds = collections.Counter(by_key[shop]["typeSlug"] for shop, _ in found)
            # One line is one vote wherever it ends up, so a product going to
            # nine fast food counters and one electronics store divides nine to
            # one. Exact fractions rather than 0.9: a tie between two kinds is
            # settled by the name order in `winner`, not by a rounding.
            reach = sum(kinds.values())
            for slug, count in kinds.items():
                cast[slug] += fractions.Fraction(count, reach)
        return cast

    def winner(cast: collections.Counter):
        """The kind of shop a site is grouped under, or None if it feeds none.

        A tie goes to the kind of shop named first; most_common() would hand it
        to whichever the count happened to yield first this run.
        """
        return min(cast, key=lambda k: (-cast[k], str(k))) if cast else None

    groups = collections.OrderedDict()
    for b in businesses:
        if b["status"] == "vacant":
            key = "\0vacant"
        elif b["status"] in ENDS_A_CHAIN:
            key = b["typeSlug"]
        else:
            key = winner(votes(b["key"])) or "\0support"
        groups.setdefault(key, []).append(b)

    by_trend = {t["key"]: t for t in trends}
    chains = []
    for key, members in groups.items():
        shops = [b for b in members if b["status"] in ENDS_A_CHAIN]
        if key == "\0vacant":
            name = msg("co.chain.name.vacant", "Vacant leases")
        elif key == "\0support":
            name = msg("co.chain.name.support", "Head office and support")
        else:
            # The English plural is English's; another language names the
            # chain by its type's game name, {type}.
            b = shops[0] if shops else members[0]
            name = msg("co.chain.name.type", "{chain}", chain=_plural(b["type"]) if shops else b["type"],
                       type=tok(b.get("typeSlug"), b["type"]))
        chains.append(_chain(name, members, fed_by, by_key, by_trend))
    chains.sort(key=lambda c: -c["profit"])
    return chains


def _plural(label: str) -> str:
    if label.endswith("s"):
        return label
    # "Travel Agency" chains as "Travel Agencies"; "Gift Shop" just takes an s.
    if len(label) > 1 and label.endswith("y") and label[-2].lower() not in "aeiou":
        return label[:-1] + "ies"
    # A station's name goes into a sentence too: "another hairdresser headwash"
    # is one, "the hairdresser headwashes" is two of them.
    if label.endswith(("sh", "ch", "x", "z")):
        return label + "es"
    return label + "s"


COST_KEYS = ("cogs", "wages", "rent", "marketing", "theft", "licensing")


def _chain(name: str, members: list, fed_by: dict, by_key: dict, by_trend: dict) -> dict:
    index = {b["key"]: b for b in members}
    revenue = sum(b["revenue"] for b in members)
    cost = sum(sum(b[k] for k in COST_KEYS) for b in members)
    profit = sum(b["profit"] for b in members)
    # Revenue booked away from the shop counter is a sale to somebody outside the
    # company — a factory shipping to a pier. It is real money, but it is not
    # what the shops took, so it is named rather than folded in. An office's fees
    # are its trading, the way a shop's takings are.
    external = sum(b["revenue"] for b in members if b["status"] not in ENDS_A_CHAIN)
    outside = {
        fed_by[b["key"]]
        for b in members
        if b["key"] in fed_by and fed_by[b["key"]] not in index
    }
    # A chain's week only compares with the week before it if every member that
    # traded has both weeks behind it. One shop opened mid-window and the whole
    # comparison is measuring the opening, not the trading.
    earners = [b for b in members if b["revenue"] > 0]
    rows = [by_trend[b["key"]] for b in earners if b["key"] in by_trend]
    ready = bool(rows) and len(rows) == len(earners) and all(r["ready"] for r in rows)
    last7 = money(sum(r["last7"] for r in rows)) if ready else None
    prev7 = money(sum(r["prev7"] for r in rows)) if ready else None
    return {
        "name": name,
        "sites": [b["key"] for b in members],
        "count": len(members),
        "revenue": money(revenue),
        "retailRevenue": money(revenue - external),
        "external": money(external),
        "cost": money(cost),
        "profit": money(profit),
        "margin": round(profit / revenue * 100, 1) if revenue else None,
        "last7": last7,
        "prev7": prev7,
        "change": round((last7 - prev7) / prev7, 4) if ready and prev7 else None,
        "staff": sum(b["staff"] for b in members),
        "suppliedBy": sorted(
            by_key[k]["name"] for k in outside if k in by_key
        ),
        **{k: money(sum(b[k] for b in members)) for k in COST_KEYS},
    }


def _site_trends(businesses: list, day: int) -> list:
    """Each site's last seven days of revenue against the seven before them."""
    out = []
    for i, b in enumerate(businesses):
        if b["status"] == "vacant":
            continue
        series = {s["day"]: s["revenue"] for s in b["series"]}
        last = [series[d] for d in range(day - 7, day) if d in series]
        prev = [series[d] for d in range(day - 14, day - 7) if d in series]
        # A shop open under two weeks has no previous week to be compared with,
        # and its first days are a ramp, not a trend.
        ready = (
            day - b["opened"] >= TREND_MIN_DAYS and len(last) == 7 and len(prev) == 7
        )
        row = {
            "s": i,
            "key": b["key"],
            "ready": ready,
            "last7": money(sum(last)),
            "prev7": money(sum(prev)),
        }
        row["change"] = (
            round((row["last7"] - row["prev7"]) / row["prev7"], 4)
            if ready and row["prev7"]
            else None
        )
        out.append(row)
    return out


# ------------------------------------------------------------------- payback
# What a site cost to set up, and when its profit paid that back
# (docs/open-a-store-scope.md, "Phase 1"). The rules are the game's own, read
# from its code on 28 Sep 2026 and checked against six real bills to the coin:
#   installation firm  586 x the building's m² + every item at its default
#                      price; walls and floors cost nothing
#                      (InteriorInstallationFirmHelper.GetInstallationFee)
#   self-installation  every item at its default price + each paid wall and
#                      floor slot at its material's price
# and the deposit in both, although the game refunds it when the lease ends.
# The firm's real bill also credits a trade-in of what stood in the building
# (sellingMultiplier x its worth, stock included). An estimate leaves that out
# on purpose: it depends on what the building held, not on the store.
INSTALL_FEE_PER_M2 = 586
# The forward estimate's rate: the average day over the last this many finished
# days since the site first sold anything, closed days included, because rent
# is paid on those too and the estimate counts calendar days.
PAYBACK_RECENT_DAYS = 14
# How many finished days of statements the game keeps (Safara on day 185 holds
# days 124 to 184); a shorter run has lost nothing yet.
STATEMENT_WINDOW = 61
# A remembered break-even day stands while the investment it was reached
# against moves by less than this share (a painting added, a plant sold).
PAYBACK_REMEMBER_SLACK = 0.01

_ORDINAL_WORDS = (
    "first", "second", "third", "fourth", "fifth", "sixth", "seventh", "eighth",
    "ninth", "tenth", "eleventh", "twelfth", "thirteenth", "fourteenth",
    "fifteenth", "sixteenth", "seventeenth", "eighteenth", "nineteenth", "twentieth",
)


def _ordinal(n: int) -> str:
    return f"{n}{'th' if 10 <= n % 100 <= 20 else {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th')}"


_ORDINALS = {word: _ordinal(i) for i, word in enumerate(_ORDINAL_WORDS, 1)}


def _address_words(text: str) -> str:
    """An address as comparable words: "4 Third Avenue" and the game's own
    "4 3rd Avenue" (the text a transaction carries) read the same."""
    words = re.findall(r"[a-z0-9]+", str(text or "").lower())
    return " ".join(_ORDINALS.get(w, w) for w in words)


def item_price(name: str, paid, prices: dict | None = None) -> float:
    """What a piece of furniture is worth: what was paid for it, or its default
    price where the save records nothing, as the game's ItemHelper.GetWorth does."""
    if paid:
        return float(paid)
    table = (prices if prices is not None else load_item_prices())["items"]
    return float((table.get(name) or {}).get("p") or 0)


def setup_cost(items, materials, square_metres, deposit, prices: dict | None = None,
               vehicles: float = 0) -> dict:
    """What a store costs to set up, in both install modes.

    `items` are (item name, price paid) pairs, the paid price 0 or None where
    nothing was paid yet; `materials` the MaterialIDs of the wall and floor
    slots; `square_metres` the building's floor (ba_buildings.json `m`). A store
    that exists passes its save's furniture and slots and its lastDeposit; a
    planned one passes its shopping list and its deposit estimate. `vehicles`
    is what the business's own vehicles cost, delivery included
    (_site_vehicles()). `firm` and `self` are the investment in each mode,
    deposit and vehicles included.
    """
    prices = prices if prices is not None else load_item_prices()
    furniture = sum(item_price(name, paid, prices) for name, paid in items)
    table = prices["materials"]
    walls = sum(float((table.get(m) or {}).get("p") or 0) for m in materials)
    fee = INSTALL_FEE_PER_M2 * float(square_metres or 0)
    deposit = float(deposit or 0)
    vehicles = float(vehicles or 0)
    return {
        "furniture": money(furniture),
        "materials": money(walls),
        "fee": money(fee),
        "deposit": money(deposit),
        "vehicles": money(vehicles),
        "firm": money(furniture + fee + deposit + vehicles),
        "self": money(furniture + walls + deposit + vehicles),
    }


def _vehicle_type(vehicle: dict):
    """A vehicle instance's type slug; None in a save too old to name it."""
    name = (vehicle or {}).get("vehicleTypeName")
    return name if isinstance(name, str) else None


def _vehicle_deliveries(save: Save, table: dict) -> dict:
    """What was paid to have a vehicle delivered, per vehicle id, for the
    purchases the transaction log still holds (about a week).

    A purchase is ba:transaction_vehiclebought, its transactionData naming the
    type (`vehicleName`) but neither the vehicle nor where it went: a Freight
    Truck T1 bought for delivery costs $103,000 against its $98,000 price, one
    collected at the dealer the price alone. VehicleInstances grows in the
    order vehicles are bought, so the log's purchases of a type, oldest first,
    are the last instances of that type in the list; the excess over the
    type's price (ba_store_rules.json `vehicles`) is the delivery.
    """
    bought = collections.defaultdict(list)
    for t in save.items(save.root.get("Transactions")):
        if not isinstance(t, dict) or t.get("transactionType") != "ba:transaction_vehiclebought":
            continue
        data = {e.get("$k"): e.get("$v") for e in save.items(t.get("transactionData")) if isinstance(e, dict)}
        kind = data.get("vehicleName")
        if isinstance(kind, str) and kind in table:
            bought[kind].append(-float(t.get("amount") or 0) - float(table[kind]))
    by_type = collections.defaultdict(list)
    for v in save.items(save.root.get("VehicleInstances")):
        if isinstance(v, dict) and v.get("id") and _vehicle_type(v) in bought:
            by_type[_vehicle_type(v)].append(v["id"])
    out = {}
    for kind, fees in bought.items():
        ids = by_type[kind][-len(fees):]
        for vid, fee in zip(ids, fees[len(fees) - len(ids):]):
            if fee > 0:
                out[vid] = money(fee)
    return out


def _site_vehicles(save: Save, registration: dict, table: dict) -> dict:
    """The vehicles a business holds, {vehicle id: price by type}.

    The tie is the building registration's `vehicleSlots`, a warehouse's or a
    factory's parking (Entities.VehicleSlot: `vehicleInstanceId`, and the
    `employeeDriverId` driving it), each id one of the save's VehicleInstances.
    A vehicle in no slot, such as the player's own car, belongs to no
    business. A type with no price (a hand truck, a flatbed) counts nothing.
    """
    instances = {v.get("id"): v for v in save.items(save.root.get("VehicleInstances")) if isinstance(v, dict)}
    out = {}
    for slot in save.items(registration.get("vehicleSlots")):
        vid = slot.get("vehicleInstanceId") if isinstance(slot, dict) else None
        if vid and vid in instances:
            out[vid] = float(table.get(_vehicle_type(instances[vid])) or 0)
    return out


def _site_setup(save: Save, registration: dict, addr, prices: dict, vehicles: float = 0) -> dict:
    """setup_cost() for a rented building, read off its registration;
    `vehicles` the business's own, as _payback() prices them."""
    items = []
    # Stacked items are top-level instances too; stackedItems only points at them.
    for item in _item_instances(save, registration.get("itemInstances")):
        if item.get("itemName"):
            items.append((item["itemName"], item.get("priceOnPurchase")))
    materials = []
    for design in save.items(registration.get("interiorDesigns")):
        for slot in save.items((save.deref(design) or {}).get("materials")):
            if isinstance(slot, dict) and slot.get("MaterialID"):
                materials.append(slot["MaterialID"])
    building = load_buildings().get(addr) or {}
    return setup_cost(items, materials, building.get("m"), registration.get("lastDeposit"), prices, vehicles)


def _install_bills(save: Save, names: Names, addresses: dict) -> dict:
    """The installation firm's bills the transaction log still holds (about a
    week), per site key: [(day, amount)]. A bill names its address as text,
    "4 3rd Avenue"; `addresses` maps each site key to its (street, number)."""
    by_words = {_address_words(names.addr(addr)): key for key, addr in addresses.items()
                if isinstance(addr[0], str)}
    by_addr = {addr: key for key, addr in addresses.items()}
    out = collections.defaultdict(list)
    for t in save.items(save.root.get("Transactions")):
        if not isinstance(t, dict) or t.get("transactionType") != "ba:transaction_interiorinstallation":
            continue
        key = by_addr.get(save.address(t.get("address")))
        if key is None:
            data = {e.get("$k"): e.get("$v") for e in save.items(t.get("transactionData"))
                    if isinstance(e, dict)}
            key = by_words.get(_address_words(data.get("address")))
        if key is None:
            continue
        day = (save.deref(t.get("timestamp")) or {}).get("Day")
        out[key].append((day, -float(t.get("amount") or 0)))
    return out


def payback_outcome(investment: float, days: list, exact: bool, opened: int, rate, not_before=None) -> dict:
    """When `days` of profit, (day, profit) oldest first, pay `investment` back.

    `reached`: the first day the running total reached it, and how many days
    after opening, where `days` start with the lease. `latest`: the same day
    where they start inside it, so the site paid back by then at the latest.
    Otherwise, from the lease's start, `togo`: the days still needed at `rate`
    a day, or `never` when the rate earns nothing. From inside the lease the
    profit before the record is unknown, so neither can be said: `window`
    gives the whole payback period at `rate` instead (`days`, and `day`, the
    opening plus that; both absent when the rate earns nothing). `unknown`
    with no rate at all, from the lease's start.

    `not_before`: no day earlier counts as the crossing -- a chain's newest
    member's opening, before which its investment was not yet spent.
    """
    total = 0.0
    for day, profit in days:
        total += profit
        if total >= investment and (not_before is None or day >= not_before):
            if exact:
                return {"state": "reached", "day": day, "after": day - opened}
            return {"state": "latest", "day": day}
    if not exact:
        if rate is not None and rate > 0:
            days = max(1, math.ceil(investment / rate))
            return {"state": "window", "days": days, "day": opened + days}
        return {"state": "window"}
    if rate is None:
        return {"state": "unknown"}
    if rate <= 0:
        return {"state": "never"}
    return {"state": "togo", "days": max(1, math.ceil((investment - total) / rate))}


def _payback_rate(days: list, opened: int):
    """The average day over the last PAYBACK_RECENT_DAYS finished days after
    opening, counted from the first day anything sold; None before that.
    `days` are (day, profit, sales)."""
    selling = [i for i, (day, _p, sales) in enumerate(days) if day > opened and sales > 0]
    if not selling:
        return None
    recent = [p for day, p, _s in days[selling[0]:] if day > opened][-PAYBACK_RECENT_DAYS:]
    return sum(recent) / len(recent) if recent else None


def chain_window_day(members: list):
    """The day a chain that grew over time pays back at recent profit: the
    first day t, no earlier than its newest member's opening, on which
    sum(rate x (t - opened)) over its members reaches sum(investment).
    `members` are (opened, rate, investment); a rate of None earns nothing.
    The newest member's opening when the members before it had already
    covered the investment by then; None when they had not and together
    earn nothing a day."""
    if not members:
        return None
    newest = max(opened for opened, _r, _i in members)
    invested = sum(inv for _o, _r, inv in members)
    # The members that opened first may have paid it all back by the day
    # the newest opened, whatever the rate together is now.
    if sum((rate or 0) * (newest - opened) for opened, rate, _i in members) >= invested:
        return newest
    slope = sum(rate or 0 for _o, rate, _i in members)
    if slope <= 0:
        return None
    need = invested + sum((rate or 0) * opened for opened, rate, _i in members)
    return max(newest, math.ceil(need / slope - 1e-9))


def _member_rate(days: list, opened: int):
    """A chain member's recent daily profit, sales or none (a cost centre, or
    a site with no sale yet): the average of its
    last PAYBACK_RECENT_DAYS days after opening; None before that."""
    recent = [p for day, p, _s in days if day > opened][-PAYBACK_RECENT_DAYS:]
    return sum(recent) / len(recent) if recent else None


# How long a site's day-by-day trail is kept once the record no longer reaches
# its opening: up to break even plus PAYBACK_TRAIL_AFTER days, and never more
# than PAYBACK_TRAIL_DAYS days from the opening.
PAYBACK_TRAIL_DAYS = 180
PAYBACK_TRAIL_AFTER = 30


def _payback_trail(days: list, exact: bool, opened: int, memory: dict, invest: float, last_day=None):
    """A trading site's days from its opening, beyond the record's 61.

    The whole run from the opening is the record's own days while the record
    reaches the opening (`exact`), and after that the kept trail with the
    record's newer days after it, as long as the two meet. Every save that
    knows the whole run writes it back to `memory["trail"]` ([day, profit,
    sales] from the opening), with the lease's cost before the opening as
    `memory["before"]` and the first day the record held as `memory["since"]`,
    capped at PAYBACK_TRAIL_DAYS days, and at PAYBACK_TRAIL_AFTER days past the
    day the larger investment, `invest`, is covered.

    Once the record starts after the trail's last day, the days between are
    lost: the trail is dropped and `memory["rolled"]` set, for good.

    A trail a newer save wrote may run past this save's last statement,
    `last_day`: only the days up to it are this save's, so the rest is left
    out before the two are joined and before the gap is judged.

    Returns ((trail, before, since), rolled): the whole run where it is known,
    else None; `rolled` is True for a site whose trail rolled off.
    """
    if exact:
        full = [[d, money(p), money(s)] for d, p, s in days if d >= opened]
        before = money(sum(p for d, p, _s in days if d < opened))
        since = days[0][0] if days else None
        memory.pop("rolled", None)
    else:
        if memory.get("rolled"):
            return None, True
        kept = memory.get("trail")
        try:
            kept = [[int(d), float(p), float(s)] for d, p, s in kept] if isinstance(kept, list) else []
        except (TypeError, ValueError):
            kept = []
        if last_day is not None:
            kept = [d for d in kept if d[0] <= last_day]
        if not kept:
            return None, False
        # The record must pick up the day after the trail ends, or the days
        # between are unknown.
        if days and days[0][0] > kept[-1][0] + 1:
            for field in ("trail", "before", "since"):
                memory.pop(field, None)
            memory["rolled"] = True
            return None, True
        full = kept + [[d, money(p), money(s)] for d, p, s in days if d > kept[-1][0]]
        before = money(memory.get("before") or 0)
        since = memory.get("since") if isinstance(memory.get("since"), int) else None
    capped, reached, total = [], None, before
    for d in full:
        total += d[1]
        if reached is None and total >= invest:
            reached = d[0]
        if len(capped) >= PAYBACK_TRAIL_DAYS or (reached is not None and d[0] > reached + PAYBACK_TRAIL_AFTER):
            break
        capped.append(d)
    memory["trail"], memory["before"], memory["since"] = capped, before, since
    return (full, before, since), False


def _payback_row(days: list, cost: dict, exact: bool, opened: int, memory: dict, last_day,
                 not_before=None) -> dict:
    """Profit so far, the recent rate and the outcome in each install mode,
    with a break-even day remembered from an earlier save where the statements
    no longer reach it. `not_before` as payback_outcome() takes it."""
    rate = _payback_rate(days, opened)
    row = {
        "since": days[0][0] if days else None,
        "exact": exact,
        "opened": opened,
        "profit": money(sum(p for _d, p, _s in days)),
        "rate": money(rate) if rate is not None else None,
    }
    for mode in ("firm", "self"):
        outcome = payback_outcome(cost[mode], [(d, p) for d, p, _s in days], exact, opened, rate, not_before)
        kept = memory.get(mode)
        if outcome["state"] == "reached":
            memory[mode] = [outcome["day"], cost[mode]]
        elif (isinstance(kept, list) and len(kept) == 2 and last_day is not None
              and kept[0] <= last_day and (not_before is None or kept[0] >= not_before)
              and abs(kept[1] - cost[mode]) <= PAYBACK_REMEMBER_SLACK * max(cost[mode], 1)):
            outcome = {"state": "reached", "day": kept[0], "after": kept[0] - opened, "kept": True}
        row[mode] = outcome
    return row


def _payback(save: Save, names: Names, buildings: list, businesses: list, chains: list,
             stmt_history: list, history, character: str) -> dict:
    """Investment, profit so far and break-even per site and per chain.

    A factory, a depot and a head office are cost centres: they get no payback
    of their own, and their investment counts in their chain, where a shop fed
    by its own factory stops looking free of goods costs. A chain's investment
    and profit are the sums over its sites. A chain of cost centres alone has a
    row only when it sells something (a factory selling outside the company);
    one that sells nothing has nothing to pay anything back with.

    A site's investment takes in the vehicles it holds (_site_vehicles()), so
    a chain's counts its depots' and factories' trucks.

    The history keeps what the statements forget. An older save of the same
    character reads it and changes nothing, as the ledger does, so going back
    to an earlier save and forward again loses no remembered day.
    """
    prices = load_item_prices()
    regs = {site_key(_address_of(b, strict=True)): b for b in buildings}
    addresses = {key: _address_of(b, strict=True) for key, b in regs.items()}
    bills = _install_bills(save, names, addresses)
    vehicle_prices = load_store_rules().get("vehicles") or {}
    deliveries = _vehicle_deliveries(save, vehicle_prices)
    start = stmt_history[0][0] if stmt_history else None
    last_day = stmt_history[-1][0] if stmt_history else None
    # Fewer statements than the game keeps: nothing has dropped out yet.
    whole = len(stmt_history) < STATEMENT_WINDOW
    store = history.payback(character)
    # How far this save reaches: its last statement, or the day before its
    # own for a save with none yet (a first day), to compare with the newest
    # save the memory has seen before anything in it changes.
    today = save.root.get("Day")
    now = last_day if last_day is not None else (today - 1 if isinstance(today, int) else None)
    kept_day = store.get("day") if isinstance(store.get("day"), int) else None
    older = kept_day is not None and (now is None or now < kept_day)
    if older:  # read the newer save's memory, write none of it
        store = json.loads(json.dumps(store))
    elif now is not None:
        store["day"] = now
    kept_sites, kept_chains = store["sites"], store["chains"]
    # Each vehicle's delivery, by vehicle id for the whole company: the log
    # shows it for a week, and the truck may change slots after that. An
    # entry goes when the vehicle is gone from the save.
    existing = {v.get("id") for v in save.items(save.root.get("VehicleInstances")) if isinstance(v, dict)}
    kept_fees = store["vehicleFees"]
    vehicle_fees = {vid: deliveries.get(vid, kept_fees.get(vid)) for vid in existing if vid}
    vehicle_fees = {vid: fee for vid, fee in vehicle_fees.items() if isinstance(fee, (int, float)) and fee > 0}
    kept_fees.clear()
    kept_fees.update(vehicle_fees)

    sites, series, window_exact, runs = {}, {}, {}, {}
    for b in businesses:
        key = b["key"]
        if b["status"] == "vacant" or key not in regs:
            continue
        addr = addresses[key]
        days = [(day, by[addr].get("TotalProfit", 0), by[addr].get("TotalSales", 0))
                for day, by in stmt_history if addr in by]
        opened = b["opened"]
        # The record reaches back to the lease, or at least to the opening:
        # rent paid on an empty lease before the record is the lease's own,
        # not trading the record has lost.
        exact = not days or whole or days[0][0] > start or opened > start
        # Sales before the opening day were another business on the same
        # lease, whose setup is not this one's: count from the day after them.
        prior = [i for i, (day, _p, sales) in enumerate(days) if day < opened and sales > 0]
        if prior:
            days, exact = days[prior[-1] + 1:], True
        first = days[0][0] if days else None
        memory = kept_sites.get(key)
        if not isinstance(memory, dict) or memory.get("opened") != opened:
            memory = {"opened": opened}
        # The business's own vehicles at their type's price, and the delivery
        # paid for each, wherever it is parked now.
        held = _site_vehicles(save, regs[key], vehicle_prices)
        cost = _site_setup(save, regs[key], addr, prices,
                           sum(held.values()) + sum(vehicle_fees.get(vid, 0) for vid in held))
        # The firm's real bill where the log still holds it, and remembered
        # after it drops out, so the investment does not jump a week later.
        # Only the bill that set the site up counts: the lease starts inside
        # the record and the bill comes no later than the first day with
        # sales. A re-layout months on is a new bill for an old site.
        lease = min(opened, first) if first is not None else opened
        selling = next((day for day, _p, sales in days if sales > 0), None)
        billed = sum(amount for day, amount in bills.get(key, ())
                     if exact and (day is None or (day >= lease and (selling is None or day <= selling))))
        if billed:
            memory["bill"] = money(billed)
        billed = memory.get("bill") or 0
        if billed:
            cost["billed"] = money(billed)
            cost["firm"] = money(cost["deposit"] + billed + cost["vehicles"])
        kept_sites[key] = memory
        series[key] = days
        row = {"costCentre": b["costCentre"], "cost": cost}
        if b["costCentre"]:
            row.update(since=first, exact=exact, opened=opened,
                       profit=money(sum(p for _d, p, _s in days)))
            if exact:
                runs[key] = days
        else:
            window_exact[key] = exact
            full, rolled = _payback_trail(days, exact, opened, memory, max(cost["firm"], cost["self"]), last_day)
            if full is not None:
                trail, before, since = full
                # The whole run from the lease on: the record's own days, or
                # the kept trail with the record's newer days after it.
                run = ([(since, before, 0)] if since is not None and since < opened else []) + [tuple(d) for d in trail]
                runs[key] = run
                row.update(_payback_row(run, cost, True, opened, memory, last_day))
                row["since"] = since if since is not None else row["since"]
                # Day by day from the opening, for a plan's After opening
                # (Open a store, step 6): [day, profit, sales]. What the lease
                # cost before the opening day is one sum, `before`; both add up
                # to `profit`.
                row["days"] = [list(d) for d in trail]
                row["before"] = before
            else:
                row.update(_payback_row(days, cost, exact, opened, memory, last_day))
                if rolled:
                    # The site was seen from its opening once, but the days
                    # between the kept trail and the record were lost.
                    row["rolled"] = True
        sites[key] = row
    # A site given up since the last save leaves the memory with it.
    for key in [k for k in kept_sites if k not in sites]:
        del kept_sites[key]

    out_chains = {}
    for chain in chains:
        members = [k for k in chain["sites"] if k in sites]
        if not members or (all(sites[k]["costCentre"] for k in members)
                           and not any(sales > 0 for k in members for _d, _p, sales in series[k])):
            continue
        cost = {field: money(sum(sites[k]["cost"].get(field, 0) for k in members))
                for field in ("furniture", "materials", "fee", "deposit", "vehicles", "billed", "firm", "self")}
        # Every member's whole run known (the record's, or a kept trail): the
        # chain's is their sum and exact. Otherwise the record's days, and
        # the record's own reach.
        whole = all(k in runs for k in members)
        by_day = collections.defaultdict(lambda: [0.0, 0.0])
        for k in members:
            for day, profit, sales in (runs[k] if whole else series[k]):
                by_day[day][0] += profit
                by_day[day][1] += sales
        days = [(day, p, s) for day, (p, s) in sorted(by_day.items())]
        opened = min(sites[k]["opened"] for k in members)
        exact = whole or all(window_exact.get(k, sites[k]["exact"]) for k in members)
        name = str(chain["name"])
        memory = kept_chains.get(name)
        if not isinstance(memory, dict) or memory.get("opened") != opened:
            memory = {"opened": opened}
        # Each member's investment is spent on its own opening day: the whole
        # is not paid back before the newest member has opened, whatever the
        # others earned before it (as chain_window_day() counts it).
        newest = max(sites[k]["opened"] for k in members)
        row = {"sites": members, "cost": cost, **_payback_row(days, cost, exact, opened, memory, last_day, newest)}
        # A chain that grew over time: each member pays from its own opening,
        # at its own rate, so the day is not the first opening plus the whole.
        for mode in ("firm", "self"):
            if row[mode]["state"] == "window":
                # A member with no sales yet still pays rent and wages: its
                # recent days count, as a cost centre's do.
                rates = [(sites[k]["opened"],
                          sites[k].get("rate") if sites[k].get("rate") is not None
                          else _member_rate(series[k], sites[k]["opened"]),
                          sites[k]["cost"][mode]) for k in members]
                day = chain_window_day(rates)
                row[mode] = {"state": "window", "day": day} if day is not None else {"state": "window"}
        kept_chains[name] = memory
        out_chains[chain["sites"][0]] = row
    for name in [n for n in kept_chains if n not in {str(c["name"]) for c in chains}]:
        del kept_chains[name]
    return {"sites": sites, "chains": out_chains, "recentDays": PAYBACK_RECENT_DAYS}


# ------------------------------------------------------------- open a store
# Expansion › Open a store (docs/open-a-store-scope.md, phase 2): the facts a
# plan for a store that does not exist yet is worked out from. Python says what
# the save and the game's tables hold -- what a type needs to be fully outfitted
# in each layout, what every product meets in every neighbourhood, the player's
# own shops of the type and what they really earn, the company's borrowing room
# -- and the board script does the arithmetic the reader moves: the building,
# the install mode, the marketing mix and the loan, as Plan a factory does.
# The profit rules are the game's own, read from its code and checked against
# 108 real shops; docs/dashboard-reference.md, "Open a store", writes them out.

_store_rules = None


def load_store_rules() -> dict:
    """ba_store_rules.json, read once: the game's tables a plan needs.

    `products` per item (wholesale and default price, sales ratio, whether it
    has a neighbourhood demand, a service, a ticket), `furniture` per item (the
    customers an hour it adds, the products it holds, its tags, what it stands
    on, who sells it), `types` per business type (products and their impact,
    requirements, customer demands), `hoods`, `banks` and `vendors`. Generated
    by make_store_rules.py and written to /data/ by the browser worker. A
    missing file is not an error: the view then has nothing to plan with.
    """
    global _store_rules
    if _store_rules is None:
        for path in (
            os.path.join(os.path.dirname(os.path.abspath(__file__)), "ba_store_rules.json"),
            "/data/ba_store_rules.json",  # where the worker puts it in a browser
        ):
            try:
                with open(path, encoding="utf-8") as fh:
                    loaded = json.load(fh)
                _store_rules = {part: loaded.get(part) or {} for part in STORE_RULE_PARTS}
                break
            except (OSError, ValueError, AttributeError):
                continue  # not here, or unreadable: try the next place
        else:
            _store_rules = {part: {} for part in STORE_RULE_PARTS}
    return _store_rules


STORE_RULE_PARTS = ("products", "furniture", "types", "hoods", "banks", "vendors", "vehicles", "skills")
# The building kinds a store can be planned in.
PLAN_KINDS = ("retail", "office", "cinema", "theater")
# The structural wage estimate (research PROFIT_MODEL.md, "Costs"): base
# hourly wages of a cashier, a cleaner and a security guard, which a skill of
# 100 lifts by 1 + 1.05^100 / 100, and the customers an hour one cashier serves.
PLAN_WAGES = {"cashier": 16, "cleaner": 12, "guard": 15, "perCashier": 30}
# An office's staff are its own profession (SkillData.baseHourlyWage, research
# PROFIT_COSTS.md, C1): one person at a computer bills one client an hour.
PLAN_OFFICE_WAGES = {
    "ba:skill_lawyer": 50, "ba:skill_programmer": 36, "ba:skill_graphicdesigner": 35,
    "ba:skill_eventplanner": 33, "ba:skill_travelagent": 31,
}
# The six campaigns (MARKETING_TYPES) by the plan's lowercase ids: price a
# day and the square metres each reaches. One of each at most per business.
MARKETING_CAMPAIGNS = tuple((name.lower(), price, reach) for name, price, reach in MARKETING_TYPES)
# The lenders' BankSettings assets carry rates and caps but no name and no
# address; these are the banks the game shows (research LOANS.md, section 1).
BANK_PLACES = {
    "VantanderBankSettings": ("Vantander Bank", ("ba:street_secondavenue", 6)),
    "JensenCapitalSettings": ("Jensen Capital", ("ba:street_fourthavenue", 17)),
}
LOAN_MINIMUM = 500  # Dialogs.BankDialog: less is "too low"
# Dialogs.BankDialog: while the tutorial is on and its objective "Get a $15,000
# loan from Jensen Capital" is open, a bank lends against at least this.
TUTORIAL_LOAN_FLOOR = 15500
TUTORIAL_LOAN_OBJECTIVE = "tutorial_quest_establish_first_business_objective_1"
# BoatTypes..cctor: each BoatData.type's price, which counts as the player's
# wealth. Hard-coded in the game, as the marketing campaigns are.
BOAT_PRICES = {0: 3_200_000, 1: 2_500_000, 2: 90_000_000}
# The satisfaction a well-run new shop settles at (all four parts near 95)
# where the player runs none of the type to take it from.
PLAN_SATISFACTION = 95
# What a shop of the player's own is measured over: its last finished trading
# days after the opening, the window the profit model was validated on.
OWN_PROFIT_DAYS = 14
# The days after its first sale a new shop still earns below its steady
# state (research RAMP.md: satisfaction starts at 50, new staff climb 0.6 an
# hour); the board's OS_RAMP holds the factors.
RAMP_DAYS = 5
# The shops a new one would take demand from, measured over their last week.
SALES_DAYS = 7
# FurnitureStoreManagerDialog: one flat fee per furniture delivery contract.
FURNITURE_DELIVERY_FEE = 250
# The item type bits that meet a customer demand (the items bundle's flags).
MUSIC_FLAG, SEATING_FLAG, SINK_FLAG, TOILET_FLAG = 1024, 4096, 16777216, 33554432
# WorkoutVarietyCustomerDemand: a gym's machines train this many distinct
# WorkoutExercise.workoutTypes (research NOTES.md, customer demands).
WORKOUT_VARIETY = 5
# Interior elements, floor slots and wall slots of each layout, read from the
# interiorDesigns of real saves (research NOTES.md, section 3); a layout the
# player rents is read from their own save instead. Wall counts vary by one or
# two between saves of the same layout.
LAYOUT_SLOTS = {
    "A1": (121, 75, 61), "A2": (176, 120, 74), "B1": (102, 54, 49), "C1": (290, 225, 84),
    "C2": (306, 225, 114), "D2": (416, 345, 95), "F1": (158, 96, 82), "J1": (444, 360, 107),
    "K1": (789, 660, 183), "L1": (294, 204, 114), "M1": (1296, 1131, 212),
    "R1": (2575, 1947, 1019), "S1": (2356, 1821, 943),
}


def _plan_initial(build_at_start, model: str | None, size_cap, type_slug: str, sqm, products) -> float:
    """The start of every open hour's arrivals for a store the model plans:
    _initial_customers(), shared with the staffing assistant's ceiling. An
    office starts from its building's customer capacity whatever build the
    game started on: every office in the saves checked on 29 Sep 2026, a game
    started on build 2701 among them, bills at the rate that capacity gives
    (check_profit_model.py), not its floor times the fee's sales ratio."""
    if model == "office":
        return _initial_customers(CAPPED_INITIAL_BUILD, size_cap, type_slug, sqm, products)
    return _initial_customers(build_at_start, size_cap, type_slug, sqm, products)


def demand_with(providers: int, default_price: float) -> float:
    """A product's expected neighbourhood demand with `providers` sellers
    (ProductMarketHelper.CalculateDemand): 100 less a step per seller past the
    few the item's price makes room for, drawn one below or at it, and 29 to
    34 once it bottoms out."""
    opt = optimal_providers(default_price)
    base = 100 - (providers * 100) // opt
    return min(100.0, base - 0.5) if base >= 30 else 31.5


def optimal_providers(default_price: float) -> int:
    """Item.GetOptimalProviders: how many sellers a neighbourhood holds before
    demand starts to fall, fewer for dear goods."""
    if not default_price:
        return 7
    return min(math.ceil(math.sqrt(1300 / default_price)), 7)


def decor_route(elements: int, floor_slots: int, wall_slots: int, materials: dict, target: int) -> dict | None:
    """The cheapest paid walls and floors that lift a bare shell to `target`.

    The game's score (InteriorScoreCalculator) is the floor of the average of
    two parts: the spend per interior element, at most 100, and the share of
    slots with a paid material. Every paid slot adds to both, so the cheapest
    route paints the cheapest kind of slot first. `materials` is
    ba_item_prices.json's table; only materials the designer sells count. None
    when the layout's slots are unknown or the target cannot be reached.
    """
    if not elements or not floor_slots and not wall_slots:
        return None
    if target <= 0:
        return {"floors": 0, "walls": 0, "floor": None, "wall": None, "cost": 0, "score": 0}

    def cheapest(kind):
        paid = [(m["p"], uuid) for uuid, m in materials.items()
                if m.get("t") == kind and m.get("b") and (m.get("p") or 0) > 0]
        return min(paid) if paid else None

    floor, wall = cheapest(1), cheapest(2)
    kinds = sorted([k for k in ((floor, floor_slots, "floor"), (wall, wall_slots, "wall")) if k[0]],
                   key=lambda k: k[0][0])
    slots = floor_slots + wall_slots
    painted = {"floor": 0, "wall": 0}
    spend = 0.0
    for (price, _uuid), room, kind in kinds:
        for _ in range(room):
            if math.floor((min(spend / elements, 100) + 100 * sum(painted.values()) / slots) / 2) >= target:
                break
            painted[kind] += 1
            spend += price
    score = math.floor((min(spend / elements, 100) + 100 * sum(painted.values()) / slots) / 2)
    if score < target:
        return None
    return {"floors": painted["floor"], "walls": painted["wall"],
            "floor": floor[1] if floor and painted["floor"] else None,
            "wall": wall[1] if wall and painted["wall"] else None,
            "floorPrice": floor[0] if floor else None, "wallPrice": wall[0] if wall else None,
            "cost": money(spend), "score": score}


def works_in(facts: dict, kind: str) -> bool:
    """Whether the game lets a piece of furniture work in a business type
    (`kind`, no prefix): its "Can only be used in ..." requirement, "o" the
    only types, "no" the types it does not work in. A piece whose requirement
    is unmet stands in the shop but the game leaves it out of the business
    (ItemHelper.HasAnyMissingRequirements): a concession stand register in a
    clothing store is no point of sale, though the opening check counts it.
    A business of no known type is not judged."""
    if not kind:
        return True
    only = facts.get("o")
    return (not only or kind in only) and kind not in (facts.get("no") or ())


def outfit_lines(type_slug: str, rules: dict, prices: dict, cap, sqm, copied=None) -> list:
    """What a 100% outfitted store of a type holds, as shopping-list lines.

    Each line is {"item", "qty", "group", "why"}: `group` is "req" (the
    type's requirements, one each), "cap" (the more of a capacity station it
    takes for its customers an hour to cover the building's `cap`), "dem" (one
    item per customer demand the type makes) or "shelf" (the displays), and
    `why` what the line answers: a requirement's name, a demand, or the
    products a display holds. Every item is one somebody sells, at its default
    price, and made for the type where the item names the types it is for;
    the cheapest one that does the job wins.

    The displays are `copied` -- (item, qty, products) from the player's own
    site of the type and layout -- and, for every product the type sells that
    those do not hold (all of them with nothing to copy), enough of its
    cheapest display for the building's customers an hour: a single one would
    cap the whole shop at its own rate (the game groups shelf capacity per
    product), and the profit model sells the type's whole range. A station
    that must stand on or beside other furniture (a computer on a desk, with a
    chair) takes the cheapest of each placement requirement's group. A gym's
    workout variety is WORKOUT_VARIETY distinct workout types among its
    machines. The interior-design demand is walls and floors, not an item.
    """
    t = (rules.get("types") or {}).get(type_slug) or {}
    furniture = rules.get("furniture") or {}
    table = prices.get("items") or {}
    products = rules.get("products") or {}
    cap = cap[0] if isinstance(cap, (list, tuple)) else cap
    cap = int(cap or 0)

    def price(name):
        return float((table.get(name) or {}).get("p") or 0)

    def flags(name):
        return int((table.get(name) or {}).get("t") or 0)

    def facts(name):
        return furniture.get(name) or {}

    kind = type_slug.removeprefix("ba:businesstype_")

    def sold(name, typed=True):
        """On sale, and made for this type where the item says what it is for
        (the designer's categories): a liquor store gets no cinema register.
        Those tags only sort the catalogue (FurnitureTagMatcher), never where
        a piece may stand, so an item that answers a customer demand (a
        speaker, a sink) is any the stores sell: `typed` False. Where the game
        itself limits a piece to some types, it is that (works_in())."""
        fits = facts(name).get("bt")
        return (price(name) > 0 and bool(facts(name).get("v")) and works_in(facts(name), kind)
                and (not typed or not fits or kind in fits))

    def mounts(name):
        """What a station has to be attached to: the cheapest sold piece of
        each placement requirement's group (a desk and a chair for a
        computer). A table written before the groups is one group."""
        groups = facts(name).get("m") or []
        if groups and not isinstance(groups[0], list):
            groups = [groups]
        out = []
        for group in groups:
            under = [m for m in group if sold(m)]
            # Where the designer made pieces for this type, one of those; else
            # one the station's own store sells, bought with it on the same
            # delivery (a computer's chair from the computer shop, not the
            # beach towel that also seats and costs least).
            stores = set(facts(name).get("v") or ())
            under = ([m for m in under if kind in (facts(m).get("bt") or ())]
                     or [m for m in under if stores & set(facts(m).get("v") or ())] or under)
            if under:
                out.append(min(under, key=lambda m: (price(m), m)))
        return out

    def unit_cost(name):
        return price(name) + sum(price(under) for under in mounts(name))

    def cheapest(names, typed=True):
        names = [n for n in names if sold(n, typed)]
        return min(names, key=lambda n: (unit_cost(n), n)) if names else None

    def sized(names):
        """The station that covers `cap` customers an hour for the least."""
        best = None
        for n in _in_order(set(names)):
            if not sold(n):
                continue
            rate = facts(n).get("c") or 0
            qty = max(1, math.ceil(cap / rate)) if rate and cap else 1
            key = (qty * unit_cost(n), -rate, n)
            if best is None or key < best[0]:
                best = (key, n, qty)
        return (best[1], best[2]) if best else (None, 0)

    lines = []

    def add(item, qty, group, why):
        if not item or qty <= 0:
            return
        lines.append({"item": item, "qty": int(qty), "group": group, "why": why})
        for under in mounts(item):
            lines.append({"item": under, "qty": int(qty), "group": group, "why": "mount"})

    def held():
        return {line["item"] for line in lines}

    shelf_products = []
    for req in t.get("rq") or ():
        if req.get("any") or req.get("lic"):
            continue  # a product on a shelf (the displays), or a fee paid in game
        if req.get("i"):
            names = [n for n in req["i"] if n in furniture]
            if not names:
                # A requirement for stock on a shelf (a hairdresser's hair-care
                # product) is a display for that product.
                shelf_products.extend(n for n in req["i"] if n in products)
                continue
        elif req.get("t"):
            names = [n for n, row in table.items() if flags(n) & req["t"] and n in furniture]
        else:
            continue
        name = req.get("n") or ""
        if req.get("sq"):
            item = cheapest(names)
            qty = min(math.ceil(float(sqm or 0) / req["sq"]), req.get("mx") or 1) if sqm else 1
            add(item, max(1, qty), "req", name)
            continue
        item, qty = sized(names)
        add(item, 1, "req", name)
        if qty > 1:
            add(item, qty - 1, "cap", name)

    demands = [d for d, weight in t.get("dm") or () if weight and weight > 0]

    def has(pred):
        return any(pred(n) for n in held())

    for demand in demands:
        if demand == "music" and not has(lambda n: flags(n) & MUSIC_FLAG):
            add(cheapest([n for n in furniture if flags(n) & MUSIC_FLAG], False), 1, "dem", demand)
        elif demand == "seating" and not has(lambda n: flags(n) & SEATING_FLAG):
            add(cheapest([n for n in furniture if flags(n) & SEATING_FLAG], False), 1, "dem", demand)
        elif demand == "sink" and not has(lambda n: flags(n) & SINK_FLAG):
            add(cheapest([n for n in furniture if flags(n) & SINK_FLAG], False), 1, "dem", demand)
        elif demand == "employeeuniforms" and not has(lambda n: "uniform" in (facts(n).get("x") or ())):
            add(cheapest([n for n in furniture if "uniform" in (facts(n).get("x") or ())], False), 1, "dem", demand)
        elif demand in ("toilet", "toiletprivacy") and not has(lambda n: flags(n) & TOILET_FLAG):
            # One stall meets both: it is a toilet, and the first toilet found
            # carries the privacy tag. A plain toilet beside it could be the
            # one found first and fail the privacy demand.
            private = "toiletprivacy" in demands
            pool = [n for n in furniture if flags(n) & TOILET_FLAG
                    and (not private or "privacy" in (facts(n).get("x") or ()))]
            add(cheapest(pool, False), 1, "dem", "toilet+privacy" if private and "toilet" in demands else demand)
        elif demand == "workoutvariety":
            # The cheapest machine of each workout type the gym does not train
            # yet, until WORKOUT_VARIETY distinct types stand in it.
            trained = {facts(n).get("wt") for n in held() if facts(n).get("wt") is not None}
            offer = {}
            for n in _in_order({n for n in furniture if facts(n).get("wt") is not None}):
                if sold(n) and facts(n)["wt"] not in trained:
                    key = (unit_cost(n), n)
                    if facts(n)["wt"] not in offer or key < offer[facts(n)["wt"]][0]:
                        offer[facts(n)["wt"]] = (key, n)
            for _key, n in sorted(offer.values())[:max(0, WORKOUT_VARIETY - len(trained))]:
                add(n, 1, "dem", demand)

    # A cinema's or a theatre's audience sits: the seats made for the venue
    # (the cheapest a seat), enough for the building's customers an hour,
    # shared across a cinema's screens so each screen seats its part.
    if t.get("b") in ("cinema", "theater") and cap:
        seats = [n for n in furniture if (facts(n).get("st") or 0) > 0 and kind in (facts(n).get("bt") or ()) and sold(n)]
        if seats:
            screens = sum(line["qty"] for line in lines if line["why"] == "cinemascreen") or 1
            for seat, qty in _cheapest_cover(math.ceil(cap / screens), {n: (facts(n)["st"], unit_cost(n)) for n in seats}):
                add(seat, screens * qty, "cap", "seats")

    covered = set()
    for item, qty, held_products in copied or ():
        add(item, qty, "shelf", list(held_products) or "storage")
        covered.update(held_products)
    # Every product the model sells needs a display: the copied shelves' own,
    # else enough of its cheapest. A display several products share is summed
    # first and added once, so what it stands on counts it whole.
    shelves = {}
    for p in [*(p for p, _impact in t.get("i") or ()), *shelf_products]:
        row = products.get(p) or {}
        if p in covered or row.get("s") or row.get("k") or p in (t.get("f"), t.get("fw")):
            continue  # shown already, or a service, a ticket or an entrance fee: no shelf
        shows = [n for n, f in furniture.items() if p in (f.get("h") or ()) and (f.get("c") or 0) > 0]
        item, qty = sized(shows)
        if not item:
            continue
        got = shelves.setdefault(item, [0, []])
        got[0] += qty
        got[1].append(p)
    for item, (qty, held_products) in shelves.items():
        add(item, qty, "shelf", held_products)
    return lines


def plan_layout(row: dict) -> str | None:
    """What a plan's outfit is kept by: a building's layout (size and version,
    a premises row's `layout` or a ba_buildings.json row). A cinema or a
    theatre has no floor plan, so no `layout`, but each version seats its own
    crowd (S1 150, S3 100): its size and version from the building table.
    The board reads the same key (osLayout(), from `venues`)."""
    if "layout" in row or "size" in row:
        if row.get("layout"):
            return row["layout"]
        street, _, number = str(row.get("key") or "").partition("#")
        found = load_buildings().get((street, int(number))) if number.isdigit() else None
        return plan_layout(found) if found else row.get("size")
    if row.get("z") and row.get("v") is not None and not _layout(row):
        return f"{row['z']}{row['v']}"
    return _layout(row) or row.get("z")


def _venue_caps(names: Names) -> dict:
    """{size and version: customer capacity} for the cinemas and theatres
    (S1 150, S2 125, S3 100; R1 200 ...), from the same rows _door_caps()
    reads (_cap_rows()). An outfit is planned per layout, so a theatre's are
    kept exact here even where the finder shows its letter's range."""
    return {code: cap for section, _letter, code, cap in _cap_rows(names)
            if section in ("cinema", "theater")}


def _building_row(reg: dict) -> dict:
    return load_buildings().get(_address_of(reg)) or {}


def _cheapest_cover(need: int, pieces: dict) -> list:
    """[(piece, count)] whose places add up to `need` or more for the least:
    `pieces` is {piece: (places, price)}. Six four-seat rows and a single seat
    can beat seven rows."""
    if need <= 0 or not pieces:
        return []
    top = need + max(places for places, _price in pieces.values())
    best = [(0.0, None)] + [(math.inf, None)] * top
    for total in range(1, top + 1):
        for name in sorted(pieces):
            places, price = pieces[name]
            if places <= total and best[total - places][0] + price < best[total][0]:
                best[total] = (best[total - places][0] + price, name)
    total = min(range(need, top + 1), key=lambda n: (best[n][0], n))
    counts = collections.Counter()
    while total > 0 and best[total][1]:
        name = best[total][1]
        counts[name] += 1
        total -= pieces[name][0]
    return sorted(counts.items())


def _setup_items(lines: list) -> list:
    """Outfit lines as setup_cost()'s (item, price paid) pairs: nothing is paid
    yet, so every piece counts at its default price."""
    return [(line["item"], None) for line in lines for _ in range(line["qty"])]


def _layout_slots(save: Save, regs: list, prices: dict) -> dict:
    """{layout: (elements, floor slots, wall slots)}: LAYOUT_SLOTS, with each
    layout the player rents read off its own interiorDesigns."""
    table = load_buildings()
    materials = prices.get("materials") or {}
    out = dict(LAYOUT_SLOTS)
    for reg in regs:
        layout = _layout(table.get(_address_of(reg)) or {})
        if not layout:
            continue
        designs = list(save.items(reg.get("interiorDesigns")))
        floors = walls = 0
        for design in designs:
            for slot in save.items((save.deref(design) or {}).get("materials")):
                kind = (materials.get(slot.get("MaterialID")) or {}).get("t") if isinstance(slot, dict) else None
                floors += kind == 1
                walls += kind == 2
        if designs and floors:
            out[layout] = (len(designs), floors, walls)
    return out


def _copied_shelving(save: Save, reg: dict, type_slug: str, rules: dict) -> list:
    """The displays and stock shelves at one of the player's own sites, as
    (item, count, products it holds for the type) -- what a plan of the same
    type and layout copies."""
    furniture = rules.get("furniture") or {}
    sells = {p for p, _impact in ((rules.get("types") or {}).get(type_slug) or {}).get("i") or ()}
    counts = collections.Counter()
    for item in _item_instances(save, reg.get("itemInstances")):
        name = item.get("itemName")
        if name:
            counts[name] += 1
    out = []
    for name in _in_order(counts):
        facts = furniture.get(name) or {}
        holds = sorted(sells & set(facts.get("h") or ()))
        if holds or "storage" in (facts.get("x") or ()):
            out.append((name, counts[name], holds))
    return out


def required_placed(placed: collections.Counter, type_slug: str, rules: dict, prices: dict, sqm,
                    available=None, stocked=None) -> list:
    """What a business of a type still lacks of its opening requirements.

    `placed` counts the item names standing in it. Each row is [requirement
    name, needed, placed]: a requirement is met by any item of its named set
    or carrying its tag, one of them, or for a per-area one (sinks and toilet
    stalls in an office) one per `sq` m², at most `mx` when the rule has one.
    The stock shelf every shop needs (`any`) is met by a display for a product
    the type sells. `available` is
    the registration's cachedAvailableProducts, when the save has it: a
    product the shop lists as available meets either requirement even where
    the displays are not known to hold it. A requirement that names a product
    is met only by that availability or by the product actually on a display
    (`stocked`, the cargo in the placed items): an empty shelf can hold it but
    does not. A fee paid in game (`lic`) is not furniture and has no row.
    """
    t = (rules.get("types") or {}).get(type_slug) or {}
    furniture = rules.get("furniture") or {}
    table = prices.get("items") or {}
    sells = {p for p, _impact in t.get("i") or ()}
    offered = set(available or ())
    kind = type_slug.removeprefix("ba:businesstype_")

    def holding(products) -> int:
        return sum(n for name, n in placed.items() if products & set((furniture.get(name) or {}).get("h") or ()))

    on_display = set(stocked or ())

    out = []
    for req in t.get("rq") or ():
        if req.get("lic"):
            continue
        if req.get("any"):
            have = holding(sells)
            if not have and sells & offered:
                have = 1
            out.append([req.get("n") or "", 1, have])
            continue
        if req.get("i") and any(n not in furniture for n in req["i"]):
            products = {n for n in req["i"] if n not in furniture}
            have = sum(placed[n] for n in req["i"] if n in furniture and n in placed)
            if not have and products & (offered | on_display):
                have = 1
            out.append([req.get("n") or "", 1, have])
            continue
        if req.get("i"):
            names = set(req["i"])
        elif req.get("t"):
            names = {n for n in placed if int((table.get(n) or {}).get("t") or 0) & req["t"]}
        else:
            continue
        need = 1
        if req.get("sq"):
            need = max(1, math.ceil(float(sqm) / req["sq"])) if sqm else 1
            if req.get("mx"):
                need = min(need, req["mx"])
        # A piece the type cannot use is no help, though the game's own opening
        # check counts it (works_in()).
        out.append([req.get("n") or "", need, sum(placed[n] for n in names if n in placed and works_in(furniture.get(n) or {}, kind))])
    return out


def _placed_items(save: Save, reg: dict) -> collections.Counter:
    """The furniture standing in a rented building, per item name."""
    placed = collections.Counter()
    for item in _item_instances(save, reg.get("itemInstances")):
        if item.get("itemName"):
            placed[item["itemName"]] += 1
    return placed


def _stocked_products(save: Save, reg: dict, furniture: dict) -> set:
    """The products actually on a building's displays: cargo with an amount,
    held by an item whose furniture facts (`h`) list that product. Stock in
    storage shelving is not on display."""
    out = set()
    for item in _item_instances(save, reg.get("itemInstances")):
        shows = set((furniture.get(item.get("itemName")) or {}).get("h") or ())
        for cargo in save.items(item.get("cargoInstances")):
            if cargo.get("itemName") in shows and (cargo.get("amount") or 0) > 0:
                out.add(cargo["itemName"])
    return out


def _opened_stores(save: Save, regs: dict, businesses: list, types: dict, rules: dict, prices: dict) -> dict:
    """{site key: {"placed", "req", "seating", "sells"}} for every business of a
    planned type: how much furniture stands in it, which opening requirements
    it meets, whether anything to sit on does, and what it offers for sale
    (cachedAvailableProducts, which the game counts it a provider of). The
    checklist until opening reads it (Open a store, step 5); the model reads
    `sells` for a store already at a plan's address."""
    out = {}
    table = prices.get("items") or {}
    for b in businesses:
        reg = regs.get(b.get("key"))
        if reg is None or b.get("typeSlug") not in types or b.get("status") == "vacant":
            continue
        placed = _placed_items(save, reg)
        available = {n for n in save.items(reg.get("cachedAvailableProducts")) if isinstance(n, str)}
        out[b["key"]] = {
            "placed": sum(placed.values()),
            "req": required_placed(placed, b["typeSlug"], rules, prices, _building_row(reg).get("m"), available,
                                   _stocked_products(save, reg, rules.get("furniture") or {})),
            "seating": any(int((table.get(n) or {}).get("t") or 0) & SEATING_FLAG for n in placed),
            "sells": sorted(available),
        }
    return out


def _store_market(save: Save, rules: dict, items: set, mpm: float, agent: int) -> dict:
    """What each product meets in each neighbourhood today.

    Per item: its default price, sales ratio, whether it has a neighbourhood
    demand, whether it is a service, how many sellers the market holds before
    demand falls (`opt`) and the import unit cost -- wholesale x the save's
    import price index x the difficulty's price multiplier x the best
    purchasing agent's discount, never the income statement's goods, which
    are near nothing where the player's own factories supply. Per
    neighbourhood: the sellers there now (the player's included), whether a
    rival company sells it (no monopoly bonus then), the lowest price asked
    there (a rival's for what it stocks, the player's as set), and the last day
    anyone sold it there (NeighborhoodDemand.lastDaySold), which a first
    seller's hype waits on.
    """
    table = load_buildings()
    products = rules.get("products") or {}
    idx, sellers, last_sold = {}, {}, {}
    for entry in save.items(save.root.get("productMarketEntries")):
        name = entry.get("itemName") if isinstance(entry, dict) else None
        if name not in items:
            continue
        idx[name] = entry.get("importPriceIndex") or 1.0
        for value in save.items(entry.get("demandValues")):
            hood = value.get("neighborhood")
            if hood and hood != GLOBAL_HOOD:
                sellers[(name, hood)] = int(value.get("providers") or 0)
                # NeighborhoodDemand.lastDaySold: a hype waits on 21 days without
                # it. Every save the board reads (MIN_BUILD on) has it; None where one does not.
                last = value.get("lastDaySold")
                last_sold[(name, hood)] = int(last) if isinstance(last, (int, float)) else None
    # The lowest price a customer sees there: the player's own shops at their
    # configured price, stocked or not (PROFIT_MODEL.md), and a rival's only
    # for an item on its shelves (cachedAvailableProducts).
    rival_sells, lowest = set(), {}
    for reg in save.items(save.root.get("BuildingRegistrations")):
        if not reg or not reg.get("BusinessName") or reg.get("temporarilyClosed"):
            continue
        hood = hood_key(table.get(_address_of(reg)))
        if not hood:
            continue
        stocked = {n for n in save.items(reg.get("cachedAvailableProducts")) if isinstance(n, str) and n in items}
        for line in save.items(reg.get("retailPrices")):
            name = line.get("itemName") if isinstance(line, dict) else None
            price = _configured_price(line.get("price")) if name in stocked or (
                reg.get("RentedByPlayer") and name in items) else None
            if price:
                lowest[(name, hood)] = min(lowest.get((name, hood), price), price)
        if reg.get("businessOwnerRivalId"):
            rival_sells.update((name, hood) for name in stocked)
    discount = 1 - 0.25 * max(0, min(100, agent)) / 100
    hoods = _in_order({h for (_n, h) in sellers} | {h for (_n, h) in lowest})
    out = {}
    for name in _in_order(items):
        row = products.get(name) or {}
        out[name] = {
            "p": row.get("p") or 0,
            "r": row.get("r") or 0,
            "d": row.get("d") or 0,
            "s": row.get("s") or 0,
            "opt": optimal_providers(row.get("p") or 0),
            "cost": round((row.get("w") or 0) * idx.get(name, 1.0) * mpm * discount, 4),
            **({"only": row["l"]} if row.get("l") else {}),
            "hoods": {hood: [sellers.get((name, hood), 0), int((name, hood) in rival_sells),
                             lowest.get((name, hood)), last_sold.get((name, hood))] for hood in hoods},
        }
    return out


def _own_shops(save: Save, regs: dict, businesses: list, grids: list, stmt_history: list,
               market: dict, caps: dict, day: int, models: dict) -> dict:
    """Per business type, each of the player's trading shops as the profit
    model sees it, with what it really earned.

    What it earned is the average of its last OWN_PROFIT_DAYS finished days
    after its first day with sales: sales less every unit sold at the import
    cost, wages, rent, marketing and licensing fees. A shop can stand a few
    days between its setup and its first sale, and those days hold costs and
    no sales, so the window starts from the sales, not the lease (research
    RAMP.md, 3c). The board runs the model over the shop's own building,
    hours and marketing and puts the two side by side; `k`, for a shop still
    in its first days, is each window day's distance from that first sale, so
    the board holds it to its ramp (osDayProfit()).
    """
    table = load_buildings()
    hours = {g["key"]: g.get("open") for g in grids}
    # An office bills one client an hour per staffed computer, so its own
    # staffing bounds what it can earn; a shop's stations are the model's.
    staffed = {g["key"]: g.get("staffed") for g in grids if g.get("office")}
    out = collections.defaultdict(list)
    for b in businesses:
        slug = b.get("typeSlug")
        reg = regs.get(b["key"])
        if b.get("status") not in ("retail", "office") or not reg:
            continue
        addr = _address_of(reg, strict=True)
        row = table.get(addr) or {}
        opened = b.get("opened") or 0
        orders = {e.get("dayNumber"): e for e in save.items(reg.get("orderHistory"))}
        sold_on = [d for d, by in stmt_history if addr in by and d >= opened and (by[addr].get("TotalSales") or 0) > 0]
        sold_on += [d for d, e in orders.items() if isinstance(d, int) and d >= opened
                    and any((s.get("amountSold") or 0) > 0 for s in save.items(e.get("itemSales")))]
        first = min(sold_on) if sold_on else opened + 1
        by_day = {d: by[addr] for d, by in stmt_history if addr in by and first < d < day}
        days = sorted(d for d in by_day if d in orders)[-OWN_PROFIT_DAYS:]
        if len(days) < 3:
            continue
        cost = 0.0
        sold = collections.Counter()
        for d in days:
            for sale in save.items(orders[d].get("itemSales")):
                name = sale.get("itemName")
                sold[name] += sale.get("amountSold", 0)
                cost += sale.get("amountSold", 0) * ((market.get(name) or {}).get("cost") or 0)
        n = len(days)
        total = sum(by_day[d].get("TotalSales", 0) - by_day[d].get("SalaryExpenses", 0)
                    - by_day[d].get("RentExpenses", 0) - by_day[d].get("MarketingExpenses", 0)
                    - by_day[d].get("LicensingFees", 0) for d in days)
        door = _size_cap(row, caps)
        # What the game starts each hour from for this shop: its own shelves
        # in an old game, as _plan_site() reads them.
        initial = _plan_initial(save.root.get("buildNumberAtStart"), models.get(slug), door, slug,
                                row.get("m") or 0, save.items(reg.get("cachedAvailableProducts")))
        out[slug].append({
            "key": b["key"],
            "hood": b.get("neighbourhood"),
            "layout": plan_layout(row),
            "m2": row.get("m"),
            "cap": door[0] if isinstance(door, list) else door,
            "initial": round(initial, 4),
            "promo": b.get("promotion") or 0,
            "marketing": money(sum(by_day[d].get("MarketingExpenses", 0) for d in days) / n),
            "open": hours.get(b["key"]),
            "sat": (b.get("satisfaction") or {}).get("overall"),
            "actual": money((total - cost) / n),
            "days": n,
            **({"k": [d - first for d in days]} if days[0] - first < RAMP_DAYS else {}),
            **({"staffed": staffed[b["key"]]} if models.get(slug) == "office" and staffed.get(b["key"]) else {}),
        })
    return {slug: sorted(rows, key=lambda r: r["key"]) for slug, rows in out.items()}


def _own_sales(save: Save, regs: dict, businesses: list, market: dict, day: int) -> dict:
    """{hood: {item: [[site key, units a day, margin a unit]]}}: what the
    player's own shops sell of each planned product in each neighbourhood over
    their last SALES_DAYS days, for the demand a new shop there takes away."""
    out = collections.defaultdict(lambda: collections.defaultdict(list))
    for b in businesses:
        reg = regs.get(b["key"])
        hood = b.get("neighbourhood")
        if not reg or not hood or b.get("status") != "retail":
            continue
        recent = [e for e in save.items(reg.get("orderHistory")) if e.get("dayNumber", day) < day][-SALES_DAYS:]
        if not recent:
            continue
        units, takings = collections.Counter(), collections.Counter()
        for entry in recent:
            for sale in save.items(entry.get("itemSales")):
                name = sale.get("itemName")
                if name in market:
                    units[name] += sale.get("amountSold", 0)
                    takings[name] += sale.get("totalPrice", 0)
        for name in _in_order(units):
            if units[name] <= 0:
                continue
            per_unit = takings[name] / units[name] - market[name]["cost"]
            out[hood][name].append([b["key"], round(units[name] / len(recent), 2), round(per_unit, 2)])
    return {hood: dict(items) for hood, items in sorted(out.items())}


def _finance_facts(save: Save, daily: list, rules: dict) -> dict:
    """What the banks weigh before they lend (Dialogs.BankDialog.LoanRequest),
    and their terms.

    The most a bank lends is the lower of its own cap less what the company
    owes it, and the largest of the player's wealth, a quarter of the last
    seven days' average profit over the loan's term and, while the tutorial
    still asks for the first loan, TUTORIAL_LOAN_FLOOR, less everything owed.
    Wealth (PlayerHelper.GetPersonalWealth) is cash, investment funds, the
    motor vehicles at their type's price (ba_store_rules.json), the boats at
    theirs (BOAT_PRICES) and the property bought. A loan is the bank's whose
    address it names; one at an address that is no bank still counts in
    what is owed overall.
    """
    root = save.root
    gv = save.deref(root.get("gameVariables")) or {}
    funds = 0.0
    for fund in save.items(root.get("investmentFunds")):
        fund = save.deref(fund) or {}
        funds += (fund.get("initialDeposit") or 0) + (fund.get("additionalInvestment") or 0) \
            - (fund.get("withdrawal") or 0) + (fund.get("interestPayment") or 0)
    property_ = sum((save.deref(e) or {}).get("purchasePrice") or 0 for e in save.items(root.get("realEstate")))
    prices = rules.get("vehicles") or {}
    vehicles = sum(prices.get((save.deref(v) or {}).get("vehicleTypeName"), 0)
                   for v in save.items(root.get("VehicleInstances")))
    boats = sum(BOAT_PRICES.get((save.deref(b) or {}).get("type"), 0) for b in save.items(root.get("playerBoats")))
    done = set(save.items(root.get("CompletedQuestEntries")))
    tutorial = bool(gv.get("tutorialEnabled")) and TUTORIAL_LOAN_OBJECTIVE not in done
    places = {site_key(addr): bank for bank, (_n, addr) in BANK_PLACES.items()}
    owed = collections.Counter()
    for loan in save.items(root.get("Loans")):
        loan = save.deref(loan) or {}
        addr = save.address(loan.get("bankAddress"))
        owed[places.get(site_key(addr)) if addr else None] += loan.get("remainingAmount") or 0
    last = [d["profit"] for d in daily[-7:]]
    per_year = gv.get("daysPerYear") or 60
    banks = []
    for bank, terms in sorted((rules.get("banks") or {}).items()):
        name, addr = BANK_PLACES.get(bank, (bank, None))
        banks.append({
            "id": bank, "name": name, "key": site_key(addr) if addr else None,
            "rate": terms.get("r") or 0, "years": terms.get("y") or 0, "max": terms.get("x") or 0,
            "term": per_year * (terms.get("y") or 0), "owed": money(owed.get(bank, 0)),
        })
    return {
        "cash": money(root.get("Money") or 0),
        "wealth": money((root.get("Money") or 0) + funds + vehicles + boats + property_),
        "floor": TUTORIAL_LOAN_FLOOR if tutorial else 0,
        "profit7": money(sum(last) / 7) if last else 0,
        "owed": money(sum(owed.values())),
        "multiplier": round(gv.get("bankInterestMultiplier") or 0.7, 4),
        "year": per_year,
        "minimum": LOAN_MINIMUM,
        "banks": banks,
    }


def _open_store(save: Save, names: Names, regs_list: list, businesses: list, premises: dict,
                grids: list, stmt_history: list, daily: list, staff: list) -> dict:
    """The facts Expansion › Open a store plans with (see the section note)."""
    rules = load_store_rules()
    if not rules.get("types"):
        return {}
    prices = load_item_prices()
    root = save.root
    day = root["Day"]
    gv = save.deref(root.get("gameVariables")) or {}
    mpm = gv.get("marketPriceMultiplier") or 1.0
    # The best purchasing agent's skill sets the import discount; a company
    # with none yet is planned as if it hires a good one, as its shops will.
    agents = [p.get("level") or 0 for p in staff if p.get("skill") == "ba:skill_purchasingagent"]
    agent = int(max(agents)) if agents else 100
    regs = {site_key(_address_of(r, strict=True)): r for r in regs_list}
    caps = premises.get("caps") or {}
    buildings = premises.get("buildings") or []

    types, items_used, product_items, models = {}, set(), set(), {}
    venue_caps = _venue_caps(names)
    slots = _layout_slots(save, regs_list, prices)
    build_at_start = root.get("buildNumberAtStart")
    for slug, t in sorted((rules.get("types") or {}).items()):
        cat = t.get("b")
        if not t.get("c") or slug not in RETAIL_TYPES | OFFICE_TYPES or cat not in PLAN_KINDS:
            continue
        # The rules reproduce shops and offices; a cinema's screens and seats
        # and a theatre's actors cap them in ways the model does not follow.
        model = "office" if slug in OFFICE_TYPES else None if cat in ("cinema", "theater") else "retail"
        models[slug] = model
        sells = [[p, round(impact, 4)] for p, impact in t.get("i") or ()]
        own = [b for b in businesses if b.get("typeSlug") == slug and b.get("status") != "vacant"]
        layouts, initial = {}, {}
        for layout in _in_order({plan_layout(b) for b in buildings if b["type"] == cat and plan_layout(b)
                                 and b["status"] in ("vacant", "rival", "mine")}):
            sample = next(b for b in buildings if b["type"] == cat and plan_layout(b) == layout)
            source = None
            same = [b for b in own if b["key"] in regs and plan_layout(_building_row(regs[b["key"]])) == layout]
            if same:
                source = max(same, key=lambda b: (sum(s["profit"] for s in (b.get("series") or [])[-7:]), b["key"]))
            copied = _copied_shelving(save, regs[source["key"]], slug, rules) if source else None
            # A venue's own version seats its own crowd, not the size's lowest.
            cap = venue_caps.get(layout, sample.get("cap")) if cat in ("cinema", "theater") else sample.get("cap")
            lines = outfit_lines(slug, rules, prices, cap, sample.get("m2"), copied)
            cost = setup_cost(_setup_items(lines), [], sample.get("m2"), 0, prices)
            items_used.update(line["item"] for line in lines)
            layouts[layout] = {
                "lines": [[line["item"], line["qty"], line["group"], line["why"]] for line in lines],
                "furniture": cost["furniture"],
                "fee": cost["fee"],
                "from": source["key"] if source else None,
            }
            # The shop fully stocked with the type's range, as the plan has it.
            initial[layout] = round(_plan_initial(build_at_start, model, cap, slug,
                                                  sample.get("m2"), [p for p, _i in sells]), 4)
        if not layouts:
            continue
        product_items.update(p for p, _i in sells)
        product_items.update(x for x in (t.get("f"), t.get("fw")) if x)
        curve = load_demand_curves()["types"].get(slug) or {}
        types[slug] = {
            "cat": cat,
            "model": model,
            "products": sells,
            "fee": t.get("f"),
            "feeWeekend": t.get("fw"),
            "amt": t.get("a") or 1,
            "noOrder": bool(t.get("n")),
            "days": curve.get("d") or [1.0] * 7,
            "hours": curve.get("h") or [1.0] * 24,
            "demands": [[d, w] for d, w in t.get("dm") or ()],
            "run": len(own),
            "layouts": layouts,
            "initial": initial,
            # An office's hourly wage at skill 0 for the profession it bills.
            **({"wage": max((PLAN_OFFICE_WAGES.get(k, 0) for k in t.get("sk") or ()), default=0)}
               if model == "office" else {}),
        }

    market = _store_market(save, rules, product_items, mpm, agent)
    # The cheapest walls and floors to each interior score a neighbourhood
    # asks for (Midtown's 50 today), per layout: {layout: {score: route}}.
    decor = {}
    materials = prices.get("materials") or {}
    targets = sorted({int(h.get("mi") or 0) for h in (rules.get("hoods") or {}).values()} - {0})
    for layout in _in_order({layout for t in types.values() for layout in t["layouts"]}):
        # A layout nobody has read is costed as another version of its size.
        near = layout if layout in slots else next((k for k in sorted(slots) if k[:1] == layout[:1]), None)
        for target in targets:
            route = decor_route(*slots[near], materials, target) if near else None
            if route:
                decor.setdefault(layout, {})[str(target)] = {**route, **({"like": near} if near != layout else {})}
    hoods = {}
    for hood, h in sorted((rules.get("hoods") or {}).items()):
        shares = (h.get("w") or 0, h.get("m") or 0, h.get("u") or 0)
        total = sum(shares) or 1
        hoods[hood] = {
            # CitizenHelper.Init: the price everyone accepts, as a multiple of
            # the reference price.
            "idx": round((1.2 * shares[0] + 1.4 * shares[1] + 1.7 * shares[2]) / total, 4),
            "strength": h.get("ms") or 0,
            "demands": h.get("cw") or 0,
            "interior": h.get("mi") or 0,
        }
    furniture = rules.get("furniture") or {}
    table = prices.get("items") or {}
    vendors = rules.get("vendors") or {}
    used_vendors = {v for item in items_used for v in (furniture.get(item) or {}).get("v") or ()}
    return {
        "game": {
            "promo": round(gv.get("baseCustomerPromotionMultiplier") or 0.55, 4),
            "prices": round(mpm, 4),
            "wages": round(gv.get("employeeHourlySalaryMultiplier") or 0.7, 4),
            "tax": gv.get("taxPercentage") or 0,
            "capInitial": (build_at_start or 0) >= CAPPED_INITIAL_BUILD,
            "agent": agent,
            "installFee": INSTALL_FEE_PER_M2,
            "delivery": FURNITURE_DELIVERY_FEE,
            "satisfaction": PLAN_SATISFACTION,
            "wageBase": PLAN_WAGES,
        },
        "types": types,
        "market": market,
        "hoods": hoods,
        "decor": decor,
        "items": {item: {"p": float((table.get(item) or {}).get("p") or 0),
                         "v": (furniture.get(item) or {}).get("v") or []} for item in _in_order(items_used)},
        "vendors": {key: vendors[key] for key in _in_order(used_vendors) if key in vendors},
        "own": _own_shops(save, regs, businesses, grids, stmt_history, market, caps, day, models),
        "sales": _own_sales(save, regs, businesses, market, day),
        "built": _opened_stores(save, regs, businesses, types, rules, prices),
        "campaigns": [list(c) for c in MARKETING_CAMPAIGNS],
        # Each cinema and theatre: its size and version, and what that seats.
        "venues": {b["key"]: [plan_layout(b), venue_caps.get(plan_layout(b))]
                   for b in buildings if b["type"] in ("cinema", "theater") and plan_layout(b)},
        "finance": _finance_facts(save, daily, rules),
    }


# ----------------------------------------------------------- plan a factory
# Expansion › Plan a factory (issue #172, mockup/factory-flow/NOTES.md on the
# factory-flow-canvas branch): the facts a factory plan is priced from. As for
# a store, Python says what the save and the game's tables hold and the board
# does the arithmetic the reader moves (the lines, the building, the install
# mode, the loan). No break-even: a factory is a cost centre of its chain.
# The vehicle a factory plans, and a depot the plan adds: the game's own
# delivery vehicles. A Freight Truck T1 wants a driver at 95% skill, a Vord
# Courier D500 one at 75% (the help pages). Both are sold by General US Trucks.
FACTORY_TRUCK = "ba:vehicletype_freighttruckt1"
DEPOT_VAN = "ba:vehicletype_deliverytruck"
VEHICLE_DEALER = ("General US Trucks", "ba:street_seventhavenue#1", "ba:neighborhood_industrycity")
PALLET_SHELF = "ba:itemname_palletshelf"
# The game pays a delivery driver a flat 5.7 hours a day, whatever the round
# takes (NOTES.md, decision 15); a hire at headquarters is planned at 40 h.
DRIVER_DAY_HOURS = 5.7
HQ_WEEK_HOURS = 40


def _factory_kits(names: Names, prices: dict) -> dict:
    """Each workstation's kit, priced: {workstation: [[item, price], ...]},
    the assembly machine first, as the help page lists them."""
    table = prices.get("items") or {}
    out = {}
    for key, text in sorted(names.locale.items()):
        match = re.match(r"^help_factory_workstation_([a-z0-9]+)_content$", key)
        if not match:
            continue
        machines, _, rest = text.partition("To an Assembly Machine")
        assembly = rest.partition("can be used to create")[0]
        kit = ["ba:itemname_" + s for _n, s in _FURNITURE_RE.findall(assembly)]
        kit += ["ba:itemname_" + s for _n, s in _FURNITURE_RE.findall(machines)]
        out[match.group(1)] = [[item, float((table.get(item) or {}).get("p") or 0)]
                               for item in dict.fromkeys(kit)]
    return out


def _factory_days(save: Save, reg: dict) -> dict:
    """What left a factory each finished day, per item:
    {"first": day, "out": {item: [units a day, ...]}, "sold": {item: [...]}},
    each list one entry a day from `first` to yesterday.

    The save keeps no count of what a factory made. What it keeps is what
    left: its delivery log (deliveryTransactions, the last DELIVERY_LOG_SIZE
    transactions), where every pickup is a negative amount -- the logistics
    rounds to the player's own sites and the piers' pickup of the exports
    alike -- and its sales (orderHistory's itemSales, amountSold), which are
    the exports alone and count the same units again. So `out` is the log's
    goods leaving, and `sold` (None on a day the sales history no longer
    holds; `covered` says which days it holds) the part of it sold to the piers. A full log has lost part of its
    oldest day, so that day is left out; today is still running and is left
    out too. What is made and still held is in neither. {} with no log.
    """
    today = save.root.get("Day")
    log = [t for t in save.items(reg.get("deliveryTransactions")) if isinstance(t, dict) and isinstance(t.get("dayOfDelivery"), int)]
    if not log:
        return {}
    out = collections.defaultdict(collections.Counter)
    for t in log:
        for e in save.items(t.get("deliveryItems")):
            amount = (e.get("amountDelivered") or 0) if isinstance(e, dict) else 0
            if amount < 0 and isinstance(e.get("itemName"), str):
                out[e["itemName"]][t["dayOfDelivery"]] -= amount
    sold = collections.defaultdict(dict)
    covered = set()
    for e in save.items(reg.get("orderHistory")):
        if isinstance(e, dict) and isinstance(e.get("dayNumber"), int):
            covered.add(e["dayNumber"])
            for s_ in save.items(e.get("itemSales")):
                if isinstance(s_, dict) and isinstance(s_.get("itemName"), str) and s_.get("amountSold"):
                    sold[s_["itemName"]][e["dayNumber"]] = sold[s_["itemName"]].get(e["dayNumber"], 0) + s_["amountSold"]
    logged = {t["dayOfDelivery"] for t in log}
    first = min(logged) + (1 if len(log) >= DELIVERY_LOG_SIZE else 0)
    days = range(first, today)
    if not days:
        return {}
    return {
        "first": first,
        # Which days the sales history holds: a day it holds with no exports is a 0.
        "covered": [int(d in covered) for d in days],
        "out": {item: [int(out[item][d]) for d in days] for item in _in_order(out)},
        "sold": {item: [int(sold[item].get(d, 0)) if d in covered else None for d in days] for item in _in_order(sold)},
    }


def _open_factory(save: Save, names: Names, regs_list: list, businesses: list, recipes: dict,
                  staff: list) -> dict:
    """The facts Expansion › Plan a factory prices a plan from.

    `products`: per recipe product and ingredient, its wholesale price (`w`),
    the save's import price index (`i`, 1 where the market has none, as for
    raw material), the units a box holds (`bx`) and the most one importer
    takes a week (`mo`). An ingredient the help names one way and the city
    trades another (Bag of Tomatoes: rawtomato and tomato) is read under the
    name the store rules know, by its label, as the supply walk resolves it.
    The board prices an import at w x i x the public prices, less the best
    purchasing agent's discount, and an export at w x i x the public prices x
    the export price, with no discount (ItemHelper.GetWholesalePrice,
    ProductMarketHelper.GetProductExportPrice).

    `kits`, each workstation's machines at list price; `shelf`, the Pallet
    Shelf and the boxes it holds; `vehicles`, the factory's truck and a new
    depot's van at their price with the dealer; `items` and `vendors`, who
    sells the machines and the shelf. `sites`, per warehouse and factory the
    player runs: its pallet shelves, the products import contracts deliver to
    it ([slug, active]) and its vehicles ([type, has a driver]). `hq`: the
    purchasing agents and import contracts, the logistics managers and the
    warehouses and factories they manage (one each, the help pages).
    """
    rules = load_store_rules()
    products = rules.get("products") or {}
    if not products:
        return {}
    prices = load_item_prices()
    root = save.root
    gv = save.deref(root.get("gameVariables")) or {}
    agents = sorted(((p.get("level") or 0, str(p.get("name") or "")) for p in staff
                     if p.get("skill") == "ba:skill_purchasingagent"), key=lambda a: (-a[0], a[1]))
    agent = int(agents[0][0]) if agents else 100
    by_label = collections.defaultdict(list)
    for slug, label in names.locale.items():
        if slug.startswith("ba:itemname_") and slug in products:
            by_label[label].append(slug)
    index = {}
    for entry in save.items(root.get("productMarketEntries")):
        name = entry.get("itemName") if isinstance(entry, dict) else None
        if isinstance(name, str):
            index[name] = entry.get("importPriceIndex") or 1.0

    def known(slug, label):
        if slug in products:
            return slug
        return next(iter(sorted(by_label.get(label) or ())), slug)

    wanted = {}
    for rec in recipes.values():
        wanted.setdefault(rec["slug"], rec["item"])
        for ing in rec["ingredients"]:
            wanted.setdefault(ing["slug"], ing["item"])
    facts = {}
    for slug in _in_order(wanted):
        base = known(slug, wanted[slug])
        row = products.get(base) or {}
        facts[slug] = {"w": row.get("w") or 0, "i": round(index.get(base, 1.0), 4),
                       "bx": row.get("bx") or 0, "mo": row.get("mo") or 0}

    kits = _factory_kits(names, prices)
    furniture = rules.get("furniture") or {}
    table = prices.get("items") or {}
    used = {item for kit in kits.values() for item, _p in kit} | {PALLET_SHELF}
    items = {item: {"p": float((table.get(item) or {}).get("p") or 0),
                    "v": (furniture.get(item) or {}).get("v") or []} for item in _in_order(used)}
    vendors = rules.get("vendors") or {}
    sold_by = {v for item in used for v in (furniture.get(item) or {}).get("v") or ()}
    vehicle_prices = rules.get("vehicles") or {}

    instances = {v.get("id"): v for v in save.items(root.get("VehicleInstances")) if isinstance(v, dict)}
    regs = {site_key(_address_of(r, strict=True)): r for r in regs_list}
    contracts = collections.defaultdict(dict)
    partnerships = save.items(root.get("importPartnerships"))
    for partnership in partnerships:
        active = bool(partnership.get("isActive"))
        for product in save.items(partnership.get("products")):
            where = site_key(save.address(product.get("assignedWarehouse")))
            slug = product.get("itemName")
            if where and isinstance(slug, str):
                contracts[where][slug] = contracts[where].get(slug, False) or active
    sites = {}
    for b in businesses:
        kind = {"ba:businesstype_factory": "factory", "ba:businesstype_warehouse": "depot"}.get(b.get("typeSlug"))
        reg = regs.get(b.get("key"))
        if not kind or reg is None:
            continue
        vehicles = []
        for slot in save.items(reg.get("vehicleSlots")):
            vid = slot.get("vehicleInstanceId") if isinstance(slot, dict) else None
            if vid and vid in instances:
                vehicles.append([_vehicle_type(instances[vid]), bool(slot.get("employeeDriverId"))])
        sites[b["key"]] = {
            "kind": kind,
            "shelves": _placed_items(save, reg).get(PALLET_SHELF, 0),
            "imports": [[slug, contracts[b["key"]][slug]] for slug in _in_order(contracts[b["key"]])],
            "vehicles": vehicles,
            **({"days": _factory_days(save, reg)} if kind == "factory" else {}),
        }
    roles = collections.Counter(p.get("skill") for p in staff)
    return {
        "game": {
            "prices": round(gv.get("marketPriceMultiplier") or 1.0, 4),
            "export": round(gv.get("exportMultiplier") or 0.65, 4),
            "wages": round(gv.get("employeeHourlySalaryMultiplier") or 0.7, 4),
            "agent": agent,
            "agentName": agents[0][1] if agents else None,
            "installFee": INSTALL_FEE_PER_M2,
            "delivery": FURNITURE_DELIVERY_FEE,
            "driverHours": DRIVER_DAY_HOURS,
            "hqHours": HQ_WEEK_HOURS,
        },
        "skills": {skill: wage for skill, wage in sorted((rules.get("skills") or {}).items())
                   if skill in ("ba:skill_factoryworker", "ba:skill_deliverydriver",
                                "ba:skill_purchasingagent", "ba:skill_logisticsmanager")},
        "products": facts,
        "kits": kits,
        "shelf": {"item": PALLET_SHELF, "p": items[PALLET_SHELF]["p"],
                  "cc": (furniture.get(PALLET_SHELF) or {}).get("cc") or 60},
        "vehicles": {role: {"type": kind, "p": float(vehicle_prices.get(kind) or 0), "name": names.label(kind),
                            "dealer": VEHICLE_DEALER[0], "at": VEHICLE_DEALER[1], "hood": VEHICLE_DEALER[2]}
                     for role, kind in (("truck", FACTORY_TRUCK), ("van", DEPOT_VAN))},
        "items": items,
        "vendors": {key: vendors[key] for key in _in_order(sold_by) if key in vendors},
        "sites": sites,
        "hq": {"agents": roles.get("ba:skill_purchasingagent", 0), "contracts": len(partnerships),
               "managers": roles.get("ba:skill_logisticsmanager", 0),
               "managed": len(sites)},
    }


def _hype_exposure(businesses: list, market: dict) -> list:
    """What each running hype wave is worth, and what the day after looks like.

    The game says a wave is running and when it ends; it does not say what it is
    worth. The only honest answer is the same kind of shop where no wave is
    running — and where there is no such shop, the answer is that we cannot say.
    """
    retail = [b for b in businesses if b["status"] == "retail" and b["revenue"] > 0]
    hyped_hoods = {w["hood"] for w in market.get("hype", [])}

    out = []
    for wave in market.get("hype", []):
        slugs = set(wave.get("slugs", []))
        sites = []
        for b in retail:
            if b["neighbourhood"] != wave["hood"]:
                continue
            hyped = sum(l["revenue"] for l in b["lines"] if l["slug"] in slugs)
            whole = sum(l["revenue"] for l in b["lines"]) or 1
            if hyped <= 0:
                continue
            sites.append(
                {
                    "key": b["key"],
                    "name": b["name"],
                    "type": b["typeSlug"],
                    "revenue": b["revenue"],
                    "profit": b["profit"],
                    "share": round(hyped / whole * 100),
                }
            )
        if not sites:
            continue
        top = max(sites, key=lambda s: s["revenue"])
        best = next(b for b in retail if b["key"] == top["key"])

        # First choice is the shop's own trading before the wave landed: same
        # shop, same street, nothing else changed. Failing that, the same kind of
        # shop somewhere no wave is running — never a different kind of shop, and
        # never nothing dressed up as a number.
        before = [
            s["revenue"]
            for s in best["series"]
            if s["day"] < wave["startDay"] and s["revenue"] > 0
        ][-7:]
        if len(before) >= HYPE_BASELINE_DAYS:
            baseline = {
                "name": best["name"],
                "hood": best["neighbourhood"],
                "revenue": money(sum(before) / len(before)),
                "basis": msg("f.hype.basis.own", "its own {n} days before day {day}",
                             n=len(before), day=wave["startDay"]),
            }
        else:
            pool = [
                b
                for b in retail
                if b["typeSlug"] in {s["type"] for s in sites}
                and b["neighbourhood"] not in hyped_hoods
            ]
            other = max(pool, key=lambda b: b["revenue"], default=None)
            baseline = (
                {
                    "name": other["name"],
                    "hood": other["neighbourhood"],
                    "revenue": other["revenue"],
                    "basis": msg("f.hype.basis.other", "the no-hype {site}", site=other["name"]),
                }
                if other
                else None
            )
        out.append(
            {
                "hood": wave["hood"],
                "daysLeft": wave["daysLeft"],
                "startDay": wave["startDay"],
                "count": wave["count"],
                "items": wave["items"],
                "sites": sites,
                "top": top["key"],
                "revenue": money(sum(s["revenue"] for s in sites)),
                "profit": money(sum(s["profit"] for s in sites)),
                "baseline": baseline,
            }
        )
    out.sort(key=lambda w: w["daysLeft"])
    return out


# ----------------------------------------------------------------------- plan
def _ingredient_prices(save: Save, names: Names, supply: dict, businesses: list) -> dict:
    """What a unit of each raw material actually cost, from the owner's books.

    The save carries no importer price list — `importPartnerships.products` holds
    an item, an amount and a warehouse, and nothing about money. What it does
    carry is what was paid: each site's goods cost per item, booked where the
    goods are used (a factory, not the depot that imported them), and the
    units the delivery log shows reaching that site. The round logged on day
    d + 1 restocks what day d's cost paid for, so each cost day is paired with
    the next day's arrivals; a cost day whose round has not run yet drops out
    on both sides. Over the last PRICE_DAYS cost days, company-wide, the one
    divided by the other gives a real unit price for every material this
    company already buys, and nothing at all for one it does not. Something
    the company makes itself reaches its users at no cost, so it has no price
    here. Guessing the rest would be inventing a price list.

    Every cost day the site's log covers counts, whether or not a round came
    the next day, so a weekly import delivered straight to a factory is the
    week's cost against its one delivery. A known limit: that is right only
    where the delivery matches the week's use; a window holding two such
    deliveries misprices it, and one holding none leaves that site out, since
    nothing arrived there to divide by.
    """
    summaries = sorted(save.items(save.root["financialSummaries"]), key=lambda s: s["dayNumber"])
    if not summaries:
        return {"unit": {}, "day": None, "from": None}
    window = {s["dayNumber"] for s in summaries[-PRICE_DAYS:]}
    spend = collections.defaultdict(lambda: collections.defaultdict(float))
    for summary in summaries[-PRICE_DAYS:]:
        for statement in save.items(summary["businessIncomeStatements"]):
            key = site_key(save.address(statement.get("Address")))
            for line in save.items(statement.get("Resources")):
                if line.get("ItemName") and line.get("Amount"):
                    spend[(key, line["ItemName"])][summary["dayNumber"]] += line["Amount"]

    # Each site's cost days: every window day whose next day its log covers,
    # a day with nothing delivered included (it brought 0). A log short of
    # its full length holds everything since its first delivery, so it covers
    # from that day (what came before it was never logged); a full one has
    # lost part of its oldest day, so it covers from the day after. Today's round, not yet
    # logged, covers nothing yet, so the last cost day waits on both sides.
    today = save.root.get("Day")
    arrived = collections.defaultdict(lambda: collections.defaultdict(float))
    covered = collections.defaultdict(set)
    for building in save.items(save.root["BuildingRegistrations"]):
        if not building.get("RentedByPlayer"):
            continue
        key = site_key(_address_of(building, strict=True))
        log = save.items(building.get("deliveryTransactions"))
        days = {t.get("dayOfDelivery") for t in log if isinstance(t.get("dayOfDelivery"), int)}
        if not days:
            continue  # no log, so nothing to divide by: a shop
        reach = min(days) + 1 if len(log) >= DELIVERY_LOG_SIZE else min(days)
        covered[key] = {d for d in window
                        if d + 1 >= reach and (d + 1 != today or today in days)}
        for transaction in log:
            when = transaction.get("dayOfDelivery")
            if not isinstance(when, int) or when - 1 not in covered[key]:
                continue
            for entry in save.items(transaction.get("deliveryItems")):
                amount = entry.get("amountDelivered") or 0
                if entry.get("itemName") and amount > 0:
                    arrived[(key, entry["itemName"])][when] += amount

    made = {line["slug"] for site in (supply.get("factories") or {}).get("sites", [])
            for line in site.get("lines", [])}
    paid = collections.defaultdict(float)
    units = collections.defaultdict(float)
    for (key, slug), by_day in spend.items():
        if slug in made:
            continue
        # Only the cost days this site's log covers, each against the next
        # day's arrivals, and only where goods came in at all.
        days = covered.get(key, ())
        got = sum(arrived[(key, slug)].get(d + 1, 0.0) for d in days)
        if got <= 0:
            continue
        paid[slug] += sum(by_day.get(d, 0.0) for d in days)
        units[slug] += got
    return {
        "unit": {slug: round(paid[slug] / units[slug], 4)
                 for slug in _in_order(units) if paid[slug] > 0},
        "day": summaries[-1]["dayNumber"],
        "from": min(window),
    }


def _plan_extra(kind: str, taken: set) -> list:
    """What a type can additionally sell, as [[slug, weight], ...], heaviest first.

    The game's own product list for the type (ba_store_rules.json, `types[kind].i`)
    gives each product a weight; a main product is 1, and those under 1 are the
    extras its shelves also take. A product already in the type's range, or a
    service, is left out. Equal weights keep the game's order. Read lazily
    through load_store_rules(), never at import (the browser worker writes the
    file first).
    """
    listed = (load_store_rules()["types"].get(kind) or {}).get("i") or []
    extra = [[slug, weight] for slug, weight in listed
             if isinstance(weight, (int, float)) and 0 < weight < 1 and slug not in taken]
    return sorted(extra, key=lambda pair: -pair[1])


def _plan(
    save: Save,
    names: Names,
    businesses: list,
    catalogue: dict,
    recipes: dict,
    stations: dict,
    prices: dict,
    rhythm: dict,
) -> dict:
    """Everything a chain calculator needs, so the sliders can run in the browser.

    Nothing is decided here. The recipes, the workstations and the prices go
    across as they were read, and the arithmetic happens where the slider is.
    """
    # A fee link — (fees-haircut), say — charges for work done, never for a
    # good a shop stocks or a factory makes, so no fee belongs in a chain the
    # sliders plan. Every business help page is read once: its fees classify
    # services across the whole game, and its text is kept for the furniture
    # block a service type's range is read from below. A ticket is issued, not
    # made or imported, so it counts as a service too, though its page links it
    # as a product.
    fee_re = re.compile(r"\[([^\]]+)\]\(fees-([a-z0-9_]+)\)")
    good_re = re.compile(r"\[([^\]]+)\]\(products-([a-z0-9_]+)\)")
    services = set(ISSUED_ITEMS)
    pages = {}
    for key, text in names.locale.items():
        match = _BUSINESS_HELP_RE.match(key)
        if match:
            pages[match.group(1)] = text
            services.update("ba:itemname_" + s for _n, s in fee_re.findall(text))

    catalogue_out = {}
    for kind, items in catalogue.items():
        sold = set(items)
        text = pages.get(kind)
        header = _SELLS_HEADER_RE.search(text) if text else None
        sells = text[header.end() :].lstrip("\n").split("\n\n", 1)[0] if header else ""
        before = text[: header.start()] if header else (text or "")
        # What the type charges for is its service line: recorded for the page
        # to explain, and kept out of the products the planner can stock.
        charged = {"ba:itemname_" + s for _n, s in fee_re.findall(sells)}
        kind_services = sorted(charged | (sold & services))
        physical = sold - services
        if kind_services:
            # A service business still runs on goods — the hairdresser's chair
            # is stocked with a haircare product — and the required-furniture
            # block above its sell list names them with product links. Those
            # links, deduplicated, are what the planner can plan for the type.
            physical.update("ba:itemname_" + s for _n, s in good_re.findall(before))
        if sold & ISSUED_ITEMS and header:
            # A cinema or theater's ticket is its whole primary range, so its
            # concessions (popcorn, martinis) are what the planner can plan.
            extra = _EXTRAS_HEADER_RE.search(text, header.end())
            if extra:
                block = text[extra.end() :].lstrip("\n").split("\n\n", 1)[0]
                physical.update("ba:itemname_" + s for _n, s in good_re.findall(block))
        catalogue_out[kind] = {
            "type": names.label(kind),
            "products": sorted(physical),
            "services": kind_services,
            "extra": _plan_extra(kind, physical | set(kind_services) | services),
        }

    # What the owner's own shops of each type actually sell, per product per day,
    # so the default target is his trading rather than a guess.
    mine = collections.defaultdict(lambda: collections.defaultdict(list))
    sites = collections.Counter()
    for b in businesses:
        if b["status"] != "retail" or not b["revenue"]:
            continue
        sites[b["typeSlug"]] += 1
        for line in b["lines"]:
            if line["price"] and line["rate"] > 0:
                mine[b["typeSlug"]][line["slug"]].append(line["rate"])
    own = {}
    for kind, products in mine.items():
        # Only physical lines count as trade the planner can plan; what the
        # shops make from a service fee is dropped. A type whose measured
        # sales were all services keeps its site count all the same — the
        # shops exist even where nothing plan-able was sold.
        entry = catalogue_out.get(kind, {})
        # A product the type can additionally sell counts too: what the shops
        # already sell of it is measured, and beats the rate the player types.
        planable = set(entry.get("products", ())) | {s for s, _w in entry.get("extra", ())}
        own[kind] = {
            "sites": sites[kind],
            # The same count under the name the chain planner prints.
            "shops": sites[kind],
            "perDay": {
                s: round(sum(v) / len(v), 1)
                for s, v in products.items()
                if s in planable
            },
            # How many of those shops sell each product the type can
            # additionally sell: a product only some of them trial is spread
            # over all of them on the page, and stays the player's to type.
            "sellers": {
                s: len(v)
                for s, v in products.items()
                if s in planable and s not in entry.get("products", ())
            },
            # The same for its main products: perDay is their average over
            # the shops that stock them, which Plan a factory spreads over all.
            "stocked": {
                s: len(v)
                for s, v in products.items()
                if s in entry.get("products", ())
            },
        }

    labels = {}
    for recipe in recipes.values():
        labels[recipe["slug"]] = recipe["item"]
        for ing in recipe["ingredients"]:
            labels[ing["slug"]] = ing["item"]
    for entry in catalogue_out.values():
        for slug in entry["products"] + entry["services"] + [s for s, _w in entry["extra"]]:
            labels.setdefault(slug, names.label(slug))

    # Orders are placed importer by importer in the game, and each one already
    # has a number in the box. One product can sit on several contracts, so the
    # running totals are summed — a later contract, or a line ordered at zero,
    # adds what it has and never overwrites what came before — and every
    # contract is kept, so the shopping list can still be typed in per importer.
    #
    # A Smart Delivery contract (isTarget) holds a stock level rather than
    # bringing its amount, so a depot's week is what one delivery brings into
    # it empty, as _supply() counts it: two levels on one depot hold the
    # higher, and a level beside a plain order follows the delivery order.
    # "ordered" is that week summed over depots, the one company-wide total
    # the target needs. A level belongs to its depot and is never summed:
    # "depots" says per depot how the line is set (level, plain amount on top
    # of it, or a weekly amount), and "smart" whether any counted depot runs
    # on a level.
    partnerships = save.items(save.root["importPartnerships"])
    ranks = _import_ranks(save, partnerships)
    sources, drops = {}, collections.defaultdict(lambda: {"active": [], "paused": []})
    for order, partnership in enumerate(partnerships):
        who = names.addr(save.address(partnership.get("importAddress")))
        active = bool(partnership.get("isActive"))
        smart = bool(partnership.get("isTarget"))
        for product in save.items(partnership["products"]):
            row = sources.setdefault(
                product["itemName"],
                {"ordered": 0, "paused": 0, "active": False, "contracts": []},
            )
            warehouse = save.address(product["assignedWarehouse"])
            amount = product.get("amount", 0)
            row["contracts"].append(
                {
                    "from": who,
                    "warehouse": names.addr(warehouse),
                    "ordered": amount,
                    "active": active,
                    "smart": smart,
                }
            )
            row["active"] = row["active"] or active
            drops[(product["itemName"], warehouse)]["active" if active else "paused"].append(
                {"amount": amount, "smart": smart, "rank": ranks[order], "importer": who}
            )
    for (item, _warehouse), groups in drops.items():
        row = sources[item]
        for group in groups.values():
            group.sort(key=lambda d: d["rank"])
        row["ordered"] += _import_drop(0, groups["active"])
        row["paused"] += _import_drop(0, groups["paused"])
    for item, row in sources.items():
        lead = "active" if row["active"] else "paused"
        row["depots"] = []
        for (name, warehouse), groups in drops.items():
            counted = [d for d in groups[lead] if d["amount"]]
            if name != item or not counted:
                continue
            held = _import_level(counted)
            row["depots"].append({
                "warehouse": names.addr(warehouse), "smart": held["smart"], "level": held["level"],
                "importer": counted[held["at"]]["importer"] if held["smart"] else None,
                "name": _level_name(
                    [{"importer": d["importer"], "order": d["rank"][1]}
                     for d in sorted(groups["active"] + groups["paused"], key=lambda d: d["rank"])],
                    counted[held["at"]]["importer"], counted[held["at"]]["rank"][1],
                ) if held["smart"] else None,
                "plainBefore": held["plainBefore"], "plainAfter": held["plainAfter"],
                "weekly": _import_drop(0, counted),
            })
        row["smart"] = any(d["smart"] for d in row["depots"])
        row["from"] = ", ".join(dict.fromkeys(c["from"] for c in row["contracts"]))
        row["warehouse"] = ", ".join(
            dict.fromkeys(c["warehouse"] for c in row["contracts"])
        )

    beat = rhythm.get("customers") or rhythm.get("revenue")
    uplift = (max(p["index"] for p in beat) / 100) if beat else 1.0
    return {
        "sources": sources,
        "recipes": list(recipes.values()),
        "workstations": _workstations(names),
        "catalogue": catalogue_out,
        "items": labels,
        "own": own,
        "prices": prices["unit"],
        "priceDay": prices["day"],
        "priceFrom": prices.get("from"),
        "priceCount": len(prices["unit"]),
        "peak": round(uplift, 3),
        # By the workstation's key, never its name.
        "stations": {s: rate for s, (_skill, rate) in stations.items()},
    }


# --------------------------------------------------------------------- alerts
# What the number in a finding's "worth" is counted in, for the page to print
# under the amount. Only groups whose worth carries money get a unit; the rest
# are left empty because their worth is always None.
# Registry: "A finding kind" (docs/architecture.md, Registries). Every kind
# needs: its group, emitted by note() in _alerts() or _finding() in a helper
# such as _idle_notes() (or an AMENITY_DEMANDS row); ALERT_GROUPS; ALERT_LINKS;
# FINDING_ROUTES; ALERT_EVIDENCE, or NO_EVIDENCE in tests/alert_kinds.test.cjs;
# ALERT_UNITS if its worth is money, else NOT_MONEY there; SS_KIND_SYN for its
# search words, if players have any; its line under "What counts as a finding"
# in docs/dashboard-reference.md. The checklist has the only-if tables.
ALERT_UNITS = {
    "notrading": msg("f.unit.rent", "/day rent"),
    "vacant": msg("f.unit.rent", "/day rent"),
    "loss": msg("f.unit.loss", "/day loss"),
    "hype": msg("f.unit.revenue", "/day revenue"),
    "trend": msg("f.unit.revenue", "/day revenue"),
    "atcap": msg("f.unit.trade", "/day trade"),
    "idlestaff": msg("f.unit.wages", "/day wages"),
    "dead": msg("f.unit.tied", "/day tied up"),
    "target": msg("f.unit.excess", "/day excess"),
}


def _amt(n, unit: str, *, of=None, sign: str = "", places: int = 0) -> dict:
    """The figure a finding with no money worth shows on the right, as data,
    so the page never reads it back out of the sentence: `n` (and `of`, for
    "84/168") in `unit`, one of the unit ids the page's amtUnit() words.
    `sign` is "$", "%" or "x". A number the sentence rounds is rounded the
    same way here, so the two always agree; `places` is how many decimals
    the sentence writes ("1.0 days"), sent as `dp` for the page to keep."""
    out = {"n": n, "unit": unit}
    if of is not None:
        out["of"] = of
    if sign:
        out["sign"] = sign
    if places:
        out["n"] = _shown(n, places)
        out["dp"] = places
    return out


def _shown(v, places: int = 0):
    """v as a finding's sentence writes it with `places` decimals
    (_half_away()), as a number: an int when it is whole."""
    r = _half_away(v, places)
    return int(r) if r == r.to_integral_value() else float(r)


def _msg_list(items: list):
    """Several names or phrases as one list, "a, b, c", that stays a message:
    a nested "{a}, {b}" per comma, the last pair under a key of its own
    (f.list.last), so a translation can join that one with its "and". One item
    is itself."""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return msg("f.list.last", "{a}, {b}", a=items[0], b=items[1])
    return msg("f.list", "{a}, {b}", a=items[0], b=_msg_list(items[1:]))


def _worked_over(d: dict):
    """Why an hours or days demand fails when the roster itself meets it: the
    week worked so far has passed its top. The whole row, or how many of it;
    None when it has not."""
    w = d.get("workedOver")
    if not w:
        return None
    if w["count"] == d["count"]:
        if w["unit"] == "days":
            return msg("f.jobdemand.over.days", "worked over {max} days this week", max=w["max"])
        return msg("f.jobdemand.over.hours", "worked over {max} hours this week", max=w["max"])
    if w["unit"] == "days":
        return msg("f.jobdemand.over.days.some", {"one": "{n} worked over {max} days this week",
                                                    "other": "{n} worked over {max} days this week"},
                   n=w["count"], max=w["max"])
    return msg("f.jobdemand.over.hours.some", {"one": "{n} worked over {max} hours this week",
                                                "other": "{n} worked over {max} hours this week"},
               n=w["count"], max=w["max"])


def _demand_priority(priority: int):
    """A job demand's priority as a finding says it: JOB_DEMAND_PRIORITY,
    lowercased."""
    if priority == 2:
        return msg("f.jobdemand.critical", "critical")
    if priority == 1:
        return msg("f.jobdemand.important", "important")
    return msg("f.jobdemand.nice", "nice to have")


def _alert_id(*parts: str) -> str:
    """A stable id for a finding: the same finding keeps it across renders,
    and it does not depend on where the finding sits in the list."""
    return hashlib.sha1(":".join(parts).encode("utf-8")).hexdigest()[:10]


def _finding(
    level: str,
    site: str,
    group: str,
    text: str,
    *,
    key=None,
    rank: float = 0.0,
    subject: str = "",
    worth=None,
    always: bool = False,
    ev: dict | None = None,
    named: str | None = None,
    amt: dict | None = None,
) -> dict:
    """One row of the list.

    `key` is the business's site key (its address) when the finding is about
    one business; a synthetic site such as "3 shops" has none. The id hashes
    the key where there is one, so a renamed business keeps its silences and
    two shops that share a name never share a finding. The page navigates by
    the key too, so it never opens a namesake.

    `ev` is what the site panel needs to point at the row this finding is
    about, once `rank` and `subject` have been dropped by _condense(): the
    item's `slug`, or a machine's list position as `slot`. It is left off
    entirely where the panel has a fixed mark to pulse instead, because it
    travels in every payload.

    `subject` is English, since the id hashes it; `named` is how a summary
    line of several rows names it (_condense()), with its game names as tokens.

    `amt` is the figure a row with no money worth shows (_amt()), left off
    where the sentence has none.
    """
    return {
        "level": level,
        "site": site,
        "group": group,
        "text": text,
        "rank": rank,
        "subject": subject,
        "named": subject if named is None else named,
        "worth": worth,
        "unit": ALERT_UNITS.get(group, ""),
        "id": _alert_id(group, key or site, subject),
        "siteKey": key,
        "always": always,
        **({"ev": ev} if ev else {}),
        **({"amt": amt} if amt else {}),
    }


# Registry: "A finding kind" (docs/architecture.md, Registries). Every kind
# needs: its group, emitted by note() in _alerts() or _finding() in a helper
# such as _idle_notes() (or an AMENITY_DEMANDS row); ALERT_GROUPS; ALERT_LINKS;
# FINDING_ROUTES; ALERT_EVIDENCE, or NO_EVIDENCE in tests/alert_kinds.test.cjs;
# ALERT_UNITS if its worth is money, else NOT_MONEY there; SS_KIND_SYN for its
# search words, if players have any; its line under "What counts as a finding"
# in docs/dashboard-reference.md. The checklist has the only-if tables.
def _alerts(
    businesses: list,
    supply: dict,
    chains: list,
    trends: list,
    hype: list,
    hours: list,
    grids: list,
    day: int,
    gate: float,
    mode: str = "cap",
    agencies: list = (),
) -> dict:
    """Only things worth acting on, with a number and a deadline where one exists.

    Two filters run over everything below. Findings that repeat across many
    products at one site collapse into a single counted line, and findings that
    carry a dollar figure have to clear the materiality gate — a fraction of a
    day's profit — or they are counted at the foot of the panel instead of read
    out. A site that cannot trade at all is never counted away.
    """
    found = []

    def note(level, site, group, text, rank=0.0, subject="", worth=None, always=False,
             key=None, ev=None, named=None, amt=None):
        found.append(
            _finding(level, site, group, text, key=key, rank=rank, subject=subject,
                     worth=worth, always=always, ev=ev, named=named, amt=amt)
        )

    # A delivery plan: a route or an import into the site, or a repeating
    # wholesale contract to it.
    planned = {link["to"] for link in supply["graph"]["links"]}
    planned |= {businesses[s]["key"] for s in supply.get("wholesaleShops", ())
                if 0 <= s < len(businesses)}

    # --- a site that has not started trading is one finding, not four
    silent = set()
    for b in businesses:
        # Only a shop or an office can fail to trade. A warehouse, factory or
        # head office never books a sale, so silence there is its normal state.
        if b["status"] not in ("retail", "office") or b["revenue"] or day - b["opened"] > NEW_SITE_DAYS:
            continue
        office = b["status"] == "office"
        silent.add(b["key"])
        priced = [l for l in b["lines"] if l["price"] > 0]
        # A ticket is issued, never shelved, so only the other lines need stock.
        shelved = [l for l in priced if not l.get("issued")]
        stocked = [l for l in shelved if l["units"] > 0]
        # Which of the six pre-flight checks fail is the finding, so the slugs
        # are kept on the business beside the words: the site panel reads the
        # same list and the two cannot drift apart. An office sells hours, not
        # goods, so it has nothing to stock or deliver. A site shut with the
        # game's temporarily-closed switch books no day however ready it is,
        # so that reason comes first.
        failed, reasons = [], []
        if b.get("closed"):
            failed.append("closed")
            reasons.append(msg("f.notrading.closed", "temporarily closed"))
        if b["staff"] == 0:
            failed.append("staff")
            reasons.append(msg("f.notrading.staff", "no staff"))
        if not priced:
            failed.append("prices")
            reasons.append(msg("f.notrading.prices", "no prices set"))
        elif not office and shelved and not stocked:
            failed.append("stock")
            reasons.append(msg("f.notrading.stock", "no stock"))
        elif not office and len(stocked) * 2 < len(shelved):
            failed.append("shelves")
            reasons.append(msg("f.notrading.shelves", "{n} of {of} shelves bare",
                               n=len(shelved) - len(stocked), of=len(shelved)))
        if not office and (shelved or not priced) and b["key"] not in planned:
            failed.append("plan")
            reasons.append(msg("f.notrading.plan", "no delivery plan"))
        b["notTrading"] = failed
        if not reasons:
            reasons.append(
                msg("f.notrading.ready.office", "staffed and priced, no trading day booked yet")
                if office or not shelved else
                msg("f.notrading.ready", "staffed and stocked, no trading day booked yet")
            )
        note(
            "critical",
            b["name"],
            "notrading",
            msg("f.notrading", "{site} opened day {day}, not trading yet: {reasons}, ${rent:,.0f}/day rent",
                site=b["name"], day=b["opened"], reasons=_msg_list(reasons), rent=b["rent"]),
            worth=b["rent"],
            always=True,
            key=b["key"],
        )

    vacant = [b for b in businesses if b["status"] == "vacant"]
    if vacant:
        rent = sum(b["rent"] for b in vacant)
        note(
            "warn",
            msg("f.site.leases", {"one": "{n} lease", "other": "{n} leases"}, n=len(vacant)),
            "vacant",
            msg("f.vacant", {"one": "{n} vacant lease costing ${rent:,.0f}/day in rent",
                             "other": "{n} vacant leases costing ${rent:,.0f}/day in rent"}, n=len(vacant), rent=rent),
            worth=rent,
        )

    for b in businesses:
        if b["status"] == "vacant" or b["key"] in silent:
            continue
        if b["profit"] < 0 and not b["costCentre"]:
            note(
                "critical" if b["profit"] < -1000 else "warn",
                b["name"],
                "loss",
                msg("f.loss", "Lost {w:$} yesterday", w=abs(b["profit"])),
                worth=abs(b["profit"]),
                key=b["key"],
            )
        if b["status"] in ("retail", "office") and b["staff"] == 0:
            note("critical", b["name"], "staff", msg("f.staff.none", "No staff assigned"), always=True, key=b["key"])
        sat = b["satisfaction"]["overall"]
        if sat is not None and b["customers"] and sat < 80:
            note("warn", b["name"], "satisfaction", msg("f.satisfaction", "Customer satisfaction at {n}%", n=sat),
                 key=b["key"], amt=_amt(sat, "satisfied", sign="%"))
        if b.get("missingUniformLocker"):
            # Installing the locker is the first action to take, so it stands in
            # for whichever roles are uncovered behind it.
            note(
                "warn", b["name"], "uniform",
                msg("f.uniform.locker", "No uniform locker installed; add one to manage employee uniforms"),
                always=True, key=b["key"],
            )
        elif b.get("uniformGaps"):
            skills = b.get("uniformGapSkills") or []
            roles = _msg_list([tok(skills[i] if i < len(skills) else None, role)
                               for i, role in enumerate(b["uniformGaps"])])
            note(
                "warn", b["name"], "uniform",
                msg("f.uniform.gaps", "No uniform set for {roles}; customers judge every role "
                    "staffed at a station here", roles=roles),
                always=True, key=b["key"],
            )
        for slug in b["missingAmenities"]:
            group, text = AMENITY_DEMANDS[slug]
            note("warn", b["name"], group, text, always=True, key=b["key"])

    # --- what staff ask for and do not get. A site that has not started trading
    # still has staff whose satisfaction is moving, so it is not folded away here.
    for b in businesses:
        if b["status"] == "vacant":
            continue
        demands = b.get("staffDemands", [])
        wants = [d for d in demands if not d["company"]]
        quitting = b.get("quitWarnings", 0)
        # Every demand the site itself can meet, with the game's priority, headed
        # by how many people lack one. Once somebody with an unmet demand has
        # warned they will quit, the line is louder and names everything unmet
        # here, the company-wide demands too, since those may be all they lack.
        if quitting and demands:
            count, shown = b.get("staffLackingAny", 0), demands
        elif wants:
            count, shown = b.get("staffLacking", 0), wants
        else:
            continue
        items = []
        for d in shown:
            why = (msg("f.jobdemand.company", "company-wide") if d["company"]
                   else _demand_priority(d["priority"]))
            over = _worked_over(d)
            if over:
                why = msg("f.jobdemand.why", "{priority}, {over}", priority=why, over=over)
            items.append(msg("f.jobdemand.item", "{demand} for {n} ({why})",
                             demand=tok(d.get("slug"), d["demand"]), n=d["count"], why=why))
        if quitting:
            text = msg("f.jobdemand.quit", {
                "one": "{count} staff with unmet demands: {demands}; {n} of them has warned they will quit",
                "other": "{count} staff with unmet demands: {demands}; {n} of them have warned they will quit",
            }, count=count, demands=_msg_list(items), n=quitting)
        else:
            text = msg("f.jobdemand", {"one": "{n} staff member with unmet demands: {demands}",
                                       "other": "{n} staff with unmet demands: {demands}"},
                       n=count, demands=_msg_list(items))
        note(
            "critical" if quitting else "warn", b["name"], "jobdemand", text,
            always=True, key=b["key"], amt=_amt(count, "staff"),
        )

    # --- the staff demands no single site can settle: health insurance comes
    # through an HR manager's plan, a happy boss is the owner's own happiness.
    company, lacking = collections.OrderedDict(), 0
    for b in businesses:
        if b["status"] == "vacant":
            continue
        lacking += b.get("staffLackingCompany", 0)
        for d in b.get("staffDemands", []):
            if d["company"]:
                row = company.setdefault(d["slug"], dict(d, count=0))
                row["count"] += d["count"]
    if company:
        rows = sorted(company.values(), key=lambda d: (-d["priority"], -d["count"], d["demand"]))
        insured = any(JOB_DEMANDS[d["slug"]][0] == "insurance" for d in rows)
        demands = _msg_list([msg("f.companydemand.item", "{demand} for {n}",
                                 demand=tok(d.get("slug"), d["demand"]), n=d["count"]) for d in rows])
        note(
            "warn", msg("f.site.company", "Company"), "companydemand",
            msg("f.companydemand.insurance", {
                "one": "{n} staff member with unmet demands: {demands}. Health insurance comes through "
                       "an HR manager's plan",
                "other": "{n} staff with unmet demands: {demands}. Health insurance comes through "
                         "an HR manager's plan"}, n=lacking, demands=demands)
            if insured else
            msg("f.companydemand", {"one": "{n} staff member with unmet demands: {demands}",
                                    "other": "{n} staff with unmet demands: {demands}"},
                n=lacking, demands=demands),
            always=True, amt=_amt(lacking, "staff"),
        )

    # --- the promotion cap, which is reached with campaigns or not at all
    # Promotion is the foot traffic the address comes with plus whatever the
    # marketing campaigns add, held at 100. Each shop's and office's plan
    # (_marketing()) is the cheapest mix that brings it to 100, or marketing
    # to 100 where 100 is out of reach. The sites whose plan differs from what
    # they run make up to two lines: those it raises (a warning when one gains
    # PROMOTION_GAP points or more), and those that pay for campaigns that only
    # push past the target. A plan that only adds missing switches changes
    # neither cost nor promotion and is no finding. A site short of 100 whose
    # plan waits on a first visit to an agency gets a line naming it: one with
    # no plan at all (no switch, no agency known), and one already on the best
    # mix its known agencies allow that a visit would raise (a visit that would
    # only save money is the site panel's hint alone). Each line has its own
    # subject, so its id is its own. The sites not trading yet are the
    # not-trading line's.
    raised, saved, unplanned, capped = [], [], [], []
    gain = lambda b: b["marketingPlan"]["promotionPlan"] - b["marketingPlan"]["promotionNow"]  # noqa: E731
    for b in businesses:
        p = b.get("marketingPlan")
        if b["status"] not in ("retail", "office") or b["key"] in silent or not p:
            continue
        if p["on"] is None:
            if p["visit"] and p["promotionNow"] < PROMOTION_CAP:
                unplanned.append(b)
        elif set(p["on"]) != set(p["was"]):
            # A site whose plan costs more is raising its promotion, even where
            # the promotion the save stores already reads higher than the model's.
            (raised if gain(b) > 0 or p["costPlan"] > p["costNow"] else saved).append(b)
        elif p.get("visitRaises") and p["promotionPlan"] < PROMOTION_CAP and p["promotionNow"] < PROMOTION_CAP:
            capped.append(b)
    sites_of = lambda group: msg("f.site.sites", {"one": "{n} site", "other": "{n} sites"}, n=len(group))  # noqa: E731
    if raised:
        raised.sort(key=lambda b: (-gain(b), b["name"]))
        extra = sum(b["marketingPlan"]["costPlan"] - b["marketingPlan"]["costNow"] for b in raised)
        n, site, top = len(raised), raised[0]["name"], raised[0]["marketingPlan"]["promotionPlan"]

        def item(b):
            p = b["marketingPlan"]
            if gain(b) > 0:
                return msg("f.promotion.item.gain", "{site} {a}% → {b}%", site=b["name"],
                           a=p["promotionNow"], b=p["promotionPlan"])
            return msg("f.promotion.item.save", "{site} {a:$} → {b:$}/day", site=b["name"],
                       a=p["costNow"], b=p["costPlan"])
        sites = _msg_list([item(b) for b in raised])
        if n == 1:
            text = (msg("f.promotion.reach.less.one", "{site} can reach {p}% promotion for less", site=site, p=top)
                    if extra < 0 else
                    msg("f.promotion.reach.more.one", "{site} can reach {p}% promotion for {w:$}/day more",
                        site=site, p=top, w=extra)
                    if extra > 0 else
                    msg("f.promotion.reach.one", "{site} can reach {p}% promotion", site=site, p=top))
        elif all(b["marketingPlan"]["promotionPlan"] >= PROMOTION_CAP for b in raised):
            text = (msg("f.promotion.reach.less.many", "{n} sites can reach 100% promotion for less: {sites}",
                        n=n, sites=sites)
                    if extra < 0 else
                    msg("f.promotion.reach.more.many",
                        "{n} sites can reach 100% promotion for {w:$}/day more: {sites}", n=n, w=extra, sites=sites)
                    if extra > 0 else
                    msg("f.promotion.reach.many", "{n} sites can reach 100% promotion: {sites}", n=n, sites=sites))
        else:
            text = (msg("f.promotion.gain.less.many", "{n} sites can gain promotion for less: {sites}",
                        n=n, sites=sites)
                    if extra < 0 else
                    msg("f.promotion.gain.more.many", "{n} sites can gain promotion for {w:$}/day more: {sites}",
                        n=n, w=extra, sites=sites)
                    if extra > 0 else
                    msg("f.promotion.gain.many", "{n} sites can gain promotion: {sites}", n=n, sites=sites))
        note(
            "warn" if any(gain(b) >= PROMOTION_GAP for b in raised) else "info",
            site if n == 1 else sites_of(raised), "promotion", text, rank=-max(gain(b) for b in raised),
            subject="mix-raise", always=True, key=raised[0]["key"] if n == 1 else None,
            amt=_amt(top, "promotion", sign="%"),
        )
    if saved:
        saved.sort(key=lambda b: (b["marketingPlan"]["costPlan"] - b["marketingPlan"]["costNow"], b["name"]))
        w = sum(b["marketingPlan"]["costNow"] - b["marketingPlan"]["costPlan"] for b in saved)
        if len(saved) == 1:
            text = msg("f.promotion.save.one", "{site} can save {w:$}/day at the same promotion",
                       site=saved[0]["name"], w=w)
        else:
            text = msg("f.promotion.save.many", "{n} sites can save {w:$}/day at the same promotion: {sites}",
                       n=len(saved), w=w, sites=_msg_list([
                           msg("f.promotion.item.save", "{site} {a:$} → {b:$}/day", site=b["name"],
                               a=b["marketingPlan"]["costNow"], b=b["marketingPlan"]["costPlan"])
                           for b in saved]))
        note(
            "info", saved[0]["name"] if len(saved) == 1 else sites_of(saved), "promotion", text,
            subject="mix-save", always=True, key=saved[0]["key"] if len(saved) == 1 else None,
            amt=_amt(_shown(w), "/day", sign="$"),
        )
    by_key = {a["key"]: a["name"] for a in agencies}
    agencies_of = lambda group: _msg_list([by_key.get(k) or k for k in  # noqa: E731
                                           sorted({k for b in group for k in b["marketingPlan"]["visit"]})])
    if unplanned:
        one = len(unplanned) == 1
        note(
            "info", unplanned[0]["name"] if one else sites_of(unplanned), "promotion",
            msg("f.promotion.visit", "Visit {agencies} once: no campaign can be set at {sites} before that",
                agencies=agencies_of(unplanned), sites=_msg_list([b["name"] for b in unplanned])),
            subject="visit-first", always=True, key=unplanned[0]["key"] if one else None,
        )
    if capped:
        one = len(capped) == 1
        note(
            "info", capped[0]["name"] if one else sites_of(capped), "promotion",
            msg("f.promotion.visit.more", "Visit {agencies} once to raise promotion at {sites}",
                agencies=agencies_of(capped), sites=_msg_list([b["name"] for b in capped])),
            subject="visit-more", always=True, key=capped[0]["key"] if one else None,
        )

    # --- what a hype wave is carrying, and what the day it ends costs
    grid_of = {g["key"]: g for g in grids}

    def full_hours(key: str) -> int:
        """Hours of a normal week this shop spends within 10% of its ceiling."""
        grid = grid_of.get(key)
        if not grid:
            return 0
        return sum(
            1
            for wd in range(7)
            if not grid["thin"][wd]
            for hour in range(24)
            if grid["customers"][wd][hour] is not None
            and grid["effective"][wd][hour]
            and grid["customers"][wd][hour] >= grid["effective"][wd][hour] * HYPE_TIGHT
        )

    # A shop's takings under hype are one number however many waves carry them,
    # so the waves are gathered by the shop they land hardest on and each shop
    # gets one line. The waves come soonest-ending first, which the line keeps.
    by_top = {}
    for wave in hype:
        top = max(wave["sites"], key=lambda s: s["revenue"])
        by_top.setdefault(top["key"], (top, []))[1].append(wave)

    for top, waves in by_top.values():
        waves.sort(key=lambda w: w["daysLeft"])
        soonest = waves[0]["daysLeft"]
        if len(waves) == 1:
            left, n = waves[0]["daysLeft"], waves[0]["count"]
            if left <= 0:
                lines = msg("f.hype.lines.today", {"one": "{n} line ends today", "other": "{n} lines ends today"}, n=n)
            elif left == 1:
                lines = msg("f.hype.lines.tomorrow", {"one": "{n} line ends tomorrow", "other": "{n} lines ends tomorrow"}, n=n)
            else:
                lines = msg("f.hype.lines.left", {"one": "{n} line has {days} days left", "other": "{n} lines has {days} days left"},
                            n=n, days=left)
        else:
            parts = []
            for i, wave in enumerate(waves):
                left, n = wave["daysLeft"], wave["count"]
                if left <= 0:
                    parts.append(msg("f.hype.part.today", {"one": "{n} ends today",
                                                           "other": "{n} end today"}, n=n))
                elif left == 1:
                    parts.append(msg("f.hype.part.tomorrow", {"one": "{n} ends tomorrow",
                                                              "other": "{n} end tomorrow"}, n=n))
                elif i == 0:
                    parts.append(msg("f.hype.part.first", {"one": "{n} ends in {days} days",
                                                           "other": "{n} end in {days} days"}, n=n, days=left))
                else:
                    parts.append(msg("f.hype.part.later", {"one": "{n} in {days} days",
                                                           "other": "{n} in {days} days"}, n=n, days=left))
            lines = msg("f.hype.lines.waves", "{n} lines ({waves})",
                        n=sum(w["count"] for w in waves), waves=_msg_list(parts))
        one = len(waves) == 1
        hood = tok(waves[0]["hood"], hood_label(waves[0]["hood"]))
        # Pricing is somebody else's job in this company. When a wave lands on a
        # shop that is already full, the door turns part of it away — until the
        # wave's end date.
        full = full_hours(top["key"])
        # The baseline is the first wave's: the shop's own days before a later
        # wave already carry the earlier one.
        base = min(waves, key=lambda w: w["startDay"])["baseline"]
        if base:
            drop = max(top["revenue"] - base["revenue"], 0)
            said = dict(hood=hood, lines=lines, site=top["name"], revenue=top["revenue"],
                        base=base["revenue"], basis=base["basis"], drop=drop)
            if full and one:
                text = msg("f.hype.wave.full", {
                    "one": "{hood} hype on {lines}; {site} does ${revenue:,.0f}/day under it against ${base:,.0f} for "
                           "{basis}; about ${drop:,.0f}/day of revenue rides on the wave. It already runs within 10% "
                           "of capacity for {n} hour of a normal week, so the door is turning part of the wave "
                           "away.",
                    "other": "{hood} hype on {lines}; {site} does ${revenue:,.0f}/day under it against ${base:,.0f} for "
                             "{basis}; about ${drop:,.0f}/day of revenue rides on the wave. It already runs within "
                             "10% of capacity for {n} hours of a normal week, so the door is turning part of the "
                             "wave away.",
                }, n=full, **said)
            elif full:
                text = msg("f.hype.waves.full", {
                    "one": "{hood} hype on {lines}; {site} does ${revenue:,.0f}/day under it against ${base:,.0f} for "
                           "{basis}; about ${drop:,.0f}/day of revenue rides on the waves. It already runs within "
                           "10% of capacity for {n} hour of a normal week, so the door is turning part of the "
                           "waves away.",
                    "other": "{hood} hype on {lines}; {site} does ${revenue:,.0f}/day under it against ${base:,.0f} for "
                             "{basis}; about ${drop:,.0f}/day of revenue rides on the waves. It already runs within "
                             "10% of capacity for {n} hours of a normal week, so the door is turning part of the "
                             "waves away.",
                }, n=full, **said)
            elif one:
                text = msg("f.hype.wave", "{hood} hype on {lines}; {site} does ${revenue:,.0f}/day under it against "
                           "${base:,.0f} for {basis}; about ${drop:,.0f}/day of revenue rides on the wave.", **said)
            else:
                text = msg("f.hype.waves", "{hood} hype on {lines}; {site} does ${revenue:,.0f}/day under it against "
                           "${base:,.0f} for {basis}; about ${drop:,.0f}/day of revenue rides on the waves.", **said)
            note(
                "critical" if soonest <= 2 else "warn",
                top["name"],
                "hype",
                text,
                worth=drop,
                key=top["key"],
            )
        else:
            said = dict(hood=hood, lines=lines, site=top["name"], revenue=top["revenue"])
            note(
                "warn",
                top["name"],
                "hype",
                msg("f.hype.nobase", "{hood} hype on {lines}; {site} does ${revenue:,.0f}/day under it. There is no "
                    "shop of the same kind trading without a wave and no trading days before this one started, "
                    "so there is no baseline to say what the drop will be", **said)
                if one else
                msg("f.hype.nobase.waves", "{hood} hype on {lines}; {site} does ${revenue:,.0f}/day under it. There "
                    "is no shop of the same kind trading without a wave and no trading days before the first of "
                    "them started, so there is no baseline to say what the drop will be", **said),
                always=True,
                key=top["key"],
                amt=_amt(_shown(top["revenue"]), "/day under hype", sign="$"),
            )

    # --- a site whose week moved, against the week before it
    riding = {w["top"] for w in hype}
    for row in trends:
        if not row["ready"] or row["change"] is None:
            continue
        if abs(row["change"]) < TREND_MOVE:
            continue
        b = businesses[row["s"]]
        # A factory's takings are batch exports on the purchase calendar, not
        # trading; and a shop up under its own hype wave is the line above this
        # one said twice. An office's fees are trading like a shop's takings.
        if b["status"] not in ("retail", "office"):
            continue
        if row["change"] > 0 and b["key"] in riding:
            continue
        said = dict(pct=abs(row["change"]) * 100, now=row["last7"], start=day - 7, end=day - 1,
                    before=row["prev7"])
        note(
            "warn" if row["change"] < 0 else "info",
            b["name"],
            "trend",
            msg("f.trend.up", "Revenue up {pct:.0f}% week on week: ${now:,.0f} over days {start}-{end} against "
                "${before:,.0f} the week before", **said)
            if row["change"] > 0 else
            msg("f.trend.down", "Revenue down {pct:.0f}% week on week: ${now:,.0f} over days {start}-{end} against "
                "${before:,.0f} the week before", **said),
            worth=abs(row["last7"] - row["prev7"]) / 7,
            key=b["key"],
        )

    # A shop only runs dry if a day of selling outruns the morning top-up.
    found.extend(_shelf_notes(businesses, supply, silent, mode))

    # A depot only runs dry if it cannot reach the next delivery by more than a
    # few hours, and an order is only wrong if it cannot cover the week it has to
    # cover.
    found.extend(_import_notes(businesses, supply, silent, mode))

    # --- what the hour-by-hour grid says that a daily total cannot
    # Five shops hitting the same 30/h ceiling in the same hours is one finding
    # about five shops, not five findings. Offices group only with offices, and
    # a role's stations only with the same stations: two findings that name two
    # different answers are two lines, whatever else they share. A site held by
    # its building's own capacity is no line at all: there is nothing to do
    # about it, so it stays on the site page's hour grid and chip only.
    same = collections.OrderedDict()
    for finding in hours:
        if (
            finding["kind"] == "cap"
            and finding["key"] not in silent
            and finding["heldBy"][0][0] != "door"
        ):
            same.setdefault(
                (
                    finding.get("office", False),
                    finding["limit"],
                    finding["cap"],
                    finding.get("capTop", finding["cap"]),
                    finding["when"],
                    finding["hours"],
                    finding.get("noun"),
                    finding.get("fix"),
                ),
                [],
            ).append(finding)
    for (office, limit, cap, top, when, per_week, _noun, _fix), group in same.items():
        worth = sum(f["throughput"] for f in group)
        where = (
            group[0]["site"]
            if len(group) == 1
            else msg("f.site.offices", {"one": "{n} office", "other": "{n} offices"}, n=len(group))
            if office
            else msg("f.site.shops", {"one": "{n} shop", "other": "{n} shops"}, n=len(group))
        )
        said = dict(
            where=where, when=when, n=per_week, worth=worth, fix=group[0]["fix"],
            rate=msg("f.atcap.rate", "{n}/h", n=cap) if cap == top
            else msg("f.atcap.range", "{low}-{high}/h", low=cap, high=top),
            noun=group[0].get("noun") or _sp_counters(office),
            # Only the first character: a tie joins two limits, and
            # str.capitalize() would lowercase "DJ booths" in the second.
            # _cap_first() does that and keeps the limit a message.
            limit=_cap_first(limit),
        )
        several = group[0].get("limits", 1) > 1
        if len(group) == 1:
            text = (
                msg("f.atcap.limits", {
                    "one": "{where} fills the {noun} {when}, {n} hour a week at {rate} and "
                           "${worth:,.0f}/day of sales in those hours. {limit} are the limit; the fix is {fix}",
                    "other": "{where} fills the {noun} {when}, {n} hours a week at {rate} and "
                             "${worth:,.0f}/day of sales in those hours. {limit} are the limit; the fix is {fix}"}, **said)
                if several else
                msg("f.atcap", {
                    "one": "{where} fills the {noun} {when}, {n} hour a week at {rate} and "
                           "${worth:,.0f}/day of sales in those hours. {limit} is the limit; the fix is {fix}",
                    "other": "{where} fills the {noun} {when}, {n} hours a week at {rate} and "
                             "${worth:,.0f}/day of sales in those hours. {limit} is the limit; the fix is {fix}"}, **said)
            )
        else:
            sites = _msg_list([f["site"] for f in group])
            text = (
                msg("f.atcap.sites.limits", {
                    "one": "{where} fill the {noun} {when}, {n} hour a week at {rate} and "
                           "${worth:,.0f}/day of sales in those hours. {limit} are the limit; the fix is {fix}: {sites}",
                    "other": "{where} fill the {noun} {when}, {n} hours a week at {rate} and "
                             "${worth:,.0f}/day of sales in those hours. {limit} are the limit; the fix is {fix}: {sites}"}, sites=sites, **said)
                if several else
                msg("f.atcap.sites", {
                    "one": "{where} fill the {noun} {when}, {n} hour a week at {rate} and "
                           "${worth:,.0f}/day of sales in those hours. {limit} is the limit; the fix is {fix}: {sites}",
                    "other": "{where} fill the {noun} {when}, {n} hours a week at {rate} and "
                             "${worth:,.0f}/day of sales in those hours. {limit} is the limit; the fix is {fix}: {sites}"}, sites=sites, **said)
            )
        # One site can be at more than one ceiling, and the limit is what keeps
        # the ids apart: a role short of people says "Gym Trainer staffing" and
        # the same role short of posts says "fitness planning boards", so
        # silencing one line never silences the other. The limit alone is
        # hashed, and it is the string main hashed too, so a shop's and an
        # office's silences survive this change.
        note(
            "warn", where, "atcap", text, subject=plain(limit), named=limit, worth=worth,
            key=group[0]["key"] if len(group) == 1 else None,
        )

    # --- overstaffing: one line per site, the whole week of it. The hour grid
    # keeps every idle run of the site's roles under "week"; a finding written
    # before that existed carries its one run and is read as a week of one.
    for finding in hours:
        if finding["key"] in silent or finding["kind"] != "idle":
            continue
        site = finding["site"]
        default = _sp_counters(finding.get("office", False))
        week = finding.get("week") or {
            "spare": finding["spare"],
            "worth": finding["worth"],
            "seen": finding["seen"],
            "parts": [{
                "noun": finding.get("noun"),
                "staff": finding["staff"],
                "when": _hour_phrase({WEEKDAYS.index(finding["day"]): set(
                    range(finding["from"], finding["to"]))}),
            }],
        }
        runs = _idle_parts(week["parts"], default)
        note(
            "info",
            site,
            "idlestaff",
            # The waste leads, so the row's headline is the whole week's figure
            # and the shape of the hours unfolds as its detail.
            msg("f.idlestaff", {
                "one": "{site} has {n} staffed hour a week more than its customers need: {runs}, at {seen} customers an hour",
                "other": "{site} has {n} staffed hours a week more than its customers need: {runs}, at {seen} customers an hour",
            }, site=site, n=week["spare"], runs=runs, seen=week["seen"]),
            worth=week["worth"],
            key=finding["key"],
        )

    found.extend(_idle_notes(businesses, supply["idle"], silent, mode))
    found.extend(_feed_notes(businesses, supply.get("factories", {}), silent, mode))
    found.extend(_staff_notes(businesses, supply.get("factories", {}), silent, mode))
    found.extend(_unnamed_notes(businesses, supply.get("factories", {}), silent))
    return _condense(found, gate)


def _fact_labels(businesses: list, supply: dict) -> dict:
    """(site index, slug) -> the name a finding gives the goods: the site's own
    line, else what an import row or a factory line calls it."""
    labels, by_slug = {}, {}
    for i, b in enumerate(businesses):
        for line in b.get("lines", []):
            labels.setdefault((i, line["slug"]), line["item"])
            by_slug.setdefault(line["slug"], line["item"])
    for row in supply.get("imports", []):
        labels.setdefault((row["s"], row["slug"]), row["item"])
    for site in supply.get("factories", {}).get("sites", []):
        for row in site["needs"]:
            labels.setdefault((site["s"], row["slug"]), row["item"])
            if row.get("importSite") is not None:
                labels.setdefault((row["importSite"], row["slug"]), row["item"])
    # A site the plans ask for goods it has never held: another site's name for them.
    for s, items in supply.get("facts", {}).items():
        for slug in items:
            if slug in by_slug:
                labels.setdefault((int(s), slug), by_slug[slug])
    return labels


def _shelf_notes(businesses: list, supply: dict, silent: set, mode: str = "cap") -> list:
    """A shelf on no plan with little left, or a top-up its busiest day outruns.

    Read off the shelf's fact. A tight top-up (covers the day, not the margin)
    is for the Checks and Orders pages, never a finding here; a shelf the Not
    routed finding names (`via`) is said there, once.
    """
    facts = supply.get("facts", {})
    rows = {(r["s"], r["slug"]): r for r in supply.get("shops", [])}
    labels = _fact_labels(businesses, supply)
    notes = []
    for s_key in _in_order(facts):
        s = int(s_key)
        b = businesses[s]
        # A shop shut with the game's temporarily closed switch sells nothing:
        # its shelves are no finding (the not-trading finding names it).
        if b["key"] in silent or b.get("closed"):
            continue
        # Nothing upstream supplies it (_supply_facts' shelf()): one finding
        # per shop, however many of its goods it is (a shop pricing a dozen
        # things nothing brings is one thing to sort out).
        unsourced = []
        for slug in _in_order(facts[s_key]):
            fact = _supply_fact(facts, s, slug, mode)
            if (fact["role"] == "shelf" and fact["st"] == "noplan"
                    and fact["why"] in ("source", "priced") and fact["lvl"] != "info"):
                unsourced.append((slug, fact))
        if unsourced:
            notes.append(_unsourced_note(businesses, b, s, unsourced, labels))
        for slug in _in_order(facts[s_key]):
            fact = _supply_fact(facts, s, slug, mode)
            if fact["role"] != "shelf":
                continue
            if fact["st"] == "noplan" and fact["why"] in ("source", "priced"):
                continue
            line = next((l for l in b["lines"] if l["slug"] == slug), None)
            if not line:
                continue
            item = tok(slug, line["item"])
            if (fact["st"] == "noplan" and fact["lvl"] in ("warn", "critical")
                    and fact.get("via") is None):
                rate = round(line.get("tradeRate", line["rate"]))
                notes.append(_finding(
                    fact["lvl"], b["name"], "unplanned",
                    msg("f.unplanned", "{item} is on no distribution plan: {units:,} left at {rate:,}/day",
                        item=item, units=line["units"], rate=rate),
                    key=b["key"], rank=-line["units"], subject=line["item"], named=item, ev={"slug": slug},
                    amt=_amt(rate, "/day")))
            elif fact["st"] == "short" and fact["cad"] == "weekly":
                # Fed by a weekly wholesale delivery, not a top-up.
                rate = round(line.get("tradeRate", line["rate"]))
                row = rows.get((s, slug)) or {}
                day = fact.get("day") or row.get("wholesaleDay")
                day = (msg("f.wholesale.day", "{d:day}", d=WEEKDAYS.index(day)) if day in WEEKDAYS
                       else day or msg("f.wholesale.next", "the next"))
                also_short = _below(fact["have"], fact["use"])
                said = dict(item=item, day=day, have=fact["have"], use=fact["use"])
                if fact["why"] == "shortfall" and also_short:
                    # Both at once: the stock does not reach the drop, and the
                    # delivery would not carry the week if it did.
                    text = (msg("f.wholesale.both.raise", "{item} runs out before {day}'s wholesale delivery, and "
                                "the delivery brings {have:,} a week against the {use:,} it sells; raise the "
                                "contract to {set:,}", set=fact["setTo"], **said)
                            if fact.get("setTo") else
                            msg("f.wholesale.both", "{item} runs out before {day}'s wholesale delivery, and the "
                                "delivery brings {have:,} a week against the {use:,} it sells", **said))
                elif fact["why"] == "shortfall":
                    text = msg("f.wholesale.shortfall", "{item} runs out before {day}'s wholesale delivery: "
                               "{units:,} left at {rate:,}/day", item=item, day=day, units=line["units"], rate=rate)
                else:
                    text = msg("f.wholesale.order", "{item}'s wholesale delivery brings {have:,} a week against "
                               "the {use:,} it sells", **said)
                # Running out before the delivery ranks ahead of an order
                # short of the week; the ratio breaks ties among each.
                ratio = round(fact["have"] / fact["use"], 2) if fact["use"] else 0
                notes.append(_finding(
                    fact["lvl"], b["name"], "wholesale", text, key=b["key"],
                    rank=ratio - 10 if fact["why"] == "shortfall" else ratio,
                    subject=line["item"], named=item, ev={"slug": slug},
                    amt=_amt(line["units"], "left") if fact["why"] == "shortfall" and not also_short
                    else _amt(fact["use"], "/week used")))
            elif fact["st"] == "short" and fact["why"] == "target":
                peak = (rows.get((s, slug)) or {}).get("peakDay")
                notes.append(_finding(
                    "critical", b["name"], "outruns",
                    msg("f.outruns.day", "{item} sells {use:,} on a {d:day} against a {have:,} top-up; empties "
                        "before the next drop", item=item, use=fact["use"], have=fact["have"],
                        d=WEEKDAYS.index(peak))
                    if peak in WEEKDAYS else
                    msg("f.outruns", "{item} sells {use:,} on its busiest day against a {have:,} top-up; empties "
                        "before the next drop", item=item, use=fact["use"], have=fact["have"]),
                    key=b["key"],
                    rank=-round(fact["use"] / fact["have"] * 100) if fact["have"] else 0,
                    subject=line["item"], named=item, ev={"slug": slug}))
    return notes


def _lasts_msg(days):
    """How long a holding lasts, as a finding says it: "about 18 days", and
    past LASTS_CAP days "over 60 days", as the cover figures cap it."""
    days = days or 0
    if days > LASTS_CAP:
        return msg("f.lasts.over", "over {n:,} days", n=LASTS_CAP)
    return msg("f.lasts.about", {"one": "about {n:,} day", "other": "about {n:,} days"}, n=max(1, round(days)))


def _unsourced_note(businesses: list, b: dict, s: int, found: list, labels: dict) -> dict:
    """One shop's goods nothing upstream supplies, as one finding: a top-up
    from a site that has none coming in, or a price with nothing bringing it.
    One item is said on its own; several are listed, the ones with a top-up
    first, and the finding lands on the first."""
    found = sorted(found, key=lambda sf: (sf[1]["why"] != "source", -(sf[1].get("have") or 0), str(sf[0])))
    level = "critical" if any(f["lvl"] == "critical" for _slug, f in found) else "warn"
    slug, fact = found[0]
    label = labels.get((s, slug), slug)
    named = tok(slug, label)
    source = fact.get("from")
    if len(found) > 1:
        items = [tok(sl, labels.get((s, sl), sl)) for sl, _f in found]
        text = msg("f.unsourced.list", "Nothing upstream supplies {n} goods {site} is topped up with or prices: "
                   "{items}; add them to an import, or to a route from a factory that makes them",
                   n=len(found), site=b["name"], items=_msg_list(items))
    elif fact["why"] == "source" and source is not None and 0 <= source < len(businesses):
        text = msg("f.unsourced", "{item} is topped up to {have:,} from {source}, but nothing brings "
                   "it to {source}: no stock, import, factory line or route; add it to an import "
                   "there, or to a route from a factory that makes it",
                   item=named, have=fact["have"], source=businesses[source]["name"])
    else:
        text = msg("f.unsourced.priced", "{item} is priced here but nothing brings it: no top-up, "
                   "wholesale delivery or import; add it to a route from a depot or factory",
                   item=named)
    return _finding(level, b["name"], "unsourced", text, key=b["key"],
                    rank=-len(found), subject=label, named=named, ev={"slug": slug})


def _import_notes(businesses: list, supply: dict, silent: set, mode: str = "cap") -> list:
    """A line an import brings, when its week or its stock falls short.

    One finding per (site, item), read off the fact: a depot's, or a factory's
    own import. An import the factory lines draw on is said in their words
    (kind feed), one only other sites draw on in the order's (order, paused);
    stock that will not reach the drop is a shortfall either way. Tight is
    never a finding here.
    """
    facts = supply.get("facts", {})
    # The rows walked in the sizing asked for: Demand's own where it was sent.
    rows = {(r["s"], r["slug"]): r
            for r in (supply.get("importsDem", supply.get("imports", [])) if mode == "dem"
                      else supply.get("imports", []))}
    depots = supply.get("factories", {}).get("depots", {})
    labels = _fact_labels(businesses, supply)
    notes = []
    for s_key in _in_order(facts):
        s = int(s_key)
        b = businesses[s]
        if b["key"] in silent:
            continue
        for slug in _in_order(facts[s_key]):
            whole = _supply_fact(facts, s, slug, mode)
            # A factory's own contract beside a daily top-up is its `import`.
            fact = whole.get("import") or whole
            # A depot only a route from your own site feeds: its daily top-up
            # against its busiest day, as a shelf's (tight is no finding).
            if fact["role"] == "depot" and fact["cad"] == "daily":
                if fact["st"] == "short" and fact["why"] == "target":
                    item = labels.get((s, slug), slug)
                    named = tok(slug, item)
                    plans = [fact.get("from")] + [r[0] for r in fact.get("raise") or ()]
                    notes.append(_finding(
                        "critical", b["name"], "topup",
                        msg("f.topup.several", "{item} is topped up to {have:,} a day against the {use:,} its busiest "
                            "day sends on; raise the top-ups on the plans of {sites} to {set:,}",
                            item=named, have=fact["have"], use=fact["use"], set=fact["setTo"],
                            sites=_msg_list([businesses[x]["name"] for x in plans if x is not None]))
                        if fact.get("raise") else
                        msg("f.topup", "{item} is topped up to {have:,} a day against the {use:,} its busiest day "
                            "sends on; raise the top-up to {set:,}",
                            item=named, have=fact["have"], use=fact["use"], set=fact["setTo"]),
                        key=b["key"], rank=round(fact["have"] / fact["use"], 2) if fact["use"] else 0,
                        subject=item, named=named, ev={"slug": slug}))
                continue
            if fact["cad"] != "weekly" or fact["role"] not in ("depot", "input"):
                continue
            st, why = fact["st"], fact["why"]
            # A factory's own paused contract beside a top-up is said with the
            # input (_feed_notes), once; one the top-up covers is no finding.
            if st == "paused" and whole is not fact:
                continue
            if not (st == "paused" or (st == "short" and why in ("order", "shortfall"))
                    or (st == "noplan" and fact["lvl"] != "info")):
                continue
            item = labels.get((s, slug), slug)
            named = tok(slug, item)
            row = rows.get((s, slug))
            entry = depots.get(s, {}).get(slug) or {}
            parts = fact.get("parts") or {}
            site, key = b["name"], b["key"]
            ev = {"slug": slug}
            if st == "short" and why == "shortfall" and row:
                notes.append(_shortfall_note(row, item, site, key, businesses))
                continue
            if st == "short" and fact["role"] == "depot" and fact.get("wholesale"):
                # A depot a wholesale store delivers to: its contract, said on
                # the depot's own page (Weekly imports does not list it).
                said = dict(item=named, have=fact["have"], use=fact["use"], route=parts.get("route"),
                            set=fact.get("setTo"))
                if parts.get("route") and fact.get("setTo"):
                    text = msg("f.depot.wholesale.route.raise", "{item}'s wholesale delivery brings {have:,} a week "
                               "against {use:,} used beyond the {route:,} a week a route brings; raise the contract "
                               "to {set:,}", **said)
                elif parts.get("route"):
                    text = msg("f.depot.wholesale.route", "{item}'s wholesale delivery brings {have:,} a week "
                               "against {use:,} used beyond the {route:,} a week a route brings", **said)
                elif fact.get("setTo"):
                    text = msg("f.depot.wholesale.raise", "{item}'s wholesale delivery brings {have:,} a week "
                               "against {use:,} used; raise the contract to {set:,}", **said)
                else:
                    text = msg("f.depot.wholesale", "{item}'s wholesale delivery brings {have:,} a week against "
                               "{use:,} used", **said)
                notes.append(_finding(
                    fact["lvl"], site, "wholesale", text,
                    key=key, rank=round(fact["have"] / fact["use"], 2) if fact["use"] else 0,
                    subject=item, named=named, ev=ev, amt=_amt(fact["use"], "/week used")))
                continue
            smart = _smart_words(entry.get("target") or 0, entry.get("plainAfter", 0),
                                 entry.get("plainBefore", 0)) if entry.get("smart") else ""
            if parts.get("lines") or fact["role"] == "input":
                amt = None
                if st == "paused":
                    text = msg("f.import.paused.resume", "{item} import is paused; resume the contract supplying "
                               "{site}", item=named, site=site)
                elif st == "noplan":
                    stock = next((l["units"] for l in b["lines"] if l["slug"] == slug), 0)
                    said = dict(item=named, site=site, stock=stock, use=fact["use"], route=parts.get("route"),
                                weeks=stock / fact["use"] if fact["use"] else 0)
                    amt = _amt(said["weeks"], "weeks", places=1)
                    # The factories alone, or other sites drawing on it too;
                    # and a route bringing part of the week, or not.
                    if not parts.get("sites") and parts.get("route"):
                        text = msg("f.import.noplan.route", "{item} has no standing import; {site} holds {stock:,}, "
                                   "{weeks:.1f} weeks of the {use:,} a week the factories eat beyond the {route:,} a "
                                   "week a route brings", **said)
                    elif not parts.get("sites"):
                        text = msg("f.import.noplan", "{item} has no standing import; {site} holds {stock:,}, "
                                   "{weeks:.1f} weeks of the {use:,} a week the factories eat", **said)
                    elif parts.get("route"):
                        text = msg("f.import.noplan.sites.route", "{item} has no standing import; {site} holds "
                                   "{stock:,}, {weeks:.1f} weeks of the {use:,} a week the factories and other sites "
                                   "draw beyond the {route:,} a week a route brings", **said)
                    else:
                        text = msg("f.import.noplan.sites", "{item} has no standing import; {site} holds {stock:,}, "
                                   "{weeks:.1f} weeks of the {use:,} a week the factories and other sites draw",
                                   **said)
                elif entry.get("smart"):
                    said = dict(item=named, use=fact["use"], smart=smart, at=entry.get("levelName"),
                                set=fact.get("setTo"))
                    if entry.get("levelName") and fact.get("setTo"):
                        text = msg("f.import.smart.at.raise", "{item}: this import needs to cover {use:,} a week and "
                                   "{smart}; raise the Smart Delivery stock at {at} to {set:,}", **said)
                    elif entry.get("levelName"):
                        text = msg("f.import.smart.at", "{item}: this import needs to cover {use:,} a week and "
                                   "{smart}; raise the Smart Delivery stock at {at}", **said)
                    elif fact.get("setTo"):
                        text = msg("f.import.smart.raise", "{item}: this import needs to cover {use:,} a week and "
                                   "{smart}; raise the Smart Delivery stock to {set:,}", **said)
                    else:
                        text = msg("f.import.smart", "{item}: this import needs to cover {use:,} a week and "
                                   "{smart}; raise the Smart Delivery stock", **said)
                elif fact.get("setTo"):
                    text = msg("f.import.order.raise", "{item}: this import needs to cover {use:,} a week and the "
                               "import order is {order:,}; raise it to {set:,}",
                               item=named, use=fact["use"], order=entry.get("weekly", 0), set=fact["setTo"])
                else:
                    text = msg("f.import.order", "{item}: this import needs to cover {use:,} a week and the import "
                               "order is {order:,}", item=named, use=fact["use"], order=entry.get("weekly", 0))
                notes.append(_finding(fact["lvl"], site, "feed", text, key=key,
                                      rank=-round(fact["use"] / 7), subject=item, named=named, ev=ev, amt=amt))
                continue
            if st == "noplan":
                # A depot only shops draw on, with no standing import: nothing
                # brings it, or the routes into it cannot bring what it sends
                # on (_supply_facts' route_fed()). Nothing upstream supplies
                # it, as a shelf's unsourced finding says of a shelf.
                passes = fact.get("passes")
                said = dict(item=named, site=site, use=fact["use"], route=parts.get("route", 0),
                            total=fact["use"] + parts.get("route", 0), set=fact.get("setTo") or 0,
                            lasts=_lasts_msg(fact.get("lasts")),
                            sender=businesses[passes]["name"] if passes is not None else "")
                # Nothing brings it, or only what a sender holds: nothing
                # upstream supplies it (unsourced). Routes that bring part of
                # it leave an import to add (order).
                group = "unsourced"
                if passes is not None:
                    text = msg("f.depot.noplan.passes", "{item}: no standing supply brings it to {site}; the route "
                               "from {sender} only passes on what it holds, {lasts} of the {use:,} a week {site} "
                               "sends on; import {set:,} a week", **said)
                elif parts.get("route"):
                    group = "order"
                    text = msg("f.depot.noplan.route", "{item}: the routes into {site} bring {route:,} a week of "
                               "the {total:,} a week it sends on, and no standing import brings the rest; import "
                               "{set:,} a week", **said)
                else:
                    text = msg("f.depot.noplan", "{item}: nothing brings it to {site}, which sends on {use:,} a "
                               "week; import {set:,} a week", **said)
                said_as = dict(key=key, rank=-round(fact["use"] / 7), subject=item, named=named, ev=ev,
                               amt=_amt(said["lasts"].p["n"], "days") if passes is not None else None)
                notes.append(_finding(fact["lvl"], site, "order", text, **said_as) if group == "order"
                             else _finding(fact["lvl"], site, "unsourced", text, **said_as))
                continue
            cover = row["cover"] if row else 0
            if st == "paused":
                # round() is what {cover:.0f} printed, and a whole number
                # picks the plural a translation needs.
                text = (msg("f.paused", {"one": "{item} import is paused: {n} day left at {rate:,}/day",
                                         "other": "{item} import is paused: {n} days left at {rate:,}/day"},
                            item=named, n=round(cover), rate=row.get("importPerDay", row["perDay"]))
                        if row else msg("f.paused.bare", "{item} import is paused", item=named))
                notes.append(_finding(fact["lvl"], site, "paused", text,
                                      key=key, rank=cover, subject=item, named=named, ev=ev,
                                      amt=_amt(row.get("importPerDay", row["perDay"]), "/day") if row else None))
                continue
            text = _order_text(businesses, fact, entry, row, named)
            notes.append(_finding(fact["lvl"], site, "order", text,
                                  key=key, rank=cover, subject=item, named=named, ev=ev,
                                  amt=_amt(text.p["short"], "units short")))
    return notes


def _order_text(businesses: list, fact: dict, entry: dict, row: dict | None, named) -> "Msg":
    """An import order short of its week, as its finding says it: how soon
    it bites (the stock runs dry before the drop, the route that only passes
    on what its sender holds, or what is held here), or the order alone."""
    smart = _smart_words(entry.get("target") or 0, entry.get("plainAfter", 0),
                         entry.get("plainBefore", 0)) if entry.get("smart") else ""
    brought = entry.get("weekly", 0)
    said = dict(item=named, smart=smart, brought=brought, use=fact["use"], short=fact["use"] - brought)
    if row and row["coverFit"] == "short":
        said.update(when=_runs_dry_when(row), by=row["shortBy"],
                    arrives=row.get("coverageUntil", row["arrives"]))
        text = (msg("f.order.smart.dry", "{item}: {smart} against a {use:,} week of use, {short:,} short; "
                    "already runs dry {when}, {by:.1f} days before {arrives:day}'s import", **said)
                if entry.get("smart") else
                msg("f.order.dry", "{item} orders {brought:,} a week against a {use:,} week of use, "
                    "{short:,} short; already runs dry {when}, {by:.1f} days before {arrives:day}'s import",
                    **said))
    elif fact.get("passes") is not None:
        # The route into the depot only passes on what its sender
        # holds: how long that lasts is how soon the order bites.
        said.update(sender=businesses[fact["passes"]]["name"], lasts=_lasts_msg(fact.get("lasts")))
        text = (msg("f.order.smart.passes", "{item}: {smart} against a {use:,} week of use, {short:,} "
                    "short; the route from {sender} only passes on what it holds, {lasts} of it",
                    **said)
                if entry.get("smart") else
                msg("f.order.passes", "{item} orders {brought:,} a week against a {use:,} week of use, "
                    "{short:,} short; the route from {sender} only passes on what it holds, {lasts} "
                    "of it", **said))
    elif fact["lvl"] == "warn" and fact.get("lasts") is not None:
        # Short of its week, but what is held here lasts beyond it.
        said.update(lasts=_lasts_msg(fact["lasts"]))
        text = (msg("f.order.smart.lasts", "{item}: {smart} against a {use:,} week of use, {short:,} "
                    "short; what is held here lasts {lasts}", **said)
                if entry.get("smart") else
                msg("f.order.lasts", "{item} orders {brought:,} a week against a {use:,} week of use, "
                    "{short:,} short; what is held here lasts {lasts}", **said))
    elif entry.get("smart"):
        text = msg("f.order.smart", "{item}: {smart} against a {use:,} week of use, {short:,} short", **said)
    else:
        text = msg("f.order", "{item} orders {brought:,} a week against a {use:,} week of use, {short:,} "
                   "short", **said)
    return text


def _order_says(businesses: list, supply: dict) -> None:
    """The order finding's sentence on each short import line whose finding
    says how long its stock lasts or which route only passes on what it
    holds (fact `says`, and under `dem` where Demand sizing says it
    differently): the Supply table's status tip gives it for every line,
    where the findings list gives one line of a site. In place."""
    facts = supply.get("facts", {})
    depots = supply.get("factories", {}).get("depots", {})
    labels = _fact_labels(businesses, supply)
    rows = {mode: {(r["s"], r["slug"]): r for r in (supply.get("importsDem", supply.get("imports", []))
                                                    if mode == "dem" else supply.get("imports", []))}
            for mode in SIZING_MODES}
    for s_key in _in_order(facts):
        s = int(s_key)
        for slug in _in_order(facts[s_key]):
            entry = depots.get(s, {}).get(slug) or {}
            said = {}
            for mode in SIZING_MODES:
                fact = _supply_fact(facts, s, slug, mode)
                row = rows[mode].get((s, slug))
                if (fact.get("role") != "depot" or fact.get("cad") != "weekly" or fact.get("st") != "short"
                        or fact.get("why") != "order" or not entry
                        or (row and row["coverFit"] == "short")
                        or not (fact.get("passes") is not None
                                or (fact.get("lvl") == "warn" and fact.get("lasts") is not None))):
                    said[mode] = None
                    continue
                said[mode] = _order_text(businesses, fact, entry, row, tok(slug, labels.get((s, slug), slug)))
            base = facts[s_key][slug]
            if said["cap"] is not None:
                base["says"] = said["cap"]
            if said["dem"] != said["cap"]:
                base.setdefault("dem", {})["says"] = said["dem"]


def _runs_dry_when(row: dict):
    """When an import row's stock runs dry, as the findings say it: on its
    weekday, or in so many days."""
    if row["runsOut"]:
        return msg("f.dry.on", "on {d:day}", d=WEEKDAYS.index(row["runsOut"]))
    # cover is a float, printed "1.0": English keeps "days" for it.
    return msg("f.dry.in", {"one": "in {n} days", "other": "in {n} days"}, n=row["cover"])


def _shortfall_note(row: dict, item: str, site: str, key: str, businesses: list | None = None) -> dict:
    """A depot's stock that will not reach its next drop, or, where a route
    brings the week, a busy day the shelf cannot carry to the next round.
    Where the morning rounds to a depot beside it are what runs it dry
    before that depot's own import lands (`topsUp`), the finding names that
    depot and the target the rounds fill it to."""
    named = tok(row["slug"], item)
    # The draw the import answers for; a route's share is named, not hidden.
    said = dict(item=named, when=_runs_dry_when(row), routed=row.get("routed"),
                rate=row.get("importPerDay", row["perDay"]))
    if row.get("covered"):
        text = (msg("f.shortfall.route.paused", "{item} runs dry {when}, before the route's next round; a route "
                    "brings the week's draw ({routed:,}/day) but a busy day outruns the shelf; the import is paused",
                    **said)
                if row["paused"] else
                msg("f.shortfall.route", "{item} runs dry {when}, before the route's next round; a route brings the "
                    "week's draw ({routed:,}/day) but a busy day outruns the shelf", **said))
    elif row.get("topsUp") and businesses and 0 <= row["topsUp"][0] < len(businesses):
        said.update(by=row["shortBy"], arrives=row.get("coverageUntil", row["arrives"]),
                    site=businesses[row["topsUp"][0]]["name"], target=row["topsUp"][1])
        text = msg("f.shortfall.topup", "{item} runs dry {when}, {by:.1f} days before {arrives:day}'s import: the "
                   "morning rounds top {site} up to {target:,} before its own import lands", **said)
    else:
        said.update(by=row["shortBy"], arrives=row.get("coverageUntil", row["arrives"]))
        text = (msg("f.shortfall.routed", "{item} runs dry {when}, {by:.1f} days before {arrives:day}'s import "
                    "({rate:,}/day beyond the {routed:,}/day a route brings)", **said)
                if row.get("routed") else
                msg("f.shortfall", "{item} runs dry {when}, {by:.1f} days before {arrives:day}'s import ({rate:,}/day, "
                    "{peak:,} at peak)", peak=row["peakPerDay"], **said))
    # How many days early it runs dry, or, where a route brings the week, the
    # route's draw.
    amt = (_amt(said["routed"], "/day") if row.get("covered")
           else _amt(said["by"], "days early", places=1))
    return _finding("critical", site, "shortfall", text,
                    key=key, rank=row["cover"], subject=item, named=named, ev={"slug": row["slug"]}, amt=amt)


def _unnamed_notes(businesses: list, factories: dict, silent: set) -> list:
    """A machine whose recipe the board cannot read, and the needs it hides.

    Two different things wear the same badge on the lines table. A machine with
    no recipe selected at all is standing still and costing rent; one that is
    running a recipe the board cannot identify may be working, but
    every input need at that site is short by whatever it eats — which is worth
    saying out loud, because nothing else on the board looks wrong.
    """
    notes = []
    for site in factories.get("sites", []):
        business = businesses[site["s"]]
        if business["key"] in silent:
            continue
        for kind, group, level in (("idle", "unset", "critical"), ("blind", "unnamed", "warn")):
            rows = [u for u in site["unnamed"] if u["idle"] == (kind == "idle")]
            machines = sum(u["machines"] for u in rows)
            if not machines:
                continue
            where = ", ".join(
                sorted({f"{u['workstation']} #{s}" for u in rows for s in u["slots"]})
            )
            # The same places in the same order, their workstation a token.
            spots = {f"{u['workstation']} #{s}": msg("f.unnamed.spot", "{station} #{slot}",
                                                       station=tok(u.get("workstationKey"), u["workstation"]),
                                                       slot=s)
                     for u in rows for s in u["slots"]}
            shown = _msg_list([spots[w] for w in sorted(spots)]) if spots else ""
            if kind == "idle":
                text = msg("f.unset", {
                    "one": "{n} machine at {spots} has no recipe set: staffed and rented, making nothing",
                    "other": "{n} machines at {spots} have no recipe set: staffed and rented, making nothing",
                }, n=machines, spots=shown)
            else:
                text = msg("f.unnamed", {
                    "one": "{n} machine at {spots} runs a recipe without usable details. Its inputs are missing "
                           "from the totals; name unknown recipes or load matching game text to include them",
                    "other": "{n} machines at {spots} run a recipe without usable details. Its inputs are missing "
                             "from the totals; name unknown recipes or load matching game text to include them",
                }, n=machines, spots=shown)
            notes.append(
                _finding(
                    level, business["name"], group, text,
                    key=business["key"], rank=-machines, subject=where, named=shown,
                    amt=_amt(machines, "machine" if machines == 1 else "machines"),
                )
            )
    return notes


def _staff_notes(businesses: list, factories: dict, silent: set, mode: str = "cap") -> list:
    """A factory machine nobody is posted to for part of the week stands still.

    Sized 24/7 a machine needs all STAFF_HOURS of the week; sized for demand a
    named line's machine needs only its `needHours.dem` a day, so it is a gap
    only below that week. The finding's id does not change with the mode.
    """
    notes = []
    for site in factories.get("sites", []):
        business = businesses[site["s"]]
        if business["key"] in silent:
            continue
        for line in site["lines"] + site["unnamed"]:
            name = line.get("item") or line["workstation"]
            named = (tok(line.get("slug"), line["item"]) if line.get("item")
                     else tok(line.get("workstationKey"), line["workstation"]))
            week = STAFF_HOURS
            if mode == "dem" and line.get("needHours"):
                week = line["needHours"]["dem"] * 7
            for machine in line.get("gaps", []):
                if machine["hours"] >= week:
                    continue
                share = machine["hours"] / week
                lost = round((week - machine["hours"]) / 7 * line.get("rate", 0))
                subject = f"{name} at position {machine['slot']}"
                said = dict(item=named, slot=machine["slot"], hours=machine["hours"], week=week,
                            off=machine["off"])
                if week < STAFF_HOURS:
                    text = (
                        msg("sp.py.staff.needed.lost", "{item} machine at list position {slot} is staffed "
                            "{hours} of {week} hours needed; nobody on it {off}; {lost:,} a day not made",
                            lost=lost, **said)
                        if lost else
                        msg("sp.py.staff.needed", "{item} machine at list position {slot} is staffed "
                            "{hours} of {week} hours needed; nobody on it {off}", **said)
                    )
                else:
                    text = (
                        msg("sp.py.staff.lost", "{item} machine at list position {slot} is staffed "
                            "{hours} of {week} hours; nobody on it {off}; {lost:,} a day not made",
                            lost=lost, **said)
                        if lost else
                        msg("sp.py.staff", "{item} machine at list position {slot} is staffed "
                            "{hours} of {week} hours; nobody on it {off}", **said)
                    )
                notes.append(
                    _finding(
                        "critical" if share < STAFF_CRITICAL else "warn",
                        business["name"], "staff", text,
                        key=business["key"], rank=machine["hours"], subject=subject,
                        named=msg("sp.py.staff.named", "{item} at position {slot}",
                                  item=named, slot=machine["slot"]),
                        ev={"slot": machine["slot"], "slug": line.get("slug")},
                        amt=_amt(machine["hours"], "hours staffed", of=week),
                    )
                )
    return notes


def _feed_notes(businesses: list, factories: dict, silent: set, mode: str = "cap") -> list:
    """A factory input its top-up does not cover, with the number to change.

    Read off the input's verdict (its fact, mirrored on the row, with what
    Demand sizing changes under `dem`). An input an import brings straight to
    the factory is judged on its week by _import_notes(), and a depot's import
    there too, once however many factories draw on it.
    """
    notes = []
    for site in factories.get("sites", []):
        business = businesses[site["s"]]
        if business["key"] in silent:
            continue
        for base in site["needs"]:
            if base.get("directImport"):
                continue
            row = {**base, **base["dem"]} if mode == "dem" and base.get("dem") else base
            status, why = row["status"], row.get("why")
            per_day = row.get("use", base["perDay"])
            depot = (businesses[row["from"]]["name"] if row["from"] is not None
                     else msg("f.feed.depot", "the depot"))
            slugs = row.get("lineSlugs") or []
            lines = [tok(slugs[i] if i < len(slugs) else None, line) for i, line in enumerate(row["lines"][:3])]
            item = tok(row.get("slug"), row["item"])
            if status == "noplan" and row.get("via") is not None:
                continue  # said once, by the depot's Not routed finding
            # The paused own import is offered as the other way out, after
            # whatever the sentence says first.
            own = bool(row.get("ownPaused"))
            said = dict(item=item, per=per_day, depot=depot, site=business["name"])
            amt = _amt(per_day, "/day needed")
            if status == "noplan":
                amt = _amt(per_day, "/day")
                said.update(lines=_msg_list(lines) if lines else "")
                text = (msg("f.feed.noplan.resume", "{item} feeds {lines} at {per:,}/day but no depot tops it up; "
                            "or resume the paused {item} import to {site}", **said)
                        if own else
                        msg("f.feed.noplan", "{item} feeds {lines} at {per:,}/day but no depot tops it up", **said))
            elif status == "short" and why == "target":
                raise_to = row.get("setTo", base.get("raiseTarget"))
                # round() is what {hours:.0f} printed, and a whole number
                # picks the plural a translation needs.
                said.update(target=row["target"], n=round(row["target"] / per_day * 24 if per_day else 0),
                            set=raise_to)
                if row.get("stalled"):
                    said.update(stock=row["depotStock"])
                amt = _amt(said["n"], "hours covered")
                text = _feed_target_text(bool(raise_to), bool(row.get("stalled")), own, said)
            elif status == "short" and why == "dry":
                said.update(arrives=row["arrives"], stock=row["depotStock"])
                text = (msg("f.feed.dry.resume", "{item} arrives at {arrives:,}/day against {per:,} needed and "
                            "{depot} holds {stock:,}; the import is not keeping up; or resume the paused {item} "
                            "import to {site}", **said)
                        if own else
                        msg("f.feed.dry", "{item} arrives at {arrives:,}/day against {per:,} needed and {depot} "
                            "holds {stock:,}; the import is not keeping up", **said))
            elif status == "stalled" and why == "notDrawn":
                said.update(arrives=row["arrives"], stock=row["depotStock"])
                text = (msg("f.feed.notdrawn.resume", "{item} arrives at {arrives:,}/day against {per:,} needed "
                            "while {depot} holds {stock:,}; it isn't reaching the factory; or resume the paused {item} "
                            "import to {site}", **said)
                        if own else
                        msg("f.feed.notdrawn", "{item} arrives at {arrives:,}/day against {per:,} needed while "
                            "{depot} holds {stock:,}; it isn't reaching the factory", **said))
            else:
                continue
            notes.append(
                _finding(
                    row["level"], business["name"], "feed", text,
                    key=business["key"], rank=-base["perDay"], subject=row["item"], named=item,
                    ev={"slug": row["slug"]}, amt=amt,
                )
            )
    return notes


def _feed_target_text(raise_it: bool, stalled: bool, own: bool, said: dict):
    """_feed_notes()'s sentence for a top-up short of the line: the number to
    raise it to, the week nothing arrived and the paused own import, each
    where it applies. `said` holds item, target, n (the hours covered), per,
    set, depot, stock and site."""
    if raise_it and stalled and own:
        return msg("f.feed.target.raise.stalled.resume", {
            "one": "{item} top-up of {target:,} covers {n} hour of a {per:,}/day line; raise it to {set:,}; and none "
                   "arrived last week though {depot} holds {stock:,}; or resume the paused {item} import to {site}",
            "other": "{item} top-up of {target:,} covers {n} hours of a {per:,}/day line; raise it to {set:,}; and "
                     "none arrived last week though {depot} holds {stock:,}; or resume the paused {item} import to "
                     "{site}"}, **said)
    if raise_it and stalled:
        return msg("f.feed.target.raise.stalled", {
            "one": "{item} top-up of {target:,} covers {n} hour of a {per:,}/day line; raise it to {set:,}; and none "
                   "arrived last week though {depot} holds {stock:,}",
            "other": "{item} top-up of {target:,} covers {n} hours of a {per:,}/day line; raise it to {set:,}; and "
                     "none arrived last week though {depot} holds {stock:,}"}, **said)
    if raise_it and own:
        return msg("f.feed.target.raise.resume", {
            "one": "{item} top-up of {target:,} covers {n} hour of a {per:,}/day line; raise it to {set:,}; or "
                   "resume the paused {item} import to {site}",
            "other": "{item} top-up of {target:,} covers {n} hours of a {per:,}/day line; raise it to {set:,}; or "
                     "resume the paused {item} import to {site}"}, **said)
    if raise_it:
        return msg("f.feed.target.raise", {
            "one": "{item} top-up of {target:,} covers {n} hour of a {per:,}/day line; raise it to {set:,}",
            "other": "{item} top-up of {target:,} covers {n} hours of a {per:,}/day line; raise it to {set:,}"},
            **said)
    if stalled and own:
        return msg("f.feed.target.stalled.resume", {
            "one": "{item} top-up of {target:,} covers {n} hour of a {per:,}/day line; and none arrived last week "
                   "though {depot} holds {stock:,}; or resume the paused {item} import to {site}",
            "other": "{item} top-up of {target:,} covers {n} hours of a {per:,}/day line; and none arrived last week "
                     "though {depot} holds {stock:,}; or resume the paused {item} import to {site}"}, **said)
    if stalled:
        return msg("f.feed.target.stalled", {
            "one": "{item} top-up of {target:,} covers {n} hour of a {per:,}/day line; and none arrived last week "
                   "though {depot} holds {stock:,}",
            "other": "{item} top-up of {target:,} covers {n} hours of a {per:,}/day line; and none arrived last week "
                     "though {depot} holds {stock:,}"}, **said)
    if own:
        return msg("f.feed.target.resume", {
            "one": "{item} top-up of {target:,} covers {n} hour of a {per:,}/day line; or resume the paused {item} "
                   "import to {site}",
            "other": "{item} top-up of {target:,} covers {n} hours of a {per:,}/day line; or resume the paused {item} "
                     "import to {site}"}, **said)
    return msg("f.feed.target", {
        "one": "{item} top-up of {target:,} covers {n} hour of a {per:,}/day line",
        "other": "{item} top-up of {target:,} covers {n} hours of a {per:,}/day line"}, **said)


def _notrouted_text(one: bool, needs: bool, held: bool, said: dict):
    """_idle_notes()'s Not routed sentence: one site or several (`who`), that
    sell it or, with no shop among them, need it, and how long what they hold
    lasts where that is known. `said` holds site, stock, item, who, per and
    days."""
    if one and needs and held:
        return msg("f.notrouted.one.needs.held", "{site} holds {stock:,} {item} no plan sends on; {who} needs "
                   "{per:,}/day and holds {days}", **said)
    if one and needs:
        return msg("f.notrouted.one.needs", "{site} holds {stock:,} {item} no plan sends on; {who} needs {per:,}/day",
                   **said)
    if one and held:
        return msg("f.notrouted.one.sells.held", "{site} holds {stock:,} {item} no plan sends on; {who} sells "
                   "{per:,}/day and holds {days}", **said)
    if one:
        return msg("f.notrouted.one.sells", "{site} holds {stock:,} {item} no plan sends on; {who} sells {per:,}/day",
                   **said)
    if needs and held:
        return msg("f.notrouted.need.held", "{site} holds {stock:,} {item} no plan sends on; {who} need {per:,}/day "
                   "and hold {days}", **said)
    if needs:
        return msg("f.notrouted.need", "{site} holds {stock:,} {item} no plan sends on; {who} need {per:,}/day",
                   **said)
    if held:
        return msg("f.notrouted.sell.held", "{site} holds {stock:,} {item} no plan sends on; {who} sell {per:,}/day "
                   "and hold {days}", **said)
    return msg("f.notrouted.sell", "{site} holds {stock:,} {item} no plan sends on; {who} sell {per:,}/day", **said)


def _idle_notes(businesses: list, idle: list, silent: set, mode: str = "cap") -> list:
    """Stock standing still, said once per cause rather than once per shelf.

    Six shops holding a thousand cupcakes each is not six findings; it is one
    top-up target set too high (targetHigh), grouped by the target. Stock with
    nothing moving out stays one line per holding (notMoving), and so does
    stock a Smart Delivery level or a weekly order keeps too high (importHigh)
    or stock that is simply weeks of what leaves (overstock); all three are
    Idle stock. Stock no plan sends on while the company's own sites sell or
    need it is Not routed (notrouted), one finding that names those sites,
    whose own no-plan findings then give way to it. `idle` rows carry the
    sizing modes they hold in (`modes`) and what Demand sizing changes (`dem`).
    """
    rows = []
    for row in idle:
        if mode not in row.get("modes", ("cap",)):
            continue
        rows.append({**row, **row["dem"]} if mode == "dem" and row.get("dem") else row)
    live = [r for r in rows if businesses[r["s"]]["key"] not in silent]
    notes = []

    def worth_of(row):
        # Raw materials carry no retail price, so there is no honest dollar
        # figure to gate them by: the units are the finding.
        weeks = row["weeks"] if row["weeks"] else row["stock"] / max(row["perWeek"], 1)
        return row["value"] / max(1.0, weeks * 7) if row["price"] else None

    for row in live:
        why = row.get("why") or ("notMoving" if row["dead"] else None)
        if why in (None, "targetHigh"):
            continue
        name, key = businesses[row["s"]]["name"], businesses[row["s"]]["key"]
        ev = {"slug": row["slug"]}
        item = tok(row["slug"], row["item"])
        if why == "notRouted":
            unfed = row.get("unfed") or []
            sites = [businesses[s] for s, _per_day, _days in unfed]
            types = {b["type"] for b in sites}
            if len(sites) == 1:
                who = sites[0]["name"]
            elif len(types) == 1:
                # Several of one type: the count and the type's name, which a
                # translation writes its own way ("Geschenkladen × 3").
                who = msg("f.notrouted.type", {"one": "{n} {type}", "other": "{n} {type}"}, n=len(sites),
                          type=tok(sites[0].get("typeSlug"), _plural(types.pop()).lower()))
            else:
                who = msg("f.notrouted.sites", {"one": "{n} sites", "other": "{n} sites"}, n=len(sites))
            days = [u[2] for u in unfed if u[2] is not None]
            said = dict(site=name, stock=row["stock"], item=item, who=who,
                        per=sum(u[1] for u in unfed),
                        days=msg("f.notrouted.days", {"one": "~{n:,} day", "other": "~{n:,} days"},
                                 n=round(sum(days) / len(days))) if days else "")
            text = _notrouted_text(len(sites) == 1, all(b["status"] != "retail" for b in sites), bool(days), said)
            notes.append(_finding(
                "warn", name, "notrouted", text,
                key=key, rank=-row["stock"], subject=row["item"], named=item, ev=ev,
                amt=_amt(said["per"], "/day")))
        elif why == "notMoving":
            # Brought here by a top-up target, with no shelf, onward route or
            # line here to use it: most likely a target set on the wrong route.
            # The stock may be meant for sites no plan reaches yet, so the
            # finding offers both ways out.
            text = (
                msg("f.dead.route", "{stock:,} {item} held with nothing moving out; {src} tops it up to {target:,} "
                    "here and no plan sends it on: add a plan to the shops that should get it, or stop the top-up",
                    stock=row["stock"], item=item, target=row["target"], src=businesses[row["routedFrom"]]["name"])
                if row.get("routedFrom") is not None else
                msg("f.dead", "{stock:,} {item} held with nothing moving out", stock=row["stock"], item=item)
            )
            notes.append(_finding(
                "info", name, "dead", text,
                key=key, rank=-row["stock"], subject=row["item"], named=item, worth=worth_of(row), ev=ev))
        elif why == "importHigh":
            # Idle stock is IDLE_WEEKS or more of what draws on it, so neither
            # count of weeks is ever one.
            said = dict(stock=row["stock"], item=item, weeks=row["weeks"], level=row.get("importLevel") or 0,
                        of=(row.get("importLevel") or 0) / max(row["perWeek"], 1))
            text = (
                msg("f.dead.import.smart", "{stock:,} {item} is {weeks:.0f} weeks of what it feeds; Smart Delivery "
                    "keeps {level:,} in stock, {of:.0f} weeks of it, so lower the import", **said)
                if row.get("smart") else
                msg("f.dead.import", "{stock:,} {item} is {weeks:.0f} weeks of what it feeds; the import brings "
                    "{level:,} a week, {of:.0f} weeks of it, so lower the import", **said)
            )
            notes.append(_finding(
                "info", name, "dead", text,
                key=key, rank=-row["stock"], subject=row["item"], named=item, worth=worth_of(row), ev=ev,
                amt=_amt(_shown(row["weeks"]), "weeks")))
        else:
            notes.append(_finding(
                "info", name, "dead",
                msg("f.dead.weeks", "{stock:,} {item} is {weeks:.0f} weeks of what leaves",
                    stock=row["stock"], item=item, weeks=row["weeks"]),
                key=key, rank=-row["stock"], subject=row["item"], named=item, worth=worth_of(row), ev=ev,
                amt=_amt(_shown(row["weeks"]), "weeks")))

    # A top-up target set too high groups by the target behind it: the same
    # number in the same plan, repeated across shops, is one setting to change.
    by_target = collections.OrderedDict()
    for row in live:
        why = row.get("why") or ("notMoving" if row["dead"] else None)
        if why in (None, "targetHigh"):
            by_target.setdefault(row["target"] or 0, []).append(row)
    for target, rows in by_target.items():
        items = sorted({r["item"] for r in rows})
        slug_of = {r["item"]: r["slug"] for r in rows}
        shown = _msg_list([tok(slug_of[i], i) for i in items])
        sites = len({r["s"] for r in rows})
        daily = sum(r["perWeek"] for r in rows) / 7 / len(rows)
        stock = sum(r["stock"] for r in rows)
        # Value the excess at what it sells for, spread over how long it takes to
        # sell — a rate, so it can be read against a day's profit.
        worth = sum(
            r["value"] / max(1.0, r["weeks"] * 7) for r in rows if r["price"]
        ) or None
        if target and daily:
            amt = _amt(_shown(target / daily), "daily sales", sign="x")
            text = msg("f.target", {
                "one": "{items} top-up target of {target:,} is {x:.0f}x daily sales in {n} shop; lower the target",
                "other": "{items} top-up target of {target:,} is {x:.0f}x daily sales in {n} shops; lower the target",
            }, items=shown, target=target, x=target / daily, n=sites)
        else:
            # Idle stock is IDLE_WEEKS or more of what draws on it: never one week.
            text = msg("f.target.units", {
                "one": "{units:,} units of {items} across {n} site is {weeks:.0f} weeks of supply",
                "other": "{units:,} units of {items} across {n} sites is {weeks:.0f} weeks of supply",
            }, units=stock, items=shown, n=sites, weeks=stock / max(sum(r["perWeek"] for r in rows), 1))
            amt = _amt(stock, "units")
        one = businesses[rows[0]["s"]] if sites == 1 else None
        site = one["name"] if one else msg("f.target.site", {"one": "{n} shop", "other": "{n} shops"}, n=sites)
        notes.append(
            _finding(
                "info", site, "target", text,
                key=one["key"] if one else None, rank=-stock, subject=items[0],
                named=tok(slug_of[items[0]], items[0]), worth=worth, amt=amt,
                # One target set too high can span several shops; the panel can
                # only point at a row when a single site owns the finding, and
                # the row it points at is the one the sentence names. Across
                # several shops Supply still lands on a row: the named item's
                # biggest holding (`s`, the shop's index).
                ev={"slug": next(r["slug"] for r in rows if r["item"] == items[0])}
                if one else {"slug": slug_of[items[0]], "s": max(
                    (r for r in rows if r["item"] == items[0]), key=lambda r: (r["stock"], -r["s"]))["s"]},
            )
        )
    return notes


# How a pile of same-shaped findings at one site reads as a single line: n
# findings, and the one named first. A line stands for CONDENSE_AT or more, so
# the "one" forms are there for a translation's plural rules, not the English.
# Registry: "A finding kind" (only if: see the checklist).
SUMMARIES = {
    "shortfall": lambda n, subject: msg("f.sum.shortfall", {
        "one": "{n} item runs dry before its next delivery; soonest {subject}",
        "other": "{n} items run dry before their next delivery; soonest {subject}"}, n=n, subject=subject),
    "order": lambda n, subject: msg("f.sum.order", {
        "one": "{n} weekly order cannot cover its own week; worst {subject}",
        "other": "{n} weekly orders cannot cover their own week; worst {subject}"}, n=n, subject=subject),
    "paused": lambda n, subject: msg("f.sum.paused", {
        "one": "{n} import is paused; soonest to run out is {subject}",
        "other": "{n} imports are paused; soonest to run out is {subject}"}, n=n, subject=subject),
    "outruns": lambda n, subject: msg("f.sum.outruns", {
        "one": "{n} product outsells its daily top-up; worst {subject}",
        "other": "{n} products outsell their daily top-up; worst {subject}"}, n=n, subject=subject),
    "topup": lambda n, subject: msg("f.sum.topup", {
        "one": "{n} product outruns the depot's daily top-up; worst {subject}",
        "other": "{n} products outrun the depot's daily top-up; worst {subject}"}, n=n, subject=subject),
    "wholesale": lambda n, subject: msg("f.sum.wholesale", {
        "one": "{n} product's wholesale deliveries fall short or arrive too late; worst {subject}",
        "other": "{n} products' wholesale deliveries fall short or arrive too late; worst {subject}"},
        n=n, subject=subject),
    "unsourced": lambda n, subject: msg("f.sum.unsourced", {
        "one": "{n} product nothing upstream supplies; largest {subject}",
        "other": "{n} products nothing upstream supplies; largest {subject}"}, n=n, subject=subject),
    "unplanned": lambda n, subject: msg("f.sum.unplanned", {
        "one": "{n} stocked product is on no distribution plan; largest {subject}",
        "other": "{n} stocked products are on no distribution plan; largest {subject}"}, n=n, subject=subject),
    "dead": lambda n, subject: msg("f.sum.dead", {
        "one": "{n} product sits idle; largest {subject}",
        "other": "{n} products sit idle; largest {subject}"}, n=n, subject=subject),
    "notrouted": lambda n, subject: msg("f.sum.notrouted", {
        "one": "{n} product is held where no plan sends it on; largest {subject}",
        "other": "{n} products are held where no plan sends them on; largest {subject}"}, n=n, subject=subject),
    "feed": lambda n, subject: msg("f.sum.feed", {
        "one": "{n} factory input is not fed as the machines need; largest {subject}",
        "other": "{n} factory inputs are not fed as the machines need; largest {subject}"}, n=n, subject=subject),
    "staff": lambda n, subject: msg("f.sum.staff", {
        "one": "{n} factory machine is not staffed round the clock; worst {subject}",
        "other": "{n} factory machines are not staffed round the clock; worst {subject}"}, n=n, subject=subject),
    "unnamed": lambda n, subject: msg("f.sum.unnamed", {
        "one": "{n} factory machine runs a recipe the board cannot name; {subject} the largest",
        "other": "{n} factory machines run recipes the board cannot name; {subject} the largest"},
        n=n, subject=subject),
    "unset": lambda n, subject: msg("f.sum.unset", {
        "one": "{n} factory machine has no recipe set; {subject} the largest",
        "other": "{n} factory machines have no recipe set; {subject} the largest"}, n=n, subject=subject),
    "target": lambda n, subject: msg("f.sum.target", {
        "one": "{n} top-up target is set far above what sells; {subject} the deepest",
        "other": "{n} top-up targets are set far above what sells; {subject} the deepest"}, n=n, subject=subject),
}
CONDENSE_AT = 3  # three or more of a kind at one site becomes one line
# Registry: "A finding kind" (only if: see the checklist).
WORST_FIRST = {"wholesale"}  # condensed by severity first, then rank


def _condense(found: list, gate: float) -> dict:
    # One site is one key; a synthetic site ("3 shops") has none and is its name.
    buckets = collections.OrderedDict()
    for item in found:
        buckets.setdefault((item["siteKey"] or item["site"], item["group"]), []).append(item)

    out = []
    for (where, group), rows in buckets.items():
        if len(rows) < CONDENSE_AT or group not in SUMMARIES:
            out.extend(rows)
            continue
        # A kind whose rows mix severities reads out its worst severity first,
        # the rank breaking ties within it.
        if group in WORST_FIRST:
            rows.sort(key=lambda r: ({"critical": 0, "warn": 1, "info": 2}.get(r["level"], 3), r["rank"]))
        else:
            rows.sort(key=lambda r: r["rank"])
        worst = rows[0]
        worths = [r["worth"] for r in rows if r["worth"] is not None]
        out.append(
            {
                "level": worst["level"],
                "site": worst["site"],
                "siteKey": worst["siteKey"],
                "group": group,
                "text": SUMMARIES[group](len(rows), worst.get("named", worst["subject"])),
                "detail": worst["text"],
                "worth": sum(worths) if worths else None,
                "unit": ALERT_UNITS.get(group, ""),
                # How many findings the line stands for, where it has no money.
                "amt": _amt(len(rows), "orders" if group == "order" else "findings"),
                # The subject is dropped here, so the merged row is keyed on
                # where it is alone.
                "id": _alert_id("summary", group, where),
                "always": any(r["always"] for r in rows),
                # A merged line reads out the worst of its rows, so it points
                # at that row's evidence.
                **({"ev": worst["ev"]} if worst.get("ev") else {}),
            }
        )

    order = {"critical": 0, "warn": 1, "info": 2}
    lines, minor = [], []
    for row in out:
        for key in ("rank", "subject", "named"):
            row.pop(key, None)
        small = (
            not row["always"]
            and row["worth"] is not None
            and abs(row["worth"]) < gate
        )
        row.pop("always")
        if row["worth"] is not None:
            row["worth"] = money(row["worth"])
        (minor if small else lines).append(row)

    lines.sort(key=lambda a: order[a["level"]])
    minor.sort(key=lambda a: -(a["worth"] or 0))
    return {
        "lines": lines,
        "minor": {
            "count": len(minor),
            "gate": round(gate, 2),
            "worth": money(sum(m["worth"] or 0 for m in minor)),
            "rows": minor,
        },
    }


# ------------------------------------------------------------------- render

# Where the payload waits while render() fills the other placeholders: a NUL
# pair, which no asset carries and json.dumps() always escapes.
DATA_SLOT = "\x00__DATA__\x00"


def script_json(text: str) -> str:
    """JSON text made safe to sit inside a <script> element.

    Every "<" becomes \\u003c, the same character to the JSON (a "<" only
    ever stands inside a string there), so no saved name can close the script
    ("</script>") or open a comment that swallows its end ("<!--<script").
    """
    return text.replace("<", "\\u003c")


def render(
    data: dict | None,
    live: bool = False,
    *,
    banner: str = "",
    before_script: str = "",
    head: str = "",
    map_external: bool = False,
    site: bool = False,
    names: dict | None = None,
    ui: dict | None = None,
) -> str:
    """The page. With live=True it asks its data source for fresh numbers.

    ``data`` may be None for a page that receives its numbers later, as the
    in-browser board does. ``banner`` is markup placed above the board,
    ``before_script`` goes just ahead of the board's own script, which is where
    a host page defines ``window.LEDGER_SOURCE``, and ``head`` is extra markup
    for the document head (a viewport tag, an analytics beacon).

    The doctype comes first so the page runs in standards mode: without it the
    viewport height reads as the document's, tables do not inherit line-height
    and the tooltip layer has to guess where the window ends.

    A save name is the player's own text, so it is escaped on the way into the
    title, and every ``<`` is escaped inside the JSON (script_json()) so a name
    can never close the script tag it sits in.

    ``names`` is ``{"lang": code, "names": table}``, a name_table() the page
    lays over the payload's names (``--lang``); None keeps them English.
    ``ui`` is ``{"lang": code, "table": table}``, Big Copilot's own text in
    that language (web/i18n/<code>.json, ``--lang``); None keeps it English.
    """
    names_json = "null" if not names else script_json(json.dumps(names, ensure_ascii=False, separators=(",", ":")))
    ui_json = "null" if not ui else script_json(json.dumps(ui, ensure_ascii=False, separators=(",", ":")))
    if data is None:
        payload, title = "null", "Big Copilot"
    else:
        payload = script_json(json.dumps(data, separators=(",", ":")))
        title = f"{data['meta']['save']} · Big Copilot"
    # UI source stays shared between the local HTML and browser build. Static
    # exports embed geography so opening a file needs no local server or fetch.
    asset_root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "web")
    with open(os.path.join(asset_root, "changelog.json"), encoding="utf-8") as fh:
        changes = json.load(fh)
    changelog = "".join(
        '<li class="changelog-entry"><div class="changelog-meta">'
        f'<time datetime="{html_escape(entry["date"])}">'
        f'{dt.date.fromisoformat(entry["date"]).strftime("%d %b %Y")}</time>'
        f'<a href="https://github.com/PeterHartwieg/big-copilot/pull/{int(entry["pr"])}" '
        f'target="_blank" rel="noopener" aria-label="View pull request {int(entry["pr"])}">'
        f'PR #{int(entry["pr"])} ↗</a></div>'
        f'<h3>{html_escape(entry["title"])}</h3><p>{html_escape(entry["summary"])}</p></li>'
        for entry in sorted(changes, key=lambda entry: (entry["date"], entry["pr"]), reverse=True)
    )
    with open(os.path.join(asset_root, "map.js"), encoding="utf-8") as fh:
        map_script = fh.read()
    with open(os.path.join(asset_root, "map.css"), encoding="utf-8") as fh:
        map_css = fh.read()

    # The wiki travels the same way as the map: one source, shared by the local
    # HTML and the browser build. A checkout without the two files still renders
    # a whole board — the Wiki page then says so instead of throwing, and the
    # tab is left out of the top navigation.
    def optional_asset(name: str) -> str:
        try:
            with open(os.path.join(asset_root, name), encoding="utf-8") as fh:
                return fh.read()
        except OSError:
            return ""

    wiki_script = optional_asset("wiki.js")
    wiki_css = optional_asset("wiki.css")
    # Big Copilot's own text in another language (docs/architecture.md, "UI
    # text"): tt() and the table loader, at the end of the head (after the
    # stylesheets), ahead of every script that may call it, with the table a --lang page carries. It is spliced
    # last, and only at the first marker (the head's), so no other
    # placeholder's .replace() runs over the table, and a marker inside the
    # payload is left alone.
    with open(os.path.join(asset_root, "i18n.js"), encoding="utf-8") as fh:
        # The site's page also remembers the footer's Language (TT_SITE); a
        # local page's language is its --lang.
        i18n_script = (fh.read().replace("/*__TT_SITE__*/false", "true" if site else "false", 1)
                       .replace("/*__UI_TABLE__*/null", ui_json))
    map_payload = ""
    if data is not None and not live and not map_external:
        import base64
        with open(os.path.join(asset_root, "maps", "locations.json"), encoding="utf-8") as fh:
            locations = json.load(fh)
        with open(os.path.join(asset_root, "maps", locations["image"]), "rb") as fh:
            image = "data:image/svg+xml;base64," + base64.b64encode(fh.read()).decode("ascii")
        embedded = {"data": locations, "image": image}
        # The finder's floor plans travel with the map in a page opened from a
        # file; without them the finder simply shows no plan.
        try:
            with open(os.path.join(asset_root, "maps", "floor-plans.json"), encoding="utf-8") as fh:
                embedded["plans"] = json.load(fh)
        except (OSError, ValueError):
            pass
        map_payload = "window.BIG_COPILOT_MAP=" + script_json(json.dumps(embedded, separators=(",", ":"))) + ";"
    # A page that is saved and opened from a file has nowhere to fetch the help
    # from, so an export carries it. The hosted build fetches it instead, with
    # the build stamp on it, and would only be made heavier by a copy. The wiki
    # needs no save, so this travels even in an export that has no numbers.
    wiki_payload = ""
    if wiki_script and not live:
        catalogue = optional_asset("wiki-data.json")
        if catalogue:
            wiki_payload = ("window.BIG_COPILOT_WIKI="
                            + script_json(catalogue.strip()) + ";")
    # The <html> start tag is optional and the page never closed one, so this
    # only names the language of the element the parser makes anyway.
    return "<!doctype html>" + chr(10) + '<html lang="en">' + chr(10) + '<meta charset="utf-8">' + chr(10) + head + (
        # The payload goes in last, through DATA_SLOT, so no placeholder's
        # .replace() below runs over the save's own text.
        load_template().replace("/*__DATA__*/null", DATA_SLOT)
        .replace("/*__MAP_CSS__*/", map_css)
        .replace("/*__MAP_SCRIPT__*/", map_script)
        .replace("/*__MAP_PAYLOAD__*/", map_payload)
        .replace("/*__WIKI_CSS__*/", wiki_css)
        .replace("/*__WIKI_SCRIPT__*/", wiki_script)
        .replace("/*__WIKI_PAYLOAD__*/", wiki_payload)
        # One table of neighbourhood tags, written once here, so a wiki address
        # wears the same two letters a business does.
        .replace("/*__HOOD_TAGS__*/{}", json.dumps(HOOD_TAG, separators=(",", ":")))
        # And their English names by the same keys, for a board without game text.
        .replace("/*__HOOD_NAMES__*/{}", json.dumps(HOOD_LABEL, separators=(",", ":")))
        # The game names in another language, for a local page built with --lang.
        .replace("/*__NAMES__*/null", names_json)
        .replace("<!--__CHANGELOG__-->", changelog)
        .replace("/*__LIVE__*/false", "true" if live else "false")
        .replace("__TITLE__", html_escape(title))
        .replace("<!--__FOOTER__-->", footer_html(site=site))
        .replace("<!--__BANNER__-->", banner)
        .replace("<!--__BEFORE_SCRIPT__-->", before_script)
        .replace("/*__I18N_SCRIPT__*/", i18n_script, 1)
        .replace(DATA_SLOT, payload, 1)
    )


# The board's HTML and CSS (template/board.html) and its script
# (template/board.js), beside this file. They are read on the first render(),
# never at import: the Pyodide worker imports this module with only its
# fetched files on disk and never renders.
_template = None
# Where the board script stands in board.html: a line of its own, the whole
# body of the page's last <script> block (tools/split_board_script.py).
BOARD_SCRIPT_SLOT = "/*__BOARD_SCRIPT__*/\n"


def splice_board_script(page: str, script: str) -> str:
    """board.html with board.js in its slot: the page as one string again."""
    if page.count(BOARD_SCRIPT_SLOT) != 1:
        raise ValueError("template/board.html must carry %r once" % BOARD_SCRIPT_SLOT.strip())
    return page.replace(BOARD_SCRIPT_SLOT, script, 1)


def load_template() -> str:
    """template/board.html with template/board.js spliced in, as one string,
    read once, with LF line endings. The splice comes before every other
    placeholder, so render() sees the page as if it were one file."""
    global _template
    if _template is None:
        folder = os.path.join(os.path.dirname(os.path.abspath(__file__)), "template")
        with open(os.path.join(folder, "board.html"), encoding="utf-8") as fh:
            page = fh.read()
        with open(os.path.join(folder, "board.js"), encoding="utf-8") as fh:
            script = fh.read()
        _template = splice_board_script(page, script)
    return _template


# ------------------------------------------------------- cli and watch server
def newest_under(target: str) -> str:
    """The most recently written save at or below `target`."""
    if os.path.isfile(target):
        return target
    folders = [target] + [
        os.path.join(target, n)
        for n in os.listdir(target)
        if os.path.isdir(os.path.join(target, n))
    ]
    saves = [
        os.path.join(f, n)
        for f in folders
        for n in os.listdir(f)
        if n.endswith(".hsg")
    ]
    if not saves:
        raise SystemExit(f"no .hsg saves under {target}")
    return max(saves, key=os.path.getmtime)


def read_save_meta(path: str) -> dict:
    """The game's sidecar for a save: `<name>.hsg.meta`, a small JSON file.

    It names the character and the game day without opening the save itself.
    Missing or unreadable (very old saves have a different shape) gives {}.
    """
    try:
        with open(path + ".meta", encoding="utf-8") as fh:
            meta = json.load(fh)
    except (OSError, ValueError):
        return {}
    who = meta.get("characterData") or meta.get("playerCustomizationData") or {}
    return {
        "character": (who.get("name") or "").strip(),
        "day": meta.get("day"),
        "autosave": bool(meta.get("isRecoverSave")),
    }


def catalogue(root: str) -> list[dict]:
    """Every save under `root`, grouped by character folder, newest first.

    Each entry: folder (the character id the game generated), character (its
    name, from the sidecars, else from a "New <name> Save Game" file, else the
    folder), and saves: [{path, name, day, autosave, mtime}] newest first.
    Groups are ordered by their newest save, so the ones being played lead.
    """
    if os.path.isfile(root):
        root = os.path.dirname(root) or "."  # a bare filename has no dirname
    folders = [root] + sorted(
        os.path.join(root, n)
        for n in os.listdir(root)
        if os.path.isdir(os.path.join(root, n))
    )
    groups = []
    for folder in folders:
        saves = []
        for n in os.listdir(folder):
            if not n.lower().endswith(".hsg"):
                continue
            path = os.path.join(folder, n)
            meta = read_save_meta(path)
            saves.append(
                {
                    "path": path,
                    "name": n[:-4],
                    "day": meta.get("day"),
                    "autosave": meta.get("autosave", n.lower().startswith("recover")),
                    "character": meta.get("character", ""),
                    "mtime": os.path.getmtime(path),
                }
            )
        if not saves:
            continue
        saves.sort(key=lambda s: -s["mtime"])
        character = next((s["character"] for s in saves if s["character"]), "")
        if not character:
            for s in saves:
                m = re.match(r"New (.+?) Save Game", s["name"])
                if m:
                    character = m.group(1).strip()
                    break
        groups.append(
            {
                "folder": folder,
                "character": character or os.path.basename(folder),
                "saves": saves,
            }
        )
    groups.sort(key=lambda g: -g["saves"][0]["mtime"])
    return groups


def print_catalogue(groups: list[dict]) -> None:
    for g in groups:
        print(f"{g['character']}  ({os.path.basename(g['folder'])})")
        for s in g["saves"]:
            when = dt.datetime.fromtimestamp(s["mtime"]).strftime("%d %b %H:%M")
            day = f"day {s['day']:>4}" if s["day"] is not None else "day    ?"
            kind = "autosave" if s["autosave"] else "saved   "
            print(f"    {when}  {day}  {kind}  {s['name']}")
    print()
    print('Pass a character or save name to open it: python ba_dashboard.py "Costy Co"')


def default_root(lead: str = "") -> str:
    """SAVE_ROOT, or a SystemExit saying there is no folder to look in.

    Only the Windows location is found on its own: elsewhere USERPROFILE is
    unset, so SAVE_ROOT is a bare relative string rather than a place anyone
    could look, and naming it would send the reader after a folder that was
    never there. `lead` is what already went wrong, so the two ways on are
    spelled out once.
    """
    if os.path.isdir(SAVE_ROOT):
        return SAVE_ROOT
    missing = (
        f"no save folder at {SAVE_ROOT}"
        if os.path.isabs(SAVE_ROOT)
        else "no save folder to look in: only the Windows one is found on its own"
    )
    raise SystemExit(
        # ASCII only: a piped log under cp850 would show an em dash as an escape.
        f"{lead}there is {missing}. Pass the save folder or a .hsg file as the "
        "argument (the README has the Windows and macOS paths), or use "
        "bigcopilot.com, which reads saves in the browser."
    )


def resolve_target(arg: str | None) -> str:
    """Turn the positional argument into a file or folder to read.

    A path that exists is taken as is. Anything else is a name: a save
    (`Costy Co`, `Costy Co.hsg`) or a character; an exact match wins, then a
    case-insensitive substring. A save name gives that file; a character name
    gives its folder, so --watch follows the character's autosaves. Several
    matches are listed and the run stops, so a guess never opens the wrong city.
    """
    if not arg:
        return default_root()
    if os.path.exists(arg):
        return arg
    root = default_root(f"{arg} does not exist, and ")  # a name needs the folder
    want = arg.lower().removesuffix(".hsg")
    groups = catalogue(root)
    saves = [(g, s) for g in groups for s in g["saves"]]
    # Four tiers, each tried on its own: a save named exactly so, a character
    # named exactly so, then the same two as substrings. "Costy Co" is both a
    # save and a character here; the save wins, and "Costy" finds the character.
    tiers = [
        [(f"{g['character']} - {s['name']}", s["path"]) for g, s in saves if s["name"].lower() == want],
        [(g["character"], g["folder"]) for g in groups if g["character"].lower() == want],
        [(g["character"], g["folder"]) for g in groups if want in g["character"].lower()],
        [(f"{g['character']} - {s['name']}", s["path"]) for g, s in saves if want in s["name"].lower()],
    ]
    for hits in tiers:
        if len(hits) == 1:
            return hits[0][1]
        if hits:
            print(f"{arg!r} matches more than one save or character:")
            for label, path in hits:
                print(f"  {label:<40} {path}")
            raise SystemExit("be more specific, or pass the path")
    print(f"nothing named {arg!r} under {root}. The saves there:\n")
    print_catalogue(groups)
    raise SystemExit(1)


class SaveShapeError(Exception):
    """The save parsed, but a field the board relies on was not where expected."""


def safe_extract(save: Save, names: Names, history_path: str | None) -> dict:
    """extract(), with a game-patch failure turned into one readable sentence.

    The format is reverse-engineered, so a renamed field surfaces as a KeyError
    deep inside a helper. Nobody can act on that; the game build and the build
    this tool was checked against are what a report needs.
    """
    build = save.root.get("buildNumberAtLastSave")
    if build is not None and build < MIN_BUILD:
        raise SaveShapeError(
            f"this save is from game build {build}; the board understands saves "
            f"from build {MIN_BUILD} onward. Load the game and save again to bring it "
            "up to date"
        )
    try:
        return extract(save, names, history_path)
    except (KeyError, TypeError, AttributeError, IndexError, ValueError) as exc:
        newer = build is not None and build > VERIFIED_BUILD
        raise SaveShapeError(
            "the save does not have the shape this board expects "
            f"({type(exc).__name__}: {exc}{_raised_at(exc)}). Game build {build}, board checked on "
            f"build {VERIFIED_BUILD}"
            + (": the game has probably changed its save format" if newer else "")
        ) from exc
    except Exception as exc:  # a bug of the board's own: say where, so a screenshot finds it
        raise SaveShapeError(
            f"the board hit a bug reading this save ({type(exc).__name__}: {exc}{_raised_at(exc)}). "
            f"Game build {build}"
        ) from exc


def _raised_at(exc: BaseException) -> str:
    """", in fn, line N": the innermost frame of the board's own code (this file
    or ba_save.py) that ``exc`` passed through; web/py/ holds the same files,
    so the line is the source's at that release."""
    where = ""
    tb = exc.__traceback__
    while tb is not None:
        code = tb.tb_frame.f_code
        if os.path.basename(code.co_filename) in ("ba_dashboard.py", "ba_save.py"):
            where = f", in {code.co_name}, {os.path.basename(code.co_filename)} line {tb.tb_lineno}"
        tb = tb.tb_next
    return where


def browser_build(
    save_path: str, locale_path: str, history_path: str, names_path: str | None = None
) -> str:
    """One rebuild for the in-browser board: parse, extract, JSON.

    Everything arrives as a path on Pyodide's virtual filesystem, so the same
    extract() runs unchanged; only this wrapper knows it is in a browser. The
    character id is kept beside the history so a later browser_name() can
    file the name under the right company without parsing the save again.

    ``names_path`` is the table of display names shipped with the page; the
    player's own en.json, when given, is laid over it and adds the help pages
    that recipes and station capacities are read from. A file in another
    language is left out: web/app.js refuses one before keeping it, so this
    only meets one kept before that check, and the shipped names beat
    translated ones with every recipe and capacity missing.
    """
    locale = dict(load_locale(names_path)) if names_path else {}
    own = load_locale(locale_path)
    if english_text(own):
        locale.update(own)
    names = Names(locale)
    try:
        save = load_save(save_path)
    except Exception as exc:  # gzip, struct and format errors alike
        raise SaveShapeError(
            f"{os.path.basename(save_path)} is not a Big Ambitions save this board can "
            f"read ({type(exc).__name__}: {exc})"
        ) from exc
    data = safe_extract(save, names, history_path)
    character = save.root.get("characterId") or "default"
    # The page keeps this file in localStorage, a few MB for the whole site:
    # sixty days of demand for every character ever opened would fill it.
    # No file here means extract() did not write one (it set a damaged one
    # aside), and this run writes nothing either.
    if os.path.exists(history_path):
        history = History(history_path)
        history.keep_recent(character, BROWSER_HISTORY_DAYS, BROWSER_HISTORY_CHARACTERS, save.root.get("Day"))
        history.write()
    with open(history_path + ".character", "w", encoding="utf-8") as fh:
        fh.write(character)
    return json.dumps(data, separators=(",", ":"))


def browser_name(history_path: str, rid: str, slug: str | None) -> None:
    """A factory line the player named in the browser; the next build follows."""
    try:
        with open(history_path + ".character", encoding="utf-8") as fh:
            character = fh.read().strip() or "default"
    except OSError:
        character = "default"
    history = History(history_path)
    history.named(character, {rid: slug})
    history.write()


BELOW_NORMAL_PRIORITY_CLASS = 0x00004000


def backfill_history(target: str, history_path: str, names: Names) -> int:
    """Seed demand history from the other saves of the same character.

    Older saves are real snapshots of the same city, so the trend line starts
    populated instead of waiting a week for its first comparison. Only the folder
    holding the newest save is read: every other folder is a different character,
    and a different city.
    """
    folder = os.path.dirname(newest_under(target)) or "."  # a bare filename has none
    saves = sorted(
        os.path.join(folder, n) for n in os.listdir(folder) if n.endswith(".hsg")
    )
    print(f"Seeding demand history from {len(saves)} saves in {os.path.basename(folder)}")
    recorded = 0
    for path in saves:
        try:
            save = load_save(path)
            extract(save, names, history_path)
            print(f"  day {save.root['Day']:>4}  {os.path.basename(path)}", flush=True)
            recorded += 1
        except Exception as exc:
            print(f"  skipped {os.path.basename(path)}: {exc}", flush=True)
    return recorded


def yield_to_the_game() -> bool:
    """Drop below normal priority so the game always gets the core first."""
    try:
        if sys.platform != "win32":
            os.nice(10)
            return True
        import ctypes

        kernel32 = ctypes.windll.kernel32
        kernel32.SetPriorityClass.argtypes = [ctypes.c_void_p, ctypes.c_uint32]
        kernel32.SetPriorityClass.restype = ctypes.c_int
        # -1 is the pseudo-handle for the current process. It has to be passed
        # as a real pointer-width value or the call fails with a bad handle.
        current_process = ctypes.c_void_p(-1)
        return bool(
            kernel32.SetPriorityClass(current_process, BELOW_NORMAL_PRIORITY_CLASS)
        )
    except Exception:  # priority is a nicety, never a reason to fail
        return False


class LinkUnavailable(Exception):
    """The game link did not answer: the game is closed or between cities."""


class LinkMismatch(LinkUnavailable):
    """The mod answered, but speaks a schema version this board does not know.

    An outage like any other to the watch loop (docs/game-link-api.md, the
    clients' loop, step 5): said once under the board it keeps, and over the
    moment a health answer of this version arrives. A one-shot run stops on it.
    """


def loopback_link(url: str) -> str:
    """The mod's address with localhost and [::1] spelt 127.0.0.1.

    The mod listens on http://127.0.0.1:<port>/ only, and its listener turns
    away any other Host, so the other two names for this machine would read as
    a game that is not there. Any other address is left as given.
    """
    try:
        parts = urllib.parse.urlsplit(url)
        port = parts.port
    except ValueError:  # a port that is no number: urllib says so on the call
        return url
    if parts.hostname not in ("localhost", "::1"):
        return url
    host = f"127.0.0.1:{port}" if port else "127.0.0.1"
    return urllib.parse.urlunsplit((parts.scheme, host, parts.path, parts.query, parts.fragment))


class GameLink:
    """The running game's save, served by the Big Copilot Link mod.

    docs/game-link-api.md is the contract; this is the watcher's client of it.
    urllib only, with 5-second timeouts: the link shares the machine with the
    game, so a stalled call must never hold the watch loop. poll() downloads
    a save only when /health shows a stamp this board has not built from, so
    an idle game costs nothing.

    LinkUnavailable is a normal answer, not a crash: the listener lives only
    while a city is loaded, so the watch loop reports it once and carries on.
    """

    SCHEMA = 1  # the schema version this client speaks; see the contract
    TIMEOUT = 5

    def __init__(self, url: str, out_dir: str):
        # --game takes a URL and nothing else; argparse would otherwise hand a
        # save name typed after the flag to urllib, which raises ValueError.
        if not re.match(r"^https?://", url or ""):
            raise SystemExit(
                f"--game takes the mod's address (default http://127.0.0.1:8322), "
                f"not {url!r}; a save or character name does not combine with it"
            )
        self.url = loopback_link(url.rstrip("/"))
        # No proxy, whatever HTTP_PROXY says: urllib would send even
        # 127.0.0.1 through one, which fails, or hands a local intercepting
        # proxy the player's whole save.
        self._opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
        self.path = os.path.join(out_dir, "game-link.hsg")
        self.stamp = ""  # the stamp of the bytes last downloaded
        self.character = ""
        self.company = ""
        self.stale = False  # why wait_for_save() returned older bytes than it asked for, or False
        self.not_ready = 0  # /health answers in a row that were no health object (any status)

    def _call(self, route: str, method: str = "GET", headers: dict | None = None):
        try:
            # Request() is what raises ValueError for an address urllib cannot
            # use, so it belongs inside the try with the call.
            req = urllib.request.Request(
                self.url + route, method=method, headers=headers or {}
            )
            with self._opener.open(req, timeout=self.TIMEOUT) as res:
                return res.status, dict(res.headers), res.read()
        except urllib.error.HTTPError as err:
            return err.code, dict(err.headers), err.read()
        except (urllib.error.URLError, OSError, http.client.HTTPException, ValueError) as exc:
            raise LinkUnavailable(
                "the game link did not answer; start the game with the Big Copilot "
                "Link mod enabled and load a save"
            ) from exc

    def poll(self) -> str | None:
        """The path of a freshly downloaded game-link.hsg, else None.

        Keeps the last stamp it built from and sends it as If-None-Match, so
        a game that has moved on costs one /health and nothing more.
        Raises LinkUnavailable while the game is not there, and its
        LinkMismatch while the mod speaks a schema version this board does not
        know: the next poll asks again, so a mod put right is read as ever.
        """
        status, _, body = self._call("/health")
        health = None
        if status == 200 and body:
            try:
                health = json.loads(body)
            except ValueError:
                health = None
        if not isinstance(health, dict) or health.get("schemaVersion") is None:
            # Answered, but not with health: a status other than 200 (the mod is
            # there and not ready), or a 200 that is no health object, or one
            # with no version in it (something else on that port for a moment).
            # The next poll asks again; only a health object with a version says
            # what it speaks. Ten in a row is an outage, said once by the watch
            # loop and raised on every poll until a health answer, so it never
            # looks over between two polls, and one stray answer never stops
            # the watcher for good.
            self.not_ready += 1
            if self.not_ready >= 10:
                raise LinkUnavailable(
                    f"{self.url} answers, but not as the Big Copilot Link mod; "
                    "is another program on that port?"
                )
            return None
        self.not_ready = 0
        version = health.get("schemaVersion")
        if version != self.SCHEMA:
            raise LinkMismatch(
                f"the Big Copilot Link mod speaks schema version {version}; this "
                f"board needs version {self.SCHEMA}. Update the mod or the board"
            )
        stamp = health.get("stamp") or ""
        if not stamp or stamp == self.stamp or health.get("busy"):
            return None
        headers = {"If-None-Match": f'"{self.stamp}"'} if self.stamp else {}
        status, res_headers, data = self._call("/save", headers=headers)
        if status != 200:  # 503 no_save_yet, or a race the next poll settles
            return None
        with open(self.path, "wb") as fh:
            fh.write(data)
        self.stamp = res_headers.get("X-Game-Link-Stamp") or stamp
        self.character = res_headers.get("X-Game-Link-Character") or health.get("character") or ""
        self.company = health.get("company") or ""
        return self.path

    def wait_for_save(self, seconds: float = 45.0) -> str | None:
        """Ask the mod for fresh bytes and poll until they arrive, or time out.

        The one-shot build's way in: a refresh is requested, and poll() is
        tried every second until it hands over a path. An accepted refresh
        (202) is waited for: the bytes must carry a stamp newer than the one
        the mod named, or the build would show the state before the request.
        A refusal or a throttle is not an error here: this link has downloaded
        nothing yet, so poll() takes whatever the mod already serves. Only a
        mod with nothing to serve inside the deadline comes back None. A
        LinkUnavailable from the refresh surfaces.
        """
        self.stale = False
        status, body = self.refresh()
        superseded = body.get("stamp") if status == 202 else None
        deadline = time.monotonic() + seconds
        path = None
        while True:
            try:
                got = self.poll()
            except LinkUnavailable as exc:
                # The game went away mid-wait, or the port stopped answering as
                # the mod. Bytes already downloaded in this call are still a
                # board; only an empty-handed wait surfaces it. The reason is
                # the exception's own, whichever it was.
                if path is None:
                    raise
                self.stale = str(exc)
                return path
            if got is not None:
                path = got
                if superseded is None or self.stamp != superseded:
                    return path
            if time.monotonic() >= deadline:
                # The requested refresh never landed; the bytes that did are
                # still the game's state, only a little older. The caller says so.
                self.stale = "the mod did not finish the refresh in time" if path is not None else False
                return path
            time.sleep(1)

    def refresh(self) -> tuple[int, dict]:
        """Ask the mod to serialize the game now; /refresh's status and body."""
        status, _, body = self._call("/refresh", method="POST")
        try:
            parsed = json.loads(body or b"{}")
        except ValueError:
            parsed = {}
        # Some other local service on that port answers JSON that is no object.
        return status, parsed if isinstance(parsed, dict) else {}


class Board:
    """Holds the current dashboard, and rebuilds it when the save changes."""

    def __init__(self, target: str, out: str, link: GameLink | None = None, lang: str | None = None):
        self.target = target
        self.link = link
        self.out = out
        self.locale_source, locale = game_text()
        self.names = Names(locale)
        self.lang_names = cli_names(lang, self.locale_source, locale)
        self.lang_ui = cli_ui_table(lang)
        self.history = os.path.join(os.path.dirname(out) or ".", "market_history.json")
        self.lock = threading.Lock()
        self.html = b""
        self.data = b"{}"
        self.stamp = b'{"stamp":""}'
        self.source = None
        self.day = None
        self.error = None
        self._stamp = ""
        self._fingerprint = None
        self.character = None
        self.revision = 0  # bumps when the player names a line, so the page refetches
        self.build = threading.Lock()

    def name_line(self, rid: str, slug: str | None) -> None:
        """A recipe the player named by hand; rebuild so the needs follow."""
        with self.build:
            history = History(self.history)
            history.named(self.character or "default", {rid: slug})
            if not history.write():
                print(f"The line name was not kept: {os.path.basename(self.history)} could not be "
                      "read or written. Name the line again once the board has rebuilt.", flush=True)
            with self.lock:
                self.revision += 1
                self._fingerprint = None
            self._refresh(settle=False)

    def refresh(self, settle: bool = True) -> bool:
        """Rebuild if a newer save has appeared. True if anything changed."""
        with self.build:
            return self._refresh(settle)

    def _refresh(self, settle: bool) -> bool:
        if self.link is not None:
            # The link has no folder to scan: the mod says when its bytes have
            # moved, and its stamp is the whole fingerprint. A cleared
            # fingerprint (the player named a line) rebuilds from the bytes
            # this link downloaded, since the mod has nothing newer to say. A
            # fresh board has no fingerprint either, and no stamp: a
            # game-link.hsg left by an earlier session is never its source.
            # The rebuild after a name does not need the game: with the game
            # closed, the downloaded bytes still carry the name to the board.
            try:
                path = self.link.poll()
            except LinkUnavailable:
                if (self._fingerprint is not None or not self.link.stamp
                        or not os.path.exists(self.link.path)):
                    raise
                path = None
            if path is None:
                if (self._fingerprint is not None or not self.link.stamp
                        or not os.path.exists(self.link.path)):
                    return False
                path = self.link.path
            mark = self.link.stamp
            if mark == self._fingerprint:
                return False
        else:
            path = newest_under(self.target)
            mark = (path, os.path.getmtime(path), os.path.getsize(path))
            if mark == self._fingerprint:
                return False
            if settle:
                # The game may still be writing; only read once the file holds still.
                time.sleep(0.75)
                if (os.path.getmtime(path), os.path.getsize(path)) != mark[1:]:
                    return False

        try:
            data = safe_extract(load_save(path), self.names, self.history)
            # names= only for --lang: an English board renders as it always has.
            lang = {"names": self.lang_names} if self.lang_names else {}
            if self.lang_ui:
                lang["ui"] = self.lang_ui
            live_page = render(data, live=True, **lang).encode("utf-8")
            static_page = render(data, **lang).encode("utf-8")
        except Exception as exc:
            # Fingerprint it anyway. Without this a save that will not build is
            # re-read every interval -- a 26 MB parse every few seconds, which
            # is precisely the CPU the game is supposed to get. The next save
            # the game writes clears the mark and we try again.
            with self.lock:
                self._fingerprint = mark
                self.error = f"{os.path.basename(path)}: {exc}"
                self._publish_stamp()
            raise

        with self.lock:
            self._fingerprint = mark
            self.source = path
            self.error = None
            self.html = live_page
            self.data = json.dumps(data, separators=(",", ":")).encode("utf-8")
            self.character = data["supply"].get("factories", {}).get("character")
            self.day = data["meta"]["day"]
            if self.link is not None:
                self._stamp = f"game-link@{mark}#{self.revision}"
            else:
                self._stamp = f"{os.path.basename(path)}@{mark[1]:.0f}#{self.revision}"
            self._publish_stamp()

        with open(self.out, "wb") as fh:
            fh.write(static_page)
        return True

    def _publish_stamp(self) -> None:
        """What the open page polls: the build it has, and why it is stuck.

        Called with the lock already held.
        """
        body = {"stamp": self._stamp}
        if self.error:
            body["error"] = self.error
        self.stamp = json.dumps(body).encode("utf-8")


class BoardHandler(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    board: Board = None
    NAME_MAX_BYTES = 16 * 1024  # a {rid, slug} is a few dozen bytes

    def _this_host(self) -> bool:
        """A request addressed to this server by a loopback name, and else
        answered 403. The server listens on 127.0.0.1 only, but a web page on
        a name that resolves here (DNS rebinding) would send its own Host."""
        port = self.server.server_address[1]
        host = (self.headers.get("Host") or "").strip().lower()
        if host in (f"127.0.0.1:{port}", f"localhost:{port}"):
            return True
        self.send_error(403)
        return False

    def do_GET(self):
        if not self._this_host():
            return
        route = self.path.split("?")[0].rstrip("/") or "/"
        # Explicit allowlist: the watch server exposes no arbitrary workspace
        # files. The wiki's catalogue is the public one beside the page, never
        # the extractor's own working copies.
        map_assets = {
            "/maps/locations.json": "application/json",
            "/maps/map-background.svg": "image/svg+xml",
            "/maps/floor-plans.json": "application/json",
            "/wiki-data.json": "application/json",
        }
        if route in map_assets:
            path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "web", route.lstrip("/"))
            try:
                with open(path, "rb") as fh:
                    body = fh.read()
            except OSError:
                self.send_error(404)
                return
            self.send_response(200)
            self.send_header("Content-Type", map_assets[route])
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Cache-Control", "no-cache")
            self.end_headers()
            self.wfile.write(body)
            return
        with self.board.lock:
            body, ctype = {
                "/": (self.board.html, "text/html; charset=utf-8"),
                "/index.html": (self.board.html, "text/html; charset=utf-8"),
                "/data.json": (self.board.data, "application/json"),
                "/stamp": (self.board.stamp, "application/json"),
            }.get(route, (None, None))
        if body is None:
            self.send_error(404)
            return
        self.send_response(200)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        """The page naming a factory line by hand: {rid, slug}, slug null to clear."""
        if not self._this_host():
            return
        route = self.path.split("?")[0].rstrip("/")
        if route != "/name":
            self.send_error(404)
            return
        # JSON only: a page elsewhere can send a form or text/plain POST
        # without asking, but not this one, which needs a CORS preflight this
        # server never answers. The body is never read past its cap.
        if self.headers.get_content_type() != "application/json":
            self.send_error(415)
            return
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            self.send_error(400)
            return
        if length < 0:
            self.send_error(400)
            return
        if length > self.NAME_MAX_BYTES:
            self.send_error(413)
            return
        try:
            body = json.loads(self.rfile.read(length) or b"{}")
            rid, slug = str(body["rid"]), body.get("slug") or None
        except (ValueError, KeyError, TypeError):
            self.send_error(400)
            return
        try:
            self.board.name_line(rid, slug)
        except Exception as exc:  # the board keeps serving the last build
            print(f"  naming a line failed -- {exc}", flush=True)
        self.send_response(204)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def log_message(self, *args):
        pass  # the watcher prints what matters


def watch(
    target: str,
    out: str,
    port: int,
    interval: int,
    open_browser: bool,
    link: GameLink | None = None,
    lang: str | None = None,
) -> None:
    lowered = yield_to_the_game()
    board = Board(target, out, link=link, lang=lang)
    try:
        board.refresh(settle=False)
    except LinkUnavailable as exc:
        # The game is not up yet, or the mod is off. The poll loop below
        # keeps trying; the server has nothing to be sorry for.
        print(f"  {exc}", flush=True)
    except Exception as exc:
        # A save that will not build is no reason to stop watching: the poll
        # loop below tries again when the game writes the next one.
        print(f"  skipped the first build -- {board.error or exc}", flush=True)
        traceback.print_exc()
    if not board.html:
        # Until a board builds, the page is the live shell with no numbers: it
        # polls the stamp and draws the first board that does.
        board.html = render(None, live=True).encode("utf-8")
    BoardHandler.board = board
    server = http.server.ThreadingHTTPServer(("127.0.0.1", port), BoardHandler)
    url = f"http://127.0.0.1:{port}/"

    def poll():
        last_failure = None
        link_down = ""  # what was last said about the link being out, while it is
        while True:
            try:
                moved = board.refresh()
            except LinkUnavailable as exc:
                # Once per outage, not once per interval: the game is closed
                # or between cities, or the mod speaks another schema version,
                # and the board on screen is still good. Polling goes on, so a
                # game that comes back, or a mod put right, is read again.
                if str(exc) != link_down:
                    link_down = str(exc)
                    print(f"  {time.strftime('%H:%M:%S')}  {exc}", flush=True)
            except Exception as exc:
                signature = f"{type(exc).__name__}: {exc}"
                print(
                    f"  {time.strftime('%H:%M:%S')}  skipped a rebuild -- "
                    f"{board.error or signature}",
                    flush=True,
                )
                # The traceback the first time each failure appears. A page of
                # bare "skipped a rebuild: 'NetWorth'" says nothing about where
                # it came from, and that is the only record there is.
                if signature != last_failure:
                    last_failure = signature
                    traceback.print_exc()
                    print(
                        "  serving the last board that built; retrying when "
                        "the game writes a new save",
                        flush=True,
                    )
            else:
                if link_down:
                    link_down = ""
                    print(f"  {time.strftime('%H:%M:%S')}  the game link is back", flush=True)
                if moved:
                    what = (
                        f"the game (day {board.day})"
                        if board.link is not None
                        else os.path.basename(board.source)
                    )
                    print(
                        f"  {time.strftime('%H:%M:%S')}  rebuilt from {what}",
                        flush=True,
                    )
                    last_failure = None
            time.sleep(interval)

    threading.Thread(target=poll, daemon=True).start()

    if board.link is not None:
        print(f"Linked to the game at {board.link.url}", flush=True)
    else:
        print(f"Watching {target}", flush=True)
    print(f"  serving {url}  (checks every {interval}s, rebuilds only on a new save)")
    print(f"  priority {'lowered, the game gets the CPU first' if lowered else 'unchanged'}")
    print(f"  {locale_note(board.locale_source, board.names.locale)}")
    print("  Ctrl+C to stop", flush=True)
    if open_browser:
        webbrowser.open(url)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nStopped.")
        server.shutdown()


def game_text() -> tuple[str | None, dict[str, str]]:
    """load_best_locale() for a local run, which stops on a non-English file.

    BA_LOCALE pointed at de.json would give translated names and no recipes,
    capacities or door caps; the run says so instead of drawing that board.
    """
    try:
        return load_best_locale()
    except NotEnglishText as exc:
        raise SystemExit(str(exc)) from None


def locale_note(source: str | None, locale: dict[str, str]) -> str:
    """One line naming the game text a local run used, for the CLI summary.

    The bundled English keeps labels reading properly even with no game
    installed, which is the point of detecting it -- but it is a filtered copy
    of whatever build shipped it, so a run that fell back has to say so rather
    than look identical to one reading the player's own install.

    Reports the table that loaded, not a path that merely exists: a truncated
    en.json is the likeliest way this goes wrong, and naming the file while
    every label falls back to a slug would hide exactly what it is here to show.
    """
    if not locale:
        return "game text: none found, so names fall back to raw slugs"
    if bundled_locale(source):
        return (
            "game text: the English bundled with the board, not your install; "
            "set BA_LOCALE to your game's en.json for the names your build uses"
        )
    return f"game text: {source}"


def cli_names(lang: str | None, source: str | None, english: dict[str, str]) -> dict | None:
    """--lang: the game names of one language, from the installed game, for
    render(names=...). None for English or no --lang."""
    if not lang or lang == "en":
        return None
    if lang not in GAME_NAME_LANGS:
        raise SystemExit(f"--lang {lang}: the game has no such language; one of "
                         + ", ".join(code for code in GAME_NAME_LANGS))
    if not source or bundled_locale(source):
        raise SystemExit(f"--lang {lang} reads the game's own {lang}.json beside its en.json, "
                         "and no installed game was found; set BA_LOCALE to the game's en.json")
    other = load_locale(os.path.join(os.path.dirname(source), f"{lang}.json"))
    if name_coverage(english, other) < NAME_COVERAGE:
        raise SystemExit(f"--lang {lang}: {os.path.join(os.path.dirname(source), lang + '.json')} "
                         "names too few of the game's items to use")
    return {"lang": lang, "names": name_table(english, other)}


def cli_ui_table(lang: str | None) -> dict | None:
    """--lang: Big Copilot's own text in that language, for render(ui=...),
    from the table the site ships (web/i18n/<lang>.json, which
    `python build_web.py` writes). None for English, or for a language with
    no table or an empty one: the page's own words then stay English."""
    if not lang or lang == "en":
        return None
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "web", "i18n", f"{lang}.json")
    try:
        with open(path, encoding="utf-8") as fh:
            table = json.load(fh)
    except (OSError, ValueError):
        return None
    return {"lang": lang, "table": table} if isinstance(table, dict) and table else None


def main() -> None:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    ap.add_argument(
        "save",
        nargs="?",
        help="a .hsg file, a save folder, or the name of a save or character",
    )
    ap.add_argument(
        "--list",
        action="store_true",
        help="list every save under the save folder, by character, and stop",
    )
    ap.add_argument(
        "-o", "--out", default="dashboard.html", help="where to write the page"
    )
    ap.add_argument(
        "--watch",
        action="store_true",
        help="serve the board locally and rebuild it whenever the game saves",
    )
    ap.add_argument(
        "--port", type=int, default=8770, help="port for the local server in watch mode"
    )
    ap.add_argument(
        "--interval",
        type=int,
        default=None,
        help="seconds between checks: 5 for a save folder, 30 for the game link",
    )
    ap.add_argument(
        "--no-open", action="store_true", help="with --watch, do not open a browser"
    )
    ap.add_argument(
        "--game",
        nargs="?",
        const="http://127.0.0.1:8322",
        default=None,
        metavar="URL",
        help="read the running game through the Big Copilot Link mod instead of a "
        "save folder; URL defaults to http://127.0.0.1:8322. The bytes are kept "
        "as game-link.hsg beside the output file",
    )
    ap.add_argument(
        "--lang",
        default=None,
        metavar="CODE",
        help="show the game's own names (items, business types, neighbourhoods, "
        "skills) in one of the game's languages, e.g. de, fr, ja, zh-cn; the rest "
        "of the page stays English, unless Big Copilot's own text has a "
        "translation into that language (web/i18n/<code>.json)",
    )
    ap.add_argument(
        "--backfill",
        action="store_true",
        help="seed demand history from every save on disk, then build",
    )
    args = ap.parse_args()

    if args.game and (args.list or args.save):
        raise SystemExit(
            "--game reads the running game; it does not combine with --list or a "
            "save or character name"
        )
    interval = args.interval if args.interval is not None else (30 if args.game else 5)

    if args.list:
        if not args.save:
            root = default_root()
        elif os.path.exists(args.save):
            root = args.save  # catalogue() takes the folder of a save file
        else:
            raise SystemExit(
                f"{args.save} does not exist. --list takes the save folder or a save file."
            )
        print_catalogue(catalogue(root))
        return

    out = os.path.abspath(args.out)
    history = os.path.join(os.path.dirname(out) or ".", "market_history.json")

    # The link needs no folder: the mod names the character and the day, so
    # the positional argument and the save-folder search are beside the point.
    link = GameLink(args.game, os.path.dirname(out) or ".") if args.game else None
    target = None if link is not None else resolve_target(args.save)
    if link is not None and args.backfill:
        raise SystemExit(
            "--backfill seeds history from the saves of a folder; it does not "
            "combine with --game"
        )

    # --watch has its own Board, which resolves the text itself, so a plain
    # watch run does not parse en.json here only to leave it behind.
    if args.backfill or not args.watch:
        locale_source, locale = game_text()
        names = Names(locale)

    if args.backfill:
        recorded = backfill_history(target, history, names)
        print(f"  merged {recorded} snapshots into {os.path.basename(history)}")

    if args.watch:
        watch(target, out, port=args.port, interval=interval, open_browser=not args.no_open, link=link,
              lang=args.lang)
        return

    if link is not None:
        try:
            path = link.wait_for_save()
        except LinkUnavailable as exc:
            raise SystemExit(str(exc)) from None
        if path is None:
            raise SystemExit(
                "the game link has no save to read yet; load a save in the game "
                "and try again"
            )
        source_name = "the game link"
    else:
        path = newest_under(target)
        source_name = os.path.basename(path)
    lang_names = cli_names(args.lang, locale_source, locale)
    data = safe_extract(load_save(path), names, history)
    with open(out, "w", encoding="utf-8") as fh:
        fh.write(render(data, names=lang_names, ui=cli_ui_table(args.lang)))

    k = data["kpi"]
    minor = data["minor"]
    print(
        f"{data['meta']['save']} - day {data['meta']['day']}  "
        f"(from {source_name}, game build {data['meta']['build']}, "
        f"board checked on {VERIFIED_BUILD})"
    )
    if link is not None and link.stale:
        # Two lines: the reason is a sentence of its own, sometimes a question.
        print(f"  {link.stale}", flush=True)
        print("  the board shows the state the mod last served", flush=True)
    worth = f"{k['netWorth']:>14,.0f}" if k["netWorth"] is not None else "   not reported"
    print(f"  cash {k['cash']:>14,.0f}   net worth {worth}")
    print(f"  profit yesterday {k['profitYesterday']:>+11,.0f}   7-day avg {k['profitAvg7']:>+11,.0f}")
    print(
        f"  {k['businesses']} businesses, {k['employees']} staff, "
        f"{len(data['alerts'])} alerts "
        f"({minor['count']} more below the ${minor['gate']:,.0f}/day line)"
    )
    print(f"  wrote {out}")
    print(f"  {locale_note(locale_source, locale)}")


if __name__ == "__main__":
    main()
